import { Select, Spin } from 'antd';
import React, { useCallback, useMemo, useState, useRef, useEffect } from 'react';
import { LoadingOutlined } from '@ant-design/icons';

import { debounce } from 'lodash';
import { listAllDevicesByPage } from '@/hooks/socket/cameras';
import { ROOT_GROUP_ID } from '@/constants/group';

const mergeData = (prev, current) => {
  return {
    ...prev,
    ...current,
    devices: [...(prev.devices || []), ...(current.devices || [])],
  };
};

const defaultGetOptions = (options) => options;

export const CameraSelector = ({
  onChange,
  value,
  namespace,
  dropdownClassName,
  placeholder,
  style,
  getOptions,
  setCameraSelected,
  allCameras,
  onSelectedGroupIdChange,
  setSelectedCameras
}) => {
  const [pages, setPages] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isDebounce, setIsDebounce] = useState(false);
  const timeRequestRef = useRef(Date.now());
  const searchRef = useRef('');
  const data = useMemo(() => {
    return pages.reduce(mergeData, {});
  }, [pages]);

  const fetchCameras = useCallback(
    async ({ page, name }) => {
      setIsLoading(true);
      const response = await listAllDevicesByPage({
        page,
        size: 10,
        namespace,
        deviceType: 'camera',
        timeRequest: timeRequestRef.current,
        name,
      });
      setPages((prev) => [...prev, response]);
      setIsLoading(false);

      return response;
    },
    [namespace]
  );

  const handleSearch = useMemo(
    () =>
      debounce(
        (value) => {
          timeRequestRef.current = Date.now();
          setIsDebounce(false);
          searchRef.current = value;

          fetchCameras({
            page: 0,
            size: 10,
            name: value || undefined,
            namespace,
            deviceType: 'camera',
            timeRequest: timeRequestRef.current,
          }).then((res) => {
            setPages([res]);
          });
        },
        500,
        { leading: false, trailing: true }
      ),
    [fetchCameras, namespace]
  );

  const fetchNextPage = useCallback(() => {
    fetchCameras({
      page: pages.length,
      name: searchRef.current,
    });
  }, [pages.length, fetchCameras]);

  const handleScroll = useMemo(
    () => debounce(fetchNextPage, 200, { leading: true, trailing: true }),
    [fetchNextPage]
  );

  const onScroll = (e) => {
    if (isLoading) return;

    if (data.devices.length >= data.total) {
      console.log('end');
      return;
    }

    const isBottom =
      e.target.scrollTop + e.target.clientHeight + 10 >= e.target.scrollHeight;

    if (isBottom) {
      handleScroll(e);
    }
  };

  const onSearch = (value) => {
    setIsDebounce(true);
    handleSearch(value);
  };

  const onSelect = (newValue) => {
    console.log('newValue: ', newValue);
    setCameraSelected(newValue);
    const filtered = value.filter((cam) => cam?.serial !== newValue);
    const newResult = [
      ...filtered,
      data?.devices?.find((device) => device?.serial === newValue),
    ].filter(Boolean);

    onChange(newResult);
  };

  const onDeselect = (newValue) => {
    const filtered = value.filter((cam) => cam?.serial !== newValue);
    onChange(filtered);
  };

  const [key, setKey] = useState(0);
  const defaultOptions = useMemo(() => {
    return (
      data?.devices?.map((device) => ({
        label: device?.name,
        value: device?.serial,
        ...device,
      })) || []
    );
  }, [data]);

  const handleSelectChange = useCallback((selectedSerials) => {
    console.log('handleSelectChange - selectedSerials: ', selectedSerials);
    if (!selectedSerials || selectedSerials.length === 0) {
      console.log('handleSelectChange - allCameras: ', allCameras);
      onChange([allCameras?.devices?.[0]?.serial] || []);
      setCameraSelected([allCameras?.devices?.[0]] || [])
      onSelectedGroupIdChange(ROOT_GROUP_ID)
      return;
    }

    const newResult = selectedSerials?.filter(Boolean)
      .map((serial) => {
        const existingCam = value?.filter(Boolean)?.find((cam) => cam?.serial === serial);
        if (existingCam) return existingCam;

        return data?.devices?.find((device) => device?.serial === serial);
      })
      .filter(Boolean);

    console.log('handleSelectChange - newResult: ', newResult);
    onChange(newResult);
  }, [value, data, allCameras]);

  const finalOptions = useMemo(() => {
    const tmp = [...defaultOptions];

    if (value && Array.isArray(value)) {
      value.filter(Boolean).forEach((cam) => {
        if (!tmp.find((opt) => opt?.value === cam?.serial)) {
          tmp.push({
            label: cam?.name,
            value: cam?.serial,
            ...cam,
          });
        }
      });
    }

    return getOptions ? getOptions(tmp) : tmp;
  }, [defaultOptions, getOptions, value]);


  return (
    <Select
      key={key}
      mode="multiple"
      loading={isLoading || isDebounce}
      onSearch={onSearch}
      onPopupScroll={onScroll}
      value={(value || [])?.filter(Boolean)?.map((item) => item?.serial)}
      options={finalOptions}
      onSelect={onSelect}
      onDeselect={onDeselect}
      onChange={handleSelectChange}
      showSearch
      showArrow
      style={style}
      placeholder={placeholder}
      filterOption={false}
      getPopupContainer={(trigger) => trigger.parentElement}
      allowClear
      dropdownRender={(menu) => {
        return (
          <Spin
            indicator={<LoadingOutlined style={{ fontSize: 24 }} spin />}
            spinning={isLoading}
          >
            {menu}
          </Spin>
        );
      }}
      onFocus={() => {
        // retain data if no search was done last time
        if (searchRef.current || pages.length === 0) {
          timeRequestRef.current = Date.now();

          fetchCameras({
            page: 0,
            name: '',
          }).then((res) => {
            setPages([res]);
          });
        }
      }}
      onBlur={() => {
        setKey((prev) => (prev + 1) % 5);
      }}
      height={300}
      listItemHeight={32}
      dropdownClassName={dropdownClassName}
    />
  );
};
