/* eslint-disable react-hooks/exhaustive-deps */
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Button, Card, Col, Divider, Row, Select } from "antd";
import { useTranslation } from "react-i18next";
import { useDispatch, useSelector } from "react-redux";
import * as SERVICE from "@/constants/service.types";
import {
    socketEmitEvent,
    updateNotificationReturn,
} from "@/redux/actions";
import { ArrowLeftOutlined, CheckCircleOutlined, QuestionCircleFilled } from "@ant-design/icons";
import { setJustUpdatedNotifications, setSelectedNotification } from "@/redux/notification/action";
import "./index.scss";
import { NotificationLevelTag, NotificationStatusTag } from "../NotificationTag";
import {
    AI_WARNING_EVENT_TYPE,
    DEVICE_EVENT_TYPE,
    NOTIFICATION_TASK_STATUS,
    NOTIFICATION_TYPE,
} from "@/constants/notification.keys";
import CameraOnIcon from "@/assets/icons/camera_on.svg";
import CameraIcon from "@/assets/icons/camera.svg";
import Info5Icon from "@/assets/icons/info_5.svg";
import DurationIcon from "@/assets/icons/duration.svg";
import moment from "moment";
import Expand from "react-expand-animated";
import ChangePasswordFormComponent from "@/pages/Profile/ChangePasswordComponent";
import UpdateSystemFillIcon from '@/assets/icons/update_system_fill.svg'
import SituationPlayer from "@/pages/PlaybackV2/Main/Player/SituationPlayer";

const { Option } = Select

const NotificationDetail = ({ notification }) => {
    const { t } = useTranslation();
    const dispatch = useDispatch();
    const { namespace, updateNotifications, listAlert } = useSelector((state) => state);

    const [requestId, setRequestId] = useState(Date.now());
    const [notificationData, setNotificationData] = useState(notification);
    const [newTaskStatus, setNewTaskStatus] = useState(null);
    const [isImageModalOpen, setIsImageModalOpen] = useState(false);

    const handleImageClick = () => setIsImageModalOpen(true);
    const handleCloseModal = () => setIsImageModalOpen(false);

    useEffect(() => {
        if (notification) {
            console.log('notification: ', notification);
            setNotificationData(notification)
        }
    }, [notification]);

    useEffect(() => {
        if (notificationData) {
            console.log('notificationData?.content: ', notificationData?.content);
        }
    }, [notificationData]);

    const extraInfo = useMemo(() => JSON.parse(notificationData?.extraInfo || "{}"), [notificationData]);

    useEffect(() => {
        console.log('updateNotifications: ', updateNotifications);
        console.log('newTaskStatus: ', newTaskStatus);
        console.log('notificationData: ', notificationData);
        if (updateNotifications && updateNotifications?.id === notificationData?.id && updateNotifications?.taskStatus === newTaskStatus) {
            console.log("Here");
            setNotificationData(prev => ({
                ...prev,
                taskStatus: updateNotifications.taskStatus,
                updatedAt: updateNotifications.updatedAt,
            }));
            dispatch(setJustUpdatedNotifications(updateNotifications))
            dispatch(updateNotificationReturn(null));
        }
    }, [updateNotifications, notificationData, newTaskStatus, dispatch]);

    const handleUpdateTaskStatus = useCallback(() => {
        if (notificationData?.taskStatus === NOTIFICATION_TASK_STATUS.TASK_DONE) return;

        const requestId = Date.now();
        const dataBody = {
            timeRequested: requestId,
            notificationId: notificationData.id,
            taskStatus: notificationData?.taskStatus === NOTIFICATION_TASK_STATUS.TASK_RECEIVED
                ? NOTIFICATION_TASK_STATUS.TASK_IN_PROCESS
                : NOTIFICATION_TASK_STATUS.TASK_DONE,
            namespace,
        }

        const dataObj = {
            appServiceType: SERVICE.UPDATE_NOTIFICATION,
            requestId: requestId,
            body: JSON.stringify(dataBody),
        };
        setNewTaskStatus(dataBody.taskStatus);
        setRequestId(requestId);
        dispatch(socketEmitEvent(dataObj));
    }, [notificationData, namespace, dispatch]);

    const renderContent = useCallback(() => {
        if (!AI_WARNING_EVENT_TYPE.includes(notificationData?.type)) return null;

        return (
            <>
                {
                    extraInfo?.actionTime && extraInfo?.serial && (
                        <div className="mt-4">
                            <div className="flex gap-1 items-center justify-start">
                                <img src={CameraIcon} className="w-5 h-auto" alt="camera" />
                                <h3 className="text-gray-900 m-0 text-lg">Situation Video</h3>
                            </div>
                            <SituationPlayer
                                serial={extraInfo?.serial}
                                queryTime={extraInfo?.actionTime}
                                thumbnail={extraInfo?.imageUrl}
                            />
                        </div>
                    )
                }
            </>
        );
    }, [extraInfo, notificationData]);

    const renderFooterDetail = useCallback(() => {
        switch (notificationData?.taskStatus) {
            case NOTIFICATION_TASK_STATUS.TASK_RECEIVED:
                // console.log('notificationData?.taskStatus: ', notificationData?.taskStatus);
                return (
                    <Button
                        type="primary"
                        className="w-full btn-start-processing"
                        onClick={handleUpdateTaskStatus}
                    >
                        {t('Start processing')}
                    </Button>
                );

            case NOTIFICATION_TASK_STATUS.TASK_IN_PROCESS:
                return (
                    <Button
                        type="primary"
                        className="w-full btn-mark-completed"
                        onClick={handleUpdateTaskStatus}
                    >
                        {t('Mark as completed')}
                    </Button>
                );

            case NOTIFICATION_TASK_STATUS.TASK_DONE:
                return (
                    <div className="text-center text-green-600 notify-completed-status ">
                        <CheckCircleOutlined className="w-6 h-6 mx-auto mb-1" />
                        <p className="text-base m-0">Completed</p>
                    </div>
                );

            default:
                return (
                    <div className="text-center text-green-600 notify-completed-status ">
                        <CheckCircleOutlined className="w-6 h-6 mx-auto mb-1" />
                        <p className="text-base m-0">Completed</p>
                    </div>
                );
        }
    }, [handleUpdateTaskStatus, notificationData, t]);

    const renderDetailInformation = useCallback(() => {
        const items = [];

        if (AI_WARNING_EVENT_TYPE.includes(notificationData?.type)) {
            items.push(
                <NotificationDetailItem
                    key="camera"
                    label="Camera"
                    detail={
                        notificationData?.content.split(" - ")?.[1]?.trim() || "Unknown"
                    }
                    icon={CameraOnIcon}
                />
            );
        }

        if (DEVICE_EVENT_TYPE.includes(notificationData?.type) && extraInfo?.title) {
            items.push(
                <NotificationDetailItem
                    key="reason"
                    label="Reason"
                    detail={
                        extraInfo?.title
                    }
                    IconComponent={<QuestionCircleFilled width={20} height={20} />}
                />
            )
        }

        if (notificationData?.type === NOTIFICATION_TYPE.REQUIRE_CHANGE_PASSWORD) {
            items.push(
                <NotificationDetailItem
                    key="time"
                    label="Processing term"
                    detail={moment(notificationData?.fromTime || notificationData?.createdAt).format(
                        "HH:mm:ss DD-MM-YYYY"
                    )}
                    icon={UpdateSystemFillIcon}
                />
            );
        }

        if (extraInfo && extraInfo?.member) {
            items.push(
                <NotificationDetailItem
                    key={extraInfo?.member}
                    label="Person in charge"
                    detail={extraInfo?.member || "Unknown"}
                    icon={Info5Icon}
                />
            );
        }

        return items;
    }, [extraInfo, notificationData]);

    const handleChange = useCallback((item, value) => {
        let dataInfo = (item?.extraInfo && JSON.parse(item.extraInfo)) || {}
        const alertData = listAlert?.find(item => item?.errorId === value)
        dataInfo.errorId = value
        dataInfo.errorCode = alertData?.errorCode
        dataInfo.title = alertData?.title
        console.log('dataInfo: ', dataInfo);
        item.status = 3
        let data = {
            notificationId: item.id,
            status: 3,
            namespace,
            extraInfo: JSON.stringify({ ...dataInfo })
        };
        let dataObj = {
            appServiceType: SERVICE.UPDATE_NOTIFICATION,
            requestId: new Date().getTime(),
            body: JSON.stringify(data),
        };
        dispatch(socketEmitEvent(dataObj));
    }, [dispatch])

    const renderExpandContent = useCallback(() => {
        let ele;
        const isOpen = notificationData?.taskStatus === NOTIFICATION_TASK_STATUS.TASK_IN_PROCESS
        if (notificationData?.type === NOTIFICATION_TYPE.REQUIRE_CHANGE_PASSWORD) {
            ele = (
                <>
                    <h3 className="text-lg">{t("Change password")}</h3>
                    <ChangePasswordFormComponent open={isOpen} />
                </>
            )
        } else if (DEVICE_EVENT_TYPE.includes(notificationData?.type)) {
            ele = <>
                <Row style={{ padding: '8px 8px 0px 8px' }}>
                    <Col span={24}>
                        <Select
                            size="small"
                            placeholder={t("Select reason")}
                            style={{ width: '100%' }}
                            defaultValue={(notificationData?.extraInfo && JSON.parse(notificationData.extraInfo)?.errorCode) || undefined}
                            onChange={(value) => handleChange(notificationData, value)}
                        >
                            {listAlert?.map(item => (
                                <Option value={item.errorId}>{item.title}</Option>
                            ))}
                        </Select>
                    </Col>
                </Row>
            </>
        }


        return (
            <Expand open={isOpen} className="w-full">
                {ele}
            </Expand>
        );
    }, [notificationData, listAlert, t]);

    return (
        <div className="notification-detail-wrapper flex flex-col h-full">
            <div>
                <Button
                    type="text"
                    icon={<ArrowLeftOutlined />}
                    onClick={() => dispatch(setSelectedNotification(null))}
                    className="btn-back"
                >
                    Back
                </Button>
                <Row className="flex flex-nowrap gap-1">
                    <Col span={1} className="flex justify-center">
                        {notificationData?.prefixIcon}
                    </Col>
                    <Col span={23}>
                        <h2 className="text-foreground font-semibold m-0">
                            {notificationData?.content}
                        </h2>
                        <div className="flex gap-1/2 flex-wrap">
                            <NotificationLevelTag level={notificationData?.level} />
                            <NotificationStatusTag taskStatus={notificationData?.taskStatus} />
                        </div>
                    </Col>
                </Row>
            </div>

            <div className="mt-4 flex flex-col flex-1">
                <Divider className="m-0 bg-gray-300" />
                <div className="notification-detail-content flex flex-col flex-1 justify-between">
                    <div>
                        <div className="mt-4 w-full">{renderContent()}</div>
                        <div className="space-y-3 bg-white p-4 rounded-lg mt-4">
                            <h3 className="text-gray-900 text-lg">Detail information</h3>
                            <div className="flex justify-between">
                                <div className="flex flex-col gap-1">
                                    <NotificationDetailItem
                                        label='Event time'
                                        detail={moment(extraInfo?.actionTime).format('HH:mm:ss DD-MM-YYYY')}
                                        icon={DurationIcon}
                                    />
                                    {renderDetailInformation()}
                                </div>
                                {extraInfo?.imageUrl && (
                                    <div className="w-full flex-1 gap-1" style={{ maxWidth: '60%' }}>
                                        <div className="flex gap-1 items-center mb-1">
                                            <img src={CameraIcon} className="w-5 h-auto" alt="camera" />
                                            <span className="text-gray-600 text-base">{t("Event image")}</span>
                                        </div>
                                        <div className="rounded-lg overflow-hidden">
                                            <img
                                                src={extraInfo.imageUrl}
                                                alt="event_img"
                                                className="w-full h-auto object-cover cursor-pointer"
                                                onClick={handleImageClick}
                                            />
                                        </div>
                                    </div>
                                )}

                                {isImageModalOpen && (
                                    <div
                                        className="fixed inset-0 bg-transparent flex items-center justify-center z-50 w-screen h-screen"
                                        onClick={handleCloseModal}
                                    >
                                        <div
                                            className="shadow-lg rounded-lg border-dashed border-2"
                                            style={{ width: 'fit-content', height: 'fit-content' }}
                                        >
                                            <img
                                                src={extraInfo.imageUrl}
                                                alt="modal_img"
                                                className="rounded-lg"
                                                style={{ width: '80vw', height: 'auto', maxWidth: '1200px', maxHeight: '80vh', objectFit: 'initial' }}
                                                onClick={(e) => e.stopPropagation()}
                                            />
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                        <div className="mt-4 flex justify-center">
                            {renderExpandContent()}
                        </div>
                    </div>

                    <div className="mb-4">
                        <Divider className="my-4 bg-gray-300" />
                        {renderFooterDetail()}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default NotificationDetail;

const NotificationDetailItem = ({ label, detail, icon, IconComponent }) => {
    return (
        <div className="flex gap-1 items-start notification-detail-item" style={{ height: 'fit-content' }}>
            <div className="flex items-center text-base">
                {icon && <img src={icon} className="w-5 h-auto" alt="" />}
                {IconComponent && !icon && (IconComponent)}
            </div>

            <div className="flex-1 flex flex-col items-start justify-start">
                <div className="text-gray-500 text-base">{label}</div>
                <div className="text-gray-900 flex-1 text-base">
                    {detail}
                </div>
            </div>
        </div>
    )
}