import { Button, Input, Modal, Table, Tooltip } from "antd";
import React, { useCallback, useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import moment from "moment";
import { useSelector } from "react-redux";
import ExpandRoleComponent from "./ExpandRole";
import { EditIcon } from '@/icons/Edit';
import { TrashCanIcon } from '@/icons/TrashCan';
import { deleteCustomerRole, getListFunctionOfRole, updateCustomerRole } from "@/hooks/socket/role";
import { openMessage } from "@/redux/actions";
import { NOTIFIES } from "@/constants/system.keys";
import { CloseOutlined, ExclamationCircleOutlined, SaveOutlined } from '@ant-design/icons';

const RoleCustomerTable = ({ data = [], loading, onRefresh = () => { } }) => {
  const { t } = useTranslation()
  const { namespace } = useSelector(state => state)
  const [expKeys, setExpKeys] = useState([]);
  const [roleToEdit, setRoleToEdit] = useState(null)
  const [newRoleName, setNewRoleName] = useState(null)

  const onRemove = useCallback((record) => {
    console.log("🚀 ~ onRemoveMember ~ record:", record)
    Modal.confirm({
      title: `${t('Remove role')}: ${record?.detailRole
        }?`,
      icon: <ExclamationCircleOutlined />,
      okText: t('Remove'),
      onOk() {
        return deleteCustomerRole({
          roleId: record?.roleId,
          namespace
        }).then(
          (res) => {
            console.log("🚀 ~ onRemove ~ res:", res)
            openMessage(NOTIFIES.SUCCESS, t('Role removed successfully'));
            onRefresh();
          },
          (err) => {
            console.log("🚀 ~ onRemove ~ err:", err)
            openMessage(NOTIFIES.ERROR, t('Remove role failed'));
          }
        );
      },
      onCancel() { },
    });
  }, [namespace, onRefresh, t]);

  const onUpdate = useCallback(async () => {
    if (newRoleName && newRoleName === roleToEdit?.detailRole) return
    updateCustomerRole({
      roleId: roleToEdit?.roleId,
      role: newRoleName !== null ? newRoleName : roleToEdit?.detailRole,
      isGlobal: 0,
      namespace
    })
      .then(res => {
        setRoleToEdit(null)
        if (!res || !res?.role || !res?.role?.roleId) {
          openMessage(NOTIFIES.ERROR, t('Update role failed'));
          return
        }
        onRefresh()
        openMessage(NOTIFIES.SUCCESS, t('Role updated successfully'));
      })
      .catch(err => {
        openMessage(NOTIFIES.ERROR, t('Update role failed'));
      })
  }, [roleToEdit, namespace, onRefresh, newRoleName])

  useEffect(() => {
    return () => {
      setRoleToEdit(null)
    }
  }, [])

  return (
    <Table
      className="role-customer-table"
      loading={loading}
      columns={[
        {
          title: t('Name'),
          dataIndex: 'detailRole',
          key: 'detailRole',
          render: (value, row) => {
            if (!roleToEdit || roleToEdit?.roleId !== row?.roleId) return value
            return <Input
              placeholder={t('Enter role name')}
              onChange={(e) => setNewRoleName(e.target.value)}
              value={newRoleName !== null ? newRoleName : roleToEdit?.detailRole || ''}
            />
          }
        },
        {
          title: t('Scope'),
          dataIndex: 'scopeAccount',
          key: 'scopeAccount',
        },
        {
          title: t('Permission'),
          dataIndex: 'permissionGroup',
          key: 'permissionGroup',
          width: 200,
        },
        {
          title: t('Created at'),
          dataIndex: 'createdAt',
          key: 'createdAt',
          width: 200,
        },
        {
          title: t('Action'),
          key: 'action-role',
          width: 120,
          render: (value, row) => (
            <div className="role-actions">
              {
                roleToEdit && roleToEdit?.roleId === row?.roleId ? (
                  <>
                    <Button
                      type="primary"
                      icon={<SaveOutlined />}
                      onClick={onUpdate}>
                      Save
                    </Button>
                    <Button
                      type="default"
                      icon={<CloseOutlined />}
                      onClick={() => {
                        setRoleToEdit(null)
                        setNewRoleName(null)
                      }}
                    >
                      Cancel
                    </Button>
                  </>
                ) : (
                  <>
                    <Tooltip title={'Edit'}>
                      <div
                        className="edit-btn action-btn"
                        onClick={() => {
                          setRoleToEdit(row)
                          setNewRoleName(null)
                        }}
                      >
                        <EditIcon />
                      </div>
                    </Tooltip>
                    <Tooltip title={'Remove'}>
                      <div
                        className="delete-btn action-btn"
                        onClick={() => onRemove(row)}
                      >
                        <TrashCanIcon />
                      </div>
                    </Tooltip>
                  </>
                )
              }
            </div >
          ),
        },
      ]}
      dataSource={data?.map((item) => ({ ...item, key: item.roleId })) || []}
      expandable={{
        expandedRowRender: (record) => (
          <ExpandRoleComponent
            roleId={record?.roleId}
          />
        ),
      }}
      expandedRowKeys={expKeys}
      onExpand={(expanded, record) => {
        setExpKeys(expanded ? [record.roleId] : []);
      }}
    />
  )
}

export default RoleCustomerTable;