const SECONDS_IN_DAY = 86400;

const formatTime = (seconds) => {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const remainingSeconds = Math.floor(seconds % 60);
  return `${hours.toString().padStart(2, '0')}:${minutes
    .toString()
    .padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`;
};

const timeToSeconds = (timeStr) => {
  const parts = timeStr.split(':');
  return (
    parseInt(parts[0]) * 3600 + parseInt(parts[1]) * 60 + parseInt(parts[2])
  );
};

const getTime = (computeTime) => {
  if (!computeTime) return '';
  const tmp = computeTime?.trim();
  if (tmp?.includes(' ')) return tmp?.split(' ')?.[1];
  return tmp;
};

const mergeRanges = (ranges, newRange) => {
  const newFrom = timeToSeconds(newRange.fromTime);
  const newTo = timeToSeconds(newRange.toTime);

  let merged = [];
  let current = { from: newFrom, to: newTo };

  for (const r of ranges) {
    const from = timeToSeconds(r.fromTime);
    const to = timeToSeconds(r.toTime);

    if (to < current.from || from > current.to) {
      merged.push(r);
    } else {
      current.from = Math.min(current.from, from);
      current.to = Math.max(current.to, to);
    }
  }

  merged.push({
    ...newRange,
    fromTime: formatTime(current.from),
    toTime: formatTime(current.to),
  });

  merged.sort((a, b) => timeToSeconds(a.fromTime) - timeToSeconds(b.fromTime));

  return merged;
};

const convertByteToMB = (byte) => {
  return (byte / (1024 * 1024)).toFixed(2);
};

const genDownloadKeyLocal = (serial, fromTime, toTime) => {
  return `playback-local-${serial}|${fromTime}-${toTime}`;
};

export const ProgressBarV2 = ({
  currentTime,
  onSeek,
  playbackRate,
  setPlaybackRate,
  playbackRateOptions,
  showRateSelector = true,
  maxAvailableTime,
  minAvailableTime,
  availableTimes,
  getPlaybackThumbnail,
  serial,
  name,
  namespace,
  allowPlaybackRateAdvanced,
  isFullScreen,
  handleTogglePTZDewarp,
  ptzDewarpActive,
  handleFullscreen,
  containerRef,
  handleMuted,
  muted,
}) => {
  const progressRef = useRef(null);
  const progressInnerRef = useRef(null);
  const headerInnerRef = useRef(null);
  const tooltipRef = useRef(null);
  const tooltipThumbnailRef = useRef(null);
  const tooltipTimeRef = useRef(null);
  const scrubberRef = useRef(null);
  const hoverScrubberRef = useRef(null);
  const isDragging = useRef(false);
  const [dragTime, setDragTime] = useState(null);
  const thumbnailTimerRef = useRef(null);
  const playbackControls = useSelector(getPlaybackControls);
  const [hasThumbnail, setHasThumbnail] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(1);
  const dispatch = useDispatch();
  const [selectedPlaybackRate, setSelectedPlaybackRate] = useState(
    playbackRate || PLAYBACK_RATE_OPTIONS?.[3]?.value,
  );
  const isHoldingRef = useRef(false);
  const prevPlaybackRateRef = useRef(PLAYBACK_RATE_OPTIONS?.[3]?.value);
  const playbackThumbnails = useSelector(getPlaybackThumbnails);
  const initialSelectedDate = useSelector(getSelectedDate);
  const { devicesActiveOfServices, totalCamera } = useSelector(
    (state) => state,
  );
  const [allowBackup, setAllowBackup] = useState(false);
  const { t } = useTranslation();
  const clickTimeoutRef = useRef(null);
  const [displayTime, setDisplayTime] = useState(currentTime);
  const isSeekingRef = useRef(false);
  const forceSwitchPlaybackRate = useSelector(getForceSwitchPlaybackRate);
  const [downloadModalVisible, setDownloadModalVisible] = useState(false);
  const [downloadRanges, setDownloadRanges] = useState([]);
  const [compressedProgress, setCompressedProgress] = useState(0);
  const [isLoadingConfirm, setIsLoadingConfirm] = useState(false);
  const allCompresses = useSelector(getAllCompress);

  const [isDraggingRange, setIsDraggingRange] = useState(false);
  const [dragRangeStart, setDragRangeStart] = useState(null);
  const [dragRangeEnd, setDragRangeEnd] = useState(null);
  const mouseDownPositionRef = useRef(null);
  const hasDraggedRef = useRef(false);
  const [hasNewRange, setHasNewRange] = useState(null);
  const [processedRanges, setProcessedRanges] = useState(new Set());
  const [deletedList, setDeletedList] = useState([]);
  const [popconfirmKey, setPopconfirmKey] = useState(0);
  const playbackType = useSelector(getPlaybackMode);
  const [mergedAvailableSegments, setMergedAvailableSegments] = useState([]);
  const blobUrlCacheRef = useRef({});
  const cachingDownloadedRef = useRef(new Map());
  const playbackControlsRef = useRef(playbackControls);
  const { camerasDate } = useSelector((state) => state);
  const [showEditTime, setShowEditTime] = useState(false);

  useEffect(() => {
    playbackControlsRef.current = playbackControls;
  }, [playbackControls]);

  useEffect(() => {
    if (!downloadModalVisible) {
      cachingDownloadedRef.current = new Map();
    }
  }, [downloadModalVisible]);

  useEffect(() => {
    const activeDownloads = compressManager
      .getActiveCompresses()
      .filter((d) => d.serial === serial);

    if (activeDownloads.length > 0) {
      dispatch(syncDownloadStates(serial, activeDownloads));
    }
  }, [serial, dispatch]);

  useEffect(() => {
    if (!isSeekingRef.current && dragTime === null) {
      setDisplayTime(currentTime);
    }
  }, [currentTime, dragTime]);

  useEffect(() => {
    if (playbackRate) {
      const maxPlaybackRate = Math.max(playbackRate, selectedPlaybackRate);
      setSelectedPlaybackRate(
        playbackType === EnumPlaybackType.LOCAL
          ? selectedPlaybackRate
          : allowPlaybackRateAdvanced
            ? maxPlaybackRate
            : maxPlaybackRate > 8
              ? forceSwitchPlaybackRate
                ? 1
                : 8
              : maxPlaybackRate,
      );
      if (forceSwitchPlaybackRate) {
        dispatch(setForceSwitchPlaybackRate(false));
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    playbackRate,
    allowPlaybackRateAdvanced,
    selectedPlaybackRate,
    forceSwitchPlaybackRate,
    playbackType,
  ]);

  useEffect(() => {
    if (devicesActiveOfServices) {
      if (devicesActiveOfServices?.devices?.length > 0) {
        setAllowBackup(
          devicesActiveOfServices?.devices?.some(
            (item) => item?.serial === serial,
          ),
        );
      }
    }
  }, [devicesActiveOfServices, serial]);

  useEffect(() => {
    const timeRequest = new Date().getTime();
    let data = {
      serviceId: 20,
      timeRequest,
      namespace,
      page: 0,
      size: totalCamera || 100,
    };
    let dataObj = {
      appServiceType: LIST_DEVICE_ACTIVE_SERVICE_ID,
      requestId: timeRequest,
      body: JSON.stringify(data),
    };
    return dispatch(socketEmitEvent(dataObj));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [namespace, totalCamera, serial]);

  useEffect(() => {
    if (
      !availableTimes ||
      !availableTimes.length ||
      availableTimes?.filter(
        (item) => Object.keys(item)?.length > 0 && item?.from && item?.to,
      )?.length <= 0
    ) {
      setMergedAvailableSegments([]);
      return;
    }

    let tmp = availableTimes || [];
    // beeXLogger.debug("AVAILABLE TIMES: ", availableTimes)
    const GAP_TOLERANCE = 60;
    const segments = tmp
      .map((s) => ({
        ...s,
        from: Math.max(0, Math.min(SECONDS_IN_DAY, s.from)),
        to: Math.max(0, Math.min(SECONDS_IN_DAY, s.to)),
      }))
      .map((s) => {
        if (s.to - s.from <= GAP_TOLERANCE)
          return { ...s, cloud: true, box: true };
        return s;
      })
      .sort((a, b) => a.from - b.from);
    // console.log('PLAYBACK TIME FINAL merged: ', segments);

    const merged = [];
    for (const s of segments) {
      if (!merged.length) {
        merged.push({ ...s });
        continue;
      }
      const last = merged[merged.length - 1];
      if (s.from <= last.to + GAP_TOLERANCE) {
        last.to = Math.max(last.to, s.to);
      } else {
        merged.push({ ...s });
      }
    }
    setMergedAvailableSegments(merged || []);
  }, [availableTimes]);

  const baseStart =
    mergedAvailableSegments && mergedAvailableSegments.length
      ? mergedAvailableSegments[0].from
      : 0;
  const displayTimeForOrigin =
    mergedAvailableSegments && mergedAvailableSegments.length
      ? Math.max(dragTime !== null ? dragTime : currentTime, baseStart)
      : dragTime !== null
        ? dragTime
        : currentTime;
  const originPct = (displayTimeForOrigin / SECONDS_IN_DAY) * 100;

  useEffect(() => {
    if (scrubberRef.current) {
      if (originPct > 0 && originPct < 100) {
        scrubberRef.current.style.left = `${originPct}%`;
        scrubberRef.current.style.display = `block`;
      } else {
        scrubberRef.current.style.display = `none`;
      }
    }
  }, [originPct]);

  useEffect(() => {
    return () => {
      if (clickTimeoutRef.current) {
        clearTimeout(clickTimeoutRef.current);
      }
      setZoomLevel(1);
      setSelectedPlaybackRate(PLAYBACK_RATE_OPTIONS?.[3]?.value);
      isHoldingRef.current = false;
      prevPlaybackRateRef.current = PLAYBACK_RATE_OPTIONS?.[3]?.value;
    };
  }, []);

  const isTimeAvailable = useCallback(
    (time) => {
      if (!mergedAvailableSegments || !mergedAvailableSegments.length)
        return false;
      return mergedAvailableSegments.some(
        (seg) => time >= seg.from && time <= seg.to,
      );
    },
    [mergedAvailableSegments],
  );

  const handleChangePlaybackControls = useCallback(
    (key, value) => {
      const prevControls = playbackControlsRef.current || {};
      if (prevControls?.[key] === value) return;

      const nextControls = {
        ...prevControls,
        [key]: value,
      };

      playbackControlsRef.current = nextControls;
      dispatch(setPlaybackControls(nextControls));
    },
    [dispatch],
  );

  const handleDocumentMouseMove = useCallback(
    (e) => {
      if (!isDragging.current || !progressRef.current) return;

      const rect = progressRef.current.getBoundingClientRect();
      let x = e.clientX - rect.left;

      x = Math.max(0, Math.min(x, rect.width));

      let dragTime;
      if (zoomLevel > 1) {
        const originPixel = (originPct / 100) * rect.width;
        const offsetFromOrigin = x - originPixel;
        const unscaledOffsetFromOrigin = offsetFromOrigin / zoomLevel;
        const unscaledX = originPixel + unscaledOffsetFromOrigin;
        const percentage = unscaledX / rect.width;
        dragTime = Math.floor(percentage * SECONDS_IN_DAY);
      } else {
        const percentage = x / rect.width;
        dragTime = Math.floor(percentage * SECONDS_IN_DAY);
      }

      dragTime = Math.max(0, Math.min(SECONDS_IN_DAY, dragTime));

      const isDraggingBackward = dragTime <= currentTime;

      if (!isDraggingBackward && !isTimeAvailable(dragTime)) return;

      setDragTime(dragTime);

      document.body.style.cursor = 'pointer';
      progressRef.current.style.cursor = 'pointer';

      if (tooltipRef.current) {
        tooltipRef.current.style.left = `${x}px`;
        tooltipRef.current.style.display = 'block';

        if (tooltipTimeRef.current) {
          tooltipTimeRef.current.textContent = formatTime(dragTime);
        }
      }

      if (scrubberRef.current) {
        const percentage = dragTime / SECONDS_IN_DAY;
        scrubberRef.current.style.left = `${percentage * 100}%`;
      }
    },
    [isTimeAvailable, currentTime, zoomLevel, originPct],
  );

  const handleDocumentMouseUp = useCallback(() => {
    if (!isDragging.current || !progressRef.current) return;

    isDragging.current = false;

    try {
      document.body.style.cursor = '';
      progressRef.current.style.cursor = '';
    } catch (err) {}

    const rect = progressRef.current.getBoundingClientRect();
    const caretLeft = scrubberRef.current ? scrubberRef.current.offsetLeft : 0;
    const percentage = caretLeft / rect.width;
    const seekTime = Math.floor(percentage * SECONDS_IN_DAY);

    if (tooltipRef.current) {
      tooltipRef.current.style.display = 'none';
    }

    const isBackward = seekTime <= currentTime;

    if (isBackward || isTimeAvailable(seekTime)) {
      onSeek(seekTime);
    }

    setDragTime(null);
  }, [onSeek, isTimeAvailable, currentTime]);

  useEffect(() => {
    document.addEventListener('mousemove', handleDocumentMouseMove);
    document.addEventListener('mouseup', handleDocumentMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleDocumentMouseMove);
      document.removeEventListener('mouseup', handleDocumentMouseUp);
    };
  }, [handleDocumentMouseMove, handleDocumentMouseUp]);

  const handleMouseMove = useCallback(
    (e) => {
      if (thumbnailTimerRef.current) {
        clearTimeout(thumbnailTimerRef.current);
      }
      if (tooltipThumbnailRef.current) {
        tooltipThumbnailRef.current.src = '';
        tooltipThumbnailRef.current.style.display = 'none';
        setHasThumbnail(false);
      }
      if (isDragging.current) return;

      if (!progressRef.current || !tooltipRef.current) return;

      const rect = progressRef.current.getBoundingClientRect();
      let x = e.clientX - rect.left;
      x = Math.max(0, Math.min(x, rect.width));

      let hoverTime;
      if (zoomLevel > 1) {
        // beeXLogger.debug('handleMouseMove - originPct: ', originPct);
        // beeXLogger.debug('handleMouseMove -  rect.width: ', rect.width);
        const originPixel = (originPct / 100) * rect.width;
        // beeXLogger.debug('handleMouseMove - originPixel: ', originPixel);
        const offsetFromOrigin = x - originPixel;
        // beeXLogger.debug('handleMouseMove - offsetFromOrigin: ', offsetFromOrigin);

        const unscaledOffsetFromOrigin = offsetFromOrigin / zoomLevel;
        // beeXLogger.debug('handleMouseMove - unscaledOffsetFromOrigin: ', unscaledOffsetFromOrigin);
        const unscaledX = originPixel + unscaledOffsetFromOrigin;
        // beeXLogger.debug('handleMouseMove - unscaledX: ', unscaledX);
        // beeXLogger.debug('handleMouseMove======================');

        const percentage = unscaledX / rect.width;
        hoverTime = Math.floor(percentage * SECONDS_IN_DAY);
      } else {
        const percentage = x / rect.width;
        hoverTime = Math.floor(percentage * SECONDS_IN_DAY);
      }

      hoverTime = Math.max(0, Math.min(SECONDS_IN_DAY, hoverTime));

      if (!isTimeAvailable(hoverTime)) {
        progressRef.current.style.cursor = 'not-allowed';
        if (tooltipRef.current) {
          tooltipRef.current.style.display = 'none';
        }
        if (tooltipThumbnailRef.current) {
          tooltipThumbnailRef.current.style.display = 'none';
          setHasThumbnail(false);
        }
        if (tooltipTimeRef.current) {
          tooltipTimeRef.current.style.display = 'none';
        }
        if (hoverScrubberRef.current) {
          hoverScrubberRef.current.style.left = 0;
          hoverScrubberRef.current.style.display = 'none';
        }
      } else {
        progressRef.current.style.cursor = 'pointer';
        tooltipRef.current.style.display = 'block';
        tooltipRef.current.style.left = `${x}px`;
        if (hoverScrubberRef.current) {
          hoverScrubberRef.current.style.left = `${x}px`;
          hoverScrubberRef.current.style.display = 'block';
        }

        if (tooltipTimeRef.current) {
          let displayText = formatTime(hoverTime);

          if (playbackType === EnumPlaybackType.CLOUD) {
            displayText = `${displayText} - available on cloud`;
          } else if (playbackType === EnumPlaybackType.LOCAL) {
            const isInSegment =
              mergedAvailableSegments &&
              mergedAvailableSegments.length > 0 &&
              mergedAvailableSegments?.find(
                (seg) => hoverTime >= seg.from && hoverTime <= seg.to,
              );
            if (isInSegment) {
              displayText = `${displayText} - ${isInSegment?.box ? 'available on box' : 'available on cloud'}`;
            }
          }

          tooltipTimeRef.current.textContent = displayText;
          tooltipTimeRef.current.style.display = 'block';
          tooltipTimeRef.current.style.left = `${x} px`;
        }

        if (tooltipThumbnailRef.current && !tooltipThumbnailRef.current?.src) {
          tooltipThumbnailRef.current.style.display = 'none';
          setHasThumbnail(false);
        }

        let hasCachingThumbnail = false;
        if (playbackThumbnails) {
          const finalQueryTime = computeQueryTime(
            initialSelectedDate,
            formatTime(hoverTime),
          );
          if (playbackThumbnails?.serial === serial) {
            const thumbnails = [...(playbackThumbnails?.thumbnails || [])];
            const exist = thumbnails?.find(
              (th) => th?.queryTime === finalQueryTime,
            );
            if (exist && exist?.imageBase64) {
              hasCachingThumbnail = true;
            }
          }
        }
        thumbnailTimerRef.current = setTimeout(
          async () => {
            try {
              if (getPlaybackThumbnail) {
                const res = await getPlaybackThumbnail(formatTime(hoverTime));
                const src = res?.imageBase64;

                if (tooltipThumbnailRef.current) {
                  if (src) {
                    tooltipThumbnailRef.current.src = src;
                    tooltipThumbnailRef.current.style.display = 'block';
                    setHasThumbnail(true);
                  } else {
                    tooltipThumbnailRef.current.style.display = 'none';
                    setHasThumbnail(false);
                  }
                }
              }
            } catch (err) {
              if (tooltipThumbnailRef.current) {
                tooltipThumbnailRef.current.style.display = 'none';
                setHasThumbnail(false);
              }
            }
          },
          !hasCachingThumbnail ? 250 : 0,
        );
      }
    },
    [
      zoomLevel,
      isTimeAvailable,
      originPct,
      playbackThumbnails,
      playbackType,
      mergedAvailableSegments,
      initialSelectedDate,
      serial,
      getPlaybackThumbnail,
    ],
  );

  const handleMouseLeave = useCallback(() => {
    if (thumbnailTimerRef.current) {
      clearTimeout(thumbnailTimerRef.current);
    }
    if (tooltipRef.current && !isDragging.current) {
      tooltipRef.current.style.display = 'none';
    }

    if (hoverScrubberRef.current) {
      hoverScrubberRef.current.style.left = 0;
      hoverScrubberRef.current.style.display = 'none';
    }
  }, []);

  const handleConfirmDownload = useCallback(
    (rangesToDownload = downloadRanges) => {
      return new Promise((resolve) => {
        if (rangesToDownload && rangesToDownload?.length > 0) {
          let pendingRequests = 0;
          let hasError = false;
          let downloadsFailed = [];

          rangesToDownload
            .filter((range) => {
              const rangeKey = `${range.fromTime} -${range.toTime} `;
              const downloadKeyLocal = genDownloadKeyLocal(
                range?.serial,
                computeQueryTime(
                  initialSelectedDate,
                  timeToSeconds(range?.fromTime),
                ),
                computeQueryTime(
                  initialSelectedDate,
                  timeToSeconds(range?.toTime),
                ),
              );
              const isCached =
                playbackType === EnumPlaybackType.LOCAL
                  ? cachingDownloadedRef.current?.has(downloadKeyLocal)
                  : false;
              return (
                range?.fromTime &&
                range?.toTime &&
                !processedRanges.has(rangeKey) &&
                range?.playbackType === playbackType &&
                !isCached
              );
            })
            .forEach((item) => {
              const rangeKey = `${item.fromTime} -${item.toTime} `;
              pendingRequests++;
              const hasDataOnCloud = mergedAvailableSegments?.some(
                (seg) =>
                  timeToSeconds(item?.fromTime) >= seg.from &&
                  timeToSeconds(item?.toTime) <= seg.to,
              );
              const downloadInput = {
                fromTime: computeQueryTime(
                  initialSelectedDate,
                  timeToSeconds(item.fromTime),
                ),
                toTime: computeQueryTime(
                  initialSelectedDate,
                  timeToSeconds(item.toTime),
                ),
                serial,
                namespace,
              };
              let downloadKeyLocal = null;
              if (playbackType === EnumPlaybackType.LOCAL) {
                downloadKeyLocal = genDownloadKeyLocal(
                  serial,
                  downloadInput.fromTime,
                  downloadInput.toTime,
                );
                const downloadState =
                  downloaderInstance.getState(downloadKeyLocal);
                if (
                  !downloadState ||
                  (downloadState && downloadState.status === 'error')
                ) {
                  downloaderInstance.addToWaitList(downloadKeyLocal);
                }
              }

              requestDownloadPlaybackOnDevice(downloadInput)
                .then((res) => {
                  if (res?.deviceSerial === serial && res?.downloadUrl) {
                    if (
                      downloadKeyLocal &&
                      genDownloadKeyLocal(
                        serial,
                        res?.fromTime,
                        res?.toTime,
                      ) === downloadKeyLocal &&
                      !cachingDownloadedRef.current.has(downloadKeyLocal)
                    ) {
                      cachingDownloadedRef.current.set(downloadKeyLocal, {
                        downloadKey: downloadKeyLocal,
                        playbackType,
                        serial,
                      });
                      let url = res?.downloadUrl?.includes('/playbacks')
                        ? res?.downloadUrl
                        : res?.downloadUrl?.replace(
                            serial,
                            `playbacks / ${serial} `,
                          );
                      url = url?.replace(
                        'playback01.beex.vn',
                        'playback01.beex.vn:5199',
                      );
                      setTimeout(() => {
                        beeXLogger.debug('START DOWNLOAD: ', downloadKeyLocal);
                        downloaderInstance.download(
                          downloadKeyLocal,
                          url,
                          res?.downloadType,
                          res?.fileSize || 0,
                        );
                      }, 5000);
                      setProcessedRanges(
                        (prev) => new Set([...prev, rangeKey]),
                      );
                    }
                  } else {
                    // Device returns invalid response, fallback to cloud
                    throw new Error('Invalid device download response');
                  }
                  pendingRequests--;
                  if (pendingRequests === 0) {
                    resolve({ hasError, success: !hasError });
                  }
                })
                .catch((deviceErr) => {
                  beeXLogger.debug(
                    'DEVICE DOWNLOAD FAILED, TRYING CLOUD: ',
                    deviceErr,
                  );
                  requestDownloadPlaybackOnCloud(downloadInput)
                    .then((res) => {
                      if (res?.uuid && res?.serial === serial) {
                        setProcessedRanges(
                          (prev) => new Set([...prev, rangeKey]),
                        );
                        const downloadInfo = {
                          ...item,
                          ...res,
                          name,
                          serial,
                          namespace,
                          compressStatus: res?.status || 'processing',
                          compressProgress: res?.progress || 0,
                        };

                        dispatch(addCompress(serial, res?.uuid, downloadInfo));

                        compressManager.startDownload(downloadInfo, {
                          onProgress: (uuid, info) => {
                            dispatch(updateCompress(serial, uuid, info));
                            setCompressedProgress((prev) =>
                              info?.compressProgress > prev
                                ? info?.compressProgress
                                : prev + 0.5,
                            );
                            if (
                              info.status === 'completed' &&
                              info.downloadUrl
                            ) {
                              const downloadKey = `playback - ${serial}| ${uuid} `;
                              downloaderInstance.download(
                                downloadKey,
                                info.downloadUrl,
                              );
                            }
                          },
                          onComplete: (uuid, resCompress) => {
                            const downloadKey = `playback - ${serial}| ${uuid} `;
                            dispatch(
                              updateCompress(serial, uuid, {
                                compressStatus: 'completed',
                                ...resCompress,
                                downloadKey,
                              }),
                            );
                            // beeXLogger.debug("START DOWNLOAD - CREATE BLOB LINK");

                            const downloadState =
                              downloaderInstance.getState(downloadKey);
                            if (
                              downloadState &&
                              downloadState.status !== 'error'
                            ) {
                              downloaderInstance.addToWaitList(downloadKey);
                            }
                            downloaderInstance.download(
                              downloadKey,
                              resCompress?.downloadUrl,
                            );
                          },
                          onError: (uuid, error) => {
                            dispatch(
                              updateCompress(serial, uuid, {
                                compressStatus: 'error',
                                compressError: error,
                              }),
                            );
                          },
                        });
                      }
                      pendingRequests--;
                      if (pendingRequests === 0) {
                        resolve({ hasError, success: !hasError });
                      }
                    })
                    .catch((cloudErr) => {
                      beeXLogger.debug(
                        'BOTH DEVICE AND CLOUD DOWNLOAD FAILED: ',
                        cloudErr,
                      );
                      downloadsFailed.push(item);
                      hasError = true;
                      openMessage(
                        NOTIFIES.ERROR,
                        'Failed to merge the video at this time.',
                      );
                      setProcessedRanges((prev) => {
                        const newSet = new Set(prev);
                        newSet.delete(rangeKey);
                        return newSet;
                      });
                      pendingRequests--;
                      if (pendingRequests === 0) {
                        resolve({ hasError, success: !hasError });
                      }
                    })
                    .finally(() => {
                      if (downloadsFailed.length > 0) {
                        setDownloadRanges((prev) =>
                          prev?.filter(
                            (item) =>
                              !downloadsFailed?.some(
                                (df) =>
                                  df?.fromTime === item?.fromTime &&
                                  df?.toTime === item?.toTime &&
                                  df?.serial === item?.serial,
                              ),
                          ),
                        );
                      }
                    });
                });
            });

          if (pendingRequests === 0) {
            resolve({ hasError: false, success: true });
          }
        } else {
          resolve({ hasError: false, success: true });
        }
      });
    },
    [
      dispatch,
      downloadRanges,
      initialSelectedDate,
      mergedAvailableSegments,
      name,
      namespace,
      playbackType,
      processedRanges,
      serial,
    ],
  );

  const handleRemoveDownloadCloud = (downloadKey, uuid, resourceCloudId) => {
    compressManager.removeCompress(uuid);
    downloaderInstance.cancel(downloadKey);
    dispatch(removeCompress(serial, uuid));
    setDeletedList((prev) => [...prev, uuid]);
    deleteTempDownloadPlaybackOnCloud({
      uuid: uuid,
      resourceCloudId: resourceCloudId || -1,
      serial,
      namespace,
    });
  };

  const handleRemoveDownloadLocal = (downloadKey, row) => {
    if (!downloadKey || !downloaderInstance) return;
    downloaderInstance.cancel(downloadKey);
    setDownloadRanges((prev) =>
      prev?.filter(
        (range) =>
          range?.fromTime !== row?.fromTime && range?.toTime !== row?.toTime,
      ),
    );
  };

  useEffect(() => {
    if (!scrubberRef.current) return;

    const time = dragTime !== null ? dragTime : displayTime;
    const finalTime =
      mergedAvailableSegments && mergedAvailableSegments.length
        ? Math.max(time, baseStart)
        : time;

    scrubberRef.current.style.left = `${(finalTime / SECONDS_IN_DAY) * 100}% `;
  }, [displayTime, dragTime, mergedAvailableSegments, baseStart]);

  const handleHoldStart = useCallback(
    (action) => {
      if (selectedPlaybackRate === 1) return;
      let rate = selectedPlaybackRate;

      if (clickTimeoutRef.current) {
        clearTimeout(clickTimeoutRef.current);
        clickTimeoutRef.current = null;
      }

      clickTimeoutRef.current = setTimeout(() => {
        isHoldingRef.current = true;
        isSeekingRef.current = true;

        setDisplayTime(currentTime);
        handleChangePlaybackControls('direction', 'forward');

        setTimeout(() => setPlaybackRate(rate), 10);

        prevPlaybackRateRef.current = playbackRate;
      }, 150);
    },
    [
      selectedPlaybackRate,
      currentTime,
      handleChangePlaybackControls,
      playbackRate,
      setPlaybackRate,
    ],
  );

  const handleHoldEnd = useCallback(() => {
    if (clickTimeoutRef.current) {
      clearTimeout(clickTimeoutRef.current);
      clickTimeoutRef.current = null;
    }

    if (!isHoldingRef.current) return;

    setPlaybackRate(PLAYBACK_RATE_OPTIONS?.[3]?.value);
    handleChangePlaybackControls('direction', 'forward');

    setTimeout(() => {
      isHoldingRef.current = false;
      isSeekingRef.current = false;
      setDisplayTime(currentTime);
    }, 50);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentTime]);

  const handleBackup = useCallback(() => {
    const dataBody = {
      serial,
      namespace,
      dateRecord: moment(initialSelectedDate).format('YYYY-MM-DD'),
    };
    startAdvanceBackup(dataBody).then((res) => {
      if (res?.result === 1) {
        openMessage(
          NOTIFIES.SUCCESS,
          t(
            `Successfully submitted the backup request for camera ${name} – ${moment(dataBody?.dateRecord).format('DD/MM/YYYY')} `,
          ),
        );
      } else {
        openMessage(NOTIFIES.SUCCESS, t('Something went wrong'));
      }
    });
  }, [serial, namespace, initialSelectedDate, t, name]);

  useEffect(() => {
    if (playbackControls?.direction === 'reverse' && isHoldingRef.current) {
      const interval = setInterval(() => {
        setDisplayTime(currentTime);
      }, 100);

      return () => clearInterval(interval);
    }
  }, [playbackControls, currentTime]);

  useEffect(() => {
    if (!isSeekingRef.current && dragTime === null) {
      setDisplayTime(currentTime);
    }
  }, [currentTime, dragTime]);

  const handleProgressMouseDownForRange = useCallback(
    (e) => {
      if (!progressRef.current) return;

      e.preventDefault();
      e.stopPropagation();

      const rect = progressRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;

      mouseDownPositionRef.current = { x: e.clientX, y: e.clientY };
      hasDraggedRef.current = false;

      let clickTime;
      if (zoomLevel > 1) {
        const originPixel = (originPct / 100) * rect.width;
        const offsetFromOrigin = x - originPixel;
        const unscaledOffsetFromOrigin = offsetFromOrigin / zoomLevel;
        const unscaledX = originPixel + unscaledOffsetFromOrigin;
        const percentage = unscaledX / rect.width;
        clickTime = Math.floor(percentage * SECONDS_IN_DAY);
      } else {
        const percentage = x / rect.width;
        clickTime = Math.floor(percentage * SECONDS_IN_DAY);
      }

      clickTime = Math.max(0, Math.min(SECONDS_IN_DAY, clickTime));

      if (!isTimeAvailable(clickTime)) return;

      setIsDraggingRange(true);
      setDragRangeStart(clickTime);
      setDragRangeEnd(clickTime);
    },
    [zoomLevel, isTimeAvailable, originPct],
  );

  const handleProgressMouseMoveForRange = useCallback(
    (e) => {
      if (!progressRef.current || !isDraggingRange) return;

      if (mouseDownPositionRef.current) {
        const deltaX = Math.abs(e.clientX - mouseDownPositionRef.current.x);
        const deltaY = Math.abs(e.clientY - mouseDownPositionRef.current.y);

        if (deltaX > 5 || deltaY > 5) {
          hasDraggedRef.current = true;
        }
      }

      const rect = progressRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;

      let hoverTime;
      if (zoomLevel > 1) {
        const originPixel = (originPct / 100) * rect.width;
        const offsetFromOrigin = x - originPixel;
        const unscaledOffsetFromOrigin = offsetFromOrigin / zoomLevel;
        const unscaledX = originPixel + unscaledOffsetFromOrigin;
        const percentage = unscaledX / rect.width;
        hoverTime = Math.floor(percentage * SECONDS_IN_DAY);
      } else {
        const percentage = x / rect.width;
        hoverTime = Math.floor(percentage * SECONDS_IN_DAY);
      }

      hoverTime = Math.max(0, Math.min(SECONDS_IN_DAY, hoverTime));

      if (!isTimeAvailable(hoverTime)) return;

      setDragRangeEnd(hoverTime);
    },
    [isDraggingRange, zoomLevel, isTimeAvailable, originPct],
  );

  const handleProgressMouseUpForRange = useCallback(() => {
    if (!isDraggingRange || dragRangeStart === null || dragRangeEnd === null) {
      setIsDraggingRange(false);
      setDragRangeStart(null);
      setDragRangeEnd(null);
      mouseDownPositionRef.current = null;
      hasDraggedRef.current = false;
      return;
    }

    if (!hasDraggedRef.current) {
      const seekTime = dragRangeStart;
      if (isTimeAvailable(seekTime)) {
        if (scrubberRef.current) {
          const percentage = seekTime / SECONDS_IN_DAY;
          scrubberRef.current.style.left = `${percentage * 100}% `;
          scrubberRef.current.style.display = `block`;
        }
        onSeek(seekTime);
      }
    } else {
      const from = Math.min(dragRangeStart, dragRangeEnd);
      const to = Math.max(dragRangeStart, dragRangeEnd);
      const duration = to - from;

      if (duration >= 5) {
        if (duration > 12 * 3600) {
          openMessage(
            NOTIFIES.WARNING,
            t('Download range must not exceed 12 hours'),
          );
          setDragRangeStart(null);
          setDragRangeEnd(null);
        } else {
          setPopconfirmKey((prev) => prev + 1);
          setHasNewRange({
            fromTime: formatTime(from),
            toTime: formatTime(to),
            serial,
            name,
            playbackType,
          });
        }
      }
    }
    setIsDraggingRange(false);
    mouseDownPositionRef.current = null;
    hasDraggedRef.current = false;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    isDraggingRange,
    dragRangeStart,
    dragRangeEnd,
    isTimeAvailable,
    onSeek,
    serial,
    name,
    playbackType,
  ]);

  useEffect(() => {
    const handleMouseMove = (e) => handleProgressMouseMoveForRange(e);
    const handleMouseUp = () => handleProgressMouseUpForRange();

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [handleProgressMouseMoveForRange, handleProgressMouseUpForRange]);

  useEffect(() => {
    return () => {
      const currentControls = playbackControlsRef.current || {};
      dispatch(
        setPlaybackControls({
          ...currentControls,
          state: 'pause',
        }),
      );
    };
  }, [dispatch]);

  const downloadTableColumn = useMemo(() => {
    if (playbackType === EnumPlaybackType.CLOUD) {
      return [
        {
          title: 'Camera name',
          align: 'center',
          dataIndex: 'name',
          render: (text) => text,
        },
        {
          title: 'From',
          align: 'center',
          dataIndex: 'fromTime',
          render: (text) => moment(text).format('HH:mm:ss DD-MM-YYYY'),
        },
        {
          title: 'To',
          align: 'center',
          dataIndex: 'toTime',
          render: (text) => moment(text).format('HH:mm:ss DD-MM-YYYY'),
        },
        {
          title: 'Compress status',
          align: 'center',
          dataIndex: 'key',
          render: (_, row) => {
            const status = row?.compressStatus;

            if (!status) {
              return '';
            }

            if (status === 'processing' && compressedProgress <= 0) {
              return (
                <Tooltip title="Preparing file, may take a while">
                  <div>
                    <Spin
                      spinning
                      indicator={<LoadingOutlined />}
                      className="mr-1"
                      size="small"
                    />
                    Compressing...
                  </div>
                </Tooltip>
              );
            }

            if (status === 'completed') {
              return (
                <div className="flex items-center justify-center gap-2">
                  <Progress
                    percent={row?.compressProgress || 0}
                    showInfo={false}
                    style={{ width: 120 }}
                  />
                </div>
              );
            }
            if (status === 'error') {
              return <span className="text-red-500">Failed</span>;
            }

            return (
              <Progress
                percent={compressedProgress || row?.compressProgress || 0}
                showInfo={false}
                style={{ width: 120 }}
              />
            );
          },
        },
        {
          title: 'Download status',
          dataIndex: 'key',
          align: 'center',
          width: 300,
          render: (_, row) => {
            const downloadBlob = downloaderInstance.getBlob(row?.downloadKey);
            const downloadState = downloaderInstance.getState(row?.downloadKey);
            const status = downloadState?.status;
            if (downloadState) {
              beeXLogger.debug('DOWNLOAD STATE CLOUD: ', downloadState);
            }

            if (
              (!status &&
                row?.progress === 100 &&
                row?.status !== 'completed') ||
              (status === 'waiting' &&
                (downloadState?.progress <= 0 || !downloadState?.progress))
            ) {
              return (
                <Tooltip title="Preparing file, may take a while">
                  <div>
                    <Spin
                      spinning
                      indicator={<LoadingOutlined />}
                      className="mr-1"
                      size="small"
                    />
                    Preparing file
                  </div>
                </Tooltip>
              );
            }

            if (!status) {
              return '';
            }

            if (status === 'completed') {
              if (!deletedList.includes(row?.uuid)) {
                setTimeout(() => {
                  setDeletedList((prev) => [...prev, row?.uuid]);
                  deleteTempDownloadPlaybackOnCloud({
                    uuid: row?.uuid,
                    resourceCloudId: row?.resourceCloudId,
                    serial,
                    namespace,
                  });
                }, 500);
              }

              let blobUrl = '';
              if (downloadBlob && row?.uuid) {
                if (!blobUrlCacheRef.current[row.uuid]) {
                  blobUrlCacheRef.current[row.uuid] =
                    URL.createObjectURL(downloadBlob);
                }
                blobUrl = blobUrlCacheRef.current[row.uuid];
              }

              return (
                <div className="flex items-center justify-center gap-2 relative">
                  {blobUrl && (
                    <>
                      <video
                        key={row.uuid}
                        className="w-full h-auto object-contain allow-control"
                        src={blobUrl}
                        controls
                        preload="auto"
                        style={{ display: 'block' }}
                      />
                      <button
                        onClick={() => {
                          if (downloadBlob) {
                            Downloader.downloadBlob(
                              downloadBlob,
                              row?.pathFile || row?.uuid + '.mp4',
                            );
                          }
                        }}
                        className="absolute top-2 right-2 ml-auto flex h-8 w-8 cursor-pointer items-center justify-center rounded-full border-none bg-gray-100"
                      >
                        <DownloadOutlined
                          style={{
                            color: '#000',
                          }}
                          width={14}
                          height={14}
                        />
                      </button>
                    </>
                  )}
                </div>
              );
            }

            if (status === 'error') {
              if (
                downloadRanges?.some(
                  (range) =>
                    range?.fromTime === row?.fromTime &&
                    range?.toTime === row?.toTime,
                )
              ) {
                compressManager.removeCompress(row?.uuid);
                openMessage(NOTIFIES.ERROR, t('Download failure'));
                // setDownloadRanges(prev => prev?.filter(range => range?.fromTime !== row?.fromTime && range?.toTime !== row?.toTime))
              }
              return <span className="text-red-500">Failed</span>;
            }

            return (
              <div className="flex items-center gap-2">
                <Progress
                  percent={downloadState?.progress || 0}
                  showInfo={false}
                  style={{ width: 120 }}
                />
                {downloadState?.downloadSize > 0 &&
                  downloadState?.totalSize > 0 && (
                    <span className="nowrap">
                      {convertByteToMB(downloadState?.downloadSize)} /{' '}
                      {convertByteToMB(downloadState?.totalSize)} MB
                    </span>
                  )}
              </div>
            );
          },
        },
        {
          title: 'Actions',
          align: 'center',
          render: (_, row) => (
            <div className="w-full h-full flex items-center justify-center">
              <div className="p-1 hover:bg-gray-50 rounded-full w-8 h-8 flex justify-center items-center cursor-pointer">
                <RemoveIcon
                  className="cursor-pointer"
                  onClick={() => {
                    handleRemoveDownloadCloud(
                      row?.downloadKey,
                      row.uuid,
                      row?.resourceCloudId,
                    );
                    setDownloadRanges((prev) =>
                      prev?.filter(
                        (item) =>
                          row?.fromTime !== item?.fromTime &&
                          row?.toTime !== item?.toTime &&
                          row?.serial !== item?.serial,
                      ),
                    );
                  }}
                />
              </div>
            </div>
          ),
        },
      ];
    } else {
      return [
        {
          title: 'Camera name',
          align: 'center',
          dataIndex: 'name',
          render: (text) => text,
        },
        {
          title: 'From',
          align: 'center',
          dataIndex: 'fromTime',
          render: (text) =>
            moment(text + ' ' + initialSelectedDate).format(
              'HH:mm:ss DD-MM-YYYY',
            ),
        },
        {
          title: 'To',
          align: 'center',
          dataIndex: 'toTime',
          render: (text) =>
            moment(text + ' ' + initialSelectedDate).format(
              'HH:mm:ss DD-MM-YYYY',
            ),
        },
        {
          title: 'Download status',
          dataIndex: 'key',
          align: 'center',
          width: 300,
          render: (_, row) => {
            const downloadKey = genDownloadKeyLocal(
              serial,
              computeQueryTime(
                initialSelectedDate,
                timeToSeconds(row?.fromTime),
              ),
              computeQueryTime(initialSelectedDate, timeToSeconds(row?.toTime)),
            );
            const downloadBlob = downloaderInstance.getBlob(downloadKey);
            const downloadState = downloaderInstance.getState(downloadKey);
            const status = downloadState?.status;

            if (
              (!status &&
                row?.progress === 100 &&
                row?.status !== 'completed') ||
              (status === 'waiting' &&
                (downloadState?.progress <= 0 || !downloadState?.progress))
            ) {
              return (
                <Tooltip title="Preparing file, may take a while">
                  <div>
                    <Spin
                      spinning
                      indicator={<LoadingOutlined />}
                      className="mr-1"
                      size="small"
                    />
                    Preparing file
                  </div>
                </Tooltip>
              );
            }

            if (!status) {
              return '';
            }

            if (status === 'completed') {
              let blobUrl = '';
              if (downloadBlob && downloadKey) {
                if (!blobUrlCacheRef.current[downloadKey]) {
                  blobUrlCacheRef.current[downloadKey] =
                    URL.createObjectURL(downloadBlob);
                }
                blobUrl = blobUrlCacheRef.current[downloadKey];
                cachingDownloadedRef.current.set(downloadKey, {
                  downloadKey,
                  playbackType,
                  serial,
                });
              }
              return (
                <div className="flex items-center justify-center gap-2 relative">
                  {blobUrl && (
                    <>
                      <video
                        key={downloadKey}
                        className="w-full h-auto object-contain allow-control"
                        src={blobUrl}
                        controls
                        preload="auto"
                        style={{ display: 'block' }}
                      />
                      <button
                        onClick={() => {
                          if (downloadBlob) {
                            Downloader.downloadBlob(
                              downloadBlob,
                              `playback-${row?.serial}-${row?.fromTime}-${row?.toTime}.mp4`,
                            );
                          }
                        }}
                        className="absolute top-2 right-2 ml-auto flex h-8 w-8 cursor-pointer items-center justify-center rounded-full border-none bg-gray-100"
                      >
                        <DownloadOutlined
                          style={{
                            color: '#000',
                          }}
                          width={14}
                          height={14}
                        />
                      </button>
                    </>
                  )}
                </div>
              );
            }

            if (status === 'error') {
              if (
                downloadRanges?.some(
                  (range) =>
                    range?.fromTime === row?.fromTime &&
                    range?.toTime === row?.toTime,
                )
              ) {
                compressManager.removeCompress(row?.uuid);
                openMessage(NOTIFIES.ERROR, t('Download failure'));
                // setDownloadRanges(prev => prev?.filter(range => range?.fromTime !== row?.fromTime && range?.toTime !== row?.toTime))
              }
              return <span className="text-red-500">Failed</span>;
            }

            return (
              <div className="flex items-center justify-center gap-2">
                <Progress
                  percent={downloadState?.progress || 0}
                  showInfo={false}
                  style={{ width: 120 }}
                />
                {downloadState?.downloadSize > 0 && (
                  <span className="nowrap">
                    {convertByteToMB(downloadState?.downloadSize)} /{' '}
                    {convertByteToMB(downloadState?.totalSize)} MB
                  </span>
                )}
              </div>
            );
          },
        },
        {
          title: 'Actions',
          align: 'center',
          render: (_, row) => (
            <div className="w-full h-full flex items-center justify-center">
              <div className="p-1 hover:bg-gray-50 rounded-full w-8 h-8 flex justify-center items-center cursor-pointer">
                <RemoveIcon
                  className="cursor-pointer"
                  onClick={() =>
                    handleRemoveDownloadLocal(
                      genDownloadKeyLocal(
                        serial,
                        computeQueryTime(
                          initialSelectedDate,
                          timeToSeconds(row?.fromTime),
                        ),
                        computeQueryTime(
                          initialSelectedDate,
                          timeToSeconds(row?.toTime),
                        ),
                      ),
                      row,
                    )
                  }
                />
              </div>
            </div>
          ),
        },
      ];
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    compressedProgress,
    deletedList,
    downloadRanges,
    namespace,
    playbackType,
    serial,
  ]);

  const downloadDataSource = useMemo(() => {
    if (playbackType === EnumPlaybackType.CLOUD) {
      return allCompresses && allCompresses?.length > 0
        ? allCompresses.filter((item) => item && item?.fromTime && item?.toTime)
        : [];
    } else {
      return downloadRanges || [];
    }
  }, [allCompresses, downloadRanges, playbackType]);

  useEffect(() => {
    setDownloadRanges((prev) =>
      prev?.some((item) => item?.playbackType === playbackType)
        ? prev?.filter((range) => range?.playbackType === playbackType)
        : prev,
    );
  }, [playbackType]);

  const onSelectedDateChange = (date) => {
    dispatch(setSelectedDate(date));
  };

  return (
    <div
      className={`relative w-full rounded-sm p-4 pt-0 `}
      style={{
        backgroundColor: isFullScreen ? 'transparent' : 'white',
      }}
    >
      <div className="mb-2 relative overflow-hidden">
        <DatePicker
          value={moment(initialSelectedDate, PLAYBACK_DATE_FORMAT)}
          onChange={(date) =>
            onSelectedDateChange(
              date?.format(PLAYBACK_DATE_FORMAT) ??
                moment().startOf('day').format(PLAYBACK_DATE_FORMAT),
            )
          }
          style={{
            width: '20%',
            maxWidth: 200,
          }}
          disabledDate={(current) => {
            return current.isAfter(moment(), 'day');
          }}
          dateRender={(current) => {
            const style = {};
            if (
              camerasDate &&
              camerasDate.find((x) => x === current.format('MM-DD-YYYY'))
            ) {
              style.color = 'rgba(255, 255, 255, 0.85)';
              style.borderBottom = '1px solid #028fd5';
            }
            return (
              <div className="ant-picker-cell-inner" style={style}>
                {current.date()}
              </div>
            );
          }}
        />
        <div
          ref={headerInnerRef}
          className="flex justify-between transition-all absolute"
          style={{
            transform: zoomLevel > 1 ? `scaleX(${zoomLevel})` : 'none',
            transformOrigin: `${originPct}% 50 % `,
            width: '100%',
            left: 0,
            marginTop: 10,
          }}
        >
          {Array.from({ length: 25 }).map((_, i) => {
            const hourTime = i * 3600;
            const isOutside =
              minAvailableTime < maxAvailableTime
                ? (typeof minAvailableTime === 'number' &&
                    hourTime < minAvailableTime) ||
                  (typeof maxAvailableTime === 'number' &&
                    hourTime > maxAvailableTime)
                : true;

            const position = (i / 24) * 100;

            return (
              <div
                key={i}
                className={`text-xs font-bold ${zoomLevel !== 1 ? 'absolute' : ''} ${
                  isOutside
                    ? isFullScreen
                      ? 'text-textButton'
                      : 'text-gray-400'
                    : isFullScreen
                      ? 'text-white'
                      : 'text-textButton'
                } `}
                style={{
                  transform:
                    zoomLevel > 1 ? `scaleX(${1 / zoomLevel})` : 'none',
                  transformOrigin: 'center',
                  left: `${position}% `,
                  whiteSpace: 'nowrap',
                  textAlign: 'center',
                  width: 'fit-content',
                }}
              >
                {`${i.toString().padStart(2, '0')}:00`}
              </div>
            );
          })}
        </div>
        <div style={{ height: '1.5rem' }} />
      </div>

      <div className="relative mt-3 mb-0 rounded-2xl">
        <div
          ref={tooltipRef}
          className={`absolute z-50 hidden select-none pointer-events-none ${hasThumbnail ? '-top-44' : '-top-11'} `}
          style={{
            left: '0px',
            transform: `translateX(-50%)`,
          }}
        >
          <div className="flex flex-col items-center">
            <img
              ref={tooltipThumbnailRef}
              src=""
              alt="thumb"
              className="w-48 h-32 object-cover rounded-md mb-1 hidden z-50"
              style={{
                border: '2px solid #028fd5',
              }}
            />
            <div
              ref={tooltipTimeRef}
              className="whitespace-nowrap rounded-md bg-bg2 px-3 py-1.5 text-sm text-textButton shadow-lg z-10"
            />
          </div>
        </div>

        <div
          ref={hoverScrubberRef}
          className="absolute top-1/2 -translate-y-1/2 transition-opacity hoverScrubber"
          style={{
            width: '2px',
            height: '100%',
            backgroundColor: '#faad14',
            transform: 'translate(-50%, -50%)',
            zIndex: 30,
            pointerEvents: 'none',
            left: '0%',
            top: 0,
            maxHeight: '100%',
            display: 'none',
          }}
        />

        <div
          ref={scrubberRef}
          className="absolute top-1/2 -translate-y-1/2 transition-transform scrubber justify-center hidden"
          style={{
            width: '2px',
            height: '100%',
            backgroundColor: '#faad14',
            cursor: 'pointer',
            transform: 'translate(-50%, -50%)',
            zIndex: 40,
            pointerEvents: 'auto',
            left: '0%',
            top: 0,
            maxHeight: '100%',
          }}
        />
        {downloadRanges &&
          downloadRanges?.length > 0 &&
          downloadRanges
            ?.filter(
              (item) =>
                item?.serial === serial && item?.playbackType === playbackType,
            )
            ?.map((downloadRange, index) => (
              <>
                {downloadRange.fromTime && downloadRange.toTime && (
                  <div
                    key={downloadRange}
                    className="absolute h-full"
                    style={{
                      top: 0,
                      transform: 'translateY(-50%)',
                      left: `${(timeToSeconds(downloadRange.fromTime) / SECONDS_IN_DAY) * 100}% `,
                      width: `${(Math.abs(timeToSeconds(downloadRange.toTime) - timeToSeconds(downloadRange.fromTime)) / SECONDS_IN_DAY) * 100}% `,
                      // backgroundColor: '#faad14',
                      backgroundColor: 'transparent',
                      zIndex: 25,
                      pointerEvents: 'none',
                    }}
                  />
                )}
              </>
            ))}

        <Popconfirm
          className="z-50"
          key={popconfirmKey}
          title={
            hasNewRange
              ? t('Are you sure to download this range {{from}} - {{to}}', {
                  from: hasNewRange?.fromTime,
                  to: hasNewRange?.toTime,
                })
              : null
          }
          onConfirm={async () => {
            const newRanges = mergeRanges(downloadRanges || [], {
              ...hasNewRange,
            });
            setDownloadRanges((prev) => [...prev, hasNewRange]);
            setIsLoadingConfirm(true);

            try {
              const result = await handleConfirmDownload([
                ...downloadRanges,
                hasNewRange,
              ]);
              if (result?.success && !result?.hasError) {
                setDownloadModalVisible(true);
              }
            } catch (error) {
            } finally {
              setIsLoadingConfirm(false);
            }

            setHasNewRange(null);
            setDragRangeStart(null);
            setDragRangeEnd(null);
            mouseDownPositionRef.current = null;
            hasDraggedRef.current = false;
          }}
          onCancel={() => setHasNewRange(null)}
          okText="Yes"
          cancelText="No"
          visible={hasNewRange}
          destroyTooltipOnHide={true}
          getPopupContainer={(trigger) =>
            trigger ? trigger?.parentElement : document.body || document.body
          }
          okButtonProps={{
            loading: isLoadingConfirm,
            disabled: isLoadingConfirm,
          }}
          trigger={[]}
        >
          {dragRangeStart !== null && dragRangeEnd !== null ? (
            <div
              className="absolute h-full"
              style={{
                top: 0,
                transform: 'translateY(-50%)',
                left: `${(Math.min(dragRangeStart, dragRangeEnd) / SECONDS_IN_DAY) * 100}% `,
                width: `${(Math.abs(dragRangeEnd - dragRangeStart) / SECONDS_IN_DAY) * 100}% `,
                backgroundColor: 'rgba(68, 185, 123, 0.5)',
                zIndex: 26,
                pointerEvents: 'none',
                border: '1px solid #44b97b',
              }}
            />
          ) : (
            <span style={{ display: 'none' }}></span>
          )}
        </Popconfirm>

        <div
          className="relative cursor-pointer bg-gray-300 shadow-inner overflow-hidden rounded-2xl h-2"
          ref={progressRef}
          onMouseDown={handleProgressMouseDownForRange}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          style={{ top: '50%', transform: 'translateY(-50%)' }}
        >
          <div
            ref={progressInnerRef}
            className="absolute inset-0 transition-all"
            style={{
              transform: zoomLevel > 1 ? `scaleX(${zoomLevel})` : 'none',
              transformOrigin: `${originPct}% 50% `,
            }}
          >
            {mergedAvailableSegments.map((seg, index) => {
              const leftPct = (seg.from / SECONDS_IN_DAY) * 100;
              const widthPct = ((seg.to - seg.from) / SECONDS_IN_DAY) * 100;
              return (
                <div
                  key={index}
                  className="absolute h-full"
                  style={{
                    left: `${leftPct}% `,
                    width: `${widthPct}% `,
                    zIndex: 2,
                    backgroundColor: seg?.box
                      ? '#0a3d88'
                      : seg?.cloud
                        ? '#028fd5'
                        : '#6ecfff',
                  }}
                  onMouseMove={handleMouseMove}
                  onMouseLeave={handleMouseLeave}
                />
              );
            })}
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <div className="flex items-center justify-start gap-2">
          <div
            className={`text-sm font-medium select-none ${isFullScreen ? 'text-white' : 'text-textButton'} `}
            onClick={() => setShowEditTime((prev) => !prev)}
          >
            {showEditTime ? (
              <Input placeholder="Enter time" value={''} type="time" />
            ) : (
              formatTime(currentTime > displayTime ? currentTime : displayTime)
            )}
          </div>

          {muted ? (
            <img
              src={MuteIcon}
              onClick={() => {
                handleMuted(false);
              }}
              alt=""
              width={24}
              height={24}
              className="cursor-pointer"
            />
          ) : (
            <img
              src={UnMuteIcon}
              onClick={() => {
                handleMuted(true);
              }}
              alt=""
              width={24}
              height={24}
              className="cursor-pointer"
            />
          )}
        </div>

        <div
          className={`flex items-center justify-center gap-2 ${isFullScreen ? 'in-fullscreen' : ''} `}
        >
          <Tooltip
            title={
              currentTime && playbackControls?.state === 'play'
                ? t('Rewind')
                : null
            }
          >
            <Button
              style={{ width: 32, height: 32 }}
              className={`border - white btn - control ${!currentTime || playbackControls?.state === 'loading' || playbackControls?.state === 'reload' ? 'disabled' : ''} `}
              disabled={
                !currentTime ||
                playbackControls?.state === 'loading' ||
                playbackControls?.state === 'reload'
              }
              type={
                playbackControls?.direction === 'reverse' &&
                isHoldingRef.current
                  ? 'primary'
                  : 'default'
              }
              shape="circle"
              icon={<Rewind10Icon />}
              onClick={() => {
                if (!isHoldingRef.current) {
                  handleChangePlaybackControls('rewind', 10);
                }
              }}
            />
          </Tooltip>

          <Tooltip
            title={t(
              currentTime
                ? playbackControls?.state === 'pause'
                  ? 'Play'
                  : playbackControls?.state === 'play'
                    ? 'Pause'
                    : playbackControls?.state === 'reload'
                      ? 'Reload'
                      : playbackControls?.state === 'loading'
                        ? ''
                        : ''
                : null,
            )}
          >
            <Button
              style={{ width: 32, height: 32 }}
              disabled={!currentTime || playbackControls?.state === 'loading'}
              className={`btn - control ${!currentTime || playbackControls?.state === 'loading' ? 'disabled' : ''} `}
              type="default"
              shape="circle"
              icon={
                currentTime ? (
                  playbackControls?.state === 'pause' ? (
                    <CaretRightOutlined />
                  ) : playbackControls?.state === 'play' ? (
                    <PauseOutlined />
                  ) : playbackControls?.state === 'reload' ? (
                    <ReloadOutlined />
                  ) : playbackControls?.state === 'loading' ? (
                    <LoadingOutlined />
                  ) : (
                    <PauseOutlined />
                  )
                ) : (
                  <CaretRightOutlined />
                )
              }
              onClick={() =>
                handleChangePlaybackControls(
                  'state',
                  playbackControls?.state === 'pause'
                    ? 'play'
                    : playbackControls?.state === 'play'
                      ? 'pause'
                      : playbackControls?.state === 'reload'
                        ? 'triggerReload'
                        : 'pause',
                )
              }
            />
          </Tooltip>

          <Tooltip
            title={
              currentTime && playbackControls?.state === 'play'
                ? selectedPlaybackRate === 1
                  ? 'Forward'
                  : !isHoldingRef.current
                    ? t('Press and hold to speed up')
                    : null
                : null
            }
          >
            <Button
              style={{ width: 32, height: 32 }}
              disabled={
                !currentTime ||
                playbackControls?.state === 'loading' ||
                playbackControls?.state === 'reload'
              }
              className={`btn - control ${!currentTime || playbackControls?.state === 'loading' || playbackControls?.state === 'reload' ? 'disabled' : ''} `}
              type={
                playbackControls?.direction === 'forward' &&
                isHoldingRef.current
                  ? 'primary'
                  : 'default'
              }
              shape="circle"
              icon={
                !isHoldingRef.current ? (
                  selectedPlaybackRate === 1 ? (
                    <Forward10Icon />
                  ) : (
                    <ForwardOutlined />
                  )
                ) : playbackRate <= 1 ? (
                  <Forward10Icon />
                ) : (
                  <ForwardOutlined />
                )
              }
              onClick={() => {
                if (!isHoldingRef.current) {
                  handleChangePlaybackControls('forward', 10);
                }
              }}
              onMouseDown={() => handleHoldStart('forward')}
              onMouseUp={() => handleHoldEnd()}
              onMouseLeave={() => handleHoldEnd()}
              onTouchStart={() => handleHoldStart('forward')}
              onTouchEnd={() => handleHoldEnd()}
            />
          </Tooltip>
        </div>

        <div
          className={`flex items-center ${isFullScreen ? 'in-fullscreen gap-3' : 'gap-2'} `}
        >
          {allowBackup && (
            <Tooltip title="Backup">
              <Button
                shape="circle"
                type="default"
                className="rounded-full btn-migration"
                onClick={handleBackup}
              >
                <MigrationIcon />
              </Button>
            </Tooltip>
          )}

          <Tooltip placement="topRight" title={t('View downloading')}>
            <Button
              type="default"
              className="rounded-full"
              onClick={() => setDownloadModalVisible(true)}
              icon={<DownloadOutlined />}
            />
          </Tooltip>
          {/* <div className="flex items-center gap-2 border-brand border border-solid rounded-full px-2 py-1 zoom-progress">
            <span
              className={`w-6 h-6 flex items-center justify-center rounded-full cursor-pointer transition zoom-btn
                ${zoomLevel === 1 ? 'text-gray-400 cursor-not-allowed' : 'hover:bg-gray-50 hover:text-brand active:scale-95 active'} `}
              onClick={() => zoomLevel > 1 && setZoomLevel(z => z - 1)}
            >
              <MinusCircleOutlined className={`${zoomLevel > 1 ? 'hover:text-brand' : ''} `} />
            </span>
            <span className="text-xs font-semibold text-gray-600 select-none zoom-label">ZOOM</span>
            <span
              className={`w-6 h-6 flex items-center justify-center rounded-full cursor-pointer transition zoom-btn
                ${zoomLevel === 15 ? 'text-gray-400 cursor-not-allowed' : 'hover:bg-gray-50 hover:text-brand active:scale-95 active'} `}
              onClick={() => zoomLevel < 15 && setZoomLevel(z => z + 1)}
            >
              <PlusCircleOutlined className={`${zoomLevel < 15 ? 'hover:text-brand' : ''} `} />
            </span>
          </div> */}

          {showRateSelector && (
            <Select
              virtual={false}
              size="sm"
              options={playbackRateOptions}
              value={selectedPlaybackRate}
              onChange={setSelectedPlaybackRate}
              style={{ minWidth: '100px' }}
              className="bg-transparent rounded-full playback-rate-selector border-brand border border-solid"
              getPopupContainer={(trigger) => trigger.parentElement}
            />
          )}

          {isFullScreen && currentTime > 0 && (
            <div
              className={`flex justify-end items-center gap-2 ${!isFullScreen ? 'w-full' : ''} `}
            >
              <img
                src={ptzDewarpActive ? ControlIconOn : ControlIconOff}
                alt="PTZ Dewarp"
                width={24}
                height={24}
                onClick={handleTogglePTZDewarp}
                className="cursor-pointer"
              />
              <img
                src={isFullScreen ? ExitFullscreenIcon : FullscreenIcon}
                alt="Fullscreen"
                width={24}
                height={24}
                onClick={handleFullscreen}
                className="cursor-pointer"
              />
            </div>
          )}
        </div>
      </div>

      <Modal
        title={t('Download')}
        visible={downloadModalVisible}
        onOk={() => {
          setDownloadModalVisible(false);
          setCompressedProgress(0);
        }}
        onCancel={() => {
          setDownloadModalVisible(false);
          setCompressedProgress(0);
        }}
        footer={null}
        width={1500}
        getContainer={() =>
          (containerRef && containerRef?.current) || document.body
        }
      >
        <div className="space-y-4">
          <Table
            dataSource={downloadDataSource?.map((item, index) => ({
              ...item,
              key: item?.uuid,
              index: index + 1,
            }))}
            columns={downloadTableColumn}
            pagination={false}
            scroll={{
              y: '50vh',
            }}
          />
        </div>
      </Modal>
    </div>
  );
};
