import React from 'react';

const SECONDS_IN_HOUR = 3600;

export const TimelineHeader = ({
  headerInnerRef,
  zoomLevel,
  originPct,
  minAvailableTime,
  maxAvailableTime,
  isFullScreen
}) => {
  return (
    <div className="mb-2 relative overflow-hidden">
      <div
        ref={headerInnerRef}
        className="flex justify-between transition-all absolute"
        style={{
          transform: zoomLevel > 1 ? `scaleX(${zoomLevel})` : 'none',
          transformOrigin: `${originPct}% 50%`,
          width: '100%',
          left: 0,
        }}
      >
        {Array.from({ length: 25 }).map((_, i) => {
          const hourTime = i * SECONDS_IN_HOUR;
          const isOutside = minAvailableTime < maxAvailableTime ?
            ((typeof minAvailableTime === 'number' && hourTime < minAvailableTime) ||
              (typeof maxAvailableTime === 'number' && hourTime > maxAvailableTime)) : true;

          const position = (i / 24) * 100;

          return (
            <div
              key={i}
              className={`text-xs font-bold ${zoomLevel !== 1 ? 'absolute' : ''} ${
                isOutside
                  ? isFullScreen ? 'text-textButton' : 'text-gray-400'
                  : isFullScreen ? 'text-white' : 'text-textButton'
              }`}
              style={{
                transform: zoomLevel > 1 ? `scaleX(${1 / zoomLevel})` : 'none',
                transformOrigin: 'center',
                left: `${position}%`,
                whiteSpace: 'nowrap',
                textAlign: 'center',
                width: 'fit-content',
              }}
            >
              {`${i.toString().padStart(2, '0')}:00`}
            </div>
          );
        })}
      </div>
      <div style={{ height: '1rem' }} />
    </div>
  );
};
