import { DownloadOutlined, ExclamationCircleOutlined } from '@ant-design/icons';
import {
  Button,
  Checkbox,
  Col,
  Empty,
  Modal,
  Popover,
  Row,
  Select,
  Tag,
  Tooltip,
} from 'antd';
import introJs from 'intro.js';
import moment from 'moment';
import React, { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSelector } from 'react-redux';
import NoDataIcon from '../../assets/icons/no-data-icon-v2.svg';
import IconExclamation from '../../assets/icons/exclamation.svg';
import IconPlayButton from '../../assets/icons/play-button.svg';
import Thumbnail from '../../assets/images/thumbnail.jpg';
import Spinner from '../../components/Spinner';
import * as SERVICE from '../../constants/service.types';
import { resetCameraStorageReturn, socketEmitEvent } from '../../redux/actions';
import { downloadFile } from '../../untils/download';
import VideoInformation from '../Camera/VideoInformation';
import './index.scss';
import {
  generateLinkExternalStorageFile,
  getListExternalCameraStorageFile,
} from '@/hooks/socket/playback';
import PlayerComponent from '@/components/Player';
import PlaceHolderThumbnail from '@/assets/images/thumbnail-placeholder.png';

const { Option } = Select;
const { confirm } = Modal;

const ALL_TIME_PICKER_VALUE = 1000;

const BackupStorageVideoComponent = ({
  dispatch,
  serial,
  permission,
  selectCamera,
  dateRecord,
}) => {
  const { t } = useTranslation();
  const { decryptData, namespace } = useSelector((state) => state);

  const [isLoading, setIsLoading] = useState(false);
  const [timeRecord, setTimeRecord] = useState();
  const [data, setData] = useState();
  const [timePicker, setTimePicker] = useState(ALL_TIME_PICKER_VALUE);
  const [videos, setVideos] = useState(null);
  const [dataSelectSource, setDataSelectSource] = useState();
  const [downloadVideos, setDownloadVideos] = useState([]);
  const [backupStorage, setBackupStorage] = useState(null);
  const [videoLoading, setVideoLoading] = useState();
  const [downLoading, setDownloading] = useState(false);

  useEffect(() => {
    return () => {
      setData(null);
    };
  }, []);

  useEffect(() => {
    if (serial && namespace) {
      setIsLoading(true);
      getListExternalCameraStorageFile({
        serial,
        namespace,
        dateRecord: moment(dateRecord || Date.now()).format('YYYY-MM-DD'),
      })
        .then((res) => {
          setBackupStorage(
            res?.map((item) => {
              const tmp = { ...item };
              const pathFile = item?.pathFile;
              if (!pathFile) return tmp;

              const timestamp = Number(pathFile.split('_')[1]) * 1000;

              const fromMoment = moment(timestamp).subtract(7, 'hour');
              const from = fromMoment.format('HH:mm:ss');

              const hour = fromMoment.hour();
              const minute = fromMoment.minute();
              const durationMs = item?.duration;
              const to = fromMoment
                .clone()
                .add(durationMs, 'seconds')
                .format('HH:mm:ss');

              const d = moment.duration(durationMs, 'seconds');
              const duration =
                d.hours() > 0
                  ? moment.utc(d.asMilliseconds()).format('HH:mm:ss')
                  : moment.utc(d.asMilliseconds()).format('mm:ss');
              return {
                ...tmp,
                recordId: item?.pathFile + '_' + Math.random(),
                from,
                to,
                hour,
                minute,
                duration,
                durationMs,
              };
            }),
          );
          setIsLoading(false);
          console.log('getListExternalCameraStorageFile - res: ', res);
        })
        .catch((err) => {
          console.log('getListExternalCameraStorageFile - err: ', err);
          setIsLoading(false);
        });
    }
  }, [serial, namespace, dateRecord]);

  useEffect(() => {
    setTimeout(() => {
      introJs().start();
    }, 300);
    return () => {
      dispatch(resetCameraStorageReturn());
      introJs().exit();
    };
  }, [dispatch]);

  const handleConfirmDownload = useCallback(async () => {
    setDownloading(true);

    const progressMap = new Map();
    let completedCount = 0;

    try {
      const downloadPromises = downloadVideos.map(async (video, index) => {
        const res = await generateLinkExternalStorageFile({
          serial: video?.serial,
          dateRecord: video?.recordDate,
          pathFile: video?.pathFile,
          namespace,
        });

        const secureLink = res?.secureLink;
        if (!secureLink) return;

        await downloadFile({
          url: secureLink,
          fileName: video?.pathFile?.replace('.mp4', ''),
          isSaveAs: true,
          onProgress: (progress) => {
            progressMap.set(index, progress);
          },
          onFetched: () => {
            completedCount++;
            if (completedCount === downloadVideos?.length) {
              setDownloading(false);
              setDownloadVideos([]);
            }
          },
        });
      });

      await Promise.allSettled(downloadPromises);
    } finally {
      setDownloading(false);
    }
  }, [downloadVideos, namespace]);

  const handleDownloadVideos = useCallback(() => {
    if (!downloadVideos?.length) return;

    confirm({
      title: t('Are you sure to download videos?'),
      icon: <ExclamationCircleOutlined />,
      onOk: () => {
        handleConfirmDownload();
      },
    });
  }, [downloadVideos, handleConfirmDownload, t]);

  useEffect(() => {
    if (!backupStorage) return;

    let times = [];
    backupStorage.map(
      (video) =>
        !times.some((time) => time.value - 100 === video.hour) &&
        times.push({
          value: video.hour + 100,
          title: `${video.hour < 10 ? '0' + video.hour : video.hour}:00 - ${
            video.hour === 23
              ? '00'
              : video.hour < 9
                ? '0' + (video.hour + 1)
                : video.hour + 1
          }:00`,
        }),
    );
    setTimeRecord(times);
    setData([...backupStorage].reverse());

    if (backupStorage.length === 0) {
      setVideos(null);
      setIsLoading(false);
      return;
    }

    setIsLoading(false);
  }, [backupStorage]);

  useEffect(() => {
    if (!data?.length) {
      setVideos(null);
      return;
    }

    let videos = [];
    data.forEach((video) => {
      if (
        !videos?.find(
          (item) => item.from === video.from && item.minute === video.minute,
        )
      ) {
        videos.push({
          ...video,
          loading: false,
        });
      }
    });
    videos.sort((a, b) => {
      return b?.from?.localeCompare(a?.from, undefined, {
        numeric: true,
        sensitivity: 'base',
      });
    });

    const selectedTime = Number(timePicker);
    const filteredVideos =
      selectedTime === ALL_TIME_PICKER_VALUE
        ? videos
        : videos.filter((video) => Number(video.hour) === selectedTime - 100);

    setVideos(filteredVideos?.length ? filteredVideos : null);
  }, [data, timePicker]);

  const onLogService = useCallback(
    async (serial) => {
      const timeRequest = new Date().getTime();
      let data = {
        timeRequest,
        namespace,
        serial,
      };
      let dataObj = {
        appServiceType: SERVICE.LIST_SERVICE_BY_DEVICE_SERIAL,
        requestId: timeRequest,
        body: JSON.stringify(data),
      };
      return dispatch(socketEmitEvent(dataObj));
    },
    [dispatch, namespace],
  );

  useEffect(() => {
    if (selectCamera) {
      onLogService(selectCamera.serial);
    }
  }, [selectCamera, onLogService]);

  const onViewVideo = useCallback(
    async (recordId) => {
      const video = videos.find((v) => v.recordId === recordId);
      if (!video) return;

      generateLinkExternalStorageFile({
        serial: video?.serial,
        dateRecord: video?.recordDate,
        pathFile: video?.pathFile,
        namespace,
      })
        .then((res) => {
          console.log('🚀 ~ BackupStorageVideoComponent ~ res:', res);
          if (res && res?.secureLink) {
            setVideos((state) =>
              state.map((v) =>
                v.recordId === recordId
                  ? { ...v, secureLink: res?.secureLink, loading: false }
                  : v,
              ),
            );
          }
          setVideoLoading(null);
        })
        .catch(() => {
          setVideoLoading(null);
        });
    },
    [videos, namespace],
  );

  const getListStorage = useCallback(
    (serial, dateRecord) => {
      let data = {
        serial,
        dateRecord: dateRecord.format('YYYY-MM-DD'),
        namespace,
      };
      let dataObj = {
        appServiceType: SERVICE.LIST_CAMERA_STORAGE_FILE,
        requestId: new Date().getTime(),
        body: JSON.stringify(data),
      };

      dispatch(socketEmitEvent(dataObj));
    },
    [dispatch, namespace],
  );

  const getListStorageDate = useCallback(
    (serial) => {
      let data = {
        serial,
        namespace,
      };
      let dataObj = {
        appServiceType: SERVICE.LIST_CAMERA_STORAGE_FILE_DATE,
        requestId: new Date().getTime(),
        body: JSON.stringify(data),
      };

      dispatch(socketEmitEvent(dataObj));
    },
    [dispatch, namespace],
  );

  useEffect(() => {
    if (dateRecord && serial) {
      getListStorage(serial, dateRecord);
      setIsLoading(true);
    }
  }, [dateRecord, getListStorage, serial]);

  useEffect(() => {
    if (serial) {
      getListStorageDate(serial);
    }
  }, [getListStorageDate, serial]);

  const handleReportActionLog = (logContent, logSerial) => {
    let data = {
      action: 'Download',
      content: logContent,
      namespace,
      serial: logSerial,
    };
    let dataObj = {
      appServiceType: SERVICE.REPORT_ACTION_LOG,
      requestId: new Date().getTime(),
      body: JSON.stringify(data),
    };
    dispatch(socketEmitEvent(dataObj));
  };

  useEffect(() => {
    let timeout = null;
    if (videoLoading) {
      timeout = setTimeout(() => {
        onViewVideo(videoLoading?.recordId);
      }, 100);
    }
    return () => {
      clearTimeout(timeout);
    };
  }, [videoLoading, onViewVideo]);

  const onChangeSelectDownload = (checked, video) => {
    if (!video?.recordId) return;

    setDownloadVideos((prev) => {
      const existed = prev.some((item) => item.recordId === video.recordId);

      if (checked && !existed) {
        return [...prev, video];
      }

      if (!checked) {
        return prev.filter((item) => item.recordId !== video.recordId);
      }

      return prev;
    });
  };

  return (
    <div className="storage-video-component">
      <div className="header-storage-component flex items-center justify-between">
        <div className="picker-side" style={{ display: 'flex' }}>
          <Select
            className="picker"
            value={timePicker}
            disabled={!timeRecord}
            onChange={(times) => setTimePicker(Number(times))}
            style={{ width: '255px', height: '32px' }}
          >
            <Option value={ALL_TIME_PICKER_VALUE}>{t('All time')}</Option>
            {timeRecord &&
              timeRecord.map((time, index) => (
                <Option key={index} value={time.value}>
                  {time.title}
                </Option>
              ))}
          </Select>
        </div>
        <div>
          <Button
            type="primary"
            icon={<DownloadOutlined />}
            onClick={handleDownloadVideos}
            loading={downLoading}
            disabled={downloadVideos?.length === 0}
          >
            Download{' '}
            {downloadVideos?.length > 0 &&
              `(${downloadVideos?.length} file${downloadVideos?.length > 1 ? 's' : ''})`}
          </Button>
        </div>
      </div>

      <div className="center-storage-component">
        {!isLoading ? (
          videos ? (
            videos.length > 0 && (
              <Row gutter={[8, 8]}>
                {videos.map((video) => (
                  <Col key={video.recordId} xs={24} md={12} lg={8}>
                    <div className="main-child-video">
                      <div className="streaming-video">
                        {video?.secureLink ? (
                          <>
                            <PlayerComponent
                              type="video"
                              loading={video.loading}
                              permission={permission && permission.split('_')}
                              src={video.secureLink && video.secureLink}
                              poster={
                                video.thumbnail &&
                                video.thumbnail.match(/http/g)
                                  ? video.thumbnail
                                  : Thumbnail
                              }
                              logContent={JSON.stringify({
                                recordId: video.recordId,
                                isSaveAs: decryptData?.fileName ? true : false,
                                cameraName:
                                  decryptData?.fileName ||
                                  video.fileName?.replace('.mp4', ''),
                                actionDate: moment(video.recordDate).format(
                                  'DD-MM-YYYY',
                                ),
                              })}
                              logSerial={video.serial}
                              handleReportActionLog={handleReportActionLog}
                              dateTime={`${
                                moment(video?.recordDate).format(
                                  'DD-MM-YYYY',
                                ) ?? ''
                              }_${video?.from?.replaceAll(':', '-') ?? ''}_${
                                video?.to?.replaceAll(':', '-') ?? ''
                              }`}
                            />
                          </>
                        ) : (
                          <div
                            className="thumbnail-wrapper"
                            style={{
                              position: 'relative',
                              width: '100%',
                              height: '100%',
                              cursor: 'pointer',
                            }}
                            onClick={() => {
                              setVideoLoading({
                                ...video,
                                loading: true,
                              });
                            }}
                          >
                            <img
                              src={
                                PlaceHolderThumbnail ||
                                video?.thumbnail ||
                                Thumbnail
                              }
                              alt="thumbnail"
                              style={{
                                width: '100%',
                                height: '100%',
                                objectFit: 'cover',
                                display: 'block',
                              }}
                            />
                            {!(
                              videoLoading?.recordId === video?.recordId &&
                              videoLoading?.loading
                            ) && (
                              <img
                                className="icon-play"
                                src={IconPlayButton}
                                alt="play-button"
                                style={{
                                  position: 'absolute',
                                  top: '50%',
                                  left: '50%',
                                  transform: 'translate(-50%, -50%)',
                                }}
                              />
                            )}
                            {videoLoading?.recordId === video?.recordId &&
                              videoLoading?.loading && (
                                <div
                                  style={{
                                    position: 'absolute',
                                    top: '50%',
                                    left: '50%',
                                    transform: 'translate(-50%, -50%)',
                                  }}
                                >
                                  <Spinner />
                                </div>
                              )}
                          </div>
                        )}
                      </div>

                      <div className="description">
                        <div className="flex gap-3 items-center justify-start">
                          <Checkbox
                            onChange={(e) =>
                              onChangeSelectDownload(e.target.checked, video)
                            }
                            disabled={
                              downLoading &&
                              downloadVideos?.some(
                                (v) => v?.recordId === video?.recordId,
                              )
                            }
                            checked={downloadVideos?.some(
                              (v) => v?.recordId === video?.recordId,
                            )}
                          />
                          <div className="des">{`${video.from} - ${video.to}`}</div>
                        </div>
                        <div style={{ display: 'flex' }}>
                          <div style={{ marginRight: 10, marginLeft: 10 }}>
                            {video.tags && (
                              <Tag style={{ margin: 3 }}>
                                <>
                                  {video.tags.split(';')[0].slice(0, 20)}{' '}
                                  {(video.tags.split(';').length > 1 ||
                                    video.tags.split(';')[0].length > 20) && (
                                    <span>...</span>
                                  )}
                                </>
                              </Tag>
                            )}
                          </div>
                          <Popover
                            trigger="click"
                            placement="topRight"
                            content={
                              <VideoInformation
                                video={video}
                                onUpdateVideoTagsSuccess={() =>
                                  getListStorage(serial, dateRecord)
                                }
                                dataSelectSource={dataSelectSource}
                                setDataSelectSource={setDataSelectSource}
                              />
                            }
                            title={t('Video information')}
                          >
                            <Tooltip title={t('Video information')}>
                              <div className="icon-question">
                                <img src={IconExclamation} alt="question" />
                              </div>
                            </Tooltip>
                          </Popover>
                        </div>
                      </div>
                    </div>
                  </Col>
                ))}
              </Row>
            )
          ) : (
            <div className="empty-video">
              <Empty
                image={NoDataIcon}
                imageStyle={{
                  height: 100,
                }}
                description={<span>{t('No data!')}</span>}
              />
            </div>
          )
        ) : (
          <Spinner />
        )}
      </div>
    </div>
  );
};

export default BackupStorageVideoComponent;
