import React, { useState, useEffect, useRef } from 'react';
import { Card, Row, Col, Button, Empty, Badge, Select, Tooltip, Popconfirm, Modal, Switch } from 'antd';
import {
  CloseOutlined,
  SettingOutlined
} from '@ant-design/icons';
import { GridFocusIcon } from '@/icons/GridFocus';
import { Grid2x2Icon } from '@/icons/Grid2x2';
import { Grid3x3Icon } from '@/icons/Grid3x3';
import { Grid4x4Icon } from '@/icons/Grid4x4';
import { Grid5x5Icon } from '@/icons/Grid5x5';
import { Grid6x6Icon } from '@/icons/Grid6x6';
import broadcastService from '../../../services/broadcastService';
import './index.scss';
import NodataIcon from '../../../assets/icons/no-data-icon-v2.svg';
import { useTranslation } from 'react-i18next';


export const WindowControlMode = ({ namespace }) => {
  const [activeWindows, setActiveWindows] = useState({});
  const [activeSettingWindowId, setActiveSettingWindowId] = useState(null);
  const lastSeenRef = useRef({});
  const activeGlowWindowIdRef = useRef(null);
  const glowTimerRef = useRef(null);
  const { t } = useTranslation();

  // Create a ref for activeSettingWindowId to be accessible synchronously inside triggerGlow
  const activeSettingWindowIdRef = useRef(null);

  useEffect(() => {
    // 1. Request status update from all child windows immediately
    broadcastService.publish('REQUEST_STATUS', 'ALL');

    // 2. Subscribe to BroadcastChannel messages
    const unsubscribe = broadcastService.subscribe((message) => {
      if (message.type === 'WINDOW_HEARTBEAT') {
        const { windowId, groupId, groupName, gridMode, autoSwitch, autoPlay } = message.payload;

        // Update the timestamp in Ref (does not trigger re-render!)
        lastSeenRef.current[windowId] = Date.now();

        // Only update state if there is a real state change to prevent re-renders
        setActiveWindows((prev) => {
          const current = prev[windowId];
          const isGridChanged = !current || current.gridMode?.size !== gridMode?.size;
          const isSwitchChanged = !current || current.autoSwitch !== autoSwitch;
          const isPlayChanged = !current || current.autoPlay !== autoPlay;
          const isNameChanged = !current || current.groupName !== groupName;

          if (isGridChanged || isSwitchChanged || isPlayChanged || isNameChanged) {
            return {
              ...prev,
              [windowId]: {
                windowId,
                groupId,
                groupName,
                gridMode,
                autoSwitch,
                autoPlay,
              },
            };
          }
          return prev;
        });
      } else if (message.type === 'WINDOW_UNREGISTER') {
        const { windowId } = message.payload;
        delete lastSeenRef.current[windowId];

        // Safety check: close modal if current setting window is unregistered
        if (activeSettingWindowIdRef.current === windowId) {
          activeSettingWindowIdRef.current = null;
          setActiveSettingWindowId(null);
        }

        if (activeGlowWindowIdRef.current === windowId) {
          activeGlowWindowIdRef.current = null;
        }

        setActiveWindows((prev) => {
          if (prev[windowId]) {
            const updated = { ...prev };
            delete updated[windowId];
            return updated;
          }
          return prev;
        });
      }
    });

    // 3. Heartbeat expiry scanner (clear window if no response in 8 seconds)
    const expiryScanner = setInterval(() => {
      const now = Date.now();
      setActiveWindows((prev) => {
        let changed = false;
        const updated = { ...prev };
        Object.keys(updated).forEach((id) => {
          const lastSeen = lastSeenRef.current[id] || 0;
          if (now - lastSeen > 8000) {
            delete updated[id];
            delete lastSeenRef.current[id];
            changed = true;
          }
        });
        return changed ? updated : prev;
      });
    }, 4000);

    return () => {
      unsubscribe();
      clearInterval(expiryScanner);
      if (glowTimerRef.current) {
        clearTimeout(glowTimerRef.current);
      }
    };
  }, []);

  const triggerGlow = (windowId, active) => {
    // If setting modal is active for a different window, keep that window glowing and ignore others
    if (activeSettingWindowIdRef.current && windowId !== activeSettingWindowIdRef.current) {
      return;
    }

    // If setting modal is active for this window, do NOT turn off its glow on hover out
    if (!active && activeSettingWindowIdRef.current === windowId) {
      return;
    }

    if (active) {
      if (activeGlowWindowIdRef.current === windowId) return;

      // Turn off previous glowing window first
      if (activeGlowWindowIdRef.current) {
        broadcastService.publish('HIGHLIGHT_WINDOW', activeGlowWindowIdRef.current, { active: false });
      }

      activeGlowWindowIdRef.current = windowId;
      broadcastService.publish('HIGHLIGHT_WINDOW', windowId, { active: true });
    } else {
      if (activeGlowWindowIdRef.current === windowId) {
        activeGlowWindowIdRef.current = null;
        broadcastService.publish('HIGHLIGHT_WINDOW', windowId, { active: false });
      }
    }
  };

  const handleMouseEnter = (windowId) => {
    if (glowTimerRef.current) {
      clearTimeout(glowTimerRef.current);
    }
    glowTimerRef.current = setTimeout(() => {
      triggerGlow(windowId, true);
    }, 60);
  };

  const handleMouseLeave = (windowId) => {
    if (glowTimerRef.current) {
      clearTimeout(glowTimerRef.current);
    }
    glowTimerRef.current = setTimeout(() => {
      triggerGlow(windowId, false);
    }, 60);
  };

  const handleCloseSettingModal = (windowId) => {
    activeSettingWindowIdRef.current = null;
    triggerGlow(windowId, false);
    setActiveSettingWindowId(null);
  };

  const changeGridMode = (windowId, size) => {
    let grid = [3, 3];
    let quality = 'THREE';
    if (size === 4) { grid = [2, 2]; quality = 'THREE'; }
    else if (size === 9) { grid = [3, 3]; quality = 'THREE'; }
    else if (size === 16) { grid = [4, 4]; quality = 'TWO'; }
    else if (size === 25) { grid = [5, 5]; quality = 'ONE'; }
    else if (size === 36) { grid = [6, 6]; quality = 'ONE'; }

    // Send native broadcast
    broadcastService.publish('CHANGE_GRID_MODE', windowId, { size, grid, quality });

    // Update parent state immediately for instant feedback
    setActiveWindows((prev) => {
      if (prev[windowId]) {
        return {
          ...prev,
          [windowId]: {
            ...prev[windowId],
            gridMode: { size, grid },
          },
        };
      }
      return prev;
    });
  };

  const changeAutoSwitch = (windowId, seconds) => {
    broadcastService.publish('CHANGE_AUTO_SWITCH', windowId, { seconds });

    setActiveWindows((prev) => {
      if (prev[windowId]) {
        return {
          ...prev,
          [windowId]: {
            ...prev[windowId],
            autoSwitch: seconds,
          },
        };
      }
      return prev;
    });
  };

  const changeAutoPlay = (windowId, autoPlay) => {
    broadcastService.publish('CHANGE_AUTO_PLAY', windowId, { autoPlay });

    setActiveWindows((prev) => {
      if (prev[windowId]) {
        return {
          ...prev,
          [windowId]: {
            ...prev[windowId],
            autoPlay,
          },
        };
      }
      return prev;
    });
  };

  const closeWindow = (windowId) => {
    // 1. Send close command to child window
    broadcastService.publish('CLOSE_WINDOW', windowId);

    // 2. Immediately remove from local state to prevent UI delays
    delete lastSeenRef.current[windowId];
    setActiveWindows((prev) => {
      if (prev[windowId]) {
        const updated = { ...prev };
        delete updated[windowId];
        return updated;
      }
      return prev;
    });
  };

  const renderSettingModal = () => {
    if (!activeSettingWindowId) return null;
    const win = activeWindows[activeSettingWindowId];
    if (!win) return null;

    const currentGridSize = win.gridMode?.size || 9;

    return (
      <Modal
        visible={!!activeSettingWindowId}
        title={
          <div className="modal-title-section">
            <SettingOutlined style={{ marginRight: 8, color: '#1890ff' }} />
            <span>Group Settings: {win.groupName}</span>
          </div>
        }
        footer={null}
        onCancel={() => handleCloseSettingModal(win.windowId)}
        width={520}
        centered
        className="window-setting-modal"
      >
        <div className="modal-setting-content">
          <div className="setting-row">
            <span className="setting-label">Grid Mode:</span>
            <span className="setting-value">
              <div className="grid-modes-wrapper">
                <Tooltip title="Focus Mode">
                  <div
                    className={`grid-mode-btn ${currentGridSize === 6 ? 'active' : ''}`}
                    onClick={() => changeGridMode(win.windowId, 6)}
                  >
                    <GridFocusIcon />
                  </div>
                </Tooltip>
                <Tooltip title="Grid 2x2">
                  <div
                    className={`grid-mode-btn ${currentGridSize === 4 ? 'active' : ''}`}
                    onClick={() => changeGridMode(win.windowId, 4)}
                  >
                    <Grid2x2Icon />
                  </div>
                </Tooltip>
                <Tooltip title="Grid 3x3">
                  <div
                    className={`grid-mode-btn ${currentGridSize === 9 ? 'active' : ''}`}
                    onClick={() => changeGridMode(win.windowId, 9)}
                  >
                    <Grid3x3Icon />
                  </div>
                </Tooltip>
                <Tooltip title="Grid 4x4">
                  <div
                    className={`grid-mode-btn ${currentGridSize === 16 ? 'active' : ''}`}
                    onClick={() => changeGridMode(win.windowId, 16)}
                  >
                    <Grid4x4Icon />
                  </div>
                </Tooltip>
                <Tooltip title="Grid 5x5">
                  <div
                    className={`grid-mode-btn ${currentGridSize === 25 ? 'active' : ''}`}
                    onClick={() => changeGridMode(win.windowId, 25)}
                  >
                    <Grid5x5Icon />
                  </div>
                </Tooltip>
                <Tooltip title="Grid 6x6">
                  <div
                    className={`grid-mode-btn ${currentGridSize === 36 ? 'active' : ''}`}
                    onClick={() => changeGridMode(win.windowId, 36)}
                  >
                    <Grid6x6Icon />
                  </div>
                </Tooltip>
              </div>
            </span>
          </div>
          <div className="setting-row">
            <span className="setting-label">Auto Switch:</span>
            <span className="setting-value">
              <Select
                value={win.autoSwitch || 0}
                style={{ width: 220 }}
                onChange={(value) => changeAutoSwitch(win.windowId, value)}
              >
                <Select.Option value={0}>Off</Select.Option>
                <Select.Option value={120}>2 minutes</Select.Option>
                <Select.Option value={300}>5 minutes</Select.Option>
                <Select.Option value={600}>10 minutes</Select.Option>
                <Select.Option value={1800}>30 minutes</Select.Option>
              </Select>
            </span>
          </div>
          <div className="setting-row">
            <span className="setting-label">Auto Play:</span>
            <span className="setting-value">
              <Switch
                checked={win.autoPlay === 'on'}
                onChange={(checked) => changeAutoPlay(win.windowId, checked ? 'on' : 'off')}
              />
            </span>
          </div>
        </div>
      </Modal>
    );
  };

  const activeWindowsArray = Object.values(activeWindows);

  return (
    <div className="window-control-mode">
      <div className="control-content">
        {activeWindowsArray.length === 0 ? (
          <Empty
            className="empty-windows"
            image={NodataIcon}
            imageStyle={{
              height: 60,
            }}
            description={
              <span className="text-brand">
                {t('No data')}
              </span>
            }
          />

        ) : (
          <Row gutter={[16, 16]}>
            {activeWindowsArray.map((win) => (
              <Col
                xs={24}
                sm={12}
                md={8}
                lg={6}
                key={win.windowId}
                onMouseEnter={() => handleMouseEnter(win.windowId)}
                onMouseLeave={() => handleMouseLeave(win.windowId)}
              >
                <Card
                  className="window-card"
                  bodyStyle={{ display: 'none' }}
                  title={
                    <Tooltip title={win.groupName}>
                      <div className="card-title-section">
                        <Badge status="processing" text={win.groupName} />
                      </div>
                    </Tooltip>
                  }
                  extra={
                    <div className="card-actions">
                      <Button
                        type="text"
                        icon={<SettingOutlined />}
                        className="action-btn"
                        onClick={() => {
                          // Clear hover timer
                          if (glowTimerRef.current) {
                            clearTimeout(glowTimerRef.current);
                          }

                          // Focus and unminimize native window by sending a command to it
                          broadcastService.publish('FOCUS_WINDOW', win.windowId);

                          // Glow immediately
                          activeSettingWindowIdRef.current = win.windowId;
                          triggerGlow(win.windowId, true);
                          setActiveSettingWindowId(win.windowId);
                        }}
                      />
                      <Popconfirm
                        title="Bạn có chắc chắn muốn đóng cửa sổ này?"
                        onConfirm={() => closeWindow(win.windowId)}
                        okText="Đòng ý"
                        cancelText="Hủy"
                        placement="bottomRight"
                      >
                        <Button
                          type="text"
                          icon={<CloseOutlined />}
                          className="action-btn close-btn"
                        />
                      </Popconfirm>
                    </div>
                  }
                />
              </Col>
            ))}
          </Row>
        )}
      </div>
      {renderSettingModal()}
    </div>
  );
};

export default WindowControlMode;
