import React from 'react';
import { Route, Switch } from 'react-router-dom';
import DashboardPage from '../pages/Dashboard';
import LivePage from '../pages/Live';
import ProfilePage from '../pages/Profile';
import GatewayPage from '../pages/Gateway';
import EmptyPage from '../components/EmptyPage';
import ServicePage from '../pages/Service';
import CameraPage from '../pages/Camera';
import SystemPage from '../pages/System';
import ReportPage from '../pages/Report';
import { PlaybackPageV2 } from '@/pages/PlaybackV2';
import { OrganizationV2 } from '@/pages/OrganizationV2';
import SitesPage from '@/pages/Sites';
import CameraPageV2 from '@/pages/CameraV2';

let routes = (
  <Switch>
    <Route exact path="/">
      <DashboardPage />
    </Route>
    <Route exact path="/sites">
      <SitesPage />
    </Route>
    <Route exact path="/live">
      <LivePage />
    </Route>
    <Route exact path="/gateway">
      <GatewayPage />
    </Route>
    <Route exact path="/settings">
      <ProfilePage />
    </Route>
    <Route exact path="/shares">
      <OrganizationV2 />
    </Route>
    <Route exact path="/service">
      <ServicePage />
    </Route>
    <Route exact path="/cameraV1">
      <CameraPage />
    </Route>
    <Route exact path="/camera">
      <CameraPageV2 />
    </Route>
    <Route exact path="/system">
      <SystemPage />
    </Route>
    <Route exact path="/report">
      <ReportPage />
    </Route>
    <Route exact path="/playback">
      <PlaybackPageV2 />
    </Route>
    <Route>
      <EmptyPage />
    </Route>
  </Switch>
);

export default routes;
