import React, { useCallback, useEffect, useMemo, useState } from "react";
import * as SERVICE from '../../constants/service.types'
import { useDispatch, useSelector } from "react-redux";
import { PlusOutlined } from '@ant-design/icons';


import { socketEmitEvent } from "@/redux/actions";
import { Button, Divider, Select } from "antd";
import { useTranslation } from "react-i18next";
import Expand from "react-expand-animated";
import CreateMarkerComponent from "@/pages/Dashboard/CreateMarker";

const { Option } = Select;

export const PlaceSelector = ({ value, onChange }) => {
  const dispatch = useDispatch();
  const { namespace, listPlaceByPage } = useSelector(state => state)
  const { t } = useTranslation()
  const [open, setOpen] = useState(false)

  const getListAtmPlaceByPage = useCallback(
    (page, size, searchName, tag) => {
      let data = {
        appServiceType: SERVICE.LIST_ALL_PLACE_BY_PAGE,
        requestId: new Date().getTime(),
        body: JSON.stringify({
          ...(searchName && { name: searchName }),
          ...(tag && { tag }),
          namespace,
          locationType: 'place-camera',
          timeRequest: new Date().getTime(),
          page: page ?? 0,
          size: size ?? 1000,
        }),
      };
      return dispatch(socketEmitEvent(data));
    },
    [dispatch, namespace]
  );

  useEffect(() => {
    if (namespace) {
      getListAtmPlaceByPage();
    }
  }, [getListAtmPlaceByPage, namespace]);

  const options = useMemo(() => listPlaceByPage?.places || [], [listPlaceByPage])


  return (
    <Select
      className="province-select w-full"
      placeholder={t('Select place')}
      optionFilterProp="children"
      showSearch
      value={value}
      onChange={onChange}
    // dropdownRender={(menu) => (
    //   <>
    //     {menu}
    //     <Divider className="mt-4 mb-2 bg-stroke" />
    //     <div className="w-full flex items-center justify-center">
    //       <Button type="primary" icon={<PlusOutlined />}
    //         onClick={() => setOpen(true)}
    //       >
    //         Add site
    //       </Button>
    //     </div>
    //     <div className="p-4">
    //       <Expand open={open}>
    //         <CreateMarkerComponent onCreateMarker={() => { }} />
    //       </Expand>
    //     </div>
    //   </>
    // )
    // }
    >
      {
        options && options?.map(opt => (
          <Option key={opt?.placeId} value={opt?.placeId}>{t(opt?.name)}</Option>
        ))
      }
    </Select >
  )
}