const CHANNEL_NAME = 'vbee_window_sync';

class BroadcastService {
  constructor() {
    this.senderId = 'unknown';
    if (typeof window !== 'undefined') {
      if ('BroadcastChannel' in window) {
        this.channel = new BroadcastChannel(CHANNEL_NAME);
      } else {
        this.channel = null;
      }
    } else {
      this.channel = null;
    }
  }

  initSenderId() {
    if (this.senderId && this.senderId !== 'unknown' && this.senderId !== 'main') {
      return;
    }
    if (typeof window !== 'undefined') {
      this.senderId = window.name || 'main';
      if (window.__TAURI__?.webviewWindow?.getCurrentWebviewWindow) {
        try {
          const win = window.__TAURI__.webviewWindow.getCurrentWebviewWindow();
          if (win && win.label) {
            this.senderId = win.label;
          }
        } catch (e) {
          console.error('[BroadcastService] Error getting current window:', e);
        }
      }
    }
  }

  // Gửi tin nhắn
  publish(type, targetWindowId, payload = {}) {
    this.initSenderId();
    const data = {
      type,
      targetWindowId, // 'ALL' hoặc một windowId cụ thể
      senderId: this.senderId,
      payload,
      timestamp: Date.now(),
    };

    if (typeof window !== 'undefined' && window.__TAURI__?.event) {
      window.__TAURI__.event.emit(CHANNEL_NAME, data);
      return;
    }

    if (!this.channel) return;
    this.channel.postMessage(data);
  }

  // Đăng ký lắng nghe tin nhắn
  subscribe(callback) {
    this.initSenderId();
    if (typeof window !== 'undefined' && window.__TAURI__?.event) {
      let isUnsubscribed = false;
      let unlistenFn = null;

      window.__TAURI__.event.listen(CHANNEL_NAME, (event) => {
        if (!isUnsubscribed) {
          const message = event.payload;
          // Skip messages sent by this window itself (replicating BroadcastChannel behavior)
          if (message.senderId === this.senderId) {
            return;
          }
          callback(message);
        }
      }).then((unlisten) => {
        if (isUnsubscribed) {
          unlisten();
        } else {
          unlistenFn = unlisten;
        }
      });

      return () => {
        isUnsubscribed = true;
        if (unlistenFn) {
          unlistenFn();
        }
      };
    }

    if (!this.channel) return () => {};

    const listener = (event) => {
      // Replicate self-filtering for BroadcastChannel fallback if needed
      if (event.data && event.data.senderId === this.senderId) {
        return;
      }
      callback(event.data);
    };

    this.channel.addEventListener('message', listener);

    // Trả về hàm unsubscribe
    return () => {
      this.channel.removeEventListener('message', listener);
    };
  }

  close() {
    if (this.channel) {
      this.channel.close();
    }
  }
}

export const broadcastService = new BroadcastService();
export default broadcastService;
