import { isTauri } from '@/configs';
import storageService from '../services/storage.service';
import * as SYSTEM from '../constants/system.keys';

export { isTauri };

const PAKE_MAIN_WINDOW_LABEL = 'pake';

export function getTauriWindowLabel() {
  const hasTauri = typeof window !== 'undefined' && '__TAURI__' in window;
  if (!hasTauri) {
    return null;
  }

  try {
    const tauri = window.__TAURI__;
    if (tauri?.webviewWindow?.getCurrentWebviewWindow) {
      return tauri.webviewWindow.getCurrentWebviewWindow().label ?? null;
    }
    if (tauri?.window?.getCurrentWindow) {
      return tauri.window.getCurrentWindow().label ?? null;
    }
  } catch (error) {
    console.error('[Tauri Helper] getTauriWindowLabel error:', error);
    return null;
  }

  return null;
}

export function isTauriLiveWindow() {
  const hasTauri = typeof window !== 'undefined' && '__TAURI__' in window;
  if (!hasTauri) {
    return false;
  }

  const label = getTauriWindowLabel();
  if (!label || label === PAKE_MAIN_WINDOW_LABEL) {
    return false;
  }

  return label.includes('live');
}

export function openNewLiveWindow(groupId, groupName, options = {}) {
  const { gridSize = 6, autoPlay = 'off', autoSwitch = 0 } = options;
  const token = storageService.getInternalStorageByKey(SYSTEM.DECODED_ACCESS_TOKEN) || '';
  const namespace = localStorage.getItem('namespace') || '';
  const windowId = `live-group-${groupId}`;
  const url = `${window.location.origin}/#/live?groupId=${groupId}&windowId=${windowId}&groupName=${encodeURIComponent(groupName)}&accessToken=${encodeURIComponent(token)}&namespace=${encodeURIComponent(namespace)}&gridSize=${gridSize}&autoPlay=${autoPlay}&autoSwitch=${autoSwitch}`;

  console.log('[Tauri Debug] openNewLiveWindow called:', { groupId, groupName, windowId, url });

  try {
    const hasTauri = typeof window !== 'undefined' && '__TAURI__' in window;
    console.log('[Tauri Debug] hasTauri (dynamic check):', hasTauri);
    
    if (hasTauri) {
      const tauri = window.__TAURI__;
      console.log('[Tauri Debug] window.__TAURI__ keys:', Object.keys(tauri || {}));
      if (tauri?.webviewWindow) {
        console.log('[Tauri Debug] webviewWindow keys:', Object.keys(tauri.webviewWindow));
      }

      // Use Tauri v2 standard dynamic window creation if available
      if (tauri?.webviewWindow?.WebviewWindow) {
        console.log('[Tauri Debug] Creating WebviewWindow via Tauri JS API');
        const win = new tauri.webviewWindow.WebviewWindow(windowId, {
          url: url,
          title: groupName || "Live Camera",
          width: 1000,
          height: 700,
          resizable: true,
          visible: true,
        });
        
        // In Tauri v2, visible: true is set so the window is automatically shown and focused on creation.
        // Calling win.show() and win.setFocus() immediately after new WebviewWindow() is asynchronous
        // and can cause race conditions yielding "window not found" console errors, so we let Tauri handle it.
        return;
      }
      
      // Fallback: Pake intercepts window.open to create a new Tauri window
      console.log('[Tauri Debug] Fallback to window.open');
      window.open(url, windowId, 'width=1000,height=700');
    } else {
      console.log('[Tauri Debug] Not in Tauri, calling window.open _blank');
      window.open(url, '_blank');
    }
  } catch (error) {
    console.error('[Tauri Debug] Failed to open live window:', error);
    try {
      window.open(url, '_blank');
    } catch (_) {}
  }
}

