import { useSocketQuery } from '@/socket/useSocketRequest';
import * as SERVICE from '@/constants/service.types';

export const useGetAccountByNamespace = (namespace) => {
  return useSocketQuery(
    { namespace },
    {
      appServiceType: SERVICE.LIST_ACCOUNT_BY_NAMESPACE,
      disabled: !namespace,
    }
  );
};

export const useListDeviceByUser = ({
  shareUserId,
  namespace,
  page,
  size,
  timeRequest,
}) => {
  return useSocketQuery(
    {
      namespace,
      shareUserId,
      deviceType: 'camera',
      page,
      size,
      timeRequest,
    },
    {
      appServiceType: SERVICE.LIST_DEVICE_BY_USER,
      disabled: !shareUserId || !namespace,
    }
  );
};

export const useListGroupAccountByDeviceGroup = ({
  deviceGroupId,
  namespace,
  page,
  size,
  timeRequest,
}) => {
  return useSocketQuery(
    {
      deviceGroupId,
      namespace,
      page,
      size,
      timeRequest,
    },
    {
      appServiceType: SERVICE.LIST_GROUP_ACCOUNT_BY_DEVICE_GROUP_BY_PAGE,
      disabled: !deviceGroupId || !namespace,
    }
  );
};
