import React, { Fragment, useState } from 'react';
import * as XLSX from 'xlsx';
import { useGetAccountByNamespace } from '@/hooks/socket/member';
import {
  Button,
  Divider,
  Input,
  Modal,
  Switch,
  Table,
  Tag,
  Tooltip,
} from 'antd';
import { useMemo } from 'react';
import { useSelector } from 'react-redux';
import {
  ACCOUNT_STATUS,
  NOTIFIES,
  USER_TYPE_OPTIONS,
} from '@/constants/system.keys';
import colorsDark from '@/assets/colors/dark';
import { EditIcon } from '@/icons/Edit';
import { ExclamationCircleOutlined, KeyOutlined } from '@ant-design/icons';
import { TrashCanIcon } from '@/icons/TrashCan';
import {
  parseResponseBody,
  prepareBody,
  requestSocketPromiseWithTimeout,
} from '@/socket/query';
import * as SERVICE from '@/constants/service.types';
import UpdateMemberComponent from '../Modals/UpdateMember';
import moment from 'moment';
import { useTranslation } from 'react-i18next';
import ChangePasswordComponent from '../Modals/ChangePassword';
import { openMessage } from '@/redux/actions';
import { Header } from './Header';
import { useAdvancedSearch } from './use-advanced-search';
import '../index.scss';

const removeMember = async ({ username, phonenumber, namespace }) => {
  const body = {
    username,
    phonenumber,
    namespace,
  };

  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.REMOVE_MEMBER,
    body: prepareBody(body),
  });

  return parseResponseBody(response);
};

const updateMember = async ({ namespace, username, ...rest }) => {
  const body = {
    namespace,
    username,
    ...rest,
  };
  console.log("🚀 ~ updateMember ~ body:", body)

  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.UPDATE_MEMBER,
    body: prepareBody(body),
  });

  console.log("🚀 ~ updateMember ~ response:", response)
  return parseResponseBody(response);
};

const updateMemberConfig = async ({ liveTimeout, accountId, namespace }) => {
  const body = {
    namespace,
    accountId,
    liveTimeout,
  };

  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.CONFIGURATION_USER,
    body: prepareBody(body),
  });

  return parseResponseBody(response);
};

const resetPassword = async ({ accountId, newPassword, namespace }) => {
  const body = {
    accountId,
    newPassword,
    namespace,
  };

  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.RESET_USER_PASSWORD,
    body: prepareBody(body),
  });

  return parseResponseBody(response);
};

const memberRoleColors = (roleName) => {
  switch (roleName) {
    case 'admin':
      return colorsDark.$brandHex;
    default:
      return colorsDark.$offline;
  }
};

export const MemberV2 = () => {
  const namespace = useSelector((state) => state.namespace);
  const userId = useSelector((state) => state.userId);
  const dataUser = useSelector((state) => state.dataUser);
  const { t } = useTranslation();

  const {
    data: accountByNamespace,
    isLoading: isLoadingAccountByNamespace,
    send: refetch,
    patch: patchAccountByNamespace,
  } = useGetAccountByNamespace(namespace);

  const refetchAccountByNamespace = () => {
    refetch({
      namespace,
    });
  };

  const isAdmin = useMemo(() => {
    if (
      accountByNamespace?.find((account) => account.id === userId)?.role ===
      'admin'
    ) {
      return true;
    }

    return (
      dataUser?.role === 'admin' ||
      (dataUser?.role === 'member' && dataUser?.detailRole === 'operator')
    );
  }, [accountByNamespace, userId, dataUser]);

  const dataSource = useMemo(() => {
    console.log("🚀 ~ MemberV2 ~ accountByNamespace:", accountByNamespace)
    return accountByNamespace?.map((account) => ({
      ...account,
      key: account.accountId,
    }));
  }, [accountByNamespace]);

  const onToggleWatermark = (record, enabled) => {
    console.log('record', record, enabled);
    updateMember({
      namespace,
      username: record.username,
      enableWatermark: enabled ? 1 : 0,
    }).then(() => {
      refetchAccountByNamespace();
    });
  };

  const onToggleActiveStatus = (record, enabled) => {
    console.log('record', record, enabled);
    updateMember({
      namespace,
      username: record.username,
      accountStatus: enabled ? ACCOUNT_STATUS.ACTIVE : ACCOUNT_STATUS.BLOCKED,
    }).then(() => {
      refetchAccountByNamespace();
    });
  };

  const onUpdateMember = (requestId, values) => {
    const {
      phonenumber,
      namespace,
      fullName,
      email,
      role,
      detailRoles,
      position,
      accountId,
      liveTimeout,
      username,
      password,
      authMethod,
      enableWatermark,
      accountStatus,
      expireTime,
      externalUserId,
    } = values;

    let data = {
      phonenumber,
      namespace,
      fullName,
      email,
      role,
      detailRoles:
        (Array.isArray(detailRoles) ? detailRoles?.join(';') : detailRoles) ||
        '',
      position: position || '',
      username,
      password,
      authMethod,
      expireTime: expireTime ? expireTime.format('YYYY-MM-DD HH:mm:ss') : '',
      enableWatermark: enableWatermark ? 1 : 0,
      accountStatus: accountStatus
        ? ACCOUNT_STATUS.ACTIVE
        : ACCOUNT_STATUS.BLOCKED,
      externalUserId: externalUserId || '',
    };

    setVisibleEditMember(null);

    if (liveTimeout) {
      const dataObjConfig = {
        liveTimeout:
          moment(liveTimeout)?.hours() * 3600 +
          moment(liveTimeout)?.minutes() * 60,
        accountId,
        namespace,
      };

      Promise.allSettled([
        updateMember(data),
        updateMemberConfig(dataObjConfig),
      ]).then(() => {
        openMessage(NOTIFIES.SUCCESS, t('Member updated successfully'));
        refetchAccountByNamespace();
      }).catch(() => {
        openMessage(NOTIFIES.ERROR, t('Update member failed'));
      });

      return;
    }

    updateMember(data).then(() => {
      openMessage(NOTIFIES.SUCCESS, t('Member updated successfully'));
      refetchAccountByNamespace();
    }).catch(() => {
      openMessage(NOTIFIES.ERROR, t('Update member failed'));
    });
  };

  const onResetPasswordMember = (requestId, values) => {
    const { accountId, newPassword, namespace } = values;
    setVisibleChangePassword(null);

    resetPassword({ accountId, newPassword, namespace }).then(
      () => {
        openMessage(NOTIFIES.SUCCESS, t('Reset password successfully'));
      },
      () => {
        openMessage(NOTIFIES.ERROR, t('Reset password failed'));
      }
    );
  };

  const [visibleEditMember, setVisibleEditMember] = useState(null);
  const [visibleChangePassword, setVisibleChangePassword] = useState(null);

  const onRemoveMember = (record) => {
    Modal.confirm({
      title: `${t('Remove member with phone number as')} ${record.phonenumber
        }?`,
      icon: <ExclamationCircleOutlined />,
      okText: t('Remove'),
      onOk() {
        return removeMember({
          username: record.username,
          phonenumber: record.phonenumber,
          namespace,
        }).then(
          () => {
            openMessage(NOTIFIES.SUCCESS, t('Member removed successfully'));
            refetchAccountByNamespace();
          },
          () => {
            openMessage(NOTIFIES.ERROR, t('Remove member failed'));
          }
        );
      },
      onCancel() { },
    });
  };

  const onSearchMember = (value) => {
    console.log('value', value);
  };

  const {
    searchResult,
    isLoading: isSearchLoading,
    handleSearch,
    reSearch,
    isSearchActive,
  } = useAdvancedSearch({
    namespace,
  });

  const searchDataSource = useMemo(() => {
    return searchResult?.map((item) => ({
      ...item,
      key: item.accountId,
    }));
  }, [searchResult]);

  if (!isAdmin) {
    return null;
  }

  return (
    <div>
      <Header
        namespace={namespace}
        refetchAccountByNamespace={refetchAccountByNamespace}
        updateMemberConfig={updateMemberConfig}
        onSearchMember={handleSearch}
      />

      <Modal
        visible={visibleEditMember}
        width="620px"
        title={'Edit member'}
        onCancel={() => setVisibleEditMember(null)}
        footer={null}
      >
        {visibleEditMember && (
          <UpdateMemberComponent
            namespace={namespace}
            onUpdate={onUpdateMember}
            data={visibleEditMember}
          />
        )}
      </Modal>
      <Modal
        visible={visibleChangePassword}
        title={`${t('Change password for')}: ${visibleChangePassword?.fullName
          }`}
        onCancel={() => setVisibleChangePassword(null)}
        footer={null}
      >
        {visibleChangePassword && (
          <ChangePasswordComponent
            namespace={namespace}
            onUpdate={onResetPasswordMember}
            onDone={console.log}
            data={visibleChangePassword}
          />
        )}
      </Modal>
      <Table
        className='members-table'
        loading={isSearchActive ? isSearchLoading : isLoadingAccountByNamespace}
        dataSource={isSearchActive ? searchDataSource : dataSource}
        expandable={{
          expandedRowRender: (record) => {
            const { sessions } = record;
            return (
              <Fragment>
                {sessions.map((session, index) => (
                  <div className="session" key={index}>
                    <p>
                      <span>Client IP: </span>
                      {session.clientIp}
                    </p>
                    <p>
                      <span>Device: </span>
                      {session.deviceInfo}
                    </p>
                    <p>
                      <span>Online at: </span>
                      {session.onlineAt}
                    </p>
                    <Divider />
                  </div>
                ))}
              </Fragment>
            );
          },
          rowExpandable: (record) => record?.sessions?.length,
        }}
        columns={[
          {
            title: 'Full Name',
            dataIndex: 'fullName',
            key: 'fullName',
            width: 150,
          },
          {
            title: 'Phone',
            dataIndex: 'phonenumber',
            key: 'phoneNumber',
            render: (cell) => cell || '-',
          },
          {
            title: 'Email',
            dataIndex: 'email',
            key: 'email',
            render: (emails) => emails?.split(';')?.join('; ') ?? '-',
          },
          {
            title: 'Position',
            dataIndex: 'position',
            key: 'position',
            render: (cell) => (
              <Tooltip title={cell || '-'}>
                <span>{cell || '-'}</span>
              </Tooltip>
            ),
            width: 50,
          },
          {
            title: 'External ID',
            dataIndex: 'externalUserId',
            key: 'externalUserId',
            width: 50,
            render: (value) => value || '-',
          },
          {
            title: 'User Type',
            dataIndex: 'role',
            key: 'role',
            width: 120,
            render: (tags) => (
              <Tag color={memberRoleColors(tags)} className="m-0">
                {USER_TYPE_OPTIONS.find(
                  (item) => item.value === tags
                )?.label?.toUpperCase()}
              </Tag>
            ),
          },
          {
            title: 'Role',
            key: 'role',
            dataIndex: 'role',
            width: 100,
            render: (text) => (
              <>
                {text &&
                  text?.split(';')?.map((item, index) =>
                    item?.trim() ? (
                      <Tag
                        key={index}
                        color={colorsDark.$brandHex}
                        style={{
                          fontSize: '10px',
                          marginRight: '5px',
                          marginBottom: '2px',
                        }}
                      >
                        {item?.replaceAll('-', ' ')?.toUpperCase() || ''}
                      </Tag>
                    ) : null
                  )}
              </>
            ),
          },
          {
            title: 'Watermark',
            dataIndex: 'enableWatermark',
            key: 'watermark',
            width: 100,
            render: (_, record) => {
              const detailRolesArr = record.detailRoles?.split(';') || [];
              const isAdminDetailRole = detailRolesArr.some(
                (item) => item.split('-')?.[0] === 'admin'
              );
              const isRecordAdmin =
                record.role === 'admin' && isAdminDetailRole;

              return (
                <div>
                  {(isAdmin || record.accountId === userId) &&
                    !isRecordAdmin && (
                      <Tooltip
                        title={record?.enableWatermark ? 'Enabled' : 'Disabled'}
                      >
                        <Switch
                          checked={record?.enableWatermark}
                          onChange={(checked) =>
                            onToggleWatermark(record, checked)
                          }
                        />
                      </Tooltip>
                    )}
                </div>
              );
            },
          },
          {
            title: 'Active status',
            key: 'account_status',
            render: (record) => {
              const detailRolesArr = record.detailRoles?.split(';') || [];
              const isAdminDetailRole = detailRolesArr.some(
                (item) => item.split('-')?.[0] === 'admin'
              );
              const isRecordAdmin =
                record.role === 'admin' && isAdminDetailRole;
              return (
                <div>
                  {(isAdmin || record.accountId === userId) &&
                    !isRecordAdmin && (
                      <Tooltip
                        title={
                          record?.accountStatus === ACCOUNT_STATUS.ACTIVE
                            ? 'Available'
                            : 'Blocked'
                        }
                      >
                        <Switch
                          checked={
                            record?.accountStatus === ACCOUNT_STATUS.ACTIVE
                          }
                          onChange={(checked) =>
                            onToggleActiveStatus(record, checked)
                          }
                        />
                      </Tooltip>
                    )}
                </div>
              );
            },
          },
          {
            title: 'Expire time',
            key: 'expire_time',
            dataIndex: 'expireTime',
          },

          {
            title: 'Action',
            key: 'actions ',
            render: (record) => {
              const detailRolesArr = record.detailRoles?.split(';') || [];
              const isAdminDetailRole = detailRolesArr.some(
                (item) => item.split('-')?.[0] === 'admin'
              );
              const isRecordAdmin =
                record.role === 'admin' && isAdminDetailRole;

              return (
                <div className="manager-member-actions">
                  {(isAdmin || record.accountId === userId) &&
                    !isRecordAdmin && (
                      <Tooltip title={'Edit'}>
                        <div
                          className="edit-button"
                          onClick={() => setVisibleEditMember(record)}
                        >
                          <EditIcon />
                        </div>
                      </Tooltip>
                    )}

                  {isAdmin && !isRecordAdmin && (
                    <Tooltip title={'Change password'}>
                      <div
                        className="edit-button"
                        onClick={() => setVisibleChangePassword(record)}
                      >
                        <KeyOutlined />
                      </div>
                    </Tooltip>
                  )}
                  {isAdmin && !isRecordAdmin && (
                    <Tooltip title={'Remove'}>
                      <div
                        className="edit-button error"
                        onClick={() => onRemoveMember(record)}
                        disabled={record.role === 'admin'}
                      >
                        <TrashCanIcon />
                      </div>
                    </Tooltip>
                  )}
                </div>
              );
            },
          },
        ]}
      />
    </div>
  );
};
