import React, { useEffect, useMemo, useRef, useState } from 'react';

import {
  MinusCircleFilled,
  PlusCircleFilled,
  UserAddOutlined,
} from '@ant-design/icons';

import { TrashCanIcon } from '@/icons/TrashCan';
import { EditIcon } from '@/icons/Edit';
import { AddFolderIcon } from '@/icons/AddFolder';
import { If } from '@/components/If';

import {
  GroupNodeHeader,
  GroupNodeHeaderLeft,
  GroupNodeWrapper,
  DeviceNodeAction,
  DeviceNodeActions,
  DeviceNodeIcon,
  DeviceNodeName,
  DeviceNodeWrapper,
  GroupNodeHeaderAction,
  GroupNodeHeaderActions,
  GroupNodeHeaderIcon,
  GroupNodeHeaderName,
  GroupChildrenLoading,
  GroupNodeContent,
  NodeActionItem,
  NodeActionItems,
  NodeActionPopover,
} from '@/components/Tree/Composable';
import { MoreIcon } from '@/icons/More';

import { ProfileIcon } from '@/icons/Profile';
import {
  useGetAccountByNamespace,
  useAddMemberToGroup,
  useAddUserGroup,
  useUpdateUserGroup,
} from '@/hooks/socket/member';

import './styles.scss';
import { Button, Select } from 'antd';

const defaultAllowActions = {
  remove: true,
  addSubgroup: true,
  addUser: true,
  editName: true,
};

const noop = () => {};

export const GroupNode = ({
  id,
  namespace,
  level = 0,
  isExpanded = false,
  onExpand = noop,
  isRenaming = false,
  onRename = noop,
  isLoading = false,
  children,
  isCreating = false,
  onCreatingChange = noop,
  onAddUser = noop,
  onAddUserSuccess = noop,
  onAddGroup = noop,
  onRemoveGroup = noop,
  name,
  actions: actionsProp = defaultAllowActions,
  onRenameSuccess = noop,
  onAddGroupSuccess = noop,
  tooltip,
  isAddingUser,
  groupMembersIds,
  isEmpty,
}) => {
  const isRoot = level === 0;
  const actions = { ...defaultAllowActions, ...actionsProp };

  const renderChildren = () => {
    if (!isExpanded) {
      return null;
    }

    return (
      <GroupNodeContent>
        {isCreating && (
          <CreateGroup
            parentGroupId={id}
            namespace={namespace}
            level={level + 1}
            onCancel={() => onCreatingChange?.(false)}
            onSuccess={(newGroup) =>
              onAddGroupSuccess?.(newGroup, { id, name })
            }
          />
        )}
        {isAddingUser && (
          <AddUser
            groupMembersIds={groupMembersIds}
            namespace={namespace}
            groupId={id}
            onSuccess={onAddUserSuccess}
            onCancel={() => onAddUser?.(false)}
          />
        )}
        {children}
        {isLoading && <GroupChildrenLoading />}
      </GroupNodeContent>
    );
  };

  const onAction = (action) => {
    switch (action) {
      case 'addSubgroup':
        onAddGroup();
        break;
      case 'addUser':
        onAddUser(true);
        break;
      case 'editName':
        onRename(true);
        break;
      case 'remove':
        onRemoveGroup();
        break;
      default:
        break;
    }
  };

  return (
    <GroupNodeWrapper level={level} isExpanded={isExpanded} isRoot={isRoot}>
      <GroupNodeHeader>
        <GroupNodeHeaderLeft>
          <GroupNodeHeaderIcon
            onClick={() => {
              onExpand(!isExpanded);
            }}
          >
            {isExpanded ? <MinusCircleFilled /> : <PlusCircleFilled />}
          </GroupNodeHeaderIcon>
          {isRenaming ? (
            <EditName
              defaultName={name}
              onCancel={() => onRename?.(false)}
              groupId={id}
              namespace={namespace}
              onSuccess={onRenameSuccess}
            />
          ) : (
            <GroupNodeHeaderName tooltip={tooltip}>{name}</GroupNodeHeaderName>
          )}
        </GroupNodeHeaderLeft>
        <GroupNodeHeaderActions>
          <GroupNodeMore actions={actions} onAction={onAction} />
        </GroupNodeHeaderActions>
      </GroupNodeHeader>
      {renderChildren()}
    </GroupNodeWrapper>
  );
};

export const GroupNodeMore = ({ actions, onAction }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  const isEmpty = !(
    actions.addUser ||
    actions.addSubgroup ||
    actions.editName ||
    actions.remove
  );

  const hide = () => {
    setOpen(false);
  };

  const emitAction = (action) => {
    hide();
    onAction(action);
  };

  if (isEmpty) {
    return null;
  }

  const content = () => {
    return (
      <NodeActionItems>
        <If condition={actions.addSubgroup}>
          <NodeActionItem
            icon={<AddFolderIcon />}
            onClick={() => emitAction('addSubgroup')}
            label="Add group"
          />
        </If>
        <If condition={actions.editName}>
          <NodeActionItem
            icon={<EditIcon />}
            onClick={() => emitAction('editName')}
            label="Edit"
          />
        </If>
        <If condition={actions.addUser}>
          <NodeActionItem
            icon={<UserAddOutlined />}
            onClick={() => emitAction('addUser')}
            label="Add members"
          />
        </If>
        <If condition={actions.remove}>
          <NodeActionItem
            danger
            icon={<TrashCanIcon />}
            onClick={() => emitAction('remove')}
            label="Remove group"
          />
        </If>
      </NodeActionItems>
    );
  };

  return (
    <NodeActionPopover
      trigger="click"
      visible={open}
      onVisibleChange={setOpen}
      content={content()}
      placement="rightTop"
    >
      <GroupNodeHeaderAction ref={ref} className={open ? 'active' : ''}>
        <MoreIcon />
      </GroupNodeHeaderAction>
    </NodeActionPopover>
  );
};

/**
 * Use to replace GroupNodeHeaderName
 */
export const EditableName = ({
  defaultName,
  onCancel,
  isLoading,
  onBlur,
  onSubmit,
}) => {
  const ref = useRef(null);

  const onKeyDown = (e) => {
    if (e.key === 'Enter') {
      const name = (ref.current?.value || '').trim();

      if (name.trim() === '' || name === defaultName) {
        onCancel();

        return;
      }

      onSubmit(name);
    }
  };

  useEffect(() => {
    ref.current.focus();
  }, []);

  return (
    <GroupNodeHeaderName className="group-node-header-name-input">
      <input
        ref={ref}
        readOnly={isLoading}
        onBlur={onBlur}
        onKeyDown={onKeyDown}
        autoFocus
        className=""
        defaultValue={defaultName}
        placeholder="Group name"
      />
      <Button
        loading={isLoading}
        size="small"
        type="primary"
        onClick={() => onSubmit(ref.current.value || '')}
      >
        Save
      </Button>
      <Button loading={isLoading} size="small" onClick={onCancel}>
        Cancel
      </Button>
    </GroupNodeHeaderName>
  );
};

export const CreateGroup = ({
  onCancel,
  namespace,
  level,
  parentGroupId,
  onSuccess,
}) => {
  const [isLoading, setIsLoading] = useState(false);
  const { send } = useAddUserGroup();

  const createGroup = async (name) => {
    try {
      setIsLoading(true);
      const newGroup = await send({
        namespace,
        parentGroupId: parentGroupId,
        name,
        accountInfos: [],
      });

      setIsLoading(false);
      onSuccess(newGroup);
    } catch (error) {
      setIsLoading(false);
    }
  };

  return (
    <GroupNodeWrapper level={level} isRoot={level === 0}>
      <GroupNodeHeader>
        <GroupNodeHeaderLeft>
          <GroupNodeHeaderIcon>
            <PlusCircleFilled rotate={0} />
          </GroupNodeHeaderIcon>
          <EditableName
            defaultName=""
            onCancel={onCancel}
            isLoading={isLoading}
            onSubmit={createGroup}
          />
        </GroupNodeHeaderLeft>
      </GroupNodeHeader>
    </GroupNodeWrapper>
  );
};

const EditName = ({ defaultName, groupId, namespace, onCancel, onSuccess }) => {
  const { send } = useUpdateUserGroup();
  const [isLoading, setIsLoading] = useState(false);

  const updateName = async (name) => {
    try {
      setIsLoading(true);
      const data = await send({
        namespace,
        groupId,
        name,
      });

      setIsLoading(false);
      onSuccess(data.group.id, data.group.name);
    } catch (error) {
      setIsLoading(false);
    }
  };

  return (
    <EditableName
      defaultName={defaultName}
      onCancel={onCancel}
      isLoading={isLoading}
      onSubmit={updateName}
    />
  );
};

export const MemberNode = ({
  name,
  level = 0,
  onRemove,
  state,
  allowRemove = true,
  onSelect,
  isSelected = false,
  tooltip,
}) => {
  return (
    <DeviceNodeWrapper
      level={level}
      isInactive={(state || 0) === 0}
      isSelected={isSelected}
      tooltip={tooltip}
    >
      <DeviceNodeIcon>
        <ProfileIcon />
      </DeviceNodeIcon>
      <DeviceNodeName onClick={onSelect}>{name}</DeviceNodeName>
      <If condition={allowRemove}>
        <DeviceNodeActions>
          <DeviceNodeAction className="remove-group" onClick={onRemove}>
            <TrashCanIcon />
          </DeviceNodeAction>
        </DeviceNodeActions>
      </If>
    </DeviceNodeWrapper>
  );
};

const AddUser = ({
  groupId,
  namespace,
  onSuccess,
  onCancel,
  groupMembersIds,
}) => {
  const { data: accounts, isLoading: isLoadingAccounts } =
    useGetAccountByNamespace({ namespace });
  const [selectedAccounts, setSelectedAccounts] = useState([]);
  const { mutate: addMemberToGroup } = useAddMemberToGroup();
  const [isLoading, setIsLoading] = useState(false);
  const [open, setOpen] = useState(true);

  const onSave = async () => {
    if (!accounts) {
      return;
    }

    setIsLoading(true);
    try {
      await Promise.all(
        selectedAccounts.map((account) =>
          addMemberToGroup({
            namespace,
            groupId,
            accountId: account,
          })
        )
      );
      onSuccess(
        selectedAccounts.map((accountId) =>
          accounts.find((account) => account.accountId === accountId)
        )
      );
    } catch (error) {
      setIsLoading(false);
    }
    setIsLoading(false);
  };

  const filteredAccounts = useMemo(() => {
    return accounts?.filter(
      (account) => !groupMembersIds?.includes(account.accountId)
    );
  }, [accounts, groupMembersIds]);

  return (
    <div className="add-user-selector-wrapper flex items-center gap-2 px-2">
      <Select
        value={selectedAccounts}
        onChange={setSelectedAccounts}
        className="add-user-selector"
        allowClear
        mode="multiple"
        placeholder="Select members"
        loading={isLoadingAccounts}
        showSearch
        open={open}
        onDropdownVisibleChange={setOpen}
        autoFocus
      >
        {filteredAccounts?.map((account) => (
          <Select.Option key={account.accountId} value={account.accountId}>
            {account.fullName}-{account.phonenumber}-{account.email}
          </Select.Option>
        ))}
      </Select>

      <Button
        loading={isLoading}
        size="small"
        disabled={selectedAccounts.length === 0}
        onClick={onSave}
      >
        Save
      </Button>
      <Button size="small" onClick={onCancel}>
        Cancel
      </Button>
    </div>
  );
};
