import React from 'react';
import { Tabs } from 'antd';
import ScanAddCameraComponent from './ScanAddCamera';
import RTSPlinkAddCameraComponent from './RTSPlinkAddCamera';
import './index.scss';
import { useTranslation } from 'react-i18next';
import MilestoneCameraAddComponent from './MilestoneCameraAdd';
import BodyCameraAddComponent from './BodyCamera';

const { TabPane } = Tabs;
const AddCameraComponent = ({ onDone, gatewaySerial, gatewayAddress, gatewayLocalAddress }) => {
  const { t } = useTranslation();
  return (
    <div className="add-camera-component">
      <Tabs defaultActiveKey="1">
        <TabPane tab={t('Auto Scan Mode')} key="1">
          <ScanAddCameraComponent
            onDone={onDone}
            gatewaySerial={gatewaySerial}
            gatewayAddress={gatewayAddress}
          />
        </TabPane>
        <TabPane tab={t('RTSP Link Mode')} key="2">
          <RTSPlinkAddCameraComponent
            onDone={onDone}
            gatewaySerial={gatewaySerial}
            gatewayAddress={gatewayAddress}
          />
        </TabPane>
        <TabPane tab={t('Milestone')} key="3">
          <MilestoneCameraAddComponent
            onDone={onDone}
            gatewaySerial={gatewaySerial}
            gatewayAddress={gatewayAddress}
          />
        </TabPane>
        <TabPane tab={t('Body camera')} key="4">
          <BodyCameraAddComponent
            onDone={onDone}
            gatewaySerial={gatewaySerial}
            gatewayLocalAddress={gatewayLocalAddress}
          />
        </TabPane>
      </Tabs>
    </div>
  );
};

export default AddCameraComponent;
