import React, { useEffect, useState } from 'react';

import {
  MinusOutlined,
  PlusOutlined,
  RadiusSettingOutlined,
} from '@ant-design/icons';
import { Button, Tooltip, notification } from 'antd';
import { useTranslation } from 'react-i18next';
import { Circle, Layer, Line, Stage, Text } from 'react-konva';

import colorsDark from '../../assets/colors/dark';
import './index.scss';

const RADIUS_POINT = 5;
const DEFAULT_LINE = ['0.3,0.5', '0.5,0.7'];

const Edge = ({ node1, node2 }) => {
  return (
    <Line
      points={[node1.x, node1.y, node2.x, node2.y]}
      stroke={colorsDark.$brandHex}
      strokeWidth={1}
    />
  );
};

const limitValue = (value, minValue, maxValue) => {
  let v = value;
  v = Math.max(minValue, v);
  v = Math.min(v, maxValue);
  return v;
};

export const DrawVirtualWall = ({
  width,
  height,
  bgImage,
  virtualWalls,
  onChange,
  disabled,
}) => {
  const { t } = useTranslation();
  const [dataPoints, setDataPoints] = useState({});
  const [dataLinks, setDataLinks] = useState({});
  const [edges, setEdges] = useState([]);
  const [anchors, setAnchors] = useState([]);

  const [activePolygonIndex, setActivePolygonIndex] = useState('0');

  const buildLinks = (polygonIdx, numPoints) => {
    const newLinks = [];
    for (let i = 0; i < numPoints - 1; i++) {
      newLinks.push([`${polygonIdx}_${i}`, `${polygonIdx}_${i + 1}`]);
    }

    return newLinks;
  };

  const addPoint = () => {
    if (!activePolygonIndex) {
      notification.warning({
        message: 'Please select a region to adding points',
        placement: 'bottomRight',
      });
      return;
    }

    if (dataPoints && dataPoints[activePolygonIndex]) {
      const length = dataPoints[activePolygonIndex].length;
      const activePoints = dataPoints[activePolygonIndex];

      const lastPoint =
        length > 0
          ? dataPoints[activePolygonIndex][length - 1]
          : {
              x: width / 2,
              y: height / 2,
            };

      setDataPoints({
        ...dataPoints,
        [activePolygonIndex]: [
          ...activePoints,
          {
            id: `${activePolygonIndex}_${length}`,
            x: limitValue(lastPoint.x + 15, 0, width),
            y: limitValue(lastPoint.y + 15, 0, height),
            width: RADIUS_POINT,
            height: RADIUS_POINT,
            draggable: true,
            radius: RADIUS_POINT,
          },
        ],
      });

      const newLinks = buildLinks(activePolygonIndex, length + 1);
      setDataLinks({ ...dataLinks, [activePolygonIndex]: newLinks });
    }
  };

  const removePoint = () => {
    if (dataPoints && dataPoints[activePolygonIndex]) {
      const activePoints = dataPoints[activePolygonIndex];
      const activePointsLength = dataPoints[activePolygonIndex].length;

      if (activePointsLength < 3 && activePointsLength > 0) {
        notification.warning({
          message: 'The line is deleted',
          placement: 'bottomRight',
        });
        delete dataPoints[activePolygonIndex];
        delete dataLinks[activePolygonIndex];

        setDataPoints({ ...dataPoints });
        setDataLinks({ ...dataLinks });
        setActivePolygonIndex('');
        return;
      }

      const newPoints = activePoints.slice(0, activePoints.length - 1);
      setDataPoints({ ...dataPoints, [activePolygonIndex]: newPoints });
      const newLinks = buildLinks(activePolygonIndex, newPoints.length);
      setDataLinks({ ...dataLinks, [activePolygonIndex]: newLinks });
    }
  };

  const addNewLine = () => {
    const newPolygonIdx = Object.keys(dataPoints).length;
    const newRegionLinks = buildLinks(newPolygonIdx, 2);
    const newPoints = [];
    DEFAULT_LINE.forEach((item, pointIdx) => {
      const [x, y] = item.split(',');
      newPoints.push({
        id: `${newPolygonIdx}_${pointIdx}`,
        x: limitValue(parseFloat(x) * width, 0, width),
        y: limitValue(parseFloat(y) * height, 0, height),
        width: RADIUS_POINT,
        height: RADIUS_POINT,
        draggable: true,
        radius: RADIUS_POINT,
      });
    });
    console.log('Add New line: setDataLinks: ', {
      ...dataLinks,
      [newPolygonIdx]: newRegionLinks,
    });
    console.log('add line: setDataPoints: ', {
      ...dataPoints,
      [newPolygonIdx]: newPoints,
    });
    setDataLinks({ ...dataLinks, [newPolygonIdx]: newRegionLinks });
    setDataPoints({ ...dataPoints, [newPolygonIdx]: newPoints });
  };

  useEffect(() => {
    const mapPoints = {};
    const mapLinks = {};

    (virtualWalls || []).forEach((linePoints, idx) => {
      mapPoints[String(idx)] = Object.keys(linePoints || []).map((pointIdx) => {
        const position = virtualWalls[idx][pointIdx];
        const [x, y] = position.split(',');
        return {
          id: `${idx}_${pointIdx}`,
          x: limitValue(parseFloat(x) * width, 0, width),
          y: limitValue(parseFloat(y) * height, 0, height),
          width: RADIUS_POINT,
          height: RADIUS_POINT,
          draggable: false,
          radius: RADIUS_POINT,
        };
      });
    });

    Object.keys(mapPoints).forEach((item) => {
      mapLinks[item] = buildLinks(item, mapPoints[item].length);
    });

    setDataPoints(mapPoints);
    setDataLinks(mapLinks);
  }, [height, width, virtualWalls]);

  useEffect(() => {
    const newEdges = [];

    Object.keys(dataLinks || {}).forEach((polygonIdx) => {
      const links = dataLinks[polygonIdx];
      links.forEach((link, linkIdx) => {
        const node1 = dataPoints[polygonIdx].filter(
          (obj) => obj.id === link[0]
        )[0];

        const node2 = dataPoints[polygonIdx].filter(
          (obj) => obj.id === link[1]
        )[0];

        newEdges.push([node1, node2]);
      });
    });

    setEdges(newEdges);
  }, [dataLinks, dataPoints]);

  useEffect(() => {
    const newAnchors = [];

    Object.keys(dataPoints).forEach((polygonIdx) => {
      const polygonPoints = dataPoints[polygonIdx];
      polygonPoints.forEach((point, idx) => {
        newAnchors.push(point);
      });
    });

    setAnchors(newAnchors);
  }, [dataLinks, dataPoints]);

  useEffect(() => {
    if (typeof onChange === 'function') {
      const result = [];
      Object.keys(dataPoints).forEach((polygonId) => {
        let polygonPoints = [];
        dataPoints[polygonId].forEach((p) => {
          polygonPoints.push(
            `${(p.x / width).toFixed(2)},${(p.y / height).toFixed(2)}`
          );
        });
        result.push(polygonPoints);
      });
      onChange(result);
    }
  }, [dataPoints, onChange, width, height]);

  return (
    <div className="draw-polygon">
      <div className="controls" style={{ width: width }}>
        <div>
          <Tooltip title={t('Remove a point')} placement="bottom">
            <Button
              disabled={disabled}
              size="small"
              icon={<MinusOutlined />}
              onClick={removePoint}
            />
          </Tooltip>
          <Tooltip title={t('Add a point')} placement="bottom">
            <Button
              disabled={disabled}
              size="small"
              icon={<PlusOutlined />}
              onClick={addPoint}
            />
          </Tooltip>
        </div>

        <div>
          <Tooltip title={t('Add a virtual wall')} placement="bottom">
            <Button
              size="small"
              icon={<RadiusSettingOutlined />}
              onClick={addNewLine}
              disabled={disabled}
            />
          </Tooltip>
        </div>
      </div>
      <div className="wrap-draw-polygon">
        <img
          className="bg-img"
          src={bgImage}
          width={width}
          height={height}
          alt="Add region"
        />
        <div className="draw-region">
          <Stage width={width} height={height}>
            <Layer>
              {edges.map((edge, idx) => {
                return (
                  <Edge key={`edge-${idx}`} node1={edge[0]} node2={edge[1]} />
                );
              })}

              {anchors.map((point, idx) => {
                const polygonIdx = point.id.split('_')[0];

                return (
                  <>
                    <Circle
                      key={`point-${idx}`}
                      {...point}
                      fill={
                        activePolygonIndex === polygonIdx
                          ? colorsDark.$brandHex
                          : colorsDark.$warning
                      }
                      onClick={(e) => {
                        const pointId = e.target.attrs.id;
                        const polygonIdx = pointId.split('_')[0];
                        setActivePolygonIndex(polygonIdx);
                      }}
                      radius={RADIUS_POINT}
                      draggable={!disabled}
                      onDragMove={(e) => {
                        let xPoint = 0;
                        let yPoint = 0;

                        const pointId = e.target.attrs.id;
                        const polygonIdx = pointId.split('_')[0];
                        setActivePolygonIndex(polygonIdx);

                        const newDataPoints = { ...dataPoints };

                        let pointsTemp = dataPoints[polygonIdx].map((p1) => {
                          if (p1.id === e.target.attrs.id) {
                            const attrs = e.target.attrs;
                            xPoint = limitValue(attrs.x, 0, width);
                            yPoint = limitValue(attrs.y, 0, height);

                            return {
                              ...attrs,
                              x: xPoint,
                              y: yPoint,
                              radius: RADIUS_POINT,
                            };
                          }
                          return p1;
                        });

                        e.currentTarget.setRadius(RADIUS_POINT);

                        if (xPoint >= 0) {
                          e.currentTarget.setX(xPoint);
                        }

                        if (yPoint >= 0) {
                          e.currentTarget.setY(yPoint);
                        }

                        newDataPoints[polygonIdx] = pointsTemp;
                        setDataPoints(newDataPoints);
                      }}
                    />
                    <Text
                      text={idx}
                      width={RADIUS_POINT * 2}
                      align="center"
                      verticalAlign="middle"
                      x={Math.max(
                        0,
                        Math.min(point.x, width - RADIUS_POINT * 2)
                      )}
                      y={Math.max(
                        0,
                        Math.min(point.y, height - RADIUS_POINT * 2)
                      )}
                      fill="white"
                      fontSize={RADIUS_POINT * 2}
                      listening={false}
                    />
                  </>
                );
              })}
            </Layer>
          </Stage>
        </div>
      </div>
    </div>
  );
};

export default DrawVirtualWall;
