import { Button, Form, Input } from "antd";
import React, { useCallback, useEffect, useState } from "react";
import * as SERVICE from '@/constants/service.types'
import { useDispatch, useSelector } from "react-redux";
import { openMessage, socketEmitEvent } from "@/redux/actions";
import { useTranslation } from "react-i18next";
import { ReactComponent as S3Icon } from '@/assets/icons/s3-storage-icon.svg'
import { ReactComponent as DropboxIcon } from '@/assets/icons/dropbox-storage-icon.svg'
import { ReactComponent as NasIcon } from '@/assets/icons/nas-storage-icon.svg'
import { ReactComponent as GGDrivcIcon } from '@/assets/icons/gg-drive-storage-icon.svg'

import './index.scss'
import { NOTIFIES } from "@/constants/system.keys";

const STORAGE_TYPES = [
  { value: 'S3', label: 'S3', Icon: S3Icon, available: true },
  { value: 'dropbox', label: 'Dropbox', Icon: DropboxIcon, available: false },
  { value: 'nas', label: 'NAS', Icon: NasIcon, available: false },
  { value: 'gg-drive', label: 'Google Drive', Icon: GGDrivcIcon, available: false },
];


export const EditStorageComponent = ({ camera, namespace }) => {
  const [form] = Form.useForm();
  const dispatch = useDispatch();
  const { services, totalCamera, devicesActiveOfServices } = useSelector(state => state)
  const { t } = useTranslation()
  const [selectedStorageType, setSelectedStorageType] = useState(STORAGE_TYPES[0].value)

  useEffect(() => {
    const timeRequest = new Date().getTime();
    let data = {
      serviceId: 20,
      timeRequest,
      namespace,
      page: 0,
      size: totalCamera || 100
    };
    console.log('data: ', data);
    let dataObj = {
      appServiceType: SERVICE.LIST_DEVICE_ACTIVE_SERVICE_ID,
      requestId: timeRequest,
      body: JSON.stringify(data),
    };
    return dispatch(socketEmitEvent(dataObj));
  }, [dispatch, namespace, totalCamera]);


  useEffect(() => {
    let data = {
      namespace,
    };
    let dataObj = {
      appServiceType: SERVICE.LIST_SERVICE,
      requestId: new Date().getTime(),
      body: JSON.stringify(data),
    };
    dispatch(socketEmitEvent(dataObj));
  }, [dispatch, namespace]);

  useEffect(() => {
    if (services) {
      console.log('services: ', services);
      console.log('services: ', services?.filter(item => item?.id === 20));
      console.log('devicesActiveOfServices: ', camera, devicesActiveOfServices);
      const isActive = devicesActiveOfServices?.devices?.some(item => item?.serial === camera?.serial)
      console.log('isActive: ', isActive);
      if (isActive && form) {
        const configuration = services?.find(item => item?.id === 20)?.configuration
        if (configuration) {
          console.log('configuration: ', configuration);
          form.setFieldsValue({
            endpoint: configuration?.endpoint,
            region: configuration?.region,
            secretKey: configuration?.secretKey,
            accessKey: configuration?.accessKey,
          })
        }
      }
    }
  }, [services, devicesActiveOfServices, form, camera]);

  const onSelectStorageType = (type, available) => {
    if (!available) {
      openMessage(NOTIFIES.INFO, t('This feature is not available yet'))
      return;
    }
    setSelectedStorageType(type);
  }

  const onFinish = (value) => {
    console.log('value: ', value);
  };


  return (
    <div className="edit-storage-component">
      <div className="edit-storage-header">
        {STORAGE_TYPES.map(({ value, label, Icon, available }) => (
          <div
            key={value}
            className={`storage-type-item ${selectedStorageType === value ? 'active' : ''
              }`}
            onClick={() => onSelectStorageType(value, available)}
          >
            <Icon />
            {label}
          </div>
        ))}

      </div>
      <div className="edit-storage-form">
        <Form
          layout="horizontal"
          form={form}
          onFinish={onFinish}
        >
          <Form.Item
            name='endpoint'
            label="S3 endpoint"
          >
            <Input placeholder="Enter s3 endpoint" />
          </Form.Item>
          <Form.Item
            name='region'
            label="Region"
          >
            <Input placeholder="Enter region" />
          </Form.Item>
          <Form.Item
            name='secretKey'
            label="Secret key"
          >
            <Input placeholder="Enter secret key" type="password" />
          </Form.Item>
          <Form.Item
            name='accessKey'
            label="Access key"
          >
            <Input placeholder="Enter access key" type="password" />
          </Form.Item>
          <Form.Item className="flex w-full justify-end form-item-btn-submit">
            <Button
              htmlType="submit"
              type="primary"
            >{t('Save')}
            </Button>
          </Form.Item>
        </Form>
      </div>
    </div>
  )
}