import React, { useMemo } from 'react';
import { useProgressBarContext } from './context';
import { EVENT_ICONS } from './constants';
import { Tooltip } from 'antd';
import { formatTime } from './utils';
import { usePlaybackContext } from '../../context';
import { AiEventType, EVENT_SERVICE_IDS } from '@/constants/events';

export const EventTimeline = ({
  aiEvents,
  scrubberRef,
  hoverScrubberRef,
  handleScrubberMouseDown,
  scrubberLeftPct,
  onSeek,
}) => {
  const { visibleEventTypes } = useProgressBarContext();
  const groupedEvents = useMemo(() => {
    if (!Array.isArray(aiEvents)) return {};
    return aiEvents.reduce((acc, event) => {
      let key = event?.type;
      if (event?.type === AiEventType.COMMON_EVENT_DETECTION) {
        key = event?.serviceId;
      }
      if (!acc[key]) acc[key] = [];
      acc[key].push(event);
      return acc;
    }, {});
  }, [aiEvents]);

  const visibleEventTypesToShow = useMemo(
    () => [...(visibleEventTypes || [])],
    [visibleEventTypes],
  );
  if (
    visibleEventTypesToShow.length === 0 ||
    Object.keys(groupedEvents).length === 0
  )
    return null;

  return (
    <div className="relative w-full h-full bg-gray-100">
      <div className="flex flex-col gap-2 py-2 overflow-x-auto overflow-y-hidden">
        {visibleEventTypesToShow.map((type, index) => (
          <div key={index} className="flex items-center gap-2">
            <div className="flex-1">
              <EventTimelineRow rowData={groupedEvents[type] || []} />
            </div>
          </div>
        ))}
      </div>

      <div
        ref={scrubberRef}
        className="absolute transition-transform scrubber justify-center"
        onMouseDown={handleScrubberMouseDown}
        style={{
          width: '2px',
          height: '80%',
          backgroundColor: '#000',
          cursor: 'grab',
          transform: 'translate(-50%,-50%)',
          zIndex: 40,
          pointerEvents: 'auto',
          left: `${scrubberLeftPct}%`,
          top: '50%',
        }}
      >
        <div
          style={{
            position: 'absolute',
            top: '-6px',
            left: '50%',
            transform: 'translateX(-50%)',
            width: '10px',
            height: '10px',
            borderRadius: '50%',
            backgroundColor: '#000',
            border: '2px solid white',
            boxShadow: '0 2px 4px rgba(0,0,0,0.3)',
            cursor: 'grab',
          }}
        />
        <div
          style={{
            position: 'absolute',
            bottom: '-6px',
            left: '50%',
            transform: 'translateX(-50%)',
            width: '10px',
            height: '10px',
            borderRadius: '50%',
            backgroundColor: '#000',
            border: '2px solid white',
            boxShadow: '0 2px 4px rgba(0,0,0,0.3)',
            cursor: 'grab',
          }}
        />
      </div>

      <div
        ref={hoverScrubberRef}
        className="absolute transition-opacity hoverScrubber"
        style={{
          width: '2px',
          height: '100%',
          backgroundColor: '#faad14',
          transform: 'translateX(-50%)',
          zIndex: 30,
          pointerEvents: 'none',
          left: '0%',
          top: 0,
          display: 'none',
        }}
      />
    </div>
  );
};

const EventTimelineRow = ({ rowData }) => {
  const { setSelectedEvent } = usePlaybackContext();
  const onSelectEvent = (event) => {
    setSelectedEvent(event?.events?.[0] || null);
  };

  const getLabelKey = (event) => {
    if (!event?.serviceId) return event?.type;
    if (event?.type === AiEventType.COMMON_EVENT_DETECTION) {
      return event?.serviceId;
    }
  };

  const getTooltipTitle = (event) => {
    switch (event?.type) {
      case AiEventType.FACE_RECOGNITION:
        return `${event?.objects} - ${event?.personName}`;
      case AiEventType.COMMON_EVENT_DETECTION:
        switch (event?.serviceId) {
          case EVENT_SERVICE_IDS.MOTION_DETECTION:
            return `${event?.objects?.replace('Event', 'Motion')}: ${
              event?.timeString || formatTime(event?.time)
            }`;
          default:
            return `${event?.objects}: ${
              event?.timeString || formatTime(event?.time)
            }`;
        }
      default:
        return `${event?.objects}: ${
          event?.timeString || formatTime(event?.time)
        }`;
    }
  };

  return (
    <div className="relative w-full h-5 event-timeline-row">
      {rowData?.map((item, index) => {
        return (
          <Tooltip
            title={() => (
              <span className="flex items-center justify-start gap-1">
                {EVENT_ICONS[getLabelKey(item)]}
                {getTooltipTitle(item?.events?.[0])}
              </span>
            )}
            placement="topLeft"
            overlayClassName="event-timeline-tooltip"
          >
            <div
              key={`${item.type}-${index}-${item.time}`}
              className="absolute"
              onClick={() => onSelectEvent(item)}
              style={{
                left: `${item.leftPct}%`,
                width: `${item.widthPct}%`,
                height: '100%',
                backgroundColor: item.color,
                borderRadius: '4px',
                opacity: 0.9,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'start',
                paddingLeft: '4px',
                overflow: 'hidden',
              }}
            >
              {/* {EVENT_ICONS[event.type]} */}
            </div>
          </Tooltip>
        );
      })}
    </div>
  );
};
