export const TABS = {
  CAMERA: 'camera',
  GROUP_CAMERA: 'group_camera',
  MEMBER: 'member',
};

export const PERMISSIONS = ['live', 'playback', 'download', 'upload', 'share'];

/**
 * Transform permission string to permission array
 * @param {string} permissionString - String of permissions (e.g. "1_2_3")
 * @returns {string[]} Array of permission numbers
 */
export const permissionStringToArray = (permissionString) => {
  if (!permissionString) return [];

  return permissionString.split('_').filter(Boolean);
};

/**
 * Transform permission array to permission string
 * @param {string[]} permissionArray - Array of permission numbers
 * @returns {string} String of permissions (e.g. "1_2_3")
 */
export const permissionArrayToString = (permissionArray) => {
  if (!permissionArray?.length) return '';

  return permissionArray.filter(Boolean).join('_');
};
