import React, { useCallback, useEffect, useState } from 'react';
import { Button, Slider, Space, Card, Row, Col, Statistic } from 'antd';
import {
  ArrowUpOutlined,
  ArrowDownOutlined,
  ArrowLeftOutlined,
  ArrowRightOutlined,
  ZoomInOutlined,
  ZoomOutOutlined,
} from '@ant-design/icons';
import './index.scss';

import ArrowTopOffIcon from '../icons/arrow_upward_off.svg';
import ArrowTopOnIcon from '../icons/arrow_upward_on.svg';
import ArrowLeftOffIcon from '../icons/arrow_back_off.svg';
import ArrowLeftOnIcon from '../icons/arrow_back_on.svg';
import ArrowRightOffIcon from '../icons/arrow_forward_off.svg';
import ArrowRightOnIcon from '../icons/arrow_forward_on.svg';
import CenterControlIcon from '../icons/center_ovif.svg';
import ArrowBottomOffIcon from '../icons/arrow_downward_off.svg';
import ArrowBottomOnIcon from '../icons/arrow_downward_on.svg';

import ZoomInOffIcon from '../icons/zoom_in_off.svg';
import ZoomInOnIcon from '../icons/zoom_in_on.svg';

import ZoomOutOffIcon from '../icons/zoom_out_off.svg';
import ZoomOutOnIcon from '../icons/zoom_out_on.svg';
import { useDispatch, useSelector } from 'react-redux';
import * as SERVICE from '../../../constants/service.types';
import { socketEmitEvent } from '@/redux/actions';

export const PTZComponent = ({
  onReset = () => {},
  streamMonitorId,
  qualityLevel,
  serviceId,
  serial,
}) => {
  const [controls, setControls] = useState({
    pan: 0,
    tilt: 0,
    panSpeed: 80,
    tiltSpeed: 80,
    zoom: 0,
    zoomSpeed: 20,
  });
  const { namespace } = useSelector((state) => state);
  const dispatch = useDispatch();

  const handlePtz = useCallback(
    (navigator) => {
      let tmpControls = {
        pan: 0,
        tilt: 0,
        panSpeed: 80,
        tiltSpeed: 80,
        zoom: 0,
        zoomSpeed: 20,
      };
      if (navigator === 'up') {
        tmpControls = {
          ...tmpControls,
          pan: 0,
          tilt: 0.5,
        };
      } else if (navigator === 'down') {
        tmpControls = {
          ...tmpControls,
          pan: 0,
          tilt: -0.5,
        };
      } else if (navigator === 'left') {
        tmpControls = {
          ...tmpControls,
          pan: -0.5,
          tilt: 0,
        };
      } else if (navigator === 'right') {
        tmpControls = {
          ...tmpControls,
          pan: 0.5,
          tilt: 0,
        };
      } else if (navigator === 'zoom+') {
        tmpControls = {
          ...tmpControls,
          pan: 0,
          tilt: 0,
          zoom: 0.5,
        };
      } else if (navigator === 'zoom-') {
        tmpControls = {
          ...tmpControls,
          pan: 0,
          tilt: 0,
          zoom: -0.5,
        };
      }
      setControls(tmpControls);
      const dataBody = {
        streamMonitorId,
        qualityLevel,
        namespace,
        control: JSON.stringify(tmpControls),
        serviceId,
        serial,
      };
      console.log('🚀 ~ PTZComponent ~ dataBody:', dataBody);
      const dataObj = {
        appServiceType: SERVICE.UPDATE_STREAM_MONITOR,
        requestId: Date.now(),
        body: JSON.stringify(dataBody),
      };
      dispatch(socketEmitEvent(dataObj));
    },
    [namespace, qualityLevel, serial, serviceId, streamMonitorId],
  );

  return (
    <>
      <div className="controls-video">
        <div className="move-buttons">
          <button onClick={() => handlePtz('up')}>
            <img
              src={controls?.tilt === 1 ? ArrowTopOnIcon : ArrowTopOffIcon}
              alt="up_button"
            />
          </button>
          <button onClick={() => handlePtz('left')}>
            <img
              src={controls?.pan === -1 ? ArrowLeftOnIcon : ArrowLeftOffIcon}
              alt="left_button"
            />
          </button>
          <button onClick={() => onReset()} style={{ display: 'none' }}>
            {/* <img src={CenterControlIcon} alt="" /> */}
          </button>
          <button onClick={() => handlePtz('right')}>
            <img
              src={controls?.pan === 1 ? ArrowRightOnIcon : ArrowRightOffIcon}
              alt="right_button"
            />
          </button>
          <div />
          <button onClick={() => handlePtz('down')}>
            <img
              src={
                controls?.tilt === -1 ? ArrowBottomOnIcon : ArrowBottomOffIcon
              }
              alt="down_button"
            />
          </button>
          <div />
        </div>
        <div className="zoom-buttons">
          <button onClick={() => handlePtz('zoom+')}>
            <img
              src={controls.zoom > 0 ? ZoomInOnIcon : ZoomInOffIcon}
              alt="zoom in"
            />
          </button>
          <button onClick={() => handlePtz('zoom-')}>
            <img
              src={controls.zoom < 0 ? ZoomOutOnIcon : ZoomOutOffIcon}
              alt="zoom out"
            />
          </button>
        </div>
      </div>
    </>
  );
};

export default PTZComponent;
