import {
  parseResponseBody,
  prepareBody,
  requestSocketPromiseWithTimeout,
} from '../../socket/query'
import * as SERVICE from '../../constants/service.types'

import { useSocketRequest } from '../../socket/useSocketRequest'

export const getChallengeAuthenticationWebAuthn = async (input) => {
  const response = await requestSocketPromiseWithTimeout({
    body: prepareBody(input),
    appServiceType: SERVICE.GET_CHALLENGE_AUTHENTICATION_WEB_AUTHN,
  })

  return parseResponseBody(response);
};

