import { Button, Modal, Table, Tag, Tooltip } from "antd";
import React, { useCallback, useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { useSelector } from "react-redux";
import { addRoleFunction, deleteRoleFunction, getListFunctionOfRole } from "@/hooks/socket/role";
import { beeXLogger } from "@/helpers/logger";
import { TrashCanIcon } from '@/icons/TrashCan';
import { PlusOutlined } from '@ant-design/icons';
import './index.scss';
import { FunctionSelected, FunctionGroup } from "./CreateRole/FunctionGroup";
import { openMessage } from "@/redux/actions";
import { NOTIFIES } from "@/constants/system.keys";
import { ExclamationCircleOutlined } from '@ant-design/icons';


const ExpandRoleComponent = ({ roleId = null }) => {
    const { t } = useTranslation()
    const { namespace, listFunctions } = useSelector(state => state)
    const [functionsOfRole, setFunctionsOfRole] = useState([])
    const [loading, setLoading] = useState(false)
    const [visibleAddFunction, setVisibleAddFunction] = useState(false)
    const [functionGroups, setFunctionGroups] = useState([])
    const [selectedGroup, setSelectedGroup] = useState();
    const [selectedFunctions, setSelectedFunctions] = useState([]);
    const [addFunctionLoading, setAddFunctionLoading] = useState(false);
    const [missingFunctions, setMissingFunctions] = useState([])

    const fetchFunctionsOfRole = useCallback(() => {
        if (!roleId) return;
        setLoading(true)
        getListFunctionOfRole({ roleId, namespace })
            .then((res) => {
                beeXLogger.debug("🚀 ~ fetchFunctionsOfRole ~ res:", res)
                setFunctionsOfRole(
                    res?.map(item => ({
                        ...item,
                        name: listFunctions?.find(f => f?.tag === item?.functionTag)?.name
                    }))
                )
            })
            .catch((err) => {
                beeXLogger.debug("🚀 ~ fetchFunctionsOfRole ~ err:", err)
            })
            .finally(() => setLoading(false))
    }, [roleId, namespace, listFunctions])

    useEffect(() => {
        fetchFunctionsOfRole()
    }, [fetchFunctionsOfRole])

    useEffect(() => {
        if (missingFunctions) {
            setFunctionGroups(
                Object.values(
                    missingFunctions.reduce((acc, cur) => {
                        if (!acc[cur.groupFunction]) {
                            acc[cur.groupFunction] = {
                                groupName: cur.groupFunction,
                                functions: []
                            };
                        }
                        acc[cur.groupFunction].functions.push({
                            name: cur.name,
                            tag: cur.tag
                        });
                        return acc;
                    }, {})
                )
            )
        }
    }, [missingFunctions]);

    useEffect(() => {
        if (functionGroups && !selectedGroup) {
            setSelectedGroup(functionGroups?.[0])
        }
    }, [functionGroups, selectedGroup])

    useEffect(() => {
        if (listFunctions && functionsOfRole) {
            setMissingFunctions(
                listFunctions?.filter(item =>
                    functionsOfRole?.every(f => f?.functionTag !== item?.tag)
                )
            )
        }
    }, [functionsOfRole, listFunctions])

    const resetAddFunctionState = useCallback(() => {
        setSelectedFunctions([])
        setSelectedGroup(undefined)
        setVisibleAddFunction(false)
    }, [])

    const onSelectFunction = (group, tags) => {
        setSelectedFunctions(prev => {
            let tmp = [...prev]
            const existGroup = tmp?.some(f => f?.group === group)
            if (!existGroup) {
                tmp.push({ group, tags: [...tags] })
            }
            tmp = tmp.map(f => f?.group === group ? { ...f, tags: [...tags] } : f)
            return tmp.filter(t => t?.tags?.length > 0)
        });
    };

    const onAddFunction = useCallback(() => {
        setAddFunctionLoading(true)
        const functionTags = selectedFunctions.flatMap(item => item.tags);
        Promise.all(
            functionTags.map((tag) =>
                addRoleFunction({ roleId, functionTag: tag, namespace })
            )
        )
            .then((res) => {
                beeXLogger.debug("🚀 ~ onAddFunction ~ res:", res)
                openMessage(NOTIFIES.SUCCESS, t('Add function successfully.'));
                resetAddFunctionState()
                fetchFunctionsOfRole()
            })
            .catch(err => {
                beeXLogger.debug("🚀 ~ onAddFunction ~ err:", err)
                openMessage(NOTIFIES.ERROR, t('Failed to add function. Please try again.'));
            })
            .finally(() => setAddFunctionLoading(false))
    }, [selectedFunctions, roleId, namespace, t, resetAddFunctionState, fetchFunctionsOfRole])

    const onRemoveFunction = useCallback((record) => {
        console.log("🚀 ~ onRemoveFunction ~ record:", record)
        Modal.confirm({
            title: `${t('Remove function')}: ${record?.name}?`,
            icon: <ExclamationCircleOutlined />,
            okText: t('Remove'),
            onOk() {
                return deleteRoleFunction({
                    roleId: record?.roleId,
                    namespace,
                    functionTag: record?.functionTag
                }).then(
                    (res) => {
                        console.log("🚀 ~ onRemoveFunction ~ res:", res)
                        openMessage(NOTIFIES.SUCCESS, t('Remove function successfully.'));
                        resetAddFunctionState()
                        fetchFunctionsOfRole()
                    },
                    (err) => {
                        console.log("🚀 ~ onRemoveFunction ~ err:", err)
                        openMessage(NOTIFIES.ERROR, t('Failed to remove function. Please try again.'));
                    }
                );
            },
            onCancel() { },
        });
    }, [fetchFunctionsOfRole, namespace, resetAddFunctionState, t]);

    return (
        <>
            <div className="expand-role-component">
                <div className="expand-role-header">
                    <Button icon={<PlusOutlined />} onClick={() => setVisibleAddFunction(true)}>
                        {t('Add function')}
                    </Button>
                </div>
                <Table
                    loading={loading}
                    columns={[
                        {
                            title: t('Name'),
                            dataIndex: 'name',
                            key: 'name',
                            render: (value) => value ? value : '_'
                        },
                        {
                            title: t('Tag'),
                            dataIndex: 'functionTag',
                            key: 'functionTag',
                            render: (value, row) => {
                                if (!row?.functionTag) return null
                                return <Tag color="#028fd5">{t(value)}</Tag>
                            },
                        },
                        {
                            title: t('Created at'),
                            dataIndex: 'createdAt',
                            key: 'createdAt',
                            width: 200,
                        },
                        {
                            title: t('Action'),
                            key: 'action-role',
                            width: 120,
                            render: (value, row) => (
                                <div className="role-actions">
                                    <Tooltip title={'Remove'}>
                                        <div
                                            className="delete-btn action-btn"
                                            onClick={() => onRemoveFunction(row)}
                                        >
                                            <TrashCanIcon />
                                        </div>
                                    </Tooltip>
                                </div>
                            ),
                        },
                    ]}
                    dataSource={functionsOfRole?.map((item, index) => ({ ...item, key: index + 1 })) || []}
                />
            </div>
            <Modal
                className='add-function-modal'
                title="Add Function"
                visible={visibleAddFunction}
                maskClosable={false}
                footer={null}
                onCancel={() => {
                    resetAddFunctionState()
                }}
                width={1200}
            >
                <FunctionGroup
                    functionGroups={functionGroups}
                    selectedGroup={selectedGroup}
                    onSelectGroup={setSelectedGroup}
                    selectedFunctions={selectedFunctions}
                    onSelectFunction={onSelectFunction}
                    showAdd={true}
                    onAdd={onAddFunction}
                    addLoading={addFunctionLoading}
                    addDisabled={!selectedFunctions?.length}
                />
            </Modal>
        </>
    )
}

export default ExpandRoleComponent;