import * as SYSTEM from '../constants/system.keys';
import { GET_API } from './index';

export const getCustomerDevicesApi = async (token, dataHeader, dataQuery) => {
  return GET_API(
    `${SYSTEM.SERVER_URL_CMS}/customer-devices`,
    token,
    dataHeader,
    dataQuery
  );
};

