import { getCameraToSetting } from "@/redux/camera/reducer";
import React, { useCallback, useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { CloseCircleOutlined, MinusCircleFilled, PlusCircleFilled, RetweetOutlined, SaveOutlined } from '@ant-design/icons';
import { ReactComponent as CameraOnIcon } from '@/assets/icons/camera_on.svg'
import { ReactComponent as CameraOffIcon } from '@/assets/icons/camera_off.svg'

import './index.scss'
import { setCameraToSetting } from "@/redux/camera/action";
import { Button, Collapse, Form, Input, Modal, Select, Tooltip } from "antd";
import { useTranslation } from "react-i18next";
import LinkTag from "@/components/LinkTag";
import * as SERVICE from '@/constants/service.types';
import regex from '@/constants/system.keys';
import UpdateStreamComponent from "../UpdateStream";
import { socketEmitEvent, updateDeviceReturn } from "@/redux/actions";
import LocationSearchLocationIQ from "@/components/LocationSearchLocationIQ";
import InputTag from "@/components/InputTag";
import { EditStorageComponent } from "./EditStotage";
import { EditServiceComponent } from "./EditService";
import { Link } from 'react-router-dom';
import HistoryEventsModal from "../HistoryEventsModal";
import { uniqRequestId } from "@/untils/unique";
import { EDEVICETYPE } from "@/constants";
import { PlaceSelector } from "@/components/PlaceSelector";


const { Panel } = Collapse;

export const CameraSetting = ({ onUpdateReturn }) => {
  const { namespace, accountByNamespace, listGpsLocation, listSpeakerSip, updateDevice } = useSelector(state => state)
  const cameraToSetting = useSelector(getCameraToSetting)
  const dispatch = useDispatch()
  const { t } = useTranslation()
  const [form] = Form.useForm();
  const [visibleUpdateStream, setVisibleUpdateStream] = useState(false);
  const [visibleHistoryEvent, setVisibleHistoryEvent] = useState(false)
  const [requestId, setRequestId] = useState(Date.now());
  const [address, setAddress] = useState({
    note: '',
    lat: 0,
    lng: 0,
  });
  const [isLoadingLatLng, setIsLoadingLatLng] = useState(false);
  const [loadingSubmit, setLoadingSubmit] = useState(false)

  useEffect(() => {
    if (namespace) {
      let dataBodyGps = {
        namespace,
        timeRequest: uniqRequestId(19, EDEVICETYPE.GPS),
        deviceType: EDEVICETYPE.GPS,
        page: 0,
        size: -1,
      };

      let dataObjGps = {
        appServiceType: SERVICE.LIST_ALL_DEVICE_BY_PAGE,
        requestId: new Date().getTime(),
        body: JSON.stringify(dataBodyGps),
      };
      let dataBodySpeaker = {
        namespace,
        timeRequest: uniqRequestId(19, EDEVICETYPE.SPEAKER),
        deviceType: EDEVICETYPE.SPEAKER,
        page: 0,
        size: -1,
      };

      let dataObjSpeaker = {
        appServiceType: SERVICE.LIST_ALL_DEVICE_BY_PAGE,
        requestId: new Date().getTime(),
        body: JSON.stringify(dataBodySpeaker),
      };

      let dataBodyAccount = {
        namespace,
      };
      let dataObjAccount = {
        appServiceType: SERVICE.LIST_ACCOUNT_BY_NAMESPACE,
        requestId: new Date().getTime(),
        body: JSON.stringify(dataBodyAccount),
      };

      dispatch(socketEmitEvent(dataObjAccount));
      dispatch(socketEmitEvent(dataObjGps));
      dispatch(socketEmitEvent(dataObjSpeaker));
    }
  }, [dispatch, namespace]);


  useEffect(() => {
    if (cameraToSetting) {
      console.log('cameraToSetting: ', cameraToSetting);
      const { name, serial, note, lat, lng, tags, placeId } = cameraToSetting;
      const contact = (cameraToSetting?.contact && JSON.parse(cameraToSetting?.contact)) || {};
      setAddress({
        note,
        lat,
        lng,
      });
      form.setFieldsValue({
        name,
        serial,
        tags: tags && tags !== ';' ? tags?.split(';') : [],
        note: note || '',
        accounts: contact?.accounts ? contact?.accounts?.split(';') : [],
        gps: contact?.gps ? contact?.gps?.split(';') : [],
        speaker: contact?.speaker ? contact?.speaker?.split(';') : [],
        phones: contact?.phones ? contact?.phones?.split(';') : [],
        emails: contact?.emails ? contact?.emails?.split(';') : [],
        source: cameraToSetting?.source || '',
        subSources:
          (cameraToSetting?.subSources &&
            JSON.parse(cameraToSetting?.subSources)?.map((item) => item.source)) ??
          [],
        lat,
        lng,
        placeId: placeId || '',
      });
    }
  }, [cameraToSetting, form]);


  const onClose = () => {
    dispatch(setCameraToSetting(null))
  }

  const onChangeCollapse = (key) => {
    console.log(key);
  };

  const onUpdateDevice = useCallback(
    (data) => {
      if (data) {
        const dataTimeRequest = new Date().getTime();
        setRequestId(dataTimeRequest);
        let dataObj = {
          appServiceType: SERVICE.UPDATE_DEVICE,
          requestId: dataTimeRequest,
          body: JSON.stringify({ ...data, namespace }),
        };

        return dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, namespace]
  );

  const onFinish = (values) => {
    console.log('values: ', values);
    const contact = {
      phones: values?.phones?.join(';') || '',
      accounts: values?.accounts?.join(';') || '',
      gps: values?.gps?.join(';') || '',
      speaker: values?.speaker?.join(';') || '',
      emails: values?.emails?.join(';') || '',
    };
    const dataUpdate = {
      name: values?.name || '',
      note: values?.note ?? '',
      serial: values?.serial,
      lat: values?.lat || 0,
      lng: values?.lng || 0,
      contact: JSON.stringify({ ...contact }),
      tags: values?.tags?.join(';')?.toLowerCase() || ';',
      placeId: values?.placeId || ''
    };
    console.log('dataUpdate: ', dataUpdate);
    let dataSubSources = [];
    // eslint-disable-next-line no-unused-expressions
    values?.subSources?.map((item) => {
      const checkData = (
        cameraToSetting?.subSources && JSON.parse(cameraToSetting?.subSources)
      )?.find((item1) => item1.source === item);
      if (checkData) {
        dataSubSources = [...dataSubSources, { ...checkData }];
      } else {
        dataSubSources = [...dataSubSources, { source: item }];
      }
    });
    if (values?.subSources) {
      let data1 = {
        namespace,
        serial: values?.serial,
        subSources: JSON.stringify(dataSubSources),
      };
      console.log('data1: ', data1);
      let dataObj1 = {
        appServiceType: SERVICE.ADD_SUB_STREAM_CAMERA,
        requestId: new Date().getTime(),
        body: JSON.stringify(data1),
      };
      dispatch(socketEmitEvent(dataObj1));
    }
    setLoadingSubmit(true);
    return onUpdateDevice(dataUpdate);
  };

  const handleLinkSpeaker = (action, serial) => {
    const dataBody = {
      namespace,
      providerNamespace: null,
      fromSerial: cameraToSetting.serial,
      toSerial: serial,
    };

    const dataObj = {
      appServiceType: action === 'select' ? SERVICE.LINK_DEVICE : SERVICE.UN_LINK_DEVICE,
      requestId: new Date().getTime(),
      body: JSON.stringify(dataBody),
    };
  }

  useEffect(() => {
    if (updateDevice) {
      if (updateDevice?.requestId === requestId && updateDevice?.data?.serial === cameraToSetting?.serial) {
        console.log('updateDevice: ', updateDevice);
        setLoadingSubmit(false)
        onUpdateReturn(updateDevice)
        dispatch(updateDeviceReturn(null))
      }
    }
  }, [cameraToSetting, dispatch, onUpdateReturn, requestId, updateDevice]);


  const handleAddressChange = (address) => {
    form.setFieldsValue({
      note: address,
    });
    setAddress((state) => ({
      ...state,
      note: address,
    }));
  };

  const handleSelect = (address) => {
    form.setFieldsValue({
      note: address?.note ?? '',
    });
    setAddress(address);
    if (address?.lat && address?.lng) {
      form.setFieldsValue({
        lat: address?.lat,
        lng: address?.lng,
      });
    }
  };


  return (
    <>
      <div className="camera-setting-container">
        <div className="setting-header">
          <div className="setting-header-title">
            {
              cameraToSetting?.state === 1 ? (
                <CameraOnIcon />
              ) : (
                <CameraOffIcon />
              )
            }
            {cameraToSetting?.name}
          </div>
          <div className="btn-close"
            onClick={onClose}
          >
            <CloseCircleOutlined />
          </div>
        </div>
        <div className="setting-content">
          <Form
            layout="horizontal"
            form={form}
            onFinish={onFinish}
            className="setting-form"
          >
            <Collapse defaultActiveKey={['1']} onChange={onChangeCollapse} destroyInactivePanel={false}
              expandIcon={({ isActive }) => isActive ? <MinusCircleFilled /> : <PlusCircleFilled />}
            >
              <Panel forceRender header={t('General information')} key="1">
                <Form.Item
                  label={t('Name')}
                  name="name"
                  rules={[{ required: true, message: t("Please input the name of the camera!") }]}
                >
                  <Input placeholder={t('Enter name')} />
                </Form.Item>
                <Form.Item
                  label={t('Serial')}
                  name="serial"
                  rules={[{ required: true, message: t("Please input the serial of the camera!") }]}
                >
                  <Input placeholder={t('Enter serial')} disabled />
                </Form.Item>
                <Form.Item
                  name="tags"
                  className="edit-camera-email"
                  label={t('Tag')}
                  style={{ borer: '1px solid #434343', borderRadius: '2px' }}
                >
                  <InputTag numberTag={3} nameAdd="Add tag" />
                </Form.Item>
                <div className="edit-camera-alert"></div>
              </Panel>
              <Panel forceRender header={t('Stream configuration')} key="2">
                <Form.Item label={t('Main source')}>
                  <Input.Group compact>
                    <Form.Item name="source" noStyle>
                      <Input
                        placeholder={t('Enter main source')}
                        disabled
                      />
                    </Form.Item>

                    <Tooltip title="Edit source" placement="topLeft">
                      <Button icon={<RetweetOutlined />} onClick={() => setVisibleUpdateStream(true)} />
                    </Tooltip>
                  </Input.Group>
                </Form.Item>

                <Form.Item
                  label={t('Sub sources')}
                  name="subSources"
                >
                  <LinkTag
                    nameAdd={t('Add source')}
                    gatewaySerial={cameraToSetting?.gatewaySerial}
                    namespace={namespace}
                    dataSubSources={cameraToSetting?.subSources && JSON.parse(cameraToSetting?.subSources)}
                  />
                </Form.Item>
              </Panel>
              <Panel forceRender header={t('Location')} key="3">
                <Form.Item
                  name="note"
                  rules={[
                    {
                      pattern: regex.isName,
                      message: t('Please enter only letters and numbers!'),
                    },
                    {
                      max: 200,
                      message: t('Please input up to 200 characters!'),
                    },
                  ]}
                  label={t('Location')}
                  style={{ width: '95%' }}
                >
                  <LocationSearchLocationIQ
                    address={address?.note}
                    onChange={handleAddressChange}
                    onAddressSelect={handleSelect}
                    setIsLoadingLatLng={setIsLoadingLatLng}
                    namespace={namespace}
                  />
                </Form.Item>
                <Form.Item
                  label={t('Lat')}
                  name="lat"
                >
                  <Input />
                </Form.Item>
                <Form.Item
                  label={t('Lng')}
                  name="lng"
                >
                  <Input />
                </Form.Item>
                <Form.Item
                  name="placeId"
                  label={t('Place')}
                // style={{ width: '100%' }}
                >
                  <PlaceSelector />
                </Form.Item>
              </Panel>
              <Panel forceRender header={(
                <div className="flex justify-between items-center cursor-not-allowed">
                  <span>{t('Events')}</span>
                  <span className="underline text-brand hover:no-underline cursor-pointer" onClick={() => setVisibleHistoryEvent(true)}>{t('View')}</span>
                </div>
              )} key="4" showArrow={false} disabled></Panel>
              <Panel forceRender header={t('Integration')} key="5">
                <Form.Item name="gps" label={t('Gps')}>
                  <Select
                    showSearch
                    mode="multiple"
                    placeholder={t('Select Gps')}
                    optionFilterProp="children"
                    filterOption={(input, option) => {
                      return (
                        option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                      );
                    }}
                  >
                    {listGpsLocation?.map((d) => (
                      <Select.Option key={d.serial}>
                        {d.name ? d.name : d.serial}
                      </Select.Option>
                    ))}
                  </Select>
                </Form.Item>
                <Form.Item name="speaker" label={t('Speaker')}>
                  <Select
                    showSearch
                    mode="multiple"
                    placeholder={t('Select Speaker')}
                    optionFilterProp="children"
                    filterOption={(input, option) => {
                      return (
                        option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                      );
                    }}
                    onSelect={value => handleLinkSpeaker('select', value)}
                    onDeselect={value => handleLinkSpeaker('deselect', value)}
                  >
                    {listSpeakerSip?.map((d) => (
                      <Select.Option key={d.serial}>
                        {d.name ? d.name : d.serial}
                      </Select.Option>
                    ))}
                  </Select>
                </Form.Item>
              </Panel>
              <Panel forceRender header={t('Staffs')} key="6">
                <Form.Item name="accounts" label={t('Account')}>
                  <Select
                    showSearch
                    mode="multiple"
                    placeholder={t('Select account')}
                    optionFilterProp="children"
                    filterOption={(input, option) => {
                      const data =
                        (option &&
                          option.children &&
                          option.children.props &&
                          option.children.props.children &&
                          option.children.props.children[0] &&
                          option.children.props.children[0].props &&
                          option.children.props.children[0].props.children) ||
                        '';
                      return (
                        option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                      );
                    }}
                  >
                    {accountByNamespace?.map((d) => (
                      <Select.Option key={d.accountId}>
                        {d.fullName
                          ? `${d.phonenumber} (${d.fullName})`
                          : d.phonenumber}
                      </Select.Option>
                    ))}
                  </Select>
                </Form.Item>
                <Form.Item
                  name="emails"
                  className="edit-camera-email"
                  label={t('Email')}
                  style={{ borer: '1px solid #434343', borderRadius: '2px' }}
                >
                  <InputTag numberTag={3} nameAdd="Add email" />
                </Form.Item>
                <Form.Item
                  name="phones"
                  className="edit-camera-email"
                  label={t('Phone')}
                  style={{ borer: '1px solid #434343', borderRadius: '2px' }}
                >
                  <InputTag numberTag={3} nameAdd="Add phone" />
                </Form.Item>
              </Panel>
              {/* <Panel forceRender header={t('Storage')} key="7">
                <EditStorageComponent
                  namespace={namespace}
                  camera={cameraToSetting}
                />
              </Panel> */}
              <Panel forceRender header={(
                <div className="flex justify-between items-center">
                  <span>{t('Services')}</span>
                  <Link to='/service' className="underline text-brand hover:no-underline hover:text-brand">{t('More services')}</Link>
                </div>
              )} key="8">
                <EditServiceComponent
                  namespace={namespace}
                  camera={cameraToSetting}
                />
              </Panel>
            </Collapse>
            <div className="form-footer">
              <Button type="default">
                {t('Cancel')}
              </Button>
              <Button type="primary" htmlType="submit"
                icon={<SaveOutlined />}
                loading={loadingSubmit}
              >
                {t('Update')}
              </Button>
            </div>
          </Form>
        </div>
        <div className="setting-footer">

        </div>
      </div>


      <Modal
        title={t('Update stream')}
        visible={visibleUpdateStream}
        onCancel={() => setVisibleUpdateStream(null)}
        footer={null}
        okButtonProps={{ style: { display: 'none' } }}
      >
        <UpdateStreamComponent
          onCancel={() => setVisibleUpdateStream(null)}
          onUpdate={onUpdateDevice}
          data={cameraToSetting}
        />
      </Modal>

      <HistoryEventsModal
        title={cameraToSetting?.name}
        data={cameraToSetting}
        isModalVisible={visibleHistoryEvent}
        handleCancel={() => setVisibleHistoryEvent(false)}
      />
    </>
  )
}