import React, { useMemo } from 'react';
import { Popover, Tag } from 'antd';
import { PlusOutlined } from '@ant-design/icons';
import { EVENT_COLORS, EVENT_LABELS } from './constants';
import { useProgressBarContext } from './context';

const MAX_VISIBLE = 2;
export const EventLegend = ({ aiEvents, isFullScreen }) => {
  const { eventTypes, visibleEventTypes, toggleEventType } =
    useProgressBarContext();
  const visibleItems = useMemo(
    () => [...(eventTypes || [])].slice(0, MAX_VISIBLE),
    [eventTypes],
  );

  const hiddenItems = useMemo(
    () => [...(eventTypes || [])].slice(MAX_VISIBLE),
    [eventTypes],
  );

  if (aiEvents.length === 0) return null;

  const hiddenContent = (
    <div className="hidden-legends-wrapper">
      {hiddenItems.map((type) => (
        <LegendItem
          key={type}
          type={type}
          label={EVENT_LABELS?.[type]}
          isSelected={visibleEventTypes?.has(type)}
          onClick={toggleEventType}
          isFullScreen={isFullScreen}
        />
      ))}
    </div>
  );

  if (!eventTypes || eventTypes.size === 0) return null;
  return (
    <div className="event-legends-container">
      <div className="event-legends">
        {visibleItems.map((type) => (
          <LegendItem
            key={type}
            type={type}
            label={EVENT_LABELS?.[type]}
            isSelected={visibleEventTypes?.has(type)}
            onClick={toggleEventType}
            isFullScreen={isFullScreen}
          />
        ))}

        {hiddenItems.length > 0 && (
          <Popover
            content={hiddenContent}
            trigger="hover"
            placement="bottomLeft"
            overlayClassName="event-legend-popover"
          >
            <div className="event-legend-more">
              <Tag
                icon={<PlusOutlined />}
                className={isFullScreen ? 'tag-fullscreen' : ''}
              >
                {hiddenItems.length}
              </Tag>
            </div>
          </Popover>
        )}
      </div>
    </div>
  );
};

const LegendItem = ({ type, label, isSelected, onClick, isFullScreen }) => (
  <div
    className={`event-legend-item ${isSelected ? 'selected' : ''}`}
    onClick={() => onClick(type)}
  >
    <div className="flex items-center gap-1">
      <div
        className="legend-color-box"
        style={{
          backgroundColor: EVENT_COLORS[type],
        }}
      >
        {/* {EVENT_ICONS[type]} */}
      </div>
      <span
        className={`legend-label 
      ${isFullScreen ? 'text-white opacity-70' : 'text-gray-600'}
      ${isSelected ? 'selected' : 'not-selected'}
      `}
      >
        {label}
      </span>
    </div>
  </div>
);
