import { GridContainer, GridItem } from '@/components/CommonGrid';
import React, { useState } from 'react';
import { PlaybackPlayer } from '../Player';
import { LeftOutlined } from '@ant-design/icons';
import './styles.scss';
import { PlaybackPlayerLocal } from '../PlayerLocal';
import { Button, Tooltip } from 'antd';
import { EventHistory } from '../../ProgressBar/v3/EventHistory';

export const PlaybackGridLayout = ({
  cameras,
  mode,
  isLocal,
  displayMode,
  selectedCamera,
  showInfo,
  setShowInfo,
}) => {
  return (
    <div
      className={`playback-grid-layout ${showInfo ? 'has-info' : 'not-has-info'}`}
    >
      <GridContainer displayMode={mode}>
        {cameras.map((camera) => (
          <GridItem key={camera.serial} displayMode={mode}>
            {isLocal ? (
              <PlaybackPlayerLocal
                camera={camera}
                isFocused={selectedCamera?.serial === camera?.serial}
              />
            ) : (
              <PlaybackPlayer
                serial={camera.serial}
                thumbnail={camera.thumbnail}
                name={camera.name}
                withTimeline
                setSecureLink={() => {}}
                displayMode={displayMode}
              />
            )}
          </GridItem>
        ))}
      </GridContainer>
      <div
        className={`playback-grid-layout-right ${showInfo ? 'show' : 'hide'}`}
      >
        <EventHistory
          isFullScreen={false}
          showInfo={showInfo}
          setShowInfo={setShowInfo}
        />
      </div>
      {!showInfo && (
        <div className={`btn-show-info show`}>
          <Tooltip
            title={'Show info'}
            autoAdjustOverflow={false}
            align={{
              offset: [-50, 0],
            }}
          >
            <Button
              shape="circle"
              type="primary"
              onClick={() => setShowInfo(true)}
            >
              <LeftOutlined />
            </Button>
          </Tooltip>
        </div>
      )}
    </div>
  );
};
