import {
  listUserGroupsByParentId,
  listUserGroupMembers,
  useListUserGroups,
} from '@/hooks/socket/member';
import React, {
  memo,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useSelector } from 'react-redux';
import { GroupNodeContainer } from './NodeContainer';
import { AdvanceSearch } from './AdvanceSearch';
import { Spin } from 'antd';
import { LoadingOutlined } from '@ant-design/icons';
import { CreateGroup } from './Nodes';

export const GroupV2 = memo(() => {
  const namespace = useSelector((state) => state.namespace);

  const [_, rerender] = useState({});

  const forceRerender = useCallback(() => {
    rerender({});
  }, [rerender]);

  const { data, isLoading, patch } = useListUserGroups({ namespace });

  const groupMap = useRef({});
  /**
   * {
   *  groupId: [subgroupId, ...]
   * }
   */
  const subgroupMap = useRef({});
  /**
   * {
   *  groupId: [member, ...]
   * }
   */
  const membersMap = useRef({});
  const [expandedMap, setExpandedMap] = useState({});

  useEffect(() => {
    if (!data) return;

    data.forEach((group) => {
      groupMap.current[group.id] = group;
    });
  }, [data]);

  const onExpand = useCallback((groupId, isExpanded) => {
    setExpandedMap((prev) => ({ ...prev, [groupId]: isExpanded }));
  }, []);

  const getSubGroups = useCallback(
    (groupId) => {
      if (subgroupMap.current[groupId]) {
        return Promise.resolve(
          subgroupMap.current[groupId]
            .map((id) => groupMap.current[id])
            .filter(Boolean)
        );
      }

      return listUserGroupsByParentId({
        namespace,
        parentGroupId: groupId,
      }).then((subgroupData) => {
        subgroupMap.current[groupId] = subgroupData.groups.map(
          (child) => child.id
        );

        subgroupData.groups.forEach((child) => {
          groupMap.current[child.id] = child;
        });

        return subgroupMap.current[groupId].map((id) => groupMap.current[id]);
      });
    },
    [namespace]
  );

  const getMembers = useCallback(
    (groupId) => {
      if (membersMap.current[groupId]) {
        return Promise.resolve(membersMap.current[groupId]);
      }

      return listUserGroupMembers({
        namespace,
        groupId,
      }).then((members) => {
        membersMap.current[groupId] = members;

        return members;
      });
    },
    [namespace]
  );

  const onRenameSuccess = (groupId, newName) => {
    if (groupId in groupMap.current) {
      groupMap.current[groupId].name = newName;
      forceRerender();
    }
  };

  const onRemoveSuccess = (groupId) => {
    delete groupMap.current[groupId];
    subgroupMap.current[groupId] = [];
    membersMap.current[groupId] = [];
    patch((prev) => {
      if (!prev) {
        return prev;
      }

      if (prev.find((group) => group.id === groupId)) {
        return prev.filter((group) => group.id !== groupId);
      }

      return prev;
    });
  };

  const onRemoveMemberSuccess = (groupId, accountId) => {
    if (groupId in membersMap.current) {
      membersMap.current[groupId] = membersMap.current[groupId].filter(
        (member) => member.accountId !== accountId
      );
    }
  };

  const onAddMemberSuccess = (groupId, newMembers) => {
    if (groupId in membersMap.current) {
      const oldMembers = membersMap.current[groupId];
      const memberResult = Array.from(
        new Map(
          oldMembers
            .concat(newMembers)
            .map((member) => [member.accountId, member])
        ).values()
      );
      membersMap.current[groupId] = memberResult;
    }
  };

  const onAddGroupSuccess = (groupId, newGroup) => {
    if (groupId in groupMap.current) {
      groupMap.current[newGroup.id] = newGroup;
      subgroupMap.current[groupId] = [
        ...subgroupMap.current[groupId],
        newGroup.id,
      ];
    }
  };

  const rootGroups = useMemo(() => {
    return data?.filter((group) => group.parentGroupId === -1);
  }, [data]);

  useEffect(() => {
    console.log('rootGroups: ', rootGroups);
  }, [rootGroups]);

  const getIsExpanded = useCallback(
    (groupId) => {
      return expandedMap[groupId];
    },
    [expandedMap]
  );

  const [isSearchActive, setIsSearchActive] = useState(false);
  const [isAddingGroup, setIsAddingGroup] = useState(false);

  const onAddRootGroupSuccess = (newGroup) => {
    onAddGroupSuccess(-1, newGroup.group);
    patch((prev) => {
      if (!prev) {
        return prev;
      }

      return [newGroup.group, ...prev];
    });
    setIsAddingGroup(false);
  };

  return (
    <div className="group-v2-container">
      <AdvanceSearch
        onSearchActiveChange={setIsSearchActive}
        namespace={namespace}
        onAddGroupSuccess={onAddGroupSuccess}
        onAddMemberSuccess={onAddMemberSuccess}
        onRemoveMemberSuccess={onRemoveMemberSuccess}
        onRemoveSuccess={onRemoveSuccess}
        onRenameSuccess={onRenameSuccess}
        onAddGroup={() => setIsAddingGroup(true)}
      />
      {!isSearchActive && (
        <div className="group-tree-container relative flex flex-col gap-1">
          {isAddingGroup && (
            <CreateGroup
              onCancel={() => setIsAddingGroup(false)}
              onSuccess={onAddRootGroupSuccess}
              parentGroupId={null}
              namespace={namespace}
              level={0}
            />
          )}

          {rootGroups?.map((group) => (
            <GroupNodeContainer
              key={group.id}
              group={group}
              getSubGroups={getSubGroups}
              getMembers={getMembers}
              onRenameSuccess={onRenameSuccess}
              onRemoveSuccess={onRemoveSuccess}
              getIsExpanded={getIsExpanded}
              onExpand={onExpand}
              onAddMemberSuccess={onAddMemberSuccess}
              onRemoveMemberSuccess={onRemoveMemberSuccess}
              onAddGroupSuccess={onAddGroupSuccess}
            />
          ))}

          {isLoading && (
            <div className="absolute inset-0 flex items-center justify-center">
              <Spin indicator={<LoadingOutlined spin />} />
            </div>
          )}
        </div>
      )}
    </div>
  );
});
