export const loadingState = (metadata, previousState) => {
  return {
    ...previousState,
    loading: true,
    metadata,
    error: undefined,
  };
};

export const successState = (data, previousState) => {
  return {
    ...previousState,
    loading: false,
    data,
    error: undefined,
  };
};

export const errorState = (error, previousState) => {
  return {
    ...previousState,
    loading: false,
    error,
  };
};

