export const openMessage = (type, description, duration = 5) => {
  return message[type]({
    content: description,
    duration,
    style: {
      marginTop: '85vh',
      marginLeft: '78%',
    },
  });
};
export const openNotification = (
  type,
  description,
  image,
  data,
  onChangeModal,
) => {
  if (image) {
    return notification[type]({
      message: 'Notification',
      description: (
        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
          <div>{description}</div>
          <img
            src={image}
            alt=""
            style={{
              width: '115px',
              height: '65px',
              objectFit: 'cover',
              margin: '-25px 20px 0 0',
            }}
            onClick={() => onChangeModal(data)}
          />
        </div>
      ),
      placement: 'bottomRight',
      duration: 4,
    });
  } else {
    return notification[type]({
      message: 'Notification',
      description,
      placement: 'bottomRight',
      duration: 4,
    });
  }
};
