export const authLogoutThunk = () => {
  return async (dispatch) => {
    // logout ms azure
    if (
      localStorage.getItem(AZURE_APP_ID) &&
      localStorage.getItem(AZURE_USER_NAME)
    ) {
      const config = {
        auth: {
          clientId: localStorage.getItem(AZURE_APP_ID),
        },
      };
      const myMsal = new PublicClientApplication(config);
      const account = myMsal.getAccountByUsername(
        localStorage.getItem(AZURE_USER_NAME),
      );
      try {
        await myMsal.logoutPopup({
          account,
        });
        localStorage.removeItem(AZURE_APP_ID);
        localStorage.removeItem(AZURE_USER_NAME);
        dispatch(authLogOut());
      } catch (error) {
        openMessage(NOTIFIES.WARNING, error.message);
      }
    } else {
      dispatch(authLogOut());
    }
  };
};
