import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { Input, Pagination, Divider, Spin, Empty } from 'antd';
import { WithLatestStateDeviceNode } from '../RootTree';
import { LoadingOutlined } from '@ant-design/icons';
import { useListAllDevicesByPage } from '../../../../hooks/socket/cameras';
import * as SERVICE from '../../../../constants/service.types'
import { useDispatch, useSelector } from 'react-redux';
import { socketEmitEvent, updateDeviceReturn } from '../../../../redux/actions';
import { BACKUP_STORAGE_PAGE } from '@/pages/Service/BackupStorage';
import NodataIcon from '../../../../assets/icons/no-data-icon-v2.svg';
import { useTranslation } from 'react-i18next';

const BACKUP_STORAGE_PAGE_SIZE = 15;

const AllCamerasV1 = ({
  cameras,
  currentPage,
  pageSize,
  onPageChange,
  isLoading,
  total,
  getIsCameraPinned,
  onPinCamera,
  selectedSerial,
  onSelectCamera,
  namespace,
  allowRemove,
  allowEdit,
  onRemoveCamera,
  onUpdateCamera,
  onUpdateStream,
  variantPage,
  customCameras,
}) => {
  const timeRequestRef = useRef(Date.now());
  const {
    isLoading: isSearching,
    data: searchResult,
    send,
  } = useListAllDevicesByPage();
  const [isSearchActive, setIsSearchActive] = useState(false);
  const [searchPage, setSearchPage] = useState(1);
  const searchNameRef = useRef('');
  const { devicesActiveOfServices } = useSelector(state => state)
  const [clientPage, setClientPage] = useState(1);
  const isBackupStoragePage = useMemo(() => variantPage === BACKUP_STORAGE_PAGE, [variantPage]);
  const { t } = useTranslation()

  const fetchCameras = useCallback(
    ({ page, name }) => {
      let data1 = {
        namespace,
        deviceType: 'camera',
        timeRequest: timeRequestRef.current,
        page,
        size: 15,
        tag: 'live-list',
        name,
      };
      send(data1);
    },
    [namespace, send]
  );

  const handleSearch = (value) => {
    if (!value) {
      setIsSearchActive(false);
      searchNameRef.current = '';
      return;
    }

    searchNameRef.current = value;

    setIsSearchActive(true);
    timeRequestRef.current = Date.now();
    fetchCameras({ page: 0, name: value });
  };

  const finalCurrentPage = useMemo(() => {
    if (isBackupStoragePage) return clientPage;
    if (!isSearchActive) return currentPage;
    return searchPage;
  }, [isBackupStoragePage, clientPage, isSearchActive, searchPage, currentPage]);

  const finalTotal = useMemo(() => {
    if (isBackupStoragePage) return customCameras?.length || 0;
    if (!isSearchActive) return total;
    return searchResult?.total || 0;
  }, [isBackupStoragePage, customCameras, isSearchActive, searchResult, total]);

  const handlePageChange = (page, pageSize) => {
    if (isBackupStoragePage) {
      setClientPage(page);
      return;
    }

    if (!isSearchActive) {
      onPageChange(page, pageSize);
    } else {
      setSearchPage(page);
      fetchCameras({ page: page - 1, name: searchNameRef.current });
    }
  };

  useEffect(() => {
    if (isBackupStoragePage) {
      setClientPage(1);
    }
  }, [isBackupStoragePage, customCameras]);



  const finalPageSize = useMemo(() => {
    if (isBackupStoragePage) return BACKUP_STORAGE_PAGE_SIZE;
    if (!isSearchActive || variantPage === 'camera-v2') {
      return pageSize
    };
    return 15;
  }, [isBackupStoragePage, isSearchActive, pageSize, variantPage]);

  const camerasToRender = useMemo(() => {
    if (isBackupStoragePage) {
      const start = (clientPage - 1) * BACKUP_STORAGE_PAGE_SIZE;
      const end = start + BACKUP_STORAGE_PAGE_SIZE;
      return customCameras?.slice(start, end) || [];
    }

    if (!isSearchActive) {
      return customCameras || cameras;
    }

    if (isBackupStoragePage) {
      return searchResult?.devices?.filter(item =>
        (devicesActiveOfServices?.devices || [])
          .some(d => d.serial === item.serial)
      );
    }

    return searchResult?.devices || [];
  }, [
    isBackupStoragePage,
    clientPage,
    customCameras,
    isSearchActive,
    cameras,
    searchResult,
    devicesActiveOfServices,
  ]);

  return (
    <>
      <Input.Search
        placeholder="Search camera"
        onSearch={handleSearch}
        loading={isSearching}
        allowClear
      />
      <Divider className="camera-list-divider" />
      <div className="camera-list">
        {(isLoading || isSearching) && (
          <div className="camera-list-loading">
            <Spin indicator={<LoadingOutlined />} />
          </div>
        )}
        <div className="camera-list-items">
          {!isLoading && !isSearching && (
            <React.Fragment>
              {camerasToRender?.length > 0 ? camerasToRender?.map((cam) => (
                <WithLatestStateDeviceNode
                  key={cam.serial}
                  name={cam.name}
                  serial={cam.serial}
                  state={cam.state}
                  pinned={getIsCameraPinned?.(cam.serial) || false}
                  onPin={(pinned) => onPinCamera(cam, pinned)}
                  isSelected={selectedSerial === cam.serial}
                  onSelect={() => onSelectCamera(cam)}
                  allowRemove={allowRemove}
                  camera={allowEdit ? cam : undefined}
                  variant="all"
                  onUpdate={onUpdateCamera}
                  onUpdateStream={onUpdateStream}
                  onRemove={() => onRemoveCamera(cam.serial)}
                  showAction={variantPage !== BACKUP_STORAGE_PAGE}
                  variantPage={variantPage}
                />
              )) : (
                <div className='flex justify-center w-full no-data'>
                  {/* <Empty
                    image={NodataIcon}
                    imageStyle={{
                      height: 40,
                    }}
                    description={<span className='text-brand text-base'>{t('No data')}</span>}
                  /> */}
                </div>
              )}
            </React.Fragment>
          )}
        </div>
        {
          finalTotal > 0 && (
            <div className="camera-list-pagination">
              <Pagination
                size="small"
                showLessItems
                showSizeChanger={false}
                total={finalTotal}
                current={finalCurrentPage}
                pageSize={finalPageSize}
                onChange={handlePageChange}
              />
            </div>
          )
        }
      </div>
    </>
  );
};

export const AllCamerasRootGroup = ({
  getIsCameraPinned,
  onPinCamera,
  selectedSerial,
  onSelectCamera,
  namespace,
  onUpdateCamera,
  onUpdateStream,
  updateReturn,
  variantPage,
  customCameras
}) => {
  const { data, isLoading, send, patch } = useListAllDevicesByPage();
  const timeRequestRef = useRef(Date.now());
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: variantPage === 'camera-v2' ? 6 : 15,
  });
  const dispatch = useDispatch()

  const onRemoveCamera = (serial) => {
    console.log('onRemoveCamera =>>>', serial);
    let data = {
      serial,
      namespace,
    };
    let dataObj = {
      appServiceType: SERVICE.REMOVE_DEVICE,
      requestId: new Date().getTime(),
      body: JSON.stringify(data),
    };

    dispatch(socketEmitEvent(dataObj));
    setTimeout(() => {
      send({
        namespace,
        tag: 'camera-list',
        deviceType: 'camera',
        page: pagination.current - 1,
        size: pagination.pageSize,
        timeRequest: timeRequestRef.current,
      });
    }, 10)
  };

  useEffect(() => {
    send({
      namespace,
      tag: 'camera-list',
      deviceType: 'camera',
      page: pagination.current - 1,
      size: pagination.pageSize,
      timeRequest: timeRequestRef.current,
    });
  }, [send, namespace, pagination.pageSize, timeRequestRef, pagination]);

  useEffect(() => {
    if (updateReturn && updateReturn.isSuccess) {
      patch((prev) => {
        if (!prev) {
          return prev;
        }

        if (!prev.devices.find((d) => d.serial === updateReturn.data.serial)) {
          return prev;
        }

        return {
          ...prev,
          devices: prev.devices.map((d) =>
            d.serial === updateReturn.data.serial
              ? {
                ...d,
                ...updateReturn.data,
              }
              : d
          ),
        };
      });
    }
  }, [updateReturn, patch]);

  return (
    <AllCamerasV1
      cameras={data?.devices || []}
      currentPage={pagination.current}
      pageSize={pagination.pageSize}
      onPageChange={(page) => {
        console.log('onPageChange: ', page);
        setPagination({ ...pagination, current: page })
      }}
      isLoading={isLoading}
      total={data?.total || 0}
      getIsCameraPinned={getIsCameraPinned}
      onPinCamera={onPinCamera}
      selectedSerial={selectedSerial}
      onSelectCamera={onSelectCamera}
      namespace={namespace}
      allowEdit
      onUpdateCamera={onUpdateCamera}
      onUpdateStream={onUpdateStream}
      onRemoveCamera={onRemoveCamera}
      variantPage={variantPage}
      customCameras={customCameras}
    />
  );
};

export const AllCamerasPinnedGroup = ({
  getIsCameraPinned,
  onPinCamera,
  selectedSerial,
  onSelectCamera,
  namespace,
  cameras,
  onUpdateCamera,
  onUpdateStream,
  variantPage
}) => {
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 15,
  });

  const camerasToRender = useMemo(() => {
    return cameras.slice(
      (pagination.current - 1) * pagination.pageSize,
      pagination.current * pagination.pageSize
    );
  }, [cameras, pagination]);

  return (
    <AllCamerasV1
      cameras={camerasToRender}
      currentPage={pagination.current}
      pageSize={pagination.pageSize}
      onPageChange={(page) => setPagination({ ...pagination, current: page })}
      isLoading={false}
      total={cameras.length}
      getIsCameraPinned={getIsCameraPinned}
      onPinCamera={onPinCamera}
      selectedSerial={selectedSerial}
      onSelectCamera={onSelectCamera}
      namespace={namespace}
      allowEdit
      onUpdateCamera={onUpdateCamera}
      onUpdateStream={onUpdateStream}
      onRemoveCamera={console.log}
      variantPage={variantPage}
    />
  );
};
