import axios from 'axios';

export const downloadFile = ({ url, fileName, isSaveAs, onProgress, onFetched, onError }) => {
  if (isSaveAs) {
    return axios
      .get(url, {
        headers: {
          'Content-Type': 'application/octet-stream',
        },
        responseType: 'blob',
        onDownloadProgress: (progressEvent) => {
          if (onProgress && progressEvent.total) {
            const percentCompleted = Math.round(
              (progressEvent.loaded * 100) / progressEvent.total
            );
            onProgress({
              loaded: progressEvent.loaded,
              total: progressEvent.total,
              percent: percentCompleted,
              fileName,
            });
          }
        },
      })
      .then((response) => {
        console.log('downloadFile - response: ', response);
        const a = document.createElement('a');
        const blobUrl = window.URL.createObjectURL(response.data);
        a.href = blobUrl;
        a.download = fileName;
        a.click();

        setTimeout(() => window.URL.revokeObjectURL(blobUrl), 100);

        if (typeof onFetched === 'function') {
          onFetched(fileName);
        }

        return { success: true, fileName };
      })
      .catch((err) => {
        console.log('Download file error', err);
        if (typeof onError === 'function') {
          onError(err, fileName);
        }
        throw err;
      });
  } else {
    const buttonElement = document.createElement('a');
    buttonElement.href = url;
    buttonElement.click();

    if (typeof onFetched === 'function') {
      onFetched(fileName);
    }

    return Promise.resolve({ success: true, fileName });
  }
};