import { Button, Col, Form, Input, Modal, Row, Switch, Table } from "antd";
import React, { useCallback, useEffect, useState } from "react";
import * as SERVICE from '@/constants/service.types'
import { useDispatch, useSelector } from "react-redux";
import { activeLicenseServiceReturn, getLicenseInfoServiceReturn, openMessage, socketEmitEvent } from "@/redux/actions";
import { useTranslation } from "react-i18next";
import { ReactComponent as S3Icon } from '@/assets/icons/s3-storage-icon.svg'
import { ReactComponent as DropboxIcon } from '@/assets/icons/dropbox-storage-icon.svg'
import { ReactComponent as NasIcon } from '@/assets/icons/nas-storage-icon.svg'
import { ReactComponent as GGDrivcIcon } from '@/assets/icons/gg-drive-storage-icon.svg'
import regex from '@/constants/system.keys'

import './index.scss'
import { NOTIFIES } from "@/constants/system.keys";
import moment from "moment";

export const EditServiceComponent = ({ camera, namespace }) => {
  const [form] = Form.useForm();
  const dispatch = useDispatch();
  const { services, totalCamera, devicesActiveOfServices, isAuth, checkLicense, activeLicense } = useSelector(state => state)
  const { t } = useTranslation()
  const [selectedService, setSelectedService] = useState(null)
  const [timeRequest, setTimeRequest] = useState(new Date().getTime());
  const [isLoadCheckLicense, setIsLoadCheckLicense] = useState(false);
  const [licenseInfo, setLicenseInfo] = useState();
  const [license, setLicense] = useState();
  const [activeLicenseReturn, setActiveLicenseReturn] = useState(null);
  const [servicesToRender, setServicesToRender] = useState([]);


  useEffect(() => {
    if (services && services?.length > 0) {
      setServicesToRender(services?.slice(0, 5))
    }
  }, [services]);


  // useEffect(() => {
  //   const timeRequest = new Date().getTime();
  //   let data = {
  //     serviceId: 20,
  //     timeRequest,
  //     namespace,
  //     page: 0,
  //     size: totalCamera || 100
  //   };
  //   console.log('data: ', data);
  //   let dataObj = {
  //     appServiceType: SERVICE.LIST_DEVICE_ACTIVE_SERVICE_ID,
  //     requestId: timeRequest,
  //     body: JSON.stringify(data),
  //   };
  //   return dispatch(socketEmitEvent(dataObj));
  // }, [dispatch, namespace, totalCamera]);

  useEffect(() => {
    let data = {
      namespace,
    };
    let dataObj = {
      appServiceType: SERVICE.LIST_SERVICE,
      requestId: new Date().getTime(),
      body: JSON.stringify(data),
    };
    dispatch(socketEmitEvent(dataObj));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [namespace]);

  const onFinish = (value) => {
    console.log('value: ', value);
  };


  const onToggleService = (checked, item) => {
    console.log('checked: ', checked);
    setSelectedService(checked ? item : null)
    setServicesToRender(prev => prev?.map(item1 => item1?.id === item?.id ? { ...item1, active: checked } : item1))
  };


  const onCheckCode = useCallback(
    (licenseCode) => {
      setIsLoadCheckLicense(true);
      if (isAuth && licenseCode) {
        let data = {
          licenseCode,
          namespace,
        };
        const dataTimeRequest = new Date().getTime();
        setTimeRequest(dataTimeRequest);
        let dataObj = {
          appServiceType: SERVICE.GET_LICENSE_INFO_SERVICE,
          requestId: dataTimeRequest,
          body: JSON.stringify(data),
        };
        dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, isAuth, namespace]
  );


  const onActiveDevice = useCallback(() => {
    let data = {
      serviceId: selectedService.id,
      accountId: -1,
      licenseCode: license.licenseCode,
      namespace,
      deviceSerial: camera?.serial,
    };
    console.log('ACTIVE_LICENSE_SERVICE - data: ', data);
    let dataObj = {
      appServiceType: SERVICE.ACTIVE_LICENSE_SERVICE,
      requestId: new Date().getTime(),
      body: JSON.stringify(data),
    };
    dispatch(socketEmitEvent(dataObj));
  }, [camera, dispatch, license, namespace, selectedService]);


  useEffect(() => {
    if (checkLicense) {
      console.log('checkLicense: ', checkLicense);
      dispatch(getLicenseInfoServiceReturn(null))
      if (checkLicense.result === -13) {
        form.setFields([
          {
            name: 'checkCode',
            errors: [t('Invalid license!')],
          },
        ]);
        setLicenseInfo(null);
      } else if (checkLicense.data) {
        const { size, numberActive, endAt, licenseCode, serviceId } =
          JSON.parse(checkLicense.data);
        if (selectedService && serviceId !== selectedService.id) {
          form.setFields([
            {
              name: 'checkCode',
              errors: [t('License not found')],
            },
          ]);
          setLicenseInfo(null);
        } else if (new Date().getTime() > new Date(endAt).getTime()) {
          form.setFields([
            {
              name: 'checkCode',
              errors: [t('License expired')],
            },
          ]);
          setLicenseInfo({
            ...JSON.parse(checkLicense.data),
          });
        } else if (numberActive >= size) {
          form.setFields([
            {
              name: 'checkCode',
              errors: [t('The license has used up its activation turn!')],
            },
          ]);
          setLicenseInfo({
            ...JSON.parse(checkLicense.data),
          });
        } else {
          setLicense({
            licenseCode: licenseCode,
            size: size,
            numberActive: numberActive,
          });
          setLicenseInfo({
            ...JSON.parse(checkLicense.data),
          });
        }
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [checkLicense, form, selectedService]);

  useEffect(() => {
    if (isAuth && license && selectedService && license.numberActive < license.size) {
      onActiveDevice()
    }
  }, [isAuth, license, onActiveDevice, selectedService]);

  useEffect(() => {
    if (activeLicense) {
      console.log('activeLicense: ', activeLicense);
      setActiveLicenseReturn(activeLicense)
      setIsLoadCheckLicense(false);
      if (activeLicense?.result === 1) {
        setServicesToRender(prev => prev?.map(item => item?.id === JSON.parse(activeLicense?.data || '{}')?.serviceId ? { ...item, active: true } : item))
        setSelectedService(null)
        setLicense(null);
        setLicenseInfo(null);
        dispatch(activeLicenseServiceReturn(null))
      } else {
        form.setFields([
          {
            name: 'checkCode',
            errors: [t('Active license failed!')],
          },
        ]);
      }
    }
  }, [activeLicense]);

  const getActiveServiceState = useCallback((serviceId) => {
    console.log('serviceId: ', serviceId);
    console.log('activeLicenseReturn: ', activeLicenseReturn);
    console.log('selectedService: ', selectedService);
    // if (!activeLicenseReturn) {
    //   return selectedService?.id === serviceId
    // }

    return activeLicenseReturn?.result === 1
  }, [activeLicenseReturn, selectedService])

  useEffect(() => {
    return () => {
      dispatch(getLicenseInfoServiceReturn(null))
      dispatch(activeLicenseServiceReturn(null))
      form.resetFields();
      setLicense(null);
      setLicenseInfo(null);
      setSelectedService(null);
      setIsLoadCheckLicense(false);
      setTimeRequest(new Date().getTime());
      setActiveLicenseReturn(null);
    }
  }, [])

  return (
    <>
      <div className="edit-service-component">
        <div className="service-list">
          {
            servicesToRender?.map(item => (
              <div key={item?.id} className="service-item">
                <div className="service-item-left">
                  <img src={item?.iconUrl} alt="" />
                  <div className="service-item-info">
                    <div className="service-name">
                      <span>{item?.name}</span>
                    </div>
                    <div className="service-desc">
                      <span className="italic">No license</span>
                    </div>
                  </div>
                </div>
                <div className="service-item-right">
                  <Switch checked={item?.active} onChange={(value) => onToggleService(value, item)} />
                </div>
              </div>
            ))
          }
        </div>
      </div>
      <Modal
        title={t(selectedService?.name || 'Active service')}
        visible={Boolean(selectedService)}
        onCancel={() => {
          setSelectedService(null)
          form.resetFields();
          setLicense(null);
          setLicenseInfo(null);
        }}
        footer={null}
        okButtonProps={{ style: { display: 'none' } }}
      >
        <div className="flex flex-col gap-4">
          <Form
            form={form}
            layout="inline"
            name="register-service"
            onFinish={(values) => onCheckCode(values.checkCode.trim())}
          >
            <Row style={{ width: '100%' }}>
              <Col span={18}>
                <Form.Item
                  style={{ width: '97%' }}
                  name="checkCode"
                  rules={[
                    {
                      required: true,
                      message: t('Please enter the license code!'),
                    },
                    {
                      pattern: regex.isurl,
                      message: t('Please enter the license code!'),
                    },
                    {
                      max: 80,
                      message: t('Please input up to 80 characters!'),
                    },
                  ]}
                >
                  <Input
                    style={{ width: '100%' }}
                    placeholder="Enter license Code"
                  />
                </Form.Item>
              </Col>
              <Col span={6}>
                <Form.Item style={{ width: '100%' }}>
                  <Button
                    type="primary"
                    style={{ width: '100%' }}
                    htmlType="submit"
                    loading={isLoadCheckLicense}
                  >
                    {t('Active')}
                  </Button>
                </Form.Item>
              </Col>
            </Row>
          </Form>
          {/* {license && license.licenseCode && (
            <div className="license-info">
              {t('License')} <span>{license.licenseCode}</span> {t('has')}
              <span>
                {` ${license.size - license.numberActive}/${license.size} `}
              </span>
              {t('of the remaining activation.')}
            </div>
          )} */}
          {/* {licenseInfo?.licenseCode && (
            <>
              <Table
                pagination={false}
                scroll={{ y: 155 }}
                style={{ border: '1px solid #303030' }}
                size="small"
                columns={[
                  {
                    title: t('Create date'),
                    dataIndex: 'startAt',
                    key: 'startAt',
                    align: 'center',
                    render: (time) => moment(time).format('DD/MM/YYYY'),
                  },
                  {
                    title: t('Activated'),
                    dataIndex: 'numberActive',
                    key: 'numberActive',
                    align: 'center',
                    render: (numberActive, row) =>
                      `${numberActive ?? 0}/${licenseInfo.size ?? 0}`,
                  },
                  {
                    title: t('Duration'),
                    dataIndex: 'duration',
                    key: 'duration',
                    align: 'center',
                  },
                ]}
                dataSource={licenseInfo ? [licenseInfo] : []}
              />
              <div className="mt-2 flex justify-end">
                <Button
                  type="primary"
                  onClick={onActiveDevice}
                  loading={isLoadActiveLicenseNamespace}
                >
                  {t('Active')}
                </Button>
              </div>
            </>
          )} */}
        </div>
      </Modal >

    </>
  )
}