import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import * as SERVICE from '../../../constants/service.types';
import * as ACTIONS from '../../../redux/actions';
import { socketEmitEvent } from '../../../redux/actions';
import { Empty, List, Row, Select, Spin } from 'antd';
import { LoadingOutlined } from '@ant-design/icons';
import IconNotificationOff from '../../../assets/icons/notification_off.svg';
import { useTranslation } from 'react-i18next';
import InfiniteScroll from 'react-infinite-scroller';

import '../index.scss'
import { NOTIFICATION_TYPE } from '@/constants/notification.keys';
import NotificationCard from './NotificationCard';
import { getNotificationFilter } from '@/redux/notification/reducer';
import Spinner from '@/components/Spinner';

const { Option } = Select;

const NotificationTab = ({ data, onLoadMore = () => { }, loading }) => {
    const { t } = useTranslation();
    const dispatch = useDispatch();
    const [isLoadingMore, setIsLoadingMore] = useState(false)
    const [hasMore, setHasMore] = useState(true)
    const [open, setOpen] = useState(false)
    const [percent, setPercent] = useState(0)
    const [dataNotifications, setDataNotification] = useState([])
    const {
        isAuth,
        namespace,
    } = useSelector((state) => state);
    const notificationFilter = useSelector(getNotificationFilter())

    useEffect(() => {
        if (percent === 100) {
            setTimeout(() => {
                setPercent(0)
            }, 1000);
        }
    }, [percent]);
    useEffect(() => {
        if (loading && (!data || data.length === 0)) {
            setDataNotification([]);
        } else if (data) {
            setDataNotification(data);
        }
    }, [data, loading]);

    const renderLoading = useMemo(() => {
        const temple = isLoadingMore && hasMore && (
            <div className="demo-loading-container" style={{ display: "flex", justifyContent: 'center' }}>
                <Spin indicator={<LoadingOutlined style={{ fontSize: 24 }} spin />} />
            </div>
        )
        return temple
    }, [isLoadingMore, hasMore])

    const onHandleLoadMore = useCallback((val) => {
        console.log('val: ', val);
        setIsLoadingMore(true)
        if (isAuth === 1 && namespace) {
            let requestId = new Date().getTime();
            let data = {
                timeRequested: requestId,
                page: val,
                namespace,
            };
            let dataObj = {
                appServiceType: SERVICE.LIST_NOTIFICATION,
                requestId,
                body: JSON.stringify(data),
            };
            setTimeout(() => {
                dispatch(socketEmitEvent(dataObj));
                if (notificationFilter?.taskStatus && onLoadMore) {
                    console.log("on load more");
                    onLoadMore(notificationFilter?.taskStatus, val)
                }
                setIsLoadingMore(false);
            }, 1000);
        }
    }, [isLoadingMore, isAuth, namespace, dispatch, notificationFilter, onLoadMore])

    return (
        <div className="notification-tab-content">
            {loading ? (
                <Spinner />
            ) : dataNotifications && dataNotifications.length > 0 ? (
                <InfiniteScroll
                    initialLoad={false}
                    pageStart={0}
                    loadMore={onHandleLoadMore}
                    hasMore={!isLoadingMore && hasMore}
                    useWindow={false}
                    threshold={100}
                >
                    <List
                        id="list_item_notification"
                        itemLayout="horizontal"
                        dataSource={[...dataNotifications]}
                        renderItem={(item) => (
                            <List.Item>
                                <NotificationCard notification={item} />
                            </List.Item>
                        )}
                    />
                    {renderLoading}
                </InfiniteScroll>
            ) : (
                <Empty
                    style={{ margin: 80 }}
                    image={IconNotificationOff}
                    imageStyle={{ height: 80 }}
                    description={<span>{t('No Notifications!')}</span>}
                />
            )}
        </div>
    );

};

export default NotificationTab;