import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import { Button, Input, Modal } from 'antd';
import { DownloadOutlined } from '@ant-design/icons';
import { useTranslation } from 'react-i18next';
import {
  ACCOUNT_STATUS,
  DECODED_ACCESS_TOKEN,
  NAMESPACE,
  NOTIFIES,
} from '@/constants/system.keys';
import { getExportReportsApi } from '@/api/customerApi';
import { openMessage } from '@/redux/actions';
import storageService from '@/services/storage.service';
import AddMemberSteps from '../Modals/AddMemberSteps'
import { requestSocketPromiseWithTimeout } from '@/socket/query'
import { prepareBody, parseResponseBody } from '@/socket/query'
import * as SERVICE from '@/constants/service.types';

const addMember = async ({ namespace, ...rest }) => {
  const body = {
    namespace,
    ...rest,
  };

  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.ADD_MEMBER,
    body: prepareBody(body),
  });

  return parseResponseBody(response);
};

export const Header = ({ onSearchMember, namespace, refetchAccountByNamespace, updateMemberConfig }) => {
  const { t } = useTranslation();
  const [visibleAddMember, setVisibleAddMember] = useState(false);
  const [isLoadingExport, setIsLoadingExport] = useState(false);
  const [keyMember, setKeyMember] = useState(Math.random());
  const [fileData, setFileData] = useState([]);

  const onDownloadMember = async () => {
    try {
      setIsLoadingExport(true);
      const token =
        storageService.getInternalStorageByKey(DECODED_ACCESS_TOKEN);
      const namespace = localStorage.getItem(NAMESPACE);
      const dataQuery = {
        namespace,
        customerNamespace: namespace,
        isDownload: 1,
      };
      const dataRes = await getExportReportsApi(
        token,
        { namespace },
        dataQuery
      );
      setTimeout(() => {
        if (dataRes?.data) {
          const buttonElement = document.createElement('a');
          buttonElement.href = `data:text/csv;charset=utf-8,${encodeURI(
            dataRes.data
          )}`;
          buttonElement.target = '_blank';
          buttonElement.download = `report-members.csv`;
          buttonElement.click();
        } else {
          openMessage(NOTIFIES.WARNING, 'No data export');
        }
        setIsLoadingExport(false);
      }, 800);
    } catch (error) {
      setTimeout(() => {
        setIsLoadingExport(false);
        openMessage(
          NOTIFIES.WARNING,
          error?.response?.data?.message ?? 'Internal server error'
        );
      }, 800);
    }
  };

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) {
      return;
    }
    const reader = new FileReader();

    reader.onload = (event) => {
      const data = new Uint8Array(event.target.result);
      const workbook = XLSX.read(data, { type: 'array' });
      const worksheet = workbook.Sheets[workbook.SheetNames[0]];

      const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });
      const formattedData = jsonData.slice(1).map((row) => ({
        phonenumber: row[0],
        namespace: namespace,
        fullName: row[1],
        email: row[2],
        position: row[3],
        role: row[4],
        detailRoles: row[5],
        username: row[6],
        password: row[7],
      }));

      setFileData(formattedData);
    };

    reader.readAsArrayBuffer(file);
    e.target.value = '';
  };

  const onAddMember = (requestId, values) => {
    const {
      phonenumber,
      namespace,
      fullName,
      email,
      role,
      detailRoles,
      position,
      authMethod,
      username,
      password,
      enableWatermark,
      accountStatus,
      expireTime,
      externalUserId
    } = values;
    const normalizedExternalUserId =
      externalUserId === null || externalUserId === undefined
        ? ''
        : externalUserId.toString().trim();
    const data = {
      username,
      password,
      phonenumber,
      namespace,
      authMethod,
      fullName,
      email,
      role,
      detailRoles:
        (Array.isArray(detailRoles) ? detailRoles?.join(';') : detailRoles) ||
        '',
      expireTime: expireTime ? expireTime.format('YYYY-MM-DD HH:mm:ss') : '',
      enableWatermark: enableWatermark ? 1 : 0,
      accountStatus: accountStatus
        ? ACCOUNT_STATUS.ACTIVE
        : ACCOUNT_STATUS.BLOCKED,
      position: position || '',
      externalUserId: normalizedExternalUserId || '',
    };

    console.log("🚀 ~ onAddMember ~ data:", data)
    addMember(data).then(() => {
      refetchAccountByNamespace();
    });
  };

  const submitFileUpload = () => {
    let index = 0;
    const interval = setInterval(() => {
      if (index < fileData.length) {
        const requestId = new Date().getTime();
        onAddMember(requestId, fileData[index]);
        index++;
      } else {
        clearInterval(interval);
      }
    }, 1000);
  };

  return (
    <>
      <Modal
        width={700}
        visible={visibleAddMember}
        title={t('Add new member')}
        onCancel={() => {
          setVisibleAddMember(false);
          setKeyMember(Math.random());
        }}
        footer={null}
      >
        {visibleAddMember && (
          <AddMemberSteps
            setFileData={setFileData}
            fileData={fileData}
            keyMember={keyMember}
            handleFileUpload={handleFileUpload}
            namespace={namespace}
            onAddMember={onAddMember}
            handleAddMemberDone={console.log}
            onConfigTimeoutMember={updateMemberConfig}
            submitFileUpload={submitFileUpload}
            onCloseModalAddMember={() => {
              setVisibleAddMember(false);
              setKeyMember(Math.random());
            }}
          />
        )}
      </Modal>
      <div className="flex justify-end mb-2 gap-4">
        <Input.Search
          placeholder="Search"
          onSearch={onSearchMember}
          allowClear
          style={{ width: '240px' }}
          className="mr-auto"
        />
        <Button onClick={() => setVisibleAddMember(true)}>
          {t('Add member')}
        </Button>

        <Button
          type="primary"
          onClick={onDownloadMember}
          icon={<DownloadOutlined />}
          loading={isLoadingExport}
        >
          {t('Download reports')}
        </Button>
      </div>
    </>
  );
};
