/* eslint-disable react-hooks/exhaustive-deps */
import React, { useCallback, useEffect, useState, useRef } from "react";
import { Divider, Tabs } from "antd";
import { useTranslation } from "react-i18next";
import NotificationIcon from "../../../assets/icons/notification.svg";
import NotificationFilter from "./NotificationFilter";
import { useDispatch, useSelector } from "react-redux";
import * as SERVICE from "@/constants/service.types";
import { getFilterNotificationReturn, socketEmitEvent } from "@/redux/actions";
import {
  AI_WARNING_EVENT_TYPE,
  NOTIFICATION_LEVEL,
  NOTIFICATION_TASK_STATUS,
  NOTIFICATION_TYPE,
} from "@/constants/notification.keys";
import moment from "moment";
import NotificationTab from "./NotifiactionTab";
import { getNotificationFilter, getJustUpdatedNotification } from "@/redux/notification/reducer";
import { setNotificationFilter, setJustUpdatedNotifications, resetNotificationFilter } from "@/redux/notification/action";
import colorDark from '@/assets/colors/dark'

const { TabPane } = Tabs;

const orderByDate = (arr) => {
  return [...arr].sort(
    (a, b) => moment(b.createdAt).valueOf() - moment(a.createdAt).valueOf()
  );
};

const mergeUniqueById = (arr1, arr2) => {
  if (!Array.isArray(arr1) && !Array.isArray(arr2)) return []
  if (!Array.isArray(arr1)) return orderByDate([...arr2])
  if (!Array.isArray(arr2)) return orderByDate([...arr1])
  return orderByDate(Array.from(
    new Map([...arr1, ...arr2].map((item) => [item.id, item])).values()
  ));
};

const NotificationsV2 = () => {
  const { t } = useTranslation();
  const dispatch = useDispatch();
  const { isAuth, namespace, notifications, filterNotifications } = useSelector(
    (state) => state
  );

  const notificationFilter = useSelector(getNotificationFilter());
  const justUpdatedNotifications = useSelector(getJustUpdatedNotification());

  const [currentTab, setCurrentTab] = useState("1");
  const [loading, setLoading] = useState(false);
  const loadingTimer = useRef(null);

  const tabCacheRef = useRef({
    a2l: [],
    waiting: [],
    processing: [],
    completed: []
  });

  const tabLoadedRef = useRef({
    all: false,
    waiting: false,
    processing: false,
    completed: false
  });

  const [tabsData, setTabsData] = useState({
    all: [],
    waiting: [],
    processing: [],
    completed: []
  });

  const [overViewData, setOverViewData] = useState({
    countAiEvent: 0,
    countVeryHighLevel: 0,
    countWaitingStatus: 0,
    aiEvents: [],
    veryHighEvents: [],
    waitingEvents: []
  });

  const filterNotificationsManually = useCallback((data) => {
    let result = [...data];

    if (notificationFilter?.taskStatus && currentTab !== "1") {
      result = result.filter(item => item?.taskStatus === notificationFilter.taskStatus);
    }

    if (Number.isInteger(notificationFilter?.level) && notificationFilter.level >= 0) {
      result = result.filter(item => item?.level === notificationFilter.level);
    }

    if (notificationFilter?.searchInput) {
      result = result.filter(item =>
        item?.content?.toLowerCase()?.includes(notificationFilter.searchInput?.toLowerCase())
      );
    }

    return orderByDate(result);
  }, [notificationFilter, currentTab]);

  useEffect(() => {
    if (filterNotifications?.result === 1) {
      const newData = JSON.parse(filterNotifications?.data)?.notifications || [];
      const taskStatus = notificationFilter?.taskStatus;

      const tabKey = (() => {
        if (!taskStatus) return 'all';
        if (taskStatus === NOTIFICATION_TASK_STATUS.TASK_RECEIVED) return 'waiting';
        if (taskStatus === NOTIFICATION_TASK_STATUS.TASK_IN_PROCESS) return 'processing';
        if (taskStatus === NOTIFICATION_TASK_STATUS.TASK_DONE) return 'completed';
        return 'all';
      })();

      tabCacheRef.current[tabKey] = mergeUniqueById(
        tabCacheRef.current[tabKey],
        newData
      );

      tabLoadedRef.current[tabKey] = true;

      updateTabsDataFromCache();
    }
  }, [filterNotifications, notificationFilter]);

  const updateTabsDataFromCache = useCallback(() => {
    const applyFilter = (items) => {
      return items.filter(item =>
        (notificationFilter?.level >= 0 ? item.level === notificationFilter.level : true) &&
        (notificationFilter?.searchInput
          ? item.content?.toLowerCase()?.includes(notificationFilter.searchInput.trim().toLowerCase())
          : true)
      );
    };

    const baseNotifications = notifications && Array.isArray(notifications) ? notifications : [];

    let allData = mergeUniqueById(baseNotifications, tabCacheRef.current.all);
    if (justUpdatedNotifications && justUpdatedNotifications?.length > 0 && currentTab === "1") {
      allData = mergeUniqueById(allData, justUpdatedNotifications);
    }

    tabCacheRef.current.all = allData;

    const waitingData = applyFilter(
      mergeUniqueById(
        tabCacheRef.current.waiting,
        allData.filter(item => item.taskStatus === NOTIFICATION_TASK_STATUS.TASK_RECEIVED)
      )
    );

    const processingData = applyFilter(
      mergeUniqueById(
        tabCacheRef.current.processing,
        allData.filter(item => item.taskStatus === NOTIFICATION_TASK_STATUS.TASK_IN_PROCESS)
      ).map(item => ({ ...item, status: 3 }))
    );

    const completedData = applyFilter(
      mergeUniqueById(
        tabCacheRef.current.completed,
        allData.filter(item => item.taskStatus === NOTIFICATION_TASK_STATUS.TASK_DONE)
      ).map(item => ({ ...item, status: 3 }))
    );

    setTabsData({
      all: filterNotificationsManually(allData),
      waiting: filterNotificationsManually(waitingData),
      processing: filterNotificationsManually(processingData),
      completed: filterNotificationsManually(completedData),
    });
  }, [notifications, justUpdatedNotifications, currentTab, notificationFilter, filterNotificationsManually]);

  useEffect(() => {
    updateTabsDataFromCache();
  }, [notifications, notificationFilter, justUpdatedNotifications, updateTabsDataFromCache]);

  useEffect(() => {
    if (!notifications) return;

    const overview = notifications.reduce(
      (acc, item) => {
        if (item.level === NOTIFICATION_LEVEL.VERY_HIGH) {
          acc.countVeryHighLevel += 1;
        }
        if (AI_WARNING_EVENT_TYPE.includes(item.type)) {
          acc.countAiEvent += 1;
        }
        if (item.taskStatus === NOTIFICATION_TASK_STATUS.TASK_RECEIVED) {
          acc.countWaitingStatus += 1;
        }
        return acc;
      },
      {
        countAiEvent: 0,
        countVeryHighLevel: 0,
        countWaitingStatus: 0
      }
    );

    const aiEvents = notifications?.filter(item => AI_WARNING_EVENT_TYPE.includes(item?.type?.toLowerCase()?.trim()))
    const veryHighEvents = notifications?.filter(item => item?.level === NOTIFICATION_LEVEL.VERY_HIGH)
    const waitingEvents = notifications?.filter(item => item?.taskStatus === NOTIFICATION_TASK_STATUS.TASK_RECEIVED)

    setOverViewData(prev => ({
      ...prev,
      ...overview,
      aiEvents: mergeUniqueById(prev.aiEvents, aiEvents),
      veryHighEvents: mergeUniqueById(prev.veryHighEvents, veryHighEvents),
      waitingEvents: mergeUniqueById(prev.waitingEvents, waitingEvents),
    }));
  }, [notifications]);

  useEffect(() => {
    if (isAuth === 1 && namespace) {
      const requestId = Date.now();
      const data = { timeRequested: requestId, namespace };
      dispatch(
        socketEmitEvent({
          appServiceType: SERVICE.MARK_READ_NOTIFICATION,
          requestId,
          body: JSON.stringify(data),
        })
      );
    }
  }, [dispatch, isAuth, namespace]);

  const onFilterNotification = useCallback(
    (taskStatus = "", input = "", isLoadMore = false, page = 0, size = 10) => {
      if (isAuth === 1 && namespace) {
        const requestId = Date.now();
        const data = {
          namespace,
          page,
          size,
          timeRequest: requestId,
          type: "",
          fromTime: moment(
            moment().subtract(1, "days").set({ hour: 0, minute: 0, second: 0 })
          ).valueOf(),
          toTime: moment().valueOf(),
        };

        if (taskStatus) data.taskStatus = taskStatus;
        if (input) data.input = input;

        if (!isLoadMore) {
          dispatch(setNotificationFilter({ searchInput: input }));
        }

        dispatch(
          socketEmitEvent({
            appServiceType: SERVICE.FILTER_NOTIFICATION,
            requestId,
            body: JSON.stringify(data),
          })
        );

        setLoading(true);
        clearTimeout(loadingTimer.current);
        loadingTimer.current = setTimeout(() => {
          setLoading(false);
        }, 20000);
      }
    },
    [dispatch, isAuth, namespace]
  );

  useEffect(() => {
    if (notificationFilter?.taskStatus) {
      const tabMap = {
        [NOTIFICATION_TASK_STATUS.TASK_RECEIVED]: "2",
        [NOTIFICATION_TASK_STATUS.TASK_IN_PROCESS]: "3",
        [NOTIFICATION_TASK_STATUS.TASK_DONE]: "4"
      };
      const newTab = tabMap[notificationFilter.taskStatus];
      if (newTab) setCurrentTab(newTab);
    } else {
      setCurrentTab('1')
    }
  }, [notificationFilter?.taskStatus]);

  const onChangeTab = useCallback((tab) => {
    if (tab === currentTab) return;

    setCurrentTab(tab);

    const taskStatusMap = {
      "2": NOTIFICATION_TASK_STATUS.TASK_RECEIVED,
      "3": NOTIFICATION_TASK_STATUS.TASK_IN_PROCESS,
      "4": NOTIFICATION_TASK_STATUS.TASK_DONE,
    };

    const selectedTaskStatus = taskStatusMap[tab] || null;

    const tabKeyMap = {
      "1": 'all',
      "2": 'waiting',
      "3": 'processing',
      "4": 'completed'
    };

    const tabKey = tabKeyMap[tab];

    if (!tabLoadedRef.current[tabKey] || tabCacheRef.current[tabKey].length === 0) {
      setLoading(true);
    }

    dispatch(getFilterNotificationReturn(null));

    if (selectedTaskStatus) {
      onFilterNotification(selectedTaskStatus, notificationFilter?.searchInput || "", false, 0);
    }

    dispatch(setNotificationFilter({ taskStatus: selectedTaskStatus }));
    dispatch(setJustUpdatedNotifications(null));
  }, [dispatch, onFilterNotification, currentTab, notificationFilter]);

  useEffect(() => {
    if (!loading) return;

    const hasData = (() => {
      switch (currentTab) {
        case "1": return tabsData.all.length > 0;
        case "2": return tabsData.waiting.length > 0;
        case "3": return tabsData.processing.length > 0;
        case "4": return tabsData.completed.length > 0;
        default: return false;
      }
    })();

    if (hasData) {
      setLoading(false);
      clearTimeout(loadingTimer.current);
    }
  }, [tabsData, currentTab, loading]);

  // useEffect(() => {
  //   if (notificationFilter?.searchInput) {
  //     onFilterNotification(notificationFilter?.taskStatus, notificationFilter?.searchInput, false);
  //   }
  // }, [notificationFilter?.searchInput, onFilterNotification]);

  useEffect(() => {
    return () => {
      dispatch(resetNotificationFilter())
      setLoading(false)
      clearTimeout(loadingTimer.current);
    };
  }, []);

  return (
    <>
      <div className="sticky top-0">
        <div className="flex items-center gap-3">
          <img src={NotificationIcon} alt="" className="w-12 h-12" />
          <div className="flex-1">
            <h2 className="text-foreground font-semibold m-0">
              {t("Alerts Center")}
            </h2>
            <p className="text-muted-foreground text-sm m-0">
              {t("Management and processing of warning system cameras")}
            </p>
          </div>
        </div>
        <div className="flex gap-2 mt-4">
          <div className="bg-purple-600 text-white px-3 py-2 rounded-lg text-center flex-1">
            <div className="flex items-center gap-1 justify-center">
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"
                viewBox="0 0 24 24" fill="none" stroke="currentColor"
                strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
                className="lucide lucide-sparkles w-4 h-4">
                <path d="M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z"></path>
                <path d="M20 2v4"></path>
                <path d="M22 4h-4"></path>
                <circle cx="4" cy="20" r="2"></circle>
              </svg>
              <span className="text-xl">{overViewData.aiEvents?.length}</span>
            </div>
            <div className="text-xs">{t('AI Events')}</div>
          </div>
          <div className="bg-red-600 text-white px-3 py-2 rounded-lg text-center flex-1" style={{ backgroundColor: `${colorDark.$noti_very_high}` }}>
            <div className="text-xl">{overViewData.veryHighEvents?.length}</div>
            <div className="text-xs">{t('Very High')}</div>
          </div>
          <div className="bg-gray-600 text-white px-3 py-2 rounded-lg text-center flex-1" style={{ backgroundColor: `${colorDark.$task_received}` }}>
            <div className="text-xl">{overViewData.waitingEvents?.length}</div>
            <div className="text-xs">{t('Awaiting processing')}</div>
          </div>
        </div>

        <Divider className="my-4 bg-gray-300" />
        <NotificationFilter onSearch={(taskStatus, input) => onFilterNotification(taskStatus, input, false)} />
      </div>

      <Tabs activeKey={currentTab} onChange={onChangeTab}>
        <TabPane tab={t("All")} key="1">
          <NotificationTab
            loading={loading}
            onLoadMore={(taskStatus, page, size) => onFilterNotification(taskStatus, notificationFilter?.searchInput || "", true, page, size)}
            data={tabsData.all}
          />
        </TabPane>
        <TabPane tab={t("Awaiting")} key="2">
          <NotificationTab
            loading={loading}
            onLoadMore={(taskStatus, page, size) => onFilterNotification(taskStatus, notificationFilter?.searchInput || "", true, page, size)}
            data={tabsData.waiting}
          />
        </TabPane>
        <TabPane tab={t("Processing")} key="3">
          <NotificationTab
            loading={loading}
            onLoadMore={(taskStatus, page, size) => onFilterNotification(taskStatus, notificationFilter?.searchInput || "", true, page, size)}
            data={tabsData.processing}
          />
        </TabPane>
        <TabPane tab={t("Complete")} key="4">
          <NotificationTab
            loading={loading}
            onLoadMore={(taskStatus, page, size) => onFilterNotification(taskStatus, notificationFilter?.searchInput || "", true, page, size)}
            data={tabsData.completed}
          />
        </TabPane>
      </Tabs>
    </>
  );
};

export default NotificationsV2;