import React, { useMemo } from "react";

import colorsDark from '../../../assets/colors/dark';
import { useTranslation } from "react-i18next";
import { Tag } from "antd";
import { NOTIFICATION_LEVEL, NOTIFICATION_TASK_STATUS } from "@/constants/notification.keys";

import './index.scss'

export const NotificationLevelTag = ({ level }) => {
    const { t } = useTranslation()
    const tagData = useMemo(() => {
        switch (level) {
            case NOTIFICATION_LEVEL.VERY_HIGH:
                return {
                    color: colorsDark.$noti_very_high,
                    text: 'Very High'
                }
            case NOTIFICATION_LEVEL.HIGH:
                return {
                    color: colorsDark.$noti_high,
                    text: 'High'
                }
            case NOTIFICATION_LEVEL.NORMAL:
                return {
                    color: colorsDark.$noti_normal,
                    text: 'Medium'
                }
            case NOTIFICATION_LEVEL.LOW:
                return {
                    color: colorsDark.$noti_low,
                    text: 'Low'
                }
            default:
                return {
                    color: colorsDark.$noti_low,
                    text: 'Low'
                }
        }
    }, [level])
    return (
        <Tag color={tagData?.color}>{t(tagData?.text)}</Tag>
    )
}

export const NotificationStatusTag = ({ taskStatus }) => {
    const { t } = useTranslation()

    const tagData = useMemo(() => {
        switch (taskStatus) {
            case NOTIFICATION_TASK_STATUS.TASK_RECEIVED:
                return {
                    color: colorsDark.$task_received,
                    text: 'Received'
                }
            case NOTIFICATION_TASK_STATUS.TASK_IN_PROCESS:
                return {
                    color: colorsDark.$task_in_process,
                    text: 'Processing'
                }
            case NOTIFICATION_TASK_STATUS.TASK_DONE:
                return {
                    color: colorsDark.$task_done,
                    text: 'Done'
                }
            default:
                return null
        }
    }, [taskStatus])
    if (!tagData) return <></>
    return (
        <Tag color={tagData?.color}>{t(tagData?.text)}</Tag>
    )
}