import React, { useMemo, useState } from 'react';
import { UsersTable } from './UserTable';
import { PermissionTable } from './PermissionTable';
import {
  parseResponseBody,
  prepareBody,
  requestSocketPromiseWithTimeout,
} from '@/socket/query';
import * as SERVICE from '@/constants/service.types';
import { openMessage } from '@/redux/actions';
import { NOTIFIES } from '@/constants/system.keys';

import './styles.scss';
import { useListDeviceByUser } from '../hooks';
import { Modal } from 'antd';
import { EditPermissionModal } from '../EditPermissionModal';

const updateSharePermission = async ({
  serials,
  accountId,
  namespace,
  groupId,
  deviceGroupId,
  permission,
}) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.UPDATE_SHARE_PERMISSION_USER,
    body: prepareBody({
      serials,
      accountId,
      namespace,
      groupId,
      deviceGroupId,
      permission,
    }),
  });

  return parseResponseBody(response);
};

const unsharePermission = async ({
  serials,
  groupId,
  namespace,
  accountId,
  deviceGroupId,
}) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.UN_SHARE_PERMISSION_USER,
    body: prepareBody({
      serials,
      groupId,
      namespace,
      accountId,
      deviceGroupId,
    }),
  });

  return parseResponseBody(response);
};
export const Members = ({ accounts, isLoadingAccounts, namespace }) => {
  const [state, setState] = useState({
    page: 1,
    size: 15,
    timeRequest: new Date().getTime(),
    selectedAccountId: null,
  });

  const { data: devicesData, isLoading: isLoadingDevices } =
    useListDeviceByUser({
      shareUserId: state.selectedAccountId,
      namespace,
      page: state.page - 1,
      size: state.size,
      timeRequest: state.timeRequest,
    });

  const onPageChange = (page) => {
    setState((prev) => ({
      ...prev,
      page,
    }));
  };

  const onSelectAccountId = (accountId) => {
    setState((prev) => ({
      page: 1,
      size: 15,
      selectedAccountId: accountId,
      timeRequest: new Date().getTime(),
    }));
  };

  console.log('devices', devicesData);

  const dataSource = useMemo(() => {
    const makeKey = (device) => {
      return `${device.serial}-${device.deviceGroup?.deviceGroupId || -1}-${
        device?.group?.groupId || -1
      }`;
    };

    return devicesData?.devices?.map((device) => ({
      ...device,
      key: makeKey(device),
    }));
  }, [devicesData]);

  const onRemovePermission = async (record) => {
    if (record?.group) {
      Modal.confirm({
        title: 'Unable to remove permission',
        content: `This permission is inherited from account group ${record.group.name}`,
        cancelButtonProps: {
          style: {
            display: 'none',
          },
        },
        okText: 'OK',
      });

      return;
    }

    Modal.confirm({
      title: 'Remove permission',
      content: 'Are you sure you want to remove permission?',
      onOk: async () => {
        await unsharePermission({
          serials: record.serial,
          groupId: record.group?.groupId || -1,
          namespace,
          accountId: state.selectedAccountId,
          deviceGroupId: record.deviceGroup?.deviceGroupId || -1,
        });

        console.log('body', record, {
          serials: record.serial,
          groupId: record.group?.groupId || -1,
          namespace,
          accountId: state.selectedAccountId,
          deviceGroupId: record.deviceGroup?.deviceGroupId || -1,
        });

        // reset data on this page if selected account id is the same
        setState((prev) => {
          if (prev.selectedAccountId !== state.selectedAccountId) {
            return prev;
          }

          return {
            ...prev,
            timeRequest: new Date().getTime(),
          };
        });

        openMessage(NOTIFIES.SUCCESS, 'Remove permission successfully');
      },
    });
  };

  const [recordToEdit, setRecordToEdit] = useState(null);
  const [recordToEditLoading, setRecordToEditLoading] = useState(null);

  const onEditPermission = (record) => {
    console.log('record', record);
    if (record?.group) {
      Modal.confirm({
        title: 'Unable to edit permission',
        content: `This permission is inherited from account group ${record.group.name}`,
        cancelButtonProps: {
          style: {
            display: 'none',
          },
        },
        okText: 'OK',
      });

      return;
    }

    setRecordToEdit(record);
  };

  const onSubmitEditPermission = (permission) => {
    setRecordToEditLoading(recordToEdit.key);
    console.log('BODY', {
      accountId: state.selectedAccountId || -1,
      namespace,
      deviceGroupId: recordToEdit.deviceGroup?.deviceGroupId || -1,
      groupId: recordToEdit.group?.groupId || -1,
      permission,
      serials: recordToEdit.serial,
    });

    updateSharePermission({
      accountId: state.selectedAccountId || -1,
      namespace,
      deviceGroupId: recordToEdit.deviceGroup?.deviceGroupId || -1,
      groupId: recordToEdit.group?.groupId || -1,
      permission,
      serials: recordToEdit.serial,
    }).then(
      () => {
        // remove if we just edited this record
        setRecordToEdit((prev) => {
          if (prev?.key === recordToEdit.key) {
            return null;
          }

          return prev;
        });

        // remove loading if we just edited this record
        setRecordToEditLoading((prev) => {
          if (prev === recordToEdit.key) {
            return null;
          }

          return prev;
        });

        setState((prev) => {
          if (prev.selectedAccountId !== state.selectedAccountId) {
            return prev;
          }

          return {
            ...prev,
            timeRequest: new Date().getTime(),
          };
        });

        openMessage(NOTIFIES.SUCCESS, 'Update permission successfully');
      },
      (error) => {
        openMessage(NOTIFIES.ERROR, 'Error when update permission');
      }
    );
  };

  return (
    <div className="og2-members-component">
      <div className="og2-members-left">
        <UsersTable
          accounts={accounts}
          isLoadingAccounts={isLoadingAccounts}
          selectedAccountId={state.selectedAccountId}
          onSelectAccountId={onSelectAccountId}
        />
      </div>
      <div className="og2-members-right">
        <PermissionTable
          selectedAccountId={state.selectedAccountId}
          namespace={namespace}
          dataSource={dataSource}
          isLoadingDevices={isLoadingDevices}
          pagination={state}
          onPageChange={onPageChange}
          onRemovePermission={onRemovePermission}
          onEditPermission={onEditPermission}
          total={devicesData?.total || 0}
        />
        {recordToEdit && (
          <EditPermissionModal
            defaultPermission={recordToEdit.permission}
            onCancel={() => setRecordToEdit(null)}
            onSubmit={onSubmitEditPermission}
            name={recordToEdit.name}
            isLoading={recordToEditLoading === recordToEdit.key}
          />
        )}
      </div>
    </div>
  );
};
