import {
  parseResponseBody,
  prepareBody,
  requestSocketPromiseWithTimeout,
} from '../../socket/query';
import * as SERVICE from '../../constants/service.types';
import { beeXLogger } from '@/helpers/logger';

export const getPlaybackTimes = async (input) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.LIST_PLAYBACK_ON_CLOUD,
    body: prepareBody(input),
  });

  return parseResponseBody(response);
};

export const getLinkStorageFileByTime = async (input, timeout = 0) => {
  beeXLogger.debug('GENERATE_LINK_STORAGE_FILE_BY_TIME - input: ', input);
  const response = await requestSocketPromiseWithTimeout(
    {
      appServiceType: SERVICE.GENERATE_LINK_STORAGE_FILE_BY_TIME,
      body: prepareBody(input),
    },
    {
      timeout,
    },
  );

  beeXLogger.debug(
    'GENERATE_LINK_STORAGE_FILE_BY_TIME - response ',
    parseResponseBody(response),
  );
  return parseResponseBody(response);
};

