import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useAdvanceSearch } from '@/hooks/socket/cameras';
import { debounce } from '@/untils/function';
import { LoadingOutlined } from '@ant-design/icons';
import { GroupNodeContainer } from './NodeContainer';
import { buildTree } from './advance-search-utils';
import { Button, Empty, Input, Spin } from 'antd';
import { useTranslation } from 'react-i18next';
import { AddFolderIcon } from '@/icons/AddFolder';
import NodataIcon from '../../../assets/icons/no-data-icon.svg'

export const AdvanceSearch = ({
  onSearchActiveChange,
  namespace,
  onRenameSuccess = () => { },
  onRemoveSuccess = () => { },
  onAddGroupSuccess = () => { },
  onAddMemberSuccess = () => { },
  onRemoveMemberSuccess = () => { },
  onAddGroup = () => { },
}) => {
  const { t } = useTranslation();
  const { send, data: searchData, patch: patchSearchData } = useAdvanceSearch();
  const [isSearching, setIsSearching] = useState(false);
  const [expandedMap, setExpandedMap] = useState({});
  const [isSearchActive, setIsSearchActive] = useState(false);

  const doSearch = useMemo(
    () =>
      debounce(async (value) => {
        await send({
          namespace,
          applicationType: 'account',
          input: value,
          timeRequest: Date.now(),
          page: 0,
          size: 20,
        });

        setIsSearching(false);
      }, 500),
    [send, namespace]
  );

  const onSearch = useCallback(
    (value) => {
      value = value.trim();
      if (!value) {
        setIsSearchActive(false);
        onSearchActiveChange(false);
        setIsSearching(false);
        return;
      }

      setIsSearchActive(true);
      onSearchActiveChange(true);
      setIsSearching(true);
      doSearch(value);
    },
    [doSearch]
  );

  const [searchTree, setSearchTree] = useState();

  useEffect(() => {
    if (searchData) {
      const tree = buildTree(searchData.records);
      if (!tree) return
      // expand all groups
      setExpandedMap(
        Object.keys(tree.groups).reduce((acc, groupId) => {
          acc[Number(groupId)] = true;
          return acc;
        }, {})
      );
      setSearchTree(tree);
    }
  }, [searchData]);

  const onExpand = useCallback((groupId, isExpanded) => {
    setExpandedMap((prev) => ({ ...prev, [groupId]: isExpanded }));
  }, []);

  const getIsExpanded = useCallback(
    (groupId) => {
      return expandedMap[groupId];
    },
    [expandedMap]
  );

  const getMembers = useCallback(
    (groupId) => {
      return Promise.resolve(
        searchTree?.accountsByGroupId[groupId]
          ?.map((accountId) => searchTree?.accounts[accountId])
          .filter(Boolean) || []
      );
    },
    [searchTree]
  );

  const getSubGroups = useCallback(
    (groupId) => {
      return Promise.resolve(
        searchTree?.subGroupsByGroupId[groupId]
          ?.map((subGroupId) => searchTree?.groups[subGroupId])
          .filter(Boolean) || []
      );
    },
    [searchTree]
  );

  const afterRenameSuccess = useCallback((groupId, newName) => {
    setSearchTree((prev) => {
      if (!prev) return undefined;

      const newSearchTree = { ...prev };

      newSearchTree.groups[groupId] = {
        ...newSearchTree.groups[groupId],
        name: newName,
      };

      return newSearchTree;
    });
  }, []);

  const afterRemoveSuccess = useCallback((groupId) => {
    setSearchTree((prev) => {
      if (!prev) return undefined;

      const newSearchTree = { ...prev };

      delete newSearchTree.groups[groupId];

      return newSearchTree;
    });
  }, []);

  const afterAddGroupSuccess = useCallback((parentId, newGroup) => {
    setSearchTree((prev) => {
      if (!prev) return undefined;

      const newSearchTree = { ...prev };

      newSearchTree.groups[newGroup.id] = newGroup;
      newSearchTree.accountsByGroupId[newGroup.id] = [];
      newSearchTree.subGroupsByGroupId[newGroup.id] = [];
      newSearchTree.subGroupsByGroupId[parentId] = [
        ...newSearchTree.subGroupsByGroupId[parentId],
        newGroup.id,
      ];

      return newSearchTree;
    });
  }, []);

  const afterAddMemberSuccess = useCallback((groupId, newMembers) => {
    setSearchTree((prev) => {
      if (!prev) return undefined;

      const newSearchTree = { ...prev };
      newMembers.forEach((member) => {
        newSearchTree.accounts[member.accountId] = {
          accountId: member.accountId,
          name: member.name,
        };
      });
      newSearchTree.accountsByGroupId[groupId] = [
        ...newSearchTree.accountsByGroupId[groupId],
        ...newMembers.map((member) => member.accountId),
      ];

      return newSearchTree;
    });
  }, []);

  const afterRemoveMemberSuccess = useCallback((groupId, accountId) => {
    setSearchTree((prev) => {
      if (!prev) return undefined;

      const newSearchTree = { ...prev };

      newSearchTree.accountsByGroupId[groupId] =
        newSearchTree.accountsByGroupId[groupId].filter(
          (id) => id !== accountId
        );

      return newSearchTree;
    });
  }, []);

  console.log('SEARCH RESULT', searchData, searchTree);

  return (
    <div>
      <div className="flex justify-between">
        <Input.Search
          placeholder={t('Search')}
          style={{
            width: 240,
            marginRight: '16px',
            marginBottom: '8px',
          }}
          onChange={(e) => onSearch(e.target.value)}
          suffix={isSearching ? <LoadingOutlined spin /> : null}
          allowClear
        />
        <Button
          type="primary"
          icon={<AddFolderIcon />}
          className="flex items-center gap-2"
          onClick={() => onAddGroup()}
          style={{
            opacity: isSearchActive ? 0 : 1,
          }}
        >
          Add Group
        </Button>
      </div>

      {isSearchActive && (
        <div className="group-tree-container relative flex flex-col gap-1">
          {/* {searchTree?.rootGroups
            .map((id) => searchTree?.groups[id])
            .filter(Boolean)
            .map((group) => (
              <GroupNodeContainer
                key={group.id}
                group={group}
                getSubGroups={getSubGroups}
                getMembers={getMembers}
                onRenameSuccess={(groupId, newName) => {
                  afterRenameSuccess(groupId, newName);
                  onRenameSuccess(groupId, newName);
                }}
                onRemoveSuccess={(groupId) => {
                  afterRemoveSuccess(groupId);
                  onRemoveSuccess(groupId);
                }}
                onAddGroupSuccess={(groupId, newGroup) => {
                  afterAddGroupSuccess(groupId, newGroup);
                  onAddGroupSuccess(groupId, newGroup);
                }}
                onAddMemberSuccess={(groupId, newMembers) => {
                  afterAddMemberSuccess(groupId, newMembers);
                  onAddMemberSuccess(groupId, newMembers);
                }}
                onRemoveMemberSuccess={(groupId, accountId) => {
                  afterRemoveMemberSuccess(groupId, accountId);
                  onRemoveMemberSuccess(groupId, accountId);
                }}
                getIsExpanded={getIsExpanded}
                onExpand={onExpand}
              />
            ))} */}
          {
            !isSearching && (
              !searchTree || searchTree?.rootGroups?.length === 0 ? (
                <Empty
                  image={NodataIcon}
                  imageStyle={{
                    height: 100,
                  }}
                  description={<span>{t('No data')}</span>}
                />
              ) : (
                searchTree?.rootGroups
                  .map((id) => searchTree?.groups[id])
                  .filter(Boolean)
                  .map((group) => (
                    <GroupNodeContainer
                      key={group.id}
                      group={group}
                      getSubGroups={getSubGroups}
                      getMembers={getMembers}
                      onRenameSuccess={(groupId, newName) => {
                        afterRenameSuccess(groupId, newName);
                        onRenameSuccess(groupId, newName);
                      }}
                      onRemoveSuccess={(groupId) => {
                        afterRemoveSuccess(groupId);
                        onRemoveSuccess(groupId);
                      }}
                      onAddGroupSuccess={(groupId, newGroup) => {
                        afterAddGroupSuccess(groupId, newGroup);
                        onAddGroupSuccess(groupId, newGroup);
                      }}
                      onAddMemberSuccess={(groupId, newMembers) => {
                        afterAddMemberSuccess(groupId, newMembers);
                        onAddMemberSuccess(groupId, newMembers);
                      }}
                      onRemoveMemberSuccess={(groupId, accountId) => {
                        afterRemoveMemberSuccess(groupId, accountId);
                        onRemoveMemberSuccess(groupId, accountId);
                      }}
                      getIsExpanded={getIsExpanded}
                      onExpand={onExpand}
                    />
                  ))
              )
            )
          }
          {isSearching && (
            <div className="absolute inset-0 flex items-center justify-center">
              <Spin indicator={<LoadingOutlined spin />} />
            </div>
          )}
        </div>
      )}
    </div>
  );
};
