export class HLSAdapter {
  connect(
    streaming,
    config,
    onSuccess
  ) {
    const url =
      streaming?.version === 'v2'
        ? `https://${streaming?.wsHost}:${streaming?.hlsPort}${streaming?.path}/index.m3u8?token=${config.streamToken}`
        : `https://${streaming?.wsHost}:${streaming?.hlsPort}/${config.streamToken}${streaming?.path}/index.m3u8`;

    console.log('HLSAdapter - url: ', url);
    onSuccess(url);
  }

  destroy() {
    console.log('DESTROYING THIS INSTANCE');
  }
}
