import React, { memo, useEffect, useMemo, useState } from 'react';

import { Modal } from 'antd';
import { GroupNode, MemberNode } from './Nodes';
import {
  useCheckAndRemoveUserGroup,
  useRemoveUserGroupMember,
} from '@/hooks/socket/member';

const noopAsync = () => Promise.resolve([]);
const noop = () => {};

export const GroupNodeContainer = memo(
  ({
    group,
    level = 0,
    onRenameSuccess = noop,
    onRemoveSuccess = noop,
    getSubGroups = noopAsync,
    getIsExpanded = noop,
    onExpand,
    getMembers = noopAsync,
    onAddGroupSuccess = noop,
    onAddMemberSuccess = noop,
    onRemoveMemberSuccess = noop,
  }) => {
    const [subgroups, setSubgroups] = useState();
    const [isSubgroupLoading, setIsSubgroupLoading] = useState(false);
    const [groupMembers, setGroupMembers] = useState();
    const [isGroupMembersLoading, setIsGroupMembersLoading] = useState(false);
    const isLoading = isSubgroupLoading || isGroupMembersLoading;
    const { mutate: removeMemberFromGroup } = useRemoveUserGroupMember();
    const { mutate: checkAndRemoveUserGroup } = useCheckAndRemoveUserGroup();

    const isExpanded = getIsExpanded?.(group.id);
    const [isRenaming, setIsRenaming] = useState(false);
    const [isCreating, setIsCreating] = useState(false);
    const [isAddingUser, setIsAddingUser] = useState(false);

    const onExpandNode = (isExpanded) => {
      setIsRenaming(false);
      setIsCreating(false);
      setIsAddingUser(false);
      onExpand(group.id, isExpanded);
    };

    useEffect(() => {
      if (isExpanded) {
        setIsSubgroupLoading(true);
        getSubGroups(group.id).then((subgroups) => {
          setSubgroups(subgroups);
          setIsSubgroupLoading(false);
        });
        setIsGroupMembersLoading(true);
        getMembers(group.id).then((members) => {
          setGroupMembers(members);
          setIsGroupMembersLoading(false);
        });
      }
    }, [isExpanded, getSubGroups, getMembers]);

    const onAddGroup = () => {
      onExpand(group.id, true);
      setIsCreating(true);
    };

    const onAddUser = (adding) => {
      if (adding) {
        onExpand(group.id, true);
      }

      setIsAddingUser(adding);
    };

    const onAddSubGroupSuccess = (newGroup) => {
      setSubgroups((prev) => [...(prev || []), newGroup.group]);
      setIsCreating(false);
      onAddGroupSuccess(group.id, newGroup.group);
    };

    const onSubgroupRenameSuccess = (groupId, newName) => {
      onRenameSuccess(groupId, newName);
      setIsRenaming(false);
    };

    const onRemoveMemberFromThisGroupSuccess = (accountId) => {
      setGroupMembers((prev) =>
        prev?.filter((member) => member.accountId !== accountId)
      );
      onRemoveMemberSuccess(group.id, accountId);
    };

    const onRemoveMember = (accountId) => {
      Modal.confirm({
        title: 'Remove member',
        content: 'Are you sure you want to remove this member?',
        onOk: () => {
          return removeMemberFromGroup({
            namespace: group.namespace,
            groupId: group.id,
            accountId,
          }).then((data) => onRemoveMemberFromThisGroupSuccess(data.accountId));
        },
      });
    };

    const onRemoveThisGroup = () => {
      Modal.confirm({
        title: 'Remove group',
        content: 'Are you sure you want to remove this group?',
        onOk: () => {
          checkAndRemoveUserGroup({
            namespace: group.namespace,
            groupId: group.id,
          }).then(() => {
            onRemoveSuccess(group.id);
          });
        },
      });
    };

    const onRemoveSubgroupSuccess = (groupId) => {
      setSubgroups((prev) =>
        prev?.filter((subgroup) => subgroup.id !== groupId)
      );
      onRemoveSuccess(groupId);
    };

    const onAddUserSuccess = (accounts) => {
      const newMembers = accounts.map((account) => ({
        accountId: account.accountId,
        name: account.fullName,
        email: account.email,
        phonenumber: account.phonenumber,
        // NOT IMPORTANT
        createdAt: '',
        // NOT IMPORTANT
        indexOf: -1,
        username: account.username,
      }));

      setGroupMembers((prev) => [...(prev || []), ...newMembers]);
      setIsAddingUser(false);
      onAddMemberSuccess(group.id, newMembers);
    };

    const groupMembersIds = useMemo(() => {
      return groupMembers?.map((m) => m.accountId) || [];
    }, [groupMembers]);

    const isEmpty = useMemo(() => {
      if (!subgroups || !groupMembers) {
        // doesn't have data
        return false;
      }

      return subgroups.length === 0 && groupMembers.length === 0;
    }, [subgroups, groupMembers]);

    const sortedGroupMembers = useMemo(() => {
      return groupMembers?.sort((a, b) => {
        return b.accountId - a.accountId;
      });
    }, [groupMembers]);

    const sortedSubgroups = useMemo(() => {
      return subgroups?.sort((a, b) => {
        return b.id - a.id;
      });
    }, [subgroups]);

    return (
      <GroupNode
        id={group.id}
        name={group.name}
        namespace={group.namespace}
        level={level}
        isExpanded={isExpanded}
        onExpand={onExpandNode}
        isCreating={isCreating}
        onCreatingChange={setIsCreating}
        onAddGroup={onAddGroup}
        onAddGroupSuccess={onAddSubGroupSuccess}
        onRename={setIsRenaming}
        onRenameSuccess={(_, newName) => {
          onRenameSuccess(group.id, newName);
          setIsRenaming(false);
        }}
        isRenaming={isRenaming}
        onRemoveGroup={onRemoveThisGroup}
        isLoading={isLoading}
        isAddingUser={isAddingUser}
        onAddUser={onAddUser}
        onAddUserSuccess={onAddUserSuccess}
        groupMembersIds={groupMembersIds}
        isEmpty={isEmpty}
      >
        {sortedSubgroups?.map((subgroup) => (
          <GroupNodeContainer
            level={level + 1}
            key={subgroup.id}
            group={subgroup}
            onRenameSuccess={onSubgroupRenameSuccess}
            onRemoveSuccess={onRemoveSubgroupSuccess}
            onExpand={onExpand}
            getIsExpanded={getIsExpanded}
            getSubGroups={getSubGroups}
            getMembers={getMembers}
            onAddGroupSuccess={onAddGroupSuccess}
            onAddMemberSuccess={onAddMemberSuccess}
          />
        ))}
        {sortedGroupMembers?.map((member) => (
          <MemberNode
            onRemove={() => onRemoveMember(member.accountId)}
            level={level + 1}
            key={member.accountId}
            name={member.name}
          />
        ))}
      </GroupNode>
    );
  }
);
