import { APP_ID, NOTIFIES } from '../../../constants/system.keys'
import {
  getChallengeAuthenticationWebAuthn,
  registerWebAuthn,
  unregisterWebAuthn,
  useCheckLDAPAccount,
} from '../../../hooks/socket/auth'
import { useSelector } from 'react-redux'
import { createCredential } from './utils'
import { convertToBase64URL } from '../../../helpers/common'
import { openMessage } from '../../../redux/actions'
import { Modal } from 'antd'
import { useEffect, useState } from 'react'

export const usePasskey = () => {
  const dataUser = useSelector((state) => state.dataUser)
  const namespace = useSelector((state) => state.namespace)
  const {
    data: lDapData,
    send: refreshLDAPData,
    status: registerCheckStatus,
  } = useCheckLDAPAccount()

  const ldapAccount = Array.isArray(lDapData) ? lDapData?.find((item) => item.namespace === namespace) : {}
  const isRegistered = !!ldapAccount?.credentialId
  const [isRegistering, setIsRegistering] = useState(false)

  useEffect(() => {
    if (dataUser && dataUser?.phoneNumber && namespace) {
      refreshLDAPData({
        username: dataUser.phoneNumber,
        appId: APP_ID,
        namespace,
      })

      console.log('LDAP DATA', {
        username: dataUser.phoneNumber,
        appId: APP_ID,
        namespace,
      })
    }
  }, [dataUser, namespace, refreshLDAPData])

  const doAddPasskey = async () => {
    try {
      setIsRegistering(true)
      const res = await getChallengeAuthenticationWebAuthn({
        phonenumber: dataUser.phoneNumber,
        appId: APP_ID,
      })

      const credential = await createCredential(res.challenge, res.username)

      if (!credential) {
        setIsRegistering(false)
        return
      }

      const publicKey = credential.response.getPublicKey()

      await registerWebAuthn({
        credentialId: credential.id,
        publicKey: convertToBase64URL(publicKey, false),
        namespace,
      })

      setIsRegistering(false)

      doRefreshLDAPData()

      openMessage(NOTIFIES.SUCCESS, 'Add passkey success')
    } catch (error) {
      setIsRegistering(false)
      openMessage(NOTIFIES.ERROR, 'Add passkey failed')
      console.log(error)
    }
  }

  const onRemovePasskey = () => {
    return Modal.confirm({
      title: 'Remove passkey',
      content: 'Are you sure you want to remove your passkey?',
      onOk: doRemovePasskey,
      onCancel: () => { },
    })
  }

  const doRemovePasskey = async () => {
    try {
      await unregisterWebAuthn({
        credentialId: ldapAccount?.credentialId || '',
        namespace,
      })

      doRefreshLDAPData()

      openMessage(NOTIFIES.SUCCESS, 'Remove passkey success')
    } catch (error) {
      openMessage(NOTIFIES.ERROR, 'Remove passkey failed')
      console.log(error)
    }
  }

  const doRefreshLDAPData = () => {
    refreshLDAPData({
      username: dataUser.phoneNumber,
      appId: APP_ID,
    })
  }

  return {
    isRegistered,
    status: registerCheckStatus,
    doAddPasskey,
    onRemovePasskey,
    isRegistering,
    passkeyData: Array.isArray(lDapData) ? lDapData?.find((item) => item.namespace === namespace) : null,
  }
}
