import { SET_CAMERA_TO_SETTING } from "./action";

export const CAMERA_V2_KEY = 'camera-v2';

const initialState = {
  cameraToSetting: null
};
const internalReducer = (state = initialState, action) => {
  switch (action.type) {
    case SET_CAMERA_TO_SETTING:
      return {
        ...state,
        cameraToSetting: action.payload
      }
    default:
      return state;
  }
};

export const cameraReducer = (state, action) => {
  const cameraState = state[CAMERA_V2_KEY] || initialState;
  const newCameraState = internalReducer(cameraState, action);

  if (cameraState === newCameraState) {
    return state;
  }

  return { ...state, [CAMERA_V2_KEY]: newCameraState };
};

export const getCameraState = (state) => {
  return state[CAMERA_V2_KEY] || initialState;
};

export const getCameraToSetting = (state) => {
  return getCameraState(state)?.cameraToSetting;
};
