import clsx from 'clsx'
import styled from 'styled-components'
import './styles.scss'

export const GridContainer = styled.div.attrs(
  (props) => {
    return {
      className: clsx(
        'common-grid',
        props.displayMode && `grid-mode-${props.displayMode}`,
        props.className,
      ),
    }
  }
)``

export const GridItem = styled.div.attrs(
  (props) => ({
    className: clsx('common-grid-item', props.className),
  })
)``
