import React, { useMemo, useState } from 'react';
import { TABS } from './shared';
import { Header } from './Header';
import { Members } from './Members';
import { useSelector } from 'react-redux';
import { useGetAccountByNamespace } from './hooks';
import { GroupCamera } from './GroupCamera';
import { Cameras } from './Cameras';

export const OrganizationV2 = () => {
  const namespace = useSelector((state) => state.namespace);
  const userId = useSelector((state) => state.userId);
  const dataUser = useSelector((state) => state.dataUser);

  const [activeKey, setActiveKey] = useState(TABS.CAMERA);
  const { data: accountByNamespace, isLoading: isLoadingAccountByNamespace } =
    useGetAccountByNamespace(namespace);

  const isAdmin = useMemo(() => {
    if (
      accountByNamespace?.find((account) => account.id === userId)?.role ===
      'admin'
    ) {
      return true;
    }

    return (
      dataUser?.role === 'admin' ||
      (dataUser?.role === 'member' && dataUser?.detailRole === 'operator')
    );
  }, [accountByNamespace, userId, dataUser]);

  if (!isAdmin) {
    return <NoPermission />;
  }

  return (
    <div className="organization-v2-component p-3">
      <Header
        namespace={namespace}
        activeKey={activeKey}
        onKeyChange={setActiveKey}
      />
      {activeKey === TABS.MEMBER && (
        <Members
          accounts={accountByNamespace}
          isLoadingAccounts={isLoadingAccountByNamespace}
          namespace={namespace}
        />
      )}
      {activeKey === TABS.GROUP_CAMERA && (
        <GroupCamera
          namespace={namespace}
          accounts={accountByNamespace}
          isLoadingAccounts={isLoadingAccountByNamespace}
        />
      )}
      {activeKey === TABS.CAMERA && (
        <Cameras
          namespace={namespace}
          accounts={accountByNamespace}
          isLoadingAccounts={isLoadingAccountByNamespace}
        />
      )}
    </div>
  );
};

const NoPermission = () => {
  return (
    <div className="text-center">
      <h1>No Permission</h1>
    </div>
  );
};
