export const extractPath = (path) => {
  return path.split('/').filter(Boolean);
};

export const buildTree = (records) => {
  const isRootGroup = {};
  const groups = {};
  const accountsByGroupId = {};
  const subGroupsByGroupId = {};
  const accounts = {};

  if (!records || !records?.TbAccountGroup || records?.TbAccountGroup?.length <= 0) return

  const TbAccountGroup =
    records.TbAccountGroup.filter((account) => {
      // if all account.groups has all necessary ids, then return true, otherwise something wrong with data
      const path = extractPath(account.groupPath);

      console.log(path, account.groups);

      if (path.every((groupId) => account.groups?.[groupId])) {
        return true;
      }

      return false;
    }) ?? [];

  TbAccountGroup.forEach((account) => {
    Object.entries(account.groups).forEach(([groupId, group]) => {
      const groupIdNumber = Number(groupId);

      groups[groupIdNumber] = group;
      accountsByGroupId[groupIdNumber] = [];
      subGroupsByGroupId[groupIdNumber] = [];
    });
  });

  // Build tree
  TbAccountGroup.forEach((account) => {
    accounts[account.accountId] = {
      accountId: account.accountId,
      name: account.fullName,
    };

    const path = extractPath(account.groupPath);

    const rootGroupId = Number(path[0]);
    const parentGroupId = Number(path.at(-1));

    if (
      parentGroupId &&
      accountsByGroupId[parentGroupId].find((c) => c === account.accountId) ===
      undefined
    ) {
      accountsByGroupId[parentGroupId].push(account.accountId);
    }

    isRootGroup[rootGroupId] = true;

    for (let i = 1; i < path.length; i++) {
      const currentGroupId = Number(path[i]);
      const parentGroupId = Number(path[i - 1]);

      if (
        !subGroupsByGroupId[parentGroupId].find(
          (subGroupId) => subGroupId === currentGroupId
        )
      ) {
        subGroupsByGroupId[parentGroupId].push(currentGroupId);
      }
    }
  });

  const rootGroups = Object.values(groups)
    .filter((group) => isRootGroup[group.id])
    .map((group) => group.id);

  return {
    rootGroups,
    groups,
    subGroupsByGroupId,
    accountsByGroupId,
    accounts,
  };
};
