import { getListScheduleTaskAdvanceBackup } from '@/hooks/socket/playback';
import { Select, Table, Tooltip } from 'antd';
import moment from 'moment';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { ArrowRightOutlined, CheckCircleFilled } from '@ant-design/icons';

const { Option } = Select;

const BACKUP_SERVICE_TYPE = {
  advance_backup_storage_file: 'Advance Backup Storage File',
};

export const BackupTaskSchedule = ({
  namespace,
  selectedDate,
  devicesActiveOfServices = [],
  customSelectedCamera,
  variantPage = '',
  onViewDetail,
}) => {
  const [scheduleTasks, setScheduleTasks] = useState([]);
  const [dataSource, setDataSource] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedCameras, setSelectedCameras] = useState([]);
  const [pageSize, setPageSize] = useState(10);
  const [current, setCurrent] = useState(1);

  useEffect(() => {
    if (!namespace) {
      setScheduleTasks([]);
      return;
    }

    const requestBody = { namespace };
    if (selectedDate && moment(selectedDate).isValid()) {
      requestBody.dateRecord = moment(selectedDate).format('YYYY-MM-DD');
    }

    setLoading(true);
    getListScheduleTaskAdvanceBackup(requestBody)
      .then((res) => {
        if (res?.result !== 1) {
          setScheduleTasks([]);
          return;
        }

        let data = [];
        try {
          data = JSON.parse(res?.data || '[]');
        } catch (error) {
          data = [];
        }

        const filteredTask = (data || []).filter((task) => {
          let body = task?.body;

          if (typeof body === 'string') {
            try {
              body = JSON.parse(body);
            } catch (error) {
              return false;
            }
          }

          if (customSelectedCamera) {
            return body?.serial === customSelectedCamera.serial;
          }

          if (!body || body.namespace !== namespace) return false;

          return true;
        });

        setScheduleTasks(filteredTask);
      })
      .catch(() => {
        setScheduleTasks([]);
      })
      .finally(() => {
        setLoading(false);
      });
  }, [customSelectedCamera, namespace, selectedDate]);

  useEffect(() => {
    if (scheduleTasks.length === 0) {
      setDataSource([]);
      return;
    }

    const mappedData = scheduleTasks
      .map((item, index) => {
        let body = item?.body;

        if (typeof body === 'string') {
          try {
            body = JSON.parse(body);
          } catch (error) {
            return null;
          }
        }

        if (!body || !body.serial) {
          return null;
        }

        const cameraName = customSelectedCamera
          ? customSelectedCamera.name || '_'
          : devicesActiveOfServices.find((dev) => dev.serial === body.serial)
              ?.name || '_';

        return {
          ...item,
          camera: cameraName,
          serial: body.serial,
          recordDate: body.recordDate,
          index: index + 1,
        };
      })
      .filter(Boolean);

    setDataSource(mappedData);
  }, [devicesActiveOfServices, scheduleTasks, customSelectedCamera]);

  const filteredDataSource = useMemo(
    () =>
      selectedCameras.length
        ? dataSource.filter((item) => selectedCameras.includes(item.serial))
        : dataSource,
    [dataSource, selectedCameras],
  );

  useEffect(() => {
    setCurrent(1);
  }, [namespace, selectedDate, customSelectedCamera, selectedCameras]);

  const handleViewDetail = useCallback(
    (record) => {
      onViewDetail(record);
    },
    [onViewDetail],
  );

  const columns = useMemo(
    () => [
      ...(!customSelectedCamera
        ? [
            {
              title: 'Camera',
              dataIndex: 'camera',
              key: 'camera',
            },
          ]
        : []),
      {
        title: 'Record Date',
        dataIndex: 'recordDate',
        key: 'recordDate',
        render: (text) => moment(text).format('YYYY-MM-DD'),
      },
      {
        title: 'Created At',
        dataIndex: 'createdAt',
        key: 'createdAt',
        render: (text) => moment(text).format('YYYY-MM-DD HH:mm:ss'),
      },
      {
        title: 'Time Run',
        dataIndex: 'timeRun',
        key: 'timeRun',
        render: (text) => moment(text).format('YYYY-MM-DD HH:mm:ss'),
      },
      {
        title: 'Message',
        dataIndex: 'note',
        key: 'note',
      },
      {
        title: 'Service',
        dataIndex: 'service',
        key: 'service',
        render: (text) => BACKUP_SERVICE_TYPE[text] || text,
      },
      ...(variantPage === 'playback'
        ? [
            {
              title: 'Status',
              dataIndex: 'status',
              key: 'status',
              render: (text) => (
                <div className="task-status done">
                  <CheckCircleFilled />
                  <span>Success</span>
                </div>
              ),
            },
          ]
        : []),
      {
        title: 'Action',
        key: 'action',
        align: 'center',
        render: (_, record) => (
          <>
            <Tooltip title="View videos">
              <ArrowRightOutlined onClick={() => handleViewDetail(record)} />
            </Tooltip>
          </>
        ),
      },
    ],
    [customSelectedCamera, handleViewDetail, variantPage],
  );

  return (
    <div>
      {!customSelectedCamera && (
        <div style={{ marginBottom: 16 }}>
          <Select
            mode="multiple"
            showSearch
            optionFilterProp="children"
            allowClear
            placeholder="Select cameras"
            style={{ width: 320 }}
            value={selectedCameras}
            onChange={(values) => setSelectedCameras(values || [])}
          >
            {devicesActiveOfServices.map((item) => (
              <Option key={item.serial} value={item.serial}>
                {item.name}
              </Option>
            ))}
          </Select>
        </div>
      )}
      <Table
        dataSource={
          filteredDataSource?.map((item, index) => ({
            ...item,
            key: index + 1,
            index: (index + 1) * 1,
          })) || []
        }
        columns={columns}
        loading={loading}
        pagination={{
          pageSize,
          current,
          showSizeChanger: true,
          total: filteredDataSource.length,
          pageSizeOptions: ['10', '20', '50', '100'],
          onChange: (page, size) => {
            setCurrent(page);
            setPageSize(size);
          },
        }}
      />
    </div>
  );
};
