import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { Button, Divider, Modal, Select, Spin, Table, Typography } from 'antd';
import {
  listAllDevicesByPage,
  useAddCameraToGroup,
  useListAllDevicesByPage,
} from '../../../../hooks/socket/cameras';
import { debounce } from 'lodash';
import { LoadingOutlined } from '@ant-design/icons';

import './styles.scss';
import { CameraSelector } from './CameraSelector';

export const AddCameraToGroup = ({
  groupId,
  groupName,
  onSuccess,
  namespace,
  onClose,
  getGroupCameras,
}) => {
  const [groupCameras, setGroupCameras] = useState();

  const isGroupCameraLoading = groupCameras === undefined;

  useEffect(() => {
    getGroupCameras(groupId).then(setGroupCameras);
  }, [getGroupCameras, groupId]);

  const [cameras, setCameras] = useState([]);
  const { send: doAddCamera, isLoading: isLoadingAddCamera } =
    useAddCameraToGroup();

  const onOk = () => {
    const newCameras = cameras;

    if (!newCameras.length) {
      return;
    }

    console.log('PAYLOAD', {
      namespace,
      deviceGroupId: groupId,
      serial: newCameras[0].serial,
      indexOf: 1,
    });

    Promise.all(
      newCameras.map((cam) =>
        doAddCamera({
          namespace,
          deviceGroupId: groupId,
          serial: cam.serial,
          indexOf: 1,
        })
      )
    ).then(() => {
      onSuccess(groupId, newCameras);
    });
  };

  const getOptions = useCallback(
    (defaultOptions) => {
      const map = new Map(
        groupCameras?.map((item) => [
          item.serial,
          {
            ...item,
          },
        ]) || []
      );

      const newOptions = defaultOptions.map((item) => {
        if (map.has(item.value)) {
          return {
            ...item,
            disabled: true,
            className: 'disabled',
          };
        }

        return item;
      });

      return newOptions;
    },
    [groupCameras]
  );

  return (
    <Modal
      title={`Add camera to ${groupName}`}
      footer={
        <div>
          <Button
            loading={isLoadingAddCamera}
            type="default"
            onClick={onOk}
            disabled={!cameras.length}
          >
            Add Camera
          </Button>
        </div>
      }
      visible
      onCancel={onClose}
    >
      <CameraSelector
        onChange={setCameras}
        value={cameras}
        getOptions={getOptions}
        namespace={namespace}
        dropdownClassName="add-camera-to-group-dropdown"
        placeholder="Select camera to add"
        style={{
          width: 300,
        }}
      />
      <Divider style={{ margin: '12px 0' }} />
      <Table
        tableLayout="fixed"
        title={() => <h3>Cameras in group</h3>}
        size="small"
        scroll={{ y: 300 }}
        dataSource={groupCameras}
        rowKey="serial"
        columns={[
          {
            title: 'Serial',
            dataIndex: 'serial',
            width: 120,
          },
          {
            title: 'Name',
            dataIndex: 'name',
          },
        ]}
        loading={isGroupCameraLoading}
        pagination={{
          showSizeChanger: false,
          size: 'small',
        }}
      />
    </Modal>
  );
};
