import React, { useCallback, useState } from 'react';
import { Button } from 'antd';
import { DownloadOutlined } from '@ant-design/icons';
import { TABS } from './shared';
import storageService from '@/services/storage.service';
import { openMessage } from '@/redux/actions';
import { DECODED_ACCESS_TOKEN, NOTIFIES } from '@/constants/system.keys';
import { getReportAccountApi } from '@/api/reportApi';

const keys = [
  { key: TABS.CAMERA, label: 'Camera' },
  { key: TABS.GROUP_CAMERA, label: 'Group camera' },
  { key: TABS.MEMBER, label: 'Member' },
];

export const Header = ({ activeKey, onKeyChange, namespace }) => {
  const [isLoadingExport, setIsLoadingExport] = useState(false);

  const handleExportAccountReports = useCallback(async () => {
    try {
      setIsLoadingExport(true);
      const token =
        storageService.getInternalStorageByKey(DECODED_ACCESS_TOKEN);
      const dataQuery = {
        namespace,
        customerNamespace: namespace,
        isDownload: 1,
      };
      const dataRes = await getReportAccountApi(
        token,
        { namespace },
        dataQuery
      );
      console.log('dataRes: ', dataRes);
      setTimeout(() => {
        if (dataRes?.data) {
          const buttonElement = document.createElement('a');
          buttonElement.href = `data:text/csv;charset=utf-8,${encodeURI(
            dataRes.data
          )}`;
          buttonElement.target = '_blank';
          buttonElement.download = `report-account.csv`;
          buttonElement.click();
        } else {
          openMessage(NOTIFIES.WARNING, 'No data export');
        }
        setIsLoadingExport(false);
      }, 800);
    } catch (error) {
      setTimeout(() => {
        setIsLoadingExport(false);
        openMessage(
          NOTIFIES.WARNING,
          error?.response?.data?.message ?? 'Internal server error'
        );
      }, 800);
    }
  }, [namespace]);

  return (
    <div className="flex items-center py-2">
      <div className="flex gap-2">
        {keys.map(({ key, label }) => (
          <Button
            key={key}
            type={activeKey === key ? 'primary' : 'default'}
            onClick={() => onKeyChange(key)}
          >
            {label}
          </Button>
        ))}
      </div>
      <div className="flex-1" />
      <Button
        type="primary"
        icon={<DownloadOutlined />}
        onClick={handleExportAccountReports}
        loading={isLoadingExport}
      >
        Export
      </Button>
    </div>
  );
};
