import React, { useCallback, useEffect } from "react";
import { Filter } from "./Filter";
import * as SERVICE from '../../constants/service.types'
import { useDispatch, useSelector } from "react-redux";
import { socketEmitEvent } from "@/redux/actions";
import { SiteList } from "./SiteList";

import './index.scss'

const SitesPage = () => {
  const dispatch = useDispatch();
  const { namespace, listPlaceByPage } = useSelector(state => state)

  const getListAtmPlaceByPage = useCallback(
    (page, size, searchName, tag) => {
      let data = {
        appServiceType: SERVICE.LIST_ALL_PLACE_BY_PAGE,
        requestId: new Date().getTime(),
        body: JSON.stringify({
          ...(searchName && { name: searchName }),
          ...(tag && { tag }),
          namespace,
          locationType: 'place-camera',
          timeRequest: new Date().getTime(),
          page: page ?? 0,
          size: size ?? 8,
        }),
      };
      return dispatch(socketEmitEvent(data));
    },
    [dispatch, namespace]
  );

  useEffect(() => {
    if (namespace) {
      getListAtmPlaceByPage();
    }
  }, [getListAtmPlaceByPage, namespace]);

  return (
    <div className="sites-page w-full h-full px-4 py-6">
      <div className="filter-sites w-full flex flex-col gap-2 justify-start">
        <Filter onFilter={getListAtmPlaceByPage} />
        <div className="w-full h-full mt-4">
          <SiteList />
        </div>
      </div>
    </div>
  )
}

export default SitesPage;