import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import moment from 'moment';
import ReactPlayer from 'react-player';
import { useDispatch, useSelector } from 'react-redux';
import { getLinkStorageFileByTime } from '@/hooks/socket/playback';
import Spinner from '@/components/Spinner';
import { CameraOutlined, ExpandOutlined, CompressOutlined } from '@ant-design/icons';
import { startPlaybackCamera } from '@/hooks/socket/stream';
import { RTCCodecAdapter } from '../PlayerLocal/adapter/rtc-codec';
import { HLSAdapter } from '../PlayerLocal/adapter/hls';
import { Button } from 'antd';

const SituationPlayer = ({ serial, queryTime, thumbnail, allowFullScreen = true }) => {
  const dispatch = useDispatch();
  const playerRef = useRef(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const { namespace } = useSelector((state) => state);
  const [situationVideo, setSituationVideo] = useState(null);
  const [isFullScreen, setIsFullscreen] = useState(false);
  const [dimensions, setDimensions] = useState({});
  const containerRef = useRef(null);
  const [countRetry, setCountRetry] = useState(0)
  const [playbackStream, setPlaybackStream] = useState(null)
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    if (serial && namespace && !playbackStream) {
      setIsLoading(true)
      getLinkStorageFileByTime({
        namespace,
        deviceSerial: serial,
        queryTime: moment(queryTime)
          .subtract(3, 'seconds')
          .format('YYYY-MM-DD HH:mm:ss'),
        ipAddress: '0.0.0.0',
      })
        .then((res) => {
          console.log('setSituationVideo - res: ', res);
          setSituationVideo(res);
        })
        .catch((err) => {
          console.log('err: ', err);
          setSituationVideo(err);
        });
    }
  }, [dispatch, namespace, serial, queryTime, playbackStream]);

  useEffect(() => {
    if (situationVideo?.startSecond && playerRef.current?.seekTo) {
      setIsLoading(false)
      let backwardSeconds = 0
      if (situationVideo?.startSecond > 600) {
        backwardSeconds = situationVideo?.startSecond - 600
      }
      playerRef.current.seekTo(situationVideo.startSecond - backwardSeconds, 'seconds');
    }
  }, [situationVideo]);

  useEffect(() => {
    if (situationVideo?.result === -3 && isLoading) {
      setCountRetry(prev => prev + 1)
      startPlaybackCamera({
        serial,
        namespace,
        queryTime: moment(queryTime).subtract(10, 'seconds').format('YYYY-MM-DD HH:mm:ss'),
        serviceId: 10,
        type: 'external',
      }).then((res) => {
        setPlaybackStream(res)
      })
        .catch((err) => {
          console.log('err: ', err);
        });
    }
  }, [dispatch, isLoading, namespace, queryTime, serial, situationVideo]);

  useEffect(() => {
    const video = playerRef.current?.getInternalPlayer();
    if (video) {
      videoRef.current = video;

      video.crossOrigin = 'anonymous';

      video.addEventListener('loadedmetadata', function () {
        const ratio = video.videoWidth / video.videoHeight;
        const w = video.videoWidth;
        const h = parseInt(w / ratio, 10);

        if (canvasRef?.current) {
          canvasRef.current.width = w;
          canvasRef.current.height = h;
        }
        setDimensions({ w, h });
      });
    }
  }, [situationVideo]);

  const onDownloadDirectClick = () => {
    const video = videoRef.current || playerRef.current;
    const canvas = canvasRef.current;

    console.log('canvas: ', canvas);
    console.log('video: ', video);
    console.log('dimensions: ', dimensions);

    if (canvas && video && dimensions.w && dimensions.h) {
      try {
        const context = canvas.getContext('2d');
        context.fillRect(0, 0, dimensions.w, dimensions.h);
        context.drawImage(video, 0, 0, dimensions.w, dimensions.h);

        const url = canvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = `${serial}_${moment(queryTime).format('DD-MM-YYYY_HH-mm-ss')}.png`;
        link.href = url;
        link.click();
      } catch (error) {
        console.error('Error capturing screenshot:', error);
      }
    } else {
      console.error('Cannot capture screenshot: missing video, canvas, or dimensions');
    }
  };

  const handleFullscreen = () => {
    if (
      !!(
        document.fullScreen ||
        document.webkitIsFullScreen ||
        document.mozFullScreen ||
        document.msFullscreenElement ||
        document.fullscreenElement
      )
    ) {
      if (document.exitFullscreen) document.exitFullscreen();
      else if (document.mozCancelFullScreen) document.mozCancelFullScreen();
      else if (document.webkitCancelFullScreen) document.webkitCancelFullScreen();
      else if (document.msExitFullscreen) document.msExitFullscreen();
    } else {
      if (containerRef.current.requestFullscreen)
        containerRef.current.requestFullscreen();
      else if (containerRef.current.mozRequestFullScreen)
        containerRef.current.mozRequestFullScreen();
      else if (containerRef.current.webkitRequestFullScreen)
        containerRef.current.webkitRequestFullScreen();
      else if (containerRef.current.msRequestFullscreen)
        containerRef.current.msRequestFullscreen();
    }
  };

  const exitHandler = useCallback(() => {
    if (
      !document.fullscreenElement &&
      !document.webkitIsFullScreen &&
      !document.mozFullScreen &&
      !document.msFullscreenElement
    ) {
      setIsFullscreen(false);
    } else {
      setIsFullscreen(true);
    }
  }, []);

  useEffect(() => {
    document.addEventListener('fullscreenchange', exitHandler);
    document.addEventListener('webkitfullscreenchange', exitHandler);
    document.addEventListener('mozfullscreenchange', exitHandler);
    document.addEventListener('MSFullscreenChange', exitHandler);

    return () => {
      document.removeEventListener('fullscreenchange', exitHandler);
      document.removeEventListener('webkitfullscreenchange', exitHandler);
      document.removeEventListener('mozfullscreenchange', exitHandler);
      document.removeEventListener('MSFullscreenChange', exitHandler);
    };
  }, [exitHandler]);

  return (
    <div
      className='w-full situation-player-wrapper'
    // style={{ minHeight: '350px' }}
    >

      <div className={`situation-player relative ${isFullScreen ? 'fullscreen' : ''}`}
        ref={containerRef}
      >
        {
          (!!!situationVideo || (situationVideo?.result === -3 && !playbackStream)) ? (
            <Spinner />
          ) : (
            situationVideo?.result === -3 ? (
              !playbackStream ? (
                <div
                  className="w-full flex items-center justify-center bg-white text-base mt-2 font-semibold rounded-lg"
                  style={{ minHeight: '350px' }}
                >
                  Video not found
                </div>
              ) : (
                <>
                  {isLoading && <Spinner />}
                  <div style={{ display: isLoading ? 'none' : 'block' }}>
                    <PlaybackPlayerLocal
                      stream={playbackStream}
                      thumbnail={thumbnail}
                      setIsLoading={setIsLoading}
                      videoRef={videoRef}
                      canvasRef={canvasRef}
                      setDimensions={setDimensions}
                    />
                  </div>
                </>
              )
            ) : (
              <ReactPlayer
                ref={playerRef}
                url={situationVideo?.secureLink}
                width="100%"
                height="100%"
                playsinline
                controls={true}
                playing={true}
                config={{
                  file: {
                    attributes: {
                      crossOrigin: 'anonymous',
                      disablePictureInPicture: true,
                      controlsList: 'nodownload',
                    },
                  },
                }}
              />
            )
          )
        }
        <div className='w-full absolute bottom-0 p-2 bottom-control-player flex justify-end items-center gap-2'>
          <Button className='control-btn' icon={<CameraOutlined />} shape='circle'
            onClick={onDownloadDirectClick}
          />
          {
            allowFullScreen && (
              <Button className='control-btn' icon={isFullScreen ? <CompressOutlined /> : <ExpandOutlined />} shape='circle'
                onClick={handleFullscreen}
              />
            )
          }
        </div>
        <canvas crossOrigin="anonymous" ref={canvasRef} hidden />
      </div>
    </div>
  );
};

export default SituationPlayer;

const PlaybackPlayerLocal = ({ stream, thumbnail, setIsLoading, videoRef, canvasRef, setDimensions }) => {
  const [output, setOutput] = useState();
  const internalVideoRef = useRef(null);
  const playerRef = useRef(null);

  const adapterRef = useRef(null);
  const lastStreamTokenRef = useRef(null);

  useEffect(() => {
    if (!stream) return;

    if (stream.protocol === 'webrtc') {
      adapterRef.current = new RTCCodecAdapter();
    } else {
      adapterRef.current = new HLSAdapter();
    }

    return () => {
      adapterRef.current.destroy();
      adapterRef.current = null;
      lastStreamTokenRef.current = null;
    };
  }, [stream]);

  useEffect(() => {
    const adapter = adapterRef.current;
    if (!adapter || !stream) return;

    if (lastStreamTokenRef.current === stream.streamToken) return;
    lastStreamTokenRef.current = stream.streamToken;

    adapter.connect(
      stream,
      { streamToken: stream.streamToken },
      (output) => {
        setOutput(output);
      }
    );

    return () => adapter?.destroy();
  }, [stream, setIsLoading]);

  useEffect(() => {
    if (output instanceof MediaStream && internalVideoRef.current) {
      const videoElement = internalVideoRef.current;
      videoElement.srcObject = output;

      if (videoRef) {
        videoRef.current = videoElement;
      }

      const handleCanPlay = () => {
        setIsLoading(false);
      };

      const handlePlaying = () => {
        setIsLoading(false);
      };

      const handleLoadedMetadata = () => {
        const ratio = videoElement.videoWidth / videoElement.videoHeight;
        const w = videoElement.videoWidth;
        const h = parseInt(w / ratio, 10);

        if (canvasRef?.current) {
          canvasRef.current.width = w;
          canvasRef.current.height = h;
        }

        if (setDimensions) {
          setDimensions({ w, h });
        }
      };

      videoElement.addEventListener('canplay', handleCanPlay);
      videoElement.addEventListener('playing', handlePlaying);
      videoElement.addEventListener('loadedmetadata', handleLoadedMetadata);

      return () => {
        videoElement.removeEventListener('canplay', handleCanPlay);
        videoElement.removeEventListener('playing', handlePlaying);
        videoElement.removeEventListener('loadedmetadata', handleLoadedMetadata);
      };
    }
  }, [output, setIsLoading, videoRef, canvasRef, setDimensions]);

  useEffect(() => {
    if (typeof output === 'string' && playerRef.current) {
      const video = playerRef.current.getInternalPlayer();
      if (video && videoRef) {
        videoRef.current = video;

        const handleLoadedMetadata = () => {
          const ratio = video.videoWidth / video.videoHeight;
          const w = video.videoWidth;
          const h = parseInt(w / ratio, 10);

          if (canvasRef?.current) {
            canvasRef.current.width = w;
            canvasRef.current.height = h;
          }

          if (setDimensions) {
            setDimensions({ w, h });
          }
        };

        video.addEventListener('loadedmetadata', handleLoadedMetadata);

        return () => {
          video.removeEventListener('loadedmetadata', handleLoadedMetadata);
        };
      }
    }
  }, [output, videoRef, canvasRef, setDimensions]);

  const handleReady = useCallback(() => {
    setIsLoading(false);
  }, [setIsLoading]);

  const handleStart = useCallback(() => {
    setIsLoading(false);
  }, [setIsLoading]);

  return (
    <div className="playback-player">
      <div className="relative" style={{ width: '100%', paddingBottom: '56.25%' }}>
        <div className="absolute inset-0">
          {typeof output === 'string' && (
            <ReactPlayer
              ref={playerRef}
              pip={false}
              width="100%"
              height="100%"
              url={output}
              playing={true}
              onReady={handleReady}
              onStart={handleStart}
              config={{
                file: {
                  attributes: {
                    crossOrigin: 'anonymous',
                  },
                },
              }}
            />
          )}
          {output instanceof MediaStream && (
            <video
              ref={internalVideoRef}
              style={{ width: '100%', height: '100%' }}
              autoPlay
              playsInline
              preload="metadata"
              crossOrigin="anonymous"
            />
          )}

          {!output && thumbnail && (
            <img
              className="h-full w-full object-contain"
              src={thumbnail}
              alt=''
            />
          )}
        </div>
      </div>
    </div>
  );
};