import React, { useMemo } from "react";
import { SiteItem } from "./SiteItem";
import { useSelector } from "react-redux";
import { Empty } from "antd";
import NodataIcon from '@/assets/icons/no-data-icon-v2.svg';
import { useTranslation } from "react-i18next";

export const SiteList = () => {
  const { listPlaceByPage } = useSelector(state => state)
  const sites = useMemo(() => listPlaceByPage?.places || [], [listPlaceByPage])
  const { t } = useTranslation();

  return (
    <>
      {
        sites?.length === 0 && (
          <div className="w-full h-full flex justify-center">
            <Empty
              style={{ margin: 80 }}
              image={NodataIcon}
              imageStyle={{
                height: 60,
              }}
              description={<span className='text-brand text-base font-semibold'>{t('No data')}</span>}
            />
          </div>
        )
      }
      <div className="w-full grid grid-cols-4 gap-8">
        {
          sites && sites?.map(site => (
            <SiteItem data={site} index={site?.placeId} />
          ))
        }
      </div>
    </>
  )
}