import { Checkbox, Modal } from 'antd';
import React, { useEffect, useState } from 'react';
import {
  permissionArrayToString,
  PERMISSIONS,
  permissionStringToArray,
} from '../shared';

export const EditPermissionModal = ({
  defaultPermission,
  onCancel,
  onSubmit,
  isLoading,
  name,
}) => {
  const [permissions, setPermissions] = useState(
    permissionStringToArray(defaultPermission) || []
  );

  useEffect(() => {
    setPermissions(permissionStringToArray(defaultPermission) || []);
  }, [defaultPermission]);

  const togglePermission = (permission) => {
    setPermissions((prev) => {
      if (prev.includes(permission)) {
        return prev.filter((p) => p !== permission);
      }

      return [...prev, permission];
    });
  };

  return (
    <Modal
      title={`Edit permission for ${name}`}
      visible
      onCancel={onCancel}
      onOk={() => onSubmit(permissionArrayToString(permissions))}
      okText="Save"
      okButtonProps={{
        loading: isLoading,
      }}
    >
      <div className="flex flex-col gap-2">
        {PERMISSIONS.map((permission) => (
          <div key={permission} className="flex items-center gap-2">
            <Checkbox
              checked={permissions.includes(permission)}
              onChange={() => togglePermission(permission)}
            >
              {permission.charAt(0).toUpperCase() + permission.slice(1)}
            </Checkbox>
          </div>
        ))}
      </div>
    </Modal>
  );
};
