export const AVAILABLE_TIME_LOADING = 'PLAYBACK:AVAILABLE_TIME_LOADING'

export const availableTimeLoading = ({
  date,
  serial,
}) => ({
  type: AVAILABLE_TIME_LOADING,
  payload: {
    date,
    serial,
  },
})

export const AVAILABLE_TIME_SUCCESS = 'PLAYBACK:AVAILABLE_TIME_SUCCESS'

export const availableTimeSuccess = (
  date,
  serial,
  data
) => ({
  type: AVAILABLE_TIME_SUCCESS,
  payload: {
    date,
    serial,
    data,
  },
})

export const AVAILABLE_TIME_ERROR = 'PLAYBACK:AVAILABLE_TIME_ERROR'

export const availableTimeError = (
  date,
  serial,
  error = 'NOT_FOUND'
) => ({
  type: AVAILABLE_TIME_ERROR,
  payload: {
    date,
    serial,
    error,
  },
})

