export const SYNC_COMPRESS_STATES = 'PLAYBACK:SYNC_COMPRESS_STATES';
export const ADD_COMPRESS = 'PLAYBACK:ADD_COMPRESS';
export const UPDATE_COMPRESS = 'PLAYBACK:UPDATE_COMPRESS';
export const REMOVE_COMPRESS = 'PLAYBACK:REMOVE_COMPRESS';

export const syncDownloadStates = (serial, uuid, downloads) => ({
  type: SYNC_COMPRESS_STATES,
  payload: { serial, uuid, downloads }
});

export const addCompress = (serial, uuid, download) => ({
  type: ADD_COMPRESS,
  payload: { serial, uuid, download }
});

export const updateCompress = (serial, uuid, updates) => ({
  type: UPDATE_COMPRESS,
  payload: { serial, uuid, updates }
});

export const removeCompress = (serial, uuid) => ({
  type: REMOVE_COMPRESS,
  payload: { serial, uuid }
});