import {
    SET_SELECTED_NOTIFICATION,
    SET_NOTIFICATION_FILTER,
    SET_JUST_UPDATED_NOTIFICATION,
    RESET_NOTIFICATION_FILTER,
} from './action';

export const NOTIFICATION_KEY = 'notification';

const initialState = {
    selectedNotification: null,
    notificationFilter: {
        level: 'all',
        searchInput: '',
        taskStatus: null
    },
    justUpdatedNotifications: []
};

const internalReducer = (state = initialState, action) => {
    switch (action.type) {
        case SET_SELECTED_NOTIFICATION:
            return { ...state, selectedNotification: action.payload };
        case SET_NOTIFICATION_FILTER:
            return { ...state, notificationFilter: { ...state.notificationFilter, ...action.payload } };
        case RESET_NOTIFICATION_FILTER:
            return { ...state, notificationFilter: initialState.notificationFilter };
        case SET_JUST_UPDATED_NOTIFICATION:
            return {
                ...state,
                justUpdatedNotifications: !action.payload || action.payload?.length === 0 ? [] : [...(state.justUpdatedNotifications || []), action.payload]
            };
        default:
            return state;
    }
};

export const notificationReducer = (state, action) => {
    const notificationState = state[NOTIFICATION_KEY] || initialState;
    const newNotificationState = internalReducer(notificationState, action);

    if (notificationState === newNotificationState) return state;

    return { ...state, [NOTIFICATION_KEY]: newNotificationState };
};

export const getNotificationState = (state) => state[NOTIFICATION_KEY] || initialState;
export const getSelectedNotification = () => (state) => getNotificationState(state).selectedNotification;
export const getNotificationFilter = () => (state) => getNotificationState(state).notificationFilter;
export const getJustUpdatedNotification = () => (state) => getNotificationState(state).justUpdatedNotifications;