import React, { useState, useMemo, useEffect } from 'react';
import { Card, Badge, Input, Table, Menu, Space, Empty, Tag, Select, Button, Divider, Pagination } from 'antd';
import {
  CameraOutlined,
  UserOutlined,
  BarChartOutlined,
  SettingOutlined,
  BellOutlined,
  CreditCardOutlined,
  FileTextOutlined,
  GroupOutlined,
  SearchOutlined,
  PlusOutlined,
  CheckCircleOutlined,
  CloseOutlined
} from '@ant-design/icons';
import colorDark from '../../../assets/colors/dark';
import './index.scss';
import { useSelector } from 'react-redux';
import { useTranslation } from 'react-i18next';
import { beeXLogger } from '@/helpers/logger';

const iconMap = {
  Camera: CameraOutlined,
  Gateway: UserOutlined,
  Account: BarChartOutlined,
  Share: SettingOutlined,
  Service: BellOutlined,
  Notification: BellOutlined,
  "Action Log": CreditCardOutlined,
  Profile: FileTextOutlined,
  Base: FileTextOutlined,
};


const { Option } = Select

const MENU_PAGE_SIZE = 10

export function FunctionGroup({
  functionGroups,
  selectedGroup,
  onSelectGroup,
  selectedFunctions,
  onSelectFunction,
  showAdd = false,
  onAdd = () => { },
  addLoading = false,
  addDisabled = false
}) {
  const [searchValue, setSearchValue] = useState("");
  const { t } = useTranslation()
  const [searchField, setSearchField] = useState('name')
  const [menuPage, setMenuPage] = useState(1)

  const handleGroupSelect = ({ key }) => {
    if (onSelectGroup) {
      onSelectGroup(functionGroups?.find(item => item?.groupName === key));
    }
    setSearchValue("");
  };

  const currentGroup = useMemo(() => functionGroups?.find((g) => g?.groupName === selectedGroup?.groupName), [functionGroups, selectedGroup])
  beeXLogger.debug("🚀 ~ FunctionGroup ~ currentGroup:", currentGroup)
  const filteredFunctions = useMemo(() => currentGroup?.functions?.filter(f => {
    if (!searchValue) return true;
    const keyword = searchValue.toLowerCase().trim();
    if (searchField === 'name') {
      return f?.name?.toLowerCase().includes(keyword);
    }
    return f?.tag?.toLowerCase().includes(keyword);
  }) || [], [currentGroup, searchField, searchValue]);
  beeXLogger.debug("🚀 ~ FunctionGroup ~ filteredFunctions:", filteredFunctions)

  const paginatedGroups = useMemo(() => {
    const start = (menuPage - 1) * MENU_PAGE_SIZE;
    return functionGroups?.slice(start, start + MENU_PAGE_SIZE) || [];
  }, [functionGroups, menuPage]);

  const selectedRowKeys = useMemo(() => filteredFunctions
    ?.filter(p => selectedFunctions?.some(item => item?.tags?.includes(p?.tag)))
    .map(p => p.tag),
    [filteredFunctions, selectedFunctions]
  )
  const columns = [
    {
      title: "Name",
      dataIndex: "name",
      key: "name",
      width: 250,
    },
    {
      title: "Tag",
      dataIndex: "tag",
      key: "tag",
      render: (text, row) => {
        if (!row?.tag) return null
        return <Tag color="#028fd5">{text}</Tag>
      },
    },
  ];

  useEffect(() => {
    if (paginatedGroups?.length > 0 && onSelectGroup) {
      onSelectGroup(paginatedGroups[0]);
      setSearchValue("");
    }
  }, [menuPage, onSelectGroup, paginatedGroups]);

  return (
    <Card>
      {/* <Space align="center" className="card-header">
        <GroupOutlined className="text-xl" style={{ color: colorDark.$brandHex }} />
        <h3 style={{ margin: 0 }}>Function Groups</h3>
      </Space> */}
      <FunctionSelected
        selectedFunctions={selectedFunctions}
        functionGroups={functionGroups}
        onRemoveTag={(group, tag) => {
          onSelectFunction(group,
            selectedFunctions
              .find(f => f.group === group)
              ?.tags?.filter(t => t !== tag) || []
          )
        }}
        onRemoveGroup={(group) => {
          onSelectFunction(group, [])
        }}
      />
      <div className="flex gap-6 mt-2 overflow-hidden">
        <div style={{ width: 'fit-content', minWidth: '20%', maxWidth: '25%', flexShrink: 0, height: "fit-content" }}>
          <Menu
            theme="dark"
            mode="vertical"
            selectedKeys={selectedGroup ? [selectedGroup?.groupName] : []}
            onClick={handleGroupSelect}
            className="function-group-menu"
          >
            {paginatedGroups?.map((item) => {
              const Icon = iconMap[item?.groupName];
              return (
                <Menu.Item key={item?.groupName}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
                    <span>{item?.groupName}</span>
                  </div>
                </Menu.Item>
              );
            })}
          </Menu>
          {/* {functionGroups?.length > MENU_PAGE_SIZE && ( */}
          <Pagination
            current={menuPage}
            pageSize={MENU_PAGE_SIZE}
            total={functionGroups?.length}
            onChange={(page) => setMenuPage(page)}
            size="small"
            style={{ marginTop: 8, textAlign: 'center' }}

          />
          {/* )} */}
        </div>

        <div style={{ flex: 1, maxWidth: '75%' }}>
          {selectedGroup && currentGroup ? (
            <Card
              className='function-group-table-card'
              title={`${currentGroup?.groupName}`}
              extra={
                <div className='flex items-center justify-end gap-2'>
                  <Select value={searchField}
                    onChange={(value) => setSearchField(value)}
                  >
                    <Option value='name'>{t('Name')}</Option>
                    <Option value='tag'>{t('Tag')}</Option>
                  </Select>
                  <Input
                    placeholder={`Search by ${searchField}`}
                    value={searchValue}
                    onChange={(e) => setSearchValue(e.target.value)}
                    prefix={<SearchOutlined />}
                    style={{ width: '100%' }}
                  />
                </div>
              }
            >
              <Table
                rowSelection={{
                  type: 'checkbox',
                  selectedRowKeys,
                  onChange: (selectedKeys) => {
                    if (onSelectFunction) {
                      onSelectFunction(selectedGroup?.groupName, selectedKeys)
                    }
                  },
                }}
                dataSource={filteredFunctions}
                columns={columns}
                rowKey="tag"
                pagination={{
                  pageSize: 5,
                  total: filteredFunctions?.length,
                  position: ['bottomRight'],
                  // pageSizeOptions: ['5', '10', '20', '50', '100', '200', '400'],
                }}
              />
              <div className='h-4' />
              {
                showAdd && (
                  <div className='flex justify-end items-center'>
                    <Button icon={<PlusOutlined />} onClick={onAdd} disabled={addDisabled} loading={addLoading}>{t('Add')}</Button>
                  </div>
                )
              }
            </Card>
          ) : (
            <Card>
              <div
                style={{
                  textAlign: 'center',
                  padding: '60px 20px',
                  color: '#8c8c8c',
                }}
              >
                <GroupOutlined style={{ fontSize: 48, marginBottom: 16 }} />
                <p>Select a permission group from the sidebar to view functions</p>
              </div>
            </Card>
          )}
        </div>
      </div>
    </Card>
  );
}



export function FunctionSelected({ selectedFunctions = [], functionGroups = [], onRemoveTag, onRemoveGroup }) {
  const { listFunctions } = useSelector(state => state)

  if (!selectedFunctions || selectedFunctions?.length === 0) {
    return (
      <div className='function-selected'>
        <Space align="start">
          <CheckCircleOutlined className='text-xl function-selected-empty' />
          <span className='function-selected-empty'>
            No functions selected. Select functions from the categories below to build your custom role.
          </span>
        </Space>
      </div>
    );
  }

  return (
    <div className='function-selected'>
      <Space align="center" className='function-selected-header'>
        <CheckCircleOutlined className='text-xl' style={{ color: colorDark.$brandHex }} />
        <h3>Selected functions</h3>
      </Space>
      <Space direction="vertical" className='function-selected-list'>
        {selectedFunctions?.map((func, index) => (
          <Space
            key={index}
            className='function-selected-row'
          >
            <Space className='flex flex-wrap gap-1'>
              {func?.tags?.map((f) => (
                <code key={f} className='function-tag'>
                  {listFunctions?.find(item => item?.tag === f)?.name}
                  <span
                    className='function-tag-remove'
                    onClick={() => onRemoveTag?.(func?.group, f)}
                  >
                    <CloseOutlined />
                  </span>
                </code>
              ))}
            </Space>

            <div className='group-name-wrapper'>
              <span>
                {func?.group}
              </span>
              <span
                className='group-remove'
                onClick={() => onRemoveGroup?.(func?.group)}
              >
                <CloseOutlined />
              </span>
            </div>
          </Space>
        ))}
      </Space>
    </div>
  );
}