import React, {
  useCallback,
  useEffect,
  useMemo,
  useState,
  useRef,
} from 'react';
import { usePlaybackContext } from '../context';
import { ProgressBarV2 } from './v2';
import {
  PLAYBACK_RATE_ADVANCED_OPTIONS,
  PLAYBACK_RATE_OPTIONS,
} from '../Main/shared';
import { useDispatch, useSelector } from 'react-redux';
import {
  getAllowPlaybackRateAdvanced,
  getAvailableTimeBySerialAndDate,
  getAvailableTimeBySerialAndDateLocal,
  getFocusCamera,
  getPlaybackControls,
  getPlaybackMode,
  getPlaybackThumbnails,
  getSelectedDate,
} from '@/redux/playback/reducer';
import {
  getPlaybackTimes,
  getPlaybackTimesLocal,
  getThumbnailPlaybackByTime,
} from '@/hooks/socket/playback';
import { computeQueryTime } from '../utils';
import {
  sortTime,
  useFetchTimes,
  useFetchTimesLocal,
} from '@/redux/playback/use-fetch-times';
import {
  setPlaybackControls,
  setPlaybackThumbnails,
} from '@/redux/playback/action';
import { EnumPlaybackType } from '../Settings';
import { beeXLogger } from '@/helpers/logger';
import { ProgressBarV3 } from './v3';
import { PlaybackMainSectionMode } from '../Main';
import moment from 'moment';
import {
  PLAYBACK_DATE_FORMAT,
  PLAYBACK_DATE_TIME_FORMAT,
} from '@/constants/time';

const mergePlaybackTimes = (cloudTimes, localTimes) => {
  const allTimes = [];

  cloudTimes.forEach((r) => {
    allTimes.push({ time: r.from, type: 'start', storage: 'cloud' });
    allTimes.push({ time: r.to, type: 'end', storage: 'cloud' });
  });

  localTimes.forEach((r) => {
    allTimes.push({ time: r.from, type: 'start', storage: 'box' });
    allTimes.push({ time: r.to, type: 'end', storage: 'box' });
  });

  allTimes.sort((a, b) => a.time - b.time || (a.type === 'end' ? -1 : 1));

  let mergeTimes = [];
  let active = { cloud: 0, box: 0 };

  let prevTime = null;

  for (let e of allTimes) {
    if (
      prevTime !== null &&
      (active.cloud > 0 || active.box > 0) &&
      prevTime !== e.time
    ) {
      mergeTimes.push({
        from: prevTime,
        to: e.time,
        cloud: active.cloud > 0,
        box: active.box > 0,
      });
    }

    if (e.type === 'start') active[e.storage]++;
    else active[e.storage]--;

    prevTime = e.time;
  }

  return mergeTimes;
};

export const PlaybackMainFocusLayoutProgressBarContainer = ({
  isFullScreen = false,
  handleTogglePTZDewarp,
  ptzDeWarpActive,
  handleFullscreen,
  containerRef,
  handleMuted,
  muted,
  displayCameras,
  pageSize,
}) => {
  const {
    getCurrentTime,
    onElapsedTimeChange,
    setPivotTime,
    onPivotTimeChange,
    isActive,
    playbackRate,
    setPlaybackRate,
    allowPlaybackRate,
    displayMode,
  } = usePlaybackContext();

  const [_, rerender] = useState({});
  const initialSelectedDate = useSelector(getSelectedDate);
  const focusCamera = useSelector(getFocusCamera);
  const playbackType = useSelector(getPlaybackMode);
  const availableTimesData =
    useSelector(
      getAvailableTimeBySerialAndDate(focusCamera?.serial, initialSelectedDate),
    ) || {};
  const availableTimesDataLocal =
    useSelector(
      getAvailableTimeBySerialAndDateLocal(
        focusCamera?.serial,
        initialSelectedDate,
      ),
    ) || {};
  const { namespace } = useSelector((state) => state);
  const [availableTimes, setAvailableTimes] = useState([]);
  const [lastAvailableTimes, setLastAvailableTimes] = useState({});
  const dispatch = useDispatch();
  const playbackControlsRef = useRef(useSelector(getPlaybackControls));
  const playbackControls = useSelector(getPlaybackControls);
  const playbackThumbnails = useSelector(getPlaybackThumbnails);
  const allowPlaybackRateAdvanced = useSelector(getAllowPlaybackRateAdvanced);
  const playbackRateOptions = useMemo(
    () =>
      allowPlaybackRateAdvanced
        ? [...PLAYBACK_RATE_OPTIONS, ...PLAYBACK_RATE_ADVANCED_OPTIONS]
        : playbackType === EnumPlaybackType.LOCAL
          ? [...PLAYBACK_RATE_OPTIONS, PLAYBACK_RATE_ADVANCED_OPTIONS?.[0]]
          : PLAYBACK_RATE_OPTIONS,
    [allowPlaybackRateAdvanced, playbackType],
  );
  const currentTime = useMemo(
    () => Math.max(getCurrentTime(), 0),
    [getCurrentTime],
  );

  const minAvailableTime =
    useMemo(() => availableTimes?.[0] || 0, [availableTimes])?.from || 0;

  const maxAvailableTime = useMemo(() => {
    if (!availableTimes || availableTimes.length === 0) return 0;
    return availableTimes[availableTimes.length - 1]?.to || 0;
  }, [availableTimes]);
  const [cloudTimes, setCloudTimes] = useState([]);
  const [localTimes, setLocalTimes] = useState([]);
  const [isGridCloudLoading, setIsGridCloudLoading] = useState(false);
  const [isGridLocalLoading, setIsGridLocalLoading] = useState(false);

  const hasCloudLoadingState =
    typeof availableTimesData?.loading === 'boolean';
  const hasLocalLoadingState =
    typeof availableTimesDataLocal?.loading === 'boolean';

  const isFocusCloudLoading =
    !!focusCamera?.serial &&
    (availableTimesData?.loading || !hasCloudLoadingState);
  const isFocusLocalLoading =
    playbackType === EnumPlaybackType.LOCAL &&
    !!focusCamera?.serial &&
    (availableTimesDataLocal?.loading || !hasLocalLoadingState);

  const isPlaybackTimeLoading = useMemo(() => {
    if (displayMode === PlaybackMainSectionMode.GRID) {
      return (
        isGridCloudLoading ||
        (playbackType === EnumPlaybackType.LOCAL && isGridLocalLoading)
      );
    }

    return (
      isFocusCloudLoading ||
      (playbackType === EnumPlaybackType.LOCAL && isFocusLocalLoading)
    );
  }, [
    displayMode,
    isGridCloudLoading,
    isGridLocalLoading,
    playbackType,
    isFocusCloudLoading,
    isFocusLocalLoading,
  ]);

  const getPlaybackThumbnail = useCallback(
    (queryTime) => {
      const finalQueryTime = computeQueryTime(initialSelectedDate, queryTime);
      if (playbackThumbnails) {
        if (playbackThumbnails?.serial === focusCamera?.serial) {
          const thumbnails = [...(playbackThumbnails?.thumbnails || [])];
          const exist = thumbnails?.find(
            (th) => th?.queryTime === finalQueryTime,
          );
          if (exist && exist?.imageBase64) {
            return exist;
          }
        }
      }
      return getThumbnailPlaybackByTime({
        serial: focusCamera?.serial,
        queryTime: finalQueryTime,
        namespace,
      })
        .then((res) => {
          // beeXLogger.debug('getPlaybackThumbnail - res: ', res);
          dispatch(
            setPlaybackThumbnails({
              serial: res?.serial,
              thumbnails: [
                ...(playbackThumbnails?.thumbnails || []),
                {
                  imageBase64: res?.imageBase64,
                  queryTime: res?.queryTime,
                },
              ],
            }),
          );
          return res;
        })
        .catch((err) => {
          beeXLogger.debug('getPlaybackThumbnail - err: ', err);
          return null;
        });
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [focusCamera, initialSelectedDate, namespace, playbackThumbnails],
  );

  const handleSeek = useCallback(
    (totalSeconds) => {
      if (totalSeconds < minAvailableTime || totalSeconds > maxAvailableTime) {
        return;
      }
      dispatch(
        setPlaybackControls({
          ...(playbackControlsRef.current || {}),
          state: 'play',
        }),
      );
      setPivotTime(totalSeconds);
    },
    [dispatch, setPivotTime, minAvailableTime, maxAvailableTime],
  );

  useEffect(() => {
    if (displayMode !== PlaybackMainSectionMode.FOCUS) return;

    const arr1 = Array.isArray(availableTimesData?.data)
      ? availableTimesData.data
      : [];

    if (playbackType === EnumPlaybackType.CLOUD) {
      setAvailableTimes(arr1);
      return;
    }

    let tmp = availableTimesDataLocal?.data || [];

    tmp = tmp
      ?.map((item) => {
        const fromDate = new Date(item?.from);
        const toDate = new Date(item?.to);
        const selectedDate = new Date(`${initialSelectedDate} 00:00:00`);

        let fromSeconds = Math.floor((fromDate - selectedDate) / 1000);
        let toSeconds = Math.floor((toDate - selectedDate) / 1000);

        if (toSeconds <= 0) return null;
        if (fromSeconds >= 86400) return null;

        return {
          from: Math.max(0, fromSeconds),
          to: Math.min(86400, toSeconds),
        };
      })
      .filter(Boolean);

    const arr2 = Array.isArray(tmp) ? tmp : [];
    const merged = mergePlaybackTimes(arr1, arr2) || [];

    setLastAvailableTimes(merged[merged.length - 1]);
    setAvailableTimes(merged);
  }, [
    displayMode,
    availableTimesData,
    availableTimesDataLocal,
    playbackType,
    initialSelectedDate,
  ]);

  useEffect(() => {
    if (displayMode === PlaybackMainSectionMode.FOCUS) return;

    if (!displayCameras?.length) {
      setAvailableTimes([]);
      setLastAvailableTimes({});
      setIsGridCloudLoading(false);
      setIsGridLocalLoading(false);
      return;
    }

    const camerasToFetch = displayCameras.slice(0, pageSize);
    setIsGridCloudLoading(true);
    setIsGridLocalLoading(playbackType === EnumPlaybackType.LOCAL);

    Promise.all(
      camerasToFetch.map((camera) =>
        getPlaybackTimes({
          serial: camera?.serial,
          namespace,
          fromTime: moment(initialSelectedDate).format(PLAYBACK_DATE_FORMAT),
          toTime: moment(initialSelectedDate)
            .add(1, 'day')
            .format(PLAYBACK_DATE_FORMAT),
        }),
      ),
    )
      .then((res) => {
        console.log(
          '🚀 ~ PlaybackMainFocusLayoutProgressBarContainer ~ getPlaybackTimes:',
          res,
        );
        const cloudTimes = res.flatMap((item) => item?.storageTimes || []);
        setCloudTimes(cloudTimes.sort(sortTime));
      })
      .catch((err) => {
        beeXLogger.error(
          '🚀 ~ PlaybackMainFocusLayoutProgressBarContainer ~ getPlaybackTimes ~ err:',
          err,
        );
        beeXLogger.error('Failed to fetch cloud playback times', err);
        setCloudTimes([]);
      })
      .finally(() => {
        setIsGridCloudLoading(false);
      });

    Promise.all(
      camerasToFetch.map((camera) =>
        getPlaybackTimesLocal({
          serial: camera?.serial,
          namespace,
          fromTime: moment(initialSelectedDate, PLAYBACK_DATE_FORMAT).format(
            PLAYBACK_DATE_TIME_FORMAT,
          ),
          toTime: moment(initialSelectedDate)
            .endOf('day')
            .format(PLAYBACK_DATE_TIME_FORMAT),
        }),
      ),
    )
      .then((res) => {
        console.log(
          '🚀 ~ PlaybackMainFocusLayoutProgressBarContainer ~ getPlaybackTimesLocal:',
          res,
        );
        const localTimes = res.flatMap((item) => item?.storageTimes || []);
        setLocalTimes(localTimes.sort(sortTime));
      })
      .catch((err) => {
        beeXLogger.error(
          '🚀 ~ PlaybackMainFocusLayoutProgressBarContainer ~ getPlaybackTimesLocal ~ err:',
          err,
        );

        setLocalTimes([]);
      })
      .finally(() => {
        setIsGridLocalLoading(false);
      });
  }, [
    displayMode,
    displayCameras,
    pageSize,
    namespace,
    initialSelectedDate,
    playbackType,
  ]);

  useEffect(() => {
    if (displayMode === PlaybackMainSectionMode.GRID) {
      // beeXLogger.debug(
      //   '🚀 ~ PlaybackMainFocusLayoutProgressBarContainer ~ cloudTimes:',
      //   cloudTimes,
      // );
      // beeXLogger.debug(
      //   '🚀 ~ PlaybackMainFocusLayoutProgressBarContainer ~ localTimes:',
      //   localTimes,
      // );
      const convertedLocalTimes = localTimes
        .map((item) => {
          const fromDate = new Date(item?.from);
          const toDate = new Date(item?.to);
          const selectedDate = new Date(`${initialSelectedDate} 00:00:00`);

          let fromSeconds = Math.floor((fromDate - selectedDate) / 1000);
          let toSeconds = Math.floor((toDate - selectedDate) / 1000);

          if (toSeconds <= 0) {
            return null;
          }

          if (fromSeconds >= 86400) {
            return null;
          }

          return {
            from: Math.max(0, fromSeconds),
            to: Math.min(86400, toSeconds),
          };
        })
        .filter(Boolean);
      const mergeTimes = mergePlaybackTimes(cloudTimes, convertedLocalTimes);
      // beeXLogger.debug(
      //   '🚀 ~ PlaybackMainFocusLayoutProgressBarContainer ~ mergeTimes:',
      //   mergeTimes,
      // );
      setAvailableTimes(mergeTimes);
      setLastAvailableTimes({});
    }
  }, [cloudTimes, displayMode, initialSelectedDate, localTimes]);

  useEffect(() => {
    const listener = () => {
      rerender({});
    };

    const unsubscribe = onElapsedTimeChange(listener);
    const unsubscribePivotTimeChange = onPivotTimeChange(listener);

    return () => {
      unsubscribe();
      unsubscribePivotTimeChange();
    };
  }, [onElapsedTimeChange, onPivotTimeChange]);

  useEffect(() => {
    playbackControlsRef.current = playbackControls;
  }, [playbackControls]);

  return (
    <>
      {/* <ProgressBarV2
      onSeek={handleSeek}
      currentTime={currentTime}
      // onDownload={beeXLogger.debug}
      isPlaying={isActive()}
      // onPlayPause={beeXLogger.debug}
      // onPlay={beeXLogger.debug}
      playbackRate={allowPlaybackRateAdvanced ? playbackRate : playbackRate > 8 ? 8 : playbackRate}
      setPlaybackRate={setPlaybackRate}
      playbackRateOptions={playbackRateOptions}
      showRateSelector={allowPlaybackRate}
      maxAvailableTime={maxAvailableTime}
      minAvailableTime={minAvailableTime}
      availableTimes={[...availableTimes, (lastAvailableTimes || {})]}
      getPlaybackThumbnail={(queryTime) => getPlaybackThumbnail(queryTime)}
      serial={focusCamera?.serial}
      name={focusCamera?.name}
      namespace={namespace}
      allowPlaybackRateAdvanced={allowPlaybackRateAdvanced}
      isFullScreen={isFullScreen}
      handleTogglePTZDewarp={handleTogglePTZDewarp}
      ptzDewarpActive={ptzDewarpActive}
      handleFullscreen={handleFullscreen}
      containerRef={containerRef}
      handleMuted={handleMuted}
      muted={muted}
    /> */}
      <ProgressBarV3
        onSeek={handleSeek}
        currentTime={currentTime}
        isPlaybackTimeLoading={isPlaybackTimeLoading}
        isPlaying={isActive()}
        playbackRate={
          allowPlaybackRateAdvanced
            ? playbackRate
            : playbackRate > 8
              ? 8
              : playbackRate
        }
        setPlaybackRate={setPlaybackRate}
        playbackRateOptions={playbackRateOptions}
        showRateSelector={allowPlaybackRate}
        maxAvailableTime={maxAvailableTime}
        minAvailableTime={minAvailableTime}
        availableTimes={[...availableTimes, lastAvailableTimes || {}]}
        getPlaybackThumbnail={(queryTime) => getPlaybackThumbnail(queryTime)}
        serial={focusCamera?.serial}
        name={focusCamera?.name}
        namespace={namespace}
        allowPlaybackRateAdvanced={allowPlaybackRateAdvanced}
        isFullScreen={isFullScreen}
        handleTogglePTZDewarp={handleTogglePTZDewarp}
        ptzDeWarpActive={ptzDeWarpActive}
        handleFullscreen={handleFullscreen}
        containerRef={containerRef}
      />
    </>
  );
};
