import { useContext } from 'react';
import { createContext } from 'react';
import Downloader from './downloader';
import { DEFAULT_PLAYBACK_RATE } from './Main/shared';
import moment from 'moment';
import { PlaybackMainSectionMode } from './Main';

export const PlaybackContext = createContext({
  getPivotTime: () => moment(Date.now()).format('HH:mm:ss'),
  setPivotTime: () => {},
  getElapsedTime: () => 0,
  getCurrentTime: () => 0,
  onElapsedTimeChange: () => () => {},
  reportProgress: () => {},
  removeProgress: () => {},
  onPivotTimeChange: () => () => {},
  isActive: () => false,
  playbackRate: DEFAULT_PLAYBACK_RATE,
  setPlaybackRate: () => {},
  allowPlaybackRate: false,
  onLive: false,
  setOnLive: () => {},
  selectedEvent: null,
  setSelectedEvent: () => {},
  aiEvents: [],
  totalEvents: 0,
  displayMode: PlaybackMainSectionMode.FOCUS,
});

export const usePlaybackContext = () => {
  return useContext(PlaybackContext);
};

export const DownloadContext = createContext({
  downloader: new Downloader(),
});

export const useDownloadContext = () => {
  return useContext(DownloadContext);
};
