import React, {
  useState,
  useRef,
  forwardRef,
  useEffect,
  useCallback,
} from 'react';
import { Button, Tooltip, Select, Input, Popover } from 'antd';
import {
  CaretRightOutlined,
  PauseOutlined,
  LoadingOutlined,
  ReloadOutlined,
  ForwardOutlined,
  EnterOutlined,
} from '@ant-design/icons';
import { ReactComponent as Rewind10Icon } from '@/assets/icons/rewind-10-icon.svg';
import { ReactComponent as Forward10Icon } from '@/assets/icons/forward-10-icon.svg';
import { useTranslation } from 'react-i18next';
import { CloudDownloadOutlined, DownloadOutlined } from '@ant-design/icons';
import ControlIconOff from '@/components/Player/icons/control_camera_off.svg';
import ControlIconOn from '@/components/Player/icons/control_camera_on.svg';
import FullscreenIcon from '@/components/Player/icons/fullscreen.svg';
import ExitFullscreenIcon from '@/components/Player/icons/fullscreen.svg';
import './index.scss';
import { timeToSeconds, formatTime } from './utils';
import { usePlaybackContext } from '../../context';
import { PlaybackMainSectionMode } from '../../Main';

const TimePickerInput = forwardRef(
  (
    {
      value,
      onChange,
      maxValue,
      placeholder = '00',
      onNext,
      autoFocus = false,
      onEnter,
    },
    ref,
  ) => {
    const inputRef = useRef(null);

    React.useEffect(() => {
      if (autoFocus && inputRef.current) {
        inputRef.current.focus();
        const input = inputRef.current.input;
        if (input) {
          input.select();
        }
      }
    }, [autoFocus]);

    const handleChange = (e) => {
      let inputValue = e.target.value;

      inputValue = inputValue.replace(/[^0-9]/g, '');

      if (inputValue.length > 2) {
        inputValue = inputValue.slice(0, 2);
      }

      if (inputValue.length === 2) {
        const numValue = parseInt(inputValue, 10);
        if (numValue > maxValue) {
          inputValue = maxValue.toString().padStart(2, '0');
        }
      }

      onChange(inputValue);

      if (inputValue.length === 2 && onNext) {
        setTimeout(() => onNext(), 0);
      }
    };

    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight' && onNext) {
        onNext();
      }
    };

    const handleFocus = (e) => {
      e.target.select();
    };

    React.useImperativeHandle(ref, () => inputRef.current);

    return (
      <Input
        ref={inputRef}
        type="text"
        inputMode="numeric"
        value={value}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onFocus={handleFocus}
        placeholder={placeholder}
        maxLength={2}
        className="time-picker-input"
        onPressEnter={onEnter}
      />
    );
  },
);

TimePickerInput.displayName = 'TimePickerInput';

const TimePickerContent = ({
  hours,
  minutes,
  seconds,
  onHoursChange,
  onMinutesChange,
  onSecondsChange,
  onConfirm,
  warning,
  t,
  hoursRef,
  minutesRef,
  secondsRef,
}) => {
  useEffect(() => {
    if (
      hoursRef.current &&
      hoursRef.current.input &&
      typeof hoursRef.current.input.focus === 'function'
    ) {
      setTimeout(() => {
        hoursRef.current.input.focus();
        hoursRef.current.input.select();
      }, 100);
    }
  }, [hoursRef]);

  return (
    <div className="time-picker-content">
      <div className="time-picker-title">{t('Set playback time')}</div>
      <div className="time-picker-inputs">
        <div className="time-input-field">
          <TimePickerInput
            ref={hoursRef}
            value={hours}
            onChange={onHoursChange}
            maxValue={23}
            placeholder="00"
            onNext={() => minutesRef.current?.input?.focus()}
            onEnter={onConfirm}
          />
        </div>
        <div className="time-separator">:</div>
        <div className="time-input-field">
          <TimePickerInput
            ref={minutesRef}
            value={minutes}
            onChange={onMinutesChange}
            maxValue={59}
            placeholder="00"
            onNext={() => secondsRef.current?.input?.focus()}
            onEnter={onConfirm}
          />
        </div>
        <div className="time-separator">:</div>
        <div className="time-input-field">
          <TimePickerInput
            ref={secondsRef}
            value={seconds}
            onChange={onSecondsChange}
            maxValue={59}
            placeholder="00"
            onNext={() => null}
            onEnter={onConfirm}
          />
        </div>
        <div className="time-picker-button">
          <Button
            type="primary"
            size="small"
            icon={<EnterOutlined />}
            onClick={onConfirm}
          />
        </div>
      </div>
      {warning && <div className="time-picker-warning">{warning}</div>}
    </div>
  );
};

export const PlaybackControls = ({
  currentTime,
  displayTime,
  playbackControls,
  isTranscodeMode = false,
  isHoldingRef,
  selectedPlaybackRate,
  playbackRate,
  isFullScreen,
  onRewind,
  onPlayPause,
  onForward,
  onForwardHoldStart,
  onForwardHoldEnd,
  zoomRange,
  showRateSelector,
  playbackRateOptions,
  allowBackup,
  ptzDeWarpActive,
  onDownloadClick,
  onZoomRangeChange,
  onPlaybackRateChange,
  onBackup,
  onTogglePTZDeWarp,
  onFullscreen,
  availableTimes = [],
  onSeekTime,
}) => {
  const { t } = useTranslation();
  const [hours, setHours] = useState('');
  const [minutes, setMinutes] = useState('');
  const [seconds, setSeconds] = useState('');
  const [warning, setWarning] = useState('');
  const [timePickerKey, setTimePickerKey] = useState(0);
  const [tooltipOpen, setTooltipOpen] = useState(false);
  const [popoverOpen, setPopoverOpen] = useState(false);
  const { displayMode } = usePlaybackContext();

  const hoursRef = useRef(null);
  const minutesRef = useRef(null);
  const secondsRef = useRef(null);

  const handleTimeClick = () => {
    setPopoverOpen(true);
    setTooltipOpen(false);
    setHours('');
    setMinutes('');
    setSeconds('');
    setWarning('');
    setTimePickerKey((prev) => prev + 1);
  };

  const handleConfirmTime = useCallback(() => {
    const sec = Number(hours) * 3600 + Number(minutes) * 60 + Number(seconds);
    if (isNaN(sec)) {
      setWarning(t('Invalid time'));
      return;
    }
    if (!availableTimes?.some((item) => item?.from <= sec && item?.to >= sec)) {
      setWarning(t('Time not available'));
      return;
    }
    setWarning('');
    if (onSeekTime) onSeekTime(sec);
  }, [hours, minutes, seconds, availableTimes, onSeekTime, t]);

  const handlePopoverChange = (visible) => {
    console.log('🚀 ~ handlePopoverChange ~ visible:', visible);
    setPopoverOpen(visible);
    setWarning('');
    if (visible) {
      setTooltipOpen(false);
    }
  };

  return (
    <div className="playback-controls-container">
      <div
        className={`time-display-wrapper ${
          isFullScreen ? 'fullscreen' : 'normal'
        }`}
      >
        <Popover
          content={
            <TimePickerContent
              key={timePickerKey}
              hours={hours}
              minutes={minutes}
              seconds={seconds}
              onHoursChange={setHours}
              onMinutesChange={setMinutes}
              onSecondsChange={setSeconds}
              onConfirm={handleConfirmTime}
              warning={warning}
              t={t}
              hoursRef={hoursRef}
              minutesRef={minutesRef}
              secondsRef={secondsRef}
            />
          }
          title={null}
          trigger="click"
          onVisibleChange={handlePopoverChange}
          placement="top"
          overlayClassName="time-picker-popover"
        >
          <Tooltip
            open={tooltipOpen && !popoverOpen}
            title="Click to set time"
            onOpenChange={(open) => setTooltipOpen(open)}
            placement="top"
          >
            <div onClick={handleTimeClick}>
              {formatTime(
                currentTime > displayTime ? currentTime : displayTime,
              )}
            </div>
          </Tooltip>
        </Popover>
      </div>

      {displayMode === PlaybackMainSectionMode.FOCUS &&
        !isFullScreen &&
        !isTranscodeMode && (
          <>
            <div
              className={`controls-center ${isFullScreen ? 'fullscreen' : ''}`}
            >
              <Tooltip
                title={
                  currentTime && playbackControls?.state === 'play'
                    ? t('Rewind')
                    : null
                }
              >
                <Button
                  className={`control-button ${
                    !currentTime ||
                    playbackControls?.state === 'loading' ||
                    playbackControls?.state === 'reload'
                      ? 'disabled'
                      : ''
                  } border-white btn-control`}
                  disabled={
                    !currentTime ||
                    playbackControls?.state === 'loading' ||
                    playbackControls?.state === 'reload'
                  }
                  type={
                    playbackControls?.direction === 'reverse' &&
                    isHoldingRef.current
                      ? 'primary'
                      : 'default'
                  }
                  shape="circle"
                  icon={<Rewind10Icon />}
                  onClick={onRewind}
                />
              </Tooltip>

              <Tooltip
                title={t(
                  currentTime
                    ? playbackControls?.state === 'pause'
                      ? 'Play'
                      : playbackControls?.state === 'play'
                        ? 'Pause'
                        : playbackControls?.state === 'reload'
                          ? 'Reload'
                          : playbackControls?.state === 'loading'
                            ? ''
                            : ''
                    : null,
                )}
              >
                <Button
                  className={`control-button ${
                    !currentTime || playbackControls?.state === 'loading'
                      ? 'disabled'
                      : ''
                  } btn-control`}
                  disabled={
                    !currentTime || playbackControls?.state === 'loading'
                  }
                  type="default"
                  shape="circle"
                  icon={
                    currentTime ? (
                      playbackControls?.state === 'pause' ? (
                        <CaretRightOutlined />
                      ) : playbackControls?.state === 'play' ? (
                        <PauseOutlined />
                      ) : playbackControls?.state === 'reload' ? (
                        <ReloadOutlined />
                      ) : playbackControls?.state === 'loading' ? (
                        <LoadingOutlined />
                      ) : (
                        <PauseOutlined />
                      )
                    ) : (
                      <CaretRightOutlined />
                    )
                  }
                  onClick={onPlayPause}
                />
              </Tooltip>

              <Tooltip
                title={
                  currentTime && playbackControls?.state === 'play'
                    ? selectedPlaybackRate === 1
                      ? 'Forward'
                      : !isHoldingRef.current
                        ? t('Press and hold to speed up')
                        : null
                    : null
                }
              >
                <Button
                  className={`control-button ${
                    !currentTime ||
                    playbackControls?.state === 'loading' ||
                    playbackControls?.state === 'reload'
                      ? 'disabled'
                      : ''
                  } btn-control`}
                  disabled={
                    !currentTime ||
                    playbackControls?.state === 'loading' ||
                    playbackControls?.state === 'reload'
                  }
                  type={
                    playbackControls?.direction === 'forward' &&
                    isHoldingRef.current
                      ? 'primary'
                      : 'default'
                  }
                  shape="circle"
                  icon={
                    !isHoldingRef.current ? (
                      selectedPlaybackRate === 1 ? (
                        <Forward10Icon />
                      ) : (
                        <ForwardOutlined />
                      )
                    ) : playbackRate <= 1 ? (
                      <Forward10Icon />
                    ) : (
                      <ForwardOutlined />
                    )
                  }
                  onClick={onForward}
                  onMouseDown={onForwardHoldStart}
                  onMouseUp={onForwardHoldEnd}
                  onMouseLeave={onForwardHoldEnd}
                  onTouchStart={onForwardHoldStart}
                  onTouchEnd={onForwardHoldEnd}
                />
              </Tooltip>
            </div>
          </>
        )}

      <div className={`controls-right ${isFullScreen ? 'fullscreen' : ''}`}>
        {displayMode === PlaybackMainSectionMode.FOCUS && (
          <>
            <Tooltip placement="topRight" title={t('View downloading')}>
              <Button
                type="default"
                className="rounded-full"
                onClick={onDownloadClick}
                icon={<DownloadOutlined />}
              />
            </Tooltip>

            {showRateSelector && !isTranscodeMode && (
              <Select
                virtual={false}
                size="sm"
                options={playbackRateOptions}
                value={selectedPlaybackRate}
                onChange={onPlaybackRateChange}
                className="rate-selector-container bg-transparent rounded-full playback-rate-selector border-brand border border-solid"
                getPopupContainer={(trigger) => trigger.parentElement}
              />
            )}

            {allowBackup && (
              <Tooltip title="Backup">
                <Button
                  type="default"
                  className="rounded-full"
                  onClick={onBackup}
                >
                  <CloudDownloadOutlined />
                </Button>
              </Tooltip>
            )}
          </>
        )}

        {isFullScreen && currentTime > 0 && (
          <div
            className={`fullscreen-controls-group ${
              !isFullScreen ? 'normal' : ''
            }`}
          >
            <img
              src={ptzDeWarpActive ? ControlIconOn : ControlIconOff}
              alt="PTZ Dewarp"
              width={24}
              height={24}
              onClick={onTogglePTZDeWarp}
              className="control-icon-button"
            />
            <img
              src={isFullScreen ? ExitFullscreenIcon : FullscreenIcon}
              alt="Fullscreen"
              width={24}
              height={24}
              onClick={onFullscreen}
              className="control-icon-button"
            />
          </div>
        )}
      </div>
    </div>
  );
};
