import { Card, Divider } from "antd";
import React from "react";
import SiteIcon from './icons/site_icon.svg'
import AccountIcon from './icons/account_icon.svg'
import CameraActiveIcon from './icons/camera_active_icon.svg'
import CameraStorageIcon from './icons/camera_storage_icon.svg'
import GatewayActiveIcon from './icons/gateway_active_icon.svg'
import ReportIcon from './icons/report_icon.svg'
import { Link } from 'react-router-dom';
import { useTranslation } from "react-i18next";

import './index.scss'

export const SiteItem = ({ data }) => {
  const { t } = useTranslation()

  return (
    <Card className="site-item p-2 rounded-md border-none">
      <div className="w-full flex justify-start items-center gap-2">
        <img src={SiteIcon} alt="site" />
        <span className="text-brand font-medium">{data?.name}</span>
      </div>
      <Divider className="my-2 bg-stroke" />
      <div className="mt-4 flex flex-col gap-5 justify-start">
        <div className="flex justify-between w-full">
          <div className="flex gap-2">
            <img src={GatewayActiveIcon} alt="site" />
            <span>{t("Gateway active")}</span>
          </div>
          <span>{data?.gatewayOnlines?.length}</span>
        </div>
        <div className="flex justify-between w-full">
          <div className="flex gap-2">
            <img src={CameraActiveIcon} alt="site" />
            <span>{t("Camera active")}</span>
          </div>
          <span>{data?.cameraOnlines?.length}</span>
        </div>
        <div className="flex justify-between w-full">
          <div className="flex gap-2">
            <img src={CameraStorageIcon} alt="site" />
            <span>{t("Camera storage")}</span>
          </div>
          <span>{data?.cameraStorages?.length}</span>
        </div>
        <div className="flex justify-between w-full">
          <div className="flex gap-2">
            <img src={AccountIcon} alt="site" />
            <span>{t("Account")}</span>
          </div>
          <span>{data?.accounts ? JSON.parse(data?.accounts || '[]')?.length : 0}</span>
        </div>
        <div className="flex justify-between w-full">
          <div className="flex gap-2">
            <img src={ReportIcon} alt="site" />
            <span>{t("Report")}</span>
          </div>
          <Link to="/report" className="underline text-brand hover:no-underline cursor-pointer">{t('View')}</Link>
        </div>
      </div>
    </Card>
  )
}