import React from 'react';
import { Popconfirm } from 'antd';
import { useTranslation } from 'react-i18next';
import './index.scss';
import { SECONDS_IN_DAY, timeToSeconds } from './utils';
import { usePlaybackContext } from '../../context';
import { PlaybackMainSectionMode } from '../../Main';

export const ProgressBar = ({
  progressRef,
  progressInnerRef,
  progressThumbRef,
  isPlaybackTimeLoading,
  zoomLevel,
  originPct,
  mergedAvailableSegments,
  downloadRanges,
  serial,
  playbackType,
  dragRangeStart,
  dragRangeEnd,
  hasNewRange,
  popConfirmKey,
  isLoadingConfirm,
  handleProgressMouseDownForRange,
  handleMouseMove,
  handleMouseLeave,
  handleScrubberMouseDown,
  displayTimeForOrigin,
  onConfirmNewRange,
  onCancelNewRange,
}) => {
  const { t } = useTranslation();
  const { displayMode } = usePlaybackContext();
  return (
    <div className="relative mt-2 mb-0 rounded-2xl cursor-pointer">
      {downloadRanges &&
        downloadRanges.length > 0 &&
        downloadRanges
          .filter(
            (item) =>
              item?.serial === serial && item?.playbackType === playbackType,
          )
          .map(
            (downloadRange, index) =>
              downloadRange.fromTime &&
              downloadRange.toTime && (
                <div
                  key={`download-${index}`}
                  className="absolute h-full"
                  style={{
                    top: 0,
                    transform: 'translateY(-50%)',
                    left: `${(timeToSeconds(downloadRange.fromTime) / SECONDS_IN_DAY) * 100}%`,
                    width: `${(Math.abs(timeToSeconds(downloadRange.toTime) - timeToSeconds(downloadRange.fromTime)) / SECONDS_IN_DAY) * 100}%`,
                    backgroundColor: 'transparent',
                    zIndex: 25,
                    pointerEvents: 'none',
                  }}
                />
              ),
          )}

      <Popconfirm
        className="z-50"
        key={popConfirmKey}
        title={
          hasNewRange
            ? t('Are you sure to download this range {{from}} - {{to}}', {
                from: hasNewRange?.fromTime,
                to: hasNewRange?.toTime,
              })
            : null
        }
        onConfirm={onConfirmNewRange}
        onCancel={onCancelNewRange}
        okText="Yes"
        cancelText="No"
        visible={hasNewRange}
        destroyTooltipOnHide={true}
        getPopupContainer={(trigger) =>
          trigger ? trigger?.parentElement : document.body || document.body
        }
        okButtonProps={{
          loading: isLoadingConfirm,
          disabled: isLoadingConfirm,
        }}
        trigger={[]}
      >
        {dragRangeStart !== null && dragRangeEnd !== null && dragRangeEnd - dragRangeStart > 10 ? (
          <div
            className="absolute h-full"
            style={{
              top: 0,
              transform: 'translateY(-50%)',
              left: `${(Math.min(dragRangeStart, dragRangeEnd) / SECONDS_IN_DAY) * 100}%`,
              width: `${(Math.abs(dragRangeEnd - dragRangeStart) / SECONDS_IN_DAY) * 100}%`,
              backgroundColor: 'rgba(68, 185, 123, 0.5)',
              zIndex: 26,
              pointerEvents: 'none',
              border: '1px solid #44b97b',
            }}
          />
        ) : (
          <span style={{ display: 'none' }}></span>
        )}
      </Popconfirm>

      <div
        className={`relative cursor-pointer shadow-inner rounded-2xl h-2 playback-progress-track ${
          isPlaybackTimeLoading ? 'is-loading' : ''
        }`}
        ref={progressRef}
        onMouseDown={(e) => {
          if (displayMode === PlaybackMainSectionMode.GRID) return null;
          handleProgressMouseDownForRange(e);
        }}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
      >
        <div
          ref={progressInnerRef}
          className="absolute inset-0 transition-all"
          style={{
            transform: zoomLevel > 1 ? `scaleX(${zoomLevel})` : 'none',
            transformOrigin: `${originPct}% 50%`,
          }}
        >
          {mergedAvailableSegments.map((seg, index) => {
            const leftPct = (seg.from / SECONDS_IN_DAY) * 100;
            const widthPct = ((seg.to - seg.from) / SECONDS_IN_DAY) * 100;
            return (
              <div
                key={index}
                className="absolute h-full"
                style={{
                  left: `${leftPct}%`,
                  width: `${widthPct}%`,
                  zIndex: 2,
                  backgroundColor: seg?.box
                    ? '#0a3d88'
                    : seg?.cloud
                      ? '#028fd5'
                      : '#6ecfff',
                }}
                onMouseMove={handleMouseMove}
                onMouseLeave={handleMouseLeave}
              />
            );
          })}
        </div>

        <div
          ref={progressThumbRef}
          className="progress-thumb"
          style={{
            left: `${(displayTimeForOrigin / SECONDS_IN_DAY) * 100}%`,
          }}
          onMouseDown={handleScrubberMouseDown}
        />
      </div>
    </div>
  );
};
