import { Col, Row, Tag, Tooltip } from 'antd';
import React, {
  useCallback,
  useEffect,
  useRef,
  useState,
  useMemo,
} from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import IconCameraOnvif from '../../assets/icons/camera_onvif.svg';
import IconCameraRtsp from '../../assets/icons/camera_rtsp.svg';
import Info from '../../assets/icons/info.svg';
import Info11 from '../../assets/icons/info_11.svg';
import Info12 from '../../assets/icons/info_12.svg';
import Info3 from '../../assets/icons/info_3.svg';
import Info5 from '../../assets/icons/info_5.svg';
import Info6 from '../../assets/icons/info_6.svg';
import Info7 from '../../assets/icons/info_7.svg';
import LiveIconOn from '../../assets/icons/live-streaming-on.svg';
import OffStream from '../../assets/icons/off_stream.svg';
import PlayIconNoActive from '../../assets/icons/play-button-no-active.svg';
import PlayIcon from '../../assets/icons/play-button.svg';
import Thumbnail from '../../assets/images/thumbnail.jpg';
import * as SERVICE from '../../constants/service.types';
import { ZOOM_STATE } from '../../constants/system.keys';
import useWindowDimensions from '../../hooks/useWindowDimensions';
import {
  changeDialPadData,
  getEndStreamReturn,
  getEndStreamUtraFastReturn,
  removeStream,
  socketEmitEvent,
} from '../../redux/actions';

import { calcPercentForVideo } from '../../untils/css';
import PlayerComponent from '../Player/v2';
import { RTCCodecAdapter } from './adapter/rtc-codec';
import { HLSAdapter } from './adapter/hls';
import './index.scss';
import { ReactComponent as SettingIcon } from '@/assets/icons/setting-black-icon.svg';
import { setCameraToSetting } from '@/redux/camera/action';
import { StateTag } from '../StateTag';
import { beeXLogger } from '@/helpers/logger';
import { getCameraToSetting } from '@/redux/camera/reducer';
import { useLatestCameraState } from '@/hooks/use-latest-camera-state';
import { CAMERA_BRAND } from '@/constants/camera';
import { STEP_STATE } from '../Player/StreamConnectStep';

const INITIAL_STREAM_CONNECT_STATES = {
  1: STEP_STATE.PENDING,
  2: STEP_STATE.PENDING,
  3: STEP_STATE.PENDING,
  4: STEP_STATE.PENDING,
};

// const RETRY_PAUSE = 2000;
// var pc_config = {
//   iceServers: [{ urls: 'stun:stun01.beex.vn:3478' }],
//   bundlePolicy: 'balanced',
//   rtcpMuxPolicy: 'negotiate',
//   sdpSemantics: 'unified-plan',
// };
// var pc_constraints = { optional: [{ DtlsSrtpKeyAgreement: true }] };

const hasHLS = (streaming) => {
  if (!streaming) {
    return false;
  }

  return (
    streaming.protocol === 'hls' ||
    (streaming.path && streaming.wsHost && streaming.hlsPort)
  );
};

const hasRTC = (streaming) => {
  if (!streaming) {
    return false;
  }

  return (
    streaming.protocol === 'webrtc' ||
    (streaming.path && streaming.wsHost && streaming.wssPort)
  );
};

// const getStreamModes = (streaming) => {
//   const streamModes = [];

//   if (hasHLS(streaming)) {
//     streamModes.push('hls');
//   }

//   if (hasRTC(streaming)) {
//     streamModes.push('webrtc');
//   }

//   return streamModes;
// };

const getMode = (adapter) => {
  if (adapter instanceof RTCCodecAdapter) {
    return 'webrtc';
  }

  return 'hls';
};

// check if hls port is available
const getAdapter = (streaming, namespace) => {
  console.log('STREAMING: ', JSON.parse(JSON.stringify(streaming)));
  if (namespace === 'pharmacity.vn') {
    return RTCCodecAdapter;
  }

  if (streaming.protocol === 'webrtc') {
    return RTCCodecAdapter;
  }

  if (streaming.protocol === 'hls') {
    return HLSAdapter;
  }

  if (hasRTC(streaming)) {
    return RTCCodecAdapter;
  }

  if (hasHLS(streaming)) {
    return HLSAdapter;
  }

  return HLSAdapter;
};

const RETRY_DURATION = 5000;
const sortZoomStateAsc = (z1, z2) => {
  return z1.resolution - z2.resolution;
};

const ViewStreamComponent = ({
  serial,
  gatewaySerial,
  name,
  typeCamera,
  state: cameraState,
  resolution,
  iconSize,
  isInternal,
  thumbnail,
  zoomState,
  serviceId,
  isViewAll,
  permission,
  isAllowStreaming,
  allScreen,
  brand,
  cameraSubSources,
  cameraMainSource,
  variantPage,
  allowAudio = false,
  showSetting = false,
  showTopName = true,
  showBottomName = true,
  camera,
  pageSize,
  onFullscreenChange,
  isFullScreenMode,
}) => {
  const { t } = useTranslation();
  const [isFullscreen, setIsFullscreen] = useState(false);
  const dispatch = useDispatch();
  const { width: windowWidth, height: windowHeight } = useWindowDimensions();
  const [cameraSource, setCameraSource] = useState([]);
  const state = useLatestCameraState({ serial, defaultState: cameraState });

  useEffect(() => {
    if (cameraSubSources) {
      const tmp = JSON.parse(cameraSubSources)?.map((item) => ({
        zoomState: item.zoomState,
        source: item.source,
      }));
      setCameraSource([...tmp, cameraMainSource] || [cameraMainSource]);
    }
  }, [cameraSubSources, cameraMainSource]);

  const {
    streams,
    namespace,
    listDeviceContact,
    streamToken,
    dataUser,
    socketState,
  } = useSelector((state) => state);
  const [streaming, setStreaming] = useState();
  const [waitForWatch, setWaitForWatch] = useState(0);
  const [streamSerial, setStreamSerial] = useState(serial);
  const [isConnected, setIsConnected] = useState(false);
  const [loading, setLoading] = useState(false);
  const refTryLoad = useRef();
  const [tryLoadTimer, setTryLoadTimer] = useState(10);
  const [isLoadReload, setIsLoadReload] = useState(false);
  const [onPlay, setOnPlay] = useState(false);
  const [checkTransferZoomState, setCheckTransferZoomState] = useState(false);
  const [zoomStatePlayer, setZoomStatePlayer] = useState();
  const [zoomStateDefault, setZoomStateDefault] = useState();
  const [internal, setInternal] = useState(null);
  const onlineRestartTimeout = useRef();
  const adapterRef = useRef();
  const [output, setOutput] = useState(null);
  const outputRef = useRef(output);
  outputRef.current = output;
  const streamRef = useRef(streaming);
  streamRef.current = streaming;
  const createStreamRetryTimeout = useRef(null);
  const videoRef = useRef(null);
  const retryRef = useRef({
    count: 0,
    maxCircle: 3,
    // doesnt mean success but that means at this index, the stream is either success or manually selected by the user
    settledAt: null,
    data: zoomState?.dataZoomStates.sort(sortZoomStateAsc) || [],
  });
  const requestIdRef = useRef(null);
  const isMountedRef = useRef(true);
  const requestStreamPlayed = useRef({});
  const cameraToSetting = useSelector(getCameraToSetting);

  const hlsFatal = useRef(false);

  // useEffect(() => {
  //   setForcePlay(prev => ({ ...prev, [serial]: onPlay }))
  // }, [onPlay, serial]);

  const [streamConnectStep, setStreamConnectStep] = useState(null);
  const [streamConnectStepStates, setStreamConnectStepStates] = useState(
    INITIAL_STREAM_CONNECT_STATES,
  );
  const [streamConnectError, setStreamConnectError] = useState(null);
  const [streamConnectErrorStep, setStreamConnectErrorStep] = useState(null);
  const hasStreamOutputRef = useRef(false);
  const latestState = useLatestCameraState({ serial, defaultState: state });

  const resetStreamConnectStatus = useCallback(() => {
    setStreamConnectError(null);
    setStreamConnectErrorStep(null);
  }, []);

  const setStreamConnectLoadingStep = useCallback((step) => {
    setStreamConnectStep(step);
    setStreamConnectStepStates({
      1: step > 1 ? STEP_STATE.DONE : STEP_STATE.LOADING,
      2:
        step > 2
          ? STEP_STATE.DONE
          : step === 2
            ? STEP_STATE.LOADING
            : STEP_STATE.PENDING,
      3:
        step > 3
          ? STEP_STATE.DONE
          : step === 3
            ? STEP_STATE.LOADING
            : STEP_STATE.PENDING,
      4: STEP_STATE.PENDING,
    });
  }, []);

  const setStreamConnectSuccess = useCallback(() => {
    setStreamConnectStep(4);
    setStreamConnectStepStates({
      1: STEP_STATE.DONE,
      2: STEP_STATE.DONE,
      3: STEP_STATE.DONE,
      4: STEP_STATE.DONE,
    });
  }, []);

  const setStreamConnectFailedAtStep3 = useCallback(() => {
    setStreamConnectStep(3);
    setStreamConnectStepStates({
      1: STEP_STATE.DONE,
      2: STEP_STATE.DONE,
      3: STEP_STATE.FAILURE,
      4: STEP_STATE.PENDING,
    });
  }, []);

  const setStreamConnectFailedAtStep2 = useCallback(() => {
    setStreamConnectStep(2);
    setStreamConnectStepStates({
      1: STEP_STATE.DONE,
      2: STEP_STATE.FAILURE,
      3: STEP_STATE.PENDING,
      4: STEP_STATE.PENDING,
    });
  }, []);

  useEffect(() => {
    if (onPlay) {
      setStreamConnectLoadingStep(1);
      resetStreamConnectStatus();
    }
  }, [onPlay, resetStreamConnectStatus, setStreamConnectLoadingStep]);

  const isHlsStreaming = useMemo(
    () =>
      streaming?.hlsPort &&
      streaming?.protocol === 'hls' &&
      namespace !== 'pharmacity.vn',
    [streaming, namespace],
  );

  retryRef.current.data =
    zoomState?.dataZoomStates.sort(sortZoomStateAsc) || [];

  // useEffect(() => {
  //   setOnPlay(forcePlay)
  // }, [forcePlay]);

  const cancelRetry = useCallback(() => {
    if (createStreamRetryTimeout.current) {
      clearTimeout(createStreamRetryTimeout.current);
      createStreamRetryTimeout.current = null;
    }
  }, []);

  const scheduleRetry = useCallback(
    (callback) => {
      cancelRetry();
      createStreamRetryTimeout.current = setTimeout(() => {
        retryRef.current.count++;
        createStreamRetryTimeout.current = null;
        callback();
      }, RETRY_DURATION);
    },
    [cancelRetry],
  );

  const markSettle = useCallback(() => {
    retryRef.current.settledAt = retryRef.current.count;
  }, []);

  const createStream = useCallback(
    (dataBody) => {
      beeXLogger.debug('CREATE STREAM', dataBody);
      cancelRetry();

      if (requestIdRef.current) {
        return;
      }

      if (!navigator.onLine || socketState !== 1) {
        console.log('ABORT CREATE STREAM, NOT ONLINE', camera?.name);
        setStreamConnectError('No internet access');
        setStreamConnectErrorStep(1);
        setStreamConnectStepStates({
          1: STEP_STATE.FAILURE,
          2: STEP_STATE.PENDING,
          3: STEP_STATE.PENDING,
          4: STEP_STATE.PENDING,
        });
        adapterRef.current.destroy();
        adapterRef.current = null;
        setOutput(null);
        requestIdRef.current = null;
        dispatch(removeStream());
        setStreaming(null);
        return;
      }

      setCamPlaying(false);
      hasStreamOutputRef.current = false;
      setStreamConnectLoadingStep(1);
      resetStreamConnectStatus();
      setStreaming(null);
      setOutput(null);

      const data = {
        serial: dataBody.serial,
        namespace: dataBody.namespace,
        type: dataBody.type,
        qualityLevel:
          dataBody.qualityLevel ?? zoomState?.zoomState ?? ZOOM_STATE.FOUR,
        retry: dataBody.retry,
        serviceId: dataBody.serviceId,
      };

      if (isFullScreenMode) {
        data.present = 'fullscreen';
      }

      const newZoomState = zoomState?.dataZoomStates?.find(
        (item) => item.zoomState === data.qualityLevel,
      );

      setZoomStatePlayer((prev) => ({
        ...prev,
        ...newZoomState,
      }));

      const requestId = new Date().getTime() + Math.floor(Math.random() * 1000);

      requestIdRef.current = requestId;

      console.log('🚀 ~ ViewStreamComponent ~ data:', data);
      let dataObj = {
        appServiceType: SERVICE.START_STREAM_MONITOR,
        requestId,
        body: JSON.stringify(data),
      };
      console.log('🚀 ~ ViewStreamComponent ~ dataObj:', dataObj);
      setWaitForWatch(requestId);
      dispatch(socketEmitEvent(dataObj));

      setStreamConnectLoadingStep(2);

      const retry = (checkHls = false) => {
        if (!isMountedRef.current || requestIdRef.current !== requestId) {
          return;
        }

        const diff = retryRef.current.count - (retryRef.current.settledAt || 0);
        const shouldForceRetry =
          diff > 0 && diff % retryRef.current.maxCircle === 0;

        const isVideoPlaying = (video) =>
          !!(
            video &&
            video.currentTime > 0 &&
            !video.paused &&
            !video.ended &&
            video.readyState > 2
          );

        if (typeof outputRef.current === 'string') {
          if (isVideoPlaying(videoRef.current)) {
            markSettle();
            return;
          }

          if (checkHls) {
            scheduleRetry(() => retry(false));
          } else {
            createStream({
              ...data,
              retry: shouldForceRetry ? 1 : 0,
            });
          }
          return;
        }

        if (!outputRef.current || !videoRef.current) {
          createStream({
            ...data,
            retry: shouldForceRetry ? 1 : 0,
          });
          return;
        }

        markSettle();
      };

      scheduleRetry(() => retry(true));
    },
    [
      cancelRetry,
      dispatch,
      isFullScreenMode,
      markSettle,
      resetStreamConnectStatus,
      scheduleRetry,
      setStreamConnectLoadingStep,
      zoomState.dataZoomStates,
      zoomState.zoomState,
      socketState,
    ],
  );

  const destroyStreaming = useCallback(() => {
    if (adapterRef.current) {
      adapterRef.current.destroy();
      adapterRef.current = null;
    }
    requestIdRef.current = null;
    dispatch(removeStream(serial));

    if (streaming?.streamMonitorId) {
      const { streamId, serial } = streaming;

      if (streamId) {
        dispatch(getEndStreamReturn(streamId));
      } else {
        dispatch(getEndStreamUtraFastReturn(serial));
      }
      let dataBody = {
        streamId,
        namespace,
      };

      let dataObj = {
        appServiceType: SERVICE.STOP_STREAM,
        requestId: new Date().getTime(),
        body: JSON.stringify(dataBody),
      };
      dispatch(socketEmitEvent(dataObj));
      dispatch(getEndStreamReturn(streamId));
    }
  }, [dispatch, serial, streaming, namespace]);

  const renewStreaming = useCallback(
    (isManual = false) => {
      console.log('RENEW STREAMING');
      hasStreamOutputRef.current = false;
      setStreamConnectLoadingStep(1);
      resetStreamConnectStatus();
      let dataBody = {
        namespace,
        serial,
        type: internal ? 'internal' : 'external',
        serviceId,
        retry: 1,
      };

      destroyStreaming();
      createStream(dataBody);
    },
    [
      destroyStreaming,
      createStream,
      namespace,
      serial,
      internal,
      serviceId,
      resetStreamConnectStatus,
      setStreamConnectLoadingStep,
    ],
  );

  const playStreaming = useCallback(() => {
    if (!adapterRef.current || !streaming) {
      return;
    }

    if (
      requestIdRef.current &&
      requestStreamPlayed.current[requestIdRef.current]
    ) {
      return;
    }

    beeXLogger.debug('PLAY STREAMING', streaming);
    setStreamConnectLoadingStep(3);
    resetStreamConnectStatus();
    adapterRef.current.connect(
      streaming,
      { streamToken: streaming?.streamToken },
      (output) => {
        beeXLogger.debug('CONNECT STREAM OUTPUT: ', output);
        hasStreamOutputRef.current = true;
        resetStreamConnectStatus();
        setOutput(output);
        requestStreamPlayed.current = {
          ...requestStreamPlayed.current,
          [requestIdRef.current]: true,
        };
      },
      renewStreaming,
    );
  }, [
    streaming,
    renewStreaming,
    resetStreamConnectStatus,
    setStreamConnectLoadingStep,
  ]);

  useEffect(() => {
    return () => {
      cancelRetry();
    };
  }, [cancelRetry]);

  useEffect(() => {
    if (!streaming) {
      if (adapterRef.current) {
        adapterRef.current.destroy();
        adapterRef.current = null;
      }
      return;
    }

    if (!adapterRef.current) {
      const Adapter = getAdapter(streaming, namespace);
      adapterRef.current = new Adapter();
    }

    if (onPlay) {
      setTimeout(() => {
        playStreaming();
      }, 0);
    }
  }, [streaming, namespace]);

  useEffect(() => {
    if (onPlay && adapterRef.current && streaming) {
      setTimeout(() => {
        playStreaming();
      }, 0);
    }
  }, [onPlay, playStreaming]);

  useEffect(() => {
    if (!streaming) {
      if (adapterRef.current) {
        adapterRef.current.destroy();
        adapterRef.current = null;
      }
    }
  }, [streaming]);

  useEffect(() => {
    if (onPlay) {
      playStreaming();
    }
  }, [onPlay, playStreaming]);

  const sourceObject = useMemo(() => {
    if (!output) {
      return;
    }

    if (typeof output === 'string') {
      return {
        link: output,
        mode: 'hls',
      };
    }

    return output;
  }, [output]);

  useEffect(() => {
    (async () => {
      if (gatewaySerial && internal === null) {
        try {
          const url = `https://${gatewaySerial}.ezcam.vn:9090/info`;
          const promise = await fetch(url, {
            signal: AbortSignal.timeout(3000),
          });
          const response = await promise.json();
          setInternal(response?.localMedia === 'on');
        } catch (e) {
          setInternal(false);
        } finally {
        }
      }
    })();
  }, [gatewaySerial, internal]);

  useEffect(() => {
    let timeoutClear;
    if (
      onPlay &&
      dataUser?.accountConfiguration &&
      JSON.parse(dataUser?.accountConfiguration)?.liveTimeout > 0
    ) {
      const dataTimeout = JSON.parse(
        dataUser?.accountConfiguration,
      )?.liveTimeout;
      timeoutClear = setTimeout(() => {
        setStreaming(null);
        setOnPlay(false);
      }, dataTimeout * 1000);
      return () => {
        clearTimeout(timeoutClear);
      };
    }
  }, [onPlay, dataUser]);

  useEffect(() => {
    if (zoomState) {
      setZoomStatePlayer(zoomState);
    }
  }, [zoomState]);

  const handleTryLoad = () => {
    setIsLoadReload(true);
    refTryLoad.current = setInterval(() => {
      setTryLoadTimer((timer) => timer - 1);
    }, 1000);

    cancelRetry();
    markSettle();

    //Create stream on reload
    setStreamSerial(serial);
    let dataBody = {
      namespace,
      serial,
      type: internal ? 'internal' : 'external',
      serviceId,
      retry: 0,
    };
    createStream(dataBody);
  };

  useEffect(() => {
    if (isViewAll) {
      setOnPlay(true);
    }
  }, [isViewAll]);

  useEffect(() => {
    if (streaming && streaming.started && !isConnected) {
      clearInterval(refTryLoad.current);
      setIsConnected(true);
    }
  }, [isConnected, streaming]);

  useEffect(() => {
    if (streams && streams?.length > 0 && streamSerial && !streaming) {
      const matchedStream = streams.filter(
        (stream) =>
          stream.serial === streamSerial &&
          stream?.requestId === requestIdRef.current,
      )[0];
      if (matchedStream) {
        setStreamConnectLoadingStep(2);
        resetStreamConnectStatus();
      }
      setStreaming(matchedStream);
    }
  }, [
    streamSerial,
    streams,
    streaming,
    resetStreamConnectStatus,
    setStreamConnectLoadingStep,
  ]);

  const createStreamEffectKeyRef = useRef('');

  // Create Stream
  useEffect(() => {
    if (!onPlay) {
      createStreamEffectKeyRef.current = '';
      return;
    }

    if (latestState <= 0) {
      return;
    }

    if (!serial || !serviceId) {
      return;
    }

    const requestKey = [
      namespace,
      serial,
      serviceId,
      internal ? 'internal' : 'external',
    ].join('|');

    if (createStreamEffectKeyRef.current === requestKey) {
      return;
    }

    createStreamEffectKeyRef.current = requestKey;

    console.log('ON PLAY', {
      onPlay,
      latestState,
      serial,
      serviceId,
    });

    setLoading(true);
    setStreamSerial(serial);
    let dataBody = {
      namespace,
      serial,
      type: internal ? 'internal' : 'external',
      serviceId,
      retry: 0,
    };
    createStream(dataBody, 'uef onPlay');
  }, [
    createStream,
    internal,
    namespace,
    onPlay,
    serial,
    serviceId,
    latestState,
  ]);

  const onChangeHover = useCallback(() => {
    if (serial && namespace) {
      let dataBody = {
        namespace,
        serial,
      };
      let dataObj = {
        appServiceType: SERVICE.GET_DEVICE_CONTACT_INFO,
        requestId: new Date().getTime(),
        body: JSON.stringify(dataBody),
      };
      dispatch(socketEmitEvent(dataObj));
    }
  }, [serial, namespace, dispatch]);

  const restartCallBack = useCallback(
    (dataObject) => {
      cancelRetry();
      markSettle();
      requestIdRef.current = null;

      beeXLogger.debug('RESTART CALLBACK:', dataObject, serial, streaming);
      if (serial) {
        if (streaming) {
          const { streamId, serial } = streaming;

          if (streamId) {
            dispatch(getEndStreamReturn(streamId));
          } else {
            dispatch(getEndStreamUtraFastReturn(serial));
          }
        }

        let dataBody = {
          namespace,
          serial,
          type: internal ? 'internal' : 'external',
          serviceId,
          qualityLevel: dataObject?.qualityLevel,
          retry: 1,
        };
        createStream(dataBody);
      }
    },
    [
      cancelRetry,
      createStream,
      dispatch,
      internal,
      markSettle,
      namespace,
      serial,
      serviceId,
      streaming,
    ],
  );

  const restartLoadingCallBack = useCallback(
    (dataObject) => {
      requestIdRef.current = null;
      cancelRetry();
      markSettle();

      console.log('RESTART LOADING CALLBACK:', dataObject, serial);
      if (serial) {
        dispatch(getEndStreamUtraFastReturn(serial));

        let dataBody = {
          namespace,
          serial,
          type: internal ? 'internal' : 'external',
          serviceId,
          qualityLevel: dataObject?.qualityLevel,
          retry: 1,
        };
        createStream(dataBody);
      }
    },
    [
      cancelRetry,
      createStream,
      dispatch,
      internal,
      markSettle,
      namespace,
      serial,
      serviceId,
    ],
  );

  const restartQualityCallBack = useCallback(
    (dataObject) => {
      beeXLogger.debug('RESTART QUALITY CALLBACK:', dataObject);
      requestIdRef.current = null;
      cancelRetry();
      markSettle();

      if (serial) {
        const newZoomState = zoomState?.dataZoomStates?.find(
          (item) => item.zoomState === dataObject?.qualityLevel,
        );

        if (newZoomState) {
          beeXLogger.debug('Updating zoomStatePlayer to:', newZoomState);
          setZoomStatePlayer((prev) => ({
            ...prev,
            ...newZoomState,
          }));
        }

        if (streaming) {
          const { streamId, serial } = streaming;

          if (streamId) {
            dispatch(getEndStreamReturn(streamId));
          } else {
            dispatch(getEndStreamUtraFastReturn(serial));
          }
        }

        let dataBody = {
          namespace,
          serial,
          type: internal ? 'internal' : 'external',
          serviceId,
          qualityLevel: dataObject?.qualityLevel,
          retry: 0,
        };

        beeXLogger.debug(
          'Creating stream with qualityLevel:',
          dataObject?.qualityLevel,
        );
        createStream(dataBody);
      }
    },
    [
      cancelRetry,
      createStream,
      dispatch,
      internal,
      markSettle,
      namespace,
      serial,
      serviceId,
      streaming,
      zoomState,
    ],
  );

  useEffect(() => {
    if (streaming?.zoomState && zoomState?.dataZoomStates) {
      const confirmedQuality = zoomState.dataZoomStates.find(
        (item) => item.zoomState === streaming.zoomState,
      );
      if (confirmedQuality?.zoomState !== zoomStatePlayer?.zoomState) {
        setZoomStatePlayer({
          ...zoomState,
          ...confirmedQuality,
        });
      }
    }
  }, [streaming?.zoomState, zoomState, zoomStatePlayer]);

  // Watch Stream
  useEffect(() => {
    if (streaming && zoomState?.zoomState && streaming.started) {
      setLoading(false);
      let dataBody = {
        streamId: streaming.streamId,
        zoomState: zoomStatePlayer?.zoomState ?? ZOOM_STATE.FOUR,
        namespace,
      };
      let dataObj = {
        appServiceType: SERVICE.ZOOM_STATE_STREAM,
        requestId: new Date().getTime(),
        body: JSON.stringify(dataBody),
      };
      dispatch(socketEmitEvent(dataObj));
    }
  }, [streaming, namespace, zoomState, zoomStatePlayer, dispatch]);

  // Stop stream on exit - clean up component
  useEffect(() => {
    isMountedRef.current = true;

    return () => {
      isMountedRef.current = false;
      requestIdRef.current = null;
      requestStreamPlayed.current = {};

      cancelRetry();

      if (adapterRef.current) {
        adapterRef.current.destroy();
        adapterRef.current = null;
      }

      const streamInfo = streamRef.current;

      if (
        streamInfo &&
        streamInfo.started &&
        streamInfo.status &&
        streamInfo.status.length > 0
      ) {
        const { streamId } = streamInfo;

        dispatch(
          socketEmitEvent({
            appServiceType: SERVICE.STOP_STREAM,
            requestId: Date.now(),
            body: JSON.stringify({
              streamId,
              namespace,
            }),
          }),
        );

        if (streamId) {
          dispatch(getEndStreamReturn(streamId));
        } else {
          dispatch(getEndStreamUtraFastReturn(serial));
        }
      }

      dispatch(removeStream(serial));

      streamRef.current = null;
    };
  }, [dispatch, serial, namespace, cancelRetry]);

  useEffect(() => {
    if (onlineRestartTimeout.current) {
      clearTimeout(onlineRestartTimeout.current);
    }

    const onOnline = () => {
      console.log('On online');

      if (onlineRestartTimeout.current) {
        clearTimeout(onlineRestartTimeout.current);
      }

      cancelRetry();
      markSettle();

      setOutput(null);

      if (streamRef.current) {
        const { streamId } = streamRef.current;

        if (streamId) {
          dispatch(getEndStreamReturn(streamId));
        } else {
          dispatch(getEndStreamUtraFastReturn(serial));
        }
      }

      onlineRestartTimeout.current = setTimeout(() => {
        beeXLogger.log('SOCKET RECONNECTED, RECREATE STREAM', camera?.name);
        let dataBody = {
          namespace,
          serial,
          type: internal ? 'internal' : 'external',
          serviceId,
          retry: 0,
        };
        createStream(dataBody);
      }, 1500);
    };

    window.addEventListener('online', onOnline);

    return () => {
      window.removeEventListener('online', onOnline);
    };
  }, [
    createStream,
    namespace,
    serial,
    internal,
    serviceId,
    cancelRetry,
    markSettle,
    dispatch,
  ]);

  const onRotateCamera = useCallback(
    (navigator) => {
      if (streaming?.serial) {
        let dataBody = {
          navigator,
          namespace,
          serial: streaming?.serial,
        };
        let dataObj = {
          appServiceType: SERVICE.ROTATE_VIEW_CAMERA,
          requestId: new Date().getTime(),
          body: JSON.stringify(dataBody),
        };
        return dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, namespace, streaming],
  );
  const onZoomCamera = useCallback(
    (zoom) => {
      if (streaming?.serial) {
        let dataBody = {
          zoom,
          namespace,
          serial: streaming?.serial,
        };
        let dataObj = {
          appServiceType: SERVICE.ZOOM_VIEW_CAMERA,
          requestId: new Date().getTime(),
          body: JSON.stringify(dataBody),
        };
        return dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, namespace, streaming],
  );

  const [camPlaying, setCamPlaying] = useState(false);

  const onError = useCallback(
    (error, value) => {
      console.log('onError - ERROR', error, value);

      if (typeof value === 'object' && !value.fatal) {
        hlsFatal.current = false;
        return;
      }

      hlsFatal.current = true;
      let message =
        error || error?.message || value?.message || 'Failed to load stream';
      console.log('🚀 ~ ViewStreamComponent ~ error?.type:', error?.type);

      let errorStep = 3;
      if (value?.type === 'networkError' && streamConnectStep === 2) {
        message = 'Stream not found';
        errorStep = 2;
      }

      setCamPlaying(false);
      setStreamConnectError(message);
      setStreamConnectErrorStep(errorStep);
      if (errorStep === 2) {
        setStreamConnectFailedAtStep2();
      } else {
        setStreamConnectFailedAtStep3();
      }
    },
    [
      setStreamConnectFailedAtStep2,
      setStreamConnectFailedAtStep3,
      streamConnectStep,
    ],
  );

  useEffect(() => {
    if (camPlaying) {
      setStreamConnectSuccess();
      resetStreamConnectStatus();
    }
  }, [camPlaying, resetStreamConnectStatus, setStreamConnectSuccess]);
  const handleOnPlay = useCallback(() => {
    setCamPlaying(true);
    hasStreamOutputRef.current = true;
    setStreamConnectSuccess();
    resetStreamConnectStatus();
  }, [resetStreamConnectStatus, setStreamConnectSuccess]);

  return (
    <div className="flex flex-col h-full">
      <div
        className={`view-stream-component w-full 
      ${
        pageSize === 4
          ? 'is2Mode'
          : pageSize === 6
            ? 'isFocusMode'
            : pageSize === 9
              ? 'is3Mode'
              : pageSize === 16
                ? 'is4Mode'
                : pageSize === 25
                  ? 'is5Mode'
                  : pageSize === 36
                    ? 'is6Mode'
                    : ''
      }
      `}
      >
        {state === 1 || isConnected ? (
          !camPlaying && (
            <div className="icon-live-stream">
              <img
                width={iconSize ? iconSize : 26}
                height={iconSize ? iconSize : 26}
                className="icon"
                alt="live-stream-icon"
                src={LiveIconOn}
              />
            </div>
          )
        ) : (
          <>
            {/* <div className="name-camera">{name}</div> */}
            <div className="icon-live-stream">
              <img
                width={iconSize ? iconSize : 26}
                height={iconSize ? iconSize : 26}
                className="icon"
                alt="live-stream-icon"
                src={OffStream}
              />
            </div>
          </>
        )}
        {!camPlaying && (
          <div className="icon-type-stream">
            <img
              width={iconSize ? iconSize : 26}
              height={iconSize ? iconSize : 26}
              className="icon"
              alt="live-stream-icon"
              src={typeCamera === 'onvif' ? IconCameraOnvif : IconCameraRtsp}
            />
          </div>
        )}
        {!camPlaying && (
          <Tooltip
            placement="left"
            mouseEnterDelay={0.5}
            title={
              <>
                <Row>
                  <Col span={24}>
                    <Row
                      style={{
                        borderBottom: '1px solid var(--color-auto-stroke)',
                        paddingBottom: '10px',
                      }}
                    >
                      <Col
                        span={18}
                        style={{
                          fontWeight: 'bold',
                          fontSize: '13px',
                          color: 'var(--color-auto-text)',
                        }}
                      >
                        {listDeviceContact?.name || ''}
                      </Col>
                      <Col span={6}>
                        <StateTag state={listDeviceContact?.state} />
                      </Col>
                    </Row>
                  </Col>
                  {/* <Col span={24}>
                    <img
                      className="info-icon-stream"
                      alt="live-stream-icon"
                      src={Info1}
                    />
                    <span style={{ color: '#028fd5' }}>Camera: {listDeviceContact?.name || ''}</span>
                  </Col> */}
                  {listDeviceContact?.note && (
                    <Col
                      span={24}
                      style={{
                        color: 'var(--color-auto-text)',
                        marginTop: '10px',
                        fontSize: '13px',
                      }}
                    >
                      <img
                        className="info-icon-stream"
                        alt="live-stream-icon"
                        style={{ marginTop: '-2px' }}
                        src={Info3}
                      />
                      {listDeviceContact?.note || ''}
                    </Col>
                  )}
                  {state === 0 && (
                    <Col span={24}>
                      <Row>
                        {listDeviceContact?.errorTime && (
                          <Col
                            span={24}
                            style={{
                              color: 'var(--color-auto-text)',
                              marginTop: '5px',
                              fontSize: '13px',
                            }}
                          >
                            <img
                              className="info-icon-stream"
                              alt="live-stream-icon"
                              style={{ marginTop: '-2px' }}
                              src={Info11}
                            />
                            {t('Time')}:{' '}
                            <span style={{ color: 'rgb(245, 47, 57)' }}>
                              {listDeviceContact?.errorTime || ''}
                            </span>
                          </Col>
                        )}
                        {listDeviceContact?.errorMessage && (
                          <Col
                            span={24}
                            style={{
                              color: 'var(--color-auto-text)',
                              marginTop: '5px',
                              fontSize: '13px',
                            }}
                          >
                            <img
                              className="info-icon-stream"
                              alt="live-stream-icon"
                              style={{ marginTop: '-2px' }}
                              src={Info12}
                            />
                            {t('Reason')}:{' '}
                            <span style={{ color: 'rgb(245, 47, 57)' }}>
                              {listDeviceContact?.errorMessage || ''}
                            </span>
                          </Col>
                        )}
                      </Row>
                    </Col>
                  )}
                  <Col
                    span={24}
                    style={{ marginTop: '10px', fontSize: '13px' }}
                  >
                    <img
                      className="info-icon-stream"
                      alt="live-stream-icon"
                      style={{ marginTop: '-2px' }}
                      src={Info5}
                    />
                    <span style={{ color: '#028fd5' }}>
                      {t('PERSON IN CHARGE')}
                    </span>
                  </Col>
                  {listDeviceContact?.assigners?.length > 0 &&
                    listDeviceContact.assigners.map((item, index) => (
                      <Col span={24} key={index}>
                        <Row>
                          {item.fullName && (
                            <Col
                              span={24}
                              style={{
                                color: 'var(--color-auto-text)',
                                marginTop: '5px',
                                fontSize: '13px',
                              }}
                            >
                              <img
                                className="info-icon-stream"
                                alt="live-stream-icon"
                                style={{ marginTop: '-2px' }}
                                src={Info6}
                              />
                              {t('Họ tên')}: {item.fullName || ''}
                            </Col>
                          )}
                          {item.phoneNumber && (
                            <Col
                              span={24}
                              style={{
                                color: 'var(--color-auto-text)',
                                marginTop: '5px',
                                fontSize: '13px',
                              }}
                            >
                              <img
                                className="info-icon-stream"
                                alt="live-stream-icon"
                                style={{ marginTop: '-2px' }}
                                src={Info7}
                              />
                              {t('Phone number')}:{' '}
                              <span
                                style={{
                                  color: '#028fd5',
                                  textDecoration: 'underline',
                                  cursor: 'pointer',
                                }}
                                onClick={() => {
                                  dispatch(
                                    changeDialPadData({
                                      show: true,
                                      phone: item.phoneNumber,
                                    }),
                                  );
                                }}
                              >
                                {item.phoneNumber || ''}
                              </span>
                            </Col>
                          )}
                        </Row>
                      </Col>
                    ))}
                </Row>
              </>
            }
          >
            <div
              className="icon-info-stream"
              onMouseOver={() => onChangeHover()}
            >
              <img
                width={iconSize ? iconSize : 26}
                height={iconSize ? iconSize : 26}
                className="icon"
                alt="live-stream-icon"
                src={Info}
              />
            </div>
          </Tooltip>
        )}
        {state === 0 &&
          !isConnected &&
          permission &&
          permission.split('_') &&
          permission.split('_').find((item) => item === 'live') && (
            <>
              <div
                onClick={() =>
                  !isLoadReload && isAllowStreaming !== 0 && handleTryLoad()
                }
                className="preload-spinner reconnect"
              >
                <ReloadOutlined
                  className={isAllowStreaming === 0 ? 'no-active' : ''}
                  style={{ fontSize: 48 }}
                  spin={isLoadReload}
                />
              </div>
              {isAllowStreaming === 0 && (
                <div className="text-no-active">
                  <Tag color="#f50">{t('Not active')}</Tag>
                </div>
              )}
            </>
          )}
        {onPlay ? (
          <PlayerComponent
            name={name}
            onvif={
              typeCamera === 'onvif' || brand?.includes(CAMERA_BRAND.ONVIF_PTZ)
            }
            onRotate={onRotateCamera}
            onZoom={onZoomCamera}
            resolution={resolution}
            zoomStateProps={zoomStateDefault ?? zoomState}
            isFullscreenProps={isFullscreen}
            restartCallBack={restartCallBack}
            restartLoadingCallBack={restartLoadingCallBack}
            fullScreenCallBack={(isFull) => setIsFullscreen(isFull)}
            status={streaming && streaming.status}
            type="streaming"
            loading={loading}
            sourceObject={sourceObject}
            poster={
              thumbnail && thumbnail.match(/http/g) ? thumbnail : Thumbnail
            }
            setOnPlay={setOnPlay}
            serial={serial}
            checkTransferZoomState={checkTransferZoomState}
            zoomStatePlayer={zoomStatePlayer}
            setZoomStatePlayer={setZoomStatePlayer}
            restartQualityCallBack={restartQualityCallBack}
            // isHlsStreaming={!!streaming?.hlsPort && !forceAudio}
            isHlsStreaming={isHlsStreaming}
            // isHlsStreaming={false}
            allScreen={allScreen}
            protocol={streaming?.protocol}
            setRefVideo={(r) => (videoRef.current = r)}
            onPlay={handleOnPlay}
            onError={onError}
            selectedMode={getMode(adapterRef.current)}
            streamData={streaming}
            streamMonitorId={streaming && streaming?.streamMonitorId}
            namespace={namespace}
            brand={brand}
            cameraSource={cameraSource}
            variantPage={variantPage}
            allowAudio={allowAudio}
            streamConnectStep={streamConnectStep}
            setStreamConnectStep={setStreamConnectStep}
            streamConnectStepStates={streamConnectStepStates}
            streamConnectError={streamConnectError}
            streamConnectErrorStep={streamConnectErrorStep}
            streamConnectIsSuccess={camPlaying}
            onFullscreenChange={onFullscreenChange}
            serviceId={serviceId}
          />
        ) : (
          <div
            className="video-wrapper thumbnail"
            style={{
              paddingBottom: allScreen
                ? '56.25%'
                : `${calcPercentForVideo(
                    windowHeight - 108,
                    windowWidth - 324,
                  )}%`,
            }}
          >
            {state === 1 &&
              permission &&
              permission.split('_') &&
              permission.split('_').find((item) => item === 'live') && (
                <>
                  <img
                    alt="play-icon"
                    onClick={() => {
                      if (isAllowStreaming !== 0) {
                        setOnPlay(true);
                      }
                    }}
                    src={isAllowStreaming === 0 ? PlayIconNoActive : PlayIcon}
                  />
                  {isAllowStreaming === 0 && (
                    <div className="text-no-active">
                      <Tag color="#f50">{t('Not active')}</Tag>
                    </div>
                  )}
                </>
              )}
            <video
              poster={
                thumbnail && thumbnail.match(/http/g) ? thumbnail : Thumbnail
              }
              style={{ objectFit: 'cover' }}
            />
            {/* <img src={thumbnail} alt=''
              style={{
                width: '100%',
                height: 'auto',
                maxHeight: '100%',
                objectFit: 'cover',
                zIndex: -1,
              }} /> */}
          </div>
        )}
      </div>
      {showSetting && (
        <div className="flex justify-between items-center z-50">
          {showBottomName && (
            <Tooltip title={name}>
              <div className="font-semibold mt-1 pl-1 truncate">{name}</div>
            </Tooltip>
          )}
          <SettingIcon
            className="cursor-pointer"
            width={18}
            height={18}
            style={{
              color: cameraToSetting?.serial === serial ? '#028fd5' : '#a4a7ae',
            }}
            onClick={() => dispatch(setCameraToSetting(camera))}
          />
        </div>
      )}
    </div>
  );
};

export default ViewStreamComponent;
