import React, { useMemo } from 'react';
import moment from 'moment';
import { Progress, Spin, Tooltip } from 'antd';
import { LoadingOutlined, DownloadOutlined } from '@ant-design/icons';
import { ReactComponent as RemoveIcon } from '@/assets/icons/remove-icon.svg';
import Downloader from '../../downloader';
import { EnumPlaybackType } from '../../Settings';
import { convertByteToMB, genDownloadKeyLocal, timeToSeconds } from './utils';
import { computeQueryTime } from '../../utils';
import { beeXLogger } from '@/helpers/logger';
import { deleteTempDownloadPlaybackOnCloud } from '@/hooks/socket/playback';
import { openMessage } from '@/redux/actions';
import { NOTIFIES } from '@/constants/system.keys';

export const useDownloadPlayback = ({
  playbackType,
  compressedProgress,
  deletedList,
  downloadRanges,
  namespace,
  serial,
  initialSelectedDate,
  downloaderInstance,
  blobUrlCacheRef,
  cachingDownloadedRef,
  setDeletedList,
  setDownloadRanges,
  handleRemoveDownload,
  t
}) => {
  return useMemo(() => {
    if (playbackType === EnumPlaybackType.CLOUD) {
      return [
        {
          title: 'Camera name',
          align: 'center',
          dataIndex: 'name',
          render: (text) => text,
        },
        {
          title: 'From',
          align: 'center',
          dataIndex: 'fromTime',
          render: (text) => moment(text).format('HH:mm:ss DD-MM-YYYY'),
        },
        {
          title: 'To',
          align: 'center',
          dataIndex: 'toTime',
          render: (text) => moment(text).format('HH:mm:ss DD-MM-YYYY'),
        },
        {
          title: 'Compress status',
          align: 'center',
          dataIndex: 'key',
          render: (_, row) => {
            const status = row?.compressStatus;

            if (!status) {
              return '';
            }

            if (status === 'processing' && (compressedProgress <= 0)) {
              return (
                <Tooltip title="Preparing file, may take a while">
                  <div>
                    <Spin
                      spinning
                      indicator={<LoadingOutlined />}
                      className="mr-1"
                      size="small"
                    />
                    Compressing...
                  </div>
                </Tooltip>
              );
            }

            if (status === 'completed') {
              return (
                <div className="flex items-center justify-center gap-2">
                  <Progress
                    percent={row?.compressProgress || 0}
                    showInfo={false}
                    style={{ width: 120 }}
                  />
                </div>
              );
            }
            if (status === 'error') {
              return <span className='text-red-500'>Failed</span>;
            }

            return (
              <Progress
                percent={compressedProgress || row?.compressProgress || 0}
                showInfo={false}
                style={{ width: 120 }}
              />
            );
          },
        },
        {
          title: 'Download status',
          dataIndex: 'key',
          align: 'center',
          width: 300,
          render: (_, row) => {
            const downloadBlob = downloaderInstance.getBlob(row?.downloadKey);
            const downloadState = downloaderInstance.getState(row?.downloadKey);
            const status = downloadState?.status;

            if ((!status && row?.progress === 100 && row?.status !== 'completed') ||
              (status === 'waiting' && (downloadState?.progress <= 0 || !downloadState?.progress))) {
              return (
                <Tooltip title="Preparing file, may take a while">
                  <div>
                    <Spin
                      spinning
                      indicator={<LoadingOutlined />}
                      className="mr-1"
                      size="small"
                    />
                    Preparing file
                  </div>
                </Tooltip>
              );
            }

            if (!status) {
              return '';
            }

            if (status === 'completed') {
              if (!deletedList.includes(row?.uuid)) {
                setTimeout(() => {
                  setDeletedList(prev => [...prev, row?.uuid]);
                  deleteTempDownloadPlaybackOnCloud({
                    uuid: row?.uuid,
                    resourceCloudId: row?.resourceCloudId,
                    serial,
                    namespace
                  });
                }, 500);
              }

              let blobUrl = '';
              if (downloadBlob && row?.uuid) {
                if (!blobUrlCacheRef.current[row.uuid]) {
                  blobUrlCacheRef.current[row.uuid] = URL.createObjectURL(downloadBlob);
                }
                blobUrl = blobUrlCacheRef.current[row.uuid];
              }

              return (
                <div className="flex items-center justify-center gap-2 relative">
                  {blobUrl && (
                    <>
                      <video
                        key={row.uuid}
                        className='w-full h-auto object-contain allow-control'
                        src={blobUrl}
                        controls
                        preload="auto"
                        style={{ display: 'block' }}
                      />
                      <button
                        onClick={() => {
                          if (downloadBlob) {
                            Downloader.downloadBlob(
                              downloadBlob,
                              row?.pathFile || row?.uuid + '.mp4'
                            );
                          }
                        }}
                        className='absolute top-2 right-2 ml-auto flex h-8 w-8 cursor-pointer items-center justify-center rounded-full border-none bg-gray-100'
                      >
                        <DownloadOutlined style={{ color: '#000' }} width={14} height={14} />
                      </button>
                    </>
                  )}
                </div>
              );
            }

            if (status === 'error') {
              if (downloadRanges?.some(range => range?.fromTime === row?.fromTime && range?.toTime === row?.toTime)) {
                openMessage(NOTIFIES.ERROR, t('Download failure'));
              }
              return <span className='text-red-500'>Failed</span>;
            }

            return (
              <div className='flex items-center gap-2'>
                <Progress
                  percent={downloadState?.progress || 0}
                  showInfo={false}
                  style={{ width: 120 }}
                />
                {downloadState?.downloadSize > 0 && downloadState?.totalSize > 0 && (
                  <span className='nowrap'>
                    {convertByteToMB(downloadState?.downloadSize)} / {convertByteToMB(downloadState?.totalSize)} MB
                  </span>
                )}
              </div>
            );
          },
        },
        {
          title: 'Actions',
          align: 'center',
          render: (_, row) => (
            <div className='w-full h-full flex items-center justify-center'>
              <div className='p-1 hover:bg-gray-50 rounded-full w-8 h-8 flex justify-center items-center cursor-pointer'>
                <RemoveIcon
                  className='cursor-pointer'
                  onClick={() => {
                    handleRemoveDownload(row?.downloadKey, row.uuid, row?.resourceCloudId);
                    setDownloadRanges(prev => prev?.filter(item =>
                      row?.fromTime !== item?.fromTime && row?.toTime !== item?.toTime && row?.serial !== item?.serial
                    ));
                  }}
                />
              </div>
            </div>
          ),
        }
      ];
    } else {
      return [
        {
          title: 'Camera name',
          align: 'center',
          dataIndex: 'name',
          render: (text) => text,
        },
        {
          title: 'From',
          align: 'center',
          dataIndex: 'fromTime',
          render: (text) => moment(text + ' ' + initialSelectedDate).format('HH:mm:ss DD-MM-YYYY'),
        },
        {
          title: 'To',
          align: 'center',
          dataIndex: 'toTime',
          render: (text) => moment(text + ' ' + initialSelectedDate).format('HH:mm:ss DD-MM-YYYY'),
        },
        {
          title: 'Download status',
          dataIndex: 'key',
          align: 'center',
          width: 300,
          render: (_, row) => {
            const downloadKey = genDownloadKeyLocal(
              serial,
              computeQueryTime(initialSelectedDate, timeToSeconds(row?.fromTime)),
              computeQueryTime(initialSelectedDate, timeToSeconds(row?.toTime)),
            );
            const downloadBlob = downloaderInstance.getBlob(downloadKey);
            const downloadState = downloaderInstance.getState(downloadKey);
            const status = downloadState?.status;

            if ((!status && row?.progress === 100 && row?.status !== 'completed') ||
              (status === 'waiting' && (downloadState?.progress <= 0 || !downloadState?.progress))) {
              return (
                <Tooltip title="Preparing file, may take a while">
                  <div>
                    <Spin
                      spinning
                      indicator={<LoadingOutlined />}
                      className="mr-1"
                      size="small"
                    />
                    Preparing file
                  </div>
                </Tooltip>
              );
            }

            if (!status) {
              return '';
            }

            if (status === 'completed') {
              let blobUrl = '';
              if (downloadBlob && downloadKey) {
                if (!blobUrlCacheRef.current[downloadKey]) {
                  blobUrlCacheRef.current[downloadKey] = URL.createObjectURL(downloadBlob);
                }
                blobUrl = blobUrlCacheRef.current[downloadKey];
                cachingDownloadedRef.current.set(downloadKey, {
                  downloadKey,
                  playbackType,
                  serial
                });
              }
              return (
                <div className="flex items-center justify-center gap-2 relative">
                  {blobUrl && (
                    <>
                      <video
                        key={downloadKey}
                        className='w-full h-auto object-contain allow-control'
                        src={blobUrl}
                        controls
                        preload="auto"
                        style={{ display: 'block' }}
                      />
                      <button
                        onClick={() => {
                          if (downloadBlob) {
                            Downloader.downloadBlob(
                              downloadBlob,
                              `playback-${row?.serial}-${row?.fromTime}-${row?.toTime}.mp4`
                            );
                          }
                        }}
                        className='absolute top-2 right-2 ml-auto flex h-8 w-8 cursor-pointer items-center justify-center rounded-full border-none bg-gray-100'
                      >
                        <DownloadOutlined style={{ color: '#000' }} width={14} height={14} />
                      </button>
                    </>
                  )}
                </div>
              );
            }

            if (status === 'error') {
              if (downloadRanges?.some(range => range?.fromTime === row?.fromTime && range?.toTime === row?.toTime)) {
                openMessage(NOTIFIES.ERROR, t('Download failure'));
              }
              return <span className='text-red-500'>Failed</span>;
            }

            return (
              <div className='flex items-center justify-center gap-2'>
                <Progress
                  percent={downloadState?.progress || 0}
                  showInfo={false}
                  style={{ width: 120 }}
                />
                {downloadState?.downloadSize > 0 && (
                  <span className='nowrap'>
                    {convertByteToMB(downloadState?.downloadSize)} / {convertByteToMB(downloadState?.totalSize)} MB
                  </span>
                )}
              </div>
            );
          },
        },
        {
          title: 'Actions',
          align: 'center',
          render: (_, row) => (
            <div className='w-full h-full flex items-center justify-center'>
              <div className='p-1 hover:bg-gray-50 rounded-full w-8 h-8 flex justify-center items-center cursor-pointer'>
                <RemoveIcon
                  className='cursor-pointer'
                  onClick={() => handleRemoveDownload(
                    genDownloadKeyLocal(
                      serial,
                      computeQueryTime(initialSelectedDate, timeToSeconds(row?.fromTime)),
                      computeQueryTime(initialSelectedDate, timeToSeconds(row?.toTime)),
                    ),
                    row
                  )}
                />
              </div>
            </div>
          ),
        }
      ];
    }
  }, [
    playbackType,
    compressedProgress,
    deletedList,
    downloadRanges,
    namespace,
    serial,
    initialSelectedDate,
    downloaderInstance,
    blobUrlCacheRef,
    cachingDownloadedRef,
    setDeletedList,
    setDownloadRanges,
    handleRemoveDownload,
    t
  ]);
};
