import React, { useCallback, useEffect, useMemo, useState } from "react";

import './index.scss'
import { Input, Pagination, Select } from "antd";
import { useSelector } from "react-redux";
import { useTranslation } from "react-i18next";

const { Option } = Select
const { Search } = Input;


export const Filter = ({ onFilter }) => {
  const [provinces, setProvinces] = useState([])
  const { namespace, listPlaceByPage } = useSelector(state => state)
  const { t } = useTranslation()
  const [searchType, setSearchType] = useState('name')
  const [pagination, setPagination] = useState({
    pageSize: 8,
    currentPage: 1,
  })

  const fetchProvinces = useCallback(() => {
    fetch('https://provinces.open-api.vn/api/v2/?depth=2')
      .then(res => res.json())
      .then(data => {
        setProvinces(data)
      }).catch(err => {
        console.log('err: ', err);
      })
  }, [])

  useEffect(() => {
    fetchProvinces()
  }, [fetchProvinces]);

  const options = useMemo(() => provinces.map(p => ({
    ...p,
    label: p?.name,
    value: p?.code
  }) || []), [provinces])

  const onSearch = useCallback((value) => {
    if (searchType === 'name') {
      onFilter(0, 8, value?.trim())
    } else {
      onFilter(0, 8, null, value?.trim())
    }
  }, [searchType, onFilter])

  const onSelectProvince = (value) => {
    console.log('onSelectProvince: ', value);
  }

  const onPageChange = (value) => {
    onFilter(value - 1, 8);
    setPagination(prev => ({
      ...prev,
      currentPage: value
    }))
    console.log('value: ', value);
  }

  useEffect(() => {
    if (listPlaceByPage) {
      setPagination(prev => ({
        ...prev,
        total: listPlaceByPage?.total
      }))
    }
  }, [listPlaceByPage]);

  return (
    <div className="sites-filter-component w-full flex items-center justify-between">
      <div className="w-1/2 flex gap-2 items-center justify-start">
        {/* <Select
          className="province-select w-1/2"
          placeholder={'Provinces'}
          onChange={(value) => onSelectProvince(value)}
        >
          {
            options && options?.map(opt => (
              <Option value={opt?.value}>{opt?.name}</Option>
            ))
          }
        </Select> */}
        <div className="w-1/2 flex gap-2">
          <Search
            className="flex-1"
            placeholder={t(`Search by ${searchType}`)}
            onSearch={onSearch}
            allowClear
          />
          <Select value={searchType} onChange={(value) => setSearchType(value)}>
            <Option value='name'>{t('Name')}</Option>
            <Option value='tag'>{t('Tag')}</Option>
          </Select>
        </div>
      </div>
      {
        pagination?.total > 0 && (
          <Pagination
            size="small"
            showLessItems
            showSizeChanger={false}
            total={pagination?.total || 0}
            current={pagination?.currentPage || 1}
            pageSize={8}
            onChange={onPageChange}
          />
        )
      }
    </div>
  )
}
