import axios from 'axios';

export const GET_API = async (url, token, dataHeader = {}, dataQuery = {}) => {
  const res = await axios.get(url, {
    headers: {
      Authorization: `${token}`,
      'Content-Type': 'application/json',
      ...dataHeader,
    },
    params: dataQuery,
  });
  const { data, status } = res;
  return { status, data };
};

export const POST_API = async (
  url,
  token,
  dataHeader = {},
  dataBody = {},
  dataQuery = {},
) => {
  const res = await axios.post(
    url,
    {
      ...dataBody,
    },
    {
      headers: {
        Authorization: `${token}`,
        'Content-Type': 'application/json',
        ...dataHeader,
      },
      params: dataQuery,
    },
  );
  const { data, status } = res;
  return { status, data };
};

