import React from "react";
import './index.scss'

export const CameraStrengthComponent = ({ strength = 0 }) => {

  const safeStrength = Math.max(0, Math.min(100, strength));

  const bars = [
    safeStrength >= 25,
    safeStrength >= 50,
    safeStrength >= 75,
    safeStrength >= 100,
  ];

  return (
    <span className="camera-strength-component">
      {bars.map((active, i) => (
        <span
          key={i}
          className={`camera-strength-bar ${active ? 'active' : ''}`}
        />
      ))}
    </span>
  );
};
