import React, { useEffect, useState } from 'react';
import { PlaybackMainFocusLayout } from './FocusLayout';
import { useFetchTimes } from '@/redux/playback/use-fetch-times';
import { PlaybackMainFocusLayoutProgressBarContainer } from '../ProgressBar/container';
import { displayModeItems } from '@/components/CommonGrid/shared';
import { PlaybackGridLayout } from './GridLayout';
import { Button, Modal, Pagination, Switch, Tooltip } from 'antd';
import clsx from 'clsx';

import './styles.scss';
import { useSelector } from 'react-redux';
import { getPlaybackMode, getSelectedDate } from '@/redux/playback/reducer';
import { EnumPlaybackType } from '../Settings';
import Spinner from '@/components/Spinner';
import { usePlaybackContext } from '../context';
import { useTranslation } from 'react-i18next';
import { ReactComponent as BackUpDataIcon } from '@/assets/icons/backup-data-icon.svg';
import { BackupStorage } from '@/pages/Service/BackupStorage';

export const PlaybackMainSectionMode = {
  FOCUS: 'focus',
  GRID: 'grid',
};

export const PlaybackMainSection = ({
  cameraSelections,
  gridMode,
  pageSize,
  setDisplayMode,
  setGridMode,
  selectedCamera,
  isLoading,
  setDisplayCameras,
}) => {
  const isLocal = useSelector(getPlaybackMode) === EnumPlaybackType.LOCAL;
  const { displayMode } = usePlaybackContext();
  const [showInfo, setShowInfo] = useState(false);
  const { devicesActiveOfServices } = useSelector((state) => state);
  const [allowBackup, setAllowBackup] = useState(false);
  const { t } = useTranslation();
  const [visibleBackupStorage, setVisibleBackupStorage] = useState(false);
  const selectedDate = useSelector(getSelectedDate);

  useEffect(() => {
    if (devicesActiveOfServices) {
      if (devicesActiveOfServices?.devices?.length > 0) {
        setAllowBackup(
          devicesActiveOfServices?.devices?.some((item) => {
            return item?.serial === selectedCamera?.serial;
          }),
        );
      }
    }
  }, [devicesActiveOfServices, selectedCamera]);

  return (
    <div className="playback-player-section">
      <div className="playback-player-section-header mb-1 flex items-center justify-between gap-2">
        <div className="flex-1 flex justify-start items-center gap-2">
          <ModeSelector mode={displayMode} onChange={setDisplayMode} />
          <GridModeSelector
            visible={displayMode === PlaybackMainSectionMode.GRID}
            mode={gridMode}
            onChange={(mode) => {
              if (mode === gridMode) return;
              setGridMode(mode);
              setDisplayCameras([]);
            }}
          />
        </div>
        {allowBackup && (
          <Button
            className="btn-backup-data"
            type="primary"
            icon={<BackUpDataIcon />}
            onClick={() => setVisibleBackupStorage(true)}
          >
            {t('Your storage')}
          </Button>
        )}
      </div>
      {isLoading ? (
        <Spinner />
      ) : (
        <>
          {displayMode === PlaybackMainSectionMode.FOCUS && (
            <PlaybackMainFocusLayout
              isLocal={isLocal}
              cameras={cameraSelections}
              selectedCamera={selectedCamera}
              showInfo={showInfo}
              setShowInfo={setShowInfo}
            />
          )}
          {displayMode === PlaybackMainSectionMode.GRID && (
            <PlaybackGridLayout
              isLocal={isLocal}
              cameras={cameraSelections}
              mode={gridMode}
              displayMode={PlaybackMainSectionMode.GRID}
              selectedCamera={selectedCamera}
              showInfo={showInfo}
              setShowInfo={setShowInfo}
            />
          )}
          <div className="mt-2">
            <PlaybackMainFocusLayoutProgressBarContainer
              displayCameras={cameraSelections}
              displayMode={displayMode}
              pageSize={pageSize}
              showInfo={showInfo}
              setShowInfo={setShowInfo}
            />
          </div>
        </>
      )}
      <Modal
        visible={visibleBackupStorage}
        onCancel={() => setVisibleBackupStorage(false)}
        footer={null}
        title={t(`Your storage - ${selectedCamera?.name || ''}`)}
        className="backup-storage-modal"
      >
        <BackupStorage
          variantPage="playback"
          customSelectedCamera={selectedCamera}
          selectedDate={selectedDate}
        />
      </Modal>
    </div>
  );
};

const ModeSelector = ({ mode, onChange }) => {
  return (
    <div className="playback-main-section-mode-selector flex items-center gap-1">
      <span>Grid mode</span>
      <Tooltip
        title={
          mode === PlaybackMainSectionMode.GRID
            ? 'Enable focus view'
            : 'Enable grid view'
        }
      >
        <Switch
          checked={mode === PlaybackMainSectionMode.GRID}
          size="small"
          onChange={(checked) =>
            onChange(
              checked
                ? PlaybackMainSectionMode.GRID
                : PlaybackMainSectionMode.FOCUS,
            )
          }
        />
      </Tooltip>
    </div>
  );
};

const GridModeSelector = ({ mode, onChange, visible }) => {
  return (
    <div
      className="playback-grid-mode-selector flex items-center gap-1"
      style={{
        opacity: visible ? 1 : 0,
        visibility: visible ? 'visible' : 'hidden',
      }}
    >
      {displayModeItems.map((item) => (
        <Tooltip key={item.mode} title={item.tooltip}>
          <div
            className={clsx(
              'playback-grid-layout-item',
              mode === item.mode && 'is-active',
            )}
            onClick={() => onChange(item.mode)}
          >
            {item.icon}
          </div>
        </Tooltip>
      ))}
    </div>
  );
};
