import React, { useEffect, useState } from 'react';
import { FunctionSelected, FunctionGroup } from './FunctionGroup';
import './index.scss';
import { CreateRoleForm } from './CreateRoleForm';
import { useSelector } from 'react-redux';
import { addCustomerRole, addRoleFunction } from '@/hooks/socket/role';
import { beeXLogger } from '@/helpers/logger';
import { openMessage } from '@/redux/actions';
import { NOTIFIES } from '@/constants/system.keys';
import { useTranslation } from 'react-i18next';
import { Card, Form, Input, Button } from 'antd';
import { EditOutlined } from '@ant-design/icons';

const CreateRoleComponent = ({ onDone = () => { }, visibleAddRole = false }) => {
  const [selectedGroup, setSelectedGroup] = useState(null);
  const [selectedFunctions, setSelectedFunctions] = useState([]);
  const { listFunctions, namespace } = useSelector(state => state);
  const [functionGroups, setFunctionGroups] = useState([]);
  const [createLoading, setCreateLoading] = useState(false);
  const [form] = Form.useForm();
  const { t } = useTranslation();

  useEffect(() => {
    if (listFunctions) {
      setFunctionGroups(
        Object.values(
          listFunctions.reduce((acc, cur) => {
            if (!acc[cur.groupFunction]) {
              acc[cur.groupFunction] = {
                groupName: cur.groupFunction,
                functions: []
              };
            }
            acc[cur.groupFunction].functions.push({
              name: cur.name,
              tag: cur.tag
            });
            return acc;
          }, {})
        )
      );
    }
  }, [listFunctions]);

  useEffect(() => {
    if (!selectedGroup && functionGroups?.length > 0) {
      setSelectedGroup(functionGroups?.[0]);
    }
  }, [functionGroups, selectedGroup]);

  const onSelectFunction = (group, tags) => {
    setSelectedFunctions(prev => {
      let tmp = [...prev];
      const existGroup = tmp?.some(f => f?.group === group);
      if (!existGroup) {
        tmp.push({ group, tags: [...tags] });
      }
      tmp = tmp.map(f => f?.group === group ? { ...f, tags: [...tags] } : f);
      return tmp.filter(t => t?.tags?.length > 0);
    });
  };

  const handleFinish = () => {
    const values = form.getFieldsValue();
    handleCreateRole(values);
  };

  const handleCreateRole = (value) => {
    setCreateLoading(true);
    beeXLogger.debug('handleCreateRole: ', value, selectedFunctions);
    addCustomerRole({
      role: value?.name,
      isGlobal: 0,
      namespace,
    }).then(async (res) => {
      if (!res || !res?.role || !res?.role?.roleId) {
        setCreateLoading(false);
        openMessage(NOTIFIES.ERROR, t('Failed to create role. Please try again.'));
        return;
      }
      const roleId = res?.role?.roleId;
      const functionTags = selectedFunctions.flatMap(item => item.tags);
      Promise.all(
        functionTags.map((tag) =>
          addRoleFunction({ roleId, functionTag: tag, namespace })
        )
      ).then((res) => {
        if (!res || !res?.length || res?.some(item => !item?.role || !item?.role?.roleId)) {
          openMessage(NOTIFIES.ERROR, t('Failed to create role. Please try again.'));
        }
        openMessage(NOTIFIES.SUCCESS, t('Role created successfully.'));
        setSelectedFunctions([]);
        form.resetFields();
        onDone();
        beeXLogger.debug("🚀 ~ addRoleFunction ~ res:", res);
      }).catch(err => {
        beeXLogger.debug("🚀 ~ addRoleFunction ~ err:", err);
        setCreateLoading(false);
        openMessage(NOTIFIES.ERROR, t('Failed to create role. Please try again.'));
      });
    }).catch(err => {
      beeXLogger.debug("🚀 ~ addCustomerRole ~ err:", err);
      setCreateLoading(false);
      openMessage(NOTIFIES.ERROR, t('Failed to create role. Please try again.'));
    });
  };

  useEffect(() => {
    setTimeout(() => {
      setSelectedFunctions([]);
      form.resetFields();
    }, 300);
  }, [visibleAddRole]);

  return (
    <div className="h-full w-full">
      <div className="p-4 flex flex-col gap-2 create-role-component">
        <Card className='create-role-card'>
          <Form layout="vertical" form={form} onFinish={handleFinish}>
            <Form.Item
              label={t('Name')}
              name="name"
              rules={[{ required: true, message: t("Please enter role name!") }]}
              style={{ marginBottom: 0 }}
            >
              <Input
                placeholder={t('Enter role name')}
                prefix={<EditOutlined />}
              />
            </Form.Item>
          </Form>
        </Card>
        <FunctionGroup
          functionGroups={functionGroups}
          selectedGroup={selectedGroup}
          onSelectGroup={setSelectedGroup}
          selectedFunctions={selectedFunctions}
          onSelectFunction={onSelectFunction}
        />

        <div className='w-full flex justify-end items-center'>
          <Form form={form} onFinish={handleFinish}>
            <Form.Item shouldUpdate className='btn-create-role'>
              {() => (
                <Button
                  type="primary"
                  onClick={() => form.submit()}
                  disabled={selectedFunctions?.length === 0}
                  loading={createLoading}
                >
                  {t('Create')}
                </Button>
              )}
            </Form.Item>
          </Form>
        </div>

      </div>
    </div>
  );
};

export default CreateRoleComponent;