/* eslint-disable react-hooks/exhaustive-deps */
import { GoogleOutlined, LockFilled, PhoneFilled, RightOutlined, SolutionOutlined } from '@ant-design/icons';
import * as msal from '@azure/msal-browser';
import { Button, Col, Form, Input, Row, Select } from 'antd';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import { useHistory } from 'react-router-dom';
import passWord from '../../../assets/icons/password.svg';
import userName from '../../../assets/icons/user_name.svg';
import * as SERVICE from '../../../constants/service.types';
import {
  APP_ID,
  AZURE_APP_ID,
  AZURE_REDIRECT_URI,
  AZURE_USER_NAME,
  GOOGLE_CLIENT_ID,
  GOOGLE_NAMESPACE,
  GOOGLE_USERNAME,
  NOTIFIES,
} from '../../../constants/system.keys';
import { getCheckAuthenticationType, openMessage, socketEmitEvent, updateNamespace, } from '../../../redux/actions';
import { AUTHENTICATION_SERVICE } from '@/constants/auth';
import regex from '@/constants/system.keys'
import { VerifyPasskey } from './LoginByPasskey';
import { checkLDAPAccount, getChallengeAuthenRegisterWebAuthn } from '@/hooks/socket/auth';
import { ReactComponent as PasswordIcon } from '@/assets/icons/password.svg';
import { ReactComponent as PhoneIcon } from '@/assets/icons/phone.svg';
import { ChevronRight } from 'lucide-react';
import { FingerprintIcon } from '@/icons/Fingerprint'
import { VscAzure } from 'react-icons/vsc';


const { Option } = Select;

const HOSTNAME = window.location.hostname
const LOGIN_FORM_CLASS = {
  "cloudcam1.hoasengroup.vn": { input: "hoasen-input", submit: "hoasen-submit", feedback: 'feedback hoasen-feedback', namespace: 'hoasen-namespace' }
}

const LoginByPhoneNumberComponent = ({ onBack }) => {
  const dispatch = useDispatch();
  const history = useHistory();
  const [form] = Form.useForm();
  const [formPassword] = Form.useForm();
  const [namespaces, setNamespaces] = useState();
  const [selectNamespace, setSelectNamespace] = useState();
  const [dataUserName, setDataUserName] = useState();
  const [, forceUpdate] = useState();
  const [step, setStep] = useState(0);
  const { t } = useTranslation();
  const refCountDown = useRef();
  const phonenumber = useRef(null);
  const password = useRef(null);
  const code = useRef(null);
  const [countDown, setCountDown] = useState(30);
  const [phone, setPhone] = useState();
  const [requestId, setRequestId] = useState();
  const { authData, listNamespaceAccount, authenticationAccount, listAuthenticationTypeAccount } = useSelector(
    (state) => state
  );
  const [stepPhone, setStepPhone] = useState(0);
  const [authenticationTypes, setAuthenticationTypes] = useState([])
  const [isLoading, setIsLoading] = useState(false)
  const [isLoadingPassword, setIsLoadingPassword] = useState(false)
  const [isLoadingCode, setIsLoadingCode] = useState(false)
  const [challengePasskey, setChallengePasskey] = useState(null);
  const timeoutRef = useRef(null);
  const [isTimeout, setIsTimeout] = useState(false)

  const clearRequestTimeout = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
  }, []);


  const setRequestTimeout = useCallback((formInstance, fieldName) => {
    clearRequestTimeout();
    timeoutRef.current = setTimeout(() => {
      setIsLoading(false);
      setIsLoadingPassword(false);
      setIsLoadingCode(false);
      setIsTimeout(true)
      // formInstance.setFields([
      //   {
      //     name: fieldName,
      //     errors: [t('Timeout, please try again.')],
      //   },
      // ]);
    }, 10000);
  }, [clearRequestTimeout, t]);

  useEffect(() => {
    forceUpdate({});
  }, []);

  useEffect(() => {
    if (phonenumber.current) {
      phonenumber.current.input.focus();
    }
  }, [phonenumber]);

  useEffect(() => {
    if (password.current && (step === 2 || step === 4)) {
      password.current.input.focus();
    }
  }, [password, step]);

  useEffect(() => {
    if (code.current && step === 3) {
      code.current.input.focus();
    }
  }, [code, step]);

  useEffect(() => {
    if (countDown === 0) {
      clearInterval(refCountDown.current);
    }
  }, [countDown]);

  useEffect(() => {
    if (authenticationAccount && authenticationAccount.result < 0) {
      clearRequestTimeout();
      setIsLoadingPassword(false);
      formPassword.setFields([
        {
          name: 'password',
          errors: [t('Password is incorrect!')],
        },
      ]);
    } else if (authenticationAccount && authenticationAccount.result >= 0) {
      clearRequestTimeout();
      setIsLoadingPassword(false);
    }
  }, [authenticationAccount, formPassword, t, clearRequestTimeout]);

  useEffect(() => {
    if (authData) {
      clearRequestTimeout();
      setIsLoadingCode(false);
      if (authData.result !== 1) {
        form.setFields([
          {
            name: 'code',
            errors: [authData.message],
          },
        ]);
      }
    }
    return () => {
      form.resetFields();
    };
  }, [authData, form, clearRequestTimeout]);

  const handleConfirmPhoneNumber = (phonenumber) => {
    if (phonenumber.length === 0) return;
    if (countDown && countDown > 0) {
      refCountDown.current = setInterval(() => {
        setCountDown((timer) => timer - 1);
      }, 1000);
    }
    let dataBody = {
      phonenumber,
      appId: APP_ID,
    };
    let dataObj = {
      appServiceType: SERVICE.GET_ACTIVATION_CODE,
      requestId: new Date().getTime(),
      body: JSON.stringify(dataBody),
    };
    return dispatch(socketEmitEvent(dataObj));
  };

  const handleConfirmCode = (code) => {
    if (code.length === 0) return;

    let dataBody = {
      activationCode: code,
      appId: APP_ID,
      namespace: selectNamespace,
      encrypted: 1,
      agent: `${window.navigator.userAgent}_web`,
    };

    let dataObj = {
      appServiceType: SERVICE.AUTHENTICATION,
      requestId: new Date().getTime(),
      body: JSON.stringify(dataBody),
    };

    setIsLoadingCode(true);
    setRequestTimeout(form, 'code');
    return dispatch(socketEmitEvent(dataObj));
  };

  useEffect(() => {
    if (!listAuthenticationTypeAccount) return;
    if (listAuthenticationTypeAccount?.requestId !== requestId) return;

    clearRequestTimeout();
    setIsLoading(false);

    console.log("CHECK AUTHENTICATION TYPE: ", listAuthenticationTypeAccount);
    if (listAuthenticationTypeAccount?.result === 1) {
      if (listAuthenticationTypeAccount?.data && JSON.parse(listAuthenticationTypeAccount?.data)?.length > 0) {
        console.log("CHECK AUTHENTICATION TYPE: ", JSON.parse(listAuthenticationTypeAccount?.data || '{}'));
        const data = JSON.parse(listAuthenticationTypeAccount?.data || "[]");
        setAuthenticationTypes(data || [])
        setNamespaces([...new Set(data.map(item => item.namespace))].map(namespace => ({ namespace })));
        setStep(5)
      }
    } else if (listAuthenticationTypeAccount?.result <= 0) {
      form.setFields([
        {
          name: 'userName',
          errors: [t('The account does not exist!')],
        },
      ]);
    }
  }, [listAuthenticationTypeAccount, requestId, dataUserName, clearRequestTimeout]);

  const handleLogin = (values) => {
    const time = new Date().getTime();
    let dataBody = {
      username: values?.userName || '',
      appId: APP_ID,
    };
    let dataObj = {
      appServiceType: SERVICE.CHECK_AUTHENTICATION_TYPE,
      requestId: time,
      body: JSON.stringify(dataBody),
    };
    setRequestId(time);
    setDataUserName(values?.userName || '');
    setIsLoading(true);
    setRequestTimeout(form, 'userName');
    dispatch(socketEmitEvent(dataObj));


    checkLDAPAccount({
      username: values?.userName || '',
      appId: APP_ID,
    }).then(async (res) => {
      if (Array.isArray(res) && res?.length > 0) {
        for (const item of res) {
          if (!item?.credentialId) return;

          const challengePasskey = await getChallengeAuthenRegisterWebAuthn({
            appId: APP_ID,
            phonenumber: values?.userName,
          });
          setChallengePasskey(challengePasskey)
          return
        }
      }
    });
  };

  const handleLoginPhone = (values) => {
    handleConfirmCode(values.code);
  };

  const handlePasswordLDAP = (values) => {
    let dataBody = {
      appId: APP_ID,
      accountLdapId:
        namespaces?.find((item) => item?.namespace === selectNamespace)
          ?.accountLdapId ?? '',
      password: values.password,
      username: dataUserName,
      namespace: selectNamespace,
      language: localStorage.getItem('language') ?? 'vi',
    };
    let dataObj = {
      appServiceType: SERVICE.AUTHENTICATION_LDAP,
      requestId: new Date().getTime(),
      body: JSON.stringify(dataBody),
    };

    setIsLoadingPassword(true);
    setRequestTimeout(formPassword, 'password');
    return dispatch(socketEmitEvent(dataObj));
  };

  const handlePassword = (values) => {
    let dataBody = {
      appId: APP_ID,
      password: values.password,
      username: dataUserName,
      namespace: selectNamespace,
      language: localStorage.getItem('language') ?? 'vi',
    };
    let dataObj = {
      appServiceType: SERVICE.AUTHENTICATION_PASSWORD,
      requestId: new Date().getTime(),
      body: JSON.stringify(dataBody),
    };

    setIsLoadingPassword(true);
    setRequestTimeout(formPassword, 'password');
    return dispatch(socketEmitEvent(dataObj));
  };

  const handleLoginWithAzure = (loginResponseData) => {
    if (!loginResponseData) return;
    const { tenantId, applicationId } = loginResponseData;
    const msalConfig = {
      auth: {
        clientId: applicationId,
        authority: `https://login.microsoftonline.com/${tenantId}/`,
        redirectUri: AZURE_REDIRECT_URI,
      },
    };
    const msalInstance = new msal.PublicClientApplication(msalConfig);
    const msAccount =
      msalInstance.getAccountByUsername(dataUserName || '') || undefined;
    msalInstance
      .loginPopup({
        scopes: ['openid', 'profile', 'email', 'User.Read'],
        account: msAccount,
      })
      .then((azureResponse) => {
        let dataBody = {
          appId: APP_ID,
          localAccountId: azureResponse.account?.localAccountId,
          homeAccountId: azureResponse.account?.homeAccountId,
          environment: azureResponse.account?.environment,
          tenantId: azureResponse.account?.tenantId,
          username: azureResponse.account?.username,
          idTokenClaims: azureResponse.account?.idTokenClaims,
          name: azureResponse.account?.name,

          namespace: loginResponseData.namespace,
          language: localStorage.getItem('language') ?? 'vi',
        };
        let dataObj = {
          appServiceType: SERVICE.AUTHENTICATION_AZURE,
          requestId: new Date().getTime(),
          body: JSON.stringify(dataBody),
        };
        dispatch(updateNamespace(loginResponseData.namespace));
        localStorage.setItem(AZURE_USER_NAME, dataUserName);
        localStorage.setItem(AZURE_APP_ID, applicationId);
        dispatch(socketEmitEvent(dataObj));
      })
      .catch((azureError) => {
        openMessage(NOTIFIES.WARNING, azureError.message);
      });
  };

  const handleLoginWithGoogle = (loginResponseData) => {
    console.log("handleLoginWithGoogle: ", loginResponseData);
    if (!loginResponseData) return;
    const { clientId, namespace } = loginResponseData;

    localStorage.setItem(GOOGLE_CLIENT_ID, clientId);
    localStorage.setItem(GOOGLE_NAMESPACE, namespace);
    localStorage.setItem(GOOGLE_USERNAME, dataUserName);

    window.open(
      `https://accounts.google.com/o/oauth2/v2/auth?client_id=${clientId}&redirect_uri=${window.location.origin}/login&&response_type=code&scope=email profile`,
      '_self'
    );
  };

  const handleResend = () => {
    if (phone) {
      setCountDown(30);
      clearInterval(refCountDown.current);
      handleConfirmPhoneNumber(phone);
    }
  };

  const handleSelectNamespace = () => {
    if (selectNamespace) {
      return dispatch(updateNamespace(selectNamespace));
    }
  };

  const handleConfirmAuthenticationType = useCallback((serviceId, type) => {
    console.log('serviceId: ', serviceId);
    console.log('authenticationTypes: ', authenticationTypes);
    const typeData = authenticationTypes.find(item => item?.serviceId === serviceId || (item?.type === 'phone' && type === 'phone' && item?.serviceId === 4))
    console.log('typeData: ', typeData);
    setSelectNamespace(typeData?.namespace || '')
    if (typeData?.serviceId === AUTHENTICATION_SERVICE.LDAP_INTEGRATION || typeData?.type === 'ldap') {
      setStep(2);
      handleSelectNamespace();
    } else if (typeData?.serviceId === AUTHENTICATION_SERVICE.PHONE_AUTHENTICATION || typeData?.type === 'phone') {
      console.log("Login by Phone");
      setStep(3);
      setStepPhone(1);
      handleConfirmPhoneNumber(dataUserName);
      setPhone(dataUserName);
      handleSelectNamespace();
    } else if (typeData?.serviceId === AUTHENTICATION_SERVICE.BASIC_AUTHENTICATION_INTEGRATION) {
      setStep(4);
      handleSelectNamespace();
    } else if (typeData?.serviceId === AUTHENTICATION_SERVICE.AZURE_AD_INTEGRATION) {
      handleLoginWithAzure(typeData)
    } else if (typeData?.serviceId === AUTHENTICATION_SERVICE.GOOGLE_INTEGRATION) {
      handleLoginWithGoogle(typeData)
    } else if (typeData?.serviceId === AUTHENTICATION_SERVICE.PASSKEY_AUTHENTICATION) {
      setStep(6)
    }
  }, [dataUserName, authenticationTypes])

  useEffect(() => {
    if (step === 0) {
      setChallengePasskey(null)
      setAuthenticationTypes([])
      form.resetFields()
      clearRequestTimeout();
      setIsLoading(false);
      setIsLoadingPassword(false);
      setIsLoadingCode(false);
    }
  }, [step, clearRequestTimeout]);


  useEffect(() => {
    return () => {
      clearRequestTimeout();
    };
  }, [clearRequestTimeout]);

  const authenticationTypeButtons = useMemo(() => {
    // console.log('challengePasskey: ', !!!challengePasskey);
    // console.log(authenticationTypes?.some(item => item?.serviceId === AUTHENTICATION_SERVICE.PASSKEY_AUTHENTICATION));
    console.log('authenticationTypes: ', authenticationTypes);

    return [
      {
        label: "Password",
        icon: <LockFilled className="w-5 h-5" />,
        serviceId: AUTHENTICATION_SERVICE.BASIC_AUTHENTICATION_INTEGRATION,
        hidden: !authenticationTypes?.some(
          item => item?.serviceId === AUTHENTICATION_SERVICE.BASIC_AUTHENTICATION_INTEGRATION
        ),
        type: 'password'
      },
      {
        label: "Passkey",
        icon: <FingerprintIcon className="w-5 h-5" />,
        serviceId: AUTHENTICATION_SERVICE.PASSKEY_AUTHENTICATION,
        hidden: !!!challengePasskey || !authenticationTypes?.some(
          item => item?.serviceId === AUTHENTICATION_SERVICE.PASSKEY_AUTHENTICATION
        ),
        type: 'passkey'
      },
      {
        label: "Phone number",
        icon: <PhoneFilled className="w-6 h-6" />,
        serviceId: AUTHENTICATION_SERVICE.PHONE_AUTHENTICATION,
        hidden: authenticationTypes?.some(item => item?.type === 'phone') ? false : !authenticationTypes?.some(
          item => item?.serviceId === AUTHENTICATION_SERVICE.PHONE_AUTHENTICATION
        ),
        type: 'phone'
      },
      {
        label: "Google",
        icon: <GoogleOutlined className="w-5 h-5" />,
        serviceId: AUTHENTICATION_SERVICE.GOOGLE_INTEGRATION,
        hidden: !authenticationTypes?.some(
          item => item?.serviceId === AUTHENTICATION_SERVICE.GOOGLE_INTEGRATION
        ),
        type: 'google'
      },
      {
        label: "Azure",
        icon: <VscAzure className="w-5 h-5" />,
        serviceId: AUTHENTICATION_SERVICE.AZURE_AD_INTEGRATION,
        hidden: !authenticationTypes?.some(
          item => item?.serviceId === AUTHENTICATION_SERVICE.AZURE_AD_INTEGRATION
        ),
        type: 'azure'
      },
    ]
  }, [authenticationTypes, challengePasskey])

  return (
    <>
      {step === 0 && (
        <div className="_2sd-step-login-component">
          <div />
          <Form
            className="form-login"
            form={form}
            size="large"
            name="form_login"
            onFinish={handleLogin}
          >
            <Form.Item
              name="userName"
              rules={[
                {
                  required: true,
                  message: t('Please enter user name!'),
                },
              ]}
            >
              <Input
                ref={phonenumber}
                prefix={
                  <img
                    src={userName}
                    alt="user-name"
                    className="site-form-item-icon"
                    color="blue"
                  />
                }
                placeholder={t('Enter user name')}
                className={LOGIN_FORM_CLASS[HOSTNAME]?.input || `${isTimeout && 'input-timeout'}`}
                onChange={() => {
                  if (!isTimeout) return
                  setIsTimeout(false)
                }}
                style={isTimeout ? { borderColor: '#a61d24' } : {}}
              />
            </Form.Item>
            <div
              className={`transition-all duration-300 ease-in-out overflow-hidden ${isTimeout ? 'opacity-100 max-h-10 translate-y-0' : 'opacity-0 max-h-0 -translate-y-1'
                }`}
            >
              <div role="alert" style={{ color: '#a61d24' }}>
                {t('Timeout, please try again.')}
              </div>
            </div>

            <div className="confirm-btn">
              <Button
                shape="round"
                onClick={() => {
                  form.resetFields();
                  return onBack();
                }}
              >
                {t('Back')}
              </Button>
              <Form.Item shouldUpdate={true}>
                {() => (
                  <Button
                    shape="round"
                    htmlType="submit"
                    type="primary"
                    className={LOGIN_FORM_CLASS[HOSTNAME]?.submit || ''}
                    disabled={
                      !form.isFieldsTouched(true) ||
                      form
                        .getFieldsError()
                        .filter(({ errors }) => errors.length).length
                    }
                    loading={isLoading}
                  >
                    {t('Continue')}
                  </Button>
                )}
              </Form.Item>
            </div>
          </Form>
          <div />
        </div>
      )}
      {step === 1 && (
        <div className="_3th-step-login-component">
          <div className="select-namespaces">
            <div />
            <Select
              className={LOGIN_FORM_CLASS[HOSTNAME]?.namespace || ''}
              style={{ width: '100%' }}
              loading={!namespaces}
              onSelect={(value) => setSelectNamespace(value)}
              size="large"
              placeholder={t('Select namespace')}
            >
              {namespaces &&
                namespaces.map((namespace, index) => (
                  <Option key={index} value={namespace.namespace}>
                    {namespace.namespace}
                  </Option>
                ))}
            </Select>
            <div />
          </div>
          <div className="confirm-btn">
            <Button
              shape="round"
              className="button-size-select"
              onClick={() => {
                setSelectNamespace(null);
                form.resetFields();
                setStep(0);
              }}
            >
              {t('Back')}
            </Button>
            <Button
              shape="round"
              type="primary"
              disabled={!selectNamespace}
              className={LOGIN_FORM_CLASS[HOSTNAME]?.submit || 'button-size-select'}
              onClick={() => {
                if (
                  namespaces?.find(
                    (item) => item?.namespace === selectNamespace
                  )?.type === 'ldap'
                ) {
                  setStep(2);
                  handleSelectNamespace();
                } else if (
                  namespaces?.find(
                    (item) => item?.namespace === selectNamespace
                  )?.type === 'phone'
                ) {
                  setStep(3);
                  setStepPhone(1);
                  handleConfirmPhoneNumber(dataUserName);
                  setPhone(dataUserName);
                  handleSelectNamespace();
                }
              }}
            >
              {t('Continue')}
            </Button>
          </div>
        </div>
      )}
      {/* LDAP Password */}
      {step === 2 && (
        <div className="_2sd-step-login-component">
          <div />
          <Form
            className="form-login"
            form={formPassword}
            size="large"
            name="form_login_password"
            onFinish={handlePasswordLDAP}
          >
            <Form.Item
              name="password"
              rules={[
                {
                  required: true,
                  message: t('Please enter password!'),
                },
              ]}
            >
              <Input
                ref={password}
                type="password"
                prefix={
                  <img
                    src={passWord}
                    alt="user-name"
                    className="site-form-item-icon"
                  />
                }
                className={LOGIN_FORM_CLASS[HOSTNAME]?.input || ''}
                placeholder={t('Enter password')}
              />
            </Form.Item>
            <div className="confirm-btn">
              <Button
                shape="round"
                onClick={() => {
                  formPassword.resetFields();
                  setStep(5)
                }}
              >
                {t('Back')}
              </Button>
              <Form.Item shouldUpdate={true}>
                {() => (
                  <Button
                    shape="round"
                    htmlType="submit"
                    type="primary"
                    className={LOGIN_FORM_CLASS[HOSTNAME]?.submit || ''}
                    disabled={
                      !formPassword.isFieldsTouched(true) ||
                      formPassword
                        .getFieldsError()
                        .filter(({ errors }) => errors.length).length
                    }
                    loading={isLoadingPassword}
                  >
                    {t('Continue')}
                  </Button>
                )}
              </Form.Item>
            </div>
          </Form>
          <div />
        </div>
      )}

      {step === 3 && (
        <div className="_2sd-step-login-component">
          <div />
          <Form
            className="form-login"
            form={form}
            size="large"
            name="form_login"
            onFinish={handleLoginPhone}
          >
            <Form.Item
              name="code"
              rules={[
                {
                  required: true,
                  message: t('Please enter the verification code'),
                },
              ]}
            >
              <Input
                ref={code}
                prefix={<SolutionOutlined className="site-form-item-icon" style={{ color: "#028fd5" }} />}
                placeholder={t('Verification codes')}
                className={LOGIN_FORM_CLASS[HOSTNAME]?.input || ''}
              />
            </Form.Item>
            {stepPhone === 1 ? (
              <div className={LOGIN_FORM_CLASS[HOSTNAME]?.feedback || 'feedback'} style={{ color: '#028fd5' }}>
                {countDown > 0 ? (
                  t('VERIFICATION_CODE_TIMER', { timer: countDown })
                ) : (
                  <span onClick={handleResend}>
                    {t("Don't receive verification code, resend again")}
                  </span>
                )}
              </div>
            ) : (
              <div className="feedback" />
            )}
            <div className="confirm-btn">
              <Button
                shape="round"
                onClick={() => {
                  form.resetFields();
                  setStep(5)
                }}
              >
                {t('Back')}
              </Button>
              <Form.Item shouldUpdate={true}>
                {() => (
                  <Button
                    shape="round"
                    htmlType="submit"
                    type="primary"
                    className={LOGIN_FORM_CLASS[HOSTNAME]?.submit || ''}
                    disabled={
                      !form.isFieldsTouched(true) ||
                      form
                        .getFieldsError()
                        .filter(({ errors }) => errors.length).length
                    }
                    loading={isLoadingCode}
                  >
                    {t('Continue')}
                  </Button>
                )}
              </Form.Item>
            </div>
          </Form>
          <div />
        </div>
      )}

      {step === 4 && (
        <div className="_2sd-step-login-component">
          <div />
          <Form
            className="form-login"
            form={formPassword}
            size="large"
            name="form_login_password"
            onFinish={handlePassword}
          >
            <Form.Item
              name="password"
              rules={[
                {
                  required: true,
                  message: t('Please enter password!'),
                },
              ]}
            >
              <Input
                ref={password}
                type="password"
                prefix={
                  <img
                    src={passWord}
                    alt="user-name"
                    className="site-form-item-icon"
                  />
                }
                placeholder={t('Enter password')}
              />
            </Form.Item>
            <div className="confirm-btn">
              <Button
                shape="round"
                onClick={() => {
                  formPassword.resetFields();
                  setStep(5)
                }}
              >
                {t('Back')}
              </Button>
              <Form.Item shouldUpdate={true}>
                {() => (
                  <Button
                    shape="round"
                    htmlType="submit"
                    type="primary"
                    className={LOGIN_FORM_CLASS[HOSTNAME]?.submit || ''}
                    disabled={
                      !formPassword.isFieldsTouched(true) ||
                      formPassword
                        .getFieldsError()
                        .filter(({ errors }) => errors.length).length
                    }
                    loading={isLoadingPassword}
                  >
                    {t('Continue')}
                  </Button>
                )}
              </Form.Item>
            </div>
          </Form>
          <div />
        </div>
      )}

      {
        step === 5 && (
          <div className="_3th-step-login-component">
            <div className='mx-4 flex flex-col gap-4'>
              {
                authenticationTypeButtons.map(({ label, icon, serviceId, hidden, type }) => (
                  <Button
                    key={label}
                    variant="ghost"
                    className={`relative w-full flex items-center gap-4 rounded-md px-5 py-6 shadow-none login-button transition ${hidden && "hidden"}`}
                    size="lg"
                    icon={icon}
                    onClick={() => handleConfirmAuthenticationType(serviceId, type)}
                  >
                    <div className="text-base">{label}</div>
                    <ChevronRight className="absolute right-5" style={{ color: "#028fd5" }} />
                  </Button>
                ))
              }
            </div>
            <div className="confirm-btn">
              <Button
                shape="round"
                className="button-size-select"
                onClick={() => {
                  setChallengePasskey(null)
                  form.resetFields();
                  setStep(0);
                }}
              >
                {t('Back')}
              </Button>
            </div>
          </div >
        )
      }
      {
        step === 6 && (
          <VerifyPasskey
            challengePasskey={challengePasskey}
            onBack={() => {
              setStep(5)
            }}
          />
        )
      }
    </>
  );
};

export default LoginByPhoneNumberComponent;