import React from 'react';
import { Modal, Table } from 'antd';
import { useTranslation } from 'react-i18next';

export const DownloadModal = ({
  visible,
  downloadDataSource,
  downloadTableColumn,
  containerRef,
  onOk,
  onCancel,
}) => {
  const { t } = useTranslation()
  return (
    <Modal
      title={t('Download')}
      visible={visible}
      onOk={onOk}
      onCancel={onCancel}
      footer={null}
      width={1500}
      getContainer={() => (containerRef && containerRef?.current) || document.body}
    >
      <div className="space-y-4">
        <Table
          dataSource={downloadDataSource?.map((item, index) => ({
            ...item,
            key: item?.uuid,
            index: index + 1,
          }))}
          columns={downloadTableColumn}
          pagination={false}
          scroll={{
            y: '50vh',
          }}
        />
      </div>
    </Modal>
  );
};
