import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { BasicTimeline } from '../Timeline';
import ReactPlayer from 'react-player';
import { useDispatch, useSelector } from 'react-redux';
import {
  getAvailableTimeBySerialAndDate,
  getPlaybackControls,
  getSelectedDate,
} from '@/redux/playback/reducer';
import { usePlaybackContext } from '../../context';
import clsx from 'clsx';
import './styles.scss';
import { computeQueryTime } from '../../utils';
import { DownloadContainer } from './Download';
import { getLinkStorageFileByTime } from '@/hooks/socket/playback';
import {
  setAllowPlaybackRateAdvanced,
  setForceSwitchPlaybackRate,
  setPlaybackControls,
} from '@/redux/playback/action';
import { PlaybackMainSectionMode } from '..';
import { PLAYBACK_RATE_OPTIONS } from '../shared';
import {
  BackwardOutlined,
  ForwardOutlined,
  LeftOutlined,
  RightOutlined,
} from '@ant-design/icons';
import { Spin } from 'antd';
import { beeXLogger } from '@/helpers/logger';

const ACCUMULATION_TIMEOUT = 2000;

export const PlaybackPlayer = ({
  thumbnail,
  name,
  withTimeline,
  serial,
  onClick = () => {},
  isFocused,
  shouldFetch = true,
  onReady: onVideoElementReady = () => {},
  onFrame = () => {},
  setSecureLink = () => {},
  displayMode = PlaybackMainSectionMode.FOCUS,
  setIsLoadingMirror = () => {},
  showTopName = true,
  style = {},
  allowDownload = true,
  muted,
}) => {
  const {namespace, devicesActiveOfServices} = useSelector((state) => state);
  const selectedDate = useSelector(getSelectedDate);
  const {
    reportProgress,
    removeProgress,
    getCurrentTime,
    onPivotTimeChange,
    getPivotTime,
    playbackRate,
    allowPlaybackRate,
    setPlaybackRate,
  } = usePlaybackContext();
  const availableTimes =
    useSelector(getAvailableTimeBySerialAndDate(serial, selectedDate))?.data ||
    [];
  const [storageFile, setStorageFile] = useState({ state: 'init' }); // init, loading, loaded
  const nextStorageFile = useRef({ state: 'init' });
  const prevStorageFile = useRef({ state: 'init' });
  const playerRef = useRef(null);
  const duration = useRef(0);
  const prevDuration = useRef(0);
  const playedSeconds = useRef(0);
  const lastFetchTime = useRef(0);
  const [videoLink, setVideoLink] = useState(null);
  const playbackControls = useSelector(getPlaybackControls);
  const dispatch = useDispatch();
  const simulatedIntervalRef = useRef(null);
  const isSimulatingRef = useRef(false);
  const SIMULATED_THRESHOLD = 8;
  const reverseInterval = useRef(null);
  const [videoReady, setVideoReady] = useState(false);
  const prevSrcRef = useRef(null);
  const currentTimeFastMode = useRef(0);
  const justEndedFileRef = useRef(false);
  const modeChangeLoadingTimerRef = useRef(null);
  const isSeekingRef = useRef(false);
  const seekCompleteTimerRef = useRef(null);
  const [isPlayerLoading, setIsPlayerLoading] = useState(false);
  const playerLoadingTimerRef = useRef(null);
  const videoPlayedRef = useRef(false);
  const pendingSeekRef = useRef(null);
  const playedSecondsFastMode = useRef(0);
  const playedSecondsNormalMode = useRef(0);
  const countRetryPrepare = useRef(0);
  const [forceSwitchSrc, setForceSwitchSrc] = useState(false);
  const [src, setSrc] = useState(null);
  const [accumulatedRewind, setAccumulatedRewind] = useState(0);
  const [accumulatedForward, setAccumulatedForward] = useState(0);
  const rewindTimeoutRef = useRef(null);
  const forwardTimeoutRef = useRef(null);

  const retry = useCallback(async (fn, maxRetries = 3, onSuccess, onError) => {
    try {
      const result = await fn();

      countRetryPrepare.current = 0;

      if (onSuccess) {
        onSuccess(result);
      }
      return result;
    } catch (err) {
      countRetryPrepare.current += 1;

      if (countRetryPrepare.current >= maxRetries) {
        countRetryPrepare.current = 0;
        if (onError) {
          onError(err);
        }
        return;
      }

      return retry(fn, maxRetries, onSuccess, onError);
    }
  });

  const onFastMode = useMemo(() => {
    if (!playbackRate) return false;
    const playbackRateNum = Number(playbackRate);
    if (!playbackRateNum) return false;
    return playbackRateNum >= 16;
  }, [playbackRate]);

  useEffect(() => {
    setSrc((prev) => {
      if (!storageFile?.data) return null;

      let tmp = null;
      if (forceSwitchSrc && prev?.includes('x64')) {
        console.log('prev: ', prev);
        console.log('forceSwitchSrc: ', forceSwitchSrc);
        console.log('forceSwitchSrc - storageFile.data: ', storageFile.data);
        console.log(
          'forceSwitchSrc - nextStorageFile: ',
          nextStorageFile.current.data,
        );
        setPlaybackRate(PLAYBACK_RATE_OPTIONS?.[3]?.value);
        setForceSwitchSrc(false);
        dispatch(setAllowPlaybackRateAdvanced(false));
        dispatch(setForceSwitchPlaybackRate(true));
        tmp = storageFile.data.secureLink;
        return tmp;
      }

      console.log('onFastMode: ', onFastMode);
      if (onFastMode) {
        tmp = storageFile.data.secureX64Link;
      } else {
        tmp = storageFile.data.secureLink;
      }

      console.log(' storageFile.data: ', storageFile.data);
      console.log('tmp: ', tmp);

      return tmp;
    });
  }, [storageFile, onFastMode, forceSwitchSrc, setPlaybackRate, dispatch]);

  // const src = useMemo(() => {
  //   if (!storageFile?.data) return null;

  //   if (forceSwitchSrc && src === storageFile?.data?.secureX64Link) {
  //     setForceSwitchSrc(false)
  //     return storageFile.data.secureLink;
  //   }

  //   if (onFastMode) {
  //     return storageFile.data.secureX64Link;
  //   }

  //   return storageFile.data.secureLink;
  // }, [storageFile, onFastMode, forceSwitchSrc]);

  const getCurrentElapsedTime = useCallback(() => {
    if (!storageFile?.data) {
      return 0;
    }
    return storageFile.data.from + playedSeconds.current;
  }, [storageFile]);

  const prevQuerySecondsRef = useRef(null);

  useEffect(() => {
    if (src == null) {
      prevSrcRef.current = null;
      setVideoReady(false);
      isSeekingRef.current = true;
      prevQuerySecondsRef.current = null;
      return;
    }

    const currentQuerySeconds = storageFile?.data?.querySeconds;
    const querySecondsChanged =
      prevQuerySecondsRef.current !== null &&
      currentQuerySeconds !== null &&
      prevQuerySecondsRef.current !== currentQuerySeconds;

    if (prevSrcRef.current === src) {
      if (querySecondsChanged) {
        isSeekingRef.current = true;
        videoPlayedRef.current = false;
        if (seekCompleteTimerRef.current) {
          clearTimeout(seekCompleteTimerRef.current);
          seekCompleteTimerRef.current = null;
        }
      }
      prevQuerySecondsRef.current = currentQuerySeconds;
      return;
    }

    isSeekingRef.current = true;
    videoPlayedRef.current = false;

    if (seekCompleteTimerRef.current) {
      clearTimeout(seekCompleteTimerRef.current);
      seekCompleteTimerRef.current = null;
    }

    if (!onFastMode || !prevSrcRef.current) {
      setVideoReady(false);
    }

    prevQuerySecondsRef.current = currentQuerySeconds;
  }, [src, onFastMode, storageFile]);
  const getVideo = () => playerRef.current?.getInternalPlayer();

  useEffect(() => {
    if (!serial) {
      return;
    }

    const listener = () => {
      const currentTime = getCurrentTime();
      lastFetchTime.current = currentTime;
      console.log('queryTime111', computeQueryTime(selectedDate, currentTime));

      setStorageFile({ state: 'loading' });

      getLinkStorageFileByTime({
        ipAddress: '0:0:0:0',
        deviceSerial: serial,
        queryTime: computeQueryTime(selectedDate, currentTime),
        namespace,
      })
        .then((res) => {
          if (res?.secureX64Link) {
            dispatch(setAllowPlaybackRateAdvanced(true));
          } else {
            dispatch(setAllowPlaybackRateAdvanced(false));
          }
          if (lastFetchTime.current !== currentTime) {
            console.log('FETCH STORAGE 111 SKIPPED');
            return;
          }
          const storageData = {
            ...res,
            from: currentTime - res.startSecond,
            querySeconds: currentTime,
          };
          setStorageFile({
            data: storageData,
            state: 'loaded',
          });
          pendingSeekRef.current = {
            querySeconds: currentTime,
            from: storageData.from,
            startSecond: res.startSecond,
          };
        })
        .catch((err) => {
          setStorageFile((prev) => ({
            ...prev,
            state: 'loaded',
            error: err,
          }));
        });
    };

    const unsub = onPivotTimeChange(listener);
    return () => {
      unsub();
    };
  }, [
    dispatch,
    getCurrentTime,
    namespace,
    onPivotTimeChange,
    selectedDate,
    serial,
  ]);

  useEffect(() => {
    if (shouldFetch && getPivotTime() >= 0) {
      const currentTime = getCurrentTime();
      lastFetchTime.current = currentTime;
      console.log('queryTime111', computeQueryTime(selectedDate, currentTime));

      setStorageFile({ state: 'loading' });

      getLinkStorageFileByTime({
        ipAddress: '0:0:0:0',
        deviceSerial: serial,
        queryTime: computeQueryTime(selectedDate, currentTime),
        namespace,
      })
        .then((res) => {
          if (res?.secureX64Link) {
            dispatch(setAllowPlaybackRateAdvanced(true));
          } else {
            dispatch(setAllowPlaybackRateAdvanced(false));
          }

          if (lastFetchTime.current !== currentTime) {
            return;
          }

          const storageData = {
            ...res,
            querySeconds: currentTime,
            from: currentTime - res.startSecond,
          };
          setStorageFile({
            data: storageData,
            state: 'loaded',
          });
          pendingSeekRef.current = {
            querySeconds: currentTime,
            from: storageData.from,
            startSecond: res.startSecond,
          };
        })
        .catch((err) => {
          setStorageFile((prev) => ({
            ...prev,
            state: 'loaded',
            error: err,
          }));
        });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    serial,
    selectedDate,
    shouldFetch,
    getPivotTime,
    getCurrentTime,
    namespace,
  ]);

  useEffect(() => {
    if (!videoReady) return;
    if (!storageFile?.data) return;
    if (justEndedFileRef.current) {
      justEndedFileRef.current = false;
      console.log('justEndedFileRef');
      return;
    }

    if (
      playerRef.current &&
      playerRef.current.getInternalPlayer &&
      playerRef.current.seekTo
    ) {
      const internal = playerRef.current.getInternalPlayer();

      const attemptSeek = () => {
        try {
          const duration = internal?.duration || 0;
          const querySeconds =
            storageFile.data.querySeconds ?? getCurrentElapsedTime();
          const from = storageFile.data.from ?? 0;
          let targetSeek = querySeconds - from;
          if (targetSeek < storageFile.data.startSecond) {
            targetSeek = storageFile.data.startSecond;
          }

          if (onFastMode) {
            targetSeek = targetSeek / 16;
            console.log('getCurrentElapsedTime(): ', getCurrentElapsedTime());
            console.log('storageFile: ', storageFile);
            console.log(
              'FAST MODE SEEK TO: ',
              targetSeek,
              '(duration:',
              duration,
              ')',
            );
            console.log(
              'playedSecondsNormalMode: ',
              playedSecondsNormalMode.current,
            );
            if (playedSecondsNormalMode.current > 0) {
              targetSeek = playedSecondsNormalMode.current / 16;
            }
            setTimeout(() => {
              if (internal && typeof internal.pause === 'function') {
                internal.pause();
              }
              console.log('targetSeek: ', targetSeek);
              playerRef.current.seekTo(targetSeek, 'seconds');
              playedSecondsNormalMode.current = 0;
              setTimeout(() => {
                const newCurrentTime = internal?.currentTime || 0;
                console.log(
                  'After fast mode seek - newCurrentTime:',
                  newCurrentTime,
                  'targetSeek:',
                  targetSeek,
                );

                if (
                  Math.abs(newCurrentTime - targetSeek) > 0.1 &&
                  targetSeek < duration
                ) {
                  console.log('Fast mode seek failed, retrying...');
                  if (internal && typeof internal.pause === 'function') {
                    internal.pause();
                  }
                  playerRef.current.seekTo(targetSeek, 'seconds');
                }
              }, 100);

              if (seekCompleteTimerRef.current) {
                clearTimeout(seekCompleteTimerRef.current);
              }
              seekCompleteTimerRef.current = setTimeout(() => {
                isSeekingRef.current = false;
                seekCompleteTimerRef.current = null;
              }, 500);
            }, 10);
          } else {
            console.log('pendingSeekRef: ', pendingSeekRef.current);
            if (pendingSeekRef.current && playerRef.current) {
              const { querySeconds, from, startSecond } =
                pendingSeekRef.current;
              let targetSeek = querySeconds - from;
              if (targetSeek < startSecond) {
                targetSeek = startSecond;
              }
              setTimeout(() => {
                const internal = playerRef.current?.getInternalPlayer();
                const duration = internal?.duration || 0;

                if (duration > 0 && targetSeek < duration) {
                  if (internal && typeof internal.pause === 'function') {
                    internal.pause();
                  }
                  playerRef.current.seekTo(targetSeek, 'seconds');

                  setTimeout(() => {
                    const newCurrentTime = internal?.currentTime || 0;
                    console.log(
                      'onReady - After seek, newCurrentTime:',
                      newCurrentTime,
                      'targetSeek:',
                      targetSeek,
                    );
                    if (
                      Math.abs(newCurrentTime - targetSeek) > 1 &&
                      targetSeek < duration
                    ) {
                      console.log('onReady - Seek failed, retrying...');
                      if (internal && typeof internal.pause === 'function') {
                        internal.pause();
                      }
                      playerRef.current.seekTo(targetSeek, 'seconds');
                    }
                  }, 200);
                }

                pendingSeekRef.current = null;
              }, 200);
            } else {
              if (playedSecondsFastMode.current > 0) {
                console.log(
                  'playedSecondsFastMode: ',
                  playedSecondsFastMode.current,
                );
                targetSeek = playedSecondsFastMode.current * 16;
                console.log('targetSeek: ', targetSeek);
                console.log(
                  'getCurrentElapsedTime(): ',
                  getCurrentElapsedTime(),
                );
                console.log('storageFile: ', storageFile);
                console.log(
                  'after fast playedSeconds: ',
                  playedSeconds.current,
                );
                console.log(
                  'NORMAL MODE SEEK TO: ',
                  targetSeek,
                  '(duration:',
                  duration,
                  ')',
                );
                setTimeout(() => {
                  if (internal && typeof internal.pause === 'function') {
                    internal.pause();
                  }

                  playerRef.current.seekTo(targetSeek, 'seconds');
                  playedSecondsFastMode.current = 0;

                  setTimeout(() => {
                    const newCurrentTime = internal?.currentTime || 0;
                    console.log(
                      'After normal mode seek - newCurrentTime:',
                      newCurrentTime,
                      'targetSeek:',
                      targetSeek,
                    );

                    if (
                      Math.abs(newCurrentTime - targetSeek) > 0.1 &&
                      targetSeek < duration
                    ) {
                      console.log('Normal mode seek failed, retrying...');
                      if (internal && typeof internal.pause === 'function') {
                        internal.pause();
                      }
                      playerRef.current.seekTo(targetSeek, 'seconds');
                    }
                  }, 100);

                  if (seekCompleteTimerRef.current) {
                    clearTimeout(seekCompleteTimerRef.current);
                  }
                  seekCompleteTimerRef.current = setTimeout(() => {
                    isSeekingRef.current = false;
                    seekCompleteTimerRef.current = null;
                  }, 500);
                }, 10);
              }
            }
            console.log('=======================');
          }
        } catch (err) {
          console.error('Seek error:', err);
          isSeekingRef.current = false;
        }
      };

      const seekTimer = setTimeout(attemptSeek);
      return () => {
        clearTimeout(seekTimer);
        if (seekCompleteTimerRef.current) {
          clearTimeout(seekCompleteTimerRef.current);
          seekCompleteTimerRef.current = null;
        }
        removeProgress(serial);
      };
    }

    return () => {
      removeProgress(serial);
    };
  }, [
    storageFile,
    serial,
    removeProgress,
    videoReady,
    onFastMode,
    getCurrentElapsedTime,
  ]);

  const onProgress = useCallback(
    (props) => {
      playedSeconds.current = props.playedSeconds;
      if (onFastMode) {
        playedSecondsFastMode.current = props.playedSeconds;
      } else {
        playedSecondsNormalMode.current = props.playedSeconds;
      }

      if (!storageFile?.data) {
        removeProgress(serial);
        return;
      }

      if (
        duration.current > 0 &&
        duration.current - props.playedSeconds <= 0.3 &&
        !nextStorageFile.current?.data
      ) {
        const internal = playerRef.current?.getInternalPlayer();
        if (internal && typeof internal.pause === 'function') {
          internal.pause();
        }
        return;
      }

      const PREPARE_THRESHOLD = Math.max(
        5,
        Math.min(50, duration.current * 0.2),
      );

      const shouldPrepare =
        (onFastMode
          ? duration.current - props?.playedSeconds <= 5
          : duration.current - props.playedSeconds <= PREPARE_THRESHOLD) &&
        nextStorageFile.current.state === 'init' &&
        !nextStorageFile.current.data;

      if (shouldPrepare) {
        prevStorageFile.current = storageFile;
        nextStorageFile.current = { state: 'loading' };

        const time =
          storageFile.data.from +
          (onFastMode ? prevDuration.current * 16 : prevDuration.current) +
          2;

        const queryTime = computeQueryTime(selectedDate, time);

        console.log(
          'PREPARING FILE...',
          storageFile,
          prevDuration.current,
          queryTime,
        );

        retry(
          () =>
            getLinkStorageFileByTime({
              ipAddress: '0:0:0:0',
              deviceSerial: serial,
              queryTime,
              namespace,
            }),
          3,
          (res) => {
            if (res?.secureX64Link) {
              dispatch(setAllowPlaybackRateAdvanced(true));
            } else {
              dispatch(setAllowPlaybackRateAdvanced(false));
            }

            nextStorageFile.current = {
              data: {
                ...res,
                from: time - res.startSecond,
                querySeconds: time,
              },
              state: 'loaded',
            };
          },
          (err) => {
            const findIndex = availableTimes?.findIndex(
              (item, index) =>
                (item?.from < time && time < item?.to) ||
                (item?.to < time && availableTimes?.[index + 1]?.from > time),
            );
            console.log('index: ', findIndex);

            const newTime = availableTimes?.[findIndex + 1];

            if (newTime) {
              console.log('newTime: ', newTime);
              retry(
                () =>
                  getLinkStorageFileByTime({
                    ipAddress: '0:0:0:0',
                    deviceSerial: serial,
                    queryTime: computeQueryTime(selectedDate, newTime.from),
                    namespace,
                  }),
                3,
                (res) => {
                  if (res?.secureX64Link) {
                    dispatch(setAllowPlaybackRateAdvanced(true));
                  } else {
                    dispatch(setAllowPlaybackRateAdvanced(false));
                  }

                  nextStorageFile.current = {
                    data: {
                      ...res,
                      from: newTime.from - res.startSecond,
                      querySeconds: newTime.from,
                    },
                    state: 'loaded',
                  };
                },
                (err) => {
                  nextStorageFile.current = { state: 'init', error: err };
                },
              );

              return;
            }

            nextStorageFile.current = { state: 'init', error: err };
          },
        );
      }

      let actualElapsedTime;

      if (onFastMode) {
        actualElapsedTime = storageFile.data.from + props.playedSeconds * 16;
      } else {
        actualElapsedTime = getCurrentElapsedTime();
      }

      if (onFastMode) {
        currentTimeFastMode.current = actualElapsedTime;
      }
      reportProgress(serial, actualElapsedTime);

      if (onFrame && !isSeekingRef.current && videoPlayedRef.current) {
        onFrame(getVideo(), actualElapsedTime);
      }
    },
    [
      onFastMode,
      storageFile,
      reportProgress,
      serial,
      onFrame,
      removeProgress,
      selectedDate,
      retry,
      namespace,
      dispatch,
      availableTimes,
      getCurrentElapsedTime,
    ],
  );

  useEffect(() => {
    if (
      (nextStorageFile.current.state === 'loaded' &&
        nextStorageFile.current.error) ||
      (nextStorageFile.current.state === 'loaded' &&
        !nextStorageFile.current.data)
    ) {
      nextStorageFile.current = { state: 'init' };
    }
  }, [onFastMode]);

  useEffect(() => {
    if (!videoReady || !storageFile?.data) return;

    const checkTimer = setTimeout(() => {
      if (!playerRef.current) return;

      const internal = playerRef.current.getInternalPlayer();
      const currentTime = internal?.currentTime || 0;
      const remainingTime = duration.current - currentTime;

      if (remainingTime <= 10 && nextStorageFile.current.state === 'init') {
        if (internal) {
          const fakeProgress = {
            playedSeconds: currentTime,
          };
          onProgress(fakeProgress);
        }
      }
    }, 10);

    return () => clearTimeout(checkTimer);
  }, [videoReady, storageFile, onProgress]);

  useEffect(() => {
    if (src) {
      setSecureLink(src);
      setVideoLink(src);
    }
  }, [setSecureLink, src]);

  const onReceiveDuration = (dr) => {
    console.log('onReceiveDuration: ', dr);
    duration.current = dr;
    if (dr > 0) {
      prevDuration.current = dr;
    } else {
      // console.log('duration.current: ', duration.current);
      // console.log('nextStorageFile: ', nextStorageFile.current?.data);
      // setForceSwitchSrc(true)
      // return
    }
  };

  useEffect(() => {
    if (!playbackControls) return;
    if (!playerRef.current) return;

    const internal = playerRef.current.getInternalPlayer();
    if (!internal) return;
    const current = internal.currentTime ?? internal.getCurrentTime?.() ?? 0;

    if (playbackControls?.state === 'pause') {
      if (internal.pause) internal.pause();
    }

    if (playbackControls?.state === 'play') {
      if (internal.play) internal.play();
    }

    if (playbackControls.forward) {
      const target = current + playbackControls.forward;

      playerRef.current.seekTo(target, 'seconds');

      dispatch(setPlaybackControls('forward', null));
    }

    if (playbackControls.rewind) {
      const current = internal.currentTime ?? internal.getCurrentTime?.() ?? 0;
      const target = Math.max(0, current - playbackControls.rewind);

      playerRef.current.seekTo(target, 'seconds');
      dispatch(setPlaybackControls('rewind', null));
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [playbackControls]);

  useEffect(() => {
    if (!playerRef.current) return;

    const stopSimulated = () => {
      try {
        if (simulatedIntervalRef.current) {
          clearInterval(simulatedIntervalRef.current);
          simulatedIntervalRef.current = null;
        }
      } catch (err) {}
      isSimulatingRef.current = false;
    };

    const startSimulated = (rate) => {
      stopSimulated();
      const tickMs = 400;
      const tickSec = tickMs / 1000;
      isSimulatingRef.current = true;
      try {
        const internal = playerRef.current.getInternalPlayer();
        if (internal && internal.pause) internal.pause();
      } catch (err) {
        console.log('err: ', err);
      }
      simulatedIntervalRef.current = setInterval(() => {
        try {
          const internal = playerRef.current?.getInternalPlayer();
          const current =
            internal?.currentTime ?? internal?.getCurrentTime?.() ?? 0;
          const target = current + rate * tickSec;
          if (playerRef.current && playerRef.current.seekTo) {
            playerRef.current.seekTo(target, 'seconds');
          }
        } catch (err) {
          console.log('err: ', err);
        }
      }, tickMs);
    };

    try {
      if (typeof playbackRate !== 'number' || onFastMode) {
        stopSimulated();
        return;
      }
      if (!playerRef.current) return;
      const internal = playerRef.current.getInternalPlayer();
      if (!internal) return;

      if (!allowPlaybackRate) {
        stopSimulated();
        if (typeof internal.playbackRate !== 'undefined')
          internal.playbackRate = 1;
        return;
      }

      if (playbackRate > SIMULATED_THRESHOLD) {
        console.log('START SIMULATED');
        startSimulated(playbackRate);
        return;
      }

      stopSimulated();
      if (typeof internal.playbackRate !== 'undefined') {
        internal.playbackRate = playbackRate;
      } else if (typeof internal.setPlaybackRate === 'function') {
        internal.setPlaybackRate(playbackRate);
      } else if (internal.getInternalPlayer) {
        const nested = internal.getInternalPlayer();
        if (nested && typeof nested.playbackRate !== 'undefined')
          nested.playbackRate = playbackRate;
      }
    } catch (err) {
      console.log('err: ', err);
    }
  }, [playbackRate, allowPlaybackRate, name, onFastMode]);

  useEffect(() => {
    return () => {
      try {
        if (simulatedIntervalRef.current)
          clearInterval(simulatedIntervalRef.current);
      } catch (err) {}
    };
  }, []);

  const stopReverse = useCallback(() => {
    if (reverseInterval.current) {
      clearInterval(reverseInterval.current);
      reverseInterval.current = null;
    }
  }, []);

  const startReverse = useCallback(() => {
    if (!playerRef.current) return;

    const internal = playerRef.current.getInternalPlayer();
    if (internal && internal.pause) internal.pause();

    stopReverse();
    const reverseSpeed = playbackRate || 1;
    const frameInterval = 1000 / 30;
    const secondsPerFrame = reverseSpeed / 30;

    reverseInterval.current = setInterval(() => {
      const player = playerRef.current;
      if (!player) return;

      const internalPlayer = player.getInternalPlayer();
      if (!internalPlayer) return;

      const current = internalPlayer.getCurrentTime
        ? internalPlayer.getCurrentTime()
        : internalPlayer.currentTime || 0;

      if (current <= 0) {
        stopReverse();
        return;
      }

      const newTime = Math.max(0, current - secondsPerFrame);
      if (player.seekTo) player.seekTo(newTime, 'seconds');
    }, frameInterval);
  }, [stopReverse, playbackRate]);

  useEffect(() => {
    if (!playerRef.current || !playbackControls) return;

    const video = playerRef.current.getInternalPlayer();

    if (playbackControls?.state === 'pause') {
      stopReverse();
      if (video && video.pause) video.pause();
      return;
    }

    if (playbackControls?.direction === 'reverse') {
      startReverse();
      return;
    }

    if (playbackControls?.direction === 'forward') {
      stopReverse();
      if (video && video.play) video.play();
    }
  }, [playbackControls, startReverse, stopReverse, playbackRate]);

  useEffect(() => {
    return () => stopReverse();
  }, [stopReverse]);

  useEffect(() => {
    return () => {
      if (seekCompleteTimerRef.current) {
        clearTimeout(seekCompleteTimerRef.current);
        seekCompleteTimerRef.current = null;
      }
      if (playerLoadingTimerRef.current) {
        clearTimeout(playerLoadingTimerRef.current);
        playerLoadingTimerRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (modeChangeLoadingTimerRef.current) {
      clearTimeout(modeChangeLoadingTimerRef.current);
      modeChangeLoadingTimerRef.current = null;
    }
    if (playerLoadingTimerRef.current) {
      clearTimeout(playerLoadingTimerRef.current);
      playerLoadingTimerRef.current = null;
    }

    setIsLoadingMirror(true);
    setIsPlayerLoading(true);

    modeChangeLoadingTimerRef.current = setTimeout(() => {
      modeChangeLoadingTimerRef.current = null;
      const stillLoading =
        storageFile?.state === 'loading' ||
        (storageFile?.state === 'loaded' &&
          (!storageFile?.data || !videoReady || !src));
      setIsLoadingMirror(stillLoading);
      setIsPlayerLoading(stillLoading);
    }, 300);

    return () => {
      if (modeChangeLoadingTimerRef.current) {
        clearTimeout(modeChangeLoadingTimerRef.current);
        modeChangeLoadingTimerRef.current = null;
      }
      if (playerLoadingTimerRef.current) {
        clearTimeout(playerLoadingTimerRef.current);
        playerLoadingTimerRef.current = null;
      }
    };
  }, [onFastMode, setIsLoadingMirror, storageFile, videoReady, src]);

  useEffect(() => {
    if (modeChangeLoadingTimerRef.current) {
      return;
    }

    const shouldLoading =
      storageFile?.state === 'loading' ||
      (storageFile?.state === 'loaded' &&
        (!storageFile?.data || !videoReady || !src));

    if (shouldLoading) {
      setIsLoadingMirror(true);
      setIsPlayerLoading(true);
    } else {
      if (playerLoadingTimerRef.current) {
        clearTimeout(playerLoadingTimerRef.current);
      }
      const timer = setTimeout(() => {
        setIsLoadingMirror(false);
        setIsPlayerLoading(false);
        playerLoadingTimerRef.current = null;
      }, 300);
      playerLoadingTimerRef.current = timer;
      return () => {
        clearTimeout(timer);
        if (playerLoadingTimerRef.current === timer) {
          playerLoadingTimerRef.current = null;
        }
      };
    }
  }, [storageFile, videoReady, src, setIsLoadingMirror]);

  useEffect(() => {
    if (isFocused && videoReady) {
      const videoEl = getVideo();
      if (videoEl && onVideoElementReady) {
        onVideoElementReady(videoEl, videoLink);
      }
    }
  }, [isFocused, onVideoElementReady, videoLink, videoReady]);

  useEffect(() => {
    if (!playbackControls) return;

    if (playbackControls.rewind && playbackControls.rewind > 0) {
      setAccumulatedRewind((prev) => prev + playbackControls.rewind);

      if (rewindTimeoutRef.current) {
        clearTimeout(rewindTimeoutRef.current);
      }

      rewindTimeoutRef.current = setTimeout(() => {
        setAccumulatedRewind(0);
        rewindTimeoutRef.current = null;
      }, ACCUMULATION_TIMEOUT);
    }

    if (playbackControls.forward && playbackControls.forward > 0) {
      setAccumulatedForward((prev) => prev + playbackControls.forward);

      if (forwardTimeoutRef.current) {
        clearTimeout(forwardTimeoutRef.current);
      }

      forwardTimeoutRef.current = setTimeout(() => {
        setAccumulatedForward(0);
        forwardTimeoutRef.current = null;
      }, ACCUMULATION_TIMEOUT);
    }
  }, [playbackControls]);

  useEffect(() => {
    return () => {
      if (rewindTimeoutRef.current) {
        clearTimeout(rewindTimeoutRef.current);
      }
      if (forwardTimeoutRef.current) {
        clearTimeout(forwardTimeoutRef.current);
      }
    };
  }, []);

  useEffect(() => {
    const player = playerRef.current;
    if (!player || typeof player.getInternalPlayer !== 'function') return;

    const internalPlayer = player.getInternalPlayer();
    if (!internalPlayer) return;

    if (typeof internalPlayer.muted !== 'undefined') {
      internalPlayer.muted = muted;
      internalPlayer.volume = muted ? 0 : 1;
    }
  }, [muted]);

  return (
    <div
      onClick={onClick}
      className={`playback-player ${
        isFocused ? 'playback-player-focused' : ''
      }`}
      style={{ ...style }}
    >
      {showTopName && (
        <p className="playback-player-name m-0 overflow-hidden text-ellipsis whitespace-nowrap px-1">
          {name}
        </p>
      )}
      <Spin spinning={isPlayerLoading}>
        <div className="playback-player-thumbnail relative">
          {
            <>
              {accumulatedRewind > 0 && (
                <div
                  className="absolute top-1/2 left-2"
                  style={{
                    transition: 'opacity 0.25s ease',
                    zIndex: 10000,
                    transform: 'translateY(-50%)',
                    backgroundColor: 'rgba(0, 0, 0, 0.7)',
                    padding: '8px 12px',
                    borderRadius: '4px',
                    color: 'white',
                    fontSize: '16px',
                    fontWeight: 'bold',
                  }}
                >
                  <LeftOutlined /> -{accumulatedRewind}s
                </div>
              )}
              {accumulatedForward > 0 && (
                <div
                  className="absolute top-1/2 right-2"
                  style={{
                    transition: 'opacity 0.25s ease',
                    zIndex: 10000,
                    transform: 'translateY(-50%)',
                    backgroundColor: 'rgba(0, 0, 0, 0.7)',
                    padding: '8px 12px',
                    borderRadius: '4px',
                    color: 'white',
                    fontSize: '16px',
                    fontWeight: 'bold',
                  }}
                >
                  +{accumulatedForward}s <RightOutlined />
                </div>
              )}
            </>
          }
          {allowDownload && (
            <DownloadContainer
              triggerClassName="absolute top-1 right-1 z-20"
              serial={serial}
            />
          )}
          <div
            className={`absolute top-3 left-1/2 z-50 transition-all px-6 py-1 rounded-xl
                    text-white flex items-center justify-center gap-1
                    ${playbackRate > PLAYBACK_RATE_OPTIONS?.[3]?.value && displayMode === PlaybackMainSectionMode.GRID && src ? 'opacity-100' : 'opacity-0'}
            `}
            style={{
              backgroundColor: 'rgba(0,0,0,0.6)',
              transform: 'translateX(-50%)',
            }}
          >
            <div className="flex gap-2 items-center justify-center">
              {playbackControls?.direction === 'reverse' ? (
                <>
                  <BackwardOutlined height={24} width={24} />
                  <div className="text-sm font-medium">{playbackRate}x</div>
                </>
              ) : (
                <>
                  <div className="text-sm font-medium">{playbackRate}x</div>
                  <ForwardOutlined height={24} width={24} />
                </>
              )}
            </div>
          </div>

          <ReactPlayer
            ref={playerRef}
            url={src}
            style={{
              position: 'absolute',
              zIndex: 1,
              inset: 0,
              opacity: videoReady ? 1 : 0,
              transition: 'opacity 0.25s ease',
              willChange: 'opacity',
            }}
            onProgress={onProgress}
            controls={false}
            muted={true}
            playing={videoReady}
            width="100%"
            height="100%"
            onPlay={() => {
              videoPlayedRef.current = true;
              reportProgress(serial, getCurrentElapsedTime());
            }}
            onStart={() => {
              videoPlayedRef.current = true;
              reportProgress(serial, getCurrentElapsedTime());
            }}
            onPause={() => removeProgress(serial)}
            onError={() => removeProgress(serial)}
            onEnded={() => {
              justEndedFileRef.current = true;
              removeProgress(serial);
              currentTimeFastMode.current = 0;
              playedSeconds.current = 0;
              duration.current = 0;
              setVideoReady(false);
              videoPlayedRef.current = false;
              if (nextStorageFile.current?.data) {
                setStorageFile(nextStorageFile.current);
              } else {
                setStorageFile(nextStorageFile.current);
              }
              nextStorageFile.current = { state: 'init' };
            }}
            onReady={() => {
              const videoEl = getVideo();
              prevSrcRef.current = src;
              if (!videoReady) {
                setTimeout(() => setVideoReady(true), 100);
              }

              if (videoEl && onVideoElementReady) {
                if (!videoEl.crossOrigin) {
                  videoEl.crossOrigin = 'anonymous';
                }
                try {
                  if (
                    allowPlaybackRate &&
                    typeof playbackRate !== 'undefined' &&
                    playbackRate !== null
                  ) {
                    if (typeof videoEl.playbackRate !== 'undefined')
                      videoEl.playbackRate = !onFastMode
                        ? playbackRate
                        : playbackRate / 16;
                  }
                } catch (err) {
                  console.log('err: ', err);
                }

                if (isSeekingRef.current) {
                  setTimeout(() => {
                    if (videoEl && onVideoElementReady) {
                      onVideoElementReady(videoEl, videoLink);
                    }
                  }, 500);
                } else {
                  onVideoElementReady(videoEl, videoLink);

                  if (seekCompleteTimerRef.current) {
                    clearTimeout(seekCompleteTimerRef.current);
                  }
                  seekCompleteTimerRef.current = setTimeout(() => {
                    isSeekingRef.current = false;
                    seekCompleteTimerRef.current = null;
                  }, 300);
                }
              }
            }}
            progressInterval={100}
            onDuration={onReceiveDuration}
            config={{
              file: {
                attributes: {
                  crossOrigin: 'anonymous',
                  preload: 'auto',
                  disablePictureInPicture: true,
                  controlsList: 'nodownload',
                },
              },
            }}
          />
          {!!storageFile?.error && (
            <div
              style={{ zIndex: 2 }}
              className="error-text absolute inset-0 flex items-center justify-center bg-gray-900"
            >
              <p className="px-2 text-center text-xs font-bold text-white">
                {storageFile?.error?.result === -3
                  ? 'Record not found'
                  : 'Unable to play this playback!'}
              </p>
            </div>
          )}

          <img
            src={thumbnail}
            className="absolute inset-0 object-cover max-w-full"
            style={{
              opacity: videoReady ? 0 : 1,
              transition: 'opacity 0.25s ease',
              willChange: 'opacity',
              zIndex: videoReady ? 0 : 2,
              pointerEvents: 'none',
              margin: 'auto',
              maxHeight: '100%',
            }}
            alt=""
          />
        </div>
      </Spin>

      {/* {withTimeline && serial && <Timeline serial={serial} />} */}
    </div>
  );
};

const Timeline = ({ serial }) => {
  const selectedDate = useSelector(getSelectedDate);
  const availableTimes =
    useSelector(getAvailableTimeBySerialAndDate(serial, selectedDate))?.data ||
    [];

  return <BasicTimeline times={availableTimes} />;
};
