/* eslint-disable react-hooks/exhaustive-deps */
import React, {
  Fragment,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { PlaybackPlayer } from '../Player';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick-theme.css';
import 'slick-carousel/slick/slick.css';
import { CameraInfo } from './CameraInfo';

import './styles.scss';
import { PlayerMirror } from '../Player/Mirror';
import { PlaybackPlayerLocal } from '../PlayerLocal';
import { Button, Pagination, Popover, Tooltip } from 'antd';
import ControlIconOff from '@/components/Player/icons/control_camera_off.svg';
import ControlIconOn from '@/components/Player/icons/control_camera_on.svg';
import FullscreenIcon from '@/components/Player/icons/fullscreen.svg';
import ExitFullscreenIcon from '@/components/Player/icons/fullscreen.svg';
import {
  CAMERA_BRAND,
  VIVOTEK_CAMERA_MODEL_ALLOW_PTZ,
} from '@/constants/camera';
import PTZDewarp from '@/components/Player/FisheyePlayer';
import useWindowDimensions from '@/hooks/useWindowDimensions';
import { DEWARP_MODE } from '@/constants/ptz';
import { setFocusCamera } from '@/redux/playback/action';
import { useDispatch, useSelector } from 'react-redux';
import { usePlaybackContext } from '../../context';
import { PLAYBACK_RATE_OPTIONS } from '../shared';
import {
  BackwardOutlined,
  DownCircleOutlined,
  DownOutlined,
  ForwardOutlined,
  LeftOutlined,
  RightOutlined,
  UpOutlined,
} from '@ant-design/icons';
import {
  getPlaybackControls,
  getPlaybackMode,
  getSelectedDate,
} from '@/redux/playback/reducer';
import {
  useFetchTimes,
  useFetchTimesLocal,
} from '@/redux/playback/use-fetch-times';
import { PlaybackMainFocusLayoutProgressBarContainer } from '../../ProgressBar/container';
import { DownloadContainer } from '../Player/Download';
import { EnumPlaybackType } from '../../Settings';
import InfoInactiveIcon from '@/assets/icons/info.svg';
import InfoActiveIcon from '@/assets/icons/info-active.svg';
import { beeXLogger } from '@/helpers/logger';
import MuteIcon from '@/assets/icons/mute-icon.svg';
import UnMuteIcon from '@/assets/icons/unmute-icon.svg';
import { EventHistory } from '../../ProgressBar/v3/EventHistory';
import { useProgressBarContext } from '../../ProgressBar/v3/context';

export const PlaybackMainFocusLayout = ({
  cameras,
  isLocal,
  selectedCamera,
  showInfo,
  setShowInfo,
}) => {
  const mirrorRef = useRef(null);
  const [focusSerial, setFocusSerial] = useState(
    selectedCamera ? selectedCamera.serial : cameras[0]?.serial,
  );
  const focusSerialRef = useRef(focusSerial);
  const focusCamera = useMemo(
    () =>
      selectedCamera
        ? selectedCamera
        : cameras.find((camera) => camera?.serial === focusSerial) ||
          cameras[0],
    [focusSerial, cameras, selectedCamera],
  );
  const sliderRef = useRef(null);
  const [ptzDeWarpActive, setPtzDewarpActive] = useState(false);
  const [allowPTZDewarp, setAllowPTZDewarp] = useState(false);
  const containerRef = useRef(null);
  const { width: windowWidth, height: windowHeight } = useWindowDimensions();
  const [isFullScreen, setIsFullscreen] = useState(false);
  const [videoElement, setVideoElement] = useState(null);
  const [secureLink, setSecureLink] = useState(null);
  const [selectedDewarpMode, setSelectedDewarpMode] = useState(
    DEWARP_MODE.Rectilinear,
  );
  const dispatch = useDispatch();
  const { playbackRate } = usePlaybackContext();
  const [isLoadingMirror, setIsLoadingMirror] = useState(false);

  const settings = {
    dots: false,
    infinite: false,
    speed: 500,
    swipeToSlide: true,
    slidesToShow: 3,
    slidesToScroll: 3,
  };
  const playbackControls = useSelector(getPlaybackControls);
  const { fetchTimes } = useFetchTimes();
  const { fetchTimes: fetchTimesLocal } = useFetchTimesLocal();
  const selectedDate = useSelector(getSelectedDate);
  const [showBottomControl, setShowBottomControl] = useState(true);
  const hideControlTimeout = useRef(null);
  const isInteractingRef = useRef(false);
  const playbackType = useSelector(getPlaybackMode);
  const [video, setVideo] = useState({
    muted: true,
  });

  useEffect(() => {
    if (selectedCamera) {
      setFocusSerial(selectedCamera?.serial);
    }
  }, [selectedCamera]);

  useEffect(() => {
    if (focusSerial) {
      if (playbackType === EnumPlaybackType.CLOUD) {
        fetchTimes(selectedDate, focusSerial, true);
      } else {
        fetchTimes(selectedDate, focusSerial, true);
        fetchTimesLocal(selectedDate, focusSerial, true);
      }
    }
  }, [focusSerial, selectedDate, playbackType]);

  useEffect(() => {
    focusSerialRef.current = focusSerial;
  }, [focusSerial]);

  useEffect(() => {
    if (cameras.length > 0) {
      const cameraExists = cameras.some((cam) => cam.serial === focusSerial);
      if (!focusSerial || !cameraExists) {
        setFocusSerial(cameras[0].serial);
      }
    }
  }, [cameras]);

  useEffect(() => {
    if (focusCamera) {
      dispatch(setFocusCamera(focusCamera));
    }
  }, [focusCamera]);

  useEffect(() => {
    if (secureLink && videoElement) {
      videoElement.src = secureLink;
    }
  }, [secureLink, videoElement]);

  const handleTogglePTZDewarp = () => {
    setPtzDewarpActive((prev) => !prev);
  };

  useEffect(() => {
    if (focusCamera?.brand) {
      const brandData = focusCamera?.brand?.split(';');
      if (!brandData) return;
      const brandName = brandData?.[0]?.toLowerCase();
      const model = brandData?.[1]?.toUpperCase();
      beeXLogger.debug('brandName: ', brandName);
      setAllowPTZDewarp(brandName === CAMERA_BRAND.VIVOTEK);
      return;
    }
    setAllowPTZDewarp(false);
  }, [focusCamera]);

  useEffect(() => {
    const timeout = setTimeout(() => {
      if (sliderRef.current) {
        sliderRef.current.slickGoTo(0);
      }
    }, 1000);

    return () => clearTimeout(timeout);
  }, [cameras.length]);

  const handleFullscreen = () => {
    if (
      !!(
        document.fullScreen ||
        document.webkitIsFullScreen ||
        document.mozFullScreen ||
        document.msFullscreenElement ||
        document.fullscreenElement
      )
    ) {
      if (document.exitFullscreen) document.exitFullscreen();
      else if (document.mozCancelFullScreen) document.mozCancelFullScreen();
      else if (document.webkitCancelFullScreen)
        document.webkitCancelFullScreen();
      else if (document.msExitFullscreen) document.msExitFullscreen();
    } else {
      if (containerRef.current.requestFullscreen)
        containerRef.current.requestFullscreen();
      else if (containerRef.current.mozRequestFullScreen)
        containerRef.current.mozRequestFullScreen();
      else if (containerRef.current.webkitRequestFullScreen)
        containerRef.current.webkitRequestFullScreen();
      else if (containerRef.current.msRequestFullscreen)
        containerRef.current.msRequestFullscreen();
    }
  };

  const exitHandler = useCallback(() => {
    if (
      !document.fullscreenElement &&
      !document.webkitIsFullScreen &&
      !document.mozFullScreen &&
      !document.msFullscreenElement
    ) {
      setIsFullscreen(false);
    } else {
      setIsFullscreen(true);
    }
  }, []);

  useEffect(() => {
    document.addEventListener('fullscreenchange', exitHandler);
    document.addEventListener('webkitfullscreenchange', exitHandler);
    document.addEventListener('mozfullscreenchange', exitHandler);
    document.addEventListener('MSFullscreenChange', exitHandler);

    return () => {
      document.removeEventListener('fullscreenchange', exitHandler);
      document.removeEventListener('webkitfullscreenchange', exitHandler);
      document.removeEventListener('mozfullscreenchange', exitHandler);
      document.removeEventListener('MSFullscreenChange', exitHandler);
    };
  }, [exitHandler]);

  useEffect(() => {
    if (mirrorRef.current) {
      console.log('CLEAR MIRROR');
      mirrorRef.current.clear();
      setTimeout(() => {
        const focusedCamera = cameras.find((cam) => cam.serial === focusSerial);
        if (focusedCamera) {
          setVideoElement(null);
          setSecureLink(null);
        }
      }, 50);
    }
  }, [focusSerial]);

  useEffect(() => {
    if (!isFullScreen || !containerRef.current) return;

    const container = containerRef.current;

    const resetHideTimer = () => {
      if (isInteractingRef.current || !showBottomControl) return;

      if (hideControlTimeout.current) {
        clearTimeout(hideControlTimeout.current);
      }

      hideControlTimeout.current = setTimeout(() => {
        if (!isInteractingRef.current) {
          setShowBottomControl(false);
        }
      }, 5000);
    };

    const handleMouseDown = () => {
      isInteractingRef.current = true;
    };

    const handleMouseUp = () => {
      isInteractingRef.current = false;
    };

    container.addEventListener('mousemove', resetHideTimer);
    container.addEventListener('mousedown', handleMouseDown);
    container.addEventListener('mouseup', handleMouseUp);

    return () => {
      container.removeEventListener('mousemove', resetHideTimer);
      container.removeEventListener('mousedown', handleMouseDown);
      container.removeEventListener('mouseup', handleMouseUp);

      if (hideControlTimeout.current) {
        clearTimeout(hideControlTimeout.current);
      }
    };
  }, [isFullScreen, showBottomControl]);

  return (
    <div
      className={`playback-main-focus-layout ${showInfo ? 'has-info' : 'not-has-info'}`}
    >
      <div
        className={`playback-local-player-sub-controls-left ${showInfo ? 'show' : 'hide'}`}
      >
        <Tooltip
          title={showInfo ? null : 'Show info'}
          autoAdjustOverflow={false}
          align={{
            offset: [-50, 0],
          }}
        >
          <Button
            shape="circle"
            type="primary"
            onClick={() => setShowInfo(true)}
          >
            <LeftOutlined />
          </Button>
        </Tooltip>
      </div>
      <div
        className={`playback-main-focus-layout-content ${showInfo ? 'show-info' : 'hide-info'}`}
      >
        <div className="playback-main-focus-layout-left">
          <div className="playback-main-focus-layout-top">
            <div
              className="bg-gray-900 relative player-mirror-container"
              ref={containerRef}
            >
              <div
                className={`absolute top-3 left-1/2 z-50 transition-all px-6 py-1 rounded-xl
          text-white flex items-center justify-center gap-1
          ${typeof playbackRate === 'number' ? (playbackRate > PLAYBACK_RATE_OPTIONS?.[3]?.value ? 'opacity-100' : 'opacity-0') : 'opacity-0'}
                `}
                style={{
                  backgroundColor: 'rgba(0,0,0,0.6)',
                  transform: 'translateX(-50%)',
                }}
              >
                <div className="flex gap-2 items-center justify-center">
                  {playbackControls?.direction === 'reverse' ? (
                    <>
                      <BackwardOutlined height={24} width={24} />
                      <div className="text-sm font-medium">{playbackRate}x</div>
                    </>
                  ) : (
                    <>
                      <div className="text-sm font-medium">{playbackRate}x</div>
                      <ForwardOutlined height={24} width={24} />
                    </>
                  )}
                </div>
              </div>
              {!isLocal && (
                <PlaybackPlayer
                  thumbnail={focusCamera?.thumbnail}
                  // videoHeight={160}
                  name={focusCamera?.name}
                  withTimeline
                  serial={focusCamera?.serial}
                  onClick={() => {
                    console.log('focusCamera: ', focusCamera);
                    setFocusSerial(focusCamera?.serial);
                  }}
                  isFocused={focusSerial === focusCamera?.serial}
                  onReady={(videoElement, link) => {
                    if (focusCamera?.serial === focusSerialRef.current) {
                      // mirrorRef.current.render(videoElement);

                      try {
                        videoElement.crossOrigin = 'anonymous';
                        videoElement.preload = 'auto';
                        videoElement.autoplay = false;
                        if (
                          typeof videoElement.disablePictureInPicture !==
                          'undefined'
                        ) {
                          videoElement.disablePictureInPicture = true;
                        }
                        if (typeof videoElement.controlsList !== 'undefined') {
                          videoElement.controlsList = 'nodownload';
                        } else {
                          videoElement.setAttribute &&
                            videoElement.setAttribute(
                              'controlsList',
                              'nodownload',
                            );
                        }
                      } catch (e) {}

                      if (link && videoElement.src !== link) {
                        videoElement.src = link;
                      }

                      setVideoElement(videoElement);
                    }
                  }}
                  onFrame={(videoElement) => {
                    if (focusCamera?.serial === focusSerialRef.current) {
                      // mirrorRef.current.render(videoElement);

                      try {
                        videoElement.crossOrigin = 'anonymous';
                        videoElement.preload = 'auto';
                        videoElement.autoplay = false;
                        if (
                          typeof videoElement.disablePictureInPicture !==
                          'undefined'
                        )
                          videoElement.disablePictureInPicture = true;
                        if (typeof videoElement.controlsList !== 'undefined')
                          videoElement.controlsList = 'nodownload';
                      } catch (e) {}

                      setVideoElement(videoElement);
                    }
                  }}
                  brand={focusCamera?.brand || ''}
                  setSecureLink={setSecureLink}
                  setIsLoadingMirror={setIsLoadingMirror}
                  style={{
                    backgroundColor: 'black',
                  }}
                  allowDownload={false}
                  muted={video?.muted}
                />
              )}

              {isLocal && (
                <PlaybackPlayerLocal
                  key={focusCamera?.serial}
                  isFocused={focusSerial === focusCamera?.serial}
                  onClick={() => {
                    console.log('camera: ', focusCamera);
                    setFocusSerial(focusCamera?.serial);
                  }}
                  camera={focusCamera}
                  onReady={(videoElement) => {
                    if (focusCamera?.serial === focusSerialRef.current) {
                      // mirrorRef.current.render(videoElement);
                      try {
                        videoElement.crossOrigin = 'anonymous';
                        videoElement.preload = 'auto';
                        videoElement.autoplay = false;
                        if (
                          typeof videoElement.disablePictureInPicture !==
                          'undefined'
                        ) {
                          videoElement.disablePictureInPicture = true;
                        }
                        if (typeof videoElement.controlsList !== 'undefined') {
                          videoElement.controlsList = 'nodownload';
                        } else {
                          videoElement.setAttribute &&
                            videoElement.setAttribute(
                              'controlsList',
                              'nodownload',
                            );
                        }
                      } catch (e) {}
                      setVideoElement(videoElement);
                    }
                  }}
                  onFrame={(videoElement) => {
                    if (focusCamera?.serial === focusSerialRef.current) {
                      // mirrorRef.current.render(videoElement);
                      try {
                        videoElement.crossOrigin = 'anonymous';
                        videoElement.preload = 'auto';
                        videoElement.autoplay = false;
                        if (
                          typeof videoElement.disablePictureInPicture !==
                          'undefined'
                        )
                          videoElement.disablePictureInPicture = true;
                        if (typeof videoElement.controlsList !== 'undefined')
                          videoElement.controlsList = 'nodownload';
                      } catch (e) {}
                      setVideoElement(videoElement);
                    }
                  }}
                  muted={video?.muted}
                />
              )}

              <div
                className={`bottom-control-player ${isFullScreen ? 'in-fullscreen' : 'no-in-fullscreen'} ${showBottomControl ? 'show' : ''}`}
              >
                {isFullScreen && (
                  <Tooltip title={showBottomControl ? 'Hide' : 'Show'}>
                    <div
                      className="toggle-control-player"
                      onClick={(e) => {
                        e.stopPropagation();
                        setShowBottomControl((prev) => !prev);
                        if (hideControlTimeout.current) {
                          clearTimeout(hideControlTimeout.current);
                        }
                      }}
                      onMouseDown={(e) => e.stopPropagation()}
                    >
                      {showBottomControl ? <DownOutlined /> : <UpOutlined />}
                    </div>
                  </Tooltip>
                )}

                <div className="control-buttons">
                  {videoElement && allowPTZDewarp && (
                    <img
                      src={ptzDeWarpActive ? ControlIconOn : ControlIconOff}
                      alt="PTZ Dewarp"
                      width={24}
                      height={24}
                      onClick={handleTogglePTZDewarp}
                      className="cursor-pointer"
                    />
                  )}
                  {videoElement &&
                    !isFullScreen &&
                    (video?.muted ? (
                      <img
                        src={MuteIcon}
                        onClick={() => {
                          setVideo((prev) => ({ ...prev, muted: false }));
                        }}
                        alt=""
                        width={24}
                        height={24}
                        className="cursor-pointer"
                      />
                    ) : (
                      <img
                        src={UnMuteIcon}
                        onClick={() => {
                          setVideo((prev) => ({ ...prev, muted: true }));
                        }}
                        alt=""
                        width={24}
                        height={24}
                        className="cursor-pointer"
                      />
                    ))}
                  {!isFullScreen && (
                    <img
                      src={isFullScreen ? ExitFullscreenIcon : FullscreenIcon}
                      alt="Fullscreen"
                      width={24}
                      height={24}
                      onClick={handleFullscreen}
                      className="cursor-pointer"
                    />
                  )}
                </div>

                {isFullScreen && (
                  <div
                    className="bottom-control-in-fullscreen"
                    onMouseDown={(e) => e.stopPropagation()}
                  >
                    <PlaybackMainFocusLayoutProgressBarContainer
                      isFullScreen={isFullScreen}
                      handleTogglePTZDewarp={handleTogglePTZDewarp}
                      ptzDeWarpActive={ptzDeWarpActive}
                      handleFullscreen={handleFullscreen}
                      containerRef={containerRef}
                      handleMuted={(value) => {
                        setVideo((prev) => ({ ...prev, muted: value }));
                      }}
                      muted={video?.muted}
                    />
                  </div>
                )}
              </div>
              {ptzDeWarpActive && videoElement && (
                <PTZDewarp
                  videoElement={videoElement}
                  isActive={true}
                  containerWidth={
                    containerRef.current?.clientWidth || windowWidth
                  }
                  containerHeight={
                    containerRef.current?.clientHeight || windowHeight
                  }
                  className={isFullScreen && 'fullscreen'}
                  selectedDewarpMode={selectedDewarpMode}
                />
              )}
            </div>
          </div>
        </div>
        <div
          className={`playback-main-focus-layout-right ${showInfo ? 'show' : 'hide'}`}
        >
          <EventHistory
            isFullScreen={false}
            showInfo={showInfo}
            setShowInfo={setShowInfo}
          />
        </div>
      </div>
    </div>
  );
};
