import { useEffect, useState } from 'react'

export const useInternalStream = ({ gatewaySerial }) => {
  const [isInternal, setInternal] = useState(null)

  useEffect(() => {
    ;(async () => {
      if (gatewaySerial) {
        try {
          const url = `https://${gatewaySerial}.ezcam.vn:9090/info`
          const promise = await fetch(url, {
            signal: AbortSignal.timeout(1000),
          })
          const response = await promise.json()
          setInternal(response?.localMedia === 'on')
        } catch (e) {
          setInternal(false)
        } finally {
        }
      }
    })()
  }, [gatewaySerial])

  return { isInternal: !!isInternal, isLoading: isInternal === null }
}
