import { CameraGroupSelector } from '@/components/CameraGroupSelector';
import { ROOT_GROUP_ID } from '@/constants/group';
import {
  useListAllDevicesByPage,
  useListDeviceByDeviceGroupIdQuery,
} from '@/hooks/socket/cameras';
import { Input, Table, Tag } from 'antd';
import React, { useEffect, useMemo, useState } from 'react';
import colorsDark from '@/assets/colors/dark';
import { permissionStringToArray } from '../shared';
import { StateTag } from '@/components/StateTag';

const additionalOptions = [
  {
    label: 'All cameras',
    value: ROOT_GROUP_ID,
  },
];

export const CameraTable = ({
  namespace,
  selectedGroupId,
  selectedSerials,
  onSelectCameras,
  onSelectGroupId,
}) => {
  const [allCameraStates, setAllCameraStates] = useState({
    timeRequest: Date.now(),
    page: 1,
    size: 10,
    search: '',
  });

  const [dataByDeviceGroupStates, setDataByDeviceGroupStates] = useState({
    timeRequest: Date.now(),
    page: 1,
    size: 10,
    search: '',
  });

  const {
    send: fetchAllCameras,
    isLoading: isLoadingAllCameras,
    data: allCameraData,
  } = useListAllDevicesByPage();

  const { isLoading: isLoadingDataByDeviceGroup, data: dataByDeviceGroup } =
    useListDeviceByDeviceGroupIdQuery({
      deviceGroupId: selectedGroupId,
      // doesnt matter
      timeRequest: dataByDeviceGroupStates.timeRequest,
      namespace,
    });

  useEffect(() => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      fetchAllCameras({
        namespace,
        timeRequest: allCameraStates.timeRequest,
        page: allCameraStates.page - 1,
        size: allCameraStates.size,
        name: allCameraStates.search || undefined,
        deviceType: 'camera',
        tag: 'shares-cameras',
      });
    }
  }, [
    allCameraStates.timeRequest,
    allCameraStates.page,
    allCameraStates.size,
    allCameraStates.search,
    namespace,
    selectedGroupId,
    fetchAllCameras,
  ]);

  const cameras = useMemo(() => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      return allCameraData?.devices || [];
    }

    return (dataByDeviceGroup?.cameraInfos || []).filter((camera) =>
      camera.name
        .toLowerCase()
        .includes(dataByDeviceGroupStates.search.toLowerCase())
    );
  }, [
    allCameraData,
    dataByDeviceGroup,
    selectedGroupId,
    dataByDeviceGroupStates.search,
  ]);

  console.log('CAMMM', allCameraData, dataByDeviceGroup);

  const onSelectGroup = (group) => {
    const groupId = group?.id || ROOT_GROUP_ID;

    if (groupId === selectedGroupId) return;

    setDataByDeviceGroupStates({
      timeRequest: Date.now(),
      page: 1,
      size: 10,
      search: '',
    });
    setAllCameraStates({
      timeRequest: Date.now(),
      page: 1,
      size: 10,
      search: '',
    });
    onSelectGroupId(groupId);
  };

  const onSearch = (value) => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      setAllCameraStates({
        timeRequest: Date.now(),
        page: 1,
        size: 10,
        search: value,
      });
    } else {
      setDataByDeviceGroupStates({
        timeRequest: Date.now(),
        page: 1,
        size: 10,
        search: value,
      });
    }
  };

  const dataSource = useMemo(
    () =>
      cameras.map((camera) => ({
        key: camera.serial,
        ...camera,
      })),
    [cameras]
  );

  const page = useMemo(() => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      return allCameraStates.page;
    }
    return dataByDeviceGroupStates.page;
  }, [selectedGroupId, allCameraStates.page, dataByDeviceGroupStates.page]);

  const pageSize = useMemo(() => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      return allCameraStates.size;
    }

    return dataByDeviceGroupStates.size;
  }, [selectedGroupId, allCameraStates.size, dataByDeviceGroupStates.size]);

  const total = useMemo(() => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      return allCameraData?.total || 0;
    }

    return cameras?.length || 0;
  }, [allCameraData, cameras, selectedGroupId]);

  const pagination = useMemo(
    () => ({
      current: page,
      pageSize,
      total,
    }),
    [page, pageSize, total]
  );

  const onPageChange = (page) => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      setAllCameraStates({ ...allCameraStates, page });
    } else {
      setDataByDeviceGroupStates({ ...dataByDeviceGroupStates, page });
    }
  };

  const isLoading =
    selectedGroupId === ROOT_GROUP_ID
      ? isLoadingAllCameras
      : isLoadingDataByDeviceGroup;

  return (
    <div className="og2-cameras-camera-table-component">
      <CameraGroupSelector
        namespace={namespace}
        onSelect={onSelectGroup}
        selectedId={selectedGroupId}
        additionalOptions={additionalOptions}
      />

      <Input.Search
        key={selectedGroupId}
        placeholder="Search camera"
        onSearch={(value) => onSearch(value)}
        allowClear
      />

      <Table
        size="middle"
        loading={isLoading}
        dataSource={dataSource}
        pagination={{
          ...pagination,
          showSizeChanger: false,
          onChange: onPageChange,
        }}
        columns={columns}
        rowSelection={{
          type: 'checkbox',
          selectedRowKeys: selectedSerials,
          onChange: (keys, rows) => {
            onSelectCameras(rows);
          },
        }}
        scroll={{
          y: 'calc(100vh - 328px)',
        }}
      />
    </div>
  );
};

const columns = [
  {
    title: 'Name',
    dataIndex: 'name',
    key: 'name',
    render: (text, record) => {
      return (
        <div>
          <p className="m-0">{record.name}</p>
          <p className="m-0 text-brand underline">
            {permissionStringToArray(record.permission).join(', ')}
          </p>
        </div>
      );
    },
  },
  {
    title: 'State',
    dataIndex: 'state',
    key: 'state',
    render: (text, record) => {
      return <StateTag state={record?.state} />
    },
    width: 80,
  },
];
