/* eslint-disable react-hooks/exhaustive-deps */
import { Button, DatePicker, Select, Table } from 'antd';
import moment from 'moment';
import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { getCustomerDevicesApi } from '../../api/customerApi';
import { DECODED_ACCESS_TOKEN, NAMESPACE, NOTIFIES } from '../../constants/system.keys';
import * as ACTIONS from '../../redux/actions';
import storageService from '../../services/storage.service';
import './index.scss';
import { useSelector } from 'react-redux';

const PAGE_SIZE = 10

const { RangePicker } = DatePicker;
const { Option } = Select;

const LogEventGateway = ({ dataDevice }) => {
  const { t } = useTranslation();
  const [isLoading, setIsLoading] = useState(false);
  const [current, setCurrent] = useState(1)
  const [dataPageSize, setDataPageSize] = useState(PAGE_SIZE)
  const [dataRangerGateway, setDataRangerGateway] = useState([moment("01-01-2019", "DD-MM-YYYY").valueOf(), moment().valueOf()]);
  const [dataFilterType, setDataFilterType] = useState('gateway_lost_internet');
  const [dataLogGateway, setDataLogGateway] = useState({});
  const [isLoadingExport, setIsLoadingExport] = useState(false);
  const { namespace } = useSelector(state => state)


  useEffect(() => {
    if (dataDevice) {
      setIsLoading(true)
      onFilterLog(dataDevice?.serial, dataFilterType)
    }
  }, [dataDevice]);

  const onFilterLog = async (serial, type, fromTime, toTime, limit, offset) => {
    const token = storageService.getInternalStorageByKey(DECODED_ACCESS_TOKEN);
    const dataQuery = {
      serial,
      fromTime: fromTime ?? moment("01-01-2019", "DD-MM-YYYY").valueOf(),
      toTime: toTime ?? moment().valueOf(),
      limit: limit ?? PAGE_SIZE,
      offset: offset ?? 0,
      isDownload: 0,
      type,
    }
    const dataRes = await getCustomerDevicesApi(token, { namespace }, dataQuery)
    if (dataRes?.data?.deviceReports) {
      console.log('dataRes?.data: ', dataRes?.data);
      setDataLogGateway(dataRes?.data ?? {})
    }
    setIsLoading(false)
  }

  const onDownloadLog = async (serial, type, fromTime, toTime, limit, offset) => {
    const token = storageService.getInternalStorageByKey(DECODED_ACCESS_TOKEN);
    const dataQuery = {
      serial,
      fromTime: fromTime ?? moment("01-01-2019", "DD-MM-YYYY").valueOf(),
      toTime: toTime ?? moment().valueOf(),
      limit: limit ?? PAGE_SIZE,
      offset: offset ?? 0,
      isDownload: 1,
      type,
    }
    const dataRes = await getCustomerDevicesApi(token, { namespace }, dataQuery)
    setTimeout(() => {
      if (dataRes?.data) {
        const buttonElement = document.createElement('a');
        buttonElement.href = `data:text/csv;charset=utf-8,${encodeURI(dataRes.data)}`;
        buttonElement.target = '_blank';
        buttonElement.download = `report-log.${moment(fromTime).format('DD_MM_YYYY')}-${moment(toTime).format('DD_MM_YYYY')}.csv`;
        buttonElement.click();
      } else {
        ACTIONS.openMessage(NOTIFIES.WARNING, 'No data export');
      }
      setIsLoadingExport(false)
    }, 800);
  }

  const onPageChange = (newPage, pageSize) => {
    setCurrent(newPage)
    setDataPageSize(pageSize)
    setIsLoading(true);
    onFilterLog(dataDevice?.serial, dataFilterType, dataRangerGateway[0], dataRangerGateway[1], pageSize, (newPage - 1) * dataPageSize)
  }

  const handleDateRangerChange = (values) => {
    const FromDate = values.length > 0 ? values[0].set({ hour: 0, minute: 0, second: 0 }) : '';
    const ToDate = values.length > 0 ? values[1].set({ hour: 23, minute: 59, second: 59 }) : '';
    setCurrent(1)
    setDataPageSize(PAGE_SIZE)
    setIsLoading(true);
    setDataRangerGateway([moment(FromDate).valueOf(), moment(ToDate).valueOf()])
    onFilterLog(dataDevice?.serial, dataFilterType, moment(FromDate).valueOf(), moment(ToDate).valueOf(), PAGE_SIZE, 0)
  };

  const handleSelectType = (value) => {
    setCurrent(1)
    setDataPageSize(PAGE_SIZE)
    setIsLoading(true);
    setDataFilterType(value)
    onFilterLog(dataDevice?.serial, value, dataRangerGateway[0], dataRangerGateway[1], PAGE_SIZE, 0)
  };

  const convertHMS = (value) => {
    const sec = parseInt(value, 10); // convert value to number if it's string
    let hours = Math.floor(sec / 3600); // get hours
    let minutes = Math.floor((sec - (hours * 3600)) / 60); // get minutes
    let seconds = sec - (hours * 3600) - (minutes * 60); //  get seconds
    // add 0 if value < 10; Example: 2 => 02
    if (hours < 10) { hours = "0" + hours; }
    if (minutes < 10) { minutes = "0" + minutes; }
    if (seconds < 10) { seconds = "0" + seconds; }
    return hours + ':' + minutes + ':' + seconds; // Return is HH : MM : SS
  }

  const colums1 = [
    {
      title: 'Disconnection time',
      dataIndex: 'startTime',
      key: 'startTime_log',
      render: (text, row) => (
        <span>{row?.content ?
          (JSON.parse(row?.content)?.startTime < 0 ? moment(JSON.parse(row?.content)?.endTime * 1000)
            .utcOffset(JSON.parse(row?.content)?.startTime / 60)
            .format('HH:mm:ss DD-MM-YYYY') : moment(JSON.parse(row?.content)?.startTime * 1000).format('HH:mm:ss DD-MM-YYYY'))
          : ''}</span>
      ),
    },
    {
      title: 'Connected time',
      dataIndex: 'endTime',
      key: 'endTime_log',
      render: (text, row) => (
        <span>{row?.content ?
          moment(JSON.parse(row?.content)?.endTime * 1000).format('HH:mm:ss DD-MM-YYYY')
          : ''}</span>
      ),
    },
    {
      title: 'Duration',
      dataIndex: 'duration',
      key: 'duration',
      render: (text, row) => row?.content ?
        (JSON.parse(row?.content)?.startTime > 0 ?
          convertHMS(Math.round(moment.utc(moment(JSON.parse(row?.content)?.endTime * 1000).diff(moment(JSON.parse(row?.content)?.startTime * 1000))).valueOf() / 1000)) :
          moment(JSON.parse(row?.content)?.startTime)?.format('HH:mm:ss DD-MM-YYYY'))
        : '',
    },
    {
      title: 'Message',
      dataIndex: 'message',
      key: 'message_log',
      render: (text, row) => <span>{row?.content ? JSON.parse(row?.content)?.message : ''}</span>,
    },
  ]

  const colums2 = [
    {
      title: 'Event time',
      key: 'eventTime',
      dataIndex: 'eventTime',
      render: (text) => moment(text).format('HH:mm:ss DD-MM-YYYY'),
    },
    {
      title: 'Message',
      dataIndex: 'message',
      key: 'message_gateway',
      render: (text, row) => <span>{row?.content ?? ''}</span>,
    },
  ]

  return (
    <div className="log-gateway-page">
      <div className="box-customer-header">
        <div className="title-box-customer">
        </div>
        <Select
          value={dataFilterType}
          style={{ width: '230px', textAlign: 'start', marginRight: '16px' }}
          onChange={handleSelectType}
        >
          <Option value="gateway_lost_internet">
            <span>Gateway mất kết nối internet</span>
          </Option>
          <Option value="gateway_lost_power">
            <span>Gateway mất nguồn điện</span>
          </Option>
        </Select>
        <RangePicker
          allowClear={false}
          defaultValue={[moment("01-01-2019", "DD-MM-YYYY"), moment()]}
          format='DD-MM-YYYY'
          onChange={handleDateRangerChange}
          style={{ marginRight: '16px' }}
        />
        <Button
          loading={isLoadingExport}
          size="middle"
          type="primary"
          onClick={() => {
            onDownloadLog(dataDevice?.serial, dataFilterType, dataRangerGateway[0], dataRangerGateway[1], dataLogGateway?.total, 0)
            setIsLoadingExport(true)
          }}
        >
          {t('Export report')}
        </Button>
        {/* </div> */}
      </div>
      <div className="table-page">
        <Table
          loading={isLoading}
          size="small"
          columns={((dataFilterType === 'camera_disconnection_session') ||
            (dataFilterType === 'gateway_lost_internet')) ? colums2 : dataFilterType === 'gateway_lost_power' ? colums1 : []}
          pagination={{
            onChange: onPageChange,
            pageSize: dataPageSize,
            current,
            total: dataLogGateway?.total,
            position: ['bottomRight'],
            pageSizeOptions: ['10', '20', '50', '100', '200', '400']
          }}
          dataSource={
            dataLogGateway?.deviceReports?.filter(item => item?.type === dataFilterType)?.map((data, index) => ({
              ...data,
              key: index + 1,
              index: (index + 1) * 1,
            }))
          }
        />
      </div>
    </div>
  );
}

export default LogEventGateway;
