/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react';
import { DownloadOutlined, LoadingOutlined } from '@ant-design/icons';
import {
  Button,
  DatePicker,
  Modal,
  Progress,
  Spin,
  Table,
  Tooltip,
} from 'antd';
import { useSelector } from 'react-redux';
import {
  getAvailableTimeBySerialAndDate,
  getSelectedDate,
} from '@/redux/playback/reducer';
import clsx from 'clsx';
import Downloader from '../../downloader';
import { getLinkStorageFileByTime } from '@/hooks/socket/playback';
import { computeQueryTime } from '../../utils';
import moment from 'moment';
import { PLAYBACK_DATE_FORMAT } from '@/constants/time';
import { useFetchTimes } from '@/redux/playback/use-fetch-times';
import { useDownloadContext } from '../../context';

export const DownloadButton = ({ onClick, isDownloading, className, buttonStyle = {} }) => {
  return (
    <button
      onClick={onClick}
      className={clsx(
        'ml-auto flex h-8 w-8 cursor-pointer items-center justify-center rounded-full border-none bg-gray-100',
        className
      )}
      style={{ ...buttonStyle }}
    >
      <DownloadOutlined style={{
        color: isDownloading ? '#028fd5' : Object.keys(buttonStyle).length > 0 ? '#fff' : '#000',
      }}
        width={Object.keys(buttonStyle).length > 0 ? 24 : 14}
        height={Object.keys(buttonStyle).length > 0 ? 24 : 14}
      />
    </button>
  );
};

export const formatTime = (time) => {
  const hours = Math.floor(time / 3600)
    .toString()
    .padStart(2, '0');
  const minutes = Math.floor((time % 3600) / 60)
    .toString()
    .padStart(2, '0');
  const seconds = Math.floor(time % 60)
    .toString()
    .padStart(2, '0');
  return `${hours}:${minutes}:${seconds}`;
};

export const DownloadModal = ({
  isOpen,
  onClose,
  onDownload,
  downloadState,
  initialSelectedDate,
  serial,
}) => {
  const [selectedDate, setSelectedDate] = useState(
    initialSelectedDate || moment().format(PLAYBACK_DATE_FORMAT)
  );

  useEffect(() => {
    if (initialSelectedDate) {
      setSelectedDate(initialSelectedDate)
    }
  }, [initialSelectedDate]);
  const [selectedTime, setSelectedTime] = useState([]);

  // console.log('DOWNLOAD STATE', downloadState);

  const { fetchTimes } = useFetchTimes();

  const availableTimesData =
    useSelector(getAvailableTimeBySerialAndDate(serial, selectedDate)) || {};

  const availableTimes = availableTimesData.data || [];
  const isLoading = availableTimesData.loading;

  const dataSource = availableTimes.map((time) => ({
    key: `${selectedDate}|${time.from}-${time.to}`,
    ...time,
  }));

  useEffect(() => {
    setSelectedTime([]);
    fetchTimes(selectedDate, serial);
  }, [selectedDate]);

  return (
    // @ts-ignore
    <Modal
      visible={isOpen}
      onCancel={onClose}
      title="Download records"
      footer={null}
      style={{
        zIndex: 10000
      }}
    >
      <div className="flex flex-col gap-2 mb-2">
        <div className="flex gap-2 justify-between">
          <DatePicker
            value={moment(selectedDate, PLAYBACK_DATE_FORMAT)}
            onChange={(value) =>
              setSelectedDate(
                value?.format(PLAYBACK_DATE_FORMAT) ||
                moment().format(PLAYBACK_DATE_FORMAT)
              )
            }
            className="mb-1 w-1/2"
            getPopupContainer={(trigger) => trigger.parentElement}
          />
          <Button
            onClick={() => {
              onDownload(selectedDate, selectedTime);
            }}
            icon={<DownloadOutlined />}
            disabled={selectedTime.length === 0}
          >
            Download
          </Button>
        </div>
      </div>
      <Table
        loading={isLoading}
        dataSource={dataSource}
        columns={[
          {
            title: 'From',
            dataIndex: 'from',
            render: (text) => <span>{formatTime(text)}</span>,
          },
          {
            title: 'To',
            dataIndex: 'to',
            render: (text) => <span>{formatTime(text)}</span>,
          },
          {
            title: 'Status',
            dataIndex: 'key',
            render: (key) => {
              const state = downloadState[key];

              if (!state) {
                return '';
              }

              if (state?.status === 'waiting') {
                return (
                  <Tooltip title="Preparing file, may take a while">
                    <div>
                      <Spin
                        spinning
                        indicator={<LoadingOutlined />}
                        className="mr-1"
                        size="small"
                      />
                      Preparing file
                    </div>
                  </Tooltip>
                );
              }

              if (state?.status === 'completed') {
                return (
                  <div className="flex items-center gap-2">
                    <Button
                      size="small"
                      onClick={() => {
                        if (state.blob) {
                          Downloader.downloadBlob(
                            state.blob,
                            state.key + '.mp4'
                          );
                        }
                      }}
                      icon={<DownloadOutlined />}
                    ></Button>
                  </div>
                );
              }

              if (state?.status === 'error') {
                return <span>Failed</span>;
              }

              return (
                <Progress
                  percent={state?.progress || 0}
                  showInfo={false}
                  style={{ width: 120 }}
                />
              );
            },
          },
        ]}
        rowSelection={{
          selectedRowKeys: selectedTime,
          onChange: (selectedRowKeys) => setSelectedTime(selectedRowKeys),
        }}
        pagination={false}
        scroll={{
          y: '50vh',
        }}
      />
    </Modal>
  );
};

export const DownloadContainer = ({ triggerClassName, serial, buttonStyle = {} }) => {
  const [_, rerender] = useState({});
  const [isOpen, setIsOpen] = useState(false);
  const initialSelectedDate = useSelector(getSelectedDate);
  useEffect(() => {
    console.log('initialSelectedDate: ', initialSelectedDate);
  }, [initialSelectedDate]);
  const namespace = useSelector((state) => state.namespace);
  const { downloader } = useDownloadContext();
  const queryStr = `playback-${serial}|`;
  const downloadState = downloader.query((key) => key.startsWith(queryStr));

  useEffect(() => {
    if (!isOpen) return;

    const unsub = downloader.subscribe(() => rerender({}));

    return () => unsub();
  }, [serial, isOpen]);

  const downloadEach = async (selectedDate, from, to) => {
    const downloadKey = `playback-${serial}|${selectedDate}|${from}-${to}`;

    const downloadState = downloader.getState(downloadKey);

    if (downloadState && downloadState.status !== 'error') {
      return;
    }

    downloader.addToWaitList(downloadKey);

    getLinkStorageFileByTime({
      namespace,
      deviceSerial: serial,
      ipAddress: '0:0:0:0',
      queryTime: computeQueryTime(selectedDate, Math.floor((from + to) / 2)),
    }).then(
      ({ secureLink }) => {
        downloader.download(downloadKey, secureLink);
      },
      () => downloader.cancel(downloadKey)
    );
  };

  const onDownload = (selectedDate, selectedTime) => {
    selectedTime.forEach(async (time) => {
      const [_, fromToStr] = time.split('|');
      const [from, to] = fromToStr.split('-').map(Number);
      downloadEach(selectedDate, from, to);
    });
  };

  const formattedDownloadState = downloadState.reduce((acc, { key, state }) => {
    const [_, date, fromToStr] = key.split('|');

    acc[`${date}|${fromToStr}`] = state;

    return acc;
  }, {});

  return (
    <>
      <DownloadButton
        onClick={(e) => {
          e.stopPropagation();
          setIsOpen(true);
        }}
        className={triggerClassName}
        buttonStyle={{ ...buttonStyle }}
      />
      <DownloadModal
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
        downloadState={formattedDownloadState}
        onDownload={onDownload}
        initialSelectedDate={initialSelectedDate}
        serial={serial}
      />
    </>
  );
};
