import {
  AVAILABLE_TIME_LOADING,
  AVAILABLE_TIME_SUCCESS,
  AVAILABLE_TIME_ERROR,
  SET_SELECTED_DATE,
  STORAGE_FILE_LOADING,
  STORAGE_FILE_SUCCESS,
  STORAGE_FILE_ERROR,
  SET_AVAILABLE_TIME_LOCAL,
  SET_MODE,
  SET_FOCUS_CAMERA,
  SET_PLAYBACK_CONTROLS,
  CACHING_PLAYBACK_THUMBNAILS,
  ALLOW_PLAYBACK_RATE_ADVANCED,
  FORCE_SWITCH_PLAYBACK_RATE,
  CACHING_DOWNLOAD_PLAYBACK,
  SYNC_COMPRESS_STATES,
  ADD_COMPRESS,
  UPDATE_COMPRESS,
  REMOVE_COMPRESS,
} from './action';

import moment from 'moment';
import { errorState, loadingState, successState } from '../actions';
import { EnumPlaybackType } from '@/constants/playback';

export const PLAYBACK_KEY = 'playback-v2';

const initialState = {
  availableTime: {},
  availableTimeLocal: {},
  storageFile: {},
  selectedDate: moment().format('YYYY-MM-DD'),
  mode: EnumPlaybackType.LOCAL,
  compressesByUuid: [],
};
const internalReducer = (state = initialState, action) => {
  const { date, serial } = action.payload || {};

  switch (action.type) {
    case AVAILABLE_TIME_LOADING:
      return {
        ...state,
        availableTime: {
          ...state.availableTime,
          [serial]: { ...state.availableTime[serial], [date]: loadingState() },
        },
      };
    case AVAILABLE_TIME_SUCCESS:
      return {
        ...state,
        availableTime: {
          ...state.availableTime,
          [serial]: {
            ...state.availableTime[serial],
            [date]: successState(action.payload.data),
          },
        },
      };
    case AVAILABLE_TIME_ERROR:
      return {
        ...state,
        availableTime: {
          ...state.availableTime,
          [serial]: {
            ...state.availableTime[serial],
            [date]: errorState(action.payload.error),
          },
        },
      };
    case SET_AVAILABLE_TIME_LOCAL:
      return {
        ...state,
        availableTimeLocal: {
          ...state.availableTimeLocal,
          [serial]: {
            ...state.availableTimeLocal[serial],
            [date]: action.payload.data,
          },
        },
      };
    case STORAGE_FILE_LOADING:
      return {
        ...state,
        storageFile: {
          ...state.storageFile,
          [serial]: loadingState(),
        },
      };
    case STORAGE_FILE_SUCCESS:
      return {
        ...state,
        storageFile: {
          ...state.storageFile,
          [serial]: successState(action.payload.data),
        },
      };
    case STORAGE_FILE_ERROR:
      return {
        ...state,
        storageFile: {
          ...state.storageFile,
          [serial]: errorState(action.payload.error),
        },
      };

    case SET_SELECTED_DATE: {
      if (state.selectedDate === action.payload) {
        return state;
      }
      return {
        ...state,
        selectedDate: action.payload,
      };
    }
    case SET_MODE: {
      return {
        ...state,
        mode: action.payload,
      };
    }
    case SET_FOCUS_CAMERA: {
      return {
        ...state,
        focusCamera: action.payload,
      };
    }
    case SET_PLAYBACK_CONTROLS: {
      return {
        ...state,
        playbackControls: action.payload,
      };
    }
    case CACHING_PLAYBACK_THUMBNAILS: {
      return {
        ...state,
        playbackThumbnails: action.payload,
      };
    }
    case ALLOW_PLAYBACK_RATE_ADVANCED: {
      return {
        ...state,
        allowPlaybackRateAdvanced: action.payload,
      };
    }
    case FORCE_SWITCH_PLAYBACK_RATE: {
      return {
        ...state,
        forceSwitchPlaybackRate: action.payload,
      };
    }
    case CACHING_DOWNLOAD_PLAYBACK: {
      return {
        ...state,
        cachingDownloadPlaybacks: action.payload,
      };
    }
    case SYNC_COMPRESS_STATES:
      return {
        ...state,
        compressesByUuid: {
          ...state.compressesByUuid,
          [action.payload.uuid]: action.payload.downloads,
        },
      };

    case ADD_COMPRESS: {
      let currentDownloads = state.compressesByUuid || [];
      // beeXLogger.debug('ADD_COMPRESS - currentDownloads: ', currentDownloads);
      const exist = currentDownloads?.find(
        (item) => item?.uuid === action?.payload?.uuid,
      );
      // beeXLogger.debug('ADD_COMPRESS - exist: ', exist);
      if (exist) {
        return {
          ...state,
          compressesByUuid: currentDownloads?.map((item) =>
            item?.uuid === action?.payload?.uuid
              ? action.payload.download
              : item,
          ),
        };
      }
      currentDownloads = [...currentDownloads, action.payload.download];
      // beeXLogger.debug('ADD_COMPRESS - currentDownloads: ', currentDownloads);
      return {
        ...state,
        compressesByUuid: currentDownloads,
      };
    }

    case UPDATE_COMPRESS: {
      const currentDownloads = state.compressesByUuid || [];
      // beeXLogger.debug('UPDATE_COMPRESS - currentDownloads: ', currentDownloads);
      // beeXLogger.debug('UPDATE_COMPRESS - action.payload: ', action.payload);
      return {
        ...state,
        compressesByUuid: currentDownloads?.map((item) =>
          item?.uuid === action?.payload?.uuid
            ? { ...item, ...action.payload.updates }
            : item,
        ),
      };
    }

    case REMOVE_COMPRESS: {
      let currentDownloads = state.compressesByUuid || [];
      return {
        ...state,
        compressesByUuid: currentDownloads?.filter(
          (item) => item?.uuid !== action?.payload?.uuid,
        ),
      };
    }

    default:
      return state;
  }
};

export const playbackReducer = (state, action) => {
  const playbackState = state[PLAYBACK_KEY] || initialState;
  const newPlaybackState = internalReducer(playbackState, action);

  if (playbackState === newPlaybackState) {
    return state;
  }

  return { ...state, [PLAYBACK_KEY]: newPlaybackState };
};

export const getPlaybackState = (state) => {
  return state[PLAYBACK_KEY] || initialState;
};

export const getAvailableTimeBySerialAndDate = (serial, date) => (state) => {
  return getPlaybackState(state).availableTime[serial]?.[date];
};

export const getAvailableTimeBySerialAndDateLocal = (serial, date) => {
  return (state) => {
    return getPlaybackState(state).availableTimeLocal[serial]?.[date];
  };
};

export const getSelectedDate = (state) => {
  return getPlaybackState(state).selectedDate;
};

export const getStorageFile = (state) => {
  return getPlaybackState(state).storageFile;
};

export const getStorageFileBySerial = (serial) => (state) => {
  return getPlaybackState(state).storageFile[serial];
};

export const getPlaybackMode = (state) => {
  return getPlaybackState(state).mode;
};

export const getFocusCamera = (state) => {
  return getPlaybackState(state).focusCamera;
};

export const getPlaybackControls = (state) => {
  return getPlaybackState(state).playbackControls;
};

export const getPlaybackThumbnails = (state) => {
  return getPlaybackState(state).playbackThumbnails;
};

export const getAllowPlaybackRateAdvanced = (state) => {
  return getPlaybackState(state).allowPlaybackRateAdvanced;
};

export const getForceSwitchPlaybackRate = (state) => {
  return getPlaybackState(state).forceSwitchPlaybackRate;
};

export const getCachingDownloadPlaybacks = (state) => {
  return getPlaybackState(state).cachingDownloadPlaybacks;
};

export const getAllCompress = (state) =>
  getPlaybackState(state).compressesByUuid || [];
