import React, { useCallback, useEffect, useState } from 'react';
import './index.scss';
import { useTranslation } from 'react-i18next';
import RoleCustomerTable from './RoleCustomerTable';
import { getListCustomerRole } from '@/hooks/socket/role';
import { useSelector } from 'react-redux';
import { beeXLogger } from '@/helpers/logger';
import { Modal } from 'antd';
import CreateRoleComponent from './CreateRole';

const RoleManagement = ({ visibleAddRole = false, setVisibleAddRole = () => { } }) => {
  const { t } = useTranslation()
  const { namespace } = useSelector(state => state)

  const [listCustomerRole, setListCustomerRole] = useState(null)
  const [loadingTable, setLoadingTable] = useState(false)
  const [doneCreateRole, setDoneCreateRole] = useState(false)

  const fetchCustomerRoles = useCallback(async () => {
    if (!namespace) return

    try {
      setLoadingTable(true)

      const res = await getListCustomerRole({ namespace })
      beeXLogger.debug("🚀 ~ fetchCustomerRoles ~ res:", res)

      setListCustomerRole(res)
    } catch (err) {
      beeXLogger.error("🚀 ~ fetchCustomerRoles ~ err:", err)
    } finally {
      setLoadingTable(false)
    }
  }, [namespace])

  useEffect(() => {
    fetchCustomerRoles()
  }, [fetchCustomerRoles])

  const onDoneCreateRole = useCallback(() => {
    setVisibleAddRole(false)
    setDoneCreateRole(true)
    fetchCustomerRoles()
  }, [fetchCustomerRoles, setVisibleAddRole])

  return (
    <div className="h-full w-full role-management-component">
      <RoleCustomerTable
        data={listCustomerRole}
        loading={loadingTable}
        onRefresh={fetchCustomerRoles}
      />
      <Modal
        className='add-role-modal'
        title="Add role"
        visible={visibleAddRole}
        maskClosable={false}
        footer={null}
        okButtonProps={{ style: { display: 'none' } }}
        onCancel={() => setVisibleAddRole(false)}
      >
        <CreateRoleComponent onDone={onDoneCreateRole} visibleAddRole={visibleAddRole} />
      </Modal>
    </div>
  )
}

export default RoleManagement