import { useRef, useCallback, useMemo } from 'react';

export const INACTIVE_PIVOT_TIME = -1;

/**
 * Time starts to elapse as soon as a camera report its progress and stop elapsing when all camera progress is removed
 */
export const usePlaybackProgress = (props) => {
  const pivotTime = useRef(props?.initialPivotTime ?? INACTIVE_PIVOT_TIME);
  const onElapsedTimeChangeCallbacks = useRef([]);
  const onPivotTimeChangeCallbacks = useRef([]);
  const progressSerial = useRef(new Map());
  const lastReportedProgress = useRef(undefined);

  const setPivotTime = useCallback((time, notify = true) => {
    pivotTime.current = time;
    resetProgress();

    if (notify) {
      notifyPivotTimeChange();
    }
  }, []);

  const isActive = useCallback(() => {
    return progressSerial.current.size > 0;
  }, []);

  const reportProgress = useCallback((serial, elapsedTime) => {
    progressSerial.current.set(serial, elapsedTime);
    updateElapsedTime();
  }, []);

  const removeProgress = useCallback(
    (serial) => {
      const currentTime = getCurrentTime();
      progressSerial.current.delete(serial);

      if (isActive()) {
        updateElapsedTime();
      } else {
        setPivotTime(currentTime, false);
      }
    },
    [isActive, setPivotTime],
  );

  const lastNotifyValue = useRef(0);

  const notifyElapsedTimeChange = useCallback(() => {
    const elapsedTime = getElapsedTime();

    if (Math.floor(elapsedTime) === Math.floor(lastNotifyValue.current)) {
      lastNotifyValue.current = elapsedTime;
      return;
    }

    lastNotifyValue.current = elapsedTime;

    onElapsedTimeChangeCallbacks.current.forEach((callback) => {
      callback(elapsedTime);
    });
  }, []);

  const notifyPivotTimeChange = useCallback(() => {
    onPivotTimeChangeCallbacks.current.forEach((callback) => {
      callback(pivotTime.current);
    });
  }, []);

  const onPivotTimeChange = useCallback((callback) => {
    onPivotTimeChangeCallbacks.current.push(callback);
    return () =>
      (onPivotTimeChangeCallbacks.current =
        onPivotTimeChangeCallbacks.current.filter((cb) => cb !== callback));
  }, []);

  const updateElapsedTime = useCallback(() => {
    if (isActive()) {
      const now = Date.now();
      if (lastReportedProgress.current === undefined) {
        lastReportedProgress.current = now;
      }

      lastReportedProgress.current = now;
      setTimeout(() => {
        notifyElapsedTimeChange();
      });
    } else {
      console.log('resetElapsedTime');
      lastReportedProgress.current = undefined;
      lastReportedProgress.current = 0;
    }
  }, [isActive, notifyElapsedTimeChange]);

  const onElapsedTimeChange = useCallback((callback) => {
    onElapsedTimeChangeCallbacks.current.push(callback);
    return () =>
      (onElapsedTimeChangeCallbacks.current =
        onElapsedTimeChangeCallbacks.current.filter((cb) => cb !== callback));
  }, []);

  const getCurrentTime = useCallback(() => {
    if (isActive()) {
      return getElapsedTime();
    }

    return getPivotTime();
  }, [isActive]);

  const getPivotTime = useCallback(() => {
    return pivotTime.current;
  }, []);

  const getElapsedTime = useCallback(() => {
    const firstKey = progressSerial.current.keys().next().value;

    if (!firstKey) {
      return 0;
    }

    return progressSerial.current.get(firstKey) ?? 0;
  }, []);

  const resetProgress = useCallback(() => {
    progressSerial.current.clear();
    lastReportedProgress.current = undefined;
    lastNotifyValue.current = 0;
  }, []);

  return useMemo(
    () => ({
      getPivotTime,
      setPivotTime,
      getElapsedTime,
      getCurrentTime,
      onElapsedTimeChange,
      reportProgress,
      removeProgress,
      onPivotTimeChange,
      isActive,
    }),
    [
      getPivotTime,
      setPivotTime,
      getElapsedTime,
      getCurrentTime,
      onElapsedTimeChange,
      reportProgress,
      removeProgress,
      onPivotTimeChange,
      isActive,
    ],
  );
};
