import React, { useCallback, useEffect, useMemo, useState } from 'react';
import moment from 'moment';
import { Empty, Modal, Pagination, Tag, Tooltip } from 'antd';
import { EVENT_ICONS, EVENT_LABELS } from './constants';
import { useProgressBarContext } from './context';
import { usePlaybackContext } from '../../context';
import './index.scss';
import { AiEventType, EVENT_SERVICE_IDS } from '@/constants/events';
import NodataIcon from '@/assets/icons/no-data-icon-v2.svg';
import { ClockCircleOutlined, CloseOutlined } from '@ant-design/icons';

const PAGE_SIZE = 4;

export const EventHistory = ({
  isFullScreen,
  onPageChange = () => {},
  showInfo,
  setShowInfo,
}) => {
  const { currentTime, initialSelectedDate, eventTypes } =
    useProgressBarContext();
  const { selectedEvent, setSelectedEvent, aiEvents } = usePlaybackContext();
  const eventHistoryData = aiEvents?.eventHistoryData || [];
  const [visibleImageModal, setVisibleImageModal] = useState(null);
  const [activeEventTypes, setActiveEventTypes] = useState(new Set());
  const events = useMemo(() => {
    const selectedDay = moment(initialSelectedDate).format('YYYY-MM-DD');
    return eventHistoryData
      .filter((event) => {
        const eventDate = moment(event.timestamp).format('YYYY-MM-DD');
        return eventDate === selectedDay;
      })
      ?.filter(
        (event) =>
          activeEventTypes?.has(event?.type) ||
          activeEventTypes?.has(event?.serviceId),
      );
  }, [activeEventTypes, eventHistoryData, initialSelectedDate]);
  const totalEvents = events?.length || 0;
  const [currentPage, setCurrentPage] = useState(1);
  const paginatedEvents = useMemo(() => {
    return events?.slice(
      (currentPage - 1) * PAGE_SIZE,
      currentPage * PAGE_SIZE,
    );
  }, [events, currentPage]);

  const handlePageChange = (page) => {
    setCurrentPage(page);
    onPageChange({ page, offset: (page - 1) * PAGE_SIZE, limit: PAGE_SIZE });
  };

  const renderEventTitle = useCallback((event) => {
    if (!event || !event.type) return 'Unknown event';
    switch (event.type) {
      case AiEventType.FACE_RECOGNITION:
        return `${event?.objects} - ${event?.personName}`;
      default:
        return event?.objects || EVENT_LABELS[event.type] || event.type;
    }
  }, []);

  useEffect(() => {
    if (eventTypes) {
      setActiveEventTypes(new Set(eventTypes));
    }
  }, [eventTypes, setActiveEventTypes]);

  return (
    <>
      <div className="overflow-hidden mt-2 h-full ml-1 px-2">
        <div className="flex items-center justify-between mb-1">
          <span
            className={`font-semibold flex items-center gap-2 ${isFullScreen ? 'text-white' : 'text-gray-800'}`}
          >
            <ClockCircleOutlined />
            <span>Events</span>
          </span>
          <Tooltip title={showInfo ? 'Hide info' : null} placement="bottomLeft">
            <CloseOutlined onClick={() => setShowInfo(!showInfo)} />
          </Tooltip>
        </div>
        <div className="events-filter">
          <EventTypeFilter
            activeEventTypes={activeEventTypes}
            setActiveEventTypes={setActiveEventTypes}
          />
        </div>
        <div className="overflow-y-auto events-list">
          {paginatedEvents?.length === 0 ? (
            <Empty description="No data" image={NodataIcon} />
          ) : (
            paginatedEvents?.map((event, index) => (
              <div
                key={event?.recordId || index}
                onClick={() => setSelectedEvent(event)}
                className={`event-item flex items-center gap-3 p-2 py-3 cursor-pointer transition-colors ${
                  isFullScreen
                    ? 'hover:bg-white/10 border-b border-white/10'
                    : 'hover:bg-gray-50 border-b border-gray-300'
                } ${
                  event.time === Math.floor(currentTime)
                    ? isFullScreen
                      ? 'bg-white/20'
                      : 'bg-blue-50'
                    : ''
                }
              ${
                event?.type === AiEventType.COMMON_EVENT_DETECTION &&
                event?.serviceId === EVENT_SERVICE_IDS.MOTION_DETECTION
                  ? selectedEvent?.id === event?.id
                    ? 'selected'
                    : ''
                  : selectedEvent?.recordId === event?.recordId
                    ? 'selected'
                    : ''
              }
                `}
              >
                <div className="flex-shrink-0 w-16 h-12 rounded overflow-hidden bg-gray-200">
                  <img
                    src={event.imageUrl || event?.originPathFile}
                    alt=''
                    className="w-full h-full object-cover"
                    onClick={(e) => {
                      e.stopPropagation();
                      setVisibleImageModal(event);
                    }}
                  />
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span
                      className={`text-xs font-semibold ${isFullScreen ? 'text-white' : 'text-gray-800'}`}
                    >
                      {renderEventTitle(event)}
                    </span>
                  </div>
                  <div
                    className={`text-xs ${isFullScreen ? 'text-white/70' : 'text-gray-500'}`}
                  >
                    {moment(event.timestamp).format('HH:mm:ss')}
                  </div>
                  <div
                    className={`text-xs ${isFullScreen ? 'text-white/70' : 'text-gray-500'}`}
                  >
                    {event?.cameraLocation}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
        {totalEvents > 0 && (
          <div
            className={`flex justify-end pt-2 border-t ${isFullScreen ? 'border-white/10' : 'border-gray-100'}`}
          >
            <Pagination
              current={currentPage}
              total={totalEvents}
              pageSize={PAGE_SIZE}
              onChange={handlePageChange}
              size="small"
              showSizeChanger={false}
            />
          </div>
        )}
      </div>
      <Modal
        visible={!!visibleImageModal}
        onCancel={() => setVisibleImageModal(null)}
        footer={null}
        title={renderEventTitle(visibleImageModal)}
      >
        {visibleImageModal && (
          <img
            src={
              visibleImageModal?.imageUrl || visibleImageModal?.originPathFile
            }
            alt={EVENT_LABELS[visibleImageModal?.type]}
            className="w-full h-full object-cover"
          />
        )}
      </Modal>
    </>
  );
};

const EVENT_FILTER_LABELS = {
  [AiEventType.DETECT_OBJECT]: 'Object',
  [AiEventType.DETECT_PERSON]: 'Person',
  [AiEventType.DETECT_VIRTUAL_WALL]: 'Virtual wall crossing',
  [AiEventType.DETECT_WEAPON]: 'Weapon',
  [AiEventType.DETECT_FIRE]: 'Fire',
  [AiEventType.DETECT_WARNING_ZONE]: 'Warning zone crossing',
  [AiEventType.SECURITY_IDENTIFICATION]: 'Security identification',
  [AiEventType.SECURITY_TRACKING_EVENT]: 'Security tracking event',
  [AiEventType.FACE_RECOGNITION]: 'Face recognition',
  // [AiEventType.DETECT_PERSON_FALL]: 'Person fall',
  [AiEventType.DETECT_MANU_UNSAFE_EVENT]: 'Manual unsafe event',
  [AiEventType.DETECT_WARNING_EVENT]: 'Warning event',
  [AiEventType.SECURITY_TRACKING_OBJECT_EVENT]:
    'Security tracking object event',
  [AiEventType.CHANGE_WAREHOUSE_SUPERVISION]: 'Change warehouse supervision',
  [EVENT_SERVICE_IDS.MOTION_DETECTION]: 'Motion',
};

export const EventTypeFilter = ({
  activeEventTypes = new Set(),
  setActiveEventTypes,
}) => {
  const { eventTypes } = useProgressBarContext();

  const toggleEventType = (type) => {
    const newSet = new Set(activeEventTypes);
    if (newSet.has(type)) {
      newSet.delete(type);
    } else {
      newSet.add(type);
    }
    setActiveEventTypes(newSet);
  };

  if (!eventTypes || eventTypes.size === 0) return null;

  return (
    <div className="event-type-filter">
      {[...eventTypes].map((type) => (
        <div
          className={`event-type-chip ${activeEventTypes.has(type) ? 'active' : ''}`}
          key={type}
          onClick={() => toggleEventType(type)}
        >
          {EVENT_ICONS[type]}
          <span>{EVENT_FILTER_LABELS[type]}</span>
        </div>
      ))}
    </div>
  );
};
