import { useMemo, useEffect, useState, useRef } from 'react';
import moment from 'moment';
import { EVENT_COLORS, EVENT_LABELS } from './constants';
import { formatTime, timeToSeconds, SECONDS_IN_DAY } from './utils';
import {
  getCommonEventDetection,
  getEventsByPersonId,
  getFireDetection,
  getHistoryTrackingEvents,
  getNonComplianceWarning,
  getPersonDetectionApi,
  getSecurityIdentifications,
  getVirtualWall,
  getWarningEventDetection,
  getWarningZone,
  getWeaponDetection,
} from '@/api/criticalApi';
import storageService from '@/services/storage.service';
import { DECODED_ACCESS_TOKEN } from '@/constants/system.keys';
import { useSelector } from 'react-redux';
import { beeXLogger } from '@/helpers/logger';
import { AiEventType, EVENT_SERVICE_IDS } from '@/constants/events';

export const getAllAiEvents = (
  namespace,
  selectedDate,
  serials,
  onEvents,
  requestId,
  getRequestId,
  onTotal,
) => {
  const token = storageService.getInternalStorageByKey(DECODED_ACCESS_TOKEN);

  const serialSet = new Set(serials);

  const baseQuery = {
    token,
    dataHeader: { namespace },
    dataQuery: {
      fromTime: moment(selectedDate).startOf('day').valueOf(),
      toTime: moment(selectedDate).endOf('day').valueOf(),
      customerNamespace: namespace,
      isDownload: 0,
      limit: 50,
      offset: 0,
      serial: '',
    },
  };

  const apiConfigs = [
    // {
    //   api: getVirtualWall(baseQuery),
    //   type: AiEventType.DETECT_VIRTUAL_WALL,
    // },
    // {
    //   api: getWeaponDetection(baseQuery),
    //   type: AiEventType.DETECT_WEAPON,
    // },
    // {
    //   api: getHistoryTrackingEvents(baseQuery),
    //   type: AiEventType.SECURITY_TRACKING_EVENT,
    // },
    {
      api: getEventsByPersonId({
        token,
        dataHeader: { namespace: '', tenantId: namespace },
        dataQuery: {
          fromTime: moment(selectedDate).startOf('day').valueOf(),
          toTime: moment(selectedDate).endOf('day').valueOf(),
          limit: 50,
          offset: 0,
          personId: '',
        },
      }),
      type: AiEventType.FACE_RECOGNITION,
    },
    // {
    //   api: getSecurityIdentifications(baseQuery),
    //   type: AiEventType.SECURITY_IDENTIFICATION,
    // },
    // {
    //   api: getWarningZone(baseQuery),
    //   type: AiEventType.DETECT_WARNING_ZONE,
    // },
    // {
    //   api: getFireDetection(baseQuery),
    //   type: AiEventType.DETECT_FIRE,
    // },
    // {
    //   api: getNonComplianceWarning(baseQuery),
    //   type: AiEventType.DETECT_MANU_UNSAFE_EVENT,
    // },
    // {
    //   api: getWarningEventDetection({
    //     ...baseQuery,
    //     dataQuery: { ...baseQuery.dataQuery, serviceId: 74 },
    //   }),
    //   type: AiEventType.DETECT_WARNING_EVENT,
    // },
    {
      api: getPersonDetectionApi({
        ...baseQuery,
        dataBody: {},
      }),
      type: AiEventType.DETECT_PERSON,
    },
    {
      api: getCommonEventDetection({
        ...baseQuery,
      }),
      type: AiEventType.COMMON_EVENT_DETECTION,
    },
  ];

  let totalAll = 0;

  apiConfigs.forEach(({ api, type }) => {
    if (type === AiEventType.COMMON_EVENT_DETECTION) {
      serials.forEach((serial) => {
        if (!serial) return;
        getCommonEventDetection({
          ...baseQuery,
          dataQuery: {
            ...baseQuery.dataQuery,
            serial,
          },
        })
          .then((response) => {
            if (requestId !== getRequestId()) return;

            let records = response?.data?.records ?? [];

            records = records.filter(
              (event) => event.serviceId === EVENT_SERVICE_IDS.MOTION_DETECTION,
            );

            const events = records.map((record) => ({
              ...record,
              type,
            }));

            totalAll += events.length;

            if (events.length > 0) {
              onEvents(events);
            }
          })
          .catch(() => {});
      });

      return;
    }
    api
      .then((response) => {
        if (requestId !== getRequestId()) return;

        let records = response?.data?.records ?? [];

        if (type === AiEventType.FACE_RECOGNITION) {
          records = response?.data?.cdrs ?? [];
        }

        const events = records
          ?.filter((record) => serialSet.has(record?.serial))
          ?.map((record) => ({
            ...record,
            type,
          }));

        totalAll += events.length;

        if (events.length > 0) {
          onEvents(events);
        }
      })
      .catch(() => {});
  });

  setTimeout(() => {
    if (requestId === getRequestId()) {
      onTotal(totalAll);
    }
  }, 0);
};

export const useEvents = (initialSelectedDate, serials) => {
  const { namespace } = useSelector((state) => state);
  const [eventsData, setEventsData] = useState([]);
  const requestIdRef = useRef(0);
  const [totalEvents, setTotalEvents] = useState(0);
  const [eventTypes, setEventTypes] = useState(new Set());
  const serialsKey = useMemo(() => serials?.join(',') ?? '', [serials]);

  useEffect(() => {
    if (eventsData && eventsData.length > 0) {
      const types = new Set(
        eventsData.map((event) =>
          event?.type === AiEventType.COMMON_EVENT_DETECTION
            ? event?.serviceId
            : event.type,
        ),
      );
      setEventTypes(types);
    }
  }, [eventsData]);

  useEffect(() => {
    if (!namespace) return;

    const fetchEvents = () => {
      const requestId = ++requestIdRef.current;
      setEventsData([]);
      setTotalEvents(0);
      getAllAiEvents(
        namespace,
        initialSelectedDate,
        serials,
        (newEvents) => {
          setEventsData((prev) => [...prev, ...newEvents]);
        },
        requestId,
        () => requestIdRef.current,
        (total) => {
          setTotalEvents((prev) => prev + total);
        },
      );
    };

    fetchEvents();
    // const intervalId = setInterval(fetchEvents, 30000);

    // return () => clearInterval(intervalId);
  }, [namespace, initialSelectedDate, serialsKey]);

  const events = useMemo(() => {
    if (!eventsData || eventsData.length === 0) return [];

    const timelineItems = eventsData
      .map((event) => {
        let timeInSeconds;
        let timeString;
        let timestampMs;
        if (event.timestamp) {
          if (typeof event.timestamp === 'number') {
            const m = moment(event.timestamp);
            const hours = m.hours();
            const minutes = m.minutes();
            const seconds = m.seconds();
            timeInSeconds = hours * 3600 + minutes * 60 + seconds;
            timeString = m.format('HH:mm:ss');
            timestampMs = event.timestamp;
          } else {
            const timeParts = event.timestamp.split(':');
            const hours = parseInt(timeParts[0]) || 0;
            const minutes = parseInt(timeParts[1]) || 0;
            const seconds = parseInt(timeParts[2]) || 0;
            timeInSeconds = hours * 3600 + minutes * 60 + seconds;
            timeString = event.timestamp;
            const baseDate = moment(initialSelectedDate).startOf('day');
            timestampMs = baseDate
              .clone()
              .add(timeInSeconds, 'seconds')
              .valueOf();
          }
        } else if (event.time) {
          timeInSeconds =
            typeof event.time === 'number'
              ? event.time
              : timeToSeconds(event.time);
          timeString =
            typeof event.time === 'string'
              ? event.time
              : formatTime(event.time);
          const baseDate = moment(initialSelectedDate).startOf('day');
          timestampMs = baseDate
            .clone()
            .add(timeInSeconds, 'seconds')
            .valueOf();
        } else {
          timeInSeconds = 0;
          timeString = '00:00:00';
          const baseDate = moment(initialSelectedDate).startOf('day');
          timestampMs = baseDate.valueOf();
        }
        return {
          ...event,
          timeInSeconds,
          timeString,
          timestampMs,
        };
      })
      .sort((a, b) => a.timestampMs - b.timestampMs);

    const marks = [];
    let currentGroup = [];
    for (let i = 0; i < timelineItems.length; i++) {
      const ev = timelineItems[i];
      if (currentGroup.length === 0) {
        currentGroup.push(ev);
      } else {
        const lastEv = currentGroup[currentGroup.length - 1];
        const isCommonEvent =
          ev.type === AiEventType.COMMON_EVENT_DETECTION &&
          lastEv.type === AiEventType.COMMON_EVENT_DETECTION;
        const hasSameGroupKey = isCommonEvent
          ? ev.serviceId === lastEv.serviceId && ev.serial === lastEv.serial
          : ev.type === lastEv.type && ev.serial === lastEv.serial;
        if (ev.timestampMs - lastEv.timestampMs <= 10000 && hasSameGroupKey) {
          currentGroup.push(ev);
        } else {
          marks.push([...currentGroup]);
          currentGroup = [ev];
        }
      }
    }
    if (currentGroup.length > 0) marks.push([...currentGroup]);

    const timelineMarks = marks.map((group, idx) => {
      const first = group[0];
      const duration =
        (group[group.length - 1].timestampMs - first.timestampMs) / 1000 || 10;
      const serviceId = first?.serviceId ?? null;
      return {
        id: `timeline-mark-${idx}-${first.type}-${serviceId ?? 'na'}`,
        time: first.timeInSeconds,
        timeString: first.timeString,
        duration: group?.length * 10 || 10,
        leftPct: (first.timeInSeconds / SECONDS_IN_DAY) * 100,
        widthPct: ((duration || 10) / SECONDS_IN_DAY) * 100,
        color:
          EVENT_COLORS[first.type] || EVENT_COLORS[AiEventType.DETECT_OBJECT],
        events: group,
        type: first.type,
        serviceId,
      };
    });

    const eventHistoryData = eventsData
      .map((event, index) => {
        let timeInSeconds;
        let timeString;
        if (event.timestamp) {
          if (typeof event.timestamp === 'number') {
            const m = moment(event.timestamp);
            const hours = m.hours();
            const minutes = m.minutes();
            const seconds = m.seconds();
            timeInSeconds = hours * 3600 + minutes * 60 + seconds;
            timeString = m.format('HH:mm:ss');
          } else {
            const timeParts = event.timestamp.split(':');
            const hours = parseInt(timeParts[0]) || 0;
            const minutes = parseInt(timeParts[1]) || 0;
            const seconds = parseInt(timeParts[2]) || 0;
            timeInSeconds = hours * 3600 + minutes * 60 + seconds;
            timeString = event.timestamp;
          }
        } else if (event.time) {
          timeInSeconds =
            typeof event.time === 'number'
              ? event.time
              : timeToSeconds(event.time);
          timeString =
            typeof event.time === 'string'
              ? event.time
              : formatTime(event.time);
        } else {
          timeInSeconds = 0;
          timeString = '00:00:00';
        }
        return {
          ...event,
          timeInSeconds,
          timeString,
          serviceId: event?.serviceId ?? null,
        };
      })
      .sort((a, b) => b.timestamp - a.timestamp);

    return {
      timelineMarks,
      eventHistoryData,
    };
  }, [eventsData, initialSelectedDate]);

  return {
    ...events,
    eventTypes,
    totalEvents,
  };
};
