import { useSocketQuery, useSocketRequest } from '@/socket/useSocketRequest';
import * as SERVICE from '@/constants/service.types';

import {
  parseResponseBody,
  prepareBody,
  requestSocketPromiseWithTimeout,
} from '@/socket/query';

export const useListUserGroups = ({ namespace }) => {
  return useSocketQuery(
    {
      namespace,
    },
    {
      appServiceType: SERVICE.LIST_GROUP_MEMBER,
    }
  );
};

export const listGroupByParentId = async (input) => {
  const res = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.LIST_GROUP_BY_PARENT_GROUP,
    body: prepareBody(input),
  });

  return parseResponseBody(res);
};

export const listUserGroupsByParentId = async (input) => {
  const res = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.LIST_GROUP_BY_PARENT_GROUP,
    body: prepareBody(input),
  });

  return parseResponseBody(res);
};

export const useListUserGroupByParentId = ({ namespace, parentId }) => {
  return useSocketQuery(
    {
      namespace,
      parentGroupId: parentId,
    },
    {
      appServiceType: SERVICE.LIST_GROUP_BY_PARENT_GROUP,
    }
  );
};

export const listUserGroupMembers = async (input) => {
  const res = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.LIST_ACCOUNT_GROUP_MEMBER,
    body: prepareBody(input),
  });

  return parseResponseBody(res);
};
export const useListUserGroupMembers = ({ namespace, groupId }) => {
  return useSocketQuery(
    {
      namespace,
      groupId,
    },
    {
      appServiceType: SERVICE.LIST_ACCOUNT_GROUP_MEMBER,
    }
  );
};

export const useAddUserGroup = () => {
  return useSocketRequest({
    appServiceType: SERVICE.ADD_GROUP_MEMBER,
  });
};

export const useUpdateUserGroup = () => {
  return useSocketRequest({
    appServiceType: SERVICE.UPDATE_GROUP_MEMBER,
  });
};

const removeMemberFromGroup = (input) => {
  // Prepare data for removing member from group
  return requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.DELETE_ACCOUNT_GROUP_MEMBER,
    body: prepareBody(input),
  }).then((res) => parseResponseBody(res));
};

export const useRemoveUserGroupMember = () => {
  return {
    mutate: removeMemberFromGroup,
  };
};

const checkRemoveGroup = async (input) => {
  const res = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.CHECK_REMOVE_GROUP,
    body: prepareBody(input),
  });

  return parseResponseBody(res);
};

const removeGroup = async (input) => {
  const res = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.DELETE_GROUP_MEMBER,
    body: prepareBody(input),
  });

  return parseResponseBody(res);
};

export const useCheckRemoveUserGroup = () => {
  return {
    mutate: checkRemoveGroup,
  };
};

export const useRemoveUserGroup = () => {
  return {
    mutate: removeGroup,
  };
};

export const useCheckAndRemoveUserGroup = () => {
  const { mutate: checkRemoveGroup } = useCheckRemoveUserGroup();
  const { mutate: removeGroup } = useRemoveUserGroup();

  const checkAndRemoveUserGroup = async (input) => {
    const subgroupsToRemove = await checkRemoveGroup(input);

    return Promise.all(
      subgroupsToRemove
        .map((subgroup) =>
          removeGroup({
            namespace: subgroup.namespace,
            groupId: subgroup.id,
          })
        )
        .concat(
          removeGroup({
            namespace: input.namespace,
            groupId: input.groupId,
          })
        )
    );
  };

  return {
    mutate: checkAndRemoveUserGroup,
  };
};

export const useGetAccountByNamespace = (input) => {
  return useSocketQuery(
    {
      namespace: input ? input.namespace : '',
    },
    {
      appServiceType: SERVICE.LIST_ACCOUNT_BY_NAMESPACE,
    }
  );
};

const addMemberToGroup = (input) => {
  return requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.ADD_ACCOUNT_GROUP_MEMBER,
    body: prepareBody(input),
  });
};

export const useAddMemberToGroup = () => {
  return {
    mutate: addMemberToGroup,
  };
};

export const useSearchUserGroupByName = () => {
  return useSocketRequest({
    appServiceType: SERVICE.SEARCH_GROUP_BY_NAME,
  });
};
