import { Table, Tag, Tooltip } from 'antd';
import React from 'react';
import colorsBlack from '@/assets/colors/dark';
import { EditIcon } from '@/icons/Edit';
import { TrashCanIcon } from '@/icons/TrashCan';
import { permissionStringToArray } from '../shared';

export const PermissionTable = ({
  total,
  page,
  pageSize,
  onPageChange,
  isLoading,
  footer,
  dataSource,
  onEditPermission,
  onRemovePermission,
}) => {
  return (
    <Table
      size="middle"
      dataSource={dataSource}
      loading={isLoading}
      scroll={{
        y: 'calc(100vh - 304px)',
      }}
      pagination={{
        current: page,
        pageSize,
        onChange: onPageChange,
        showSizeChanger: false,
        total,
      }}
      columns={[
        {
          key: 'groupName',
          title: 'Account group',
          render: (text, record) => {
            return record.groupName || '-';
          },
        },
        {
          key: 'account',
          title: 'Account',
          render: (text, record) => {
            if (record.groupId > 0) {
              return '-';
            }

            return (
              <Tooltip title={record.fullName || '-'}>
                {record.phoneNumber || '-'}
              </Tooltip>
            );
          },
        },
        {
          key: 'permission',
          title: 'Permission',
          render: (text, record) => {
            const permissions = permissionStringToArray(record.permission);

            return (
              <Tooltip title={permissions.join(', ')}>
                <div>
                  {permissions.map((permission) => {
                    return (
                      <Tag key={permission} color={colorsBlack.$brandHex}>
                        {permission}
                      </Tag>
                    );
                  })}
                </div>
              </Tooltip>
            );
          },
        },
        {
          key: 'action',
          title: 'Action',
          align: 'center',
          width: 140,
          render: (text, record) => {
            return (
              <div className="flex items-center gap-2">
                <div
                  className="text-brand cursor-pointer text-center flex items-center gap-1 justify-center hover:underline"
                  onClick={() => onEditPermission(record)}
                >
                  <EditIcon className="w-4 h-4" />
                  Edit
                </div>
                <div
                  className="text-error cursor-pointer text-center flex items-center gap-1 justify-center hover:underline"
                  onClick={() => onRemovePermission(record)}
                >
                  <TrashCanIcon className="w-4 h-4" />
                  Remove
                </div>
              </div>
            );
          },
        },
      ]}
      footer={footer}
    />
  );
};
