import { ROOT_GROUP_ID } from '@/constants/group';
import React, { useMemo, useRef, useState } from 'react';
import { CameraTable } from './CameraTable';
import './styles.scss';
import { useSocketQuery } from '@/socket/useSocketRequest';
import * as SERVICE from '@/constants/service.types';
import { PermissionTable } from './PermissionTable';
import { EditPermissionModal } from '../EditPermissionModal';
import {
  parseResponseBody,
  prepareBody,
  requestSocketPromiseWithTimeout,
} from '@/socket/query';
import { Modal } from 'antd';
import { openMessage } from '@/redux/actions';
import { NOTIFIES } from '@/constants/system.keys';
import { SharePermission } from '../SharePermission';
import { permissionArrayToString } from '../shared';

const sharePermission = async ({
  serials,
  accountId,
  groupId,
  deviceGroupId,
  namespace,
  permission,
  durationSecond,
}) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.SHARE_PERMISSION_USER,
    body: prepareBody({
      serials,
      accountId,
      groupId,
      deviceGroupId,
      namespace,
      permission,
      durationSecond,
    }),
  });
  console.log("SHARE_PERMISSION_USER: ", prepareBody({
    serials,
    accountId,
    groupId,
    deviceGroupId,
    namespace,
    permission,
    durationSecond,
  }));

  console.log('SHARE_PERMISSION_USER - response: ', response);

  return parseResponseBody(response);
};

const updateSharePermission = async ({
  serials,
  accountId,
  namespace,
  groupId,
  deviceGroupId,
  permission,
}) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.UPDATE_SHARE_PERMISSION_USER,
    body: prepareBody({
      serials,
      accountId,
      namespace,
      groupId,
      deviceGroupId,
      permission,
    }),
  });

  return parseResponseBody(response);
};

const deleteSharePermission = async ({
  serials,
  groupId,
  namespace,
  accountId,
  deviceGroupId,
}) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.UN_SHARE_PERMISSION_USER,
    body: prepareBody({
      serials,
      groupId,
      namespace,
      accountId,
      deviceGroupId,
    }),
  });

  return parseResponseBody(response);
};

const useListUserShareDevice = ({ namespace, serials }) => {
  return useSocketQuery(
    {
      namespace,
      serials,
    },
    {
      appServiceType: SERVICE.LIST_USER_SHARE_DEVICE,
      disabled: !serials || serials.length === 0,
    }
  );
};

const mergeUserShareData = (users, selectedCameras) => {
  if (!selectedCameras || selectedCameras.length === 0) return [];

  const usersWithCameraName = users.map((user) => {
    const camera = selectedCameras.find(
      (camera) => camera.serial === user.serial
    );

    return {
      ...user,
      key: `${user.accountId || -1}-${user.groupId || -1}-${user.serial}`,
      cameraName: camera?.name || '-',
    };
  });

  const individualUsers = usersWithCameraName.filter(
    (user) => user.groupId <= 0
  );

  const groupUsers = usersWithCameraName
    .filter((user) => user.groupId > 0)
    .map((user) => ({
      ...user,
      children: [],
    }));

  const groupWithSerialMap = new Map(
    groupUsers.map((user) => [`${user.groupId}-${user.serial}`, user])
  );

  groupUsers.forEach((user) => {
    const key = `${user.groupId}-${user.serial}`;

    groupWithSerialMap.get(key).children.push({
      ...user,
      // avoid circular reference
      children: undefined,
      isChild: true,
    });
  });

  const groupedIndividualUsers = Array.from(
    Object.values(
      individualUsers.reduce((acc, user) => {
        const accountId = user.accountId;

        if (!acc[accountId]) {
          acc[accountId] = [];
        }

        acc[accountId].push(user);

        return acc;
      }, {})
    )
  ).flat(1);

  return Array.from(groupWithSerialMap.values()).concat(groupedIndividualUsers);
};

export const Cameras = ({ namespace, accounts, isLoadingAccounts }) => {
  const [selectedGroupId, setSelectedGroupId] = useState(ROOT_GROUP_ID);
  const [selectedCameras, setSelectedCameras] = useState([]);
  const [sharePermissionActive, setSharePermissionActive] = useState(false);
  const [sharePermissionLoading, setSharePermissionLoading] = useState(false);

  const onSelectGroupId = (groupId) => {
    setSelectedGroupId(groupId);
    setSharePermissionActive(false);
    setSharePermissionLoading(false);
  };

  const onSelectCameras = (cameras) => {
    setSelectedCameras(cameras);
    setSharePermissionActive(false);
    setSharePermissionLoading(false);
  };

  const {
    data: userShareData,
    isLoading: isLoadingUserShareData,
    send: fetchUserShareData,
  } = useListUserShareDevice({
    namespace,
    serials: selectedCameras.map((camera) => camera.serial).join(';'),
  });

  const serialsRef = useRef(selectedCameras.map((camera) => camera.serial));
  serialsRef.current = selectedCameras.map((camera) => camera.serial);

  const refreshUserShareData = () => {
    fetchUserShareData({
      namespace,
      serials: serialsRef.current.join(';'),
    });
  };

  console.log('userShareData', userShareData);

  const mergedData = useMemo(() => {
    return mergeUserShareData(userShareData?.users || [], selectedCameras);
  }, [userShareData, selectedCameras]);

  const dataSource = useMemo(() => {
    if (!selectedCameras || selectedCameras.length === 0) return [];

    console.log('mergedData - share camera: ', mergedData);
    return mergedData;
  }, [mergedData, selectedCameras]);

  console.log('dataSource', dataSource);

  const onRemovePermission = (record) => {
    console.log('record', record);
    if (record?.deviceGroup) {
      Modal.confirm({
        title: 'Unable to remove permission',
        content: `This permission is inherited from camera group ${record.deviceGroup.name}`,
        cancelButtonProps: {
          style: {
            display: 'none',
          },
        },
        okText: 'OK',
      });

      return;
    }

    Modal.confirm({
      title: 'Remove permission',
      content: `Are you sure to remove permission of ${record.isChild
        ? `${record.fullName} in ${record.groupName}`
        : record.groupName || record.fullName
        }?`,
      onOk: async () => {
        console.log('BODY', {
          serials: record.serial,
          groupId: record.groupId || -1,
          namespace,
          accountId: record.accountId || -1,
          deviceGroupId: record.deviceGroupId || -1,
        });

        await deleteSharePermission({
          serials: record.serial,
          groupId: record.groupId || -1,
          namespace,
          accountId: record.accountId || -1,
          deviceGroupId: record.deviceGroupId || -1,
        });

        openMessage(NOTIFIES.SUCCESS, 'Remove permission successfully');

        if (serialsRef.current.includes(record.serial)) {
          refreshUserShareData();
        }
      },
    });
  };

  const [recordToEdit, setRecordToEdit] = useState(null);
  const [recordToEditLoading, setRecordToEditLoading] = useState(null);

  const onEditPermission = (record) => {
    console.log('record', record);
    if (record?.deviceGroup) {
      Modal.confirm({
        title: 'Unable to edit permission',
        content: `This permission is inherited from camera group ${record.deviceGroup.name}`,
        cancelButtonProps: {
          style: {
            display: 'none',
          },
        },
        okText: 'OK',
      });

      return;
    }

    setRecordToEdit(record);
  };

  const onSubmitSharePermission = (values) => {
    const onOk = () => {
      setSharePermissionLoading(true);
      sharePermission({
        accountId: values.accountId || -1,
        groupId: values.groupId || -1,
        deviceGroupId: values.deviceGroupId || -1,
        namespace,
        permission: permissionArrayToString(values.permission),
        durationSecond: values.duration === 0 ? -1 : values.duration * 86400,
        serials: selectedCameras.map((camera) => camera.serial).join(';'),
      })
        .then((res) => {
          openMessage(NOTIFIES.SUCCESS, 'Share permission successfully');
          refreshUserShareData();
        })
        .finally(() => {
          setSharePermissionActive(false);
          setSharePermissionLoading(false);
        });
    };

    Modal.confirm({
      title: 'Share permission',
      content: `Are you sure to share permission to this ${values.type === 'group' ? 'group' : 'member'
        }?`,
      onOk,
    });
  };

  const onSubmitEditPermission = (permission) => {
    setRecordToEditLoading(recordToEdit.key);
    console.log('BODY', {
      accountId: recordToEdit.accountId || -1,
      namespace,
      deviceGroupId: recordToEdit.deviceGroupId || -1,
      groupId: recordToEdit.groupId || -1,
      permission,
      serials: recordToEdit.serial,
    });

    updateSharePermission({
      accountId: recordToEdit.accountId || -1,
      namespace,
      deviceGroupId: recordToEdit.deviceGroupId || -1,
      groupId: recordToEdit.groupId || -1,
      permission,
      serials: recordToEdit.serial,
    }).then(
      () => {
        // remove if we just edited this record
        setRecordToEdit((prev) => {
          if (prev?.key === recordToEdit.key) {
            return null;
          }

          return prev;
        });

        // remove loading if we just edited this record
        setRecordToEditLoading((prev) => {
          if (prev === recordToEdit.key) {
            return null;
          }

          return prev;
        });
        refreshUserShareData();
        openMessage(NOTIFIES.SUCCESS, 'Update permission successfully');
      },
      (error) => {
        openMessage(NOTIFIES.ERROR, 'Error when update permission');
      }
    );
  };

  return (
    <div className="og2-cameras-component">
      <div className="og2-cameras-left">
        <CameraTable
          namespace={namespace}
          selectedGroupId={selectedGroupId}
          selectedSerials={selectedCameras.map((camera) => camera.serial)}
          onSelectCameras={onSelectCameras}
          onSelectGroupId={onSelectGroupId}
        />
      </div>
      <div className="og2-cameras-right">
        <PermissionTable
          isLoading={isLoadingUserShareData}
          dataSource={dataSource}
          onRemovePermission={onRemovePermission}
          onEditPermission={onEditPermission}
          footer={() => (
            <SharePermission
              namespace={namespace}
              active={sharePermissionActive}
              onActive={() => setSharePermissionActive(true)}
              onCancel={() => setSharePermissionActive(false)}
              onSubmit={onSubmitSharePermission}
              accounts={accounts}
              disabled={!selectedCameras || selectedCameras.length === 0}
              loadingAccounts={isLoadingAccounts}
              loading={sharePermissionLoading}
            />
          )}
        />

        {recordToEdit && (
          <EditPermissionModal
            defaultPermission={recordToEdit.permission}
            isLoading={recordToEditLoading === recordToEdit.key}
            name={
              recordToEdit.isChild
                ? `${recordToEdit.fullName} in ${recordToEdit.groupName}`
                : recordToEdit.groupName || recordToEdit.fullName
            }
            onSubmit={onSubmitEditPermission}
            onCancel={() => setRecordToEdit(null)}
          />
        )}
      </div>
    </div>
  );
};
