import { getPlaybackControls, getSelectedDate } from '@/redux/playback/reducer';
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { VIEW_STREAM_SERVICE_EXTEND } from '@/constants/system.keys';
import { usePlaybackContext } from '../../context';
import { computeQueryTime } from '../../utils';
import { startPlaybackCamera } from '@/hooks/socket/stream';
import { RTCCodecAdapter } from './adapter/rtc-codec';
import { HLSAdapter } from './adapter/hls';
import ReactPlayer from 'react-player';
import { Button, Modal, Spin, Tooltip } from 'antd';
import { LeftOutlined, RightOutlined } from '@ant-design/icons';
import * as SERVICE from '@/constants/service.types';
import { socketEmitEvent } from '@/redux/actions';
import { useInternalStream } from './use-internal-stream';
import { setPlaybackControls } from '@/redux/playback/action';
import { beeXLogger } from '@/helpers/logger';
import ResetIcon from '@/components/Player/icons/refresh.svg';
import {
  STEP_STATE,
  StreamConnectStep,
} from '@/components/Player/StreamConnectStep';
import { INACTIVE_PIVOT_TIME } from '../../use-playback-progress';
import { useTranslation } from 'react-i18next';

const ACCUMULATION_TIMEOUT = 2000;

const STREAM_STATE = {
  LOADING: 'loading',
  LOADED: 'loaded',
  INIT: 'init',
};

export const STREAM_MODE = {
  NORMAL: 'normal',
  TRANSCODE: 'transcode',
};

const INITIAL_STREAM_CONNECT_STATES = {
  1: STEP_STATE.PENDING,
  2: STEP_STATE.PENDING,
  3: STEP_STATE.PENDING,
  4: STEP_STATE.PENDING,
};

export const PlaybackPlayerLocal = ({
  camera,
  onReady,
  onFrame,
  onClick,
  isFocused,
  muted,
}) => {
  const dispatch = useDispatch();
  const [adapter, setAdapter] = useState();
  const [stream, setStream] = useState();
  const [output, setOutput] = useState(null);
  const videoRef = useRef(null);
  const playerRef = useRef(null);
  const selectedDate = useSelector(getSelectedDate);
  const {
    onPivotTimeChange,
    getPivotTime,
    setPivotTime,
    getCurrentTime,
    reportProgress,
    removeProgress,
    playbackRate,
    selectedEvent,
  } = usePlaybackContext();

  const fetchedAt = useRef(0);
  const localPivot = useRef(0);
  const fetchedQueryTime = useRef(0);
  const { isInternal, isLoading: isLoadingInternal } = useInternalStream({
    gatewaySerial: camera?.gatewaySerial,
  });
  const [streamState, setStreamState] = useState({
    state: STREAM_STATE.INIT,
    error: null,
  });
  const playbackControls = useSelector(getPlaybackControls);
  const [accumulatedRewind, setAccumulatedRewind] = useState(0);
  const [accumulatedForward, setAccumulatedForward] = useState(0);
  const rewindTimeoutRef = useRef(null);
  const forwardTimeoutRef = useRef(null);
  const currentTime = useMemo(() => getCurrentTime(), [getCurrentTime]);
  const prevTimeProgressRef = useRef(0);
  const activeSeekSessionRef = useRef(0);
  const streamSeekSessionRef = useRef(0);
  const outputSeekSessionRef = useRef(0);
  const retrySeekSessionRef = useRef(null);
  const hlsOutputTimeoutRef = useRef(null);
  const outputRetryTimeoutRef = useRef(null);

  const normalModeRetryRef = useRef({
    key: null,
    retried: false,
  });
  const [hasTranscodeRetry, setHasTranscodeRetry] = useState(false);
  const retryTimeValueRef = useRef(null);
  const hasTranscodeRetryRef = useRef(false);
  const transcodeTimeoutRef = useRef(false);
  const fetchStreamRef = useRef(null);
  const streamReceivedButPlaybackFailedRef = useRef(false);
  const [streamMode, setStreamMode] = useState(null);
  const streamModeRef = useRef(null);
  const [streamConnectMode, setStreamConnectMode] = useState(
    STREAM_MODE.NORMAL,
  );
  const [streamConnectStep, setStreamConnectStep] = useState(1);
  const [streamConnectStepStates, setStreamConnectStepStates] = useState(
    INITIAL_STREAM_CONNECT_STATES,
  );
  const [streamConnectError, setStreamConnectError] = useState(null);
  const [streamConnectErrorStep, setStreamConnectErrorStep] = useState(null);
  const hasPlaybackStartedRef = useRef(false);
  const [hasFetchedStream, setHasFetchedStream] = useState(false);

  const resetStreamConnectStatus = useCallback(() => {
    setStreamConnectError(null);
    setStreamConnectErrorStep(null);
  }, []);

  const getReadableError = useCallback((err, fallback) => {
    if (typeof err === 'string') {
      return err;
    }
    return err?.message || fallback;
  }, []);

  const getErrorKey = useCallback(
    (err, fallback) => {
      const readable = getReadableError(err, fallback);
      const errorCode =
        err?.code || err?.status || err?.type || err?.details?.type || '';
      return `${String(errorCode)}|${String(readable || fallback)}`
        .toLowerCase()
        .trim();
    },
    [getReadableError],
  );

  const isSingleRetryNormalError = useCallback((errorKey = '') => {
    return /(404|stream not found|network error|hls\s*error|hlserror)/i.test(
      errorKey,
    );
  }, []);

  const resetNormalModeRetry = useCallback(() => {
    normalModeRetryRef.current = {
      key: null,
      retried: false,
    };
  }, []);

  const isSeekSessionActive = useCallback((seekSessionId) => {
    return seekSessionId === activeSeekSessionRef.current;
  }, []);

  const startSeekSession = useCallback(() => {
    activeSeekSessionRef.current += 1;
    return activeSeekSessionRef.current;
  }, []);

  const clearPendingPlaybackTimeouts = useCallback(() => {
    if (hlsOutputTimeoutRef.current) {
      clearTimeout(hlsOutputTimeoutRef.current);
      hlsOutputTimeoutRef.current = null;
    }
    if (outputRetryTimeoutRef.current) {
      clearTimeout(outputRetryTimeoutRef.current);
      outputRetryTimeoutRef.current = null;
    }
  }, []);

  const setStreamConnectLoadingStep = useCallback((step) => {
    setStreamConnectStep(step);
    setStreamConnectStepStates({
      1: step > 1 ? STEP_STATE.DONE : STEP_STATE.LOADING,
      2:
        step > 2
          ? STEP_STATE.DONE
          : step === 2
            ? STEP_STATE.LOADING
            : STEP_STATE.PENDING,
      3:
        step > 3
          ? STEP_STATE.DONE
          : step === 3
            ? STEP_STATE.LOADING
            : STEP_STATE.PENDING,
      4: STEP_STATE.PENDING,
    });
  }, []);

  const resetPlaybackForSeek = useCallback(() => {
    clearPendingPlaybackTimeouts();
    hasPlaybackStartedRef.current = false;
    streamReceivedButPlaybackFailedRef.current = false;
    retryTimeValueRef.current = null;
    setHasTranscodeRetry(false);
    setOutput(null);
    setStream(null);
    setAdapter(null);
    setStreamConnectLoadingStep(1);
    resetStreamConnectStatus();
    setStreamState((prev) => ({
      ...prev,
      state: STREAM_STATE.LOADING,
      error: null,
    }));
  }, [
    clearPendingPlaybackTimeouts,
    resetStreamConnectStatus,
    setStreamConnectLoadingStep,
  ]);

  const setStreamConnectSuccess = useCallback(() => {
    hasPlaybackStartedRef.current = true;
    setStreamConnectStep(4);
    setStreamConnectStepStates({
      1: STEP_STATE.DONE,
      2: STEP_STATE.DONE,
      3: STEP_STATE.DONE,
      4: STEP_STATE.DONE,
    });
    resetNormalModeRetry();
    resetStreamConnectStatus();
  }, [resetStreamConnectStatus, resetNormalModeRetry]);

  const setStreamConnectFailedAtStep3 = useCallback((message) => {
    hasPlaybackStartedRef.current = false;
    setStreamConnectStep(3);
    setStreamConnectError(message);
    setStreamConnectErrorStep(3);
    setStreamConnectStepStates({
      1: STEP_STATE.DONE,
      2: STEP_STATE.DONE,
      3: STEP_STATE.FAILURE,
      4: STEP_STATE.PENDING,
    });
  }, []);

  const setStreamConnectFailedAtStep2 = useCallback((message) => {
    hasPlaybackStartedRef.current = false;
    setStreamConnectStep(2);
    setStreamConnectError(message);
    setStreamConnectErrorStep(2);
    setStreamConnectStepStates({
      1: STEP_STATE.DONE,
      2: STEP_STATE.FAILURE,
      3: STEP_STATE.PENDING,
      4: STEP_STATE.PENDING,
    });
  }, []);

  const queueTranscodeRetry = useCallback(
    (time, seekSessionId = activeSeekSessionRef.current) => {
      if (!isSeekSessionActive(seekSessionId) || transcodeTimeoutRef.current) {
        return;
      }
      clearPendingPlaybackTimeouts();
      hasTranscodeRetryRef.current = true;
      hasPlaybackStartedRef.current = false;
      retryTimeValueRef.current = time;
      retrySeekSessionRef.current = seekSessionId;
      setStream(null);
      setAdapter(null);
      setOutput(null);
      resetStreamConnectStatus();
      setStreamConnectLoadingStep(1);
      setStreamState((prev) => ({
        ...prev,
        state: STREAM_STATE.LOADING,
        error: null,
      }));
      setStreamMode(STREAM_MODE.TRANSCODE);
      setStreamConnectMode(STREAM_MODE.TRANSCODE);
      setHasTranscodeRetry(true);
    },
    [
      clearPendingPlaybackTimeouts,
      isSeekSessionActive,
      resetStreamConnectStatus,
      setStreamConnectLoadingStep,
    ],
  );

  const retryPlaybackByCurrentLink = useCallback(
    (currentOutput = null, seekSessionId = activeSeekSessionRef.current) => {
      if (!isSeekSessionActive(seekSessionId)) {
        return;
      }

      setStreamConnectLoadingStep(3);
      setStreamState((prev) => ({
        ...prev,
        state: STREAM_STATE.LOADING,
        error: null,
      }));

      if (typeof currentOutput === 'string') {
        setOutput(null);
        if (outputRetryTimeoutRef.current) {
          clearTimeout(outputRetryTimeoutRef.current);
        }
        outputRetryTimeoutRef.current = setTimeout(() => {
          if (!isSeekSessionActive(seekSessionId)) {
            return;
          }
          outputSeekSessionRef.current = seekSessionId;
          setOutput(currentOutput);
          outputRetryTimeoutRef.current = null;
        }, 250);
        return;
      }

      if (stream) {
        setOutput(null);
        setAdapter(null);
        setStream((prev) => (prev ? { ...prev } : prev));
        return;
      }

      queueTranscodeRetry(localPivot.current, seekSessionId);
    },
    [
      isSeekSessionActive,
      queueTranscodeRetry,
      setStreamConnectLoadingStep,
      stream,
    ],
  );

  const retryNormalOnceOrFallbackTranscode = useCallback(
    (
      err,
      time,
      fallback,
      retryFn,
      seekSessionId = activeSeekSessionRef.current,
    ) => {
      if (!isSeekSessionActive(seekSessionId)) {
        return false;
      }
      if (hasTranscodeRetryRef.current || transcodeTimeoutRef.current) {
        return false;
      }

      const errorKey = getErrorKey(err, fallback);
      const previousRetry = normalModeRetryRef.current;
      const shouldUseSingleRetryPolicy =
        previousRetry.key === errorKey ||
        isSingleRetryNormalError(errorKey) ||
        !previousRetry.retried;

      if (shouldUseSingleRetryPolicy && !previousRetry.retried) {
        normalModeRetryRef.current = {
          key: errorKey,
          retried: true,
        };

        if (typeof retryFn === 'function') {
          retryFn(seekSessionId);
        } else {
          setTimeout(() => {
            if (fetchStreamRef.current && isSeekSessionActive(seekSessionId)) {
              fetchStreamRef.current(time, false, null, true);
            }
          }, 0);
        }

        return true;
      }

      queueTranscodeRetry(time, seekSessionId);
      return true;
    },
    [
      getErrorKey,
      isSeekSessionActive,
      isSingleRetryNormalError,
      queueTranscodeRetry,
    ],
  );

  useEffect(() => {
    activeSeekSessionRef.current += 1;
    streamSeekSessionRef.current = 0;
    outputSeekSessionRef.current = 0;
    retrySeekSessionRef.current = null;
    clearPendingPlaybackTimeouts();
    setStream(null);
    setAdapter(null);
    setOutput(null);
    hasPlaybackStartedRef.current = false;
    setStreamConnectStep(1);
    setStreamConnectStepStates(INITIAL_STREAM_CONNECT_STATES);
    resetStreamConnectStatus();
    resetNormalModeRetry();
    setStreamMode(STREAM_MODE.NORMAL);
    setStreamConnectMode(STREAM_MODE.NORMAL);
    setStreamState({
      state: STREAM_STATE.INIT,
      error: null,
    });
    setPivotTime(INACTIVE_PIVOT_TIME, false);
    setHasFetchedStream(false);
  }, [
    clearPendingPlaybackTimeouts,
    selectedDate,
    setPivotTime,
    resetStreamConnectStatus,
    resetNormalModeRetry,
  ]);

  useEffect(() => {
    if (!isFocused) {
      return;
    }

    const currentControls =
      playbackControls && typeof playbackControls === 'object'
        ? playbackControls
        : {};

    if (currentControls?.streamMode === streamConnectMode) {
      return;
    }

    dispatch(
      setPlaybackControls({
        ...currentControls,
        streamMode: streamConnectMode,
      }),
    );
  }, [dispatch, isFocused, playbackControls, streamConnectMode]);

  const fetchStream = useCallback(
    (time, useTranscode = false, customSerial = null, isErrorRetry = false) => {
      const seekSessionId = startSeekSession();
      streamSeekSessionRef.current = 0;
      retrySeekSessionRef.current = null;
      setHasFetchedStream(true);
      resetPlaybackForSeek();

      if (!useTranscode && !isErrorRetry) {
        resetNormalModeRetry();
      }

      setStreamConnectMode(
        useTranscode ? STREAM_MODE.TRANSCODE : STREAM_MODE.NORMAL,
      );

      if (!useTranscode) {
        transcodeTimeoutRef.current = false;
        hasTranscodeRetryRef.current = false;
        setStreamMode(STREAM_MODE.NORMAL);
      } else if (transcodeTimeoutRef.current) {
        if (!isSeekSessionActive(seekSessionId)) {
          return;
        }
        setHasTranscodeRetry(false);
        setStreamConnectFailedAtStep3('[Transcode] Request timed out');
        setStreamState((prev) => ({
          ...prev,
          state: STREAM_STATE.LOADED,
          error: { message: 'Request timed out', code: 'TIMEOUT' },
        }));
        return;
      } else {
        setStreamMode(STREAM_MODE.TRANSCODE);
      }

      const fetchParams = {
        serial: customSerial || camera?.serial,
        namespace: camera?.namespace,
        queryTime: computeQueryTime(selectedDate, time),
        serviceId: VIEW_STREAM_SERVICE_EXTEND.normal,
        type: isInternal ? 'internal' : 'external',
      };

      if (useTranscode) {
        fetchParams.functions = 'transcode_h264';
        fetchParams.serviceId = 'external';
      }

      setStreamConnectLoadingStep(2);

      startPlaybackCamera(fetchParams)
        .then((res) => {
          if (!isSeekSessionActive(seekSessionId)) {
            return;
          }
          console.log(
            'RTSP Link: ',
            `rtsp://${res?.serial || res?.username}:${res?.streamToken}@${res?.wssHost}:${res?.rtspPort || '10554'}${res?.path || res?.sourcePath || `/${res?.source}`}`,
          );
          fetchedQueryTime.current = computeQueryTime(selectedDate, time);
          fetchedAt.current = Date.now();
          localPivot.current = time;
          streamSeekSessionRef.current = seekSessionId;
          setStream(res);
          streamReceivedButPlaybackFailedRef.current = false;
          setStreamMode(
            useTranscode ? STREAM_MODE.TRANSCODE : STREAM_MODE.NORMAL,
          );
        })
        .catch((err) => {
          if (!isSeekSessionActive(seekSessionId)) {
            return;
          }
          beeXLogger.error('🚀 ~ startPlaybackCamera ~ err:', err);
          const isTranscodeTimeout =
            useTranscode &&
            (err?.code === 'TIMEOUT' || err?.message === 'Request timed out');
          if (isTranscodeTimeout) {
            transcodeTimeoutRef.current = true;
            hasTranscodeRetryRef.current = true;
            retrySeekSessionRef.current = seekSessionId;
            setHasTranscodeRetry(false);
          }
          if (!useTranscode && !hasTranscodeRetryRef.current) {
            const handledByRetry = retryNormalOnceOrFallbackTranscode(
              err,
              time,
              'Failed to request playback stream',
              null,
              seekSessionId,
            );
            if (handledByRetry) {
              return;
            }
          } else {
            const errorMsg = getReadableError(
              err,
              'Failed to request playback stream',
            );
            setStreamConnectFailedAtStep2(`${errorMsg}`);
            setStreamMode(null);
            setStreamState((prev) => ({
              ...prev,
              state: STREAM_STATE.LOADED,
              error: err,
            }));
            if (!isTranscodeTimeout) {
              hasTranscodeRetryRef.current = false;
            }
          }
        });
    },
    [
      camera,
      selectedDate,
      isInternal,
      startSeekSession,
      resetPlaybackForSeek,
      isSeekSessionActive,
      retryNormalOnceOrFallbackTranscode,
      setStreamConnectLoadingStep,
      resetNormalModeRetry,
      setStreamConnectFailedAtStep2,
      setStreamConnectFailedAtStep3,
      getReadableError,
    ],
  );

  useEffect(() => {
    fetchStreamRef.current = fetchStream;
  }, [fetchStream]);

  useEffect(() => {
    streamModeRef.current = streamMode;
  }, [streamMode]);

  useEffect(() => {
    if (prevTimeProgressRef.current > 0) {
      reportProgress(camera?.serial, prevTimeProgressRef);
      localPivot.current = prevTimeProgressRef.current;
      prevTimeProgressRef.current = 0;
    }
  }, [camera, playbackRate, reportProgress]);

  useEffect(() => {
    return () => {
      activeSeekSessionRef.current += 1;
      streamSeekSessionRef.current = 0;
      outputSeekSessionRef.current = 0;
      retrySeekSessionRef.current = null;
      clearPendingPlaybackTimeouts();
      setStream(null);
      setAdapter(null);
      setOutput(null);
      setStreamMode(STREAM_MODE.NORMAL);
      fetchedQueryTime.current = 0;
      fetchedAt.current = 0;
      localPivot.current = 0;
      resetNormalModeRetry();
      hasTranscodeRetryRef.current = false;
      transcodeTimeoutRef.current = false;
      retryTimeValueRef.current = null;
      streamReceivedButPlaybackFailedRef.current = false;
    };
  }, [clearPendingPlaybackTimeouts, resetNormalModeRetry, currentTime]);

  useEffect(() => {
    if (
      isLoadingInternal ||
      (selectedEvent && selectedEvent?.serial !== camera?.serial)
    ) {
      return;
    }

    const unsub = onPivotTimeChange(fetchStream);

    if (getPivotTime() >= 0) {
      fetchStream(getCurrentTime());
    }

    return () => unsub();
  }, [
    isLoadingInternal,
    fetchStream,
    onPivotTimeChange,
    getPivotTime,
    getCurrentTime,
    selectedEvent,
    camera,
  ]);

  useEffect(() => {
    if (currentTime <= 0) {
      setStream(null);
    }
  }, [currentTime]);

  useEffect(() => {
    if (!stream) {
      return;
    }

    beeXLogger.debug('CREATE ADAPTER FOR STREAM');
    if (camera?.namespace === 'pharmacity.vn') {
      setAdapter(new RTCCodecAdapter());
      return;
    }
    if (stream?.protocol === 'webrtc') {
      setAdapter(new RTCCodecAdapter());
    } else {
      setAdapter(new HLSAdapter());
    }
  }, [camera, stream]);

  useEffect(() => {
    if (adapter && stream) {
      const seekSessionId = streamSeekSessionRef.current;
      if (!isSeekSessionActive(seekSessionId)) {
        return;
      }

      beeXLogger.debug('CONNECT ADAPTER FOR STREAM', stream);
      setStreamConnectLoadingStep(3);
      adapter.connect(
        {
          ...stream,
          streamMode,
          queryTime: computeQueryTime(selectedDate, localPivot.current),
        },
        { streamToken: stream.streamToken },
        (output, iceConnectionState) => {
          if (!isSeekSessionActive(seekSessionId)) {
            return;
          }

          beeXLogger.debug('STREAM OUTPUT RECEIVED', output);

          if (adapter instanceof HLSAdapter) {
            if (hlsOutputTimeoutRef.current) {
              clearTimeout(hlsOutputTimeoutRef.current);
            }
            hlsOutputTimeoutRef.current = setTimeout(() => {
              if (!isSeekSessionActive(seekSessionId)) {
                return;
              }
              beeXLogger.debug('🚀 ~ PlaybackPlayerLocal ~ output:', output);
              outputSeekSessionRef.current = seekSessionId;
              setStreamConnectLoadingStep(3);
              setOutput(output);
              hlsOutputTimeoutRef.current = null;
            }, 1500);
          } else {
            if (!output) {
              streamReceivedButPlaybackFailedRef.current = true;
              const handledByRetry = retryNormalOnceOrFallbackTranscode(
                new Error('No stream output'),
                localPivot.current,
                'No stream output',
                (sessionId) => retryPlaybackByCurrentLink(null, sessionId),
                seekSessionId,
              );
              if (!handledByRetry) {
                setStreamConnectFailedAtStep3(`No stream output`);
                setStreamMode(STREAM_MODE.NORMAL);
                setStreamState((prev) => ({
                  ...prev,
                  state: STREAM_STATE.LOADED,
                  error: -1,
                }));
              }
            } else {
              outputSeekSessionRef.current = seekSessionId;
              setStreamConnectLoadingStep(3);
              setOutput(output);
              setStreamMode(STREAM_MODE.NORMAL);
              setStreamState({
                state: STREAM_STATE.LOADED,
                error: null,
              });
              hasTranscodeRetryRef.current = false;
            }
          }
        },
        (err) => {
          if (!isSeekSessionActive(seekSessionId)) {
            return;
          }

          beeXLogger.error('CONNECT PLAYBACK LOCAL ERROR: ', err);
          streamReceivedButPlaybackFailedRef.current = true;
          const handledByRetry = retryNormalOnceOrFallbackTranscode(
            err,
            localPivot.current,
            'Client failed to connect stream',
            (sessionId) => retryPlaybackByCurrentLink(null, sessionId),
            seekSessionId,
          );
          if (!handledByRetry) {
            const errorMsg = getReadableError(
              err,
              'Client failed to connect stream',
            );
            setStreamConnectFailedAtStep3(`${errorMsg}`);
            setStreamMode(STREAM_MODE.NORMAL);
            setStreamState((prev) => ({
              ...prev,
              state: STREAM_STATE.LOADED,
              error: -1,
            }));
          }
        },
        (iceConnectionState) => {
          if (!isSeekSessionActive(seekSessionId)) {
            return;
          }

          if (
            iceConnectionState === 'checking' ||
            iceConnectionState === 'disconnected'
          ) {
            setStreamState((prev) => ({
              ...prev,
              state: STREAM_STATE.LOADING,
              error: null,
            }));
          }
        },
      );

      return () => {
        clearPendingPlaybackTimeouts();
        adapter.destroy();
      };
    }
  }, [
    adapter,
    clearPendingPlaybackTimeouts,
    isSeekSessionActive,
    stream,
    streamMode,
    retryPlaybackByCurrentLink,
    retryNormalOnceOrFallbackTranscode,
    setStreamConnectLoadingStep,
    setStreamConnectFailedAtStep3,
    getReadableError,
    selectedDate,
  ]);

  useEffect(() => {
    if (hasTranscodeRetry) {
      if (transcodeTimeoutRef.current) {
        setHasTranscodeRetry(false);
        return;
      }
      if (retryTimeValueRef.current !== null) {
        if (
          fetchStreamRef.current &&
          isSeekSessionActive(retrySeekSessionRef.current)
        ) {
          fetchStreamRef.current(retryTimeValueRef.current, true);
          setHasTranscodeRetry(false);
        } else {
          setHasTranscodeRetry(false);
        }
      }
    }
  }, [hasTranscodeRetry, isSeekSessionActive]);

  useEffect(() => {
    if (output instanceof MediaStream && videoRef.current) {
      videoRef.current.srcObject = output;
    }
  }, [output]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video || !(output instanceof MediaStream)) return;
    video.srcObject = output;

    video.muted = true;
    video.playsInline = true;
    video.autoplay = true;

    const p = video.play();
    if (p instanceof Promise) {
      p.catch((err) => {
        //
      });
    }
  }, [output]);

  useEffect(() => {
    const intervalId = setInterval(() => {
      const dataTimeRequest = new Date().getTime();
      const dataBody = {
        serial: camera?.serial,
        namespace: camera?.namespace,
        control: null,
      };
      if (stream?.supportGateways) {
        dataBody.supportGateways = stream.supportGateways;
      }

      let dataObj = {
        appServiceType: SERVICE.PING_PLAYBACK_CAMERA,
        requestId: dataTimeRequest,
        body: JSON.stringify(dataBody),
      };
      dispatch(socketEmitEvent(dataObj));
    }, 10000);

    return () => clearInterval(intervalId);
  }, [camera, stream, dispatch]);

  useEffect(() => {
    if (!playbackControls) return;

    if (playbackControls.rewind && playbackControls.rewind > 0) {
      setAccumulatedRewind((prev) => prev + playbackControls.rewind);

      if (rewindTimeoutRef.current) {
        clearTimeout(rewindTimeoutRef.current);
      }

      rewindTimeoutRef.current = setTimeout(() => {
        setAccumulatedRewind(0);
        rewindTimeoutRef.current = null;
      }, ACCUMULATION_TIMEOUT);
    }

    if (playbackControls.forward && playbackControls.forward > 0) {
      setAccumulatedForward((prev) => prev + playbackControls.forward);

      if (forwardTimeoutRef.current) {
        clearTimeout(forwardTimeoutRef.current);
      }

      forwardTimeoutRef.current = setTimeout(() => {
        setAccumulatedForward(0);
        forwardTimeoutRef.current = null;
      }, ACCUMULATION_TIMEOUT);
    }
  }, [playbackControls]);

  useEffect(() => {
    if (!playbackControls) return;

    const internalPlayer = videoRef.current;
    const control = {};
    let shouldResetForward = false;
    let shouldResetRewind = false;

    if (playbackControls.forward) {
      control.goTo = Math.abs(playbackControls.forward);
      shouldResetForward = true;
    }

    if (playbackControls.rewind) {
      control.goTo = Math.abs(playbackControls.rewind) * -1;
      shouldResetRewind = true;
    }

    if (playbackControls?.direction) {
      control.speed = Number(
        (playbackControls.direction === 'forward'
          ? playbackRate
          : playbackRate * -1
        ).toFixed(1),
      );
    }

    if (playbackControls?.state === 'pause') {
      if (
        typeof output === 'string' &&
        internalPlayer &&
        typeof internalPlayer.pause === 'function'
      ) {
        internalPlayer.pause();
      }
      control.play = 0;
    }

    if (playbackControls?.state === 'play') {
      if (
        typeof output === 'string' &&
        internalPlayer &&
        typeof internalPlayer.play === 'function'
      ) {
        internalPlayer.play();
      }
      control.play = 1;
    }

    if (!Object.keys(control).length) return;

    const dataBody = {
      serial: camera?.serial,
      namespace: camera?.namespace,
      control: JSON.stringify(control),
    };
    if (stream?.supportGateways) {
      dataBody.supportGateways = stream.supportGateways;
    }
    dispatch(
      socketEmitEvent({
        appServiceType: SERVICE.PING_PLAYBACK_CAMERA,
        requestId: Date.now(),
        body: JSON.stringify(dataBody),
      }),
    );

    if (shouldResetForward || shouldResetRewind) {
      dispatch(
        setPlaybackControls({
          ...playbackControls,
          forward: shouldResetForward ? null : playbackControls.forward,
          rewind: shouldResetRewind ? null : playbackControls.rewind,
        }),
      );
    }
  }, [camera, dispatch, output, playbackControls, playbackRate, stream]);

  const playbackControlsRef = useRef(playbackControls);

  useEffect(() => {
    playbackControlsRef.current = playbackControls;
  }, [playbackControls]);

  const handleChangePlaybackControls = useCallback(
    (key, value) => {
      const prevControls = playbackControlsRef.current || {};
      if (prevControls?.[key] === value) return;
      dispatch(
        setPlaybackControls({
          ...prevControls,
          [key]: value,
        }),
      );
    },
    [dispatch],
  );

  const handleReloadPlayback = useCallback(() => {
    handleChangePlaybackControls('state', 'play');
    fetchStream(getCurrentTime());
  }, [getCurrentTime, fetchStream, handleChangePlaybackControls]);

  useEffect(() => {
    if (!!streamState?.error && streamState?.state === STREAM_STATE.LOADED) {
      handleChangePlaybackControls('state', 'reload');
    } else {
      if (streamState?.state === 'loading') {
        handleChangePlaybackControls('state', 'loading');
      } else if (streamState?.state === STREAM_STATE.LOADED) {
        handleChangePlaybackControls('state', 'play');
      }
    }
  }, [handleChangePlaybackControls, streamState]);

  useEffect(() => {
    if (playbackControls?.state === 'triggerReload') {
      handleReloadPlayback();
    }
  }, [playbackControls, handleReloadPlayback]);

  useEffect(() => {
    if (typeof output === 'object') {
      if (videoRef.current) {
        videoRef.current.muted = muted;
        videoRef.current.volume = muted ? 0 : 1;
      }
    } else {
      if (
        playerRef.current &&
        typeof playerRef.current.getInternalPlayer === 'function' &&
        playerRef.current.getInternalPlayer()
      ) {
        playerRef.current.getInternalPlayer().muted = muted;
        playerRef.current.getInternalPlayer().volume = muted ? 0 : 1;
      }
    }
  }, [muted, output]);

  useEffect(() => {
    if (selectedEvent && selectedEvent?.serial === camera?.serial) {
      fetchStream(selectedEvent?.timeInSeconds, false, selectedEvent?.serial);
    }
  }, [fetchStream, selectedEvent, camera]);

  return (
    <div onClick={onClick} className="playback-player">
      <div className="flex justify-between p-2">
        <p className="playback-player-name m-0 overflow-hidden text-ellipsis whitespace-nowrap px-1">
          {camera?.name}
        </p>
        <div className="flex items-center gap-1 playback-player-info">
          {getPivotTime() >= 0 && hasFetchedStream && (
            <StreamConnectStep
              step={streamConnectStep}
              currentStep={streamConnectStep}
              stepStates={streamConnectStepStates}
              failedStep={streamConnectErrorStep}
              error={streamConnectError}
              wsHost={stream?.wsHost}
              protocol={stream?.protocol}
              isPlayback={true}
              isTranscode={streamConnectMode === STREAM_MODE.TRANSCODE}
              isSuccess={hasPlaybackStartedRef.current}
              placement="bottomLeft"
            />
          )}
        </div>
      </div>
      <Spin
        spinning={streamState?.state === 'loading'}
        className="w-full h-full"
      >
        <div className="relative" style={{ width: '100%', height: '100%' }}>
          {
            <>
              {accumulatedRewind > 0 && (
                <div
                  className="absolute top-1/2 left-2"
                  style={{
                    transition: 'opacity 0.25s ease',
                    zIndex: 10000,
                    transform: 'translateY(-50%)',
                    backgroundColor: 'rgba(0, 0, 0, 0.7)',
                    padding: '8px 12px',
                    borderRadius: '4px',
                    color: 'white',
                    fontSize: '16px',
                    fontWeight: 'bold',
                  }}
                >
                  <LeftOutlined /> -{accumulatedRewind}s
                </div>
              )}
              {accumulatedForward > 0 && (
                <div
                  className="absolute top-1/2 right-2"
                  style={{
                    transition: 'opacity 0.25s ease',
                    zIndex: 10000,
                    transform: 'translateY(-50%)',
                    backgroundColor: 'rgba(0, 0, 0, 0.7)',
                    padding: '8px 12px',
                    borderRadius: '4px',
                    color: 'white',
                    fontSize: '16px',
                    fontWeight: 'bold',
                  }}
                >
                  +{accumulatedForward}s <RightOutlined />
                </div>
              )}
            </>
          }

          <div className="absolute inset-0 w-full h-full">
            {output && typeof output === 'string' && (
              <ReactPlayer
                key={`hls-${outputSeekSessionRef.current}`}
                ref={playerRef}
                pip={false}
                width="100%"
                height="100%"
                url={output}
                playing={true}
                onError={(error, value) => {
                  const outputSeekSessionId = outputSeekSessionRef.current;
                  if (!isSeekSessionActive(outputSeekSessionId)) {
                    return;
                  }

                  beeXLogger.error('onError - ReactPlayer: ', error, value);
                  if (error && !value.fatal) {
                    return;
                  }
                  streamReceivedButPlaybackFailedRef.current = true;
                  const handledByRetry = retryNormalOnceOrFallbackTranscode(
                    error,
                    localPivot.current,
                    'Failed to view playback stream',
                    (sessionId) =>
                      retryPlaybackByCurrentLink(output, sessionId),
                    outputSeekSessionId,
                  );
                  if (handledByRetry) {
                    setStreamState((prev) => ({
                      ...prev,
                      state: STREAM_STATE.LOADING,
                      error: null,
                    }));
                  } else {
                    const errorMsg = getReadableError(
                      error,
                      'Failed to view playback stream',
                    );
                    setStreamConnectFailedAtStep3(`${errorMsg}`);
                    setStreamState((prev) => ({
                      ...prev,
                      state: STREAM_STATE.LOADED,
                      error: error || -1,
                    }));
                  }

                  removeProgress(camera?.serial);
                  setOutput(null);
                }}
                onPause={() => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  removeProgress(camera?.serial);
                }}
                config={{
                  file: {
                    attributes: {
                      crossOrigin: 'anonymous',
                      disablePictureInPicture: true,
                      controlsList: 'nodownload',
                    },
                    forceHLS: true,
                    hlsOptions: {
                      enableWorker: true,
                      maxBufferLength: 30,
                      manifestLoadingMaxRetry: 10,
                      levelLoadingMaxRetry: 10,
                      maxMaxBufferLength: 40,
                      maxBufferSize: 60 * 1000 * 1000,
                      highBufferWatchdogPeriod: 4,
                      nudgeOffset: 0.2,
                      nudgeMaxRetry: 5,
                      manifestLoadingRetryDelay: 500,
                      levelLoadingRetryDelay: 500,
                      fragLoadingRetryDelay: 500,
                      fragLoadingMaxRetry: 6,
                      lowLatencyMode: false,
                    },
                  },
                }}
                onReady={() => {
                  if (onReady && playerRef.current) {
                    onReady(playerRef.current.getInternalPlayer());
                  }
                }}
                onProgress={(prop) => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  if (streamState?.state === 'loading') {
                    setStreamState((prev) => ({
                      ...prev,
                      state: STREAM_STATE.LOADED,
                      error: null,
                    }));
                  }
                  if (onFrame && playerRef.current) {
                    onFrame(playerRef.current.getInternalPlayer());
                  }
                  reportProgress(
                    camera?.serial,
                    prop.playedSeconds + localPivot.current,
                  );
                }}
                onStart={() => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  beeXLogger.debug('START HLS PLAYBACK');
                  setStreamConnectSuccess();
                  hasTranscodeRetryRef.current = false;
                  if (streamState?.state === STREAM_STATE.LOADING) {
                    setStreamState({
                      state: STREAM_STATE.LOADED,
                      error: null,
                    });
                  }
                }}
                progressInterval={isFocused ? 1000 / 30 : 1000 / 10}
              />
            )}
            {output && typeof output === 'object' && (
              <video
                key={`webrtc-${outputSeekSessionRef.current}`}
                ref={videoRef}
                poster={camera?.thumbnail}
                style={{
                  width: '100%',
                  height: '100%',
                }}
                autoPlay={true}
                preload="metadata"
                onPlay={() => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  if (onReady && videoRef.current) {
                    onReady(videoRef.current);
                  }
                }}
                onTimeUpdate={(e) => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  if (videoRef.current) {
                    onFrame(videoRef.current);
                    const msPassed =
                      localPivot.current +
                      ((Date.now() - fetchedAt.current) *
                        (Number(playbackRate) || 1)) /
                        1000;
                    prevTimeProgressRef.current = msPassed;
                    reportProgress(camera?.serial, msPassed);
                  }
                }}
                onPlaying={() => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  beeXLogger.debug('MEDIA STREAM PLAYING');
                  setStreamConnectSuccess();
                  setStreamState((prev) => ({
                    ...prev,
                    state: STREAM_STATE.LOADED,
                    error: null,
                  }));
                }}
                onWaiting={() => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  beeXLogger.debug('MEDIA STREAM WAITING');
                  if (!streamConnectError) {
                    setStreamConnectLoadingStep(3);
                  }
                  if (streamState?.state !== 'loading') {
                    setStreamState((prev) => ({
                      ...prev,
                      state: STREAM_STATE.LOADING,
                      error: null,
                    }));
                  }
                }}
                onStalled={() => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  beeXLogger.debug('MEDIA STREAM STALLED');
                  if (!streamConnectError) {
                    setStreamConnectLoadingStep(3);
                  }
                  if (streamState?.state !== 'loading') {
                    setStreamState((prev) => ({
                      ...prev,
                      state: STREAM_STATE.LOADING,
                      error: null,
                    }));
                  }
                }}
                onError={(error) => {
                  const outputSeekSessionId = outputSeekSessionRef.current;
                  if (!isSeekSessionActive(outputSeekSessionId)) {
                    return;
                  }

                  beeXLogger.error('onError - video - webRtc: ', error);
                  const handledByRetry = retryNormalOnceOrFallbackTranscode(
                    error,
                    localPivot.current,
                    'Failed to view playback stream',
                    (sessionId) => retryPlaybackByCurrentLink(null, sessionId),
                    outputSeekSessionId,
                  );

                  if (handledByRetry) {
                    setStreamState((prev) => ({
                      ...prev,
                      state: STREAM_STATE.LOADING,
                      error: null,
                    }));
                  } else {
                    const errorMsg = getReadableError(
                      error,
                      'Failed to view playback stream',
                    );
                    setStreamConnectFailedAtStep3(`${errorMsg}`);
                    setStreamState((prev) => ({
                      ...prev,
                      state: STREAM_STATE.LOADED,
                      error: error || -1,
                    }));
                  }

                  removeProgress(camera?.serial);
                }}
                onPause={() => {
                  if (!isSeekSessionActive(outputSeekSessionRef.current)) {
                    return;
                  }
                  removeProgress(camera?.serial);
                }}
                muted={false}
              />
            )}
            {!output && (
              <img
                className="h-full w-full object-contain"
                src={camera?.thumbnail}
                alt=""
              />
            )}
            {!!streamState?.error &&
              streamState?.state === STREAM_STATE.LOADED && (
                <div
                  style={{ zIndex: 2 }}
                  className="error-text absolute inset-0 flex items-center justify-center bg-gray-900 flex-col gap-1"
                >
                  <Tooltip title={'Reload'}>
                    <img
                      src={ResetIcon}
                      alt=""
                      width={48}
                      height={48}
                      className="cursor-pointer"
                      onClick={handleReloadPlayback}
                    />
                  </Tooltip>
                  <p className="px-2 text-center text-base font-bold text-white">
                    Stream not found
                  </p>
                </div>
              )}
          </div>
        </div>
      </Spin>
    </div>
  );
};

