import { getStateDownloadPlaybackOnCloud } from "@/hooks/socket/playback";

class CompressManager {
  constructor() {
    this.compresses = new Map();
    this.intervals = new Map();
    this.restoreFromStorage();
  }

  restoreFromStorage() {
    try {
      const saved = localStorage.getItem('compress_manager_state');
      if (saved) {
        const compresses = JSON.parse(saved);
        compresses.forEach(compress => {
          if (compress.status === 'processing') {
            this.compresses.set(compress.uuid, compress);
            this.startDownload(compress);
          }
        });
      }
    } catch (error) {
      console.error('Failed to restore compresses:', error);
    }
  }

  saveToStorage() {
    try {
      const compresses = this.getAllCompress();
      localStorage.setItem('compress_manager_state', JSON.stringify(compresses));
    } catch (error) {
      console.error('Failed to save compresses:', error);
    }
  }

  startDownload(compressInfo, callbacks = {}) {
    const { uuid, serial, namespace, resourceCloudId } = compressInfo;

    if (this.compresses.has(uuid)) {
      console.log('Compress already exists:', uuid);
      return;
    }

    this.compresses.set(uuid, {
      ...compressInfo,
      status: 'processing',
      progress: 0,
      startTime: Date.now()
    });

    const intervalId = setInterval(async () => {
      try {
        const res = await getStateDownloadPlaybackOnCloud({
          uuid,
          serial,
          namespace,
          resourceCloudId: resourceCloudId || -1
        });

        const currentCompress = this.compresses.get(uuid);
        if (!currentCompress) {
          this.stopCompress(uuid);
          return;
        }

        this.compresses.set(uuid, {
          ...currentCompress,
          ...res,
          compressProgress: res.progress || currentCompress.compressProgress,
        });

        if (callbacks.onProgress) {
          callbacks.onProgress(uuid, this.compresses.get(uuid));
        }

        if (res.status === 'completed' && res.downloadUrl) {
          this.stopCompress(uuid);

          if (callbacks.onComplete) {
            callbacks.onComplete(uuid, res);
          }
        }

        if (res.status === 'error') {
          this.stopCompress(uuid);

          if (callbacks.onError) {
            callbacks.onError(uuid, res);
          }
        }
      } catch (error) {
        console.error('Compress error:', uuid, error);
      }
    }, 1000);

    this.intervals.set(uuid, intervalId);
  }

  stopCompress(uuid) {
    const intervalId = this.intervals.get(uuid);
    if (intervalId) {
      clearInterval(intervalId);
      this.intervals.delete(uuid);
    }
  }

  getCompress(uuid) {
    return this.compresses.get(uuid);
  }

  getAllCompress() {
    return Array.from(this.compresses.values());
  }

  getActiveCompresses() {
    return this.getAllCompress().filter(
      d => d.status === 'processing' || d.status === 'waiting'
    );
  }

  removeCompress(uuid) {
    this.stopCompress(uuid);
    this.compresses.delete(uuid);
  }

  clearCompleted() {
    this.getAllCompress().forEach(download => {
      if (download.status === 'completed' || download.status === 'error') {
        this.removeCompress(download.uuid);
      }
    });
  }
}

export const compressManager = new CompressManager();