const { Sider } = Layout;
const { Option } = Select;

const sortByName = (a, b) => {
  if (a?.name < b?.name) {
    return -1;
  }

  if (a?.name > b?.name) {
    return 1;
  }

  return 0;
};

const paginate = (data, page, size) => {
  return data.slice((page - 1) * size, page * size);
};

const makeRecentItemKey = (userId, namespace) => {
  return `recent-live-items-${userId}-${namespace}`;
};

const getLocalRecentItems = (userId, namespace) => {
  try {
    return JSON.parse(
      localStorage.getItem(makeRecentItemKey(userId, namespace)) || '[]',
    );
  } catch (error) {
    return [];
  }
};

const setLocalRecentItems = (userId, namespace, items) => {
  // console.log('local-items', items);
  localStorage.setItem(
    makeRecentItemKey(userId, namespace),
    JSON.stringify(items),
  );
};

const mergeCameras = (camToDisplay, alertCams) => {
  const result = [];

  camToDisplay.forEach((cam, index) => {
    if (alertCams[index]) {
      result[index] = alertCams[index];
    } else {
      result[index] = cam;
    }
  });

  alertCams.forEach((cam, index) => {
    if (!result[index]) {
      result[index] = cam;
    }
  });

  return result;
};

export const VIEW_MODE = {
  FOCUS: 6,
  GRID_2X2: 4,
  GRID_3X3: 9,
  GRID_4X4: 16,
  GRID_5X5: 25,
  GRID_6X6: 36,
};

const LivePage = () => {
  const {
    isAuth,
    userId,
    gatewayStates,
    cameraStates,
    namespace,
    dataUser,
    sipAccount,
    dialPad,
    isShowCritical,
    detectionAlerts,
    cameras,
    enabledSmartMode,
    listDeviceByGroupId,
    deviceContactInfo,
  } = useSelector((state) => state);
  const history = useHistory();
  const { t } = useTranslation();
  const dispatch = useDispatch();

  const isChildWindow = isTauriLiveWindow();
  const [isControlMode, setIsControlMode] = useState(false);

  const queryParams = useMemo(() => {
    const searchString = history.location.search || window.location.hash.split('?')[1] || '';
    return new URLSearchParams(searchString);
  }, [history.location.search, history.location.hash]);
  const currentGroupIdRaw = queryParams.get('groupId');
  const currentGroupId = currentGroupIdRaw && !isNaN(currentGroupIdRaw) ? Number(currentGroupIdRaw) : currentGroupIdRaw;
  const currentWindowId = queryParams.get('windowId');
  const currentGroupName = queryParams.get('groupName') ? decodeURIComponent(queryParams.get('groupName')) : 'Live';
  const [isViewAll, setIsViewAll] = useState(() => {
    const playParam = queryParams.get('autoPlay');
    if (playParam) {
      return playParam === 'on';
    }
    return localStorage.getItem('auto_play') === 'on';
  });
  const [isFullscreen, setFullScreen] = useState(false);
  const [modalEnableSmartModeVisible, setModalEnableSmartModeVisible] =
    useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const showModalEnableSmartMode = useRef(null);
  const [isFocusMode, setIsFocusMode] = useState(() => {
    const sizeParam = queryParams.get('gridSize');
    const size = sizeParam ? Number(sizeParam) : 6;
    return size === 6;
  });

  const REDUCE_DIMENSIONS = 5;
  const [selectedGroup, setSelectedGroup] = useState(() => {
    if (isChildWindow && currentGroupId) {
      return { id: currentGroupId, name: currentGroupName };
    }
    return {
      id: RECENT_GROUP_ID,
      name: 'Pinned',
    };
  });

  const selectedGroupId = selectedGroup?.id;

  const requestIdRef = useRef(null);
  const [recentItems, setRecentItems] = useState([]);
  const [forcePlay, setForcePlay] = useState({});
  const [forceMute, setForceMute] = useState({});
  const [activeDewarpCamera, setActiveDewarpCamera] = useState(null);
  const [fullscreenCameraSerial, setFullscreenCameraSerial] = useState(null);
  const [pendingPage, setPendingPage] = useState(null);
  const [searchCamera, setSearchCamera] = useState(null);

  const handleDewarpModeChange = useCallback(
    (serial, isActive) => {
      if (isActive) {
        setActiveDewarpCamera(serial);

        setForcePlay((prev) => {
          const newState = {};
          Object.keys(prev).forEach((key) => {
            if (key !== serial) {
              newState[key] = false;
            } else {
              newState[key] = true;
            }
          });
          return newState;
        });
      } else {
        setActiveDewarpCamera(null);
      }
    },
    [setForcePlay],
  );

  const recentCamerasRaw = useMemo(() => {
    return recentItems
      .filter((item) => item.type === 'camera')
      .map((item) => item.data);
  }, [recentItems]);

  const { cameras: recentCameras, loading } = useRecentCameras({
    cameras: recentCamerasRaw,
    namespace,
    enabled: selectedGroupId === RECENT_GROUP_ID,
  });

  const finalLoading = isLoading || loading;

  useEffect(() => {
    setRecentItems(getLocalRecentItems(userId, namespace));
  }, [userId, namespace]);

  useEffect(() => {
    // console.log('recentItems', recentItems);
    // console.log('local-items', getLocalRecentItems(userId, namespace));
    if (!userId || !namespace) {
      return;
    }

    setLocalRecentItems(userId, namespace, recentItems);
  }, [recentItems, userId, namespace]);

  const [pagination, setPagination] = useState(() => {
    const sizeParam = queryParams.get('gridSize');
    const size = sizeParam ? Number(sizeParam) : 6;
    let grid = [3, 3];
    let quality = ZOOM_STATE.THREE;
    if (size === 4) { grid = [2, 2]; quality = ZOOM_STATE.THREE; }
    else if (size === 9) { grid = [3, 3]; quality = ZOOM_STATE.THREE; }
    else if (size === 16) { grid = [4, 4]; quality = ZOOM_STATE.TWO; }
    else if (size === 25) { grid = [5, 5]; quality = ZOOM_STATE.ONE; }
    else if (size === 36) { grid = [6, 6]; quality = ZOOM_STATE.ONE; }
    return {
      size,
      page: 1,
      quality,
      grid,
    };
  });
  const [prevPagination, setPrevPagination] = useState({
    size: 6,
    page: 1,
    quality: ZOOM_STATE.THREE,
    grid: [3, 3],
  });
  const [selectCamera, setSelectCamera] = useState();
  const [customCamera, setCustomCamera] = useState();
  const [autoSwitchPageSeconds, setAutoSwitchPageSeconds] = useState(() => {
    const switchParam = queryParams.get('autoSwitch');
    return switchParam ? Number(switchParam) : 0;
  });

  // Store latest child window states in a mutable Ref so the sync effect doesn't need to re-run
  const childStateRef = useRef({
    size: pagination.size,
    grid: pagination.grid,
    autoSwitch: autoSwitchPageSeconds,
    autoPlay: isViewAll ? 'on' : 'off',
  });

  useEffect(() => {
    childStateRef.current = {
      size: pagination.size,
      grid: pagination.grid,
      autoSwitch: autoSwitchPageSeconds,
      autoPlay: isViewAll ? 'on' : 'off',
    };
  }, [pagination.size, pagination.grid, autoSwitchPageSeconds, isViewAll]);

  // For child windows (openlive) - Sync state with parent (control mode)
  useEffect(() => {
    if (!isChildWindow) return;

    const sendHeartbeat = () => {
      const state = childStateRef.current;
      broadcastService.publish('WINDOW_HEARTBEAT', 'ALL', {
        windowId: currentWindowId,
        groupId: currentGroupId,
        groupName: currentGroupName,
        gridMode: { size: state.size, grid: state.grid },
        autoSwitch: state.autoSwitch,
        autoPlay: state.autoPlay,
      });
    };

    const unsubscribe = broadcastService.subscribe((message) => {
      console.log('[LivePage Child] Received broadcast:', message);
      if (message.targetWindowId !== 'ALL' && message.targetWindowId !== currentWindowId) {
        return;
      }

      switch (message.type) {
        case 'REQUEST_STATUS':
          sendHeartbeat();
          break;
        case 'CHANGE_GRID_MODE': {
          const { size, grid, quality } = message.payload;
          setPagination((state) => ({
            ...state,
            size,
            grid,
            quality,
            page: 1,
          }));
          setIsFocusMode(size === 6);
          break;
        }
        case 'CHANGE_AUTO_SWITCH': {
          const { seconds } = message.payload;
          setAutoSwitchPageSeconds(seconds);
          break;
        }
        case 'CHANGE_AUTO_PLAY': {
          const { autoPlay } = message.payload;
          setIsViewAll(autoPlay === 'on');
          break;
        }
        case 'HIGHLIGHT_WINDOW': {
          const { active } = message.payload;
          const hasClass = document.body.classList.contains('window-highlighted');
          if (active && !hasClass) {
            document.body.classList.add('window-highlighted');
          } else if (!active && hasClass) {
            document.body.classList.remove('window-highlighted');
          }
          break;
        }
        case 'FOCUS_WINDOW': {
          if (window.__TAURI__?.webviewWindow?.getCurrentWebviewWindow) {
            try {
              const currentWin = window.__TAURI__.webviewWindow.getCurrentWebviewWindow();
              if (currentWin) {
                currentWin.unminimize().then(() => currentWin.setFocus());
              }
            } catch (e) {
              console.error('[Child Window] Failed to focus:', e);
            }
          }
          break;
        }
        case 'CLOSE_WINDOW': {
          if (window.__TAURI__?.webviewWindow?.getCurrentWebviewWindow) {
            try {
              window.__TAURI__.webviewWindow.getCurrentWebviewWindow().close();
            } catch (e) {
              window.close();
            }
          } else {
            window.close();
          }
          break;
        }
        default:
          break;
      }
    });

    broadcastService.publish('WINDOW_REGISTER', 'ALL', { windowId: currentWindowId });
    sendHeartbeat();
    const heartbeatInterval = setInterval(sendHeartbeat, 3000);

    return () => {
      broadcastService.publish('WINDOW_UNREGISTER', 'ALL', { windowId: currentWindowId });
      unsubscribe();
      clearInterval(heartbeatInterval);
    };
  }, [isChildWindow, currentWindowId, currentGroupId, currentGroupName]);

  // Parent window (main app) - Listen for newly registered child windows and send current settings
  useEffect(() => {
    if (isChildWindow) return;

    const unsubscribe = broadcastService.subscribe((message) => {
      console.log('[LivePage Parent] Received broadcast:', message);
      if (message.type === 'WINDOW_REGISTER') {
        const { windowId } = message.payload;
        console.log('[LivePage Parent] Replying with current settings to child:', windowId, {
          size: pagination.size,
          grid: pagination.grid,
          autoSwitchPageSeconds,
          isViewAll
        });
        // Send current settings to the newly registered child window
        broadcastService.publish('CHANGE_GRID_MODE', windowId, {
          size: pagination.size,
          grid: pagination.grid,
          quality: pagination.quality,
        });
        broadcastService.publish('CHANGE_AUTO_SWITCH', windowId, {
          seconds: autoSwitchPageSeconds,
        });
        broadcastService.publish('CHANGE_AUTO_PLAY', windowId, {
          autoPlay: isViewAll ? 'on' : 'off',
        });
      }
    });

    return () => {
      unsubscribe();
    };
  }, [isChildWindow, pagination.size, pagination.grid, pagination.quality, autoSwitchPageSeconds, isViewAll]);

  /**
   * If selectedGroupId is ROOT_GROUP_ID, dataAllCamera is all camera
   */
  const [dataAllCamera, setDataAllCamera] = useState();
  /**
   * If selectedGroupId is not ROOT_GROUP_ID, RECENT_GROUP_ID
   */
  const [dataGroup, setDataGroup] = useState();

  const [groupSearchData, setGroupSearchData] = useState({
    isSearching: false,
    searchResults: [],
    searchTerm: '',
  });

  const recentsItemToDisplay = useMemo(() => {
    if (selectedGroupId === RECENT_GROUP_ID) {
      const localRecentsCameras = (getLocalRecentItems(userId, namespace) || [])
        ?.filter((item) => item?.type === EDEVICETYPE.CAMERA)
        ?.map((item) => item?.data);
      return recentCameras?.map((item) => {
        const localItem = localRecentsCameras?.find(
          (local) => local.serial === item.serial,
        );
        if (!localItem) return item;
        return {
          ...item,
          ...localItem,
          state: item?.state,
          brand: localItem?.brand || item?.brand || '',
        };
      });
    } else return [];
  }, [selectedGroupId, recentCameras, userId, namespace]);

  const allCameras = useMemo(() => {
    if (customCamera) {
      return [customCamera];
    }

    if (selectedGroupId === ROOT_GROUP_ID) {
      return dataAllCamera?.data || [];
    }

    if (selectedGroupId === RECENT_GROUP_ID) {
      return recentsItemToDisplay;
    }

    return dataGroup?.cameraInfos || [];
  }, [dataAllCamera, dataGroup, selectedGroupId, recentCameras, customCamera]);

  const camerasToDisplayUnsorted = useMemo(() => {
    if (customCamera) {
      return [customCamera];
    }

    if (selectedGroupId === ROOT_GROUP_ID || searchCamera) {
      return dataAllCamera?.data || [];
    }

    if (selectedGroupId === RECENT_GROUP_ID && !searchCamera) {
      return paginate(recentsItemToDisplay, pagination.page, pagination.size);
    }

    if (groupSearchData.isSearching) {
      return paginate(
        groupSearchData.searchResults || [],
        pagination.page,
        pagination.size,
      );
    }

    return paginate(
      dataGroup?.cameraInfos || [],
      pagination.page,
      pagination.size,
    );
  }, [
    dataAllCamera,
    dataGroup,
    selectedGroupId,
    recentCameras,
    pagination.page,
    pagination.size,
    customCamera,
    searchCamera,
    groupSearchData,
  ]);

  const camerasToDisplay = useMemo(() => {
    return camerasToDisplayUnsorted;
    // return camerasToDisplayUnsorted.sort((a, b) => {
    //   if (selectCamera?.serial === a.serial) {
    //     return -1;
    //   }

    //   return 0;
    // });
  }, [camerasToDisplayUnsorted, selectCamera]);

  const total = useMemo(() => {
    if (selectedGroupId === ROOT_GROUP_ID || searchCamera) {
      return dataAllCamera?.totalSize || 0;
    }

    if (selectedGroupId === RECENT_GROUP_ID && !searchCamera) {
      return recentCameras.length;
    }

    if (groupSearchData.isSearching) {
      return groupSearchData.searchResults?.length || 0;
    }

    return dataGroup?.cameraInfos?.length || 0;
  }, [
    dataAllCamera,
    dataGroup,
    selectedGroupId,
    recentCameras,
    searchCamera,
    groupSearchData,
  ]);

  useEffect(() => {
    setPagination((state) => ({
      ...state,
      page: 1,
      total,
      totalPage: Math.ceil(total / state.size),
    }));
  }, [selectedGroupId, total]);

  useEffect(() => {
    if (!cameras) {
      return;
    }

    if (
      cameras.requestId === requestIdRef.current ||
      cameras?.timeRequest === requestIdRef.current
    ) {
      setDataAllCamera(cameras);
      setIsLoading(false);
    }
  }, [cameras]);

  useEffect(() => {
    if (listDeviceByGroupId) {
      console.log('[LivePage Debug] listDeviceByGroupId received:', {
        listRequestId: listDeviceByGroupId.requestId,
        currentRequestIdRef: requestIdRef.current,
        match: listDeviceByGroupId.requestId === requestIdRef.current
      });
    }

    if (
      listDeviceByGroupId &&
      listDeviceByGroupId.requestId === requestIdRef.current
    ) {
      setDataGroup(listDeviceByGroupId);
      setIsLoading(false);
    }
  }, [listDeviceByGroupId]);

  const handleFullScreen = useFullScreenHandle();

  const { dimensions, ref } = useElementDimensions(camerasToDisplay);

  useEffect(() => {
    if (searchCamera !== null && pagination.page !== 1) {
      setPagination((state) => ({
        ...state,
        page: 1,
      }));
    }
  }, [searchCamera]);

  useEffect(() => {
    if (selectedGroupId !== ROOT_GROUP_ID || !isAuth || !namespace) {
      return;
    }

    const reqId = nextRequestId();
    requestIdRef.current = reqId;
    setIsLoading(true);
    console.log('[LivePage Debug] Requesting all devices (root):', { reqId, namespace });

    const data = {
      namespace,
      deviceType: 'camera',
      timeRequest: Date.now(),
      page: pagination.page - 1,
      size: pagination.size,
    };
    if (searchCamera) {
      data.name = searchCamera;
    }

    const dataObj = {
      appServiceType: SERVICE.LIST_ALL_DEVICE_BY_PAGE,
      requestId: reqId,
      body: JSON.stringify(data),
    };

    dispatch(socketEmitEvent(dataObj));
  }, [
    isAuth,
    namespace,
    selectedGroupId,
    pagination.page,
    pagination.size,
    searchCamera,
  ]);

  useEffect(() => {
    if (
      selectedGroupId === RECENT_GROUP_ID ||
      selectedGroupId === ROOT_GROUP_ID ||
      selectedGroupId === CUSTOM_GROUP_ID ||
      !isAuth ||
      !namespace
    ) {
      return;
    }

    const reqId = nextRequestId();
    requestIdRef.current = reqId;
    setIsLoading(true);
    console.log('[LivePage Debug] Requesting devices by group:', { reqId, selectedGroupId, namespace });

    const dataBody = {
      namespace,
      deviceGroupId: selectedGroupId,
      timeRequest: Date.now(),
    };

    const dataObj = {
      appServiceType: SERVICE.LIST_DEVICE_BY_DEVICE_GROUP_ID,
      requestId: reqId,
      body: JSON.stringify(dataBody),
    };

    dispatch(socketEmitEvent(dataObj));
  }, [selectedGroupId, isAuth, namespace]);

  const cameraDimensions = useMemo(() => {
    const { grid } = pagination;
    const { width: containerWidth, height: containerHeight } = dimensions || {};
    let cW = containerWidth;
    let cH = containerHeight;

    if (enabledSmartMode) {
      cW = window.innerWidth - 332;
    } else {
      cW = containerWidth;
    }
    return {
      width: cW / grid?.[0] - REDUCE_DIMENSIONS,
      height: cH / grid?.[1] - REDUCE_DIMENSIONS,
    };
  }, [dimensions, pagination, enabledSmartMode]);

  const requestGetSipAccount = () => {
    let data = {
      namespace,
    };
    let dataObj = {
      appServiceType: SERVICE.REQUEST_MAKE_CALL_OUT,
      requestId: new Date().getTime(),
      body: JSON.stringify(data),
    };
    return dispatch(socketEmitEvent(dataObj));
  };

  useEffect(() => {
    if (namespace) {
      requestGetSipAccount();
    }
  }, [namespace]);
  const onZoomState = (camera) => {
    const subsourceZoomStates =
      (camera?.subSources &&
        JSON.parse(camera?.subSources)?.map((item) => ({
          resolution: item.resolution,
          zoomState: item.zoomState,
        }))) ??
      [];

    const defaultZoomStates =
      camera.zoomState !== undefined
        ? [
          {
            zoomState: camera.zoomState,
            resolution: camera.resolution,
          },
        ]
        : [];

    const dataZoomStates = Array.from(
      new Map(
        [...defaultZoomStates, ...subsourceZoomStates].map((item) => [
          item.resolution,
          item,
        ]),
      ).values(),
    ).sort((a, b) => a.zoomState - b.zoomState);

    return {
      dataZoomStates: dataZoomStates,
      zoomState: dataZoomStates[0]?.zoomState,
      resolution: dataZoomStates[0]?.resolution,
    };
  };

  const handleSwitchPage = (timeSeconds) => {
    setAutoSwitchPageSeconds(timeSeconds);
  };

  useEffect(() => {
    if (autoSwitchPageSeconds > 0) {
      const interval = setInterval(() => {
        setPagination((state) => {
          beeXLogger.debug(
            'LivePage - autoSwitchPageSeconds - state.page: ',
            state.page,
          );
          beeXLogger.debug(
            'LivePage - autoSwitchPageSeconds - state?.totalPage: ',
            state?.totalPage,
          );
          const nextPage =
            state.page + 1 > state?.totalPage ? 1 : state.page + 1;
          beeXLogger.debug(
            'LivePage - autoSwitchPageSeconds - nextPage: ',
            nextPage,
          );

          if (fullscreenCameraSerial) {
            setPendingPage((prev) => (prev >= nextPage ? prev + 1 : nextPage));
            return state;
          }

          beeXLogger.debug(
            'LivePage - autoSwitchPageSeconds - Math.min(nextPage, state.totalPage): ',
            Math.min(nextPage, state.totalPage),
          );
          return {
            ...state,
            page: Math.min(nextPage, state.totalPage),
          };
        });
      }, autoSwitchPageSeconds * 1000);
      return () => clearInterval(interval);
    }
  }, [autoSwitchPageSeconds, pagination?.total, fullscreenCameraSerial]);

  useEffect(() => {
    if (!fullscreenCameraSerial && pendingPage !== null) {
      setPagination((state) => ({
        ...state,
        page: pendingPage,
      }));
      setPendingPage(null);
    }
  }, [fullscreenCameraSerial, pendingPage]);

  const modeButtonsComponent = (pageSize) => (
    <div className="mode-button">
      {isTauri && !isChildWindow && (
        <Tooltip placement="bottom" title="Window Control Mode">
          <div
            onClick={() => setIsControlMode((prev) => !prev)}
            className={`mode ${isControlMode ? 'active' : ''}`}
          >
            <DesktopOutlined style={{ fontSize: 18 }} />
          </div>
        </Tooltip>
      )}
      <Tooltip placement="bottom" title={t('Toggle full screen view')}>
        <div
          onClick={handleFullScreen.enter}
          className={`mode ${handleFullScreen?.active ? 'active' : ''}`}
        >
          <FullScreenIcon />
        </div>
      </Tooltip>
      <Tooltip placement="bottom" title={t('Toggle full focus view mode')}>
        <div
          onClick={() => {
            if (!isFocusMode) {
              setIsFocusMode(true);
              setPagination((state) => ({
                ...state,
                size: 6,
                page: 1,
                quality: ZOOM_STATE.THREE,
                grid: [3, 3],
              }));
            }
          }}
          className={`mode ${isFocusMode ? 'active' : ''}`}
        >
          <GridFocusIcon />
        </div>
      </Tooltip>
      <Tooltip placement="bottom" title={t('Toggle to 2x2 view mode')}>
        <div
          onClick={() => {
            setIsFocusMode(false);
            pageSize !== 4 &&
              setPagination((state) => ({
                ...state,
                size: 4,
                page: 1,
                quality: ZOOM_STATE.THREE,
                grid: [2, 2],
              }));
          }}
          className={`mode ${!isFocusMode && pageSize === 4 ? 'active' : ''}`}
        >
          <Grid2x2Icon />
        </div>
      </Tooltip>
      <Tooltip placement="bottom" title={t('Toggle to 3x3 view mode')}>
        <div
          onClick={() => {
            setIsFocusMode(false);
            pageSize !== 9 &&
              setPagination((state) => ({
                ...state,
                size: 9,
                page: 1,
                quality: ZOOM_STATE.THREE,
                grid: [3, 3],
              }));
          }}
          className={`mode ${!isFocusMode && pageSize === 9 ? 'active' : ''}`}
        >
          <Grid3x3Icon />
        </div>
      </Tooltip>
      <Tooltip placement="bottom" title={t('Toggle to 4x4 view mode')}>
        <div
          onClick={() => {
            setIsFocusMode(false);
            pageSize !== 16 &&
              setPagination((state) => ({
                ...state,
                size: 16,
                page: 1,
                quality: ZOOM_STATE.TWO,
                grid: [4, 4],
              }));
          }}
          className={`mode ${!isFocusMode && pageSize === 16 ? 'active' : ''}`}
        >
          <Grid4x4Icon />
        </div>
      </Tooltip>
      <Tooltip placement="bottom" title={t('Toggle to 5x5 view mode')}>
        <div
          onClick={() => {
            setIsFocusMode(false);
            pageSize !== 30 &&
              setPagination((state) => ({
                ...state,
                size: 25,
                page: 1,
                quality: ZOOM_STATE.ONE,
                grid: [5, 5],
              }));
          }}
          className={`mode per6 ${!isFocusMode && pageSize === 25 ? 'active' : ''}`}
        >
          <Grid5x5Icon />
        </div>
      </Tooltip>
      <Tooltip placement="bottom" title={t('Toggle to 6x6 view mode')}>
        <div
          onClick={() => {
            setIsFocusMode(false);
            pageSize !== 36 &&
              setPagination((state) => ({
                ...state,
                size: 36,
                page: 1,
                quality: ZOOM_STATE.ONE,
                grid: [6, 6],
              }));
          }}
          className={`mode per6 ${!isFocusMode && pageSize === 36 ? 'active' : ''}`}
        >
          <Grid6x6Icon />
        </div>
      </Tooltip>
      <Select
        className="header-camera-select"
        placeholder={t('Interval')}
        value={autoSwitchPageSeconds}
        onChange={handleSwitchPage}
      >
        <Option value={0}>{t('Off autoload')}</Option>
        <Option value={120}>2 {t('minutes')}</Option>
        <Option value={300}>5 {t('minutes')}</Option>
        <Option value={600}>10 {t('minutes')}</Option>
        <Option value={1800}>30 {t('minutes')}</Option>
      </Select>
      <div
        style={{ cursor: 'pointer', display: 'flex', alignItems: 'center' }}
        onClick={() => {
          setIsViewAll((prevState) => !prevState);
        }}
      >
        <img src={isViewAll ? AutoPlayOn : AutoPlayOff} alt="auto-play" />
      </div>
      <span
        style={{
          alignSelf: 'center',
          display: 'inline-block',
          marginRight: '16px',
          marginLeft: '4px',
        }}
      >
        {t('Auto play')}
      </span>
      <div
        style={{ cursor: 'pointer', display: 'flex', alignItems: 'center' }}
        onClick={() => {
          const showModalEnableSmartMode = localStorage.getItem(
            'showModalEnableSmartMode',
          );
          if (
            showModalEnableSmartMode === null ||
            !!Number(showModalEnableSmartMode)
          ) {
            setModalEnableSmartModeVisible(true);
          } else {
            dispatch(toggleSmartMode(true));
            handleFullScreen.enter();
          }
          setPrevPagination(pagination);
        }}
      >
        <img width={45} src={AIView} alt="ai-view" />
      </div>
    </div>
  );

  const [listSerialEvent, setListSerialEvent] = useState([]);
  const getEventBeforeCurrent = async (fromTime, toTime) => {
    const token = storageService.getInternalStorageByKey(
      SYSTEM.DECODED_ACCESS_TOKEN,
    );
    const query = {
      token,
      dataHeader: { namespace },
      dataQuery: {
        fromTime: fromTime,
        toTime: toTime,
        customerNamespace: namespace,
        isDownload: 0,
        limit: 1000,
        offset: 0,
      },
    };
    Promise.all([
      getVirtualWall(query), //tường rào ảo
      getWeaponDetection(query), // hung khí
      getHistoryTrackingEvents(query), // theo dõi
      getEventsByPersonId({
        token,
        dataHeader: {
          namespace: '',
          tenantId: namespace,
        },
        dataQuery: {
          fromTime: fromTime,
          toTime: toTime,
          limit: 1000,
          offset: 0,
          personId: '',
        },
      }), // Nhận diện
      getSecurityIdentifications(query), // xâm nhập
    ]).then((values) => {
      const serialNameSet = new Set();

      values[0].data.records.forEach((record) => {
        if (record?.serial) {
          serialNameSet.add(record.serial);
        }
      });
      values[1].data.records.forEach((record) => {
        if (record?.serial) {
          serialNameSet.add(record.serial);
        }
      });
      values[2].data.records.forEach((record) => {
        if (record?.serial) {
          serialNameSet.add(record.serial);
        }
      });
      values[3].data.cdrs.forEach((record) => {
        if (record?.serial) {
          serialNameSet.add(record.serial);
        }
      });
      values[4].data.records.forEach((record) => {
        if (record?.serial) {
          serialNameSet.add(record.serial);
        }
      });

      const serialName = Array.from(serialNameSet);
      setListSerialEvent(serialName);
    });
  };

  useEffect(() => {
    // event để test
    // getEventBeforeCurrent(1720630800, 1720717199);
    if (enabledSmartMode) {
      getEventBeforeCurrent(
        moment().startOf('day').valueOf(),
        moment().endOf('day').valueOf(),
      );
    }
  }, [enabledSmartMode]);

  const onSelectAlert = (alert) => {
    setSelectCamera(alert);
  };

  const timer = useRef({});

  const toggleClass = (serial) => {
    console.log('TOGGLE CLASS', serial);
    const camera = document.querySelector(`[data-serial="${serial}"]`);
    if (camera) {
      console.log('CAMERA', camera);
      const isAlerting = camera.classList.contains('alerting');
      if (!isAlerting) {
        camera.classList.add('alerting');
      } else {
        if (timer.current[serial]) {
          clearTimeout(timer.current[serial]); //cancel the previous timer.
          timer.current[serial] = null;
        }
      }
      timer.current[serial] = setTimeout(() => {
        camera.classList.remove('alerting');
      }, 5000);
    }
  };

  const newestActiveCamera = detectionAlerts?.[0];

  useEffect(() => {
    if (newestActiveCamera) {
      toggleClass(newestActiveCamera.serial);
    }
  }, [newestActiveCamera]);

  useEffect(() => {
    localStorage.setItem('auto_play', isViewAll ? 'on' : 'off');
  }, [isViewAll]);

  const { gateways } = useGateways(camerasToDisplay.map((cam) => cam.serial));

  const addCameraToRecent = (camera) => {
    setRecentItems((prev) => {
      const newItems = prev.filter(
        (item) => item.type !== 'camera' || item.data.serial !== camera.serial,
      );

      return [{ data: camera, type: 'camera' }, ...newItems];
    });
    // openMessage(NOTIFIES.INFO, 'Camera added to recent');
  };

  const removeCameraFromRecent = (serial) => {
    setRecentItems((prev) => {
      return prev.filter(
        (item) => item.type !== 'camera' || item.data.serial !== serial,
      );
    });
  };

  const getIsCameraPinned = (serial) => {
    return recentItems.some(
      (item) => item.type === 'camera' && item.data.serial === serial,
    );
  };

  const onPinCamera = (cam, pinned) => {
    if (pinned) {
      addCameraToRecent(cam);

      return;
    }

    Modal.confirm({
      title: 'Unpin camera',
      content: 'Are you sure you want to unpin this camera?',
      onOk: () => {
        removeCameraFromRecent(cam.serial);
      },
    });
  };

  const [activeTab, setActiveTab] = useState('list');

  const onTabChange = (key) => {
    if (key === 'list') {
      setCustomCamera(null);
    }

    setActiveTab(key);
  };

  const setAsCustomCamera = (camera) => {
    if (!camera) {
      setCustomCamera(null);

      return;
    }

    setCustomCamera(camera);
    setSelectCamera(camera);
  };

  ////////////////////////////////
  /////// ALERT CAMERAS /////////
  ////////////////////////////////

  // store camera at index i which replaces `camerasToDisplay[i]`
  const [alertCams, setAlertCams] = useState([]);
  const alertTimeBySerial = useRef({});

  const resetAlertCams = () => {
    setAlertCams([]);
    alertTimeBySerial.current = {};
  };

  const mergedCameras = useMemo(() => {
    return mergeCameras(camerasToDisplay, alertCams);
  }, [camerasToDisplay, alertCams]);

  useEffect(() => {
    if (!newestActiveCamera || !enabledSmartMode) {
      return;
    }

    alertTimeBySerial.current[newestActiveCamera.serial] = Date.now();

    const isExist = mergedCameras.some(
      (cam) => cam.serial === newestActiveCamera.serial,
    );

    if (isExist) {
      return;
    }

    const requestId = nextRequestId();

    const camRecord = {
      serial: newestActiveCamera.serial,
      requestId,
      isMock: true,
    };

    // get camera detail
    setTimeout(() => {
      const payload = {
        appServiceType: SERVICE.GET_DEVICE_CONTACT_INFO,
        requestId,
        body: JSON.stringify({
          serial: newestActiveCamera.serial,
          namespace,
        }),
      };

      dispatch(socketEmitEvent(payload));
    });

    const hasSpace = mergedCameras.length < pagination.size;

    // if page is not full, simply add it to the list
    if (hasSpace) {
      setAlertCams((prev) => {
        const newCams = [...prev];
        newCams[mergedCameras.length] = camRecord;

        return newCams;
      });

      return;
    }

    // if page is full, replace it with least alerted camera
    const leastAlertedCamera = mergedCameras.reduce((min, cam) => {
      // if min is not alerted, return min
      if (!alertTimeBySerial.current[min.serial]) {
        return min;
      }

      // if cam is not alerted, return cam
      if (!alertTimeBySerial.current[cam.serial]) {
        return cam;
      }

      // take the least alerted camera
      return alertTimeBySerial.current[cam.serial] <
        alertTimeBySerial.current[min.serial]
        ? cam
        : min;
    }, mergedCameras[0]);
    const indexOfLeastAlertedCamera = mergedCameras.findIndex(
      (cam) => cam.serial === leastAlertedCamera.serial,
    );

    setAlertCams((prev) => {
      const newAlertCams = [...prev];
      newAlertCams[indexOfLeastAlertedCamera] = camRecord;

      return newAlertCams;
    });
  }, [newestActiveCamera, enabledSmartMode, mergedCameras, pagination.size]);

  useEffect(() => {
    if (!deviceContactInfo) {
      return;
    }

    let modified = false;

    setAlertCams((prev) => {
      console.log('XYZ2');
      const needsModify = prev
        ?.filter(Boolean)
        .some(
          (cam) =>
            cam.serial === deviceContactInfo.serial &&
            cam.isMock &&
            cam.requestId === deviceContactInfo.requestId,
        );

      if (!needsModify) {
        return prev;
      }

      modified = true;

      return prev?.filter(Boolean).map((cam) => {
        if (
          cam.serial === deviceContactInfo.serial &&
          cam.requestId === deviceContactInfo.requestId
        ) {
          return deviceContactInfo;
        }

        return cam;
      });
    });

    setTimeout(() => {
      if (modified) {
        toggleClass(deviceContactInfo.serial);
      }
    }, 500);
  }, [deviceContactInfo]);

  const finalCamerasToDisplay = useMemo(() => {
    if (enabledSmartMode) {
      return mergeCameras(camerasToDisplay, alertCams);
    }

    return camerasToDisplay;
  }, [camerasToDisplay, alertCams, enabledSmartMode]);

  // console.log('finalCamerasToDisplay: ', finalCamerasToDisplay);
  // console.log('DETECTION ALERTS', detectionAlerts);
  // console.log('ALERT CAM', alertCams);

  useEffect(() => {
    beeXLogger.debug('LivePage - Preloading codecs');
    preloadCodecs();
  }, []);

  const onOpenGroupInNewWindow = (groupId, groupName) => {
    openNewLiveWindow(groupId, groupName, {
      gridSize: pagination.size,
      autoPlay: isViewAll ? 'on' : 'off',
      autoSwitch: autoSwitchPageSeconds,
    });
  };



  return (
    <div className={`camera-component live-page ${isChildWindow ? 'live-page--child' : ''}`}>
      <Modal
        title={t('Enable smart mode?')}
        visible={modalEnableSmartModeVisible}
        onCancel={() => setModalEnableSmartModeVisible(false)}
        footer={[
          <Button onClick={() => setModalEnableSmartModeVisible(false)}>
            {t('Cancel')}
          </Button>,
          <Button type="primary" onClick={() => history.push('/service')}>
            Go to service page
          </Button>,
          <Button
            type="primary"
            onClick={() => {
              dispatch(toggleSmartMode(true));
              handleFullScreen.enter();
              setModalEnableSmartModeVisible(false);
              const show = !showModalEnableSmartMode.current;
              localStorage.setItem(
                'showModalEnableSmartMode',
                show ? '1' : '0',
              );
            }}
          >
            {t('Continue')}
          </Button>,
        ]}
      >
        <div>{t('To activate smart mode')}</div>
        <ul>
          <li>
            {t('Someone has entered the restricted area - DETECT_OBJECT')}
          </li>
          <li>{t('Someone appeared - DETECT_PERSON')}</li>
          <li>{t('Someone is carrying a weapon - DETECT_WEAPON')}</li>
          <li>{t('Fire smoke detection - DETECT_FIRE')}</li>
          <li>
            {t('There is an object crossing the fence - DETECT_VIRTUAL_WALL')}
          </li>
          <li>{t("Recognize object's face - FACE_RECOGNITION(529)")}</li>
        </ul>
        <Checkbox
          defaultChecked={false}
          onChange={(event) => {
            showModalEnableSmartMode.current = event.target.checked;
          }}
        >
          {t('Do not show this again')}
        </Checkbox>
      </Modal>
      <Layout>
        {!isChildWindow && (
          <Sider width={pagination.size === 36 ? 340 : 324}>
            <div className="live-tab-content">
              <Tabs
                activeKey={activeTab}
                onChange={onTabChange}
                className="custom-tabs"
              >
                <Tabs.TabPane
                  tab={
                    <span>
                      <UnorderedListOutlined /> List
                    </span>
                  }
                  key="list"
                >
                  <ListCamera
                    namespace={namespace}
                    cameras={allCameras}
                    currentPage={pagination.page}
                    pageSize={pagination.size}
                    total={total}
                    onPageChange={(page) =>
                      setPagination((prev) => ({ ...prev, page }))
                    }
                    onSearch={console.log}
                    isLoading={isLoading}
                    selectedGroup={selectedGroup}
                    onSelectGroup={setSelectedGroup}
                    getIsCameraPinned={getIsCameraPinned}
                    onPinCamera={onPinCamera}
                    selectedSerial={selectCamera?.serial}
                    onSelectCamera={setSelectCamera}
                    requestIdRef={requestIdRef}
                    setSearchCamera={setSearchCamera}
                    onGroupSearchChange={(data) => {
                      setGroupSearchData(data);
                      if (data.isSearching) {
                        setPagination((prev) => ({ ...prev, page: 1 }));
                      }
                    }}
                    onOpenGroupInNewWindow={onOpenGroupInNewWindow}
                  />
                </Tabs.TabPane>
                <Tabs.TabPane
                  tab={
                    <span>
                      <ApartmentOutlined /> Tree
                    </span>
                  }
                  key="tree"
                >
                  <LiveTree
                    namespace={namespace}
                    onSelect={(group) => {
                      console.log('GROUP', group);
                      setSelectedGroup(group);
                    }}
                    selectedGroup={selectedGroup}
                    onSelectCamera={setSelectCamera}
                    selectedCamera={selectCamera}
                    getIsCameraPinned={getIsCameraPinned}
                    onPinCamera={onPinCamera}
                    setAsCustomCamera={setAsCustomCamera}
                    customCamera={customCamera}
                  />
                </Tabs.TabPane>
              </Tabs>
            </div>
          </Sider>
        )}
        <Layout>
          {!isChildWindow ? (
            <div
              className="header-camera-component"
              style={{
                width: `calc(100% - ${pagination.size === 36 ? 360 : 332}px)`,
              }}
            >
              {modeButtonsComponent(pagination.size)}

              {total > 0 && !isControlMode && (
                <div className="pagination">
                  <Pagination
                    current={pagination.page}
                    onChange={(value) =>
                      setPagination((state) => ({ ...state, page: value }))
                    }
                    total={total}
                    pageSize={pagination.size}
                    showSizeChanger={false}
                  />
                </div>
              )}
            </div>
          ) : (
            total > 0 && (
              <div className="header-camera-component header-camera-component--static">
                <div className="pagination">
                  <Pagination
                    current={pagination.page}
                    onChange={(value) =>
                      setPagination((state) => ({ ...state, page: value }))
                    }
                    total={total}
                    pageSize={pagination.size}
                    showSizeChanger={false}
                  />
                </div>
              </div>
            )
          )}
          <div className="main-camera-component">
            {isControlMode ? (
              <WindowControlMode namespace={namespace} />
            ) : (
              <FullScreen
                handle={handleFullScreen}
                onChange={(isFullScreen) => {
                  setFullScreen(isFullScreen);

                  setPagination((prev) => ({
                    ...prev,
                    grid: prev.grid,
                  }));

                  if (!isFullScreen) {
                    dispatch(toggleSmartMode(false));
                    if (enabledSmartMode) {
                      setSelectCamera(null);
                      dispatch(clearAlert([]));
                      resetAlertCams();
                    }
                  }
                }}
              >
                {gateways && !finalLoading ? (
                  finalCamerasToDisplay.length > 0 ? (
                    <>
                      {!isFocusMode ? (
                        <Row
                          ref={ref}
                          onDoubleClick={() => {
                            handleFullScreen.exit();
                            setFullScreen(false);
                            dispatch(toggleSmartMode(false));
                            dispatch(clearAlert([]));
                            resetAlertCams();
                          }}
                          gutter={[4, 4]}
                          className={clsx('main-live-page', {
                            fullscreen: handleFullScreen.active,
                            noneFullScreen: !handleFullScreen.active,
                            inSmartMode: enabledSmartMode,
                            isFocusMode,
                            is2Mode: pagination?.size === 4,
                            is3Mode: pagination?.size === 9,
                            is4Mode: pagination?.size === 16,
                            is5Mode: pagination?.size === 25,
                            is6Mode: pagination?.size === 36,
                          })}
                          id="main-live-page"
                          style={{
                            padding:
                              isFullscreen && enabledSmartMode ? '8px' : '',
                            display: 'grid',
                            alignContent: 'start',
                            gridTemplateColumns: `repeat(${pagination.grid?.[0]}, 1fr)`,
                            gridTemplateRows:
                              finalCamerasToDisplay.length < pagination.size
                                ? `repeat(${Math.ceil(
                                  finalCamerasToDisplay.length /
                                  pagination.grid?.[1],
                                )}, auto)`
                                : `repeat(${Math.ceil(
                                  finalCamerasToDisplay.length /
                                  pagination.grid?.[1],
                                )}, 1fr)`,
                            width:
                              isChildWindow || (isFullscreen && !enabledSmartMode)
                                ? '100%'
                                : `calc(100% - ${pagination.size === 36 ? 350 : 332
                                }px)`,
                            // height: `calc(100vh - 108px)`,
                          }}
                        >
                          {finalCamerasToDisplay.map((camera) => (
                            <div
                              key={camera.serial + selectedGroupId}
                              data-serial={camera.serial}
                              className={classNames('camera-container', {
                                fullscreen: isFullscreen,
                                selected: selectCamera?.serial === camera.serial,
                                'show-border': listSerialEvent.includes(
                                  camera.serial,
                                ),
                              })}
                              style={{ width: '100%', padding: '4px' }}
                            >
                              {camera?.typeCamera === CAMERA_TYPE.MILESTONE ? (
                                <MilestoneVideoStreamComponent
                                  key={camera.serial}
                                  allScreen={handleFullScreen.active}
                                  isViewAll={isViewAll}
                                  zoomState={onZoomState(camera)}
                                  name={camera.name}
                                  typeCamera={camera.typeCamera}
                                  resolution={camera.resolution}
                                  serviceId={VIEW_STREAM_SERVICE_EXTEND.normal}
                                  state={camera.state}
                                  serial={camera.serial}
                                  gatewaySerial={camera.gatewaySerial}
                                  thumbnail={camera.thumbnail}
                                  isInternal={gateways?.some(
                                    (g) => g.serial === camera.gatewaySerial,
                                  )}
                                  permission={camera.permission}
                                  isAllowStreaming={camera.isAllowStreaming}
                                />
                              ) : (
                                <div className="relative h-full w-full">
                                  <ViewStreamComponent
                                    key={camera.serial}
                                    allScreen={handleFullScreen.active}
                                    isViewAll={isViewAll}
                                    zoomState={onZoomState(camera)}
                                    name={camera.name}
                                    typeCamera={camera.typeCamera}
                                    resolution={camera.resolution}
                                    serviceId={VIEW_STREAM_SERVICE_EXTEND.normal}
                                    state={camera.state}
                                    serial={camera.serial}
                                    gatewaySerial={camera.gatewaySerial}
                                    thumbnail={camera.thumbnail}
                                    isInternal={gateways?.some(
                                      (g) => g.serial === camera.gatewaySerial,
                                    )}
                                    permission={camera.permission}
                                    isAllowStreaming={camera.isAllowStreaming}
                                    brand={camera.brand || ''}
                                    cameraSubSources={camera?.subSources}
                                    cameraMainSource={{
                                      zoomState: camera.zoomState,
                                      source: camera.source,
                                    }}
                                    variantPage="live"
                                    forceAudio
                                    setForcePlay={setForcePlay}
                                    forcePlay={forcePlay?.[camera.serial]}
                                    setForceMute={setForceMute}
                                    forceMute={forceMute?.[camera.serial]}
                                    allowAudio
                                    showTopName={false}
                                    camera={camera}
                                    pageSize={pagination?.size}
                                    isFullScreenMode={handleFullScreen.active}
                                  />
                                </div>
                              )}
                            </div>
                          ))}
                        </Row>
                      ) : (
                        <GridContainer
                          ref={ref}
                          displayMode={GridDisplayModeEnum.FOCUS}
                          className={clsx({
                            inSmartMode: enabledSmartMode,
                            isFit: finalCamerasToDisplay?.length < 4,
                          })}
                        >
                          {finalCamerasToDisplay?.slice(0, 6).map((camera) => (
                            <GridItem
                              key={camera.serial}
                              displayMode={GridDisplayModeEnum.FOCUS}
                            >
                              <div
                                data-serial={camera.serial}
                                className={classNames('camera-container', {
                                  fullscreen: isFullscreen,
                                  selected:
                                    selectCamera?.serial === camera.serial,
                                  'show-border': listSerialEvent.includes(
                                    camera.serial,
                                  ),
                                })}
                                style={{
                                  width: cameraDimensions?.width,
                                  minWidth: '100%',
                                }}
                              >
                                {camera?.typeCamera === CAMERA_TYPE.MILESTONE ? (
                                  <MilestoneVideoStreamComponent
                                    key={camera.serial}
                                    allScreen={handleFullScreen.active}
                                    isViewAll={isViewAll}
                                    zoomState={onZoomState(camera)}
                                    name={camera.name}
                                    typeCamera={camera.typeCamera}
                                    resolution={camera.resolution}
                                    serviceId={VIEW_STREAM_SERVICE_EXTEND.normal}
                                    state={camera.state}
                                    serial={camera.serial}
                                    gatewaySerial={camera.gatewaySerial}
                                    thumbnail={camera.thumbnail}
                                    isInternal={gateways?.some(
                                      (g) => g.serial === camera.gatewaySerial,
                                    )}
                                    permission={camera.permission}
                                    isAllowStreaming={camera.isAllowStreaming}
                                    onFullscreenChange={(isFs) =>
                                      setFullscreenCameraSerial(
                                        isFs ? camera.serial : null,
                                      )
                                    }
                                  />
                                ) : (
                                  <ViewStreamComponent
                                    key={camera.serial}
                                    allScreen={handleFullScreen.active}
                                    isViewAll={isViewAll}
                                    zoomState={onZoomState(camera)}
                                    name={camera.name}
                                    typeCamera={camera.typeCamera}
                                    resolution={camera.resolution}
                                    serviceId={VIEW_STREAM_SERVICE_EXTEND.normal}
                                    state={camera.state}
                                    serial={camera.serial}
                                    gatewaySerial={camera.gatewaySerial}
                                    thumbnail={camera.thumbnail}
                                    isInternal={gateways?.some(
                                      (g) => g.serial === camera.gatewaySerial,
                                    )}
                                    permission={camera.permission}
                                    isAllowStreaming={camera.isAllowStreaming}
                                    brand={camera.brand || ''}
                                    cameraSubSources={camera?.subSources}
                                    cameraMainSource={{
                                      zoomState: camera.zoomState,
                                      source: camera.source,
                                    }}
                                    variantPage="live"
                                    forceAudio
                                    setForcePlay={setForcePlay}
                                    forcePlay={forcePlay?.[camera.serial]}
                                    setForceMute={setForceMute}
                                    forceMute={forceMute?.[camera.serial]}
                                    allowAudio
                                    showTopName={false}
                                    camera={camera}
                                    pageSize={pagination?.size}
                                    onFullscreenChange={(isFs) =>
                                      setFullscreenCameraSerial(
                                        isFs ? camera.serial : null,
                                      )
                                    }
                                    isFullScreenMode={handleFullScreen.active}
                                  />
                                )}
                              </div>
                            </GridItem>
                          ))}
                        </GridContainer>
                      )}

                      {isFullscreen && enabledSmartMode && (
                        <AlertBox
                          events={detectionAlerts}
                          pagination={pagination}
                          onSelect={onSelectAlert}
                          setPagination={setPagination}
                          gateways={gateways}
                          data={finalCamerasToDisplay}
                          setIsFocusMode={setIsFocusMode}
                          isFocusMode={isFocusMode}
                          prevPagination={prevPagination}
                        />
                      )}

                      {isFullscreen && !enabledSmartMode && (
                        <div
                          style={{
                            position: 'fixed',
                            right: 0,
                            bottom: 0,
                            width: 50,
                            height: 50,
                            zIndex: 1000000,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            cursor: 'pointer',
                          }}
                          onClick={() => dispatch(toggleSmartMode(true))}
                        >
                          <img src={AIView} alt="ai-view" />
                        </div>
                      )}
                    </>
                  ) : (
                    <div
                      className="h-screen w-full"
                      style={{ backgroundColor: '#F2F5FA', paddingTop: 90 }}
                    >
                      <Empty
                        image={NodataIcon}
                        imageStyle={{ height: 60 }}
                        description={
                          <span className="text-brand text-base font-semibold">
                            {t('No data')}
                          </span>
                        }
                      />
                    </div>
                  )
                ) : (
                  <Spinner />
                )}
              </FullScreen>
            )}
          </div>

          <DialPad
            open={dialPad?.show}
            onClose={() => {
              dispatch(
                changeDialPadData({
                  show: false,
                  phone: '',
                }),
              );
            }}
            accountSip={sipAccount || {}}
            calledPhone={dialPad?.phone || ''}
          />
        </Layout>
      </Layout>
    </div>
  );
};

export default LivePage;
