/* eslint-disable react-hooks/exhaustive-deps */
/* eslint-disable react/jsx-no-target-blank */
import {
  CameraOutlined,
  LoadingOutlined,
  PushpinFilled,
  PushpinOutlined,
} from '@ant-design/icons';
import ClassNames from 'classnames';
import moment from 'moment';
import React, {
  Fragment,
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react';
import ReactPlayer from 'react-player';
import DurationComponent from './Duration';
import CenterControlIcon from './icons/center_ovif.svg';
import ControlIconOff from './icons/control_camera_off.svg';
import ControlIconOn from './icons/control_camera_on.svg';
import DownloadIcon from './icons/download.svg';
import FullscreenIcon from './icons/fullscreen.svg';
import ExitFullscreenIcon from './icons/fullscreen_exit.svg';
import StreamIcon from './icons/live_stream.svg';
import MoveIconOff from './icons/move_camera_off.svg';
import MoveIconOn from './icons/move_camera_on.svg';
import PauseIcon from './icons/pause.svg';
import PlayArrowIcon from './icons/play_arrow.svg';
import ResetIcon from './icons/refresh.svg';
import ReplayIcon from './icons/replay.svg';
import MuteIcon from '@/assets/icons/mute-icon.svg';
import UnMuteIcon from '@/assets/icons/unmute-icon.svg';
import './index.scss';
import { useDispatch, useSelector } from 'react-redux';
import { TransformComponent, TransformWrapper } from 'react-zoom-pan-pinch';
import useWindowDimensions from '../../hooks/useWindowDimensions';
import { removeStream, setPinnedCamerasMode } from '../../redux/actions';
import { calcPercentForVideo } from '../../untils/css';
import { downloadFile } from '../../untils/download';
import SpinnerComponent from './Spinner';
import usePanAndZoomVideo from './usePanAndZoomVideo';
import {
  CAMERA_BRAND,
  VIVOTEK_CAMERA_MODEL_ALLOW_PTZ,
} from '@/constants/camera';
import PTZDewarp from './FisheyePlayer';
import { DEWARP_MODE } from '@/constants/ptz';
import { Spin } from 'antd';
import PTZComponent from './PTZ';
import { beeXLogger } from '@/helpers/logger';
import { StreamConnectStep } from './StreamConnectStep';

// Control icons

const speeds = [
  {
    value: 0.1,
    title: '0.1x',
  },
  {
    value: 0.5,
    title: '0.5x',
  },
  {
    value: 1,
    title: '1x',
  },
  {
    value: 2,
    title: '2x',
  },
  {
    value: 4,
    title: '4x',
  },
  {
    value: 8,
    title: '8x',
  },
  {
    value: 16,
    title: '16x',
  },
];

const StreamOptions = {
  webrtc: 'Ultra Fast',
  hls: 'Fast',
};

const PlayerComponent = ({
  type,
  src,
  name,
  sourceObject,
  poster,
  loading,
  status,
  onvif,
  onRotate,
  onZoom,
  fullScreenCallBack,
  restartCallBack,
  restartLoadingCallBack,
  setOnPlay,
  zoomStateProps,
  isFullscreenProps,
  permission,
  serial,
  checkTransferZoomState,
  zoomStatePlayer,
  setZoomStatePlayer,
  restartQualityCallBack,
  logContent,
  logSerial,
  handleReportActionLog,
  dateTime,
  isHlsStreaming,
  seekTo,
  allScreen,
  protocol,
  setRefVideo,
  onPlay,
  onError,
  modes = [],
  selectedMode,
  brand,
  streamData = null,
  streamConnectStep = null,
  setStreamConnectStep = () => {},
  streamConnectStepStates = null,
  streamConnectError = null,
  streamConnectErrorStep = null,
  streamConnectIsSuccess = null,
  isPlayback = false,
  isTranscode = false,
  allowAudio,
  activeDewarpCamera = null,
  onDewarpModeChange = () => {},
  onFullscreenChange,
  streamMonitorId,
  serviceId,
}) => {
  let RETRY_TIMES = 3;
  let RETRY_DURATION = 5000;
  const progress = useRef();
  const refVideo = useRef();
  const refVideoTotal = useRef();
  const refInterval = useRef();
  const dispatch = useDispatch();
  const { pinnedCamerasMode, dataUser, streams } = useSelector(
    (state) => state,
  );
  const [count, setCount] = useState(1);
  const [rotatable, setRotatable] = useState(false);
  const [rotate, setRotate] = useState();
  const [zooming, setZooming] = useState();
  const [pin, setPin] = useState([]);
  const [isPinAll, setIsPinAll] = useState(false);
  const canvasRef = useRef();
  const [dimensions, setDimensions] = useState({});
  const [videoKey, setVideoKey] = useState();
  const [playedSecs, setPlayedSecs] = useState(0);
  const [key, setKey] = useState(Math.floor(Math.random() * 1000));
  const [modeLive, setModeLive] = useState();
  const [countHls, setCountHls] = useState(0);
  const [isRestartHls, setIsRestartHls] = useState(false);
  const hlsRetryEndTimeoutRef = useRef(null);
  const hlsReconnectTimeoutRef = useRef(null);
  const hlsRetryCountRef = useRef(0);
  const [isDownloading, setIsDownloading] = useState(false);
  const [playbackRate, setPlaybackRate] = useState(1);
  // const [streamOptions, setStreamOptions] = useState([]);
  const retryInterval = useRef(null);
  const [ptzDewarpActive, setPtzDewarpActive] = useState(false);
  const [allowPTZDewarp, setAllowPTZDewarp] = useState(false);
  const topControlRef = useRef(null);
  const bottomControlRef = useRef(null);
  const [selectedDewarpMode, setSelectedDewarpMode] = useState(
    DEWARP_MODE.Rectilinear,
  );
  const { width: windowWidth, height: windowHeight } = useWindowDimensions();
  const [isFullScreen, setIsFullscreen] = useState(false);
  const [video, setVideo] = useState({
    controls: false,
    src: null,
    type: 'video',
    loading: true,
    playbackRate: 1.0,
    url: null,
    playing: false,
    volume: 0.5,
    muted: true,
    played: 0,
    duration: 0,
    ended: false,
    seeking: false,
    fullscreen: false,
  });

  const [videoError, setVideoError] = useState();
  const [zoomStateOption, setZoomStateOption] = useState();
  const [selectedQuality, setSelectedQuality] = useState(null);

  const clearHlsRetryTimers = useCallback(() => {
    if (hlsRetryEndTimeoutRef.current) {
      clearTimeout(hlsRetryEndTimeoutRef.current);
      hlsRetryEndTimeoutRef.current = null;
    }

    if (hlsReconnectTimeoutRef.current) {
      clearTimeout(hlsReconnectTimeoutRef.current);
      hlsReconnectTimeoutRef.current = null;
    }
  }, []);

  useEffect(() => {
    hlsRetryCountRef.current = countHls;
  }, [countHls]);

  useEffect(() => {
    return () => {
      clearHlsRetryTimers();
    };
  }, [clearHlsRetryTimers]);

  useEffect(() => {
    if (!selectedQuality && zoomStatePlayer) {
      setSelectedQuality(zoomStatePlayer);
    }
  }, [zoomStatePlayer, selectedQuality]);

  const {
    containerRef,
    onMouseDown,
    onWheel,
    onReset,
    translateX,
    translateY,
    scale,
  } = usePanAndZoomVideo({ zoomable: video.controls });

  const [containerHeight, setContainerHeight] = useState('100%');

  let context;
  if (canvasRef.current) {
    context = canvasRef.current.getContext('2d');
  }

  function getVideoSizeData(videoRef) {
    const ratio = videoRef.current.videoWidth / videoRef.current.videoHeight;
    const w = videoRef.current.videoWidth;
    const h = parseInt(w / ratio, 10);
    return {
      ratio,
      w,
      h,
    };
  }

  useEffect(() => {
    if (containerRef?.current?.clientWidth) {
      setContainerHeight(
        `${((containerRef.current.clientWidth * 9) / 16).toFixed(4)}px`,
      );
    }
  }, [containerRef?.current?.clientWidth]);

  // useEffect(() => {
  //   if (protocol) {
  //     const options = protocol.split(';');

  //     setStreamOptions(options.map((item) => StreamOptions[item]));
  //   }
  // }, [protocol]);

  // useEffect(() => {
  //   if (streamOptions && streamOptions.length === 1) {
  //     setModeLive(streamOptions[0]);
  //   }
  // }, [streamOptions, zoomStatePlayer]);

  const handleFullscreen = () => {
    beeXLogger.debug('Full screen');

    // if (type === 'streaming') fullScreenCallBack(true);
    // If fullscreen mode is active...
    if (
      !!(
        document.fullScreen ||
        document.webkitIsFullScreen ||
        document.mozFullScreen ||
        document.msFullscreenElement ||
        document.fullscreenElement
      )
    ) {
      // ...exit fullscreen mode
      // (Note: this can only be called on document)
      if (document.exitFullscreen) document.exitFullscreen();
      else if (document.mozCancelFullScreen) document.mozCancelFullScreen();
      else if (document.webkitCancelFullScreen)
        document.webkitCancelFullScreen();
      else if (document.msExitFullscreen) document.msExitFullscreen();
    } else {
      if (containerRef.current.requestFullscreen)
        containerRef.current.requestFullscreen();
      else if (containerRef.current.mozRequestFullScreen)
        containerRef.current.mozRequestFullScreen();
      else if (containerRef.current.webkitRequestFullScreen) {
        refVideo.current.webkitRequestFullScreen();
      } else if (containerRef.current.msRequestFullscreen)
        containerRef.current.msRequestFullscreen();
      setIsFullscreen((prev) => !prev);
      if (type === 'streaming') fullScreenCallBack(true);

      setVideo((state) => ({
        ...state,
        fullscreen: true,
      }));
      if (onFullscreenChange) {
        onFullscreenChange(true);
      }
    }
  };

  useEffect(() => {
    if (brand && video) {
      const brandData = brand?.split(';');
      if (!brandData) return;
      const brandName = brandData?.[0]?.toLowerCase();
      const model = brandData?.[1]?.toUpperCase();
      setAllowPTZDewarp(brandName === CAMERA_BRAND.VIVOTEK && video?.playing);
      return;
    }
    setAllowPTZDewarp(false);
  }, [brand, video]);

  const handleTogglePTZDewarp = () => {
    const newState = !ptzDewarpActive;
    setPtzDewarpActive(newState);

    if (newState) {
      setVideo((state) => ({ ...state, controls: false }));
      onDewarpModeChange(serial, true);
    } else {
      onDewarpModeChange(serial, false);
    }
  };

  useEffect(() => {
    if (
      activeDewarpCamera &&
      activeDewarpCamera !== serial &&
      ptzDewarpActive
    ) {
      setPtzDewarpActive(false);
      setVideo((state) => ({ ...state, controls: false }));
    }
  }, [activeDewarpCamera, serial, ptzDewarpActive]);

  useEffect(() => {
    if (type === 'streaming') {
      let refCurrentTime;
      if (!videoKey) {
        refCurrentTime = setInterval(() => {
          setVideoKey(Math.random());
        }, 1000);
      }
      return () => {
        clearInterval(refCurrentTime);
      };
    }
  }, []);

  useEffect(() => {
    // Add listener when the video is actually available for
    // the browser to be able to check the dimensions of the video.
    if (refVideo?.current) {
      refVideo.current.addEventListener('loadedmetadata', function () {
        if (refVideo?.current) {
          const { w, h } = getVideoSizeData(refVideo);
          if (canvasRef?.current) {
            canvasRef.current.width = w;
            canvasRef.current.height = h;
          }
          setDimensions({ w, h });
        }
      });
    }
  }, []);

  const onDownloadDirectClick = () => {
    if (context && refVideo?.current) {
      context.fillRect(0, 0, dimensions.w, dimensions.h);
      context.drawImage(refVideo.current, 0, 0, dimensions.w, dimensions.h);

      const url = canvasRef.current.toDataURL('image/png');
      const link = document.createElement('a');
      link.download = `${serial ?? logSerial}_${
        dateTime ?? moment().format('DD-MM-YYYY')
      }.png`;
      link.href = url;
      link.click();
    }
  };

  useEffect(() => {
    setRotatable(type === 'streaming' && onvif);
  }, [onvif, type, serial]);

  useEffect(() => {
    setPin(sessionStorage.getItem('pinCamera')?.split(',') || []);
    const pinCameraStorage = localStorage.getItem('pin_camera');
    if (pinCameraStorage) {
      setIsPinAll(JSON.parse(pinCameraStorage));
    }
  }, []);

  const prevZoomStateRef = useRef(null);

  useEffect(() => {
    if (zoomStateProps && isFullscreenProps) {
      const maxQuality = zoomStateProps?.dataZoomStates.reduce((max, item) =>
        item.resolution > max.resolution ? item : max,
      );

      if (
        maxQuality?.zoomState !== zoomStatePlayer?.zoomState &&
        maxQuality?.zoomState !== prevZoomStateRef.current
      ) {
        prevZoomStateRef.current = maxQuality?.zoomState;
        onResetQualityStream({
          qualityLevel: maxQuality?.zoomState,
        });
      }
    }
  }, [
    isFullscreenProps,
    zoomStateProps?.dataZoomStates?.length,
    zoomStatePlayer?.zoomState,
  ]);

  useEffect(() => {
    let refClear;
    if (rotate) {
      refClear = setTimeout(() => {
        setRotate(undefined);
      }, 500);
    }
    return () => {
      clearInterval(refClear);
    };
  }, [rotate]);

  useEffect(() => {
    let refClear;
    if (zooming) {
      refClear = setTimeout(() => {
        setZooming(undefined);
      }, 500);
    }
    return () => {
      clearInterval(refClear);
    };
  }, [zooming]);

  const onResetStream = useCallback(
    (dataObject) => {
      clearHlsRetryTimers();
      hlsRetryCountRef.current = 0;
      setVideo((state) => ({
        ...state,
        src: null,
        loading: true,
        playing: false,
        url: null,
      }));
      setPlayedSecs(0);
      setCountHls(0);
      setIsRestartHls(false);
      restartCallBack({ qualityLevel: dataObject?.qualityLevel });
    },
    [clearHlsRetryTimers, restartCallBack],
  );

  const onResetStreamLoading = useCallback(
    (dataObject) => {
      clearHlsRetryTimers();
      hlsRetryCountRef.current = 0;
      setVideo((state) => ({
        ...state,
        src: null,
        loading: true,
        playing: false,
        url: null,
      }));
      setPlayedSecs(0);
      setCountHls(0);
      setIsRestartHls(false);
      restartLoadingCallBack({ qualityLevel: dataObject?.qualityLevel });
      // setSelectedZoomState(dataObject?.qualityLevel);
    },
    [clearHlsRetryTimers, restartLoadingCallBack],
  );

  const onResetQualityStream = useCallback(
    (dataObject) => {
      clearHlsRetryTimers();
      hlsRetryCountRef.current = 0;
      const newZoomState = zoomStateOption?.find((item) => {
        return item.zoomState === dataObject?.qualityLevel;
      });

      if (newZoomState) {
        setSelectedQuality(newZoomState);
        setZoomStatePlayer(newZoomState);
      }

      setVideo((state) => ({
        ...state,
        src: null,
        loading: true,
        playing: false,
        url: null,
      }));

      setPlayedSecs(0);
      setCountHls(0);
      setIsRestartHls(false);

      restartQualityCallBack({ qualityLevel: dataObject?.qualityLevel });
    },
    [clearHlsRetryTimers, restartQualityCallBack, zoomStateOption],
  );

  const countRef = useRef(1);

  // useEffect(() => {
  //   let refRestart;
  //   if (type === 'streaming' && video.playing) {
  //     let current = refVideo.current?.currentTime + 20;
  //     refRestart = setInterval(() => {
  //       if (
  //         Math.round(Math.abs(current - refVideo.current?.currentTime)) === 20
  //       ) {
  //         if (countRef.current <= 3) {
  //           beeXLogger.debug('countPlayer: ', count);
  //           countRef.current = countRef.current + 1;
  //           onResetStream();
  //           if (streams.find(stream => stream.serial === serial)) {
  //             clearInterval(refRestart);
  //             countRef.current = 1;
  //           }
  //           // setCount(count + 1);
  //         } else {
  //           clearInterval(refRestart);
  //           restartCallBack({});
  //         }
  //       } else {
  //         current = refVideo.current?.currentTime + 20;
  //       }
  //     }, RETRY_DURATION);
  //   }
  //   return () => {
  //     // clearInterval(refRestart);
  //   };
  // }, [count, onResetStream, setOnPlay, type, video.playing, restartCallBack]);

  useEffect(() => {
    if (seekTo > 0 && refVideo.current?.duration > 0) {
      refVideo.current.currentTime = seekTo;
      setVideo((state) => ({
        ...state,
        played: parseFloat(seekTo / refVideo.current.duration),
      }));
    }
  }, [refVideo.current?.duration]);

  useEffect(() => {
    if (type === 'video' && src) {
      let VOLUME = 0.5;
      refVideo.current.addEventListener('error', () => {
        setVideoError("Can't play this video");
        handlePause();
      });
      refVideo.current.setAttribute('src', src);
      refVideo.current.volume = VOLUME;
      refVideo.current.play();

      setVideo((state) => ({
        ...state,
        src,
        type,
        volume: VOLUME,
        loading: false,
        playing: true,
      }));
    } else if (type === 'streaming' && sourceObject) {
      let VOLUME = 0.5;
      if (!sourceObject?.link && refVideo.current) {
        if ('srcObject' in refVideo.current) {
          refVideo.current.srcObject = sourceObject;
        } else {
          refVideo.current.src = URL.createObjectURL(sourceObject);
        }
      }
      setVideo((state) => ({
        ...state,
        src: sourceObject,
        type,
        loading: false,
        volume: VOLUME,
        playing: true,
      }));
    }
  }, [sourceObject, src, type]);

  useEffect(() => {
    setVideo((state) => ({
      ...state,
      loading,
    }));
  }, [loading]);

  useEffect(() => {
    if (refVideo?.current?.src) {
      handleDropDownTime();
    }
    return () => clearInterval(refInterval.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [refVideo?.current?.src]);

  useEffect(() => {
    if (zoomStatePlayer?.dataZoomStates?.length) {
      const dataTemp = [];
      // eslint-disable-next-line no-unused-expressions
      zoomStatePlayer?.dataZoomStates?.map((item) => {
        if (
          !dataTemp?.find(
            (item1) =>
              item1?.resolution === item?.resolution &&
              item1?.zoomState === item?.zoomState,
          )
        ) {
          dataTemp.push(item);
        }
      });
      setZoomStateOption(dataTemp);
    }
  }, [zoomStatePlayer?.dataZoomStates]);

  const handleDropDownTime = () => {
    refInterval.current = setInterval(() => {
      const videoTime = refVideoTotal.current?.currentTimeTotal
        ? refVideoTotal.current?.currentTimeTotal +
          (refVideo.current.currentTime - refVideoTotal.current?.currentTime)
        : refVideo.current.currentTime;
      return setVideo((state) => ({
        ...state,
        played: parseFloat(videoTime / refVideo.current.duration),
      }));
    }, 1000 / video.playbackRate);
  };

  const handlePlay = () => {
    if (!isHlsStreaming) {
      refVideo.current.play();
    }
    return setVideo((state) => ({ ...state, playing: true }));
  };
  const handleRePlay = () => {
    refVideo.current.load();
    refVideo.current.src = video.src;
    refVideo.current.play();
    handleDropDownTime();
    return setVideo((state) => ({
      ...state,
      playing: true,
      ended: false,
    }));
  };

  const handlePause = () => {
    if (!isHlsStreaming) {
      refVideo.current.pause();
    }
    return setVideo((state) => ({ ...state, playing: false }));
  };

  const handleEnded = () => {
    clearInterval(refInterval.current);
    return setVideo((state) => ({ ...state, ended: true, playing: false }));
  };

  const handleDuration = () => {
    let duration = refVideo.current.duration;
    return setVideo((state) => ({
      ...state,
      duration,
    }));
  };

  const handleSeekMouseDown = (event) => {
    return setVideo((state) => ({
      ...state,
      seeking: true,
    }));
  };

  const handleSeekMouseUp = (event) => {
    setVideo((state) => ({
      ...state,
      seeking: false,
    }));
    const jumpTime =
      (event.nativeEvent.offsetX / progress.current.offsetWidth) *
      video.duration;

    refVideo.current.currentTime = jumpTime;
  };

  const handleSeekChange = (event) => {
    event.persist();
    return setVideo((state) => ({
      ...state,
      played: parseFloat(
        event.nativeEvent.offsetX / progress.current.offsetWidth,
      ),
    }));
  };

  const handleSpeedChange = (playbackRate) => {
    refVideo.current.playbackRate = playbackRate;
    setPlaybackRate(playbackRate);
    return setVideo((state) => ({
      ...state,
      playbackRate,
    }));
  };

  const handleControlsChange = () => {
    onReset();
    return setVideo((state) => ({
      ...state,
      controls: !state.controls,
    }));
  };

  const exitHandler = useCallback(() => {
    if (
      !document.fullscreenElement &&
      !document.webkitIsFullScreen &&
      !document.mozFullScreen &&
      !document.msFullscreenElement
    ) {
      // Reset zoom
      onReset();
      setPtzDewarpActive(false);
      // Set zoom state
      if (type === 'streaming') {
        fullScreenCallBack(false);
        onResetQualityStream();
      }
      beeXLogger.debug('Exit full screen');
      setIsFullscreen(false);

      setVideo((state) => ({
        ...state,
        fullscreen: false,
        controls: false,
      }));
      if (onFullscreenChange) {
        onFullscreenChange(false);
      }
    }
  }, [fullScreenCallBack, onReset, type, onResetQualityStream]);

  useEffect(() => {
    document.addEventListener('fullscreenchange', exitHandler);
    document.addEventListener('webkitfullscreenchange', exitHandler);
    document.addEventListener('mozfullscreenchange', exitHandler);
    document.addEventListener('MSFullscreenChange', exitHandler);

    return () => {
      document.removeEventListener('fullscreenchange', exitHandler);
      document.removeEventListener('webkitfullscreenchange', exitHandler);
      document.removeEventListener('mozfullscreenchange', exitHandler);
      document.removeEventListener('MSFullscreenChange', exitHandler);
    };
  }, [exitHandler]);

  const handleRotate = useCallback(
    (navigator) => {
      if (rotatable && !rotate) {
        setRotate(navigator);
        return onRotate(navigator);
      }
    },
    [onRotate, rotatable, rotate],
  );

  const handleZoom = useCallback(
    (zoom) => {
      if (rotatable && !rotate) {
        setZooming(zoom);
        return onZoom(zoom);
      }
    },
    [onZoom, rotatable, rotate],
  );

  const handlePin = () => {
    const data = sessionStorage.getItem('pinCamera')?.split(',') || [];
    const dataPin = [...data, serial];
    sessionStorage.setItem('pinCamera', dataPin?.join());
    setPin(dataPin);
  };

  const handleUnPin = () => {
    const data =
      sessionStorage
        .getItem('pinCamera')
        ?.split(',')
        ?.filter((item) => item !== serial) || [];
    sessionStorage.setItem('pinCamera', [...data]?.join());
    setPin([...data]);
  };

  const handleChangeMode = (mode) => {
    const data = pinnedCamerasMode;
    const dataTemp =
      data && JSON.parse(data)
        ? JSON.parse(data)?.filter((item) => item?.serial !== serial)
        : [];
    const dataTempStorage = JSON.stringify([
      ...dataTemp,
      {
        serial,
        mode,
      },
    ]);
    dispatch(setPinnedCamerasMode(dataTempStorage));
    setModeLive(mode);
    onResetQualityStream({
      qualityLevel: zoomStatePlayer?.zoomState,
    });
  };

  const handleError = useCallback(() => {
    const currentRetry = hlsRetryCountRef.current;

    console.log('START_STREAM_MONITOR - HANDLE ERROR', currentRetry);

    if (!navigator.onLine) {
      clearHlsRetryTimers();
      hlsRetryCountRef.current = 0;
      setCountHls(0);
      dispatch(removeStream(serial));
      onResetStream({ qualityLevel: zoomStatePlayer?.zoomState });
      return;
    }

    if (currentRetry < 3) {
      clearHlsRetryTimers();
      const nextRetry = currentRetry + 1;
      hlsRetryCountRef.current = nextRetry;
      setCountHls(nextRetry);
      setIsRestartHls(true);
      setVideo((state) => ({ ...state, loading: true }));
      setPlayedSecs(0);

      hlsRetryEndTimeoutRef.current = setTimeout(() => {
        setIsRestartHls(false);
        setVideo((state) => ({ ...state, loading: false }));
      }, 3000);
      return;
    }

    clearHlsRetryTimers();
    hlsReconnectTimeoutRef.current = setTimeout(() => {
      dispatch(removeStream(serial));
      onResetStream({ qualityLevel: zoomStatePlayer?.zoomState });
    }, 1000);
  }, [
    clearHlsRetryTimers,
    dispatch,
    onResetStream,
    serial,
    zoomStatePlayer?.zoomState,
  ]);

  const handleProgress = (playedSeconds) => {
    if (playedSeconds - playedSecs >= 2) {
      setPlayedSecs(playedSecs + 1);
    } else {
      setPlayedSecs(playedSeconds);
    }
  };

  // const playingRef = useRef(video)
  // playingRef.current = video
  // const sourceObjectRef = useRef(sourceObject)
  // sourceObjectRef.current = sourceObject

  // const autoRestartTimeRef = useRef(null);

  // useEffect(() => {
  //   // 3s after having a playing video, if the video is not playing, it will be restarted
  //   autoRestartTimeRef.current = setTimeout(() => {
  //     beeXLogger.debug("TRY RESTARTTTTTTT", playingRef.current, sourceObjectRef.current)
  //     if (playingRef.current.loading && sourceObjectRef.current) {
  //       beeXLogger.debug("RESTARTTTTTTTTTTTTTTTT")
  //       restartCallBack();
  //     }
  //   }, 3000);

  //     return () => clearTimeout(autoRestartTimeRef.current);
  // }, [restartCallBack])

  const handleMouseEnter = () => {
    if (topControlRef.current) {
      topControlRef.current.style.transform = 'translateY(0)';
    }
    if (bottomControlRef.current) {
      bottomControlRef.current.style.transform = 'translateY(-16px)';
    }
  };

  const handleMouseLeave = () => {
    if (topControlRef.current)
      topControlRef.current.style.transform = 'translateY(-100%)';
    if (bottomControlRef.current)
      bottomControlRef.current.style.transform = 'translateY(100%)';
  };

  const streamConnectStepProps = {
    step: streamConnectStep,
    currentStep: streamConnectStep,
    stepStates: streamConnectStepStates,
    failedStep: streamConnectErrorStep,
    error: streamConnectError,
    wsHost: streamData?.wsHost,
    protocol: selectedMode || protocol || streamData?.protocol,
    isPlayback,
    isTranscode,
    isSuccess:
      typeof streamConnectIsSuccess === 'boolean'
        ? streamConnectIsSuccess
        : Boolean(video?.playing && video?.type === 'streaming'),
    isFullScreen,
  };

  return (
    // <Spin spinning={video.loading}>
    <div
      className={`player-component ${isFullScreen && 'player-fullscreen'}`}
      style={{ height: '100%' }}
    >
      <figure
        ref={containerRef}
        onMouseDown={onMouseDown}
        onWheel={onWheel}
        className="relative"
        style={{
          paddingBottom: allScreen
            ? '56.25%'
            : `${calcPercentForVideo(windowHeight - 108, windowWidth - 324)}%`,
          backgroundImage:
            !isHlsStreaming || video?.controls || playedSecs > 0
              ? 'unset'
              : `url(${poster})`,
          backgroundSize: 'contain',
          backgroundRepeat: 'no-repeat',
          backgroundPosition: 'center',
        }}
      >
        {video?.loading && (
          <div
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2"
            style={{ zIndex: 1000000000 }}
          >
            <LoadingOutlined
              style={{ fontSize: '28px' }}
              className="text-brand"
            />
          </div>
        )}
        {isHlsStreaming && !isRestartHls ? (
          <TransformWrapper>
            <TransformComponent>
              <ReactPlayer
                key={sourceObject?.link}
                className="react-player"
                url={sourceObject?.link ?? ''}
                playing={video?.playing}
                pip={false}
                width="100%"
                height="100%"
                ref={(p) => {
                  refVideo.current = p?.getInternalPlayer();
                  if (setRefVideo) {
                    setRefVideo(refVideo.current);
                  }
                }}
                playbackRate={playbackRate}
                onProgress={({ playedSeconds }) =>
                  handleProgress(playedSeconds)
                }
                onError={(error, value) => {
                  if (!navigator.onLine) {
                    beeXLogger.error(
                      'HLS offline detected, forcing stream recreate',
                      name,
                    );
                    handleError();
                    return;
                  }

                  if (error && value && !value?.fatal) {
                    beeXLogger.error(
                      'Non-fatal media error, skipping retry:',
                      name,
                      error,
                      value,
                    );
                    return;
                  }

                  if (value?.type === 'networkError') {
                    dispatch(removeStream(serial));
                    handleError();
                  }

                  if (onError) {
                    onError(error, value);
                  }
                }}
                onPlay={onPlay}
                muted={video?.muted}
                config={{
                  file: {
                    attributes: {
                      disablePictureInPicture: true,
                      controlsList: 'nodownload',
                    },
                    hlsOptions: {
                      manifestLoadingTimeOut: 10000,
                      manifestLoadingMaxRetry: 2,
                      manifestLoadingRetryDelay: 1000,

                      levelLoadingTimeOut: 10000,
                      levelLoadingMaxRetry: 2,
                      levelLoadingRetryDelay: 1000,

                      fragLoadingTimeOut: 20000,
                      fragLoadingMaxRetry: 3,
                      fragLoadingRetryDelay: 1000,

                      maxBufferLength: 30,
                      maxMaxBufferLength: 60,
                      maxBufferSize: 60 * 1000 * 1000,
                      maxBufferHole: 0.5,
                      lowBufferWatchdogPeriod: 0.5,
                      highBufferWatchdogPeriod: 3,

                      startPosition: -1,
                      enableWorker: true,
                      debug: false,

                      nudgeOffset: 0.1,
                      nudgeMaxRetry: 3,
                      maxFragLookUpTolerance: 0.25,

                      xhrSetup: (xhr, url) => {
                        xhr.timeout = 20000;
                      },
                    },
                    forceHLS: true,
                  },
                }}
              />
            </TransformComponent>
          </TransformWrapper>
        ) : (
          <video
            id={`video-live-stream-${key}`}
            onDoubleClick={() => handleFullscreen()}
            poster={poster}
            ref={(p) => {
              refVideo.current = p;

              if (setRefVideo) {
                setRefVideo(refVideo.current);
              }
            }}
            className={`player-video ${ptzDewarpActive ? 'ptz-hidden' : ''}`}
            onDurationChange={handleDuration}
            onEnded={handleEnded}
            style={{
              position: 'absolute',
              width: '100%',
              height: '100%',
              transform: `translate(${translateX}px, ${translateY}px) scale(${scale})`,
            }}
            autoPlay
            onPlay={onPlay}
            muted={video?.muted}
          />
        )}
        {ptzDewarpActive && refVideo.current && isFullScreen && (
          <PTZDewarp
            videoElement={refVideo.current}
            isActive={true}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
            containerWidth={containerRef.current?.clientWidth || windowWidth}
            containerHeight={containerRef.current?.clientHeight || windowHeight}
            className={isFullScreen && 'fullscreen'}
            selectedDewarpMode={selectedDewarpMode}
          />
        )}
        {(video && video.loading) || checkTransferZoomState ? (
          type === 'streaming' ? (
            <>
              {type === 'streaming' && (
                <div
                  ref={topControlRef}
                  className={
                    pin?.find((item) => item === serial) || isPinAll
                      ? 'top-player-component no-select pinCam'
                      : 'top-player-component no-select'
                  }
                  onMouseEnter={handleMouseEnter}
                  onMouseLeave={handleMouseLeave}
                >
                  <div className="stream_name">
                    <div className="status">{name}</div>
                    <div
                      style={{ display: 'flex', alignItems: 'center', gap: 8 }}
                    >
                      <StreamConnectStep {...streamConnectStepProps} />
                      {pin?.find((item) => item === serial) || isPinAll ? (
                        <PushpinFilled
                          className="pin"
                          onClick={() => handleUnPin()}
                        />
                      ) : (
                        <PushpinOutlined
                          className="pin"
                          onClick={() => handlePin()}
                        />
                      )}
                    </div>
                  </div>
                  {status && status !== 'live' && (
                    <div className="stream_state">
                      <div className="status">{status}</div>
                    </div>
                  )}
                </div>
              )}
              <div
                ref={bottomControlRef}
                onMouseEnter={handleMouseEnter}
                onMouseLeave={handleMouseLeave}
                className={`bottom-player-component no-select ${isFullScreen ? 'in-fullscreen' : 'not-in-fullscreen'}`}
              >
                <div
                  className={`bottom-player-component no-select  ${isFullScreen ? 'in-fullscreen' : 'not-in-fullscreen'}`}
                >
                  <div className="bottom-player-control-left">
                    <div>
                      <button
                        className="play"
                        style={{ padding: '8px 6px 1px 6px' }}
                      >
                        <LoadingOutlined style={{ fontSize: '18px' }} />
                      </button>
                    </div>
                    <button className="stream">
                      <img src={StreamIcon} alt="" />
                    </button>
                    <div>
                      <button
                        onClick={() => {
                          onResetStreamLoading({
                            qualityLevel: zoomStatePlayer?.zoomState,
                          });
                          setTimeout(() => {
                            if (video?.playing) {
                            }
                          }, 1500);
                        }}
                        className="reset-stream"
                      >
                        <img src={ResetIcon} alt="" />
                      </button>
                    </div>
                    <button className="time">
                      <DurationComponent seconds={0} />
                    </button>
                  </div>
                  <div className="stream-progress" />
                  <div className="bottom-player-control-right">
                    <div className="speed">
                      <button className="resolution">
                        {`${(selectedQuality || zoomStatePlayer)?.resolution || 720}p` ??
                          ''}
                      </button>
                      <div className="speeds">
                        {zoomStateOption?.map((q, index) => (
                          <Fragment key={`${q?.zoomState}_${index}`}>
                            <button
                              className={ClassNames({
                                selected:
                                  q?.zoomState === zoomStatePlayer?.zoomState,
                              })}
                              key={q?.zoomState}
                              onClick={() => {
                                onResetQualityStream({
                                  qualityLevel: q?.zoomState,
                                });
                              }}
                            >
                              {`${q?.resolution || 720}p` ?? ''}
                            </button>
                            <br />
                          </Fragment>
                        ))}
                      </div>
                    </div>
                    <div className="speed">
                      <button
                        className="resolution"
                        style={{
                          width: selectedMode === 'webrtc' ? '100%' : '70px',
                        }}
                      >
                        {StreamOptions[selectedMode]}
                      </button>
                      <div className="speeds" style={{ width: '82px' }}>
                        {modes?.map((mode, index) => (
                          <Fragment key={`${mode}_${index}`}>
                            <button
                              className={ClassNames({
                                selected: mode === selectedMode,
                              })}
                              style={{ padding: '4px 10px' }}
                              key={mode}
                              onClick={() => handleChangeMode(mode)}
                            >
                              {`${StreamOptions[mode]}` ?? ''}
                            </button>
                            <br />
                          </Fragment>
                        ))}
                      </div>
                    </div>

                    {allowPTZDewarp && (
                      <>
                        {ptzDewarpActive && (
                          <div className="dewarp-mode">
                            <button className="dewarp-mode-btn">
                              {selectedDewarpMode || DEWARP_MODE.Rectilinear}
                            </button>
                            <div
                              className="dewarp-modes"
                              style={{
                                padding: '4px 24px !important',
                              }}
                            >
                              {Object.entries(DEWARP_MODE)?.map(
                                ([key, value]) => (
                                  <Fragment key={`${key}_${value}`}>
                                    <button
                                      className={
                                        value === selectedDewarpMode
                                          ? 'selected'
                                          : ''
                                      }
                                      key={value}
                                      onClick={() => {
                                        setSelectedDewarpMode(value);
                                      }}
                                    >
                                      {value}
                                    </button>
                                    <br />
                                  </Fragment>
                                ),
                              )}
                            </div>
                          </div>
                        )}
                        <div className="ptz-dewarp-toggle">
                          <button
                            onClick={handleTogglePTZDewarp}
                            className={`ptz-dewarp-button ${ptzDewarpActive ? 'active' : ''}`}
                            title="PTZ Dewarp Mode"
                          >
                            <img
                              src={
                                ptzDewarpActive ? ControlIconOn : ControlIconOff
                              }
                              alt="PTZ Dewarp"
                              style={{
                                filter: ptzDewarpActive
                                  ? 'brightness(1.5)'
                                  : 'none',
                              }}
                            />
                          </button>
                        </div>
                      </>
                    )}
                    {!!isFullScreen && (
                      <div className="control">
                        <button
                          onClick={handleControlsChange}
                          className="settings"
                        >
                          <img
                            src={
                              rotatable
                                ? video.controls
                                  ? ControlIconOn
                                  : ControlIconOff
                                : video.controls
                                  ? MoveIconOn
                                  : MoveIconOff
                            }
                            alt=""
                          />
                        </button>
                      </div>
                    )}
                    <div className="expand">
                      <button
                        onClick={() => handleFullscreen()}
                        className="fullscreen"
                      >
                        {!!isFullScreen ? (
                          <img src={ExitFullscreenIcon} alt="" />
                        ) : (
                          <img src={FullscreenIcon} alt="" />
                        )}
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </>
          ) : (
            <div className="loading">
              <SpinnerComponent />
            </div>
          )
        ) : (
          !!video.src && (
            <Fragment>
              {/* ONVIF PTZ Controls */}
              {video && video.controls && rotatable && (
                <Fragment>
                  {/* <div className="controls-video">
                    <div className="move-buttons">
                      <button onClick={() => handleRotate('up')}>
                        <img
                          src={
                            rotate && rotate === 'up'
                              ? ArrowTopOnIcon
                              : ArrowTopOffIcon
                          }
                          alt="up_button"
                        />
                      </button>
                      <div />
                      <button onClick={() => handleRotate('left')}>
                        <img
                          src={
                            rotate && rotate === 'left'
                              ? ArrowLeftOnIcon
                              : ArrowLeftOffIcon
                          }
                          alt="left_button"
                        />
                      </button>
                      <button onClick={() => onReset()}>
                        <img src={CenterControlIcon} alt="" />
                      </button>
                      <button onClick={() => handleRotate('right')}>
                        <img
                          src={
                            rotate && rotate === 'right'
                              ? ArrowRightOnIcon
                              : ArrowRightOffIcon
                          }
                          alt="right_button"
                        />
                      </button>
                      <div />
                      <button onClick={() => handleRotate('down')}>
                        <img
                          src={
                            rotate && rotate === 'down'
                              ? ArrowBottomOnIcon
                              : ArrowBottomOffIcon
                          }
                          alt="down_button"
                        />
                      </button>
                      <div />
                    </div>
                  </div>
                  <div className="zoom-buttons">
                    <button onClick={() => handleZoom('zoom+')}>
                      <img
                        src={
                          zooming && zooming === 'zoom+'
                            ? ZoomInOnIcon
                            : ZoomInOffIcon
                        }
                        alt="zoom in"
                      />
                    </button>
                    <button onClick={() => handleZoom('zoom-')}>
                      <img
                        src={
                          zooming && zooming === 'zoom-'
                            ? ZoomOutOnIcon
                            : ZoomOutOffIcon
                        }
                        alt="zoom out"
                      />
                    </button>
                  </div> */}
                  <PTZComponent
                    streamMonitorId={streamMonitorId}
                    qualityLevel={
                      (selectedQuality || zoomStatePlayer)?.zoomState
                    }
                    serial={serial}
                    serviceId={serviceId}
                  />
                </Fragment>
              )}
              {/* ONVIF PTZ Controls */}
              {type === 'streaming' && (
                <div
                  ref={topControlRef}
                  className={
                    pin?.find((item) => item === serial) || isPinAll
                      ? 'top-player-component no-select pinCam'
                      : 'top-player-component no-select'
                  }
                  onMouseEnter={handleMouseEnter}
                  onMouseLeave={handleMouseLeave}
                >
                  <div className="stream_name">
                    <div className="status">{name}</div>
                    <div
                      style={{ display: 'flex', alignItems: 'center', gap: 8 }}
                    >
                      <StreamConnectStep {...streamConnectStepProps} />
                      {pin?.find((item) => item === serial) || isPinAll ? (
                        <PushpinFilled
                          className="pin"
                          onClick={() => handleUnPin()}
                        />
                      ) : (
                        <PushpinOutlined
                          className="pin"
                          onClick={() => handlePin()}
                        />
                      )}
                    </div>
                  </div>
                  {status && status !== 'live' && (
                    <div className="stream_state">
                      <div className="status">{status}</div>
                    </div>
                  )}
                </div>
              )}
              <div
                ref={bottomControlRef}
                onMouseEnter={handleMouseEnter}
                onMouseLeave={handleMouseLeave}
                className={`bottom-player-component no-select aaa ${isFullScreen ? 'in-fullscreen' : 'not-in-fullscreen'}`}
              >
                <div className="bottom-player-control-left">
                  <>
                    {video.playing ? (
                      <div>
                        <button onClick={() => handlePause()} className="play">
                          <img src={PauseIcon} alt="" />
                        </button>
                      </div>
                    ) : video.ended ? (
                      <div>
                        <button onClick={() => handleRePlay()} className="play">
                          <img src={ReplayIcon} alt="" />
                        </button>
                      </div>
                    ) : (
                      <div>
                        <button onClick={() => handlePlay()} className="play">
                          <img src={PlayArrowIcon} alt="" />
                        </button>
                      </div>
                    )}
                  </>
                  {allowAudio &&
                    (video?.muted ? (
                      <div>
                        <button
                          onClick={() => {
                            setVideo((prev) => ({ ...prev, muted: false }));
                          }}
                          className="play"
                        >
                          <img src={MuteIcon} alt="" width={20} height={20} />
                        </button>
                      </div>
                    ) : (
                      <div>
                        <button
                          onClick={() => {
                            setVideo((prev) => ({ ...prev, muted: true }));
                          }}
                          className="play"
                        >
                          <img src={UnMuteIcon} alt="" width={20} height={20} />
                        </button>
                      </div>
                    ))}
                  {video?.type === 'streaming' && (
                    <>
                      <button className="stream">
                        <img src={StreamIcon} alt="" />
                      </button>
                      <div>
                        <button
                          onClick={() => {
                            onResetStream({
                              qualityLevel: zoomStatePlayer?.zoomState,
                            });
                            setTimeout(() => {
                              if (video?.playing) {
                              }
                            }, 1500);
                          }}
                          className="reset-stream"
                        >
                          <img src={ResetIcon} alt="" />
                        </button>
                      </div>
                      <div>
                        <button className="time">
                          <DurationComponent
                            seconds={
                              isHlsStreaming
                                ? playedSecs
                                : refVideo.current?.currentTime
                            }
                          />
                        </button>
                      </div>
                    </>
                  )}
                </div>
                {video.type === 'video' && (
                  <Fragment>
                    <div
                      onClick={handleSeekChange}
                      onMouseUp={handleSeekMouseUp}
                      onMouseDown={handleSeekMouseDown}
                      ref={progress}
                      className="progress"
                    >
                      <div
                        className="progress-filled"
                        style={{
                          flexBasis: `${video.played * 100}%`,
                        }}
                      />
                      <div
                        className="point"
                        style={{ marginLeft: `${video.played * 100}%` }}
                      >
                        <div className="timer">
                          <button className="timing">
                            <DurationComponent
                              seconds={
                                video &&
                                Math.round(video.played * video.duration)
                              }
                            />
                          </button>
                        </div>
                      </div>
                    </div>
                    <div>
                      <button className="time">
                        <DurationComponent seconds={video.duration} />
                      </button>
                    </div>
                    <div>
                      <button className="connect-state">
                        <StreamConnectStep {...streamConnectStepProps} />
                      </button>
                    </div>

                    <div className="speed">
                      <button>
                        {
                          speeds.filter(
                            (speed) => speed.value === video.playbackRate,
                          )[0].title
                        }
                      </button>
                      <div className="speeds">
                        {speeds.map((q, index) => (
                          <Fragment key={`${q?.value}_${index}`}>
                            <button
                              className={ClassNames({
                                selected: q.value === video.playbackRate,
                              })}
                              key={q.value}
                              onClick={() => handleSpeedChange(q.value)}
                            >
                              {q.title}
                            </button>
                            <br />
                          </Fragment>
                        ))}
                      </div>
                    </div>
                    {permission &&
                      permission.find((item) => item === 'download') && (
                        <div className="download">
                          {isDownloading ? (
                            <button>
                              <LoadingOutlined style={{ fontSize: '18px' }} />
                            </button>
                          ) : (
                            <button
                              onClick={() => {
                                setIsDownloading(true);

                                downloadFile({
                                  url: src,
                                  fileName: JSON.parse(logContent).cameraName,
                                  isSaveAs: JSON.parse(logContent).isSaveAs,
                                  onFetched: () => {
                                    setIsDownloading(false);
                                  },
                                });

                                handleReportActionLog(logContent, logSerial);
                              }}
                            >
                              <img src={DownloadIcon} alt="" width="35px" />
                            </button>
                          )}
                        </div>
                      )}
                    {allowPTZDewarp && (
                      <>
                        {ptzDewarpActive && (
                          <div className="dewarp-mode">
                            <button className="dewarp-mode-btn">
                              {selectedDewarpMode || DEWARP_MODE.Rectilinear}
                            </button>
                            <div
                              className="dewarp-modes"
                              style={{
                                padding: '4px 24px !important',
                              }}
                            >
                              {Object.entries(DEWARP_MODE)?.map(
                                ([key, value]) => (
                                  <Fragment key={`${key}_${value}`}>
                                    <button
                                      className={
                                        value === selectedDewarpMode
                                          ? 'selected'
                                          : ''
                                      }
                                      key={value}
                                      onClick={() => {
                                        setSelectedDewarpMode(value);
                                      }}
                                    >
                                      {value}
                                    </button>
                                    <br />
                                  </Fragment>
                                ),
                              )}
                            </div>
                          </div>
                        )}
                        <div className="ptz-dewarp-toggle">
                          <button
                            onClick={handleTogglePTZDewarp}
                            className={`ptz-dewarp-button ${ptzDewarpActive ? 'active' : ''}`}
                            title="PTZ Dewarp Mode"
                          >
                            <img
                              src={
                                ptzDewarpActive ? ControlIconOn : ControlIconOff
                              }
                              alt="PTZ Dewarp"
                              style={{
                                filter: ptzDewarpActive
                                  ? 'brightness(1.5)'
                                  : 'none',
                              }}
                            />
                          </button>
                        </div>
                      </>
                    )}
                  </Fragment>
                )}
                {video.type === 'streaming' && (
                  <Fragment>
                    <div className="stream-progress" />
                    {/* {!isHlsStreaming && (
                        <div className="download">
                          <button onClick={onDownloadDirectClick}>
                            <CameraOutlined style={{ fontSize: '20px' }} />
                          </button>
                        </div>
                      )}
                      <div className="speed">
                        <button className="resolution">
                          {`${(selectedQuality || zoomStatePlayer)?.resolution || 720}p` ?? ''}
                        </button>
                        <div className="speeds">
                          {zoomStateOption?.map((q, index) => (
                            <Fragment key={`${q?.zoomState}_${index}`}>
                              <button
                                className={ClassNames({
                                  selected:
                                    q?.zoomState === zoomStatePlayer?.zoomState,
                                })}
                                key={q?.zoomState}
                                onClick={() => {
                                  onResetQualityStream({
                                    qualityLevel: q?.zoomState,
                                  });
                                }}
                              >
                                {`${q?.resolution || 720}p` ?? ''}
                              </button>
                              <br />
                            </Fragment>
                          ))}
                        </div>
                      </div>
                      <div className="speed">
                        <button
                          className="resolution"
                          style={{
                            width: selectedMode === 'webrtc' ? '100%' : '70px',
                          }}
                        >
                          {StreamOptions[selectedMode]}
                        </button>
                        <div className="speeds" style={{ width: '82px' }}>
                          {modes?.map((mode, index) => (
                            <Fragment key={`${mode}_${index}`}>
                              <button
                                className={ClassNames({
                                  selected: mode === selectedMode,
                                })}
                                style={{ padding: '4px 10px' }}
                                key={mode}
                                onClick={() => handleChangeMode(mode)}
                              >
                                {`${StreamOptions[mode]}` ?? ''}
                              </button>
                              <br />
                            </Fragment>
                          ))}
                        </div>
                      </div>
                      {allowPTZDewarp && (
                        <>
                          {
                            ptzDewarpActive && (
                              <div className="dewarp-mode">
                                <button className="dewarp-mode-btn">
                                  {selectedDewarpMode || DEWARP_MODE.Rectilinear}
                                </button>
                                <div className="dewarp-modes"
                                  style={{
                                    padding: '4px 24px !important'
                                  }}
                                >
                                  {Object.entries(DEWARP_MODE)?.map(([key, value]) => (
                                    <Fragment key={`${key}_${value}`}>
                                      <button
                                        className={value === selectedDewarpMode ? 'selected' : ""}
                                        key={value}
                                        onClick={() => {
                                          setSelectedDewarpMode(value);
                                        }}
                                      >
                                        {value}
                                      </button>
                                      <br />
                                    </Fragment>
                                  ))}
                                </div>
                              </div>
                            )
                          }
                          <div className="ptz-dewarp-toggle">
                            <button
                              onClick={handleTogglePTZDewarp}
                              className={`ptz-dewarp-button ${ptzDewarpActive ? 'active' : ''}`}
                              title="PTZ Dewarp Mode"
                            >
                              <img
                                src={ptzDewarpActive ? ControlIconOn : ControlIconOff}
                                alt="PTZ Dewarp"
                                style={{
                                  filter: ptzDewarpActive ? 'brightness(1.5)' : 'none'
                                }}
                              />
                            </button>
                          </div>
                        </>
                      )} */}
                  </Fragment>
                )}
                <div className="bottom-player-control-right">
                  {video?.type === 'streaming' && (
                    <>
                      {!isHlsStreaming && (
                        <div className="download">
                          <button onClick={onDownloadDirectClick}>
                            <CameraOutlined style={{ fontSize: '20px' }} />
                          </button>
                        </div>
                      )}
                      <div className="speed">
                        <button className="resolution">
                          {`${(selectedQuality || zoomStatePlayer)?.resolution || 720}p` ??
                            ''}
                        </button>
                        <div className="speeds">
                          {zoomStateOption?.map((q, index) => (
                            <Fragment key={`${q?.zoomState}_${index}`}>
                              <button
                                className={ClassNames({
                                  selected:
                                    q?.zoomState === zoomStatePlayer?.zoomState,
                                })}
                                key={q?.zoomState}
                                onClick={() => {
                                  onResetQualityStream({
                                    qualityLevel: q?.zoomState,
                                  });
                                }}
                              >
                                {`${q?.resolution || 720}p` ?? ''}
                              </button>
                              <br />
                            </Fragment>
                          ))}
                        </div>
                      </div>
                      <div className="speed">
                        <button
                          className="resolution"
                          style={{
                            width: selectedMode === 'webrtc' ? '100%' : '70px',
                          }}
                        >
                          {StreamOptions[selectedMode]}
                        </button>
                        <div className="speeds" style={{ width: '82px' }}>
                          {modes?.map((mode, index) => (
                            <Fragment key={`${mode}_${index}`}>
                              <button
                                className={ClassNames({
                                  selected: mode === selectedMode,
                                })}
                                style={{ padding: '4px 10px' }}
                                key={mode}
                                onClick={() => handleChangeMode(mode)}
                              >
                                {`${StreamOptions[mode]}` ?? ''}
                              </button>
                              <br />
                            </Fragment>
                          ))}
                        </div>
                      </div>
                      {allowPTZDewarp && (
                        <>
                          {ptzDewarpActive && (
                            <div className="dewarp-mode">
                              <button className="dewarp-mode-btn">
                                {selectedDewarpMode || DEWARP_MODE.Rectilinear}
                              </button>
                              <div
                                className="dewarp-modes"
                                style={{
                                  padding: '4px 24px !important',
                                }}
                              >
                                {Object.entries(DEWARP_MODE)?.map(
                                  ([key, value]) => (
                                    <Fragment key={`${key}_${value}`}>
                                      <button
                                        className={
                                          value === selectedDewarpMode
                                            ? 'selected'
                                            : ''
                                        }
                                        key={value}
                                        onClick={() => {
                                          setSelectedDewarpMode(value);
                                        }}
                                      >
                                        {value}
                                      </button>
                                      <br />
                                    </Fragment>
                                  ),
                                )}
                              </div>
                            </div>
                          )}
                          <div className="ptz-dewarp-toggle">
                            <button
                              onClick={handleTogglePTZDewarp}
                              className={`ptz-dewarp-button ${ptzDewarpActive ? 'active' : ''}`}
                              title="PTZ Dewarp Mode"
                            >
                              <img
                                src={
                                  ptzDewarpActive
                                    ? ControlIconOn
                                    : ControlIconOff
                                }
                                alt="PTZ Dewarp"
                                style={{
                                  filter: ptzDewarpActive
                                    ? 'brightness(1.5)'
                                    : 'none',
                                }}
                              />
                            </button>
                          </div>
                        </>
                      )}
                    </>
                  )}
                  {!!isFullScreen && (
                    <div className="control">
                      <button
                        onClick={handleControlsChange}
                        className="settings"
                      >
                        <img
                          src={
                            rotatable
                              ? video.controls
                                ? ControlIconOn
                                : ControlIconOff
                              : video.controls
                                ? MoveIconOn
                                : MoveIconOff
                          }
                          alt=""
                        />
                      </button>
                    </div>
                  )}
                  <div className="expand">
                    <button
                      onClick={() => handleFullscreen()}
                      className="fullscreen"
                    >
                      {isFullScreen ? (
                        <img src={ExitFullscreenIcon} alt="" />
                      ) : (
                        <img src={FullscreenIcon} alt="" />
                      )}
                    </button>
                  </div>
                </div>
                <canvas crossOrigin="anonymous" ref={canvasRef} hidden />
              </div>
            </Fragment>
          )
        )}
        {!!(dataUser?.enableWatermark && video.playing) && (
          <div className="watermark-container">
            {[...Array(8)].map((item) => (
              <p key={item} style={{ transform: 'rotate(330deg)' }}>
                {dataUser.phoneNumber}
              </p>
            ))}
          </div>
        )}
      </figure>
      {ptzDewarpActive && refVideo.current && !isFullScreen && (
        <PTZDewarp
          videoElement={refVideo.current}
          isActive={true}
          onClose={() => setPtzDewarpActive(false)}
          containerWidth={containerRef.current?.clientWidth || windowWidth}
          containerHeight={containerRef.current?.clientHeight || windowHeight}
          className={isFullScreen && 'fullscreen'}
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          selectedDewarpMode={selectedDewarpMode}
        />
      )}
      {videoError && <div className="video-error">{videoError}</div>}
    </div>
    // </Spin>
  );
};

export default PlayerComponent;
