import { NOTIFICATION_LEVEL } from "@/constants/notification.keys";
import { setNotificationFilter } from "@/redux/notification/action";
import { getNotificationFilter } from "@/redux/notification/reducer";
import { Input, Select } from "antd";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import { useDispatch, useSelector } from "react-redux";


const { Search } = Input;
const { Option } = Select;

const NotificationFilter = ({ onSearch }) => {
  const { t } = useTranslation()
  const [selectedLevel, setSelectedLevel] = useState('all')
  const dispatch = useDispatch();
  const notificationFilter = useSelector(getNotificationFilter())

  const onChangeSelectLevel = (value) => {
    setSelectedLevel(value)
    dispatch(setNotificationFilter({
      level: value ?? 'all'
    }))
  }

  const handleSearch = (value) => {
    onSearch(notificationFilter?.taskStatus || '', value)
  }
  return (
    <div className="w-full">
      <div className="flex justify-between gap-4">
        <Select
          value={selectedLevel}
          style={{ width: '200px' }}
          onChange={onChangeSelectLevel}
        >
          <Option value="all">
            <span style={{ textTransform: 'none' }}>{t('All')}</span>
          </Option>
          <Option value={NOTIFICATION_LEVEL.VERY_HIGH}>
            <span style={{ textTransform: 'none' }}>{t('Very High')}</span>
          </Option>
          <Option value={NOTIFICATION_LEVEL.HIGH}>
            <span style={{ textTransform: 'none' }}>{t('High')}</span>
          </Option>
          <Option value={NOTIFICATION_LEVEL.NORMAL}>
            <span style={{ textTransform: 'none' }}>{t('Medium')}</span>
          </Option>
          <Option value={NOTIFICATION_LEVEL.LOW}>
            <span style={{ textTransform: 'none' }}>{t('Low')}</span>
          </Option>
        </Select>
        <Search
          placeholder={t('Search notification')}
          onSearch={handleSearch}
          // style={{ width: 250, marginRight: '16px' }}
          className="w-full flex"
          allowClear
        />
      </div>
    </div>
  )
}

export default NotificationFilter;