/* eslint-disable react-hooks/exhaustive-deps */
import { ApartmentOutlined, PlusOutlined, UnorderedListOutlined } from '@ant-design/icons';
import {
  Button,
  Checkbox,
  Empty,
  Layout,
  Modal,
  Pagination,
  Row,
  Select,
  Tabs,
  Tooltip,
} from 'antd';
import Axios from 'axios';
import { default as classNames, default as clsx } from 'classnames';
import _, { cloneDeep, set } from 'lodash';
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import { FullScreen, useFullScreenHandle } from 'react-full-screen';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import IconSize65On from '../../assets/icons/5-active.svg';
import IconSize65Off from '../../assets/icons/5-noactive.svg';
import IconSize66On from '../../assets/icons/6-active.svg';
import IconSize66Off from '../../assets/icons/6-noactive.svg';
import NodataIcon from '../../assets/icons/no-data-icon-v2.svg';
import IconFullScreen from '../../assets/icons/fullscreen.svg';
import IconSize16Off from '../../assets/icons/size_16_off.svg';
import IconSize16On from '../../assets/icons/size_16_on.svg';
import IconSize4Off from '../../assets/icons/size_4_off.svg';
import IconSize4On from '../../assets/icons/size_4_on.svg';
import IconSize9Off from '../../assets/icons/size_9_off.svg';
import IconSize9On from '../../assets/icons/size_9_on.svg';
import AutoPlayOff from '../../assets/icons/auto-play-off.svg';
import AutoPlayOn from '../../assets/icons/auto-play-on.svg';
import Spinner from '../../components/Spinner';
import ViewStreamComponent from '../../components/VideoStream/v2';
import * as SERVICE from '../../constants/service.types';
import * as SYSTEM from '../../constants/system.keys';
import {
  VIEW_STREAM_SERVICE_EXTEND,
  ZOOM_STATE,
} from '../../constants/system.keys';
import {
  clearAlert,
  socketEmitEvent,
  toggleSmartMode,
} from '../../redux/actions';
import './index.scss';
import {
  getEventsByPersonId,
  getHistoryTrackingEvents,
  getSecurityIdentifications,
  getVirtualWall,
  getWeaponDetection,
} from '../../api/criticalApi';
import moment from 'moment';
import useElementDimensions from '../../hooks/useElementDimensions';
import storageService from '../../services/storage.service';
import { useHistory } from 'react-router-dom';
import { LiveTree } from '../../components/Tree/Live/v2';
import { RECENT_GROUP_ID, ROOT_GROUP_ID } from '../../constants/group';
import { nextRequestId } from '../../socket/query';
import { useGateways } from '../../hooks/use-gateway-state';
import { useRecentCameras } from '../../hooks/use-recent-cameras';
import { CUSTOM_GROUP_ID } from '../../components/Tree/Live/constant';
import { CAMERA_TYPE } from '@/constants';
import MilestoneVideoStreamComponent from '@/components/VideoStream/MilestoneVideoStream';
import { ListCamera } from '@/components/Tree/Camera/ListCamera';
import { CameraTree } from '@/components/Tree/Camera';
import { getCameraToSetting } from '@/redux/camera/reducer';
import { setCameraToSetting } from '@/redux/camera/action';
import { CameraSetting } from './CameraSetting';
import { ReactComponent as GridIcon } from '@/assets/icons/grid-icon.svg';
import { ReactComponent as ListIcon } from '@/assets/icons/list-icon.svg';
import OfflineAndRtmpCameraComponent from './AddCamera/OfflineCamera';
import RTSPlinkAddCameraComponent from './AddCamera/RTSPlinkAddCamera';
import AddDeviceCamera from './AddDeviceCamera';
import { CameraListLayout } from './CameraListLayout';

const { Sider } = Layout;
const { Option } = Select;
const { TabPane } = Tabs;

const sortByName = (a, b) => {
  if (a?.name < b?.name) {
    return -1;
  }

  if (a?.name > b?.name) {
    return 1;
  }

  return 0;
};

const paginate = (data, page, size) => {
  return data.slice((page - 1) * size, page * size);
};

const makeRecentItemKey = (userId, namespace) => {
  return `recent-live-items-${userId}-${namespace}`;
};

const getLocalRecentItems = (userId, namespace) => {
  try {
    return JSON.parse(
      localStorage.getItem(makeRecentItemKey(userId, namespace)) || '[]'
    );
  } catch (error) {
    return [];
  }
};

const setLocalRecentItems = (userId, namespace, items) => {
  localStorage.setItem(
    makeRecentItemKey(userId, namespace),
    JSON.stringify(items)
  );
};

const mergeCameras = (camToDisplay, alertCams) => {
  const result = [];

  camToDisplay.forEach((cam, index) => {
    if (alertCams[index]) {
      result[index] = alertCams[index];
    } else {
      result[index] = cam;
    }
  });

  alertCams.forEach((cam, index) => {
    if (!result[index]) {
      result[index] = cam;
    }
  });

  return result;
};

const CameraPageV2 = () => {
  const {
    isAuth,
    userId,
    gatewayStates,
    cameraStates,
    namespace,
    dataUser,
    sipAccount,
    dialPad,
    isShowCritical,
    detectionAlerts,
    cameras,
    enabledSmartMode,
    listDeviceByGroupId,
    deviceContactInfo,
    updateDevice,
    addDeviceData,
    checkExternalDevice,
    activeDeviceData,
  } = useSelector((state) => state);
  const cameraToSetting = useSelector(getCameraToSetting);
  const { t } = useTranslation();
  const dispatch = useDispatch();
  const [isViewAll, setIsViewAll] = useState(
    () => localStorage.getItem('auto_play') === 'on'
  );
  const [isFullscreen, setFullScreen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const REDUCE_DIMENSIONS = 5;
  const [selectedGroup, setSelectedGroup] = useState({
    id: RECENT_GROUP_ID,
    name: 'Pinned',
  });
  const timer = useRef({});

  const selectedGroupId = selectedGroup?.id;

  const requestIdRef = useRef(null);
  const [recentItems, setRecentItems] = useState([]);

  const recentCamerasRaw = useMemo(() => {
    return recentItems
      .filter((item) => item.type === 'camera')
      .map((item) => item.data);
  }, [recentItems]);

  const { cameras: recentCameras, loading } = useRecentCameras({
    cameras: recentCamerasRaw,
    namespace,
    enabled: selectedGroupId === RECENT_GROUP_ID,
  });

  const finalLoading = isLoading;
  const [updateReturn, setUpdateReturn] = useState(null);
  const [viewMode, setViewMode] = useState('grid');

  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [requestId, setRequestId] = useState(new Date().getTime());
  const [visibleAddCamera, setVisibleAddCamera] = useState(false);
  const [addDeviceReturn, setAddDeviceReturn] = useState(addDeviceData);
  const [checkExternalDeviceReturn, setCheckExternalDeviceReturn] = useState();
  const [activeDeviceReturn, setActiveDeviceReturn] = useState(activeDeviceData);
  const [key, setKey] = useState(Math.random());
  const [keyTab, setKeyTab] = useState('1');
  const [forcePlay, setForcePlay] = useState({})
  const [forceMute, setForceMute] = useState({})
  useEffect(() => {
    return () => {
      setAddDeviceReturn(null);
      setCheckExternalDeviceReturn(null);
      setActiveDeviceReturn(null);
    };
  }, []);

  useEffect(() => {
    setAddDeviceReturn(addDeviceData);
  }, [addDeviceData]);

  useEffect(() => {
    setCheckExternalDeviceReturn(checkExternalDevice);
  }, [checkExternalDevice]);

  useEffect(() => {
    setActiveDeviceReturn(activeDeviceData);
  }, [activeDeviceData]);

  useEffect(() => {
    if (updateDevice && updateDevice.requestId === requestId) {
      setUpdateReturn(updateDevice);
      if (page && isAuth === 1 && pageSize && namespace) {
        getDeviceByPage(page - 1, pageSize);
      }
    }
  }, [updateDevice]);

  useEffect(() => {
    setRecentItems(getLocalRecentItems(userId, namespace));
  }, [userId, namespace]);

  useEffect(() => {
    if (!userId || !namespace) {
      return;
    }

    setLocalRecentItems(userId, namespace, recentItems);
  }, [recentItems, userId, namespace]);

  const [pagination, setPagination] = useState({
    page: 1,
    size: 6,
    quality: ZOOM_STATE.THREE,
    grid: [3, 3],
  });
  const [selectCamera, setSelectCamera] = useState();
  const [customCamera, setCustomCamera] = useState();

  const [dataAllCamera, setDataAllCamera] = useState();
  const [dataGroup, setDataGroup] = useState();
  const [allCameras, setAllCameras] = useState([]);

  useEffect(() => {
    let tmp = [];
    if (customCamera) {
      tmp = [customCamera];
    } else if (selectedGroupId === ROOT_GROUP_ID) {
      tmp = dataAllCamera?.data || [];
    } else if (selectedGroupId === RECENT_GROUP_ID) {
      tmp = recentCameras;
    } else {
      tmp = dataGroup?.cameraInfos || [];
    }
    if (updateReturn) {
      console.log('setAllCameras: ', updateReturn);
      tmp = tmp.map(item => item?.serial === updateReturn?.data?.serial ? { ...item, ...updateReturn?.data } : { ...item });
    }
    setAllCameras(tmp);
  }, [dataAllCamera, dataGroup, selectedGroupId, recentCameras, customCamera, updateReturn]);

  const camerasToDisplayUnsorted = useMemo(() => {
    if (customCamera) {
      return [customCamera];
    }

    if (selectedGroupId === ROOT_GROUP_ID) {
      return dataAllCamera?.data || [];
    }

    if (selectedGroupId === RECENT_GROUP_ID) {
      return paginate(recentCameras, pagination.page, pagination.size);
    }

    return paginate(
      dataGroup?.cameraInfos || [],
      pagination.page,
      pagination.size
    );
  }, [
    dataAllCamera,
    dataGroup,
    selectedGroupId,
    recentCameras,
    pagination.page,
    pagination.size,
    customCamera,
  ]);

  const camerasToDisplay = useMemo(() => {
    return camerasToDisplayUnsorted;
  }, [camerasToDisplayUnsorted, selectCamera]);

  const total = useMemo(() => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      return dataAllCamera?.totalSize || 0;
    }

    if (selectedGroupId === RECENT_GROUP_ID) {
      return recentCameras.length;
    }

    return dataGroup?.cameraInfos?.length || 0;
  }, [dataAllCamera, dataGroup, selectedGroupId, recentCameras]);

  useEffect(() => {
    setPagination((state) => ({
      ...state,
      page: 1,
      total,
      totalPage: Math.ceil(total / state.size),
    }));
  }, [selectedGroupId, total]);

  useEffect(() => {
    if (!cameras) {
      return;
    }

    setDataAllCamera(cameras);
    setIsLoading(false);
  }, [cameras]);

  useEffect(() => {
    if (
      listDeviceByGroupId &&
      listDeviceByGroupId.requestId === requestIdRef.current
    ) {
      setDataGroup(listDeviceByGroupId);
      setIsLoading(false);
    }
  }, [listDeviceByGroupId]);

  const handleFullScreen = useFullScreenHandle();

  const { dimensions, ref } = useElementDimensions(camerasToDisplay);

  useEffect(() => {
    if (selectedGroupId !== ROOT_GROUP_ID || !isAuth) {
      return;
    }

    const reqId = nextRequestId();
    requestIdRef.current = reqId;
    setIsLoading(true);

    const data = {
      namespace,
      deviceType: 'camera',
      timeRequest: Date.now(),
      page: pagination.page - 1,
      size: pagination.size,
    };

    console.log('dataaa', data);

    const dataObj = {
      appServiceType: SERVICE.LIST_ALL_DEVICE_BY_PAGE,
      requestId: reqId,
      body: JSON.stringify(data),
    };

    dispatch(socketEmitEvent(dataObj));
  }, [isAuth, namespace, selectedGroupId, pagination.page, pagination.size]);

  useEffect(() => {
    if (
      selectedGroupId === RECENT_GROUP_ID ||
      selectedGroupId === ROOT_GROUP_ID ||
      selectedGroupId === CUSTOM_GROUP_ID ||
      !isAuth
    ) {
      return;
    }

    const reqId = nextRequestId();
    requestIdRef.current = reqId;
    setIsLoading(true);

    const dataBody = {
      namespace,
      deviceGroupId: selectedGroupId,
      timeRequest: Date.now(),
    };

    const dataObj = {
      appServiceType: SERVICE.LIST_DEVICE_BY_DEVICE_GROUP_ID,
      requestId: reqId,
      body: JSON.stringify(dataBody),
    };

    dispatch(socketEmitEvent(dataObj));
  }, [selectedGroupId, isAuth, namespace]);

  const cameraDimensions = useMemo(() => {
    const { grid } = pagination;
    const { width: containerWidth, height: containerHeight } = dimensions || {};
    return {
      width: containerWidth / grid?.[0] - REDUCE_DIMENSIONS,
      height: containerHeight / grid?.[1] - REDUCE_DIMENSIONS,
    };
  }, [dimensions, pagination.grid]);

  const requestGetSipAccount = () => {
    let data = {
      namespace,
    };
    let dataObj = {
      appServiceType: SERVICE.REQUEST_MAKE_CALL_OUT,
      requestId: new Date().getTime(),
      body: JSON.stringify(data),
    };
    return dispatch(socketEmitEvent(dataObj));
  };

  useEffect(() => {
    if (namespace) {
      requestGetSipAccount();
    }
  }, [namespace]);

  const onZoomState = (camera) => {
    const subsourceZoomStates =
      (camera?.subSources &&
        JSON.parse(camera?.subSources)?.map((item) => ({
          resolution: item.resolution,
          zoomState: item.zoomState,
        }))) ??
      [];

    const defaultZoomStates =
      camera.zoomState !== undefined
        ? [
          {
            zoomState: camera.zoomState,
            resolution: camera.resolution,
          },
        ]
        : [];

    const dataZoomStates = Array.from(
      new Map(
        [...defaultZoomStates, ...subsourceZoomStates].map((item) => [
          item.resolution,
          item,
        ])
      ).values()
    ).sort((a, b) => a.zoomState - b.zoomState);

    return {
      dataZoomStates: dataZoomStates,
      zoomState: dataZoomStates[0]?.zoomState,
      resolution: dataZoomStates[0]?.resolution,
    };
  };

  const toggleClass = (serial) => {
    console.log('TOGGLE CLASS', serial);
    const camera = document.querySelector(`[data-serial="${serial}"]`);
    if (camera) {
      console.log('CAMERA', camera);
      const isAlerting = camera.classList.contains('alerting');
      if (!isAlerting) {
        camera.classList.add('alerting');
      } else {
        if (timer.current[serial]) {
          clearTimeout(timer.current[serial]);
          timer.current[serial] = null;
        }
      }
      timer.current[serial] = setTimeout(() => {
        camera.classList.remove('alerting');
      }, 5000);
    }
  };

  const newestActiveCamera = detectionAlerts?.[0];

  useEffect(() => {
    if (newestActiveCamera) {
      toggleClass(newestActiveCamera.serial);
    }
  }, [newestActiveCamera]);

  useEffect(() => {
    localStorage.setItem('auto_play', isViewAll ? 'on' : 'off');
  }, [isViewAll]);

  const { gateways } = useGateways(camerasToDisplay.map((cam) => cam.serial));

  const addCameraToRecent = (camera) => {
    setRecentItems((prev) => {
      const newItems = prev.filter(
        (item) => item.type !== 'camera' || item.data.serial !== camera.serial
      );

      return [{ data: camera, type: 'camera' }, ...newItems];
    });
  };

  const removeCameraFromRecent = (serial) => {
    setRecentItems((prev) => {
      return prev.filter(
        (item) => item.type !== 'camera' || item.data.serial !== serial
      );
    });
  };

  const getIsCameraPinned = (serial) => {
    return recentItems.some(
      (item) => item.type === 'camera' && item.data.serial === serial
    );
  };

  const onPinCamera = (cam, pinned) => {
    if (pinned) {
      addCameraToRecent(cam);
      return;
    }

    Modal.confirm({
      title: 'Unpin camera',
      content: 'Are you sure you want to unpin this camera?',
      onOk: () => {
        removeCameraFromRecent(cam.serial);
      },
    });
  };

  const [activeTab, setActiveTab] = useState('list');

  const onTabChange = (key) => {
    if (key === 'list') {
      setCustomCamera(null);
    }

    setActiveTab(key);
  };

  const setAsCustomCamera = (camera) => {
    if (!camera) {
      setCustomCamera(null);
      return;
    }

    setCustomCamera(camera);
    setSelectCamera(camera);
  };

  const finalCamerasToDisplay = useMemo(() => {
    return camerasToDisplay;
  }, [camerasToDisplay, enabledSmartMode]);

  useEffect(() => {
    return () => {
      dispatch(setCameraToSetting(null));
    };
  }, []);

  const onUpdateReturn = (value) => {
    console.log('onUpdateReturn: ', value);
    setUpdateReturn(value);
  };

  const getDeviceByPage = useCallback(
    (page, size, dataSearch) => {
      let data = {
        namespace,
        deviceType: 'camera',
        timeRequest: requestId,
        page,
        size,
      };
      if (dataSearch) {
        data.name = dataSearch;
      }
      let dataObj = {
        appServiceType: SERVICE.LIST_ALL_DEVICE_BY_PAGE,
        requestId,
        body: JSON.stringify(data),
      };
      return dispatch(socketEmitEvent(dataObj));
    },
    [dispatch, namespace, requestId]
  );

  const onUpdateCamera = useCallback(
    (data, requestId) => {
      if (data) {
        let dataObj = {
          appServiceType: SERVICE.UPDATE_DEVICE,
          requestId,
          body: JSON.stringify({
            ...data,
            namespace,
          }),
        };

        return dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, namespace]
  );

  const onRequireActiveDevice = useCallback(
    (serial) => {
      if (serial && serial.length > 0) {
        let data = {
          serial: serial.trim(),
          namespace,
        };

        let dataObj = {
          appServiceType: SERVICE.REQUIRE_ACTIVE_DEVICE,
          requestId: new Date().getTime(),
          body: JSON.stringify(data),
        };
        return dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, namespace]
  );

  const onCheckExternalDevice = useCallback(
    (serial) => {
      if (serial && serial.length > 0) {
        let data = {
          serial: serial.trim(),
          namespace,
          deviceType: 'camera',
          extraInfo: {},
        };

        let dataObj = {
          appServiceType: SERVICE.CHECK_EXTERNAL_DEVICE,
          requestId: new Date().getTime(),
          body: JSON.stringify(data),
        };
        return dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, namespace]
  );

  const onAddDevice = useCallback(
    (serial, activationCode) => {
      if (
        serial &&
        serial.length > 0 &&
        activationCode &&
        activationCode.length > 0
      ) {
        let data = {
          serial,
          activationCode,
          namespace,
        };

        let dataObj = {
          appServiceType: SERVICE.ADD_DEVICE,
          requestId: new Date().getTime(),
          body: JSON.stringify(data),
        };
        return dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, namespace]
  );

  const onAddCamera = useCallback(
    (serial, name, deviceSerial, typeCamera) => {
      if (serial && serial.length > 0 && name && name.length > 0) {
        let data = {
          namespace,
          serial: deviceSerial,
          deviceType: 'camera',
          extraInfo: {
            typeCamera: typeCamera,
            name: name.trim(),
            factorySerial: serial,
          },
        };

        let dataObj = {
          appServiceType: SERVICE.REQUEST_ADD_EXTERNAL_DEVICE,
          requestId: new Date().getTime(),
          body: JSON.stringify(data),
        };
        return dispatch(socketEmitEvent(dataObj));
      }
    },
    [dispatch, namespace]
  );

  const handleChangeTab = (value) => {
    setKeyTab(value);
  };

  return (
    <>
      <div className="camera-component-v2">
        <Layout>
          <Sider width={pagination.size === 36 ? 340 : 324}>
            <div className="live-tab-content">
              <Tabs activeKey={activeTab} onChange={onTabChange} className="custom-tabs">
                <Tabs.TabPane
                  tab={
                    <span>
                      <UnorderedListOutlined /> List
                    </span>
                  }
                  key="list"
                >
                  <ListCamera
                    getIsCameraPinned={getIsCameraPinned}
                    onPinCamera={onPinCamera}
                    onSelectCamera={setSelectCamera}
                    selectedGroup={selectedGroup}
                    selectedSerial={selectCamera?.serial}
                    onSelectGroup={setSelectedGroup}
                    namespace={namespace}
                    cameras={allCameras}
                    variantPage='camera-v2'
                  />
                </Tabs.TabPane>
                <Tabs.TabPane
                  tab={
                    <span>
                      <ApartmentOutlined /> Tree
                    </span>
                  }
                  key="tree"
                >
                  <CameraTree
                    namespace={namespace}
                    recentItems={recentItems}
                    setRecentItems={setRecentItems}
                    onSelect={setSelectedGroup}
                    selectedId={selectedGroup?.id}
                    onSelectCamera={setSelectCamera}
                    selectedSerial={selectCamera?.serial}
                    setAsCustomCamera={setAsCustomCamera}
                    onPinCamera={onPinCamera}
                    getIsCameraPinned={getIsCameraPinned}
                    customCamera={customCamera}
                    variantPage='camera-v2'
                  />
                </Tabs.TabPane>
              </Tabs>
            </div>
          </Sider>
          <div
            className="header-camera-component flex justify-between items-center"
            style={{
              width: `calc(100% - ${pagination.size === 36 ? 360 : 332}px)`,
            }}
          >
            <div className='view-mode-selector'>
              <Tooltip placement="bottom" title={t('Grid')}>
                <div className={`mode ${viewMode === 'grid' ? 'selected' : ''}`} onClick={() => setViewMode('grid')}>
                  <GridIcon />
                </div>
              </Tooltip>
              <Tooltip placement="bottom" title={t('List')}>
                <div className={`mode ${viewMode === 'list' ? 'selected' : ''}`} onClick={() => setViewMode('list')}>
                  <ListIcon />
                </div>
              </Tooltip>
            </div>
            <div className='header-right'>
              <Button
                type='default'
                icon={<PlusOutlined />}
                onClick={() => setVisibleAddCamera(true)}
              >
                Add Camera
              </Button>
            </div>
          </div>
          <Layout className='right-layout h-full'>
            <div className={`right-layout-content ${cameraToSetting ? 'shrink' : 'expand'}`}>
              <div className="main-camera-component">
                {gateways && !finalLoading ? (
                  finalCamerasToDisplay.length > 0 ? (
                    <FullScreen
                      handle={handleFullScreen}
                      onChange={(isFullScreen) => {
                        setFullScreen(isFullScreen);
                        setPagination((prevState) => ({
                          ...prevState,
                          grid: prevState.grid,
                        }));
                      }}
                    >
                      <Row
                        ref={ref}
                        onDoubleClick={() => {
                          handleFullScreen.exit();
                          setFullScreen(false);
                        }}
                        gutter={[4, 4]}
                        className={clsx('main-live-page', {
                          fullscreen: handleFullScreen.active,
                          noneFullScreen: !handleFullScreen.active,
                        })}
                        id="main-live-page"
                        style={{
                          padding: isFullscreen ? '8px' : '',
                          width:
                            isFullscreen
                              ? '100%'
                              : `calc(100% - ${pagination.size === 36 ? 350 : 332}px)`,
                          height: `calc(100vh - 108px)`,
                        }}
                      >
                        {
                          viewMode === 'grid' && (
                            finalCamerasToDisplay.map((camera) => (
                              <div
                                key={camera.serial}
                                data-serial={camera.serial}
                                style={{
                                  padding: '4px',
                                }}
                                className={classNames({
                                  'camera-container': true,
                                  fullscreen: isFullscreen,
                                  selected:
                                    selectCamera &&
                                    selectCamera.serial &&
                                    camera.serial === selectCamera.serial,
                                })}
                              >
                                {
                                  camera?.typeCamera === CAMERA_TYPE.MILESTONE ? (
                                    <MilestoneVideoStreamComponent
                                      key={camera.serial}
                                      allScreen={handleFullScreen.active}
                                      isViewAll={isViewAll}
                                      zoomState={onZoomState(camera)}
                                      name={camera.name}
                                      typeCamera={camera.typeCamera}
                                      resolution={camera.resolution}
                                      serviceId={VIEW_STREAM_SERVICE_EXTEND.normal}
                                      state={camera.state}
                                      serial={camera.serial}
                                      gatewaySerial={camera.gatewaySerial}
                                      thumbnail={camera.thumbnail}
                                      isInternal={
                                        gateways &&
                                        gateways.some(
                                          (gateway) =>
                                            gateway.serial === camera.gatewaySerial
                                        )
                                      }
                                      permission={camera.permission}
                                      isAllowStreaming={camera.isAllowStreaming}
                                    />
                                  ) : (
                                    <div className='relative h-full w-full'>
                                      <ViewStreamComponent
                                        key={camera.serial}
                                        allScreen={handleFullScreen.active}
                                        isViewAll={false}
                                        zoomState={onZoomState(camera)}
                                        name={camera.name}
                                        typeCamera={camera.typeCamera}
                                        resolution={camera.resolution}
                                        serviceId={VIEW_STREAM_SERVICE_EXTEND.normal}
                                        state={camera.state}
                                        serial={camera.serial}
                                        gatewaySerial={camera.gatewaySerial}
                                        thumbnail={camera.thumbnail}
                                        isInternal={
                                          gateways &&
                                          gateways.some(
                                            (gateway) =>
                                              gateway.serial === camera.gatewaySerial
                                          )
                                        }
                                        permission={camera.permission}
                                        isAllowStreaming={camera.isAllowStreaming}
                                        brand={camera.brand || ''}
                                        cameraSubSources={camera?.subSources}
                                        cameraMainSource={{
                                          zoomState: camera.zoomState,
                                          source: camera.source
                                        }}
                                        variantPage='live'
                                        forceAudio={true}
                                        setForcePlay={setForcePlay}
                                        forcePlay={forcePlay?.[camera?.serial]}
                                        setForceMute={setForceMute}
                                        forceMute={forceMute?.[camera?.serial]}
                                        showTopName={false}
                                        allowAudio={true}
                                        camera={camera}
                                        pageSize={pagination?.size}
                                        showSetting
                                      />
                                    </div>
                                  )
                                }
                              </div>
                            ))
                          )
                        }

                        {
                          viewMode === 'list' && (
                            <CameraListLayout
                              data={finalCamerasToDisplay}
                              pagination={pagination}
                              total={total}
                              onPageChange={(value) => {
                                console.log('value: ', value);
                                setPagination((state) => ({ ...state, page: value }));
                              }}
                              onZoomState={onZoomState}
                              gateways={gateways}
                            />
                          )
                        }
                      </Row>
                    </FullScreen>
                  ) : (
                    <Empty
                      style={{ margin: 80 }}
                      image={NodataIcon}
                      imageStyle={{
                        height: 60,
                      }}
                      description={<span className='text-brand text-base font-semibold'>{t('No data')}</span>}
                    />
                  )
                ) : (
                  <Spinner />
                )}
              </div>
              {
                viewMode === 'grid' && total > 0 && (
                  <div className="pagination">
                    <Pagination
                      current={pagination.page}
                      onChange={(value) => {
                        console.log('value: ', value);
                        setPagination((state) => ({ ...state, page: value }));
                      }}
                      total={total}
                      pageSize={pagination.size}
                      showSizeChanger={false}
                    />
                  </div>
                )
              }
            </div>
            <div className={`camera-setting ${!cameraToSetting ? 'shrink' : 'expand'}`}>
              <CameraSetting onUpdateReturn={onUpdateReturn} />
            </div>
          </Layout>
        </Layout>
      </div>

      <Modal
        visible={visibleAddCamera}
        onCancel={() => {
          setVisibleAddCamera(false);
          setKey(Math.random());
        }}
        footer={null}
        okButtonProps={{ style: { display: 'none' } }}
      >
        {visibleAddCamera && (
          <div className="add-camera-component">
            <Tabs key={key} defaultActiveKey="1" onChange={handleChangeTab}>
              <TabPane tab={t('Camera 3/4G')} key="1">
                {keyTab === '1' && (
                  <AddDeviceCamera
                    dispatch={dispatch}
                    addDeviceReturn={addDeviceReturn}
                    activeDeviceReturn={activeDeviceReturn}
                    onRequireActiveDevice={onRequireActiveDevice}
                    onAddDevice={onAddDevice}
                    onUpdate={onUpdateCamera}
                    namespace={namespace}
                    handleAddSuccessful={() => {
                      setVisibleAddCamera(false);
                      setKey(Math.random());
                      setKeyTab('1');
                      return getDeviceByPage(page - 1, pageSize);
                    }}
                  />
                )}
              </TabPane>
              <TabPane tab={t('RTSP Link')} key="2">
                {keyTab === '2' && (
                  <RTSPlinkAddCameraComponent
                    onDone={() => {
                      setVisibleAddCamera(false);
                      setKey(Math.random());
                      setKeyTab('1');
                      return getDeviceByPage(page - 1, pageSize);
                    }}
                    gatewaySerial=""
                  />
                )}
              </TabPane>
              <TabPane tab={t('Offline Camera')} key="3">
                {keyTab === '3' && (
                  <OfflineAndRtmpCameraComponent
                    typeCamera="offline_camera"
                    dispatch={dispatch}
                    checkDeviceReturn={checkExternalDeviceReturn}
                    activeDeviceReturn={activeDeviceReturn}
                    onCheckExternalDevice={onCheckExternalDevice}
                    onAddCamera={onAddCamera}
                    onUpdate={onUpdateCamera}
                    handleAddSuccessful={() => {
                      setVisibleAddCamera(false);
                      setKey(Math.random());
                      setKeyTab('1');
                      return getDeviceByPage(page - 1, pageSize);
                    }}
                  />
                )}
              </TabPane>
              <TabPane tab={t('RTMP Camera')} key="4">
                {keyTab === '4' && (
                  <OfflineAndRtmpCameraComponent
                    typeCamera="rtmp_camera"
                    dispatch={dispatch}
                    checkDeviceReturn={checkExternalDeviceReturn}
                    activeDeviceReturn={activeDeviceReturn}
                    onCheckExternalDevice={onCheckExternalDevice}
                    onAddCamera={onAddCamera}
                    onUpdate={onUpdateCamera}
                    handleAddSuccessful={() => {
                      setVisibleAddCamera(false);
                      setKey(Math.random());
                      setKeyTab('1');
                      return getDeviceByPage(page - 1, pageSize);
                    }}
                  />
                )}
              </TabPane>
            </Tabs>
          </div>
        )}
      </Modal>
    </>
  );
};

export default CameraPageV2;