import { Button, Modal, Table, Tag, Tooltip } from "antd";
import moment from "moment";
import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import { CaretRightOutlined } from '@ant-design/icons';
import { ReactComponent as SettingIcon } from '@/assets/icons/setting-black-icon.svg'
import { useDispatch } from "react-redux";
import { setCameraToSetting } from "@/redux/camera/action";

import './index.scss'
import { CameraStrengthComponent } from "./CameraStrength";
import ViewStreamComponent from "@/components/VideoStream/v2";
import { useFullScreenHandle } from "react-full-screen";
import { VIEW_STREAM_SERVICE_EXTEND } from "@/constants/system.keys";
import { StateTag } from "@/components/StateTag";

const formatResolution = (resolution) => {
  switch (resolution) {
    case 2160:
      return '4K'
    case 1440:
      return '2K'
    case 1080:
      return 'FULL HD'
    case 720:
      return 'HD'
    case 480:
      return 'SD'
    case 108:
      return '108p'
    case 72:
      return '72p'
    default:
      return ''
  }
}

export const CameraListLayout = ({ data, pagination, total, onPageChange, onZoomState, gateways }) => {
  const { t } = useTranslation()
  const dispatch = useDispatch();
  const [visibleStream, setVisibleStream] = useState(null)
  const handleFullScreen = useFullScreenHandle();

  const [forcePlay, setForcePlay] = useState({})
  const [forceMute, setForceMute] = useState({})

  useEffect(() => {
    if (!visibleStream) {
      setForcePlay({})
      setForceMute({})
    }
  }, [visibleStream])

  return (
    <div className="camera-list-layout w-full">
      <Table
        tableLayout="auto"
        size="small"
        columns={[
          {
            dataIndex: 'play',
            key: 'play',
            align: 'center',
            render: (cell, row) => (
              <Button icon={<CaretRightOutlined />} onClick={() => setVisibleStream(row)}> Play stream</Button>
            ),
          },
          {
            title: t('Name'),
            dataIndex: 'name',
            key: 'name',
            align: 'center',
            render: (text) => <span style={{ whiteSpace: 'nowrap' }}>{text || ''}</span>,
          },
          {
            title: t('State'),
            dataIndex: 'state',
            key: 'state',
            align: 'center',
            render: (state) => <StateTag state={state} />
          },
          {
            title: t('Strength'),
            dataIndex: 'strength',
            key: 'strength',
            align: 'center',
            width: '10%',
            render: (strength) => <CameraStrengthComponent strength={strength} />,
          },
          {
            title: t('Resolution'),
            dataIndex: 'resolution',
            key: 'resolution',
            align: 'center',
            render: (resolution) => formatResolution(resolution),
          },
          {
            title: t('FPS'),
            dataIndex: 'fps',
            key: 'fps',
            align: 'center',
            render: (fps) => <span style={{ whiteSpace: 'nowrap' }}>{fps || 0} fps</span>,
          },
          {
            title: t('Address'),
            dataIndex: 'note',
            key: 'note',
            align: 'center',
            render: (note) => (<span>{!note || note === 'undefined' ? '' : note}</span>)
          },
          {
            title: t('Action'),
            dataIndex: 'action',
            key: 'action',
            align: 'center',
            width: 100,
            render: (text, row) => (
              <SettingIcon className='cursor-pointer' width={18} height={18} 
                style={{ color: '#a4a7ae' }}
                onClick={() => dispatch(setCameraToSetting(row))}
              />
            ),
          },
        ]}
        pagination={{
          current: pagination.page,
          total,
          pageSize: pagination.size,
          showSizeChanger: false,
          onChange: (value) => onPageChange(value)
        }}
        dataSource={data || []}
      />

      <Modal
        visible={Boolean(visibleStream)}
        onCancel={() => setVisibleStream(null)}
        footer={null}
        okButtonProps={{ style: { display: 'none' } }}
        title={visibleStream?.name}
        width={800}
        destroyOnClose={true}
      >
        {
          visibleStream && (
            <div className='relative w-full'>
              <ViewStreamComponent
                key={visibleStream.serial}
                allScreen={handleFullScreen.active}
                isViewAll={true}
                zoomState={onZoomState(visibleStream)}
                name={visibleStream.name}
                typeCamera={visibleStream.typeCamera}
                resolution={visibleStream.resolution}
                serviceId={VIEW_STREAM_SERVICE_EXTEND.normal}
                state={visibleStream.state}
                serial={visibleStream.serial}
                gatewaySerial={visibleStream.gatewaySerial}
                thumbnail={visibleStream.thumbnail}
                isInternal={
                  gateways &&
                  gateways.some(
                    (gateway) =>
                      gateway.serial === visibleStream.gatewaySerial
                  )
                }
                permission={visibleStream.permission}
                isAllowStreaming={visibleStream.isAllowStreaming}
                brand={visibleStream.brand || ''}
                cameraSubSources={visibleStream?.subSources}
                cameraMainSource={{
                  zoomState: visibleStream.zoomState,
                  source: visibleStream.source
                }}
                variantPage='camera-v2'
                forceAudio={true}
                // setForcePlay={setForcePlay}
                // forcePlay={forcePlay?.[visibleStream?.serial]}
                setForceMute={setForceMute}
                forceMute={forceMute?.[visibleStream?.serial]}
                showTopName={false}
                allowAudio={true}
                camera={visibleStream}
                pageSize={pagination?.size}
                showBottomName={false}
              />
            </div>
          )
        }
      </Modal>
    </div>
  )
}