import { Table, Tag, Tooltip } from 'antd';
import React from 'react';
import colorsDark from '@/assets/colors/dark';
import { permissionStringToArray } from '../shared';
import { TrashCanIcon } from '@/icons/TrashCan';
import { EditIcon } from '@/icons/Edit';

export const PermissionTable = ({
  dataSource,
  onRemovePermission,
  onEditPermission,
  isLoading,
  footer,
}) => {
  return (
    <Table
      size="middle"
      loading={isLoading}
      dataSource={dataSource}
      footer={footer}
      scroll={{
        y: 'calc(100vh - 304px)',
      }}
      pagination={{
        pageSize: 15,
        total: dataSource.length || 0,
        showSizeChanger: false,
      }}
      columns={[
        {
          title: 'Account group',
          key: 'groupName',
          render: (text, record) => {
            return record.groupName || '-';
          },
        },
        {
          title: 'Account',
          key: 'account',
          render: (text, record) => {
            if (record.groupId > 0 && !record.isChild) {
              return '-';
            }

            return (
              <Tooltip title={record.fullName || '-'}>
                {record.phoneNumber || '-'}
              </Tooltip>
            );
          },
        },
        {
          title: 'Permission',
          key: 'permission',
          render: (text, record) => {
            const permissions = permissionStringToArray(record.permission);

            return (
              <Tooltip title={permissions.join(', ')}>
                <div className="flex gap-1">
                  {permissions.map((permission) => {
                    return (
                      <Tag
                        key={permission}
                        color={colorsDark.$brand}
                        className="m-0"
                      >
                        {permission}
                      </Tag>
                    );
                  })}
                </div>
              </Tooltip>
            );
          },
        },
        {
          title: 'Camera',
          key: 'cameraName',
          render: (text, record) => {
            return record.cameraName;
          },
        },
        {
          title: 'Camera group',
          key: 'deviceGroupName',
          render: (text, record) => {
            return record.deviceGroup ? record.deviceGroup.name : '-';
          },
        },
        {
          title: 'Action',
          key: 'action',
          align: 'center',
          width: 140,
          render: (text, record) => {
            // if its child, operation should be done on parent
            const canEdit = !record.isChild;
            // if its child, operation should be done on parent
            const canRemove = !record.isChild;

            return (
              <div className="flex items-center justify-end gap-2">
                {canEdit && (
                  <div
                    className="text-brand cursor-pointer text-center flex items-center gap-1 justify-center hover:underline"
                    onClick={() => onEditPermission(record)}
                  >
                    <EditIcon className="w-4 h-4" />
                    Edit
                  </div>
                )}
                {canRemove && (
                  <div
                    className="text-error cursor-pointer text-center flex items-center gap-1 justify-center hover:underline"
                    onClick={() => onRemovePermission(record)}
                  >
                    <TrashCanIcon className="w-4 h-4" />
                    Remove
                  </div>
                )}
              </div>
            );
          },
        },
      ]}
    />
  );
};
