import React from 'react';
import { Table, Tag, Tooltip } from 'antd';
import colorsDark from '@/assets/colors/dark';
import { TrashCanIcon } from '@/icons/TrashCan';
import { permissionStringToArray } from '../shared';
import { EditIcon } from '@/icons/Edit';

export const PermissionTable = ({
  dataSource,
  isLoadingDevices,
  pagination,
  onPageChange,
  onRemovePermission,
  onEditPermission,
  total,
}) => {
  return (
    <div className="og2-permission-table-component">
      <Table
        size="middle"
        dataSource={dataSource}
        loading={isLoadingDevices}
        pagination={{
          pageSize: pagination.size,
          current: pagination.page,
          size: 'small',
          onChange: onPageChange,
          showSizeChanger: false,
          total,
        }}
        columns={[
          {
            key: 'name',
            title: 'Camera',
            render: (_, record) => {
              return record.name;
            },
          },
          {
            key: 'deviceGroup',
            title: 'Camera group',
            render: (_, record) => {
              return record.deviceGroup?.name || '_';
            },
          },
          {
            title: 'Permission',
            key: 'permission',
            render: (text, record) => {
              const permissions = permissionStringToArray(record.permission);

              return (
                <Tooltip title={permissions.join(', ')}>
                  <div className="flex gap-1">
                    {permissions.map((permission) => {
                      return (
                        <Tag
                          key={permission}
                          color={colorsDark.$brand}
                          className="m-0"
                        >
                          {permission}
                        </Tag>
                      );
                    })}
                  </div>
                </Tooltip>
              );
            },
          },
          {
            key: 'group',
            title: 'Account group',
            render: (_, record) => {
              return record.group?.name || '_';
            },
          },
          {
            key: 'action',
            title: 'Action',
            align: 'center',
            width: 140,
            render: (_, record) => {
              return (
                <div className="flex items-center gap-2">
                  <div
                    className="text-brand cursor-pointer text-center flex items-center gap-1 justify-center hover:underline"
                    onClick={() => onEditPermission(record)}
                  >
                    <EditIcon className="w-4 h-4" />
                    Edit
                  </div>
                  <div
                    className="text-error cursor-pointer text-center flex items-center gap-1 justify-center hover:underline"
                    onClick={() => onRemovePermission(record)}
                  >
                    <TrashCanIcon className="w-4 h-4" />
                    Remove
                  </div>
                </div>
              );
            },
          },
        ]}
        scroll={{
          y: 'calc(100vh - 248px)',
        }}
      />
    </div>
  );
};
