import React, { useEffect, useMemo, useRef, useState } from 'react';
import moment from 'moment';
import { DatePicker, Modal, Radio } from 'antd';
import { ComputerIcon } from '@/icons/Computer';
import { CloudIcon } from '@/icons/Cloud';
import { PLAYBACK_DATE_FORMAT } from '@/constants/time';

import { PlaybackTree } from '@/components/Tree/Playback';
import { CameraSelector } from '@/components/Tree/Camera/AddCameraToGroup/CameraSelector';
import { EnumPlaybackType } from '@/constants/playback';

import './styles.scss';
import { GroupSelector } from '@/components/Tree/Playback/ListCamera/GroupSelector';
import { RECENT_GROUP_ID, ROOT_GROUP_ID } from '@/constants/group';
import { GroupCameras } from '@/components/Tree/Playback/ListCamera/GroupCameras';
import { ListCamera } from '@/components/Tree/Playback/ListCamera';
import { useDispatch, useSelector } from 'react-redux';
import { fetchCameras } from '@/components/Tree/Playback/AllCamera';
import { nextRequestId } from '@/socket/query';
import {
  LIST_ALL_DEVICE_BY_PAGE,
  LIST_DEVICE_ACTIVE_SERVICE_ID,
  LIST_DEVICE_BY_DEVICE_GROUP_ID,
} from '@/constants/service.types';
import { setTotalCamera, socketEmitEvent } from '@/redux/actions';
import { PlaybackMainSectionMode } from '../Main';
import { usePlaybackContext } from '../context';

export { EnumPlaybackType };

const CAMERA_PAGE_SIZE = 10;

const makeRecentItemKey = (userId, namespace) => {
  return `recent-playback-v2-items-${userId}-${namespace}`;
};

const getLocalRecentItems = (userId, namespace) => {
  try {
    return JSON.parse(
      localStorage.getItem(makeRecentItemKey(userId, namespace)) || '[]',
    );
  } catch (error) {
    return [];
  }
};

const setLocalRecentItems = (userId, namespace, items) => {
  localStorage.setItem(
    makeRecentItemKey(userId, namespace),
    JSON.stringify(items),
  );
};

export const Settings = ({
  selectedGroupId,
  onSelectedGroupIdChange,
  onSelectCamera,
  namespace,
  setCameraSelected,
  currentPage,
  setCurrentPage,
  pageSize,
  setDisplayCameras,
  isLoading,
  setIsLoading,
}) => {
  const [selectedGroup, setSelectedGroup] = useState({
    id: selectedGroupId || RECENT_GROUP_ID,
    name: 'Pinned',
  });
  const [recentItems, setRecentItems] = useState([]);
  const [selectCamera, setSelectCamera] = useState();
  const [dataAllCamera, setDataAllCamera] = useState(null);
  const [dataGroup, setDataGroup] = useState(null);
  const dispatch = useDispatch();
  const { isAuth, userId, cameras, listDeviceByGroupId, totalCamera } =
    useSelector((state) => state);
  const requestIdRef = useRef(null);
  const { displayMode } = usePlaybackContext();
  const finalPageSize = useMemo(() => {
    return displayMode === PlaybackMainSectionMode.FOCUS
      ? CAMERA_PAGE_SIZE
      : pageSize;
  }, [displayMode, pageSize]);

  useEffect(() => {
    return () => {
      setCameraSelected(null);
      setCurrentPage(1);
      setIsLoading(false);
      setDataAllCamera([]);
      setDataGroup(null);
      requestIdRef.current = null;
    };
  }, [setCameraSelected, setCurrentPage, setIsLoading]);

  useEffect(() => {
    if (selectedGroup?.id !== ROOT_GROUP_ID || !isAuth) {
      return;
    }

    const reqId = nextRequestId();
    requestIdRef.current = reqId;
    setIsLoading(true);

    const data = {
      namespace,
      deviceType: 'camera',
      timeRequest: Date.now(),
      page: currentPage - 1,
      size: finalPageSize,
    };
    const dataObj = {
      appServiceType: LIST_ALL_DEVICE_BY_PAGE,
      requestId: reqId,
      body: JSON.stringify(data),
    };

    dispatch(socketEmitEvent(dataObj));
  }, [
    isAuth,
    namespace,
    selectedGroup,
    currentPage,
    dispatch,
    finalPageSize,
    setIsLoading,
  ]);

  useEffect(() => {
    if (
      selectedGroup?.id === RECENT_GROUP_ID ||
      selectedGroup?.id === ROOT_GROUP_ID ||
      !selectedGroup?.id ||
      !isAuth
    ) {
      return;
    }

    const reqId = nextRequestId();
    requestIdRef.current = reqId;
    setIsLoading(true);

    const dataBody = {
      namespace,
      deviceGroupId: selectedGroup.id,
      timeRequest: Date.now(),
    };

    const dataObj = {
      appServiceType: LIST_DEVICE_BY_DEVICE_GROUP_ID,
      requestId: reqId,
      body: JSON.stringify(dataBody),
    };

    dispatch(socketEmitEvent(dataObj));
  }, [selectedGroup, isAuth, namespace, dispatch, setIsLoading, pageSize]);

  useEffect(() => {
    if (!cameras) {
      return;
    }

    if (cameras.requestId === requestIdRef.current) {
      setDataAllCamera(cameras);
      setIsLoading(false);
    }
  }, [cameras]);

  useEffect(() => {
    if (
      listDeviceByGroupId &&
      listDeviceByGroupId.requestId === requestIdRef.current
    ) {
      setDataGroup(listDeviceByGroupId);
      setIsLoading(false);
    }
  }, [listDeviceByGroupId]);

  useEffect(() => {
    setRecentItems(getLocalRecentItems(userId, namespace));
  }, [userId, namespace]);

  useEffect(() => {
    if (!userId || !namespace) {
      return;
    }

    setLocalRecentItems(userId, namespace, recentItems);
  }, [recentItems, userId, namespace]);

  const allCameras = useMemo(() => {
    if (selectedGroup?.id === ROOT_GROUP_ID) {
      return dataAllCamera?.data || [];
    }

    if (selectedGroup?.id === RECENT_GROUP_ID) {
      return recentItems
        .filter((item) => item.type === 'camera')
        .map((item) => item.data);
    }

    return dataGroup?.cameraInfos || [];
  }, [dataAllCamera, dataGroup, selectedGroup, recentItems]);

  useEffect(() => {
    setDisplayCameras(allCameras || []);
  }, [allCameras, setDisplayCameras]);

  const total = useMemo(() => {
    if (selectedGroup?.id === ROOT_GROUP_ID) {
      dispatch(setTotalCamera(dataAllCamera?.totalSize || 0));
      return dataAllCamera?.totalSize || 0;
    }

    if (selectedGroup?.id === RECENT_GROUP_ID) {
      return recentItems.filter((item) => item.type === 'camera').length;
    }

    return dataGroup?.cameraInfos?.length || 0;
  }, [dataAllCamera, dataGroup, selectedGroup, recentItems]);

  const getIsCameraPinned = (serial) => {
    return recentItems.some(
      (item) => item.type === 'camera' && item.data.serial === serial,
    );
  };

  const addCameraToRecent = (camera) => {
    setRecentItems((prev) => {
      const newItems = prev.filter(
        (item) => item.type !== 'camera' || item.data.serial !== camera.serial,
      );

      return [{ data: camera, type: 'camera' }, ...newItems];
    });
  };

  const removeCameraFromRecent = (serial) => {
    setRecentItems((prev) => {
      return prev.filter(
        (item) => item.type !== 'camera' || item.data.serial !== serial,
      );
    });
  };

  const onPinCamera = (cam, pinned) => {
    if (pinned) {
      addCameraToRecent(cam);
      return;
    }

    Modal.confirm({
      title: 'Unpin camera',
      content: 'Are you sure you want to unpin this camera?',
      onOk: () => {
        removeCameraFromRecent(cam.serial);
      },
    });
  };

  const handleSelectCamera = (camera) => {
    setSelectCamera(camera);
    if (onSelectCamera) {
      onSelectCamera(camera);
    }
    if (setCameraSelected) {
      setCameraSelected(camera);
    }
  };

  const handleSelectGroup = (group) => {
    setSelectedGroup(group);
    if (onSelectedGroupIdChange) {
      onSelectedGroupIdChange(group.id);
    }
  };

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const onSearch = () => {
    const timeRequest = new Date().getTime();
    let data = {
      serviceId: 20,
      timeRequest,
      namespace,
      page: 0,
      size: totalCamera || 100,
    };
    let dataObj = {
      appServiceType: LIST_DEVICE_ACTIVE_SERVICE_ID,
      requestId: timeRequest,
      body: JSON.stringify(data),
    };
    return dispatch(socketEmitEvent(dataObj));
  };

  return (
    <aside className="playback-v2-settings flex flex-col items-stretch gap-1">
      {/* <Radio.Group
        onChange={(e) => onPlaybackTypeChange(e.target.value)}
        value={playbackType}
        optionType="button"
        buttonStyle="solid"
        className="radio-group-playback-type"
        options={[
          {
            label: (
              <>
                <ComputerIcon />
                On Gateway
              </>
            ),
            value: EnumPlaybackType.LOCAL,
          },
          {
            label: (
              <>
                <CloudIcon />
                On Cloud
              </>
            ),
            value: EnumPlaybackType.CLOUD,
          },
        ]}
      ></Radio.Group> */}
      <ListCamera
        namespace={namespace}
        cameras={allCameras}
        currentPage={currentPage}
        pageSize={finalPageSize}
        total={total}
        onPageChange={handlePageChange}
        onSearch={onSearch}
        isLoading={isLoading}
        selectedGroup={selectedGroup}
        onSelectGroup={handleSelectGroup}
        getIsCameraPinned={getIsCameraPinned}
        onPinCamera={onPinCamera}
        selectedSerial={selectCamera?.serial}
        onSelectCamera={handleSelectCamera}
      />
    </aside>
  );
};
