import { Spin } from 'antd'
import React, {
  forwardRef,
  useImperativeHandle,
  useRef,
  useEffect,
  useState,
} from 'react'

class Mirror {
  static calculatePos(videoWidth, videoHeight, canvasWidth, canvasHeight) {
    const videoAspect = videoWidth / videoHeight
    const canvasAspect = canvasWidth / canvasHeight

    let renderWidth, renderHeight, x, y

    if (videoAspect > canvasAspect) {
      renderWidth = canvasWidth
      renderHeight = canvasWidth / videoAspect
      x = 0
      y = (canvasHeight - renderHeight) / 2
    } else {
      renderHeight = canvasHeight
      renderWidth = canvasHeight * videoAspect
      x = (canvasWidth - renderWidth) / 2
      y = 0
    }

    return { x, y, width: renderWidth, height: renderHeight }
  }

  static renderFrame(canvas, videoElement, cachedDimensions = null) {
    const ctx = canvas.getContext('2d', {
      alpha: false,
      desynchronized: true
    })
    if (!ctx) return

    const dpr = window.devicePixelRatio || 1
    const w = canvas.clientWidth
    const h = canvas.clientHeight

    if (canvas.width !== w * dpr || canvas.height !== h * dpr) {
      canvas.width = w * dpr
      canvas.height = h * dpr
    }

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)

    const dimensions = cachedDimensions || Mirror.calculatePos(
      videoElement.videoWidth,
      videoElement.videoHeight,
      w,
      h
    )

    ctx.clearRect(0, 0, w, h)

    ctx.imageSmoothingEnabled = true
    ctx.imageSmoothingQuality = 'low'

    ctx.drawImage(videoElement, dimensions.x, dimensions.y, dimensions.width, dimensions.height)

    return dimensions
  }

  static startRenderLoop(canvas, videoElement) {
    let stopped = false
    let isWarmedUp = false
    let frameCount = 0
    let cachedDimensions = null
    let lastVideoWidth = 0
    let lastVideoHeight = 0
    let lastCanvasWidth = 0
    let lastCanvasHeight = 0

    const warmUp = () => {
      if (videoElement.videoWidth > 0 && videoElement.videoHeight > 0) {
        for (let i = 0; i < 3; i++) {
          cachedDimensions = Mirror.renderFrame(canvas, videoElement, cachedDimensions)
        }
        isWarmedUp = true
      }
    }

    setTimeout(warmUp, 0)

    if ('requestVideoFrameCallback' in videoElement) {
      const step = (now, metadata) => {
        if (stopped) return

        if (videoElement.videoWidth !== lastVideoWidth ||
          videoElement.videoHeight !== lastVideoHeight ||
          canvas.clientWidth !== lastCanvasWidth ||
          canvas.clientHeight !== lastCanvasHeight) {
          cachedDimensions = null
          lastVideoWidth = videoElement.videoWidth
          lastVideoHeight = videoElement.videoHeight
          lastCanvasWidth = canvas.clientWidth
          lastCanvasHeight = canvas.clientHeight
        }

        cachedDimensions = Mirror.renderFrame(canvas, videoElement, cachedDimensions)

        frameCount++
        if (frameCount < 5 && !isWarmedUp) {
          warmUp()
        }

        videoElement.requestVideoFrameCallback(step)
      }
      videoElement.requestVideoFrameCallback(step)
    } else {
      let lastRenderTime = 0
      const minFrameTime = 1000 / 60

      const step = (timestamp) => {
        if (stopped) return

        if (timestamp - lastRenderTime < minFrameTime) {
          requestAnimationFrame(step)
          return
        }

        lastRenderTime = timestamp

        if (videoElement.videoWidth !== lastVideoWidth ||
          videoElement.videoHeight !== lastVideoHeight ||
          canvas.clientWidth !== lastCanvasWidth ||
          canvas.clientHeight !== lastCanvasHeight) {
          cachedDimensions = null
          lastVideoWidth = videoElement.videoWidth
          lastVideoHeight = videoElement.videoHeight
          lastCanvasWidth = canvas.clientWidth
          lastCanvasHeight = canvas.clientHeight
        }

        cachedDimensions = Mirror.renderFrame(canvas, videoElement, cachedDimensions)

        frameCount++
        if (frameCount < 5 && !isWarmedUp) {
          warmUp()
        }

        requestAnimationFrame(step)
      }
      requestAnimationFrame(step)
    }

    return () => {
      stopped = true
    }
  }

  static clearCanvas(canvas) {
    const ctx = canvas.getContext('2d')
    if (ctx) {
      ctx.clearRect(0, 0, canvas.width, canvas.height)
    }
  }
}

export const PlayerMirror = forwardRef(
  ({ thumbnail, aspectRatio = 16 / 9, isFullScreen = false, isLoading = false }, ref) => {
    const canvasRef = useRef(null)
    const stopLoopRef = useRef(null)
    const [showThumbnail, setShowThumbnail] = useState(true)
    const isRenderingRef = useRef(false)
    const videoElementRef = useRef(null)
    const resizeTimeoutRef = useRef(null)

    useImperativeHandle(ref, () => ({
      render: (videoElement) => {
        if (!canvasRef.current || !videoElement) return

        if (isRenderingRef.current) {
          return
        }

        if (stopLoopRef.current) {
          stopLoopRef.current()
        }

        videoElementRef.current = videoElement

        const startRendering = () => {
          if (videoElement.readyState >= 2) {
            isRenderingRef.current = true
            stopLoopRef.current = Mirror.startRenderLoop(
              canvasRef.current,
              videoElement
            )
            setShowThumbnail(false)
          } else {
            setTimeout(startRendering, 50)
          }
        }

        startRendering()
      },
      clear: () => {
        if (canvasRef.current) {
          Mirror.clearCanvas(canvasRef.current)
        }
        if (stopLoopRef.current) {
          stopLoopRef.current()
          stopLoopRef.current = null
        }
        isRenderingRef.current = false
        videoElementRef.current = null
        setShowThumbnail(true)
      },
      forceRerender: () => {
        if (canvasRef.current && videoElementRef.current) {
          Mirror.renderFrame(canvasRef.current, videoElementRef.current, null)
        }
      }
    }))

    useEffect(() => {
      if (!canvasRef.current || !isRenderingRef.current) return

      const handleResize = () => {
        if (resizeTimeoutRef.current) {
          clearTimeout(resizeTimeoutRef.current)
        }

        resizeTimeoutRef.current = setTimeout(() => {
          if (canvasRef.current && videoElementRef.current && isRenderingRef.current) {
            Mirror.renderFrame(canvasRef.current, videoElementRef.current, null)
          }
        }, 100)
      }

      handleResize()

      window.addEventListener('resize', handleResize)

      return () => {
        window.removeEventListener('resize', handleResize)
        if (resizeTimeoutRef.current) {
          clearTimeout(resizeTimeoutRef.current)
        }
      }
    }, [isFullScreen])

    useEffect(() => {
      return () => {
        if (stopLoopRef.current) {
          stopLoopRef.current()
          setShowThumbnail(true)
        }
        isRenderingRef.current = false
        videoElementRef.current = null
      }
    }, [])

    useEffect(() => {
      if (canvasRef.current) {
        Mirror.clearCanvas(canvasRef.current)
        setShowThumbnail(true)
      }
    }, [])

    const containerStyle = isFullScreen
      ? {
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
        zIndex: 9999,
      }
      : {
        height: 0,
        paddingBottom: `${(1 / aspectRatio) * 100}%`,
        alignSelf: 'center',
        position: 'relative',
        top: '50%',
      }

    return (
      <div
        className="player-mirror relative bg-black"
        style={containerStyle}
      >
        {isLoading && (
          <div
            className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-50"
            style={{ zIndex: 10 }}
          >
            <Spin size="large" />
          </div>
        )}

        {thumbnail && showThumbnail && (
          <div className="absolute inset-0 z-0 flex items-center justify-center">
            <img
              src={thumbnail}
              alt="thumbnail"
              style={{
                objectFit: 'cover',
                maxWidth: '100%',
                maxHeight: '100%',
                width: '100%',
              }}
            />
          </div>
        )}

        <canvas
          ref={canvasRef}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            zIndex: 1,
            width: '100%',
            height: '100%',
            display: 'block',
            willChange: 'contents',
            imageRendering: 'auto'
          }}
        />
      </div>
    )
  }
)