/* eslint-disable jsx-a11y/accessible-emoji */
import React, { useRef, useEffect, useState, useCallback } from 'react';
import './index.scss';

const PTZDewarp = ({
  videoElement,
  isActive,
  containerWidth,
  containerHeight,
  className,
  onMouseEnter = () => { },
  onMouseLeave = () => { },
  selectedDewarpMode
}) => {

  const canvasRef = useRef(null);
  const glRef = useRef(null);
  const programRef = useRef(null);
  const textureRef = useRef(null);
  const animationFrameRef = useRef(null);

  const [yaw, setYaw] = useState(0); // Pan
  const [pitch, setPitch] = useState(0); // Tilt
  const [roll, setRoll] = useState(0); // Rotate OZ axis
  const [fov, setFov] = useState(90); // Field of view
  const [dewarpMode, setDewarpMode] = useState(1);
  const [isDragging, setIsDragging] = useState(false);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const [forceRender, setForceRender] = useState(0);

  const mapDewarpModeToShader = (mode) => {
    const modeMap = {
      'Original': 0,
      'Rectilinear': 1,
      'Panorama': 2,
      'Cylinder': 3
    };
    return modeMap[mode] !== undefined ? modeMap[mode] : 1;
  };

  useEffect(() => {
    if (selectedDewarpMode !== undefined && selectedDewarpMode !== null) {
      const numericMode = mapDewarpModeToShader(selectedDewarpMode);
      setDewarpMode(numericMode);

      setYaw(0);
      setPitch(0);
      setRoll(0);

      if (numericMode === 2) {
        setFov(120.0);
      } else {
        setFov(90.0);
      }

      const modeNames = ['Original', 'Rectilinear', 'Panorama', 'Cylinder'];
      console.log('Dewarp mode changed:', selectedDewarpMode, '->', modeNames[numericMode]);
    }
  }, [selectedDewarpMode]);

  const vertexShaderSource = `
    attribute vec2 pos;
    varying vec2 uv;
    void main() {
      uv = (pos + 1.0) * 0.5;
      gl_Position = vec4(pos, 0.0, 1.0);
    }
  `;

  const fragmentShaderSource = `
    precision highp float;
uniform sampler2D frame;
uniform float yaw, pitch, roll, fov;
uniform int mode;

varying vec2 uv;

const float PI = 3.14159265359;

mat3 rotateX(float angle) {
  float c = cos(angle);
  float s = sin(angle);
  return mat3(1.0, 0.0, 0.0,
              0.0, c, -s,
              0.0, s, c);
}

mat3 rotateY(float angle) {
  float c = cos(angle);
  float s = sin(angle);
  return mat3(c, 0.0, s,
              0.0, 1.0, 0.0,
              -s, 0.0, c);
}

mat3 rotateZ(float angle) {
  float c = cos(angle);
  float s = sin(angle);
  return mat3(c, -s, 0.0,
              s, c, 0.0,
              0.0, 0.0, 1.0);
}

vec2 directionToFisheye(vec3 dir) {
  float theta = acos(clamp(dir.z, -1.0, 1.0));
  float phi = atan(dir.y, dir.x);
  float r = theta / PI;
  
  vec2 texCoord;
  texCoord.x = 0.5 + r * cos(phi);
  texCoord.y = 0.5 + r * sin(phi);
  
  return texCoord;
}

vec2 rotateTexture(vec2 texCoord, float angle) {
  vec2 centered = texCoord - 0.5;
  float c = cos(angle);
  float s = sin(angle);
  vec2 rotated = vec2(
    centered.x * c - centered.y * s,
    centered.x * s + centered.y * c
  );
  return rotated + 0.5;
}

vec4 modeOriginal() {
  float zoom = tan(radians(fov * 0.5));

  vec2 centered = (uv - 0.5) * zoom;

  float angle = yaw;
  float c = cos(angle);
  float s = sin(angle);

  vec2 rotated = vec2(
    centered.x * c - centered.y * s,
    centered.x * s + centered.y * c
  );

  vec2 texCoord = rotated + 0.5;
  return texture2D(frame, texCoord);
}


vec4 modeRectilinear() {
  vec2 screenPos = uv * 2.0 - 1.0;
  
  float fovRad = fov * PI / 180.0;
  float f = 1.0 / tan(fovRad * 0.5);  
  vec3 dir = normalize(vec3(screenPos.x, screenPos.y, f));
  
  mat3 rotation = rotateX(pitch) * rotateZ(roll);
  dir = rotation * dir;
  
  vec2 texCoord = directionToFisheye(dir);
  texCoord = rotateTexture(texCoord, yaw);
  
  vec2 centered = texCoord - 0.5;
  if (length(centered) > 0.5) {
    return vec4(0.0, 0.0, 0.0, 1.0);
  }
  
  return texture2D(frame, texCoord);
}

vec4 modePanorama() {
  // Apply FOV zoom to UV coordinates
  float zoom = tan(radians(fov * 0.5));
  vec2 zoomedUV = (uv - 0.5) * zoom + 0.5;
  
  // Clamp to valid range
  if (zoomedUV.x < 0.0 || zoomedUV.x > 1.0 || zoomedUV.y < 0.0 || zoomedUV.y > 1.0) {
    return vec4(0.0);
  }
  
  float v = zoomedUV.y;
  float theta = (zoomedUV.x - 0.5) * 2.0 * PI + yaw;

  float r = v * 0.5; // bán kính hemisphere

  vec2 texCoord;
  texCoord.x = 0.5 + r * cos(theta);
  texCoord.y = 0.5 + r * sin(theta);

  if (length(texCoord - 0.5) > 0.5) {
    return vec4(0.0);
  }

  return texture2D(frame, texCoord);
}


vec4 modeCylinder() {
  float zoom = tan(radians(fov * 0.5)); 
  
  vec2 screenPos = (uv * 2.0 - 1.0) * zoom; 
  
  float longitude = screenPos.x * PI;
  float height = screenPos.y;
  
  height += pitch;
  
  vec3 dir;
  dir.x = sin(longitude);
  dir.y = height;
  dir.z = cos(longitude);
  dir = normalize(dir);
  
  mat3 rotation = rotateZ(roll);
  dir = rotation * dir;
  
  vec2 texCoord = directionToFisheye(dir);
  texCoord = rotateTexture(texCoord, yaw);
  
  vec2 centered = texCoord - 0.5;
  if (length(centered) > 0.5) {
    return vec4(0.0, 0.0, 0.0, 1.0);
  }
  
  return texture2D(frame, texCoord);
}

void main() {
  vec4 color;
  
  if (mode == 0) {
    color = modeOriginal();
  } else if (mode == 1) {
    color = modeRectilinear();
  } else if (mode == 2) {
    color = modePanorama();
  } else if (mode == 3) {
    color = modeCylinder();
  } else {
    color = vec4(1.0, 0.0, 1.0, 1.0);
  }
  
  gl_FragColor = color;
}
  `;

  const compileShader = useCallback((gl, type, source) => {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);

    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      console.error('Shader compile error:', gl.getShaderInfoLog(shader));
      gl.deleteShader(shader);
      return null;
    }
    return shader;
  }, []);

  const initWebGL = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const gl = canvas.getContext('webgl');
    if (!gl) {
      console.error('WebGL not supported');
      return;
    }

    glRef.current = gl;

    const vertexShader = compileShader(gl, gl.VERTEX_SHADER, vertexShaderSource);
    if (!vertexShader) return;
    const fragmentShader = compileShader(gl, gl.FRAGMENT_SHADER, fragmentShaderSource);
    if (!fragmentShader) return;

    const program = gl.createProgram();
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);

    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      console.error('Program link error:', gl.getProgramInfoLog(program));
      return;
    }

    gl.useProgram(program);
    programRef.current = program;

    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);

    const posAttrib = gl.getAttribLocation(program, 'pos');
    gl.enableVertexAttribArray(posAttrib);
    gl.vertexAttribPointer(posAttrib, 2, gl.FLOAT, false, 0, 0);

    const texture = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    textureRef.current = texture;

  }, [compileShader, fragmentShaderSource, vertexShaderSource]);

  const render = useCallback(() => {
    if (!videoElement?.src && !videoElement?.srcObject) return;
    const gl = glRef.current;
    const program = programRef.current;
    const texture = textureRef.current;

    if (!gl || !program || !texture || !videoElement) {
      animationFrameRef.current = requestAnimationFrame(render);
      return;
    }

    const canvas = canvasRef.current;
    if (canvas.width !== containerWidth || canvas.height !== containerHeight) {
      canvas.width = containerWidth;
      canvas.height = containerHeight;
      gl.viewport(0, 0, containerWidth, containerHeight);
    }

    gl.clearColor(0.0, 0.0, 0.0, 1.0);
    gl.clear(gl.COLOR_BUFFER_BIT);

    // Kiểm tra cả srcObject (WebRTC) và src (HLS)
    const hasVideoData = videoElement.srcObject || videoElement.src;

    if (hasVideoData && videoElement.readyState >= videoElement.HAVE_CURRENT_DATA) {
      try {
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, videoElement);
      } catch (err) {
        console.error('WebGL texImage2D error:', err);
        if (err.name === 'SecurityError') {
          console.error('CORS issue: Video element needs crossOrigin="anonymous"');
        }
      }
    }

    gl.uniform1f(gl.getUniformLocation(program, 'yaw'), yaw);
    gl.uniform1f(gl.getUniformLocation(program, 'pitch'), pitch);
    gl.uniform1f(gl.getUniformLocation(program, 'roll'), roll);
    gl.uniform1f(gl.getUniformLocation(program, 'fov'), fov);
    gl.uniform1i(gl.getUniformLocation(program, 'mode'), dewarpMode);

    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

    animationFrameRef.current = requestAnimationFrame(render);
  }, [videoElement, containerWidth, containerHeight, yaw, pitch, roll, fov, dewarpMode]);

  useEffect(() => {
    if (!videoElement) return;

    const handleSeeked = () => {
      console.log('Video seeked - forcing render');
      setForceRender(prev => prev + 1);
    };

    const handlePlay = () => {
      console.log('Video playing - forcing render');
      setForceRender(prev => prev + 1);
    };

    videoElement.addEventListener('seeked', handleSeeked);
    videoElement.addEventListener('playing', handlePlay);

    return () => {
      videoElement.removeEventListener('seeked', handleSeeked);
      videoElement.removeEventListener('playing', handlePlay);
    };
  }, [videoElement]);

  useEffect(() => {
    if (isActive && videoElement) {
      initWebGL();
      render();
    }

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [isActive, videoElement, initWebGL, render]);

  const handleMouseDown = (e) => {
    setIsDragging(true);
    lastMousePos.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseMove = (e) => {
    if (!isDragging) return;

    const deltaX = e.clientX - lastMousePos.current.x;
    const deltaY = e.clientY - lastMousePos.current.y;

    setYaw(prev => {
      const newYaw = prev + deltaX * 0.005;
      return newYaw;
    });

    setPitch(prev => {
      const newPitch = prev + deltaY * 0.005;

      switch (dewarpMode) {
        case 0:
          return Math.max(-1.5, Math.min(1.5, newPitch));
        case 1:
          return Math.max(-1.2, Math.min(1.2, newPitch));
        case 2:
          return Math.max(-1.57, Math.min(1.57, newPitch));
        case 3:
          return Math.max(-0.8, Math.min(0.8, newPitch));
        default:
          return newPitch;
      }
    });

    lastMousePos.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleWheel = (e) => {
    e.preventDefault();
    const step = e.deltaY > 0 ? 2 : -2;
    setFov(prev => Math.max(10, Math.min(170, prev + step)));
  };

  // limit zoom
  // const handleWheel = (e) => {
  //   e.preventDefault();
  //   const step = e.deltaY > 0 ? 2 : -2;

  //   setFov(prev => {
  //     const newFov = prev + step;

  //     switch (dewarpMode) {
  //       case 0:
  //         return Math.max(30, Math.min(150, newFov));

  //       case 1:
  //         return Math.max(20, Math.min(120, newFov));

  //       case 2:
  //         return Math.max(60, Math.min(170, newFov));

  //       case 3:
  //         return Math.max(30, Math.min(140, newFov));

  //       default:
  //         return Math.max(10, Math.min(170, newFov));
  //     }
  //   });
  // };


  const handleReset = useCallback(() => {
    setYaw(0);
    setPitch(0);
    setRoll(0);

    switch (dewarpMode) {
      case 2:
        setFov(120);
        break;
      default:
        setFov(90);
    }
  }, [dewarpMode]);

  const handleKeyDown = useCallback((e) => {
    const step = 0.05;
    const fovStep = 2;

    switch (e.key) {
      case 'ArrowLeft': setYaw(prev => prev - step); break;
      case 'ArrowRight': setYaw(prev => prev + step); break;
      case 'ArrowUp': setPitch(prev => prev - step); break;
      case 'ArrowDown': setPitch(prev => prev + step); break;
      case 'a': case 'A': setRoll(prev => prev - step); break;
      case 'd': case 'D': setRoll(prev => prev + step); break;
      case 'z': case 'Z':
        setFov(prev => Math.max(10, prev - fovStep));
        break;
      case 'x': case 'X':
        setFov(prev => Math.min(170, prev + fovStep));
        break;
      case 'r': case 'R': handleReset(); break;
      default: break;
    }
  }, [handleReset]);

  useEffect(() => {
    if (isActive) {
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
    }
  }, [isActive, handleKeyDown]);

  if (!isActive) return null;

  return (
    <div className={`ptz-dewarp-overlay ${className || ''}`}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      <canvas
        ref={canvasRef}
        className="ptz-dewarp-canvas"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onWheel={handleWheel}
        onMouseEnter={onMouseEnter}
      />
    </div>
  );
};

export default PTZDewarp;