import React, { useCallback, useEffect, useState, useMemo } from 'react';
import { EnumPlaybackType, Settings } from './Settings';

import { useDispatch, useSelector } from 'react-redux';
import moment from 'moment';

import { PlaybackMainSection, PlaybackMainSectionMode } from './Main';

import { usePlaybackCameras } from './use-playback-cameras';
import { getPlaybackMode, getSelectedDate } from '../../redux/playback/reducer';
import { setMode, setSelectedDate } from '../../redux/playback/action';

import {
  INACTIVE_PIVOT_TIME,
  usePlaybackProgress,
} from './use-playback-progress';
import { DownloadContext, PlaybackContext } from './context';
import { ProgressBarContext } from './ProgressBar/v3/context';
import { useEvents } from './ProgressBar/v3/use-events';

import './styles.scss';
import Downloader from './downloader';
import { ROOT_GROUP_ID } from '@/constants/group';
import { DEFAULT_PLAYBACK_RATE } from './Main/shared';
import { preloadCodecs } from './Main/PlayerLocal/adapter/rtc-codec';
import { LIST_CAMERA_STORAGE_FILE_DATE } from '@/constants/service.types';
import { socketEmitEvent } from '@/redux/actions';

const emptyCameras = [];

export const PlaybackPageV2 = () => {
  const dispatch = useDispatch();
  const { namespace, camerasDate } = useSelector((state) => state);
  const selectedDate = useSelector(getSelectedDate);
  const initialPlaybackCamera = useSelector(
    (state) => state.initialPlaybackCamera,
  );
  const [selectedCameras, setSelectedCameras] = useState(
    initialPlaybackCamera ? [initialPlaybackCamera] : emptyCameras,
  );
  // const [playbackType, setPlaybackType] = useState<EnumPlaybackType>(
  //   EnumPlaybackType.CLOUD
  // )
  const playbackType = useSelector(getPlaybackMode);
  const [downloader] = useState(() => new Downloader());
  const [selectedGroupId, _setSelectedGroupId] = useState(ROOT_GROUP_ID);
  const [playbackRate, setPlaybackRate] = useState(DEFAULT_PLAYBACK_RATE);
  const [finalSelectedCamera, setFinalSelectedCamera] = useState(null);
  const [selectedEvent, setSelectedEvent] = useState();
  const [onLive, setOnLive] = useState(false);
  const {
    cameraSelections,
    displayMode,
    gridMode,
    page,
    pageSize,
    total,
    setDisplayMode,
    setGridMode,
    setPage,
  } = usePlaybackCameras({
    selectedCameras,
    selectedGroupId,
    namespace,
  });
  const {
    getPivotTime,
    setPivotTime,
    getElapsedTime,
    getCurrentTime,
    onElapsedTimeChange,
    removeProgress,
    reportProgress,
    onPivotTimeChange,
    isActive,
  } = usePlaybackProgress();
  const [selectedCamera, setSelectedCamera] = useState(
    cameraSelections?.[0] || null,
  );

  const selectedSerial = finalSelectedCamera?.serial;

  const [displayCameras, setDisplayCameras] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const serials = useMemo(
    () =>
      (displayMode === PlaybackMainSectionMode.FOCUS
        ? [finalSelectedCamera?.serial]
        : displayCameras?.slice(0, pageSize)?.map((camera) => camera.serial) ||
          []
      )?.filter(Boolean),
    [finalSelectedCamera, displayCameras, displayMode, pageSize],
  );
  const aiEvents = useEvents(selectedDate, serials);
  const [visibleEventTypes, setVisibleEventTypes] = useState(
    aiEvents.eventTypes,
  );

  useEffect(() => {
    setVisibleEventTypes(new Set(aiEvents?.eventTypes || []));
  }, [aiEvents.eventTypes, selectedDate, selectedSerial]);

  useEffect(() => {
    preloadCodecs();
  }, []);

  const setSelectedGroupId = (groupId) => {
    // if (groupId !== ROOT_GROUP_ID) {
    //   setSelectedCameras(emptyCameras);
    // }
    _setSelectedGroupId(groupId);
  };

  const onSelectedDateChange = (date) => {
    dispatch(setSelectedDate(date));
  };

  const setPlaybackType = (type) => {
    dispatch(setMode(type));
  };

  useEffect(() => {
    if (!selectedCamera) {
      setSelectedCamera(cameraSelections?.[0] || null);
    }
  }, [selectedCamera, cameraSelections]);

  useEffect(() => {
    if (selectedCamera) {
      if (Array.isArray(selectedCamera)) {
        if (selectedCamera?.length > 0)
          setFinalSelectedCamera(selectedCamera?.[0]);
      } else {
        setFinalSelectedCamera(selectedCamera);
      }
    } else {
      setFinalSelectedCamera(selectedCamera);
    }
  }, [selectedCamera]);

  const getListStorageDate = useCallback(
    (serial) => {
      let data = {
        serial,
        namespace,
      };
      let dataObj = {
        appServiceType: LIST_CAMERA_STORAGE_FILE_DATE,
        requestId: new Date().getTime(),
        body: JSON.stringify(data),
      };

      dispatch(socketEmitEvent(dataObj));
    },
    [dispatch, namespace],
  );

  useEffect(() => {
    if (finalSelectedCamera?.serial) {
      getListStorageDate(finalSelectedCamera?.serial);
    }
  }, [getListStorageDate, finalSelectedCamera, playbackType]);

  useEffect(() => {
    return () => {
      setFinalSelectedCamera(null);
    };
  }, []);

  const selectedDayEvents = useMemo(() => {
    const selectedDay = moment(selectedDate).format('YYYY-MM-DD');
    return aiEvents.eventHistoryData?.filter((event) => {
      const eventDate = moment(event.timestamp).format('YYYY-MM-DD');
      return eventDate === selectedDay;
    });
  }, [aiEvents, selectedDate]);

  const toggleEventType = (eventType) => {
    setVisibleEventTypes((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(eventType)) {
        newSet.delete(eventType);
      } else {
        newSet.add(eventType);
      }
      return newSet;
    });
  };
  const showAllEventTypes = () =>
    setVisibleEventTypes(new Set(aiEvents?.eventTypes || []));
  const hideAllEventTypes = () => setVisibleEventTypes(new Set());
  const isEventTypeVisible = (eventType) => visibleEventTypes.has(eventType);

  useEffect(() => {
    if (finalSelectedCamera?.serial) {
      setPivotTime(INACTIVE_PIVOT_TIME, false);
    }
  }, [finalSelectedCamera, setPivotTime]);

  useEffect(() => {
    setPivotTime(INACTIVE_PIVOT_TIME, false);
  }, [selectedDate, setPivotTime]);

  const handleSelectCamera = (camera) => {
    setSelectedCameras([camera]);
  };

  return (
    <PlaybackContext.Provider
      value={{
        getPivotTime,
        setPivotTime,
        getElapsedTime,
        getCurrentTime,
        onElapsedTimeChange,
        reportProgress,
        removeProgress,
        onPivotTimeChange,
        isActive,
        playbackRate,
        setPlaybackRate,
        allowPlaybackRate: true || playbackType === EnumPlaybackType.CLOUD,
        onLive,
        setOnLive,
        selectedEvent,
        setSelectedEvent,
        aiEvents,
        totalEvents: aiEvents.totalEvents,
        displayMode,
      }}
    >
      <DownloadContext.Provider value={{ downloader }}>
        <div className="playback-v2">
          <Settings
            namespace={namespace}
            playbackType={playbackType}
            onPlaybackTypeChange={setPlaybackType}
            selectedGroupId={selectedGroupId}
            onSelectedGroupIdChange={setSelectedGroupId}
            onSelectCamera={handleSelectCamera}
            selectedCameras={selectedCameras}
            setSelectedCameras={setSelectedCameras}
            onSelectedCamerasChange={(values) =>
              setSelectedCameras([values?.[values?.length - 1]] || [])
            }
            selectedDate={selectedDate}
            onSelectedDateChange={onSelectedDateChange}
            setCameraSelected={setSelectedCamera}
            selectedCamera={finalSelectedCamera}
            availableCloudDates={camerasDate}
            setCurrentPage={setPage}
            currentPage={page}
            pageSize={pageSize}
            setDisplayCameras={setDisplayCameras}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
          <ProgressBarContext.Provider
            value={{
              eventTypes: aiEvents?.eventTypes || new Set(),
              visibleEventTypes,
              toggleEventType,
              showAllEventTypes,
              hideAllEventTypes,
              isEventTypeVisible,
              selectedDayEvents,
              currentTime: 0,
              initialSelectedDate: selectedDate,
            }}
          >
            <PlaybackMainSection
              cameraSelections={displayCameras}
              selectedDate={selectedDate}
              gridMode={gridMode}
              page={page}
              pageSize={pageSize}
              total={total}
              setDisplayMode={setDisplayMode}
              setGridMode={setGridMode}
              setPage={setPage}
              selectedCamera={finalSelectedCamera}
              setSelectedCameras={setSelectedCameras}
              isLoading={isLoading}
              setDisplayCameras={setDisplayCameras}
            />
          </ProgressBarContext.Provider>
        </div>
      </DownloadContext.Provider>
    </PlaybackContext.Provider>
  );
};
