import { beeXLogger } from '@/helpers/logger';
import {
  getGridSize,
  GridDisplayModeEnum,
} from '../../components/CommonGrid/shared';
import { ROOT_GROUP_ID } from '../../constants/group';
import {
  useGetDevicesByGroupId,
  useListAllDevicesByPage,
} from '../../hooks/socket/cameras';
import { useEffect, useMemo, useState } from 'react';

export const PlaybackMainSectionMode = {
  FOCUS: 'focus',
  GRID: 'grid',
};

export const usePlaybackCameras = ({
  selectedCameras,
  selectedGroupId,
  namespace,
}) => {
  const { send: listAllDevices, data: allCameraResponse } =
    useListAllDevicesByPage();
  const { send: getDevicesByGroupId, data: devicesByGroupIdResponse } =
    useGetDevicesByGroupId();

  const [displayMode, setDisplayMode] = useState(PlaybackMainSectionMode.FOCUS);
  const [gridMode, setGridMode] = useState(GridDisplayModeEnum.TWO);

  const [page, setPage] = useState(1);

  const pageSize =
    displayMode === PlaybackMainSectionMode.FOCUS ? 3 : getGridSize(gridMode);

  useEffect(() => {
    if (selectedCameras.length > 0) {
      return;
    }

    if (selectedGroupId === ROOT_GROUP_ID) {
      listAllDevices({
        namespace: namespace,
        page: page - 1,
        size: pageSize,
        timeRequest: Date.now(),
        tag: 'playback',
        deviceType: 'camera',
      });
    } else {
      beeXLogger.debug('getDevicesByGroupId: ', {
        namespace: namespace,
        page: page - 1,
        size: pageSize,
        deviceGroupId: selectedGroupId,
        timeRequest: Date.now(),
      });
      getDevicesByGroupId({
        namespace: namespace,
        page: page - 1,
        size: pageSize,
        deviceGroupId: selectedGroupId,
        timeRequest: Date.now(),
      });
    }
  }, [
    selectedGroupId,
    selectedCameras.length,
    namespace,
    pageSize,
    page,
    listAllDevices,
    getDevicesByGroupId,
  ]);

  const cameraSelections = useMemo(() => {
    if (selectedCameras && selectedCameras?.filter(Boolean).length > 0) {
      return selectedCameras;
    }

    if (selectedGroupId === ROOT_GROUP_ID) {
      return allCameraResponse?.devices || [];
    }
    return devicesByGroupIdResponse?.deviceGroup?.devices || [];
  }, [
    selectedCameras,
    devicesByGroupIdResponse,
    selectedGroupId,
    allCameraResponse,
  ]);

  const total = useMemo(() => {
    if (selectedGroupId === ROOT_GROUP_ID) {
      return allCameraResponse?.total || 0;
    }

    return devicesByGroupIdResponse?.total || 0;
  }, [selectedGroupId, allCameraResponse, devicesByGroupIdResponse]);

  useEffect(() => {
    setPage(1);
  }, [selectedGroupId]);

  return {
    total,
    cameraSelections: cameraSelections?.filter(Boolean),
    displayMode,
    gridMode,
    setDisplayMode,
    setGridMode,
    page,
    setPage,
    pageSize,
  };
};
