import {
  PLAYBACK_DATE_FORMAT,
  PLAYBACK_DATE_TIME_FORMAT,
} from '../../constants/time'
import moment from 'moment'

export const computeQueryTime = (day, pivotTime) => {
  return moment(day, PLAYBACK_DATE_FORMAT)
    .startOf('day')
    .add(pivotTime, 'seconds')
    .format(PLAYBACK_DATE_TIME_FORMAT)
}
