import React, { useEffect, useMemo, useReducer } from 'react';
import './styles.scss';
import { Button, InputNumber, Select } from 'antd';
import { ShareAltOutlined } from '@ant-design/icons';
import { AccountGroupSelector } from '@/components/AccountGroupSelector';
import { PERMISSIONS } from '../shared';

const TYPE = {
  Group: 'group',
  Member: 'member',
};

const TYPE_OPTIONS = [
  {
    label: 'Group members',
    value: TYPE.Group,
  },
  {
    label: 'Member',
    value: TYPE.Member,
  },
];

const initialState = {
  type: null,
  duration: 0,
  permission: [],
};

const reducer = (state = initialState, action) => {
  switch (action.type) {
    case 'setType':
      return { ...state, type: action.payload };
    case 'setDuration':
      return { ...state, duration: action.payload };
    case 'setPermission':
      return { ...state, permission: action.payload };
    case 'setGroupId':
      return { ...state, groupId: action.payload };
    case 'setAccountId':
      return {
        ...state,
        accountId: action.payload,
      };
    case 'reset':
      return initialState;
    default:
      return state;
  }
};

export const SharePermission = ({
  namespace,
  active,
  onActive,
  onCancel,
  onSubmit,
  disabled,
  loading,
  accounts,
  loadingAccounts,
}) => {
  const [state, dispatch] = useReducer(reducer, initialState);

  const isInvalid = useMemo(() => {
    if (!state.type) {
      return true;
    }

    if (state.type === TYPE.Group && !state.groupId) {
      return true;
    }

    if (state.type === TYPE.Member && !state.accountId) {
      return true;
    }

    if (state.permission.length === 0) {
      return true;
    }

    return false;
  }, [state]);

  useEffect(() => {
    if (!active) {
      dispatch({ type: 'reset' });
    }
  }, [active]);

  const accountOptions = useMemo(() => {
    return accounts?.map((account) => ({
      label: `${account.username} (${account.fullName})`,
      value: account.accountId,
    }));
  }, [accounts]);

  const permissionOptions = useMemo(() => {
    return PERMISSIONS.map((permission) => ({
      label: permission,
      value: permission,
    }));
  }, []);

  if (!active) {
    return (
      <div className="flex justify-end">
        <Button
          type="primary"
          onClick={onActive}
          icon={<ShareAltOutlined />}
          disabled={disabled}
        >
          Share access permission
        </Button>
      </div>
    );
  }

  return (
    <div className="og2-share-permission">
      <Select
        options={TYPE_OPTIONS}
        onChange={(value) => dispatch({ type: 'setType', payload: value })}
        value={state.type}
        placeholder="Select type"
      />
      <div>
        {state.type === TYPE.Group && (
          <AccountGroupSelector
            namespace={namespace}
            onSelect={(value) =>
              dispatch({ type: 'setGroupId', payload: value })
            }
            selectedId={state.groupId}
          />
        )}

        {state.type === TYPE.Member && (
          <Select
            loading={loadingAccounts}
            options={accountOptions}
            placeholder="Select member"
            showSearch
            filterOption={(input, option) =>
              option.label.toLowerCase().indexOf(input.toLowerCase()) >= 0
            }
            value={state.accountId}
            onChange={(value) =>
              dispatch({ type: 'setAccountId', payload: value })
            }
          />
        )}
      </div>

      {state.type ? (
        <Select
          mode="tags"
          placeholder="Select permissions"
          options={permissionOptions}
          maxTagCount={2}
          value={state.permission}
          onChange={(value) =>
            dispatch({ type: 'setPermission', payload: value })
          }
        />
      ) : (
        <div />
      )}
      {state.type ? (
        <InputNumber
          min={0}
          placeholder="Please enter day"
          value={state.duration}
          formatter={(value) => `${value || ''} Day`}
          parser={
            (value) => value.replace(/Da|D|Dy|a|ay|y|Day/g, '').trim()
            // Xử lý khi bấm backspace
          }
          onChange={(value) => {
            dispatch({ type: 'setDuration', payload: value });
          }}
        />
      ) : (
        <div />
      )}
      <div className="flex gap-2 justify-end">
        <Button onClick={onCancel}>Cancel</Button>
        <Button
          type="primary"
          onClick={() => onSubmit(state)}
          loading={loading}
          icon={<ShareAltOutlined />}
          disabled={isInvalid}
        >
          Share
        </Button>
      </div>
    </div>
  );
};
