import { base64ToUnit8Array, stringToUnit8Array } from '../../../helpers/common'

export const createCredential = async (challenge, username) => {
  try {
    const credential = await navigator.credentials.create({
      publicKey: {
        challenge: base64ToUnit8Array(challenge),
        rp: { name: 'Cloud Camera' },
        user: {
          id: stringToUnit8Array(username),
          name: username,
          displayName: username,
        },
        pubKeyCredParams: [
          { type: 'public-key', alg: -7 },
          { type: 'public-key', alg: -257 },
        ],
        authenticatorSelection: {
          // authenticatorAttachment: 'platform',
          requireResidentKey: false,
          userVerification: 'preferred',
        },
      },
      signal: AbortSignal.timeout(60000),
      timeout: 60000, // 60s
      attestation: 'none',
    });

    return credential || null;
  } catch (error) {
    console.warn(error);
    return null;
  }
}
