import { useAdvanceSearch } from '@/hooks/socket/cameras';
import { useEffect, useMemo, useState } from 'react';

export const useAdvancedSearch = ({ namespace }) => {
  const [search, setSearch] = useState('');
  const isSearchActive = search.length > 0;

  const handleSearch = (value) => {
    setSearch(value);
  };

  const { data: searchAccountData, isLoading, send } = useAdvanceSearch();

  useEffect(() => {
    if (!search) {
      return;
    }

    send({
      applicationType: 'account',
      input: search,
      namespace,
      timeRequest: Date.now(),
      page: 0,
      size: 20,
    });
  }, [search, send]);

  const reSearch = () => {
    if (!search) {
      return;
    }

    send({
      applicationType: 'account',
      input: search,
      namespace,
      timeRequest: Date.now(),
      page: 0,
      size: 20,
    });
  };

  const searchResult = useMemo(() => {
    if (!searchAccountData) {
      return [];
    }

    const duplicate =
      searchAccountData.records.TbAccount?.concat(
        searchAccountData.records.TbAccountNamespace ?? []
      ) || [];

    return Array.from(
      new Map(duplicate.map((item) => [item.accountId, item])).values()
    );
  }, [searchAccountData]);

  return {
    search,
    isSearchActive,
    searchResult,
    isLoading,
    handleSearch,
    reSearch,
  };
};
