import {
    parseResponseBody,
    prepareBody,
    requestSocketPromise,
    requestSocketPromiseWithTimeout,
} from '../../socket/query'
import * as SERVICE from '../../constants/service.types'
import { beeXLogger } from '@/helpers/logger'

export const getListCustomerRole = async (input) => {
    beeXLogger.debug("🚀 ~ RoleSocket ~ getListCustomerRole ~ input:", input)
    const response = await requestSocketPromiseWithTimeout({
        appServiceType: SERVICE.LIST_CUSTOMER_ROLE,
        body: prepareBody(input),
    }, { timeout: 5000 })
    beeXLogger.debug("🚀 ~ RoleSocket ~ getListCustomerRole ~ response: ", parseResponseBody(response))
    return parseResponseBody(response)
}

