import React, { useMemo } from 'react';
import { useSocketQuery } from '@/socket/useSocketRequest';
import * as SERVICE from '@/constants/service.types';
import { Select } from 'antd';

export const AccountGroupSelector = ({
  namespace,
  selectedId,
  onSelect,
  size,
}) => {
  const { data: groupData, isLoading: isLoadingGroup } = useSocketQuery(
    {
      namespace,
    },
    {
      appServiceType: SERVICE.LIST_GROUP_MEMBER,
      disabled: !namespace,
    }
  );

  const options = useMemo(() => {
    return groupData?.map((item) => ({
      label: item.name,
      value: item.id,
    }));
  }, [groupData]);

  return (
    <Select
      size={size}
      placeholder="Select group member"
      options={options}
      loading={isLoadingGroup}
      onChange={onSelect}
      onSelect={onSelect}
      showSearch
      filterOption={(input, option) =>
        option.label.toLowerCase().indexOf(input.toLowerCase()) >= 0
      }
    />
  );
};
