export const SET_SELECTED_NOTIFICATION = 'NOTIFICATION:SET_SELECTED_NOTIFICATION';
export const SET_NOTIFICATION_FILTER = 'NOTIFICATION:SET_NOTIFICATION_FILTER';
export const RESET_NOTIFICATION_FILTER = 'NOTIFICATION:RESET_NOTIFICATION_FILTER';
export const SET_JUST_UPDATED_NOTIFICATION = 'NOTIFICATION:SET_JUST_UPDATED_NOTIFICATION';

export const setSelectedNotification = (payload) => ({
    type: SET_SELECTED_NOTIFICATION,
    payload,
});

export const setNotificationFilter = (payload) => ({
    type: SET_NOTIFICATION_FILTER,
    payload,
});

export const resetNotificationFilter = (payload = {}) => ({
    type: SET_NOTIFICATION_FILTER,
    payload,
});


export const setJustUpdatedNotifications = (payload) => ({
    type: SET_JUST_UPDATED_NOTIFICATION,
    payload,
});