import React from 'react';

export const TimelineTooltip = ({
  tooltipRef,
  tooltipThumbnailRef,
  tooltipTimeRef,
  hasThumbnail
}) => {
  return (
    <div
      ref={tooltipRef}
      className={`absolute z-50 hidden select-none pointer-events-none ${hasThumbnail ? '-top-36' : '-top-5'}`}
      style={{
        left: '0px',
        transform: `translateX(-50%)`,
      }}
    >
      <div className="flex flex-col items-center">
        <img
          ref={tooltipThumbnailRef}
          src=""
          alt="thumb"
          className="w-48 h-32 object-cover rounded-md mb-1 hidden z-50"
          style={{
            border: '2px solid #028fd5'
          }}
        />
        <div
          ref={tooltipTimeRef}
          className="whitespace-nowrap rounded-md bg-bg2 px-3 py-1.5 text-sm text-textButton shadow-lg z-10"
        />
      </div>
    </div>
  );
};
