/* eslint-disable react-hooks/exhaustive-deps */
import { AI_WARNING_EVENT_TYPE, NOTIFICATION_LEVEL, NOTIFICATION_TYPE } from "@/constants/notification.keys";
import { Card, Col, Row, Tag } from "antd";
import React, { useCallback, useMemo, useState } from "react";
import { RightOutlined, ClockCircleOutlined } from '@ant-design/icons';
import { NotificationLevelTag, NotificationStatusTag } from "../NotificationTag";
import { useDispatch, useSelector } from "react-redux";
import { setSelectedNotification } from "@/redux/notification/action";
import { useTranslation } from "react-i18next";
import { socketEmitEvent } from "@/redux/actions";
import * as SERVICE from '@/constants/service.types';
import moment from "moment";

import AlertNotificationIcon from '@/assets/icons/alert.svg';
import EventObjectDetectionIcon from '@/assets/icons/event_detect.svg';
import SystemAlertIcon from '@/assets/icons/System_Alerts.svg';
import DisconnectedDeviceIcon from '@/assets/icons/disconnect_device.svg'
import './index.scss';

const ICON_MAP = {
    [NOTIFICATION_TYPE.INTRUDER_DETECTION]: EventObjectDetectionIcon,
    [NOTIFICATION_TYPE.APPROACH_VIRTUAL_FENCE]: EventObjectDetectionIcon,
    [NOTIFICATION_TYPE.CROWDED_DETECTION]: EventObjectDetectionIcon,
    [NOTIFICATION_TYPE.CAMERA_OBSCURED]: EventObjectDetectionIcon,
    [NOTIFICATION_TYPE.DANGEROUS_OBJECT_DETECTION]: EventObjectDetectionIcon,
    [NOTIFICATION_TYPE.REQUIRE_CHANGE_PASSWORD]: SystemAlertIcon,
    [NOTIFICATION_TYPE.DISCONNECTED_DEVICE]: DisconnectedDeviceIcon,
    [NOTIFICATION_TYPE.DEVICE_DISCONNECTION]: DisconnectedDeviceIcon,
    [NOTIFICATION_TYPE.DEVICE_HARDWARE_WARNING]: DisconnectedDeviceIcon,
    [NOTIFICATION_TYPE.DEVICE_SOFTWARE_WARNING]: DisconnectedDeviceIcon,
};

const NotificationCard = ({ notification }) => {
    const dispatch = useDispatch();
    const { namespace } = useSelector(state => state);
    const { t } = useTranslation();

    const [requestId, setRequestId] = useState(Date.now());

    const extraInfo = useMemo(() => JSON.parse(notification?.extraInfo || "{}"), [notification]);

    const updateStatus = useCallback(() => {
        if (notification.status !== 1) return notification;

        const newRequestId = Date.now();
        const updatedNotification = { ...notification, status: 3 };

        const body = {
            timeRequested: newRequestId,
            notificationId: notification.id,
            status: 3,
            namespace,
        };

        dispatch(socketEmitEvent({
            appServiceType: SERVICE.UPDATE_NOTIFICATION,
            requestId: newRequestId,
            body: JSON.stringify(body),
        }));

        setRequestId(newRequestId);
        return updatedNotification;
    }, [namespace, notification, dispatch]);

    const getListAlert = useCallback(() => {
        if (namespace) {
            let dataBody = {
                namespace,
                deviceTypeId: (notification && notification?.deviceTypeId) || 3,
            };
            let dataObj = {
                appServiceType: SERVICE.LIST_ALERT,
                requestId: new Date().getTime(),
                body: JSON.stringify(dataBody),
            };
            dispatch(socketEmitEvent(dataObj));
        }
    }, [namespace, notification, dispatch]);

    const renderPrefixIcon = useCallback(() => {
        const icon = ICON_MAP[notification?.type] || AlertNotificationIcon;
        return (
            <img
                style={{ height: 'fit-content', marginTop: 6 }}
                src={icon}
                alt=""
            />
        );
    }, [notification]);

    const renderInfo = useCallback(() => {
        if (!notification) return null;

        const { type, level, taskStatus } = notification;
        const showAiTag = AI_WARNING_EVENT_TYPE.includes(type);
        const showImageTag = !!extraInfo?.imageUrl;
        const showVideoTag = !!extraInfo?.actionTime && !!extraInfo?.serial;
        let tags = []
        if (!!notification?.tags) {
            tags = notification?.tags.split(';') || []
        }

        return (
            <div className="flex flex-col gap-2">
                <div className="flex gap-1 flex-wrap">
                    <NotificationLevelTag level={level} />
                    <NotificationStatusTag taskStatus={taskStatus} />
                    {showAiTag && <Tag color="#e14dd7">{t('AI Detection')}</Tag>}
                    {showImageTag && <Tag color="#028fd5">{t(('Image'))}</Tag>}
                    {showVideoTag && <Tag color="#1757b7">{t('Video')}</Tag>}
                </div>
                <div className="flex gap-1 flex-wrap">
                    {tags?.length > 0 && (
                        tags.map(tag => <Tag color="#0a3d88">{t(tag)}</Tag>)
                    )}
                </div>
            </div>
        );
    }, [notification, extraInfo, t]);

    const renderExtraInfo = useCallback(() => {
        if (!extraInfo) return null;

        if (AI_WARNING_EVENT_TYPE.includes(notification?.type)) return null;

        const imageUrl = extraInfo?.imageUrl || extraInfo?.originPathFile;
        return imageUrl ? (
            <img
                src={imageUrl}
                className="w-full h-auto object-cover"
                alt="warning_camera"
            />
        ) : null;
    }, [notification, extraInfo]);

    const cardClassname = useMemo(() => {
        const statusClass = notification?.status !== 1 ? 'notification-old' : '';
        const levelMap = {
            [NOTIFICATION_LEVEL.VERY_HIGH]: 'notification-very-high',
            [NOTIFICATION_LEVEL.HIGH]: 'notification-high',
            [NOTIFICATION_LEVEL.NORMAL]: 'notification-medium',
            [NOTIFICATION_LEVEL.LOW]: 'notification-low',
        };
        const levelClass = levelMap[notification?.level] || 'notification-high';
        return `${statusClass} ${levelClass}`;
    }, [notification]);

    const onClickCard = useCallback(() => {
        const updated = updateStatus();
        dispatch(setSelectedNotification({
            ...updated,
            prefixIcon: renderPrefixIcon(),
        }));
        getListAlert()
    }, [updateStatus, dispatch, renderPrefixIcon, getListAlert]);

    return (
        <Card
            key={notification?.id + notification?.status}
            className={`w-full cursor-pointer rounded-md notification-card ${cardClassname}`}
            onClick={onClickCard}
        >
            <Row>
                <Col span={1} className="flex justify-center">{renderPrefixIcon()}</Col>
                <Col span={18} className="flex flex-col gap-1">
                    <div>
                        <div className="text-base font-medium">{notification?.content}</div>
                    </div>
                    {renderInfo()}
                    <div className="notification-time">
                        <ClockCircleOutlined />
                        <span>{moment(extraInfo?.actionTime || notification?.createdAt).format('HH:mm:ss DD-MM-YYYY')}</span>
                    </div>

                </Col>
                <Col span={4}>{renderExtraInfo()}</Col>
                <Col span={1} className="flex items-center justify-end">
                    <RightOutlined />
                </Col>
            </Row>
        </Card>
    );
};

export default NotificationCard;
