import { Input, Table } from 'antd';
import React, { useMemo, useState } from 'react';
import './styles.scss';

export const UsersTable = ({
  accounts,
  isLoadingAccounts,
  selectedAccountId,
  onSelectAccountId,
}) => {
  console.log({
    accounts,
    isLoadingAccounts,
  });
  const [search, setSearch] = useState('');

  const dataSource = useMemo(() => {
    const filteredAccounts =
      accounts?.filter((account) => {
        return (
          account.fullName?.toLowerCase().includes(search.toLowerCase()) ||
          account.phonenumber?.toLowerCase().includes(search.toLowerCase()) ||
          account.email?.toLowerCase().includes(search.toLowerCase())
        );
      }) || [];

    return (
      filteredAccounts.map((account) => ({
        ...account,
        key: account.accountId,
      })) || []
    );
  }, [accounts, search]);

  return (
    <div className="og2-users-table-component">
      <div className="mb-3">
        <Input.Search
          placeholder="Search user"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>
      <Table
        size="middle"
        dataSource={dataSource}
        columns={columns}
        loading={isLoadingAccounts}
        pagination={{
          pageSize: 15,
          size: 'small',
        }}
        rowSelection={{
          type: 'radio',
          selectedRowKeys: [selectedAccountId],
          onChange: (keys, row) => {
            onSelectAccountId(keys[0]);
          },
        }}
        scroll={{
          y: 'calc(100vh - 240px)',
        }}
      />
    </div>
  );
};

const columns = [
  {
    title: 'Full Name',
    dataIndex: 'fullName',
    key: 'fullName',
    render: (cell, row) => {
      return <div>{cell ? cell : '_'}</div>;
    },
  },
  {
    title: 'Phone Number',
    dataIndex: 'phonenumber',
    key: 'phonenumber',
  },
];
