/* eslint-disable react-hooks/exhaustive-deps */
import { DatePicker, Layout, Modal, Tabs } from 'antd';
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import * as SERVICE from '../../constants/service.types';
import { socketEmitEvent } from '../../redux/actions';
import './index.scss';
import { ListCamera } from '@/components/Tree/Camera/ListCamera';
import { RECENT_GROUP_ID } from '@/constants/group';
import './index.scss';
import BackupStorageVideoComponent from './BackupStorageVideoComponent';
import moment from 'moment';
import { BackupTaskSchedule } from './BackupTaskSchedule';

const { Sider } = Layout;

const makeRecentItemKey = (userId, namespace) => {
  return `recent-camera-items-${userId}-${namespace}`;
};

const getLocalRecentItems = (userId, namespace) => {
  try {
    return JSON.parse(
      localStorage.getItem(makeRecentItemKey(userId, namespace)) || '[]',
    );
  } catch (error) {
    return [];
  }
};

const setLocalRecentItems = (userId, namespace, items) => {
  console.log('local-items', items);
  localStorage.setItem(
    makeRecentItemKey(userId, namespace),
    JSON.stringify(items),
  );
};

export const BACKUP_STORAGE_PAGE = 'service/advance-backup';
const SERVICE_ID = 20;

export const BackupStorage = ({
  variantPage = '',
  customSelectedCamera,
  selectedDate,
}) => {
  const { t } = useTranslation();
  const dispatch = useDispatch();
  const {
    userId,
    isAuth,
    cameras: pageCameras,
    namespace,
  } = useSelector((state) => state);

  const [requestId, setRequestId] = useState(new Date().getTime());
  const [selectCamera, setSelectCamera] = useState();
  const [customCameras, setCustomCamera] = useState();
  const [dataSearchCamera, setDataSearchCamera] = useState();
  const { devicesActiveOfServices, totalCamera } = useSelector(
    (state) => state,
  );
  const [currentTab, setCurrentTab] = useState('1');
  const [dateRecord, setDateRecord] = useState(null);

  useEffect(() => {
    return () => {
      setSelectCamera(null);
      setCustomCamera(null);
      setRequestId(new Date().getTime());
      setDataSearchCamera(null);
      setCurrentTab('1');
      setDateRecord(null);
    };
  }, []);

  useEffect(() => {
    if (variantPage === 'playback') {
      setDateRecord(null);
      return;
    }

    if (selectedDate) {
      const nextDate = moment(selectedDate);
      setDateRecord(nextDate.isValid() ? nextDate : null);
    } else {
      setDateRecord(null);
    }
  }, [selectedDate, variantPage]);

  useEffect(() => {
    if (customSelectedCamera) return;
    const timeRequest = new Date().getTime();
    let data = {
      serviceId: SERVICE_ID,
      timeRequest,
      namespace,
      page: 0,
      size: totalCamera || 100,
    };
    console.log('data: ', data);
    let dataObj = {
      appServiceType: SERVICE.LIST_DEVICE_ACTIVE_SERVICE_ID,
      requestId: timeRequest,
      body: JSON.stringify(data),
    };
    return dispatch(socketEmitEvent(dataObj));
  }, [namespace, totalCamera]);

  useEffect(() => {
    if (devicesActiveOfServices) {
      if (devicesActiveOfServices?.devices?.length > 0) {
        setCustomCamera(devicesActiveOfServices?.devices || null);
      }
    }
  }, [devicesActiveOfServices]);

  useEffect(() => {
    if (customCameras?.length > 0) {
      console.log('customCameras: ', customCameras);
    }
  }, [customCameras]);

  useEffect(() => {
    if (pageCameras) {
      if (pageCameras.data?.length === 1) {
        setSelectCamera(pageCameras.data?.[0]);
      }
    }
  }, [pageCameras]);

  const getDeviceByPage = useCallback(
    (page, size, dataSearch) => {
      let data = {
        namespace,
        deviceType: 'camera',
        timeRequest: requestId,
        page,
        size,
      };
      if (dataSearch) {
        data.name = dataSearch;
      }
      let dataObj = {
        appServiceType: SERVICE.LIST_ALL_DEVICE_BY_PAGE,
        requestId,
        body: JSON.stringify(data),
      };
      return dispatch(socketEmitEvent(dataObj));
    },
    [dispatch, namespace, requestId],
  );
  useEffect(() => {
    if (isAuth === 1 && namespace && !customSelectedCamera) {
      getDeviceByPage(0, 10, dataSearchCamera);
    }
  }, [getDeviceByPage, isAuth, namespace, customSelectedCamera]);

  const [recentItems, setRecentItems] = useState([]);
  const [selectedGroup, setSelectedGroup] = useState({ id: RECENT_GROUP_ID });

  useEffect(() => {
    setRecentItems(getLocalRecentItems(userId, namespace));
  }, [userId, namespace]);

  useEffect(() => {
    console.log('recentItems', recentItems);
    console.log('local-items', getLocalRecentItems(userId, namespace));
    if (!userId || !namespace) {
      return;
    }

    setLocalRecentItems(userId, namespace, recentItems);
  }, [recentItems, userId, namespace]);

  const addCameraToRecent = (camera) => {
    setRecentItems((prev) => {
      const newItems = prev.filter(
        (item) => item.type !== 'camera' || item.data.serial !== camera.serial,
      );

      return [{ data: camera, type: 'camera' }, ...newItems];
    });
  };

  const removeCameraFromRecent = (serial) => {
    setRecentItems((prev) => {
      return prev.filter(
        (item) => item.type !== 'camera' || item.data.serial !== serial,
      );
    });
  };

  const getIsCameraPinned = (serial) => {
    return recentItems.some(
      (item) => item.type === 'camera' && item.data.serial === serial,
    );
  };

  const onPinCamera = (cam, pinned) => {
    if (pinned) {
      addCameraToRecent(cam);

      return;
    }

    Modal.confirm({
      title: 'Unpin camera',
      content: 'Are you sure you want to unpin this camera?',
      onOk: () => {
        removeCameraFromRecent(cam.serial);
      },
    });
  };

  useEffect(() => {
    if (variantPage === 'playback' && customSelectedCamera) {
      setSelectCamera(customSelectedCamera);
    }
  }, [variantPage, customSelectedCamera]);

  const cameraTreeRef = useRef();

  const onViewDetail = (record) => {
    if (!record) return;

    let body = record.body;
    if (typeof body === 'string') {
      try {
        body = JSON.parse(body);
      } catch (error) {
        body = {};
      }
    }

    const serial = body?.serial || record.serial;
    const recordDate = body?.recordDate || record.recordDate;

    const camera =
      customCameras?.find((cam) => cam.serial === serial) ||
      devicesActiveOfServices?.devices?.find((cam) => cam.serial === serial);

    if (camera) {
      setSelectCamera(camera);
    }

    setCurrentTab('1');

    if (recordDate) {
      const pickedDate = moment(recordDate);
      setDateRecord(pickedDate.isValid() ? pickedDate : null);
    }
  };

  return (
    <div className="backup-storage-tab">
      <Tabs
        activeKey={currentTab}
        onChange={setCurrentTab}
        tabBarExtraContent={
          <DatePicker
            className="picker"
            format="DD-MM-YYYY"
            allowClear
            placeholder={t('Select date')}
            value={dateRecord}
            disabled={currentTab === '1' ? !selectCamera?.serial : false}
            style={{
              width: '255px',
              marginLeft: '20px',
              height: '32px',
              marginRight: '20px',
            }}
            onChange={(value) => setDateRecord(value || null)}
          />
        }
      >
        <Tabs.TabPane tab={'Videos'} key="1">
          <Layout>
            {variantPage !== 'playback' && (
              <Sider
                width={324}
                style={{ paddingLeft: '16px', paddingTop: '12px' }}
              >
                <ListCamera
                  getIsCameraPinned={getIsCameraPinned}
                  onPinCamera={onPinCamera}
                  onSelectCamera={setSelectCamera}
                  selectedGroup={selectedGroup}
                  selectedSerial={selectCamera?.serial}
                  onSelectGroup={setSelectedGroup}
                  namespace={namespace}
                  cameras={customCameras || []}
                  onCameraRemoved={(groupId, serial) => {
                    if (
                      cameraTreeRef.current &&
                      cameraTreeRef.current.markDirty
                    ) {
                      cameraTreeRef.current.markDirty(groupId);
                    }
                  }}
                  variantPage={BACKUP_STORAGE_PAGE}
                />
              </Sider>
            )}
            <Layout style={{ padding: '0 8px' }}>
              <BackupStorageVideoComponent
                dispatch={dispatch}
                setSelect={setSelectCamera}
                serial={selectCamera && selectCamera.serial}
                permission={selectCamera && selectCamera.permission}
                selectCamera={selectCamera}
                variantPage={BACKUP_STORAGE_PAGE}
                dateRecord={dateRecord}
              />
            </Layout>
          </Layout>
        </Tabs.TabPane>
        <Tabs.TabPane tab={'Event jobs'} key="2">
          <BackupTaskSchedule
            namespace={namespace}
            selectedDate={dateRecord}
            devicesActiveOfServices={devicesActiveOfServices?.devices}
            customSelectedCamera={customSelectedCamera}
            variantPage={variantPage}
            onViewDetail={onViewDetail}
          />
        </Tabs.TabPane>
      </Tabs>
    </div>
  );
};
