/* eslint-disable react-hooks/exhaustive-deps */
/* eslint-disable no-restricted-globals */
import Axios from 'axios';
import Cookies from 'js-cookie';
import moment from 'moment';
import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useState,
} from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import { HashRouter, BrowserRouter, Redirect, Route, useLocation } from 'react-router-dom';
import SubTabComponent from '../components/SubTab';
import AppLayout from '../components/layouts';
import * as SERVICE from '../constants/service.types';
import * as SYSTEM from '../constants/system.keys';
import { useInActiveLogout } from '../hooks/useInActiveLogout';
import HoasenLogo from '../assets/favicon/hoasen_logo.png';
import {
  authLogoutThunk,
  changeLocales,
  getPublicIpReturn,
  socketEmitEvent,
  updateNamespace,
} from '../redux/actions';
import { resetDataToken } from '../redux/socket';
import AppRoutes from '../routes';
import Login from './auth/Login';
import storageService from '../services/storage.service';
import CryptoJS from 'crypto-js';
import FingerprintJS from '@fingerprintjs/fingerprintjs';
import Spinner from '../components/Spinner';
import { isElectron, isTauri } from '@/configs';
import { isTauriLiveWindow } from '../helpers/tauri';
import { sanitizeRedirectPath, POST_LOGIN_REDIRECT } from '../helpers/redirect';
import { beeXLogger } from '@/helpers/logger';

const OPEN_PAGES = 'OPEN_PAGES';
const PAGE_AVAILABLE = 'PAGE_AVAILABLE';
const HOST_NAME = window.location.hostname;
const TITLE_APP = {
  'cloudcam1.hoasengroup.vn': 'Hoa Sen Group',
  'cloudcam.dashhome.vn': 'DashHome',
};
const ICON_APP = {
  'cloudcam1.hoasengroup.vn': HoasenLogo,
};

const CustomRouter = ({ children }) => {
  if (isElectron || isTauri) return <HashRouter>{children}</HashRouter>;
  return <BrowserRouter>{children}</BrowserRouter>;
};

function AppRouterContent({
  allowMultiTab,
  current,
  isAuth,
  isLogin,
  mainTabKey,
  onMainTabChange,
  socketState,
}) {
  const location = useLocation();
  const namespace = useSelector((state) => state.namespace);
  const namespaces = useSelector((state) => state.namespaces);

  const canRenderMainContent =
    isTauri || current === mainTabKey || allowMultiTab;
  const dispatch = useDispatch();

  // Extract token and namespace from URL immediately on render (synchronously) to prevent initial redirect to /login
  const { urlToken, urlNamespace } = useMemo(() => {
    const urlParams = new URLSearchParams(window.location.hash.split('?')[1] || window.location.search);
    return {
      urlToken: urlParams.get('accessToken'),
      urlNamespace: urlParams.get('namespace'),
    };
  }, []);

  // Update namespace in Redux immediately if passed via URL
  useEffect(() => {
    if (urlNamespace && namespace !== urlNamespace) {
      dispatch(updateNamespace(urlNamespace));
    }
  }, [urlNamespace, namespace, dispatch]);

  if (urlToken && !storageService.getInternalStorageByKey(SYSTEM.DECODED_ACCESS_TOKEN)) {
    storageService.setInternalStorageByKey(SYSTEM.DECODED_ACCESS_TOKEN, urlToken);
  }

  const hasStoredToken = !!urlToken || !!storageService.getInternalStorageByKey(
    SYSTEM.DECODED_ACCESS_TOKEN,
  );

  if (!canRenderMainContent) {
    return <SubTabComponent onMainTabChange={onMainTabChange} />;
  }

  if (!isLogin) {
    beeXLogger.debug("isLoging: ", isLogin)
    // Desktop (Pake/Tauri) only: keep deep-link URL while re-authenticating.
    if (
      isTauri &&
      hasStoredToken &&
      isAuth !== -1 &&
      location.pathname !== '/login'
    ) {
      beeXLogger.debug("LOG: ", {
        isTauri,
        hasStoredToken,
        isAuth,
        locationPathName: location.pathname,
        namespace,
        namespaces: namespaces ? namespaces.length : null,
        socketState
      })
      // if (isTauriLiveWindow()) {
      //   return (
      //     <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100vh', background: '#F2F5FA' }}>
      //       <Spinner />
      //       <div style={{ marginTop: 20, color: '#1890ff', fontFamily: 'sans-serif', fontSize: '14px', textAlign: 'center' }}>
      //         <div>Đang tải cửa sổ trực tiếp...</div>
      //         <div style={{ marginTop: 8, fontSize: '12px', color: '#8c8c8c' }}>
      //           Socket: {socketState === 1 ? 'Đã kết nối' : 'Đang kết nối...'} | Auth: {isAuth === 1 ? 'Đã xác thực' : 'Đang xác thực...'}
      //         </div>
      //         <div style={{ fontSize: '12px', color: '#8c8c8c', marginTop: 4 }}>
      //           Namespace: {namespace || 'Đang tải...'} | Danh sách: {namespaces ? namespaces.length : 'Đang tải...'}
      //         </div>
      //         <div style={{ fontSize: '11px', color: '#bfbfbf', marginTop: 4 }}>
      //           Token: {urlToken ? 'Có (URL)' : 'Không tìm thấy'}
      //         </div>
      //       </div>
      //     </div>
      //   );
      // }
      return <Spinner />;
    }

    const redirectFrom = `${location.pathname}${location.search}${location.hash}`;

    if (isTauri) {
      const safeRedirectFrom = sanitizeRedirectPath(redirectFrom);
      if (safeRedirectFrom && safeRedirectFrom !== '/login') {
        sessionStorage.setItem(POST_LOGIN_REDIRECT, safeRedirectFrom);
      }
    }

    return (
      <>
        <Route exact path="/login">
          <Login />
        </Route>
        <Redirect
          to={{
            pathname: '/login',
            state: {
              from: redirectFrom,
              query: location.search,
            },
          }}
        />
      </>
    );
  }

  return <AppLayout>{AppRoutes}</AppLayout>;
}

export default function App() {
  const { i18n } = useTranslation();
  const dispatch = useDispatch();
  const {
    isAuth,
    socketState,
    language,
    namespace,
    namespaces,
    dataUser,
    theme,
  } = useSelector((state) => state);
  const [isLogin, setIsLogin] = useState(false);
  const [isBlockDevTool, setIsBlockDevTool] = useState(false);
  const [isOpenPage, setIsOpenPage] = useState(false);
  const [current] = useState(Date.now());
  const [mainTabKey, setMainTabKey] = useState(Date.now());
  const authSessionLogout = localStorage.getItem(SYSTEM.AUTO_LOGOUT_SESSION);
  const allowMultiTab = +localStorage.getItem(SYSTEM.ALLOW_MULTI_TABS);
  const [isInitialSetup, setIsInitialSetup] = useState(false); //Decode auth_token and set to storageService

  const initialSetup = useCallback(async () => {
    localStorage.removeItem('auth_token'); //remove old access token

    // Check if token is passed via URL (e.g. from main window to child window to avoid fingerprint mismatch)
    const urlParams = new URLSearchParams(window.location.hash.split('?')[1] || window.location.search);
    const urlToken = urlParams.get('accessToken');

    if (urlToken) {
      storageService.setInternalStorage({
        fingerPrintKey: 'tauri-child-window',
        decodedAccessToken: urlToken,
      });
      setIsInitialSetup(true);
      return;
    }

    const fp = await FingerprintJS.load();
    const { visitorId } = await fp.get();

    const encryptedToken = localStorage.getItem(SYSTEM.TOKEN) || '';
    try {
      storageService.setInternalStorage({
        fingerPrintKey: visitorId,
        decodedAccessToken: encryptedToken
          ? CryptoJS.AES.decrypt(encryptedToken, visitorId).toString(
            CryptoJS.enc.Utf8,
          )
          : '',
      });

      setIsInitialSetup(true);
    } catch (error) {
      storageService.setInternalStorage({
        fingerPrintKey: visitorId,
      });
      setIsInitialSetup(true);
    }
  }, []);

  useLayoutEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  useLayoutEffect(() => {
    initialSetup();
  }, [initialSetup]);

  useInActiveLogout();
  // Block inspect
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Disable F12 and certain key combinations (F12, Ctrl+Shift+I, etc.)
      if (
        isBlockDevTool &&
        (e.key === 'F12' || (e.ctrlKey && e.shiftKey && e.key === 'I'))
      ) {
        e.preventDefault();
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isBlockDevTool]);
  useEffect(() => {
    const blockDevTool = !!dataUser?.enableWatermark;
    setIsBlockDevTool(blockDevTool);
  }, [dataUser]);
  //Block right click
  useEffect(() => {
    const handleRightClick = (e) => {
      if (isBlockDevTool && process.env.NODE_ENV !== 'development') {
        e.preventDefault();
      }
    };

    window.addEventListener('contextmenu', handleRightClick);

    return () => {
      window.removeEventListener('contextmenu', handleRightClick);
    };
  }, [isBlockDevTool]);
  useEffect(() => {
    if (isTauri) {
      return;
    }

    if (!isOpenPage) {
      setIsOpenPage(true);
      if (typeof window !== 'undefined') {
        setMainTabKey(current);
        localStorage.setItem(OPEN_PAGES, current);
      }
      window.addEventListener('storage', (e) => {
        if (e.key === OPEN_PAGES) {
          setMainTabKey(parseInt(e.newValue));
          localStorage.setItem(PAGE_AVAILABLE, current);
        }
        if (e.key === PAGE_AVAILABLE) {
        }
      });
    }
  }, [current, isOpenPage]);

  const onMainTabChange = useCallback(() => {
    setMainTabKey(current);
    localStorage.setItem(OPEN_PAGES, current);
  }, [current]);

  useEffect(() => {
    const beforeUnloadHandler = (event) => {
      event.preventDefault();
      event.returnValue = '';
      resetDataToken();
      dispatch(authLogoutThunk());
    };

    if (authSessionLogout == 1) {
      window.addEventListener('beforeunload', beforeUnloadHandler);
    }

    return () => {
      window.removeEventListener('beforeunload', beforeUnloadHandler);
    };
  }, [authSessionLogout, dispatch]);

  useEffect(() => {
    async function getPublicIp(cb) {
      try {
        let result = await Axios.get(SYSTEM.CHECK_IP_URL);
        if (result.status === 200) {
          return cb(result.data);
        }
        return cb(null);
      } catch (error) {
        return false;
      }
    }
    getPublicIp((publicIp) => {
      return dispatch(getPublicIpReturn(publicIp));
    });
  }, [dispatch]);

  useEffect(() => {
    let localLanguage = localStorage.getItem(SYSTEM.LANGUAGE);
    if (!localLanguage || localLanguage.length === 0) {
      localLanguage = 'en';
    }
    dispatch(changeLocales(localLanguage));
  }, [dispatch]);

  useEffect(() => {
    if (isInitialSetup) {
      const token = storageService.getInternalStorageByKey(
        SYSTEM.DECODED_ACCESS_TOKEN,
      );
      if (token) {
        if (socketState === 1 && language) {
          let dataBody = {
            language,
            accessToken: token,
            appId: SYSTEM.APP_ID,
            encrypted: 1,
            agent: `${window.navigator.userAgent}_web`,
          };

          let dataObj = {
            appServiceType: SERVICE.AUTHENTICATION,
            requestId: new Date().getTime(),
            body: JSON.stringify(dataBody),
          };
          dispatch(socketEmitEvent(dataObj));
        }
      } else {
        resetDataToken();
        dispatch(authLogoutThunk());
      }
    }
  }, [dispatch, language, socketState, isInitialSetup]);

  useEffect(() => {
    if (isAuth === -1) {
      setIsLogin(false);
    } else if (isAuth === 1 && namespaces && namespaces.length > 0) {
      let data = {
        clientId: localStorage.getItem('onesignal_userId'),
        bundleId: 'camera.beex.vn',
        type: 3,
        namespace: namespaces[0],
      };
      let dataObj = {
        appServiceType: SERVICE.REGISTER_NOTIFICATION,
        requestId: new Date().getTime(),
        body: JSON.stringify(data),
      };
      dispatch(socketEmitEvent(dataObj));

      if (namespaces.length === 1) {
        dispatch(updateNamespace(namespaces[0]));
      } else {
        let namespace = localStorage.getItem(SYSTEM.NAMESPACE);
        if (namespace) {
          dispatch(updateNamespace(namespace));
        }
      }
    }
  }, [dispatch, isAuth, namespaces, namespace]);

  useEffect(() => {
    if (isAuth === 1) {
      let data = {};
      let dataObj = {
        appServiceType: SERVICE.LIST_NAMESPACE_BY_ACCOUNT,
        requestId: new Date().getTime(),
        body: JSON.stringify(data),
      };
      return dispatch(socketEmitEvent(dataObj));
    }
    return () => { };
  }, [dispatch, isAuth]);

  useEffect(() => {
    if (isAuth === 1 && namespace) {
      setIsLogin(true);
    }
  }, [isAuth, namespace]);

  useEffect(() => {
    if (language) {
      moment.locale(language);
      i18n.changeLanguage(language);
      localStorage.setItem(SYSTEM.LANGUAGE, language);
    }
  }, [i18n, language]);
  useEffect(() => {
    document.title = TITLE_APP[HOST_NAME] || 'BeeX';
    const favicon = document.querySelector("link[rel~='icon']");
    if (favicon && ICON_APP[HOST_NAME]) {
      favicon.href = ICON_APP[HOST_NAME];
    }
  }, []);

  return isInitialSetup ? (
    <CustomRouter>
      <AppRouterContent
        allowMultiTab={allowMultiTab}
        current={current}
        isAuth={isAuth}
        isLogin={isLogin}
        mainTabKey={mainTabKey}
        onMainTabChange={onMainTabChange}
        socketState={socketState}
      />
    </CustomRouter>
  ) : (
    <Spinner />
  );
}
