import React, {
  useRef,
  useCallback,
  useEffect,
  useState,
  useMemo,
} from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useTranslation } from 'react-i18next';
import moment from 'moment';

import {
  getAllCompress,
  getForceSwitchPlaybackRate,
  getPlaybackControls,
  getPlaybackMode,
  getPlaybackThumbnails,
  getSelectedDate,
} from '@/redux/playback/reducer';
import {
  addCompress,
  removeCompress,
  setPlaybackControls,
  setSelectedDate,
  syncDownloadStates,
  updateCompress,
} from '@/redux/playback/action';
import { openMessage, socketEmitEvent } from '@/redux/actions';
import { NOTIFIES } from '@/constants/system.keys';
import { LIST_DEVICE_ACTIVE_SERVICE_ID } from '@/constants/service.types';
import {
  deleteTempDownloadPlaybackOnCloud,
  requestDownloadPlaybackOnCloud,
  requestDownloadPlaybackOnDevice,
  startAdvanceBackup,
} from '@/hooks/socket/playback';
import { computeQueryTime } from '../../utils';
import { compressManager } from '../../CompressManager';
import { downloaderInstance } from '../../downloader';
import { EnumPlaybackType } from '../../Settings';
import { beeXLogger } from '@/helpers/logger';
import { PLAYBACK_RATE_OPTIONS } from '../../Main/shared';

import { TimelineHeader } from './TimelineHeader';
import { TimelineTooltip } from './TimelineTooltip';
import { EventTimeline } from './EventTimeline';
import { ProgressBar } from './ProgressBar';
import { EventLegend } from './EventLegend';
import { PlaybackControls } from './PlaybackControls';
import { DownloadModal } from './DownloadModal';

import {
  usePlaybackState,
  usePlaybackRate,
  useZoom,
  useDragSelection,
  useAvailableSegments,
} from './hooks';
import {
  formatTime,
  timeToSeconds,
  genDownloadKeyLocal,
  SECONDS_IN_DAY,
} from './utils';
import { useDownloadPlayback } from './use-download-playback';
import { useProgressBarContext } from './context';

import './index.scss';
import { usePlaybackContext } from '../../context';
import { DatePicker } from 'antd';
import { PLAYBACK_DATE_FORMAT } from '@/constants/time';
import { PlaybackMainSectionMode } from '../../Main';

export const ProgressBarV3 = ({
  currentTime,
  onSeek,
  isPlaybackTimeLoading = false,
  playbackRate,
  setPlaybackRate,
  playbackRateOptions,
  showRateSelector = true,
  maxAvailableTime,
  minAvailableTime,
  availableTimes,
  getPlaybackThumbnail,
  serial,
  name,
  namespace,
  allowPlaybackRateAdvanced,
  isFullScreen,
  handleTogglePTZDewarp,
  ptzDeWarpActive,
  handleFullscreen,
  containerRef,
}) => {
  const { t } = useTranslation();
  const dispatch = useDispatch();
  const progressRef = useRef(null);
  const progressInnerRef = useRef(null);
  const headerInnerRef = useRef(null);
  const tooltipRef = useRef(null);
  const tooltipThumbnailRef = useRef(null);
  const tooltipTimeRef = useRef(null);
  const scrubberRef = useRef(null);
  const hoverScrubberRef = useRef(null);
  const progressThumbRef = useRef(null);
  const isDragging = useRef(false);
  const thumbnailTimerRef = useRef(null);
  const isHoldingRef = useRef(false);
  const prevPlaybackRateRef = useRef(PLAYBACK_RATE_OPTIONS?.[3]?.value);
  const clickTimeoutRef = useRef(null);
  const blobUrlCacheRef = useRef({});
  const cachingDownloadedRef = useRef(new Map());
  const playbackControls = useSelector(getPlaybackControls);
  const playbackThumbnails = useSelector(getPlaybackThumbnails);
  const forceSwitchPlaybackRate = useSelector(getForceSwitchPlaybackRate);
  const { devicesActiveOfServices, totalCamera, camerasDate } = useSelector(
    (state) => state,
  );
  const playbackType = useSelector(getPlaybackMode);
  const allCompresses = useSelector(getAllCompress);

  const [dragTime, setDragTime] = useState(null);
  const [hasThumbnail, setHasThumbnail] = useState(false);
  const [showEventHistory, setShowEventHistory] = useState(true);
  const [allowBackup, setAllowBackup] = useState(false);
  const [downloadModalVisible, setDownloadModalVisible] = useState(false);
  const [downloadRanges, setDownloadRanges] = useState([]);
  const [compressedProgress, setCompressedProgress] = useState(0);
  const [isLoadingConfirm, setIsLoadingConfirm] = useState(false);
  const [processedRanges, setProcessedRanges] = useState(new Set());
  const [deletedList, setDeletedList] = useState([]);
  const [popConfirmKey, setPopConfirmKey] = useState(0);
  const { displayTime, setDisplayTime, isSeekingRef } = usePlaybackState(
    currentTime,
    dragTime,
  );
  const { selectedPlaybackRate, setSelectedPlaybackRate } = usePlaybackRate(
    playbackRate,
    allowPlaybackRateAdvanced,
    forceSwitchPlaybackRate,
    playbackType,
  );
  const {
    selectedEvent,
    setPivotTime,
    aiEvents: events,
    displayMode,
  } = usePlaybackContext();
  const { zoomLevel, zoomRange, setZoomRange } = useZoom();
  const mergedAvailableSegments = useAvailableSegments(availableTimes);
  const selectedDate = useSelector(getSelectedDate);
  const todayBoundaryRef = useRef(moment().startOf('day'));

  const baseStart =
    mergedAvailableSegments && mergedAvailableSegments.length
      ? mergedAvailableSegments[0].from
      : 0;
  const displayTimeForOrigin =
    mergedAvailableSegments && mergedAvailableSegments.length
      ? Math.max(dragTime !== null ? dragTime : displayTime, baseStart)
      : dragTime !== null
        ? dragTime
        : displayTime;
  const originPct = (displayTimeForOrigin / SECONDS_IN_DAY) * 100;
  const scrubberLeftPct = (displayTimeForOrigin / SECONDS_IN_DAY) * 100;

  const handleSeekPlayback = useCallback(
    (timeInSeconds) => {
      setDisplayTime(timeInSeconds);
      onSeek(timeInSeconds);
    },
    [onSeek, setDisplayTime],
  );

  const isTimeAvailable = useCallback(
    (time) => {
      if (!mergedAvailableSegments || !mergedAvailableSegments.length)
        return false;
      return mergedAvailableSegments.some(
        (seg) => time >= seg.from && time <= seg.to,
      );
    },
    [mergedAvailableSegments],
  );

  const {
    dragRangeStart,
    dragRangeEnd,
    hasNewRange,
    setHasNewRange,
    handleProgressMouseDownForRange,
    handleProgressMouseMoveForRange,
    handleProgressMouseUpForRange,
  } = useDragSelection(
    progressRef,
    zoomLevel,
    originPct,
    isTimeAvailable,
    handleSeekPlayback,
    serial,
    name,
    playbackType,
    scrubberRef,
    setPopConfirmKey,
  );

  const { initialSelectedDate } = useProgressBarContext();
  const selectedDateValue = useMemo(() => {
    const parsed = moment(selectedDate, PLAYBACK_DATE_FORMAT, true);
    return parsed.isValid() ? parsed : moment().startOf('day');
  }, [selectedDate]);
  const cameraDateSet = useMemo(
    () => new Set(Array.isArray(camerasDate) ? camerasDate : []),
    [camerasDate],
  );

  const aiEvents = useMemo(() => {
    if (!events.timelineMarks || events.timelineMarks.length === 0) return [];
    return events.timelineMarks.filter(
      (mark) => mark.time >= 0 && mark.time < SECONDS_IN_DAY,
    );
  }, [events]);

  const handleChangePlaybackControls = useCallback(
    (key, value) => {
      dispatch(
        setPlaybackControls({
          ...playbackControls,
          [key]: value,
        }),
      );
    },
    [dispatch, playbackControls],
  );

  const handleBackup = useCallback(() => {
    const dataBody = {
      serial,
      namespace,
      dateRecord: moment(initialSelectedDate).format('YYYY-MM-DD'),
    };
    startAdvanceBackup(dataBody).then((res) => {
      if (res?.result === 1) {
        openMessage(
          NOTIFIES.SUCCESS,
          t(
            `Successfully submitted the backup request for camera ${name} – ${moment(dataBody?.dateRecord).format('DD/MM/YYYY')}`,
          ),
        );
      } else {
        openMessage(NOTIFIES.ERROR, t('Something went wrong'));
      }
    });
  }, [serial, namespace, initialSelectedDate, name, t]);

  const handleConfirmDownload = useCallback(
    (rangesToDownload = downloadRanges) => {
      return new Promise((resolve) => {
        if (rangesToDownload && rangesToDownload?.length > 0) {
          let pendingRequests = 0;
          let hasError = false;
          let downloadsFailed = [];

          rangesToDownload
            .filter((range) => {
              const rangeKey = `${range.fromTime} -${range.toTime} `;
              const downloadKeyLocal = genDownloadKeyLocal(
                range?.serial,
                computeQueryTime(
                  initialSelectedDate,
                  timeToSeconds(range?.fromTime),
                ),
                computeQueryTime(
                  initialSelectedDate,
                  timeToSeconds(range?.toTime),
                ),
              );
              const isCached =
                playbackType === EnumPlaybackType.LOCAL
                  ? cachingDownloadedRef.current?.has(downloadKeyLocal)
                  : false;
              return (
                range?.fromTime &&
                range?.toTime &&
                !processedRanges.has(rangeKey) &&
                range?.playbackType === playbackType &&
                !isCached
              );
            })
            .forEach((item) => {
              const rangeKey = `${item.fromTime} -${item.toTime} `;
              pendingRequests++;
              const requestDownload =
                playbackType === EnumPlaybackType.CLOUD
                  ? requestDownloadPlaybackOnCloud
                  : requestDownloadPlaybackOnDevice;
              const downloadInput = {
                fromTime: computeQueryTime(
                  initialSelectedDate,
                  timeToSeconds(item.fromTime),
                ),
                toTime: computeQueryTime(
                  initialSelectedDate,
                  timeToSeconds(item.toTime),
                ),
                serial,
                namespace,
              };
              let downloadKeyLocal = null;
              if (playbackType === EnumPlaybackType.LOCAL) {
                downloadKeyLocal = genDownloadKeyLocal(
                  serial,
                  downloadInput.fromTime,
                  downloadInput.toTime,
                );
                const downloadState =
                  downloaderInstance.getState(downloadKeyLocal);
                if (
                  !downloadState ||
                  (downloadState && downloadState.status === 'error')
                ) {
                  downloaderInstance.addToWaitList(downloadKeyLocal);
                }
              }
              requestDownload(downloadInput)
                .then((res) => {
                  if (playbackType === EnumPlaybackType.CLOUD) {
                    if (res?.uuid && res?.serial === serial) {
                      setProcessedRanges(
                        (prev) => new Set([...prev, rangeKey]),
                      );
                      const downloadInfo = {
                        ...item,
                        ...res,
                        name,
                        serial,
                        namespace,
                        compressStatus: res?.status || 'processing',
                        compressProgress: res?.progress || 0,
                      };

                      dispatch(addCompress(serial, res?.uuid, downloadInfo));

                      compressManager.startDownload(downloadInfo, {
                        onProgress: (uuid, info) => {
                          dispatch(updateCompress(serial, uuid, info));
                          setCompressedProgress((prev) =>
                            info?.compressProgress > prev
                              ? info?.compressProgress
                              : prev + 0.5,
                          );
                          if (info.status === 'completed' && info.downloadUrl) {
                            const downloadKey = `playback - ${serial}| ${uuid} `;
                            downloaderInstance.download(
                              downloadKey,
                              info.downloadUrl,
                            );
                          }
                        },
                        onComplete: (uuid, resCompress) => {
                          const downloadKey = `playback - ${serial}| ${uuid} `;
                          dispatch(
                            updateCompress(serial, uuid, {
                              compressStatus: 'completed',
                              ...resCompress,
                              downloadKey,
                            }),
                          );
                          beeXLogger.debug('START DOWNLOAD - CREATE BLOB LINK');

                          const downloadState =
                            downloaderInstance.getState(downloadKey);
                          if (
                            downloadState &&
                            downloadState.status !== 'error'
                          ) {
                            downloaderInstance.addToWaitList(downloadKey);
                          }
                          downloaderInstance.download(
                            downloadKey,
                            resCompress?.downloadUrl,
                          );
                        },
                        onError: (uuid, error) => {
                          dispatch(
                            updateCompress(serial, uuid, {
                              compressStatus: 'error',
                              compressError: error,
                            }),
                          );
                        },
                      });
                    }
                  } else {
                    if (res?.deviceSerial === serial && res?.downloadUrl) {
                      if (
                        downloadKeyLocal &&
                        genDownloadKeyLocal(
                          serial,
                          res?.fromTime,
                          res?.toTime,
                        ) === downloadKeyLocal &&
                        !cachingDownloadedRef.current.has(downloadKeyLocal)
                      ) {
                        cachingDownloadedRef.current.set(downloadKeyLocal, {
                          downloadKey: downloadKeyLocal,
                          playbackType,
                          serial,
                        });
                        let url = res?.downloadUrl?.includes('/playbacks')
                          ? res?.downloadUrl
                          : res?.downloadUrl?.replace(
                            serial,
                            `playbacks / ${serial} `,
                          );
                        url = url?.replace(
                          'playback01.beex.vn',
                          'playback01.beex.vn:5199',
                        );
                        setTimeout(() => {
                          beeXLogger.debug(
                            'START DOWNLOAD: ',
                            downloadKeyLocal,
                          );
                          downloaderInstance.download(
                            downloadKeyLocal,
                            url,
                            res?.downloadType,
                            res?.fileSize || 0,
                          );
                        }, 5000);
                      }
                    } else {
                      //
                    }
                  }
                  pendingRequests--;
                  if (pendingRequests === 0) {
                    resolve({ hasError, success: !hasError });
                  }
                })
                .catch((err) => {
                  beeXLogger.debug('REQUEST DOWNLOAD ERR: ', err);
                  downloadsFailed.push(item);
                  hasError = true;
                  openMessage(
                    NOTIFIES.ERROR,
                    'Failed to merge the video at this time.',
                  );
                  setProcessedRanges((prev) => {
                    const newSet = new Set(prev);
                    newSet.delete(rangeKey);
                    return newSet;
                  });
                  pendingRequests--;
                  if (pendingRequests === 0) {
                    resolve({ hasError, success: !hasError });
                  }
                })
                .finally(() => {
                  if (downloadsFailed.length > 0) {
                    setDownloadRanges((prev) =>
                      prev?.filter(
                        (item) =>
                          !downloadsFailed?.some(
                            (df) =>
                              df?.fromTime === item?.fromTime &&
                              df?.toTime === item?.toTime &&
                              df?.serial === item?.serial,
                          ),
                      ),
                    );
                  }
                });
            });

          if (pendingRequests === 0) {
            resolve({ hasError: false, success: true });
          }
        } else {
          resolve({ hasError: false, success: true });
        }
      });
    },
    [
      dispatch,
      initialSelectedDate,
      name,
      namespace,
      playbackType,
      processedRanges,
      serial,
    ],
  );

  const handleRemoveDownloadCloud = useCallback(
    (downloadKey, uuid, resourceCloudId) => {
      compressManager.removeCompress(uuid);
      downloaderInstance.cancel(downloadKey);
      dispatch(removeCompress(serial, uuid));
      setDeletedList((prev) => [...prev, uuid]);
      deleteTempDownloadPlaybackOnCloud({
        uuid: uuid,
        resourceCloudId: resourceCloudId || -1,
        serial,
        namespace,
      });
    },
    [dispatch, serial, namespace],
  );

  const handleRemoveDownloadLocal = useCallback((downloadKey, row) => {
    if (!downloadKey || !downloaderInstance) return;
    downloaderInstance.cancel(downloadKey);
    setDownloadRanges((prev) =>
      prev?.filter(
        (range) =>
          range?.fromTime !== row?.fromTime && range?.toTime !== row?.toTime,
      ),
    );
  }, []);

  const handleScrubberMouseDown = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    isDragging.current = true;
    if (scrubberRef.current) {
      scrubberRef.current.style.cursor = 'grabbing';
    }
  }, []);

  const handleDocumentMouseMove = useCallback(
    (e) => {
      if (!isDragging.current || !progressRef.current) return;

      const rect = progressRef.current.getBoundingClientRect();
      let x = e.clientX - rect.left;

      x = Math.max(0, Math.min(x, rect.width));

      let dragTime;
      if (zoomLevel > 1) {
        const originPixel = (originPct / 100) * rect.width;
        const offsetFromOrigin = x - originPixel;
        const unscaledOffsetFromOrigin = offsetFromOrigin / zoomLevel;
        const unscaledX = originPixel + unscaledOffsetFromOrigin;
        const percentage = unscaledX / rect.width;
        dragTime = Math.floor(percentage * SECONDS_IN_DAY);
      } else {
        const percentage = x / rect.width;
        dragTime = Math.floor(percentage * SECONDS_IN_DAY);
      }

      dragTime = Math.max(0, Math.min(SECONDS_IN_DAY, dragTime));

      const isDraggingBackward = dragTime <= currentTime;

      if (!isDraggingBackward && !isTimeAvailable(dragTime)) return;

      setDragTime(dragTime);

      document.body.style.cursor = 'grabbing';
      progressRef.current.style.cursor = 'grabbing';

      if (tooltipRef.current) {
        tooltipRef.current.style.left = `${Math.min(x, rect.width * 0.9)}px`;
        tooltipRef.current.style.display = 'block';

        if (tooltipTimeRef.current) {
          tooltipTimeRef.current.textContent = formatTime(dragTime);
        }
      }

      if (scrubberRef.current) {
        const percentage = dragTime / SECONDS_IN_DAY;
        scrubberRef.current.style.left = `${percentage * 100}%`;
      }
      if (progressThumbRef.current) {
        const percentage = dragTime / SECONDS_IN_DAY;
        progressThumbRef.current.style.left = `${percentage * 100}%`;
      }
    },
    [isTimeAvailable, currentTime, zoomLevel, originPct],
  );

  const handleDocumentMouseUp = useCallback(() => {
    if (!isDragging.current || !progressRef.current) return;

    isDragging.current = false;

    try {
      document.body.style.cursor = '';
      progressRef.current.style.cursor = '';
    } catch (err) { }

    let seekTime = dragTime;

    if (seekTime === null) {
      const rect = progressRef.current.getBoundingClientRect();
      const caretLeft = scrubberRef.current
        ? scrubberRef.current.offsetLeft
        : 0;
      const percentage = caretLeft / rect.width;
      seekTime = Math.floor(percentage * SECONDS_IN_DAY);
    }

    if (tooltipRef.current) {
      tooltipRef.current.style.display = 'none';
    }

    const isBackward = seekTime <= currentTime;

    if (isBackward || isTimeAvailable(seekTime)) {
      beeXLogger.debug('onSeek1');
      handleSeekPlayback(seekTime);
    }

    setDragTime(null);

    if (scrubberRef.current) {
      scrubberRef.current.style.cursor = 'grab';
    }
  }, [dragTime, handleSeekPlayback, isTimeAvailable, currentTime]);

  const handleMouseMove = useCallback(
    (e) => {
      if (thumbnailTimerRef.current) {
        clearTimeout(thumbnailTimerRef.current);
      }
      if (tooltipThumbnailRef.current) {
        tooltipThumbnailRef.current.src = '';
        tooltipThumbnailRef.current.style.display = 'none';
        setHasThumbnail(false);
      }
      if (isDragging.current) return;

      if (!progressRef.current || !tooltipRef.current) return;

      const rect = progressRef.current.getBoundingClientRect();
      let x = e.clientX - rect.left;
      x = Math.max(0, Math.min(x, rect.width));

      let hoverTime;
      if (zoomLevel > 1) {
        // beeXLogger.debug('handleMouseMove - originPct: ', originPct);
        // beeXLogger.debug('handleMouseMove -  rect.width: ', rect.width);
        const originPixel = (originPct / 100) * rect.width;
        // beeXLogger.debug('handleMouseMove - originPixel: ', originPixel);
        const offsetFromOrigin = x - originPixel;
        // beeXLogger.debug('handleMouseMove - offsetFromOrigin: ', offsetFromOrigin);

        const unscaledOffsetFromOrigin = offsetFromOrigin / zoomLevel;
        // beeXLogger.debug('handleMouseMove - unscaledOffsetFromOrigin: ', unscaledOffsetFromOrigin);
        const unscaledX = originPixel + unscaledOffsetFromOrigin;
        // beeXLogger.debug('handleMouseMove - unscaledX: ', unscaledX);
        // beeXLogger.debug('handleMouseMove======================');

        const percentage = unscaledX / rect.width;
        hoverTime = Math.floor(percentage * SECONDS_IN_DAY);
      } else {
        const percentage = x / rect.width;
        hoverTime = Math.floor(percentage * SECONDS_IN_DAY);
      }

      hoverTime = Math.max(0, Math.min(SECONDS_IN_DAY, hoverTime));

      if (!isTimeAvailable(hoverTime)) {
        progressRef.current.style.cursor = 'not-allowed';
        if (tooltipRef.current) {
          tooltipRef.current.style.display = 'none';
        }
        if (tooltipThumbnailRef.current) {
          tooltipThumbnailRef.current.style.display = 'none';
          setHasThumbnail(false);
        }
        if (tooltipTimeRef.current) {
          tooltipTimeRef.current.style.display = 'none';
        }
        if (hoverScrubberRef.current) {
          hoverScrubberRef.current.style.left = 0;
          hoverScrubberRef.current.style.display = 'none';
        }
      } else {
        progressRef.current.style.cursor = 'pointer';
        tooltipRef.current.style.display = 'block';
        tooltipRef.current.style.left = `${Math.min(x, rect.width * 0.9)}px`;
        if (hoverScrubberRef.current) {
          hoverScrubberRef.current.style.left = `${x}px`;
          hoverScrubberRef.current.style.display = 'block';
        }

        if (tooltipTimeRef.current) {
          let displayText = formatTime(hoverTime);

          if (playbackType === EnumPlaybackType.CLOUD) {
            displayText = `${displayText} - available on cloud`;
          } else if (playbackType === EnumPlaybackType.LOCAL) {
            // beeXLogger.debug(
            //   '🚀 ~ ProgressBarV3 ~ mergedAvailableSegments:',
            //   mergedAvailableSegments?.find(
            //     (seg) => hoverTime >= seg.from && hoverTime <= seg.to,
            //   ),
            // );
            const isInSegment =
              mergedAvailableSegments &&
              mergedAvailableSegments.length > 0 &&
              mergedAvailableSegments?.find(
                (seg) => hoverTime >= seg.from && hoverTime <= seg.to,
              );
            if (isInSegment) {
              displayText = `${displayText} - ${isInSegment?.box ? 'available on box' : 'available on cloud'}`;
            }
          }

          tooltipTimeRef.current.textContent = displayText;
          tooltipTimeRef.current.style.display = 'block';
          tooltipTimeRef.current.style.left = `${x} px`;
        }

        if (tooltipThumbnailRef.current && !tooltipThumbnailRef.current?.src) {
          tooltipThumbnailRef.current.style.display = 'none';
          setHasThumbnail(false);
        }

        let hasCachingThumbnail = false;
        if (playbackThumbnails) {
          const finalQueryTime = computeQueryTime(
            initialSelectedDate,
            formatTime(hoverTime),
          );
          if (playbackThumbnails?.serial === serial) {
            const thumbnails = [...(playbackThumbnails?.thumbnails || [])];
            const exist = thumbnails?.find(
              (th) => th?.queryTime === finalQueryTime,
            );
            if (exist && exist?.imageBase64) {
              hasCachingThumbnail = true;
            }
          }
        }
        thumbnailTimerRef.current = setTimeout(
          async () => {
            try {
              if (getPlaybackThumbnail) {
                const res = await getPlaybackThumbnail(formatTime(hoverTime));
                const src = res?.imageBase64;

                if (tooltipThumbnailRef.current) {
                  if (src) {
                    tooltipThumbnailRef.current.src = src;
                    tooltipThumbnailRef.current.style.display = 'block';
                    setHasThumbnail(true);
                  } else {
                    tooltipThumbnailRef.current.style.display = 'none';
                    setHasThumbnail(false);
                  }
                }
              }
            } catch (err) {
              if (tooltipThumbnailRef.current) {
                tooltipThumbnailRef.current.style.display = 'none';
                setHasThumbnail(false);
              }
            }
          },
          !hasCachingThumbnail ? 250 : 0,
        );
      }
    },
    [
      zoomLevel,
      isTimeAvailable,
      originPct,
      playbackThumbnails,
      playbackType,
      mergedAvailableSegments,
      initialSelectedDate,
      serial,
      getPlaybackThumbnail,
    ],
  );

  const handleMouseLeave = useCallback(() => {
    if (thumbnailTimerRef.current) {
      clearTimeout(thumbnailTimerRef.current);
    }
    if (tooltipRef.current && !isDragging.current) {
      tooltipRef.current.style.display = 'none';
    }

    if (hoverScrubberRef.current) {
      hoverScrubberRef.current.style.left = 0;
      hoverScrubberRef.current.style.display = 'none';
    }
  }, []);

  const isTranscodeMode = playbackControls?.streamMode === 'transcode';

  const handleRewind = useCallback(() => {
    if (isTranscodeMode) {
      return;
    }
    if (!isHoldingRef.current) {
      handleChangePlaybackControls('rewind', 10);
    }
  }, [handleChangePlaybackControls, isTranscodeMode]);

  const handlePlayPause = useCallback(() => {
    if (isTranscodeMode) {
      return;
    }
    handleChangePlaybackControls(
      'state',
      playbackControls?.state === 'pause'
        ? 'play'
        : playbackControls?.state === 'play'
          ? 'pause'
          : playbackControls?.state === 'reload'
            ? 'triggerReload'
            : 'pause',
    );
  }, [handleChangePlaybackControls, isTranscodeMode, playbackControls]);

  const handleForward = useCallback(() => {
    if (isTranscodeMode) {
      return;
    }
    if (!isHoldingRef.current) {
      handleChangePlaybackControls('forward', 10);
    }
  }, [handleChangePlaybackControls, isTranscodeMode]);

  const handleForwardHoldStart = useCallback(() => {
    if (isTranscodeMode) return;
    if (selectedPlaybackRate === 1) return;
    let rate = selectedPlaybackRate;

    if (clickTimeoutRef.current) {
      clearTimeout(clickTimeoutRef.current);
      clickTimeoutRef.current = null;
    }

    clickTimeoutRef.current = setTimeout(() => {
      isHoldingRef.current = true;
      isSeekingRef.current = true;

      setDisplayTime(currentTime);
      handleChangePlaybackControls('direction', 'forward');

      setTimeout(() => setPlaybackRate(rate), 10);

      prevPlaybackRateRef.current = playbackRate;
    }, 150);
  }, [
    selectedPlaybackRate,
    isTranscodeMode,
    currentTime,
    handleChangePlaybackControls,
    playbackRate,
    isSeekingRef,
    setDisplayTime,
    setPlaybackRate,
  ]);

  const handleForwardHoldEnd = useCallback(() => {
    if (isTranscodeMode) return;
    if (clickTimeoutRef.current) {
      clearTimeout(clickTimeoutRef.current);
      clickTimeoutRef.current = null;
    }

    if (!isHoldingRef.current) return;

    setPlaybackRate(PLAYBACK_RATE_OPTIONS?.[3]?.value);
    handleChangePlaybackControls('direction', 'forward');

    setTimeout(() => {
      isHoldingRef.current = false;
      isSeekingRef.current = false;
      setDisplayTime(currentTime);
    }, 50);
  }, [
    currentTime,
    handleChangePlaybackControls,
    isTranscodeMode,
    isSeekingRef,
    setDisplayTime,
    setPlaybackRate,
  ]);

  const onConfirmNewRange = useCallback(async () => {
    if (isLoadingConfirm) return;

    setIsLoadingConfirm(true);

    const currentRange = hasNewRange;
    const newRanges = [...downloadRanges, currentRange];
    setDownloadRanges(newRanges);

    const timeoutId = setTimeout(() => {
      setIsLoadingConfirm(false);
      setHasNewRange(null);
      setPopConfirmKey((prev) => prev + 1);
    }, 10000);

    try {
      const result = await handleConfirmDownload(newRanges);

      clearTimeout(timeoutId);

      setHasNewRange(null);
      setPopConfirmKey((prev) => prev + 1);

      if (result?.success && !result?.hasError) {
        setDownloadModalVisible(true);
      }
    } catch (error) {
      clearTimeout(timeoutId);
      setDownloadRanges((prev) => prev.filter((r) => r !== currentRange));
      setHasNewRange(null);
      setPopConfirmKey((prev) => prev + 1);
    } finally {
      clearTimeout(timeoutId);
      setIsLoadingConfirm(false);
    }
  }, [hasNewRange, downloadRanges, handleConfirmDownload, isLoadingConfirm]);

  const onCancelNewRange = useCallback(() => {
    setHasNewRange(null);
  }, []);

  const handleChangePlaybackControlsRef = useRef(handleChangePlaybackControls);
  useEffect(() => {
    handleChangePlaybackControlsRef.current = handleChangePlaybackControls;
  }, [handleChangePlaybackControls]);

  const downloadTableColumn = useDownloadPlayback({
    playbackType,
    compressedProgress,
    deletedList,
    downloadRanges,
    namespace,
    serial,
    initialSelectedDate,
    downloaderInstance,
    blobUrlCacheRef,
    cachingDownloadedRef,
    setDeletedList,
    setDownloadRanges,
    handleRemoveDownload:
      playbackType === EnumPlaybackType.CLOUD
        ? handleRemoveDownloadCloud
        : handleRemoveDownloadLocal,
    t,
  });

  const downloadDataSource = useMemo(() => {
    if (playbackType === EnumPlaybackType.CLOUD) {
      return allCompresses && allCompresses?.length > 0
        ? allCompresses.filter((item) => item && item?.fromTime && item?.toTime)
        : [];
    } else {
      return downloadRanges || [];
    }
  }, [allCompresses, downloadRanges, playbackType]);

  useEffect(() => {
    document.addEventListener('mousemove', handleDocumentMouseMove);
    document.addEventListener('mouseup', handleDocumentMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleDocumentMouseMove);
      document.removeEventListener('mouseup', handleDocumentMouseUp);
    };
  }, [handleDocumentMouseMove, handleDocumentMouseUp]);

  useEffect(() => {
    const handleMouseMove = (e) => handleProgressMouseMoveForRange(e);
    const handleMouseUp = () => handleProgressMouseUpForRange();

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [handleProgressMouseMoveForRange, handleProgressMouseUpForRange]);

  useEffect(() => {
    if (!downloadModalVisible) {
      cachingDownloadedRef.current = new Map();
    }
  }, [downloadModalVisible]);

  useEffect(() => {
    const activeDownloads = compressManager
      .getActiveCompresses()
      .filter((d) => d.serial === serial);

    if (activeDownloads.length > 0) {
      dispatch(syncDownloadStates(serial, activeDownloads));
    }
  }, [serial, dispatch]);

  useEffect(() => {
    if (devicesActiveOfServices) {
      if (devicesActiveOfServices?.devices?.length > 0) {
        setAllowBackup(
          devicesActiveOfServices?.devices?.some((item) => {
            return item?.serial === serial;
          }),
        );
      }
    }
  }, [devicesActiveOfServices, serial]);

  useEffect(() => {
    const timeRequest = new Date().getTime();
    let data = {
      serviceId: 20,
      timeRequest,
      namespace,
      page: 0,
      size: totalCamera || 100,
    };
    let dataObj = {
      appServiceType: LIST_DEVICE_ACTIVE_SERVICE_ID,
      requestId: timeRequest,
      body: JSON.stringify(data),
    };
    return dispatch(socketEmitEvent(dataObj));
  }, [namespace, totalCamera, serial, dispatch]);

  useEffect(() => {
    setDownloadRanges((prev) => {
      const hasMatchingType = prev?.some(
        (item) => item?.playbackType === playbackType,
      );
      if (!hasMatchingType) return prev;

      const filtered = prev.filter(
        (range) => range?.playbackType === playbackType,
      );
      return filtered.length !== prev.length ? filtered : prev;
    });
  }, [playbackType]);

  useEffect(() => {
    const time = dragTime !== null ? dragTime : displayTime;
    const finalTime =
      mergedAvailableSegments && mergedAvailableSegments.length
        ? Math.max(time, baseStart)
        : time;

    const percentage = (finalTime / SECONDS_IN_DAY) * 100;
    if (scrubberRef.current) {
      scrubberRef.current.style.left = `${percentage}%`;
    }
    if (progressThumbRef.current) {
      progressThumbRef.current.style.left = `${percentage}%`;
    }
  }, [displayTime, dragTime, mergedAvailableSegments, baseStart]);

  useEffect(() => {
    const currentClickTimeout = clickTimeoutRef.current;
    return () => {
      if (currentClickTimeout) {
        clearTimeout(currentClickTimeout);
      }
      if (handleChangePlaybackControlsRef.current) {
        handleChangePlaybackControlsRef.current('state', 'pause');
      }
    };
  }, []);

  useEffect(() => {
    return () => {
      if (thumbnailTimerRef.current) {
        clearTimeout(thumbnailTimerRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (!selectedEvent) return;
    beeXLogger.debug('🚀 ~ ProgressBarV3 ~ selectedEvent:', selectedEvent);

    const eventTimeInSeconds = selectedEvent.timeInSeconds;
    if (eventTimeInSeconds == null || isNaN(eventTimeInSeconds)) return;

    const clampedTime = Math.max(
      0,
      Math.min(SECONDS_IN_DAY, eventTimeInSeconds),
    );

    setPivotTime(clampedTime);
    setDisplayTime(clampedTime);
    const percentage = (clampedTime / SECONDS_IN_DAY) * 100;
    if (scrubberRef.current) {
      scrubberRef.current.style.left = `${percentage}%`;
    }
    if (progressThumbRef.current) {
      progressThumbRef.current.style.left = `${percentage}%`;
    }
  }, [selectedEvent, setDisplayTime, setPivotTime]);

  const onSelectedDateChange = useCallback(
    (date) => {
      if (!date || date === selectedDate) {
        return;
      }
      dispatch(setSelectedDate(date));
    },
    [dispatch, selectedDate],
  );

  const handlePickerChange = useCallback(
    (date) => {
      const nextDate =
        date?.format(PLAYBACK_DATE_FORMAT) ??
        moment().startOf('day').format(PLAYBACK_DATE_FORMAT);
      onSelectedDateChange(nextDate);
    },
    [onSelectedDateChange],
  );

  const disabledFutureDate = useCallback((current) => {
    return current && current.isAfter(todayBoundaryRef.current, 'day');
  }, []);

  const renderDateCell = useCallback(
    (current) => {
      const style = {};
      if (cameraDateSet.has(current.format('MM-DD-YYYY'))) {
        style.color = 'rgba(255, 255, 255, 0.85)';
        style.borderBottom = '1px solid #028fd5';
      }
      return (
        <div className="ant-picker-cell-inner" style={style}>
          {current.date()}
        </div>
      );
    },
    [cameraDateSet],
  );

  return (
    <div
      className={`relative w-full rounded-sm px-0 pt-0 pb-1`}
      style={{
        backgroundColor: isFullScreen ? 'transparent' : 'white',
      }}
    >
      <div className="relative mb-2" style={{ height: 'fit-content' }}>
        <div className="flex justify-between items-center w-full mb-2">
          <DatePicker
            value={selectedDateValue}
            onChange={handlePickerChange}
            className="w-1/5"
            style={{ maxWidth: 200 }}
            disabledDate={disabledFutureDate}
            dateRender={renderDateCell}
          />
          <EventLegend aiEvents={aiEvents} isFullScreen={isFullScreen} />
        </div>
        <TimelineTooltip
          tooltipRef={tooltipRef}
          tooltipThumbnailRef={tooltipThumbnailRef}
          tooltipTimeRef={tooltipTimeRef}
          hasThumbnail={hasThumbnail}
        />

        <EventTimeline
          aiEvents={aiEvents}
          scrubberRef={scrubberRef}
          hoverScrubberRef={hoverScrubberRef}
          handleScrubberMouseDown={handleScrubberMouseDown}
          scrubberLeftPct={scrubberLeftPct}
          onSeek={handleSeekPlayback}
        />
      </div>
      <TimelineHeader
        headerInnerRef={headerInnerRef}
        zoomLevel={zoomLevel}
        originPct={originPct}
        minAvailableTime={minAvailableTime}
        maxAvailableTime={maxAvailableTime}
        isFullScreen={isFullScreen}
      />
      <ProgressBar
        progressRef={progressRef}
        progressInnerRef={progressInnerRef}
        progressThumbRef={progressThumbRef}
        isPlaybackTimeLoading={isPlaybackTimeLoading}
        zoomLevel={zoomLevel}
        originPct={originPct}
        mergedAvailableSegments={mergedAvailableSegments}
        downloadRanges={downloadRanges}
        serial={serial}
        playbackType={playbackType}
        dragRangeStart={dragRangeStart}
        dragRangeEnd={dragRangeEnd}
        hasNewRange={hasNewRange}
        popConfirmKey={popConfirmKey}
        isLoadingConfirm={isLoadingConfirm}
        handleProgressMouseDownForRange={(e) => {
          if (displayMode === PlaybackMainSectionMode.GRID) return;
          handleProgressMouseDownForRange(e);
        }}
        handleMouseMove={handleMouseMove}
        handleMouseLeave={handleMouseLeave}
        handleScrubberMouseDown={handleScrubberMouseDown}
        displayTimeForOrigin={displayTimeForOrigin}
        onConfirmNewRange={onConfirmNewRange}
        onCancelNewRange={onCancelNewRange}
      />

      <PlaybackControls
        currentTime={currentTime}
        displayTime={displayTime}
        playbackControls={playbackControls}
        isTranscodeMode={isTranscodeMode}
        isHoldingRef={isHoldingRef}
        selectedPlaybackRate={selectedPlaybackRate}
        playbackRate={playbackRate}
        isFullScreen={isFullScreen}
        onRewind={handleRewind}
        onPlayPause={handlePlayPause}
        onForward={handleForward}
        onForwardHoldStart={handleForwardHoldStart}
        onForwardHoldEnd={handleForwardHoldEnd}
        zoomRange={zoomRange}
        showRateSelector={showRateSelector}
        playbackRateOptions={playbackRateOptions}
        allowBackup={allowBackup}
        ptzDeWarpActive={ptzDeWarpActive}
        onDownloadClick={() => setDownloadModalVisible(true)}
        onZoomRangeChange={setZoomRange}
        onPlaybackRateChange={setSelectedPlaybackRate}
        onBackup={handleBackup}
        onTogglePTZDeWarp={handleTogglePTZDewarp}
        onFullscreen={handleFullscreen}
        availableTimes={availableTimes}
        onSeekTime={handleSeekPlayback}
      />

      <DownloadModal
        visible={downloadModalVisible}
        downloadDataSource={downloadDataSource}
        downloadTableColumn={downloadTableColumn}
        containerRef={containerRef}
        onOk={() => {
          setDownloadModalVisible(false);
          setCompressedProgress(0);
        }}
        onCancel={() => {
          setDownloadModalVisible(false);
          setCompressedProgress(0);
        }}
      />
    </div>
  );
};
