import { useDispatch, useSelector } from 'react-redux';
import {
  availableTimeError,
  availableTimeLoading,
  availableTimeSuccess,
  setAvailableTimeLocal,
} from './action';
import Store from '../store';
import {
  getAvailableTimeBySerialAndDate,
  getAvailableTimeBySerialAndDateLocal,
} from './reducer';
import {
  getPlaybackTimes,
  getPlaybackTimesLocal,
} from '../../hooks/socket/playback';
import moment from 'moment';
import {
  PLAYBACK_DATE_FORMAT,
  PLAYBACK_DATE_TIME_FORMAT,
} from '../../constants/time';
import { errorState, loadingState, successState } from '../actions';
import { beeXLogger } from '@/helpers/logger';

export const useFetchTimes = () => {
  const dispatch = useDispatch();
  const namespace = useSelector((state) => state.namespace);

  const fetchTimes = (date, serial, repeat = false) => {
    // dont fetch if already fetching
    if (
      getAvailableTimeBySerialAndDate(serial, date)(Store.getState()) &&
      !repeat
    ) {
      return;
    }

    dispatch(availableTimeLoading({ date, serial }));
    beeXLogger.debug('FETCH TIMES CLOUD...', {
      serial,
      namespace: namespace,
      fromTime: date,
      toTime: moment(date).add(1, 'day').format(PLAYBACK_DATE_FORMAT),
    });
    getPlaybackTimes({
      serial,
      namespace: namespace,
      fromTime: date,
      toTime: moment(date).add(1, 'day').format(PLAYBACK_DATE_FORMAT),
    })
      .then((res) => {
        beeXLogger.debug('FETCH TIMES CLOUD - cloud: ', res);
        dispatch(availableTimeSuccess(date, serial, res.storageTimes));
      })
      .catch((error) => {
        beeXLogger.debug('FETCH TIMES CLOUD - error: ', error);
        dispatch(availableTimeError(date, serial));
      });
  };

  return { fetchTimes };
};

export const useFetchTimesLocal = () => {
  const dispatch = useDispatch();
  const namespace = useSelector((state) => state.namespace);

  const fetchTimes = (date, serial, repeat = false) => {
    if (
      getAvailableTimeBySerialAndDateLocal(serial, date)(Store.getState()) &&
      !repeat
    ) {
      return;
    }

    dispatch(setAvailableTimeLocal(serial, date, loadingState()));
    beeXLogger.debug('FETCH TIMES LOCAL...', {
      serial,
      namespace: namespace,
      fromTime: moment(date, PLAYBACK_DATE_FORMAT).format(
        PLAYBACK_DATE_TIME_FORMAT,
      ),
      toTime: moment(date).endOf('day').format(PLAYBACK_DATE_TIME_FORMAT),
    });
    getPlaybackTimesLocal({
      serial,
      namespace: namespace,
      fromTime: moment(date, PLAYBACK_DATE_FORMAT).format(
        PLAYBACK_DATE_TIME_FORMAT,
      ),
      toTime: moment(date).endOf('day').format(PLAYBACK_DATE_TIME_FORMAT),
    })
      .then((res) => {
        beeXLogger.debug('FETCH TIMES LOCAL - res: ', res);
        dispatch(
          setAvailableTimeLocal(
            serial,
            date,
            successState((res.storageTimes || []).sort(sortTime)),
          ),
        );
      })
      .catch((error) => {
        beeXLogger.debug('FETCH TIMES LOCAL - error: ', error);
        dispatch(setAvailableTimeLocal(serial, date, errorState('NOT_FOUND')));
      });
  };

  return { fetchTimes };
};

export const sortTime = (a, b) => {
  return moment(a.from).valueOf() - moment(b.from).valueOf();
};
