import {
  parseResponseBody,
  prepareBody,
  requestSocketPromiseWithTimeout,
} from '@/socket/query';

import * as SERVICE from '@/constants/service.types';
import { beeXLogger } from '@/helpers/logger';

export const checkRTSPStream = async (input) => {
  const response = await requestSocketPromiseWithTimeout(
    {
      body: prepareBody(input),
      appServiceType: SERVICE.CHECK_RTSP_STREAM,
    },
    { timeout: 10000 },
  );

  return parseResponseBody(response);
};

export const startPlaybackCamera = async (input) => {
  const isTranscodeRequest = input?.functions === 'transcode_h264';
  const timeout = isTranscodeRequest ? 20000 : 10000;

  beeXLogger.debug(
    '🚀 ~ startPlaybackCamera ~ prepareBody(input):',
    prepareBody(input),
  );
  const response = await requestSocketPromiseWithTimeout(
    {
      body: prepareBody(input),
      appServiceType: SERVICE.START_PLAYBACK_CAMERA,
    },
    { timeout },
  );
  beeXLogger.debug('response:startPlaybackCamera ', parseResponseBody(response));

  return parseResponseBody(response);
};
