import React, { useMemo, useState } from 'react';
import './styles.scss';
import { GroupTree } from './GroupTree';
import { useListGroupAccountByDeviceGroup } from '../hooks';
import { PermissionTable } from './PermissionTable';
import { EditPermissionModal } from '../EditPermissionModal';
import {
  parseResponseBody,
  prepareBody,
  requestSocketPromiseWithTimeout,
} from '@/socket/query';
import * as SERVICE from '@/constants/service.types';
import { Modal } from 'antd';
import { SharePermission } from '../SharePermission';
import { permissionArrayToString } from '../shared';
import { openMessage } from '@/redux/actions';
import { NOTIFIES } from '@/constants/system.keys';

const sharePermission = async ({
  serials,
  accountId,
  groupId,
  deviceGroupId,
  namespace,
  permission,
  durationSecond,
}) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.SHARE_PERMISSION_USER,
    body: prepareBody({
      serials,
      accountId,
      groupId,
      deviceGroupId,
      namespace,
      permission,
      durationSecond,
    }),
  });

  return parseResponseBody(response);
};

const updateSharePermission = async ({
  serials,
  accountId,
  namespace,
  groupId,
  deviceGroupId,
  permission,
}) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.UPDATE_SHARE_PERMISSION_USER,
    body: prepareBody({
      serials,
      accountId,
      namespace,
      groupId,
      deviceGroupId,
      permission,
    }),
  });

  return parseResponseBody(response);
};

const deleteSharePermission = async ({
  serials,
  groupId,
  namespace,
  accountId,
  deviceGroupId,
}) => {
  const response = await requestSocketPromiseWithTimeout({
    appServiceType: SERVICE.UN_SHARE_PERMISSION_USER,
    body: prepareBody({
      serials,
      groupId,
      namespace,
      accountId,
      deviceGroupId,
    }),
  });

  return parseResponseBody(response);
};

export const GroupCamera = ({ namespace, accounts, isLoadingAccounts }) => {
  const [state, setState] = useState({
    page: 1,
    size: 15,
    timeRequest: new Date().getTime(),
    selectedGroupId: null,
  });
  const [recordToEdit, setRecordToEdit] = useState(null);
  const [loadingRecordToEdit, setLoadingRecordToEdit] = useState(null);

  const [sharePermissionActive, setSharePermissionActive] = useState(false);
  const [sharePermissionLoading, setSharePermissionLoading] = useState(false);

  const {
    data: groupAccountByDeviceGroup,
    isLoading: isLoadingGroupAccountByDeviceGroup,
  } = useListGroupAccountByDeviceGroup({
    deviceGroupId: state.selectedGroupId,
    namespace,
    page: state.page - 1,
    size: state.size,
    timeRequest: state.timeRequest,
  });

  console.log('groupAccountByDeviceGroup', groupAccountByDeviceGroup);

  const onSelectGroupId = (groupId) => {
    setState((prev) => ({
      page: 1,
      size: 15,
      timeRequest: new Date().getTime(),
      selectedGroupId: groupId,
    }));
    setSharePermissionActive(false);
    setSharePermissionLoading(false);
  };

  const onPageChange = (page) => {
    setState((prev) => ({
      ...prev,
      page,
    }));
  };

  const dataSource = useMemo(() => {
    return groupAccountByDeviceGroup?.groups?.map((item) => ({
      ...item,
      key: `${item.accountId || -1}-${item.groupId || -1}`,
    }));
  }, [groupAccountByDeviceGroup]);

  const onEditPermission = (record) => {
    if (record.originDeviceGroupId !== state.selectedGroupId) {
      // Unable to edit because this permission is inherited from parent group
      Modal.confirm({
        title: 'Unable to edit',
        content: 'This permission is inherited from parent group',
        cancelButtonProps: {
          style: {
            display: 'none',
          },
        },
      });

      return;
    }

    setRecordToEdit(record);
  };

  const cancelEditPermission = () => {
    setRecordToEdit(null);
  };

  const onSubmitEditPermission = (permission) => {
    if (!recordToEdit) {
      return;
    }

    if (permission === recordToEdit.permission) {
      cancelEditPermission();
      return;
    }

    console.log('permission', permission);
    const deviceGroupId = state.selectedGroupId;
    setLoadingRecordToEdit(recordToEdit.key);

    const closeIfMatch = () => {
      // reset loading record to edit if it is the same record
      setLoadingRecordToEdit((prev) => {
        if (!prev) {
          return prev;
        }

        if (prev === recordToEdit.key) {
          return null;
        }

        return prev;
      });

      setRecordToEdit((prev) => {
        if (!prev) {
          return prev;
        }

        if (prev.key === recordToEdit.key) {
          return null;
        }

        return prev;
      });
    };

    updateSharePermission({
      serials: '',
      accountId: recordToEdit.accountId || -1,
      namespace,
      groupId: recordToEdit.groupId || -1,
      deviceGroupId,
      permission,
    })
      .then((res) => {
        setState((prev) => {
          if (prev.selectedGroupId !== deviceGroupId) {
            return prev;
          }

          // refetch data
          return {
            ...prev,
            timeRequest: new Date().getTime(),
          };
        });

        closeIfMatch();
      })
      .catch((err) => {
        console.log('err update share permission', err);
        closeIfMatch();
      });
  };

  const onDeletePermission = (record) => {
    console.log('record', record);
    if (record.originDeviceGroupId !== state.selectedGroupId) {
      // Unable to delete because this permission is inherited from parent group
      Modal.confirm({
        title: 'Unable to delete',
        content: 'This permission is inherited from parent group',
        cancelButtonProps: {
          style: {
            display: 'none',
          },
        },
      });

      return;
    }

    Modal.confirm({
      title: 'Delete Permission',
      content: record.groupId
        ? 'Are you sure you want to delete permission for this group?'
        : 'Are you sure you want to delete permission for this account?',
      onOk: async () => {
        await deleteSharePermission({
          serials: '',
          accountId: record.accountId || -1,
          namespace,
          groupId: record.groupId || -1,
          deviceGroupId: state.selectedGroupId,
        });
        setState((prev) => {
          if (prev.selectedGroupId !== state.selectedGroupId) {
            return prev;
          }

          return {
            ...prev,
            timeRequest: new Date().getTime(),
          };
        });
      },
    });
  };

  const onSubmitSharePermission = (values) => {
    const onOk = () => {
      setSharePermissionLoading(true);
      sharePermission({
        accountId: values.accountId || -1,
        groupId: values.groupId || -1,
        deviceGroupId: state.selectedGroupId,
        namespace,
        permission: permissionArrayToString(values.permission),
        durationSecond: values.duration === 0 ? -1 : values.duration * 86400,
        serials: '',
      })
        .then((res) => {
          openMessage(NOTIFIES.SUCCESS, 'Share permission successfully');
          // back to page 1 if selected group id is the same
          setState((prev) => {
            if (prev.selectedGroupId !== state.selectedGroupId) {
              return prev;
            }

            return {
              ...prev,
              page: 1,
              timeRequest: new Date().getTime(),
            };
          });
        })
        .finally(() => {
          setSharePermissionActive(false);
          setSharePermissionLoading(false);
        });
    };

    Modal.confirm({
      title: 'Share permission',
      content: `Are you sure to share permission to this ${
        values.type === 'group' ? 'group' : 'member'
      }?`,
      onOk,
    });
  };

  return (
    <div className="og2-group-camera-component">
      <div className="og2-group-camera-left">
        <GroupTree
          namespace={namespace}
          onSelect={onSelectGroupId}
          selectedId={state.selectedGroupId}
        />
      </div>
      <div className="og2-group-camera-right">
        <PermissionTable
          page={state.page}
          pageSize={state.size}
          onPageChange={onPageChange}
          isLoading={isLoadingGroupAccountByDeviceGroup}
          dataSource={dataSource}
          onEditPermission={onEditPermission}
          onRemovePermission={onDeletePermission}
          total={groupAccountByDeviceGroup?.total || 0}
          footer={() => (
            <SharePermission
              namespace={namespace}
              active={sharePermissionActive}
              onActive={() => setSharePermissionActive(true)}
              onCancel={() => setSharePermissionActive(false)}
              onSubmit={onSubmitSharePermission}
              accounts={accounts}
              disabled={!state.selectedGroupId}
              loadingAccounts={isLoadingAccounts}
              loading={sharePermissionLoading}
            />
          )}
        />
        {recordToEdit && (
          <EditPermissionModal
            defaultPermission={recordToEdit.permission}
            onCancel={cancelEditPermission}
            onSubmit={onSubmitEditPermission}
            name={recordToEdit.groupName || recordToEdit.fullName}
            isLoading={loadingRecordToEdit === recordToEdit.key}
          />
        )}
      </div>
    </div>
  );
};
